version: '3.8'

services:
  sync-server:
    build: .
    container_name: mucheng-sync-server
    ports:
      - "${PORT:-3000}:3000"
    volumes:
      - ./data:/app/data
    environment:
      - NODE_ENV=production
      - PORT=3000
      - DATABASE_PATH=/app/data/sync.db
      - RESOURCES_PATH=/app/data/resources
      - JSON_BODY_LIMIT=${JSON_BODY_LIMIT:-50mb}
      - JWT_SECRET=${JWT_SECRET:?JWT_SECRET is required}
      - JWT_REFRESH_SECRET=${JWT_REFRESH_SECRET:?JWT_REFRESH_SECRET is required}
      - ACCESS_TOKEN_EXPIRES_IN=${ACCESS_TOKEN_EXPIRES_IN:-3600}
      - REFRESH_TOKEN_EXPIRES_IN=${REFRESH_TOKEN_EXPIRES_IN:-604800}
      - API_RATE_LIMIT=${API_RATE_LIMIT:-60}
      - SYNC_RATE_LIMIT=${SYNC_RATE_LIMIT:-1000}
      - LOGIN_RATE_LIMIT=${LOGIN_RATE_LIMIT:-10}
      - REGISTER_RATE_LIMIT=${REGISTER_RATE_LIMIT:-5}
      - MAX_RESOURCE_SIZE=${MAX_RESOURCE_SIZE:-104857600}
      - CHANGE_LOG_RETENTION_DAYS=${CHANGE_LOG_RETENTION_DAYS:-7}
      - CORS_ORIGINS=${CORS_ORIGINS:-*}
      - TRUST_PROXY=${TRUST_PROXY:-false}
      - SECURE_MODE=${SECURE_MODE:-false}
      - LEGACY_API_KEY_AUTH_ENABLED=${LEGACY_API_KEY_AUTH_ENABLED:-false}
      - API_KEYS=${API_KEYS:-}
      - LOG_LEVEL=${LOG_LEVEL:-info}
      # 传输助手配置
      - TRANSFER_RELAY_ENABLED=${TRANSFER_RELAY_ENABLED:-true}
      - TRANSFER_RELAY_KEY=${TRANSFER_RELAY_KEY:?TRANSFER_RELAY_KEY is required}
      - TRANSFER_RELAY_PATH=${TRANSFER_RELAY_PATH:-/transfer}
      - TRANSFER_MAX_CONNECTIONS=${TRANSFER_MAX_CONNECTIONS:-100}
      - TRANSFER_MESSAGE_RATE_LIMIT=${TRANSFER_MESSAGE_RATE_LIMIT:-60}
      - TRANSFER_FILE_RATE_LIMIT=${TRANSFER_FILE_RATE_LIMIT:-10}
      - TRANSFER_SESSION_TIMEOUT=${TRANSFER_SESSION_TIMEOUT:-1800000}
      - TRANSFER_HEARTBEAT_INTERVAL=${TRANSFER_HEARTBEAT_INTERVAL:-30000}
    restart: unless-stopped
    healthcheck:
      test: ["CMD", "wget", "-q", "--spider", "http://localhost:3000/api/health"]
      interval: 30s
      timeout: 10s
      retries: 3
      start_period: 40s
    logging:
      driver: "json-file"
      options:
        max-size: "10m"
        max-file: "3"

volumes:
  sync-data:

