                    <Col span={3}>
                      <Text strong>自定义</Text>
                      <Input
                        value={splitCustom}
                        onChange={e => setSplitCustom(e.target.value)}
                        placeholder="分隔符"
                        style={{ marginTop: 4 }}
                      />
                    </Col>
