              <Input
                placeholder="如: jpg, png, gif, mp4"
                value={customFileType}
                onChange={e => {
                  setCustomFileType(e.target.value);
                  // 清除分类选择，因为用户手动编辑了
                  if (fileTypes.length > 0) {
                    setFileTypes([]);
                  }
