          }
        } catch (err) {
          console.error('Failed to create Excel note:', err);
          message.error('创建 Excel 笔记失败');
        }
        return;
      }

      setCurrentTool(tool);
      if (tool) {
        // 切换到工具时清除笔记选择
        setSelectedNoteId(null);
      }
    },
    [selectedFolderId, refresh]
  );

  // 锁定应用
  const handleLockApp = useCallback((showFeedback: boolean = true) => {
    const securitySettings = localStorage.getItem('mucheng-security');
    if (securitySettings) {
      try {
        const settings = JSON.parse(securitySettings);
        if (settings.appLockEnabled && settings.lockPassword) {
          setIsAppLocked(true);
          setVaultUnlocked(false); // 同时锁定密码库
          if (showFeedback) {
            message.info('应用已锁定');
          }
        } else {
          if (showFeedback) {
            message.warning('请先在设置中启用应用锁定');
          }
        }
      } catch {
        if (showFeedback) {
          message.warning('请先在设置中启用应用锁定');
        }
      }
    } else {
      if (showFeedback) {
        message.warning('请先在设置中启用应用锁定');
      }
    }
  }, []);

  // 解锁应用
  const [failedAttempts, setFailedAttempts] = useState(0);
  const [lockedUntil, setLockedUntil] = useState<number | null>(null);

  // 密码哈希函数
  const hashPassword = async (password: string): Promise<string> => {
    const encoder = new TextEncoder();
    const data = encoder.encode(password + 'mucheng-salt-2024');
    const hashBuffer = await crypto.subtle.digest('SHA-256', data);
    const hashArray = Array.from(new Uint8Array(hashBuffer));
    return hashArray.map(b => b.toString(16).padStart(2, '0')).join('');
  };

  const handleUnlockApp = useCallback(
    async (password: string): Promise<boolean> => {
      const securitySettings = localStorage.getItem('mucheng-security');
      if (securitySettings) {
        try {
          const settings = JSON.parse(securitySettings);
          const hashedInput = await hashPassword(password);
          if (hashedInput === settings.lockPassword) {
            setIsAppLocked(false);
            setFailedAttempts(0);
            return true;
          }
        } catch {
          /* ignore */
        }
      }

      const newAttempts = failedAttempts + 1;
      setFailedAttempts(newAttempts);

      // 5次失败后锁定30秒
      if (newAttempts >= 5) {
        setLockedUntil(Date.now() + 30000);
        setTimeout(() => {
          setLockedUntil(null);
          setFailedAttempts(0);
        }, 30000);
      }

      return false;
    },
    [failedAttempts]
  );

  // 启动时检查是否需要锁定
  useEffect(() => {
    const securitySettings = localStorage.getItem('mucheng-security');
    if (securitySettings) {
      try {
        const settings = JSON.parse(securitySettings);
        if (settings.appLockEnabled && settings.lockPassword) {
          setIsAppLocked(true);
        }
      } catch {
        /* ignore */
      }
    }
  }, []);

  useEffect(() => {
    const api = (window as any).electronAPI;
    if (!api?.onWindowMinimized) {
      return;
    }

    api.onWindowMinimized(() => {
      const securitySettings = localStorage.getItem('mucheng-security');
      if (!securitySettings) {
        return;
      }

      try {
        const settings = JSON.parse(securitySettings);
        if (settings.appLockEnabled && settings.lockPassword && settings.lockOnMinimize) {
          handleLockApp(false);
        }
      } catch {
        /* ignore */
      }
    });
  }, [handleLockApp]);

  // 更新 ref 以保持最新的回调函数
  React.useEffect(() => {
    callbacksRef.current = {
      handleQuickCreateNote,
      handleSync,
      handleDeleteNote,
      handleDuplicateNote,
      handleTogglePin,
      updateSettings,
    };
  }, [
    handleQuickCreateNote,
    handleSync,
    handleDeleteNote,
    handleDuplicateNote,
    handleTogglePin,
    updateSettings,
  ]);

  // 更新 ref 以保持最新的状态
  React.useEffect(() => {
    stateRef.current = {
      currentTool,
      selectedNoteId,
      selectedView,
      currentNote,
      filteredNotes,
    };
  }, [currentTool, selectedNoteId, selectedView, currentNote, filteredNotes]);

  // 监听 Web Clipper 笔记创建事件
  useEffect(() => {
    const api = (window as any).electronAPI;
    if (api?.clipper?.onNoteCreated) {
      api.clipper.onNoteCreated(async (data: { noteId: string }) => {
        message.success('网页已保存到笔记');
        await refresh();
        // 选中新创建的笔记
        if (data.noteId) {
          setSelectedNoteId(data.noteId);
          setCurrentTool(null);
          setSelectedView('all');
        }
      });
    }
  }, [refresh]);

  // 如果应用被锁定，显示锁定界面
  if (isAppLocked) {
    return (
      <LockScreen
        onUnlock={handleUnlockApp}
        failedAttempts={failedAttempts}
        lockedUntil={lockedUntil}
      />
    );
  }

  return (
    <Layout style={{ height: '100vh' }}>
      <Sider
        width={180}
        theme={isDarkMode ? 'dark' : 'light'}
        style={{
          borderRight: `1px solid ${isDarkMode ? '#303030' : '#eee'}`,
          background: isDarkMode ? '#141414' : '#fafafa',
        }}
      >
        <Sidebar
          selectedFolderId={selectedFolderId}
          selectedView={selectedView}
          folders={folders}
          tags={tags}
          aiEnabled={featureSettings.ai_enabled}
          todoEnabled={featureSettings.todo_enabled}
          vaultEnabled={featureSettings.vault_enabled}
          bookmarkEnabled={featureSettings.bookmark_enabled}
          toolboxEnabled={featureSettings.toolbox_enabled}
          diagramEnabled={featureSettings.diagram_enabled}
          transferEnabled={featureSettings.transfer_enabled}
          excelEnabled={featureSettings.excel_enabled}
          currentTool={currentTool}
          onSelectFolder={handleSelectFolder}
          onSelectView={handleSelectView}
          onSelectTag={handleSelectTag}
          onSelectTool={handleSelectTool}
          onCreateNote={handleCreateNote}
          onQuickCreateNote={handleQuickCreateNote}
          onCreateFolder={handleCreateFolder}
          onDeleteFolder={handleDeleteFolder}
          onRenameFolder={handleRenameFolder}
          onDeleteTag={handleDeleteTag}
          onOpenSettings={() => setSettingsOpen(true)}
          onSync={handleSync}
          syncStatus={syncStatus}
        />
      </Sider>
      <Layout>
        {/* 根据当前工具显示不同内容 */}
        {currentTool === 'ai' ? (
          <AIAssistantPanel />
        ) : currentTool === 'todo' ? (
          <Content style={{ background: isDarkMode ? '#141414' : '#fff' }}>
            <TodoPanel />
          </Content>
        ) : currentTool === 'vault' ? (
          (() => {
            const hasVaultPassword = !!localStorage.getItem('mucheng-vault-password');
            if (hasVaultPassword && !vaultUnlocked) {
              return (
                <VaultLockScreen
                  hasPassword={true}
                  onUnlock={() => setVaultUnlocked(true)}
                  onSetPassword={() => setSettingsOpen(true)}
                />
              );
            }
            return <VaultPanel />;
          })()
        ) : currentTool === 'bookmark' ? (
          <BookmarkPanel />
        ) : currentTool === 'toolbox' ? (
          <Content style={{ background: isDarkMode ? '#141414' : '#fff' }}>
            <ToolboxPanel />
          </Content>
        ) : currentTool === 'diagram' ? (
          <Content style={{ background: isDarkMode ? '#141414' : '#fff' }}>
            <DiagramPanel />
          </Content>
        ) : currentTool === 'transfer' ? (
          <Content style={{ background: isDarkMode ? '#141414' : '#fff', padding: 0 }}>
            <TransferPanel visible={currentTool === 'transfer'} />
          </Content>
        ) : (
          <>
            <Sider
              width={260}
              theme={isDarkMode ? 'dark' : 'light'}
              style={{ borderRight: `1px solid ${isDarkMode ? '#303030' : '#eee'}` }}
            >
              <NoteList
                notes={filteredNotes}
                selectedNoteId={selectedNoteId}
                onSelectNote={handleSelectNote}
                onSearch={searchNotes}
                onDeleteNote={
                  selectedView === 'trash' ? handlePermanentDeleteNote : handleDeleteNote
                }
                onRestoreNote={selectedView === 'trash' ? handleRestoreNote : undefined}
                onToggleStar={handleTogglePin}
                onDuplicateNote={handleDuplicateNote}
                onMoveToFolder={handleMoveToFolder}
                onLockNote={handleLockNote}
                onUnlockNote={handleUnlockNote}
                onCreateNote={handleQuickCreateNote}
                onCreateTemplateNote={handleCreateNote}
                isTrashView={selectedView === 'trash'}
              />
            </Sider>
            <Layout>
              <Content style={{ padding: 0, background: isDarkMode ? '#141414' : '#fff' }}>
                {/* 根据笔记类型显示不同编辑器 */}
                {currentNote?.type === 'excel_note' ? (
                  <ExcelEditorPanel noteId={selectedNoteId} />
                ) : (
                  <Editor
                    noteId={selectedNoteId}
                    note={currentNote}
                    onSave={handleSaveNote}
                    onToggleStar={handleTogglePin}
                    onUpdateTags={handleUpdateNoteTags}
                    onDelete={handleDeleteNote}
                    onDuplicate={handleDuplicateNote}
                    onLockNote={handleLockNoteFromEditor}
                    onUnlockNote={handleUnlockNoteFromEditor}
                    onUploadImage={handleUploadImage}
                    onUploadAttachment={handleUploadAttachment}
                    allTags={tags}
                    onCreateTag={createTag}
                    isTrashView={selectedView === 'trash'}
                    defaultMode={isNewNote ? 'edit' : 'preview'}
                  />
                )}
              </Content>
              <Footer
                style={{
                  padding: '4px 16px',
                  background: isDarkMode ? '#1f1f1f' : '#fafafa',
                  borderTop: `1px solid ${isDarkMode ? '#303030' : '#f0f0f0'}`,
                  display: 'flex',
                  justifyContent: 'flex-end',
                  alignItems: 'center',
                }}
              >
                <SyncStatusBar
                  status={syncStatus}
                  lastSyncTime={lastSyncTime}
                  pendingChanges={pendingChanges}
                  progress={syncProgress}
                  lastResult={lastSyncResult}
                  onSync={handleSync}
                  onForceResync={handleForceResync}
                  onOpenSettings={() => setSettingsOpen(true)}
                />
              </Footer>
            </Layout>
          </>
        )}
      </Layout>

      <SettingsModal
        open={settingsOpen}
        onClose={() => setSettingsOpen(false)}
        defaultTab={settingsTab}
      />
      <TemplateSelector
        open={templateSelectorOpen}
        onClose={() => setTemplateSelectorOpen(false)}
        onSelect={handleTemplateSelect}
      />
      <WelcomeGuide open={welcomeOpen} onClose={() => setWelcomeOpen(false)} />

      {/* 移动/复制笔记到文件夹 Modal */}
      <Modal
        title="移动/复制笔记"
        open={moveNoteModalOpen}
        onOk={handleConfirmMoveNote}
        onCancel={() => setMoveNoteModalOpen(false)}
        okText={moveMode === 'move' ? '移动' : '复制'}
        cancelText="取消"
      >
        <Space direction="vertical" style={{ width: '100%' }} size="middle">
          <div>
            <div style={{ marginBottom: 8, fontWeight: 500 }}>操作类型</div>
            <Radio.Group value={moveMode} onChange={e => setMoveMode(e.target.value)}>
              <Radio value="move">移动（原位置删除）</Radio>
              <Radio value="copy">复制（保留原笔记）</Radio>
            </Radio.Group>
          </div>
          <div>
            <div style={{ marginBottom: 8, fontWeight: 500 }}>目标文件夹</div>
            <Select
              style={{ width: '100%' }}
              placeholder="选择目标文件夹"
              value={moveTargetFolderId}
              onChange={setMoveTargetFolderId}
              allowClear
              options={(() => {
                // 构建带层级的文件夹选项
                const buildFolderOptions = (
                  parentId: string | null,
                  level: number
                ): { value: string | null; label: string }[] => {
                  const children = folders.filter(f => f.parentId === parentId);
                  const result: { value: string | null; label: string }[] = [];
                  for (const folder of children) {
                    const indent = '　'.repeat(level); // 使用全角空格缩进
                    const prefix = level > 0 ? '└ ' : '';
                    result.push({
                      value: folder.id,
                      label: `${indent}${prefix}📁 ${folder.name}`,
                    });
                    // 递归添加子文件夹
                    result.push(...buildFolderOptions(folder.id, level + 1));
                  }
                  return result;
                };
                return [
                  { value: null, label: '📁 根目录（无文件夹）' },
                  ...buildFolderOptions(null, 0),
                ];
              })()}
            />
          </div>
        </Space>
      </Modal>
    </Layout>
  );
};

export default App;

/**
 * ImageToolPanel - 图片处理工具面板
 */

import React, { useState, useCallback, useMemo } from 'react';
import {
  Layout,
  Menu,
  Card,
  Button,
  Space,
  Typography,
  message,
  Spin,
  Upload,
  Row,
  Col,
  Slider,
  Select,
  InputNumber,
  Switch,
  Divider,
  Descriptions,
  Radio,
  Tooltip,
} from 'antd';
import {
  SwapOutlined,
  ExpandOutlined,
  ScissorOutlined,
  RotateRightOutlined,
  BgColorsOutlined,
  FilterOutlined,
  PictureOutlined,
  InfoCircleOutlined,
  CompressOutlined,
  UploadOutlined,
  DownloadOutlined,
  ReloadOutlined,
  InboxOutlined,
  UndoOutlined,
  RedoOutlined,
  QuestionCircleOutlined,
} from '@ant-design/icons';
import {
  imageApi,
  fileToBase64,
  base64ToDataUrl,
  formatFileSize,
  calculateCompressionRatio,
  ImageMetadata,
  ProcessOptions,
  ProcessResult,
} from '../services/imageApi';
import useImageHistory, { ImageToolType } from '../hooks/useImageHistory';
import useImageKeyboard, { SHORTCUT_HELP } from '../hooks/useImageKeyboard';
import CropBox from './CropBox';
import ComparisonView, { ComparisonMode } from './ComparisonView';

const { Content, Sider } = Layout;
const { Text, Title } = Typography;
const { Dragger } = Upload;


// 工具定义
interface ImageTool {
  id: ImageToolType;
  name: string;
  icon: React.ReactNode;
}

const imageTools: ImageTool[] = [
  { id: 'format-convert', name: '格式转换', icon: <SwapOutlined /> },
  { id: 'resize', name: '尺寸调整', icon: <ExpandOutlined /> },
  { id: 'crop', name: '图片裁剪', icon: <ScissorOutlined /> },
  { id: 'rotate-flip', name: '旋转翻转', icon: <RotateRightOutlined /> },
  { id: 'color-adjust', name: '颜色处理', icon: <BgColorsOutlined /> },
  { id: 'filters', name: '滤镜效果', icon: <FilterOutlined /> },
  { id: 'watermark', name: '水印叠加', icon: <PictureOutlined /> },
  { id: 'metadata', name: '元数据', icon: <InfoCircleOutlined /> },
  { id: 'compress', name: '优化压缩', icon: <CompressOutlined /> },
];

// ============ 主组件 ============

interface ImageToolPanelProps {
  defaultTool?: ImageToolType;
  hideSidebar?: boolean;
}

const ImageToolPanel: React.FC<ImageToolPanelProps> = ({ defaultTool = 'format-convert', hideSidebar = true }) => {
  const [selectedTool, setSelectedTool] = useState<ImageToolType>(defaultTool);
  const [imageData, setImageData] = useState<string | null>(null);
  const [metadata, setMetadata] = useState<ImageMetadata | null>(null);
  const [processing, setProcessing] = useState(false);
  const [result, setResult] = useState<ProcessResult | null>(null);
  const [previewUrl, setPreviewUrl] = useState<string | null>(null);
  const [originalPreviewUrl, setOriginalPreviewUrl] = useState<string | null>(null);
  const [showComparison, setShowComparison] = useState(false);

  // 当 defaultTool 变化时同步更新 selectedTool
  React.useEffect(() => {
    setSelectedTool(defaultTool);
  }, [defaultTool]);  const history = useImageHistory();

  const handleFileUpload = useCallback(async (file: File) => {
    const MAX_FILE_SIZE = 50 * 1024 * 1024;
    if (file.size > MAX_FILE_SIZE) {
      message.error('文件大小超过 50MB 限制');
      return false;
    }
    try {
      setProcessing(true);
      const base64 = await fileToBase64(file);
      setImageData(base64);
      const meta = await imageApi.getMetadata(base64);
      setMetadata(meta);
      const preview = await imageApi.generatePreview(base64);
      const previewDataUrl = base64ToDataUrl(preview, 'png');
      setPreviewUrl(previewDataUrl);
      setOriginalPreviewUrl(previewDataUrl);
      setResult(null);
      setShowComparison(false);
      history.clear();
      message.success('图片加载成功');
    } catch (error) {
      console.error('Failed to load image:', error);
      message.error('图片加载失败');
    } finally {
      setProcessing(false);
    }
    return false;
  }, [history]);

  const handleProcess = useCallback(async (options: ProcessOptions, useCurrentResult: boolean = false) => {
    // 如果 useCurrentResult 为 true 且有处理结果，则基于当前结果继续处理
    const inputData = useCurrentResult && result?.buffer ? result.buffer : imageData;
    if (!inputData) {
      message.warning('请先上传图片');
      return;
    }
    try {
      setProcessing(true);
      const processResult = await imageApi.process(inputData, options);
      setResult(processResult);
      const newPreviewUrl = base64ToDataUrl(processResult.buffer, processResult.info.format);
      setPreviewUrl(newPreviewUrl);
      history.push({
        toolType: selectedTool,
        options,
        previewUrl: newPreviewUrl,
        result: processResult,
      });
      message.success('处理完成');
    } catch (error) {
      console.error('Failed to process image:', error);
      message.error('处理失败: ' + (error as Error).message);
    } finally {
      setProcessing(false);
    }
  }, [imageData, result, selectedTool, history]);

  const handleSave = useCallback(async () => {
    const buffer = result?.buffer || imageData;
    if (!buffer) {
      message.warning('没有可保存的图片');
      return;
    }
    const format = result?.info.format || metadata?.format || 'png';
    const defaultName = `image_${Date.now()}.${format}`;
    try {
      const saved = await imageApi.saveFile(buffer, defaultName);
      if (saved) {
        message.success('保存成功');
      }
    } catch (error) {
      console.error('Failed to save:', error);
      message.error('保存失败');
    }
  }, [result, imageData, metadata]);

  const handleReset = useCallback(() => {
    if (imageData && metadata) {
      setResult(null);
      imageApi.generatePreview(imageData).then(preview => {
        setPreviewUrl(base64ToDataUrl(preview, 'png'));
      });
    }
  }, [imageData, metadata]);

  const handleUndo = useCallback(() => {
    if (!history.canUndo) {
      message.info('没有可撤销的操作');
      return;
    }
    const prevState = history.undo();
    if (prevState) {
      setPreviewUrl(prevState.previewUrl);
      setResult(prevState.result || null);
      message.info('已撤销');
    }
  }, [history]);

  const handleRedo = useCallback(() => {
    if (!history.canRedo) {
      message.info('没有可重做的操作');
      return;
    }
    const nextState = history.redo();
    if (nextState) {
      setPreviewUrl(nextState.previewUrl);
      setResult(nextState.result || null);
      message.info('已重做');
    }
  }, [history]);

  useImageKeyboard({
    onUndo: handleUndo,
    onRedo: handleRedo,
    onSave: handleSave,
    onReset: handleReset,
  }, !!imageData);

  const shortcutHelpContent = useMemo(() => (
    <div style={{ padding: 8 }}>
      <div style={{ fontWeight: 'bold', marginBottom: 8 }}>快捷键</div>
      {SHORTCUT_HELP.map((item, index) => (
        <div key={index} style={{ marginBottom: 4 }}>
          <Text code>{item.keys}</Text> {item.action}
        </div>
      ))}
    </div>
  ), []);


  const renderToolContent = () => {
    if (!imageData) {
      return (
        <div style={{ padding: 24 }}>
          <Dragger
            accept="image/*"
            showUploadList={false}
            beforeUpload={handleFileUpload}
            style={{ padding: 40 }}
          >
            <p className="ant-upload-drag-icon">
              <InboxOutlined style={{ fontSize: 48, color: '#1890ff' }} />
            </p>
            <p className="ant-upload-text">点击或拖拽图片到此处</p>
            <p className="ant-upload-hint">支持 JPEG、PNG、WebP、AVIF、GIF、TIFF、SVG 格式</p>
          </Dragger>
        </div>
      );
    }

    const toolProps: ToolProps = {
      imageData,
      metadata,
      result,
      previewUrl,
      originalPreviewUrl,
      showComparison,
      onComparisonToggle: setShowComparison,
      processing,
      onProcess: handleProcess,
      onSave: handleSave,
      onReset: handleReset,
    };

    switch (selectedTool) {
      case 'format-convert':
        return <FormatConvertTool {...toolProps} />;
      case 'resize':
        return <ResizeTool {...toolProps} />;
      case 'crop':
        return <CropTool {...toolProps} />;
      case 'rotate-flip':
        return <RotateFlipTool {...toolProps} />;
      case 'color-adjust':
        return <ColorAdjustTool {...toolProps} />;
      case 'filters':
        return <FiltersTool {...toolProps} />;
      case 'watermark':
        return <WatermarkTool {...toolProps} />;
      case 'metadata':
        return <MetadataTool {...toolProps} />;
      case 'compress':
        return <CompressTool {...toolProps} />;
      default:
        return <div>请选择工具</div>;
    }
  };

  const currentTool = imageTools.find(t => t.id === selectedTool);
  const menuItems = imageTools.map(tool => ({
    key: tool.id,
    icon: tool.icon,
    label: tool.name,
  }));

  // 当隐藏侧边栏时，直接渲染工具内容
  if (hideSidebar) {
    return (
      <div style={{ height: '100%' }}>
        <Spin spinning={processing}>
          {imageData && (
            <div style={{ marginBottom: 16, display: 'flex', justifyContent: 'flex-end', alignItems: 'center' }}>
              <Space>
                <Tooltip title="撤销 (Ctrl+Z)">
                  <Button icon={<UndoOutlined />} onClick={handleUndo} disabled={!history.canUndo} />
                </Tooltip>
                <Tooltip title="重做 (Ctrl+Y)">
                  <Button icon={<RedoOutlined />} onClick={handleRedo} disabled={!history.canRedo} />
                </Tooltip>
                <Tooltip title={shortcutHelpContent} placement="bottomRight">
                  <Button icon={<QuestionCircleOutlined />} />
                </Tooltip>
                <Upload accept="image/*" showUploadList={false} beforeUpload={handleFileUpload}>
                  <Button icon={<UploadOutlined />}>更换图片</Button>
                </Upload>
              </Space>
            </div>
          )}
          {renderToolContent()}
        </Spin>
      </div>
    );
  }

  return (
    <Layout style={{ height: '100%' }}>
      <Sider width={180} style={{ background: 'transparent', borderRight: '1px solid var(--border-color, #f0f0f0)' }}>
        <Menu
          mode="inline"
          selectedKeys={[selectedTool]}
          onClick={({ key }) => setSelectedTool(key as ImageToolType)}
          items={menuItems}
          style={{ background: 'transparent', borderRight: 0, height: '100%' }}
        />
      </Sider>
      <Content style={{ padding: 16, overflow: 'auto' }}>
        <Spin spinning={processing}>
          <div style={{ marginBottom: 16, display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
            <Title level={5} style={{ margin: 0 }}>
              {currentTool?.icon} {currentTool?.name}
            </Title>
            {imageData && (
              <Space>
                <Tooltip title="撤销 (Ctrl+Z)">
                  <Button icon={<UndoOutlined />} onClick={handleUndo} disabled={!history.canUndo} />
                </Tooltip>
                <Tooltip title="重做 (Ctrl+Y)">
                  <Button icon={<RedoOutlined />} onClick={handleRedo} disabled={!history.canRedo} />
                </Tooltip>
                <Tooltip title={shortcutHelpContent} placement="bottomRight">
                  <Button icon={<QuestionCircleOutlined />} />
                </Tooltip>
                <Upload accept="image/*" showUploadList={false} beforeUpload={handleFileUpload}>
                  <Button icon={<UploadOutlined />}>更换图片</Button>
                </Upload>
              </Space>
            )}
          </div>
          {renderToolContent()}
        </Spin>
      </Content>
    </Layout>
  );
};


