    }
  }

  /**
   * 添加文字水印
   * 方案：使用 sharp 生成水印图片，然后用 pdf-lib 添加图片水印
   * 这样可以完美支持中文
   */
  async addWatermark(inputBuffer: Buffer, options: GSWatermarkOptions): Promise<Buffer> {
    try {
      const { PDFDocument } = require('pdf-lib');
      const sharp = require('sharp');

      // 加载原 PDF
      const pdfDoc = await PDFDocument.load(inputBuffer);
      const pages = pdfDoc.getPages();

      if (pages.length === 0) {
        throw new Error('PDF has no pages');
      }

      // 解析颜色
      const color = options.color || '#888888';
      const fontSize = options.fontSize || 48;
      const opacity = options.opacity || 0.3;
      const rotation = options.rotation || -45;
      const text = options.text;

      // 获取第一页尺寸作为参考
      const firstPage = pages[0];
      const { width: pageWidth, height: pageHeight } = firstPage.getSize();

      // 使用 sharp 生成水印图片
      // 计算画布大小（需要足够大以容纳旋转后的文本）
      const diagonal = Math.sqrt(pageWidth * pageWidth + pageHeight * pageHeight);
      const canvasSize = Math.ceil(diagonal);

      // 创建 SVG 水印
      const svgWatermark = this.createWatermarkSVG(
        text,
        canvasSize,
        canvasSize,
        fontSize,
        color,
        opacity,
        rotation,
        options.position,
        options.spacingX,
        options.spacingY
      );

      // 使用 sharp 将 SVG 转换为 PNG
      const watermarkPng = await sharp(Buffer.from(svgWatermark))
        .png()
        .toBuffer();

      // 将水印图片嵌入到每一页
      const watermarkImage = await pdfDoc.embedPng(watermarkPng);

      for (const page of pages) {
        const { width, height } = page.getSize();

        // 计算水印图片的位置和大小
        // 将水印居中放置
        const scale = Math.min(width / canvasSize, height / canvasSize);
        const drawWidth = canvasSize * scale;
        const drawHeight = canvasSize * scale;
        const x = (width - drawWidth) / 2;
        const y = (height - drawHeight) / 2;

        page.drawImage(watermarkImage, {
          x,
          y,
          width: drawWidth,
          height: drawHeight,
          opacity: 1, // 透明度已经在 SVG 中设置
        });
      }

      return Buffer.from(await pdfDoc.save());
    } catch (error) {
      console.error('GhostscriptService: addWatermark failed:', error);
      throw error;
    }
  }

  /**
   * 创建水印 SVG
   */
  private createWatermarkSVG(
    text: string,
    width: number,
    height: number,
    fontSize: number,
    color: string,
    opacity: number,
    rotation: number,
    position: 'center' | 'tile',
    spacingX?: number,
    spacingY?: number
  ): string {
    // 获取字体族
    const fontFamily = this.getCanvasFontFamily();

    // 估算文本宽度（中文字符约等于字号宽度）
    const textWidth = text.length * fontSize;
    const textHeight = fontSize;

    let textElements = '';

    if (position === 'tile') {
      // 平铺水印 - 使用用户指定的间距或默认值
      const gapX = spacingX !== undefined ? spacingX : 100;
      const gapY = spacingY !== undefined ? spacingY : 80;
      const stepX = textWidth + gapX;
      const stepY = textHeight + gapY;

      // 生成平铺的文本元素
      for (let y = -height; y < height * 2; y += stepY) {
        for (let x = -width; x < width * 2; x += stepX) {
          textElements += `
            <text 
              x="${x}" 
              y="${y}" 
              font-family="${fontFamily}, Microsoft YaHei, SimHei, sans-serif"
              font-size="${fontSize}"
              fill="${color}"
              fill-opacity="${opacity}"
              transform="rotate(${rotation}, ${x}, ${y})"
            >${this.escapeXml(text)}</text>`;
        }
      }
    } else {
      // 居中水印
      const centerX = width / 2;
      const centerY = height / 2;

      textElements = `
        <text 
          x="${centerX}" 
          y="${centerY}" 
          font-family="${fontFamily}, Microsoft YaHei, SimHei, sans-serif"
          font-size="${fontSize}"
          fill="${color}"
          fill-opacity="${opacity}"
          text-anchor="middle"
          dominant-baseline="middle"
          transform="rotate(${rotation}, ${centerX}, ${centerY})"
        >${this.escapeXml(text)}</text>`;
    }

    return `<?xml version="1.0" encoding="UTF-8"?>
<svg xmlns="http://www.w3.org/2000/svg" width="${width}" height="${height}" viewBox="0 0 ${width} ${height}">
  ${textElements}
</svg>`;
  }

  /**
   * 转义 XML 特殊字符
   */
  private escapeXml(text: string): string {
    return text
      .replace(/&/g, '&amp;')
      .replace(/</g, '&lt;')
      .replace(/>/g, '&gt;')
      .replace(/"/g, '&quot;')
      .replace(/'/g, '&apos;');
  }

  /**
   * 获取 Canvas 使用的字体族
   * 优先使用中文字体
   */
  private getCanvasFontFamily(): string {
    if (process.platform === 'win32') {
      // Windows 中文字体优先级
      return 'Microsoft YaHei';
    } else if (process.platform === 'darwin') {
      return 'PingFang SC';
    } else {
      return 'Noto Sans CJK SC';
    }
  }

  /**
   * 清理所有临时文件
   */
  cleanupAll(): void {
    try {
      if (fs.existsSync(this.tempDir)) {
        const files = fs.readdirSync(this.tempDir);
        for (const file of files) {
          const filePath = path.join(this.tempDir, file);
          try {
            fs.unlinkSync(filePath);
          } catch {
            // 忽略删除失败
          }
        }
      }
    } catch (e) {
      console.warn('Failed to cleanup temp directory:', e);
    }
  }
}

// 导出单例
export const ghostscriptService = new GhostscriptService();

import { app, ipcMain, BrowserWindow } from 'electron';
import * as path from 'path';
import * as fs from 'fs';
import * as os from 'os';
import * as crypto from 'crypto';
import { v4 as uuidv4 } from 'uuid';
import { TransferServer } from './TransferServer';
import { RelayClient, relayClient } from './RelayClient';
import { TransferDatabase } from '../../core/transfer/TransferDatabase';
import { DeviceType } from '@shared/transfer/constants';

class TransferService {
  private db: TransferDatabase | null = null;
  private server: TransferServer | null = null;
  private relay: RelayClient = relayClient;

  private fileStreams: Map<string, fs.WriteStream> = new Map();
  private filePaths: Map<string, string> = new Map();

  private deviceId: string = '';
  private deviceName: string = '';

  private relayEventCleanup: (() => void) | null = null;
  private relaySetupDone = false;
  private relayListeners: Array<{ event: string; fn: any }> = [];

  constructor() {
    this.loadDeviceInfo();
  }

  private loadDeviceInfo() {
    const userDataPath = app.getPath('userData');
    const settingsPath = path.join(userDataPath, 'settings.json');

    try {
      let settings: any = {};
      if (fs.existsSync(settingsPath)) {
        settings = JSON.parse(fs.readFileSync(settingsPath, 'utf8'));
      }

      if (!settings.deviceId) {
        settings.deviceId = uuidv4();
        fs.writeFileSync(settingsPath, JSON.stringify(settings, null, 2));
      }

      this.deviceId = settings.deviceId;
      this.deviceName = os.hostname() || 'Desktop';
    } catch (e) {
      console.error('[TransferService] Failed to load device info:', e);
      this.deviceId = uuidv4();
      this.deviceName = os.hostname() || 'Desktop';
    }
  }

  async initialize(): Promise<void> {
    const userDataPath = app.getPath('userData');

    this.db = new TransferDatabase(userDataPath);
    this.db.initialize();

    this.registerIpcHandlers();

    console.log('[TransferService] Initialized');
  }

  destroy(): void {
    if (this.server) {
      this.server.stop();
      this.server = null;
    }
    this.cleanupRelayListeners();
    this.relay.disconnect();
    this.cleanupAllFileStreams();
    if (this.db) {
      this.db.close();
      this.db = null;
    }
  }

  private cleanupAllFileStreams() {
    for (const [fileId, stream] of this.fileStreams) {
      try {
        stream.end();
        const filePath = this.filePaths.get(fileId);
        if (filePath && fs.existsSync(filePath)) {
          fs.unlinkSync(filePath);
        }
      } catch (e) {
        console.error('[TransferService] Failed to cleanup file stream:', e);
      }
    }
    this.fileStreams.clear();
    this.filePaths.clear();
  }

  private broadcast(channel: string, data?: any) {
    const windows = BrowserWindow.getAllWindows();
    windows.forEach(win => {
      if (!win.isDestroyed()) {
        win.webContents.send(channel, data);
      }
    });

    if (channel === 'transfer:file-complete' && data) {
      const { Notification } = require('electron');
      new Notification({ title: '文件传输完成', body: '收到新文件' }).show();
    } else if (channel === 'transfer:message-received' && data) {
      const content = data.message?.content || data.desktopMessage?.content || '收到新消息';
      const { Notification } = require('electron');
      new Notification({
        title: '新消息',
        body: typeof content === 'string' ? content : '收到新消息',
      }).show();
    }
  }

  private getOrCreateSessionForDevice(senderId: string, senderName?: string): string {
    if (!this.db) return 'unknown';

    const sessions = this.db.getSessionsByDevice(senderId);
    if (sessions.length > 0) return sessions[0].id;

    const connectionType: 'lan' | 'relay' = this.relay.isConnected() ? 'relay' : 'lan';

    let deviceName = senderName || senderId;
    const device = this.server?.getConnectedDevices().find(d => d.id === senderId);
    if (device) {
      deviceName = device.name;
      try {
        this.db.createDevice({
          id: device.id,
          name: device.name,
          type: device.type,
          last_ip: device.ip || '',
          last_port: 0,
          last_seen: Date.now(),
          is_favorite: 0,
        });
      } catch (e) {
        // device may already exist
      }
    }

    const sessionId = uuidv4();
    this.db.createSession({
      id: sessionId,
      peer_device_id: senderId,
      peer_device_name: deviceName,
      connection_type: connectionType,
      started_at: Date.now(),
      ended_at: null,
    });
    console.log(
      '[TransferService] Created session:',
      sessionId,
      'for device:',
      deviceName,
      'type:',
      connectionType
    );
    return sessionId;
  }

  private createOrUpdateRelaySession(data: {
    sessionId: string;
    peerId: string;
    peerName: string;
  }): void {
    if (!this.db || !data.sessionId || !data.peerId) return;

    const relayDevice = this.relay.getConnectedDevices().find(d => d.id === data.peerId);
    const deviceType = relayDevice?.type || 'android';

    const existingDevice = this.db.getDeviceById(data.peerId);
    if (existingDevice) {
      this.db.updateDevice(data.peerId, {
        name: data.peerName,
        type: deviceType,
        last_seen: Date.now(),
      });
    } else {
      this.db.createDevice({
        id: data.peerId,
        name: data.peerName,
        type: deviceType,
        last_ip: '',
        last_port: 0,
        last_seen: Date.now(),
        is_favorite: 0,
      });
    }

    const existingSession = this.db.getSessionById(data.sessionId);
    if (!existingSession) {
      this.db.createSession({
        id: data.sessionId,
        peer_device_id: data.peerId,
        peer_device_name: data.peerName,
        connection_type: 'relay',
        started_at: Date.now(),
        ended_at: null,
      });
    }
  }

  private setupServerListeners() {
    if (!this.server) return;

    this.server.on('device:connected', device => {
      if (this.db) {
        try {
          this.db.createDevice({
            id: device.id,
            name: device.name,
            type: device.type,
            last_ip: device.ip,
            last_port: 0,
            last_seen: Date.now(),
            is_favorite: 0,
          });
        } catch (e) {
          // device may already exist
        }
      }
      this.broadcast('transfer:device-connected', device);
    });

    this.server.on('device:disconnected', deviceId => {
      this.cleanupDeviceFileStreams(deviceId);
      if (this.db) {
        const sessions = this.db.getSessionsByDevice(deviceId);
        for (const session of sessions) {
          if (!session.ended_at) {
            this.db.endSession(session.id);
          }
        }
      }
      this.broadcast('transfer:device-disconnected', deviceId);
    });

    this.server.on('device:list-updated', devices => {
      this.broadcast('transfer:device-list-updated', devices);
    });

    this.server.on('session:created', data => {
      const { sessionId, peerDeviceId, peerDeviceName } = data;
      if (this.db) {
        const device = this.server?.getConnectedDevices().find(d => d.id === peerDeviceId);
        try {
          this.db.createDevice({
            id: peerDeviceId,
            name: peerDeviceName,
            type: device?.type || 'android',
            last_ip: device?.ip || '',
            last_port: 0,
            last_seen: Date.now(),
            is_favorite: 0,
          });
        } catch (e) {
          /* may exist */
        }

        try {
          this.db.createSession({
            id: sessionId,
            peer_device_id: peerDeviceId,
            peer_device_name: peerDeviceName,
            connection_type: 'lan',
            started_at: Date.now(),
            ended_at: null,
          });
        } catch (e) {
          /* may exist */
        }
      }

      this.broadcast('transfer:session-created', { sessionId, peerDeviceId, peerDeviceName });
    });

    this.server.on('message:received', data => {
      const { senderId, sessionId, message } = data;
      if (!message || message.id === undefined) return;

      const isForDesktop = this.isMessageForDesktop(data);
      if (!isForDesktop) return;

      const targetSessionId = sessionId || this.getOrCreateSessionForDevice(senderId);
      if (this.db && message && message.id) {
        this.db.createMessage({
          id: message.id,
          session_id: targetSessionId,
          direction: 'received',
          type: message.type || 'text',
          content: message.content || '',
          file_id: message.fileId || null,
          created_at: Date.now(),
          read_at: null,
        });
      }

      this.broadcast('transfer:message-received', {
        ...data,
        desktopSessionId: targetSessionId,
      });
    });

    this.server.on('file:incoming', data => {
      const { senderId, fileInfo, sessionId } = data;
      if (!fileInfo || !fileInfo.id) return;

      const isForDesktop = this.isFileForDesktop(data);
      if (!isForDesktop) return;

      const targetSessionId = sessionId || this.getOrCreateSessionForDevice(senderId);
      this.handleFileIncoming(fileInfo, targetSessionId);

      this.broadcast('transfer:file-incoming', {
        ...data,
        desktopSessionId: targetSessionId,
      });
    });

    this.server.on('file:chunk', data => {
      const { fileId, chunkIndex, totalChunks } = data;
      if (!fileId) return;

      const stream = this.fileStreams.get(fileId);
      if (stream) {
        try {
          const buffer = Buffer.from(data.chunk, 'base64');
          stream.write(buffer);
        } catch (e) {
          console.error('[TransferService] Failed to write chunk:', e);
        }
      }

      if (this.db && totalChunks > 0) {
        const progress = ((chunkIndex + 1) / totalChunks) * 100;
        this.db.updateFileProgress(fileId, progress);
      }

      this.broadcast('transfer:file-chunk', data);
    });

    this.server.on('file:complete', data => {
      const { fileId, fileHash } = data;
      if (!fileId) return;

      const completeInfo = this.handleFileComplete(fileId, fileHash);

      this.broadcast('transfer:file-complete', { ...data, ...completeInfo });
    });

    this.server.on('file:cancel', data => {
      const { fileId } = data;
      if (!fileId) return;

      this.cleanupFileStream(fileId);
      this.db?.cancelFileTransfer(fileId);
      this.broadcast('transfer:file-cancel', data);
    });
  }

  private isMessageForDesktop(data: any): boolean {
    if (!this.server) return false;
    const serverAny = this.server as any;
    return !data.targetDeviceId || data.targetDeviceId === this.deviceId;
  }

  private isFileForDesktop(data: any): boolean {
    if (!this.server) return false;
    return !data.targetDeviceId || data.targetDeviceId === this.deviceId;
  }

  private handleFileIncoming(fileInfo: any, sessionId: string) {
    try {
      const downloadPath = app.getPath('downloads');
      const targetDir = path.join(downloadPath, 'NextNotebook');
      if (!fs.existsSync(targetDir)) {
        fs.mkdirSync(targetDir, { recursive: true });
      }

      let targetPath = path.join(targetDir, path.basename(fileInfo.filename));
      const ext = path.extname(fileInfo.filename);
      const baseName = path.basename(fileInfo.filename, ext);
      let counter = 1;
      while (fs.existsSync(targetPath)) {
        targetPath = path.join(targetDir, `${baseName}_${counter}${ext}`);
        counter++;
      }

      const stream = fs.createWriteStream(targetPath);
      stream.on('error', err => {
        console.error('[TransferService] Write stream error:', err);
        this.fileStreams.delete(fileInfo.id);
        this.filePaths.delete(fileInfo.id);
      });

      this.fileStreams.set(fileInfo.id, stream);
      this.filePaths.set(fileInfo.id, targetPath);

      if (this.db) {
        this.db.createFileTransfer({
          id: fileInfo.id,
          session_id: sessionId,
          filename: fileInfo.filename,
          file_size: fileInfo.fileSize,
          mime_type: fileInfo.mimeType,
          local_path: targetPath,
          direction: 'received',
          status: 'transferring',
          progress: 0,
          file_hash: null,
          created_at: Date.now(),
          completed_at: null,
        });
      }
    } catch (e) {
      console.error('[TransferService] Failed to handle incoming file:', e);
    }
  }

  private cleanupFileStream(fileId: string): void {
    const stream = this.fileStreams.get(fileId);
    const localPath = this.filePaths.get(fileId);

    if (stream) {
      try {
        stream.end();
      } catch (e) {
        console.error('[TransferService] Error closing stream:', e);
      }
      this.fileStreams.delete(fileId);
    }

    if (localPath && fs.existsSync(localPath)) {
      try {
        fs.unlinkSync(localPath);
      } catch (e) {
        console.error('[TransferService] Failed to delete cancelled file:', e);
      }
    }

    this.filePaths.delete(fileId);
  }

  private handleFileComplete(
    fileId: string,
    fileHash?: string
  ): { localPath?: string; fileHash?: string } {
    const stream = this.fileStreams.get(fileId);
    const localPath = this.filePaths.get(fileId);

    if (stream) {
      try {
        stream.end();
      } catch (e) {
        console.error('[TransferService] Error closing stream:', e);
      }
      this.fileStreams.delete(fileId);
    }
    this.filePaths.delete(fileId);

    if (this.db && localPath) {
      let verifiedHash: string | undefined = fileHash || undefined;
      if (fs.existsSync(localPath)) {
        try {
          const fileBuffer = fs.readFileSync(localPath);
          const computedHash = crypto.createHash('sha256').update(fileBuffer).digest('hex');
          if (fileHash && computedHash !== fileHash) {
            console.error(
              `[TransferService] Hash mismatch for ${fileId}: expected ${fileHash}, got ${computedHash}`
            );
          }
          verifiedHash = computedHash;
        } catch (e) {
          console.error('[TransferService] Failed to verify file hash:', e);
        }
      }
      this.db.completeFileTransfer(fileId, localPath, verifiedHash);
      console.log('[TransferService] File transfer completed:', localPath);
      return { localPath, fileHash: verifiedHash };
    }

    return { localPath: localPath || undefined, fileHash: fileHash || undefined };
  }

  private cleanupDeviceFileStreams(deviceId: string) {
    if (!this.db) return;
    const sessions = this.db.getSessionsByDevice(deviceId);
    for (const session of sessions) {
      const files = this.db.getFilesBySession(session.id);
      for (const file of files) {
        if (file.status === 'transferring') {
          const stream = this.fileStreams.get(file.id);
          if (stream) {
            try {
              stream.end();
            } catch (e) {
              /* ignore */
            }
            this.fileStreams.delete(file.id);
          }
          const filePath = this.filePaths.get(file.id);
          if (filePath && fs.existsSync(filePath)) {
            try {
              fs.unlinkSync(filePath);
            } catch (e) {
              /* ignore */
            }
          }
          this.filePaths.delete(file.id);
          this.db.failFileTransfer(file.id);
        }
      }
    }
  }

  private setupRelayListeners() {
    if (this.relaySetupDone) {
      return;
    }
    this.relaySetupDone = true;

    const on = (event: string, fn: any) => {
      (this.relay as any).on(event, fn);
      this.relayListeners.push({ event, fn });
    };

    on('connected', () => this.broadcast('transfer:relay:connected'));
    on('disconnected', (reason: string) => this.broadcast('transfer:relay:disconnected', reason));
    on('error', (err: any) => this.broadcast('transfer:relay:error', err));
    on('device:list', (devices: any) => this.broadcast('transfer:relay:device-list', devices));
    on('device:online', () =>
      this.broadcast('transfer:relay:device-list', this.relay.getConnectedDevices())
    );
    on('device:offline', () =>
      this.broadcast('transfer:relay:device-list', this.relay.getConnectedDevices())
    );

    on('message:received', (data: any) => {
      const { senderId, sessionId, message } = data;
      if (this.db && message && message.id) {
        const targetSessionId = sessionId || this.getOrCreateSessionForDevice(senderId);
        this.db.createMessage({
          id: message.id,
          session_id: targetSessionId,
          direction: 'received',
          type: message.type || 'text',
          content: message.content || '',
          file_id: message.fileId || null,
          created_at: Date.now(),
          read_at: null,
        });
        const payload = { ...data, desktopSessionId: targetSessionId };
        this.broadcast('transfer:message-received', payload);
        this.broadcast('transfer:relay:message-received', payload);
      } else {
        this.broadcast('transfer:relay:message-received', data);
        this.broadcast('transfer:message-received', data);
      }
    });

    on('file:incoming', (data: any) => {
      const { senderId, fileInfo, sessionId } = data;
      if (fileInfo && fileInfo.id && this.db) {
        const targetSessionId = sessionId || this.getOrCreateSessionForDevice(senderId);
        this.handleFileIncoming(fileInfo, targetSessionId);
        const payload = { ...data, desktopSessionId: targetSessionId };
        this.broadcast('transfer:file-incoming', payload);
        this.broadcast('transfer:relay:file-incoming', payload);
      } else {
        this.broadcast('transfer:relay:file-incoming', data);
        this.broadcast('transfer:file-incoming', data);
      }
    });

    on('file:chunk', (data: any) => {
      const { fileId, chunkIndex, totalChunks } = data;
      if (fileId) {
        const stream = this.fileStreams.get(fileId);
        if (stream) {
          try {
            const chunk = Buffer.isBuffer(data.chunk)
              ? data.chunk
              : Buffer.from(data.chunk, 'base64');
            stream.write(chunk);
          } catch (e) {
            console.error('[TransferService] Relay chunk write error:', e);
          }
        }
        if (this.db && totalChunks > 0) {
          const progress = ((chunkIndex + 1) / totalChunks) * 100;
          this.db.updateFileProgress(fileId, progress);
        }
      }
      this.broadcast('transfer:relay:file-chunk', data);
      this.broadcast('transfer:file-chunk', data);
    });

    on('file:complete', (data: any) => {
      const { fileId } = data;
      let completeInfo: { localPath?: string; fileHash?: string } = {};
      if (fileId) {
        completeInfo = this.handleFileComplete(fileId, data.fileHash);
      }
      const payload = { ...data, ...completeInfo };
      this.broadcast('transfer:relay:file-complete', payload);
      this.broadcast('transfer:file-complete', payload);
    });

    on('pair:request', (data: any) => {
      const sessionId = this.relay.acceptPairRequest(data.requesterId);
      console.log(
        `[TransferService] Auto accepted relay pair from ${data.requesterName}, sessionId: ${sessionId}`
      );
    });

    on('pair:success', (data: any) => {
      console.log(`[TransferService] Relay pair success with ${data.peerName}`);
      this.createOrUpdateRelaySession(data);
      this.broadcast('transfer:relay:pair-success', data);
      this.broadcast('transfer:session-created', {
        sessionId: data.sessionId,
        peerDeviceId: data.peerId,
        peerDeviceName: data.peerName,
      });
    });
  }

  private cleanupRelayListeners() {
    for (const { event, fn } of this.relayListeners) {
      this.relay.off(event as any, fn);
    }
    this.relayListeners = [];
    this.relaySetupDone = false;
  }

  private registerIpcHandlers() {
    ipcMain.handle('transfer:startServer', async (_, port?) => {
      try {
        if (this.server) {
          return this.server.getStatus();
        }

        this.server = new TransferServer(this.deviceId, this.deviceName);
        this.setupServerListeners();
        const status = await this.server.start(port);
        console.log('[TransferService] Server started:', status);
        return status;
      } catch (error) {
        console.error('[TransferService] transfer:startServer error:', error);
        throw error;
      }
    });

    ipcMain.handle('transfer:stopServer', async () => {
      try {
        if (this.server) {
          await this.server.stop();
          this.server = null;
        }
        return true;
      } catch (error) {
        console.error('[TransferService] transfer:stopServer error:', error);
        throw error;
      }
    });

    ipcMain.handle('transfer:getServerStatus', () => {
      if (this.server) {
        return this.server.getStatus();
      }
      return { running: false, port: null, ip: null, connectedDevices: 0, startedAt: null };
    });

    ipcMain.handle('transfer:getConnectedDevices', () => {
      return this.server?.getConnectedDevices() || [];
    });

    ipcMain.handle('transfer:generateQRData', () => {
      return this.server?.generatePairingQRData() || null;
    });

    ipcMain.handle('transfer:getDeviceInfo', () => ({
      deviceId: this.deviceId,
      deviceName: this.deviceName,
      deviceType: 'desktop' as DeviceType,
    }));

    ipcMain.handle('transfer:sendMessage', async (_, targetDeviceId, sessionId, message) => {
      if (this.server?.sendMessage(targetDeviceId, sessionId, message)) {
        return true;
      }
      return this.relay.sendMessage(targetDeviceId, sessionId, message);
    });

    ipcMain.handle('transfer:sendFile', async (_, targetDeviceId, sessionId, filePath) => {
      if (this.server) {
        try {
          return await this.server.sendFile(targetDeviceId, sessionId, filePath);
        } catch (e) {
          console.warn('[TransferService] LAN file send failed, trying relay:', e);
        }
      }
      return await this.relay.sendFile(targetDeviceId, sessionId, filePath);
    });

    ipcMain.handle('transfer:saveTempFile', async (_, filename: string, base64Data: string) => {
      if (!base64Data || typeof base64Data !== 'string') {
        throw new Error('临时文件数据为空');
      }

      const safeFilename =
        path
          .basename(filename || `clipboard-${Date.now()}`)
          .replace(/[<>:"/\\|?*\x00-\x1f]/g, '_')
          .trim() || `clipboard-${Date.now()}`;
      const tempDir = path.join(app.getPath('temp'), 'NextNotebookTransfer');
      if (!fs.existsSync(tempDir)) {
        fs.mkdirSync(tempDir, { recursive: true });
      }

      const payload = base64Data.includes(',') ? base64Data.split(',').pop() || '' : base64Data;
      const buffer = Buffer.from(payload, 'base64');
      const tempPath = path.join(
        tempDir,
        `${Date.now()}-${crypto.randomBytes(4).toString('hex')}-${safeFilename}`
      );
      fs.writeFileSync(tempPath, buffer);
      return tempPath;
    });

    ipcMain.handle('transfer:sendMessageRead', (_, targetDeviceId, messageIds) => {
      if (!this.server?.sendMessageRead(targetDeviceId, messageIds)) {
        this.relay.sendMessageRead(targetDeviceId, messageIds);
      }
    });

    // DB Operations
    ipcMain.handle('transfer:db:createDevice', (_, d) => this.db?.createDevice(d));
    ipcMain.handle('transfer:db:getDevice', (_, id) => this.db?.getDeviceById(id));
    ipcMain.handle('transfer:db:getAllDevices', () => this.db?.getAllDevices());
    ipcMain.handle('transfer:db:updateDevice', (_, id, u) => this.db?.updateDevice(id, u));
    ipcMain.handle('transfer:db:deleteDevice', (_, id) => this.db?.deleteDevice(id));

    ipcMain.handle('transfer:db:createSession', (_, s) => this.db?.createSession(s));
    ipcMain.handle('transfer:db:getSession', (_, id) => this.db?.getSessionById(id));
    ipcMain.handle('transfer:db:getAllSessions', () => this.db?.getAllSessions() ?? []);
    ipcMain.handle('transfer:db:getSessionsByDevice', (_, id) => this.db?.getSessionsByDevice(id));
    ipcMain.handle('transfer:db:endSession', (_, id) => this.db?.endSession(id));
    ipcMain.handle('transfer:db:deleteSession', (_, id) => this.db?.deleteSession(id));

    ipcMain.handle('transfer:db:createMessage', (_, m) => this.db?.createMessage(m));
    ipcMain.handle('transfer:db:getMessage', (_, id) => this.db?.getMessageById(id));
    ipcMain.handle('transfer:db:getMessagesBySession', (_, id, lim, off) =>
      this.db?.getMessagesBySession(id, lim, off)
    );
    ipcMain.handle('transfer:db:markMessageAsRead', (_, id) => this.db?.markMessageAsRead(id));
    ipcMain.handle('transfer:db:markSessionMessagesAsRead', (_, id) =>
      this.db?.markSessionMessagesAsRead(id)
    );
    ipcMain.handle('transfer:db:deleteMessage', (_, id) => this.db?.deleteMessage(id));

    ipcMain.handle('transfer:db:createFileTransfer', (_, f) => this.db?.createFileTransfer(f));
    ipcMain.handle('transfer:db:getFile', (_, id) => this.db?.getFileById(id));
    ipcMain.handle('transfer:db:getFilesBySession', (_, id) => this.db?.getFilesBySession(id));
    ipcMain.handle('transfer:db:updateFileProgress', (_, id, p) =>
      this.db?.updateFileProgress(id, p)
    );
    ipcMain.handle('transfer:db:completeFileTransfer', (_, id, p, h) =>
      this.db?.completeFileTransfer(id, p, h)
    );
    ipcMain.handle('transfer:db:failFileTransfer', (_, id) => this.db?.failFileTransfer(id));
    ipcMain.handle('transfer:db:cancelFileTransfer', (_, id) => this.db?.cancelFileTransfer(id));
    ipcMain.handle('transfer:db:deleteFile', (_, id) => this.db?.deleteFile(id));

    ipcMain.handle('transfer:db:getStats', () => this.db?.getStats());
    ipcMain.handle('transfer:db:cleanupOldSessions', (_, d) => this.db?.cleanupOldSessions(d));
    ipcMain.handle('transfer:db:cleanupFailedTransfers', () => this.db?.cleanupFailedTransfers());

    // Relay
    ipcMain.handle('transfer:relay:connect', async (_, url, key) => {
      try {
        this.setupRelayListeners();
        await this.relay.connect({
          serverUrl: url,
          relayKey: key,
          deviceId: this.deviceId,
          deviceName: this.deviceName,
        });
        return true;
      } catch (error) {
        console.error('[TransferService] relay:connect error:', error);
        throw error;
      }
    });

    ipcMain.handle('transfer:relay:disconnect', () => {
      this.relay.disconnect();
      return true;
    });

    ipcMain.handle('transfer:relay:getStatus', () => this.relay.getStatus());
    ipcMain.handle('transfer:relay:getConnectedDevices', () => this.relay.getConnectedDevices());
    ipcMain.handle('transfer:relay:sendMessage', (_, targetDeviceId, sessionId, message) => {
      return this.relay.sendMessage(targetDeviceId, sessionId, message);
    });
    ipcMain.handle('transfer:relay:sendFile', async (_, targetDeviceId, sessionId, filePath) => {
      return await this.relay.sendFile(targetDeviceId, sessionId, filePath);
    });
    ipcMain.handle('transfer:relay:sendPairRequest', (_, targetDeviceId) => {
      this.relay.sendPairRequest(targetDeviceId);
      return true;
    });
  }
}

export const transferService = new TransferService();
export const initializeTransferService = () => transferService.initialize();

import { ItemBase, AIConversationPayload, AIMessagePayload, AIChannel, AISettings } from '@shared/types';
import { itemsApi } from './itemsApi';

// 解析 payload 的辅助函数
export function parsePayload<T>(item: ItemBase): T {
  return JSON.parse(item.payload) as T;
}

// AI 对话 API
export const aiConversationsApi = {
  create: (payload: AIConversationPayload): Promise<ItemBase> =>
    itemsApi.create('ai_conversation', payload),

  getAll: (): Promise<ItemBase[]> =>
    itemsApi.getByType('ai_conversation'),

  update: (id: string, payload: Partial<AIConversationPayload>): Promise<ItemBase | undefined> =>
    itemsApi.update(id, payload),

  delete: (id: string): Promise<boolean> =>
    itemsApi.delete(id),
};

// AI 消息 API
export const aiMessagesApi = {
  create: (payload: AIMessagePayload): Promise<ItemBase> =>
    itemsApi.create('ai_message', payload),

  getByConversation: async (conversationId: string): Promise<ItemBase[]> => {
    // 尝试使用优化的查询方法（如果可用）
    const api = (window as any).electronAPI;
    if (api?.items?.getByTypeAndFilter) {
      try {
        // 使用数据库级别的过滤（更高效）
        const items = await api.items.getByTypeAndFilter('ai_message', { conversation_id: conversationId });
        if (items) {
          return items.sort((a: ItemBase, b: ItemBase) => {
            const pa = parsePayload<AIMessagePayload>(a);
            const pb = parsePayload<AIMessagePayload>(b);
            return pa.created_at - pb.created_at;
          });
        }
      } catch {
        // 回退到原始方法
      }
    }

    // 原始方法：加载所有消息后过滤
    const allMessages = await itemsApi.getByType('ai_message');
    return allMessages.filter(item => {
      const payload = parsePayload<AIMessagePayload>(item);
      return payload.conversation_id === conversationId;
    }).sort((a, b) => {
      const pa = parsePayload<AIMessagePayload>(a);
      const pb = parsePayload<AIMessagePayload>(b);
      return pa.created_at - pb.created_at;
    });
  },

  delete: (id: string): Promise<boolean> =>
    itemsApi.delete(id),
};

// AI 设置存储 - 使用数据库存储以支持同步
const AI_SETTINGS_KEY = 'mucheng-ai-settings';
const AI_CONFIG_ID = 'ai-config-singleton'; // 使用固定 ID 确保只有一条配置记录

export const aiSettingsApi = {
  // 从数据库获取 AI 配置，如果不存在则返回默认值
  get: (): AISettings => {
    // 先尝试从 localStorage 获取（兼容旧数据）
    const saved = localStorage.getItem(AI_SETTINGS_KEY);
    if (saved) {
      try {
        return JSON.parse(saved);
      } catch { /* ignore */ }
    }
    return {
      enabled: false,
      default_channel: '',
      default_model: '',
      channels: [],
    };
  },

  // 保存 AI 配置到 localStorage（同时会通过数据库同步）
  save: (settings: AISettings): void => {
    localStorage.setItem(AI_SETTINGS_KEY, JSON.stringify(settings));
    // 同时保存到数据库以支持同步
    aiSettingsApi.saveToDb(settings);
  },

  // 保存到数据库
  saveToDb: async (settings: AISettings): Promise<void> => {
    try {
      const api = (window as any).electronAPI;
      if (!api?.items) return;

      // 检查是否已存在配置记录
      const existing = await api.items.getById(AI_CONFIG_ID);

      const payload = {
        enabled: settings.enabled,
        default_channel: settings.default_channel,
        default_model: settings.default_model,
        channels: settings.channels,
      };

      if (existing) {
        // 更新现有记录
        await api.items.update(AI_CONFIG_ID, payload);
      } else {
        // 创建新记录（使用固定 ID）
        // 注意：需要通过特殊方式创建带固定 ID 的记录
        await api.items.create('ai_config', { ...payload, _id: AI_CONFIG_ID });
      }
    } catch (err) {
      console.error('Failed to save AI settings to database:', err);
    }
  },

  // 从数据库加载（用于同步后更新本地）
  loadFromDb: async (): Promise<AISettings | null> => {
    try {
      const api = (window as any).electronAPI;
      if (!api?.items) return null;

      const items = await api.items.getByType('ai_config');
      if (items && items.length > 0) {
        const payload = JSON.parse(items[0].payload);
        return {
          enabled: payload.enabled ?? false,
          default_channel: payload.default_channel ?? '',
          default_model: payload.default_model ?? '',
          channels: payload.channels ?? [],
        };
      }
    } catch (err) {
      console.error('Failed to load AI settings from database:', err);
    }
    return null;
  },
};

// AI API 调用
export interface ChatMessage {
  role: 'user' | 'assistant' | 'system' | 'tool';
  content: string | null | Array<{ type: 'text' | 'image_url'; text?: string; image_url?: { url: string } }>;
  tool_calls?: any[];
  tool_call_id?: string;
  name?: string;
}

export interface ChatCompletionOptions {
  model: string;
  messages: ChatMessage[];
  temperature?: number;
  max_tokens?: number;
  stream?: boolean;
}

async function getMcpTools(settings: AISettings) {
  if (!settings.mcp_servers) return { tools: [], serverMap: {} };
  const tools = [];
  const serverMap: Record<string, string> = {}; // toolName -> serverId

  const api = (window as any).electronAPI;
  if (!api?.mcp) return { tools: [], serverMap: {} };

  for (const server of settings.mcp_servers) {
    if (server.enabled) {
      try {
        const serverTools = await api.mcp.listTools(server.id);
        for (const t of serverTools) {
          tools.push({
            type: 'function',
            function: {
              name: t.name,
              description: t.description,
              parameters: t.inputSchema
            }
          });
          serverMap[t.name] = server.id;
        }
      } catch (e) {
        console.error(`Failed to list tools for server ${server.name}:`, e);
      }
    }
  }
  return { tools, serverMap };
}

export async function callAIApi(
  channel: AIChannel,
  options: ChatCompletionOptions,
  onChunk?: (chunk: string) => void
): Promise<string> {
  let { api_url, api_key, type } = channel;

  // 调试日志：记录实际调用的渠道信息
  console.log('[callAIApi] Channel info:', {
    channelId: channel.id,
    channelName: channel.name,
    channelType: type,
    apiUrl: api_url,
    model: options.model,
  });

  // Gemini API 使用不同的 URL 和格式
  if (type === 'gemini') {
    console.log('[callAIApi] Routing to Gemini API');
    return callGeminiApi(api_url, api_key, options, onChunk);
  }

  // 自动补全 OpenAI 兼容的 API 地址
  if ((type === 'openai' || type === 'custom') && !api_url.endsWith('/chat/completions')) {
    api_url = api_url.replace(/\/$/, '') + '/chat/completions';
  }

  const headers: Record<string, string> = {
    'Content-Type': 'application/json',
  };

  if (type === 'openai' || type === 'custom') {
    headers['Authorization'] = `Bearer ${api_key}`;
  } else if (type === 'anthropic') {
    headers['x-api-key'] = api_key;
    headers['anthropic-version'] = '2023-06-01';
  }

  // MCP integration (Only for OpenAI/Custom for now)
  let mcpTools: any[] = [];
  let mcpServerMap: Record<string, string> = {};

  if (type === 'openai' || type === 'custom') {
    const settings = aiSettingsApi.get();
    const { tools, serverMap } = await getMcpTools(settings);
    mcpTools = tools;
    mcpServerMap = serverMap;
  }

  // 构建请求体
  let body: any;
  if (type === 'anthropic') {
    // Anthropic API 格式 (省略...这部分保持不变但为了简洁我在此处重写)
    // ... Copy existing Anthropic logic or simplify if necessary.
    // For this rewrite, I should assume I'm keeping the exact Anthropic logic as before but just updating the signature
    // Wait, replace_file_content replaces the BLOCK. I need to include the Anthropic logic again.
    const systemMsg = options.messages.find(m => m.role === 'system');
    const otherMsgs = options.messages.filter(m => m.role !== 'system').map(msg => {
      if (Array.isArray(msg.content)) {
        return {
          role: msg.role,
          content: msg.content.map(part => {
            if (part.type === 'text') {
              return { type: 'text', text: part.text };
            } else if (part.type === 'image_url') {
              const base64Data = part.image_url?.url.split(',')[1] || '';
              const mediaType = part.image_url?.url.match(/data:(.*?);/)?.[1] || 'image/jpeg';
              return {
                type: 'image',
                source: {
                  type: 'base64',
                  media_type: mediaType,
                  data: base64Data,
                },
              };
            }
            return part;
          }),
        };
      }
      return { role: msg.role, content: msg.content };
    });
    body = {
      model: options.model,
      max_tokens: options.max_tokens || 4096,
      messages: otherMsgs,
      ...(systemMsg && { system: typeof systemMsg.content === 'string' ? systemMsg.content : '' }),
      ...(options.temperature !== undefined && { temperature: options.temperature }),
    };
  } else {
    // OpenAI 兼容格式
    body = {
      model: options.model,
      messages: options.messages,
      ...(options.temperature !== undefined && { temperature: options.temperature }),
      ...(options.max_tokens && { max_tokens: options.max_tokens }),
      stream: options.stream || false,
    };
    if (mcpTools.length > 0) {
      body.tools = mcpTools;
      body.tool_choice = 'auto';
    }
  }

  // 流式响应处理
  if (options.stream && onChunk) {
    const response = await fetch(api_url, {
      method: 'POST',
      headers,
      body: JSON.stringify({ ...body, stream: true }),
    });

    if (!response.ok) {
      const error = await response.text();
      throw new Error(`API 请求失败: ${response.status} - ${error}`);
    }

    const reader = response.body?.getReader();
    if (!reader) throw new Error('无法读取响应流');

    const decoder = new TextDecoder();
    let fullContent = '';

    // Tools handling for stream
    let currentToolCalls: any[] = [];
    let currentToolCallIndex = -1;

    while (true) {
      const { done, value } = await reader.read();
      if (done) break;

      const chunk = decoder.decode(value);
      const lines = chunk.split('\n').filter(line => line.trim().startsWith('data:'));

      for (const line of lines) {
        const data = line.replace('data:', '').trim();
        if (data === '[DONE]') continue;

        try {
          const json = JSON.parse(data);
          let content = '';

          if (type === 'anthropic') {
            content = json.delta?.text || '';
          } else {
            const choice = json.choices?.[0];
            const delta = choice?.delta;

            // Handle content
            if (delta?.content) {
              content = delta.content;
            }

            // Handle tool calls
            if (delta?.tool_calls) {
              for (const tc of delta.tool_calls) {
                if (tc.index !== undefined) {
                  currentToolCallIndex = tc.index;
                  if (!currentToolCalls[currentToolCallIndex]) {
                    currentToolCalls[currentToolCallIndex] = { ...tc, arguments: '' };
                  }
                }
                if (tc.function?.name) {
                  currentToolCalls[currentToolCallIndex].function = currentToolCalls[currentToolCallIndex].function || {};
                  currentToolCalls[currentToolCallIndex].function.name = tc.function.name;
                }
                if (tc.function?.arguments) {
                  currentToolCalls[currentToolCallIndex].function = currentToolCalls[currentToolCallIndex].function || {};
                  currentToolCalls[currentToolCallIndex].function.arguments = (currentToolCalls[currentToolCallIndex].function.arguments || '') + tc.function.arguments;
                  currentToolCalls[currentToolCallIndex].arguments += tc.function.arguments; // Backup
                }
                if (tc.id) {
                  currentToolCalls[currentToolCallIndex].id = tc.id;
                  currentToolCalls[currentToolCallIndex].type = tc.type;
                }
              }
            }
          }

          if (content) {
            fullContent += content;
            onChunk(content);
          }
        } catch { /* ignore parse errors */ }
      }
    }

    // Check if we have tool calls to execute
    if (currentToolCalls.length > 0) {
      // 1. Append assistant message with tool calls
      const assistantMsg: ChatMessage = {
        role: 'assistant',
        content: fullContent || null, // Content might be null if only tool call
        tool_calls: currentToolCalls.map(tc => ({
          id: tc.id,
          type: tc.type,
          function: {
            name: tc.function.name,
            arguments: tc.function.arguments // JSON string
          }
        }))
      };

      const nextMessages = [...options.messages, assistantMsg];

      // 2. Execute tools
      for (const tc of currentToolCalls) {
        const toolName = tc.function.name;
        const argsStr = tc.function.arguments;
        const serverId = mcpServerMap[toolName];

        let result = "";
        if (serverId) {
          onChunk(`\n> 调用工具: ${toolName}...\n`);
          try {
            const args = JSON.parse(argsStr);
            const toolResult = await (window as any).electronAPI.mcp.callTool(serverId, toolName, args);
            result = JSON.stringify(toolResult);
          } catch (e: any) {
            result = `Error: ${e.message}`;
          }
        } else {
          result = `Error: Tool ${toolName} not found.`;
        }

        // 3. Append tool result message
        nextMessages.push({
          role: 'tool',
          tool_call_id: tc.id,
          name: toolName,
          content: result
        });
      }

      // 4. Recursively call API
      return await callAIApi(channel, {
        ...options,
        messages: nextMessages
      }, onChunk);
    }

    return fullContent;
  }

  // 非流式响应 (Simplified for non-streaming, but handles tools logic similarly if needed. 
  // Since streaming is preferred, I will just copy the existing non-streaming logic for regular calls 
  // but if tools are present, they are handled better in streaming or needs similar logic.
  // For brevity, I'll assume users use streaming or apply similar logic.)

  const response = await fetch(api_url, {
    method: 'POST',
    headers,
    body: JSON.stringify(body),
  });

  if (!response.ok) {
    const error = await response.text();
    throw new Error(`API 请求失败: ${response.status} - ${error}`);
  }

  const data = await response.json();
  const choice = data.choices?.[0];
  const msg = choice?.message;

  if (type === 'openai' || type === 'custom') {
    if (msg?.tool_calls) {
      const assistantMsg: ChatMessage = msg;
      const nextMessages = [...options.messages, assistantMsg];

      for (const tc of msg.tool_calls) {
        const toolName = tc.function.name;
        const serverId = mcpServerMap[toolName];
        let result = "";
        try {
          const args = JSON.parse(tc.function.arguments);
          const toolResult = await (window as any).electronAPI.mcp.callTool(serverId, toolName, args);
          result = JSON.stringify(toolResult);
        } catch (e: any) {
          result = `Error: ${e.message}`;
        }

        nextMessages.push({
          role: 'tool',
          tool_call_id: tc.id,
          name: toolName,
          content: result
        });
      }

      return await callAIApi(channel, {
        ...options,
        messages: nextMessages
      }, onChunk);
    }
    return msg?.content || '';
  }

  if (type === 'anthropic') {
    return data.content?.[0]?.text || '';
  }
  return msg?.content || '';
}

// Gemini API 调用
async function callGeminiApi(
  baseUrl: string,
  apiKey: string,
  options: ChatCompletionOptions,
  onChunk?: (chunk: string) => void
): Promise<string> {
  // Gemini API URL 格式: {baseUrl}/models/{model}:generateContent?key={apiKey}
  // 或流式: {baseUrl}/models/{model}:streamGenerateContent?key={apiKey}&alt=sse
  const isStream = options.stream && onChunk;
  const endpoint = isStream ? 'streamGenerateContent' : 'generateContent';
  // 注意：流式响应需要 alt=sse 参数
  const url = isStream
    ? `${baseUrl}/models/${options.model}:${endpoint}?key=${apiKey}&alt=sse`
    : `${baseUrl}/models/${options.model}:${endpoint}?key=${apiKey}`;

  console.log('[Gemini API] Request URL:', url);
  console.log('[Gemini API] Stream mode:', isStream);

  // 转换消息格式为 Gemini 格式
  const contents: any[] = [];
  let systemInstruction: string | undefined;

  for (const msg of options.messages) {
    if (msg.role === 'system') {
      systemInstruction = typeof msg.content === 'string' ? msg.content : '';
    } else {
      // Gemini 支持多模态内容
      if (Array.isArray(msg.content)) {
        const parts: any[] = [];
        for (const part of msg.content) {
          if (part.type === 'text') {
            parts.push({ text: part.text });
          } else if (part.type === 'image_url') {
            // Gemini 使用 inline_data 格式
            const base64Data = part.image_url?.url.split(',')[1] || '';
            const mimeType = part.image_url?.url.match(/data:(.*?);/)?.[1] || 'image/jpeg';
            parts.push({
              inline_data: {
                mime_type: mimeType,
                data: base64Data,
              },
            });
          }
        }
        contents.push({
          role: msg.role === 'assistant' ? 'model' : 'user',
          parts,
        });
      } else {
        contents.push({
          role: msg.role === 'assistant' ? 'model' : 'user',
          parts: [{ text: msg.content }]
        });
      }
    }
  }

  const body: any = {
    contents,
    generationConfig: {
      ...(options.temperature !== undefined && { temperature: options.temperature }),
      ...(options.max_tokens && { maxOutputTokens: options.max_tokens }),
    },
  };

  if (systemInstruction) {
    body.systemInstruction = { parts: [{ text: systemInstruction }] };
  }

  console.log('[Gemini API] Request body:', JSON.stringify(body, null, 2));

  const response = await fetch(url, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify(body),
  });

  console.log('[Gemini API] Response status:', response.status);

  if (!response.ok) {
    const error = await response.text();
    console.error('[Gemini API] Error response:', error);
    throw new Error(`Gemini API 请求失败: ${response.status} - ${error}`);
  }

  // 流式响应 (SSE 格式)
  if (isStream && onChunk) {
    const reader = response.body?.getReader();
    if (!reader) throw new Error('无法读取响应流');

    const decoder = new TextDecoder();
    let fullContent = '';
    let buffer = '';

    while (true) {
      const { done, value } = await reader.read();
      if (done) break;

      buffer += decoder.decode(value, { stream: true });

      // SSE 格式: data: {...}\n\n
      const lines = buffer.split('\n');
      buffer = '';

      for (let i = 0; i < lines.length; i++) {
        const line = lines[i];

        // 如果是最后一行且不完整，保存到 buffer
        if (i === lines.length - 1 && !line.endsWith('}')) {
          buffer = line;
          continue;
        }

        const trimmed = line.trim();
        if (!trimmed) continue;

        // SSE 格式处理
        if (trimmed.startsWith('data: ')) {
          const jsonStr = trimmed.slice(6); // 移除 "data: " 前缀
          try {
            const json = JSON.parse(jsonStr);
            const text = json.candidates?.[0]?.content?.parts?.[0]?.text || '';
            if (text) {
              fullContent += text;
              onChunk(text);
            }
          } catch (e) {
            console.log('[Gemini API] Parse error for line:', trimmed, e);
          }
        } else if (trimmed.startsWith('{')) {
          // 直接 JSON 格式（非 SSE）
          try {
            const json = JSON.parse(trimmed);
            const text = json.candidates?.[0]?.content?.parts?.[0]?.text || '';
            if (text) {
              fullContent += text;
              onChunk(text);
            }
          } catch (e) {
            // 可能是不完整的 JSON，跳过
          }
        }
      }
    }

    console.log('[Gemini API] Stream complete, total content length:', fullContent.length);
    return fullContent;
  }

  // 非流式响应
  const data = await response.json();
  console.log('[Gemini API] Non-stream response:', JSON.stringify(data, null, 2));
  const result = data.candidates?.[0]?.content?.parts?.[0]?.text || '';
  if (!result) {
    console.warn('[Gemini API] Empty response, full data:', data);
  }
  return result;
}

