// 变更日志
async function loadLogs(el) {
  const data = await api('/changes?limit=200');

  // 统计各类型数量
  const typeCounts = {};
  data.changes.forEach(c => {
    typeCounts[c.type] = (typeCounts[c.type] || 0) + 1;
  });

  el.innerHTML = `
    <div class="card">
      <div class="card-header">
        <span>变更日志 (共 ${data.changes.length} 条)</span>
