/**
 * ImageService - 图片处理服务
 * 使用 Sharp 库在主进程中处理图片
 */

import sharp from 'sharp';

// ============ 类型定义 ============

export interface ImageMetadata {
  width: number;
  height: number;
  format: string;
  space: string;
  channels: number;
  depth: string;
