  hasAlpha: boolean;
  size: number;
  exif?: Record<string, any>;
  icc?: {
    name: string;
    description?: string;
  };
}

export interface ProcessOptions {
  // 格式转换
  format?: 'jpeg' | 'png' | 'webp' | 'avif' | 'gif' | 'tiff';
  quality?: number;
  compressionLevel?: number;
  lossless?: boolean;
  progressive?: boolean;
  mozjpeg?: boolean;
  effort?: number;

  // 尺寸调整
