  };
}

// ============ ImageService 类 ============

export class ImageService {
  /**
   * 获取图片元数据
   */
  async getMetadata(input: string): Promise<ImageMetadata> {
    const buffer = this.decodeBase64(input);
    const image = sharp(buffer);
    const metadata = await image.metadata();
    const stats = await image.stats();

    const result: ImageMetadata = {
      width: metadata.width || 0,
      height: metadata.height || 0,
      format: metadata.format || 'unknown',
      space: metadata.space || 'unknown',
      channels: metadata.channels || 0,
      depth: metadata.depth || 'unknown',
      density: metadata.density,
      hasAlpha: metadata.hasAlpha || false,
      size: buffer.length,
    };

    // 提取 EXIF 数据
    if (metadata.exif) {
      try {
        result.exif = this.parseExif(metadata.exif);
      } catch (e) {
        // EXIF 解析失败，忽略
      }
    }

    // 提取 ICC 配置文件
    if (metadata.icc) {
      try {
        result.icc = this.parseIcc(metadata.icc);
      } catch (e) {
        // ICC 解析失败，忽略
      }
    }

    return result;
  }

  /**
   * 处理图片
   */
  async process(input: string, options: ProcessOptions): Promise<ProcessResult> {
    const buffer = this.decodeBase64(input);
    let image = sharp(buffer);

    // 应用处理选项
    image = await this.applyOptions(image, options);

    // 输出格式
    const outputFormat = options.format || 'png';
    image = this.applyFormat(image, outputFormat, options);

    // 元数据处理
    if (options.stripMetadata) {
      image = image.withMetadata({ orientation: undefined });
    } else if (options.withMetadata) {
      image = image.withMetadata();
    }

    // 执行处理
    const { data, info } = await image.toBuffer({ resolveWithObject: true });

    return {
      buffer: data.toString('base64'),
      info: {
        format: info.format,
        width: info.width,
        height: info.height,
        size: data.length,
      },
    };
  }

  /**
   * 生成预览缩略图
   */
  async generatePreview(input: string, maxSize: number = 800): Promise<string> {
    const buffer = this.decodeBase64(input);
    const image = sharp(buffer);
    const metadata = await image.metadata();

    // 计算缩放尺寸
    const width = metadata.width || maxSize;
    const height = metadata.height || maxSize;
    const scale = Math.min(maxSize / width, maxSize / height, 1);

    const result = await image
      .resize({
        width: Math.round(width * scale),
        height: Math.round(height * scale),
        fit: 'inside',
        withoutEnlargement: true,
      })
      .png()
      .toBuffer();

    return result.toString('base64');
  }

  // ============ 私有方法 ============

  private decodeBase64(input: string): Buffer {
    // 移除 data URL 前缀（如果有）
    const base64Data = input.replace(/^data:image\/\w+;base64,/, '');
    return Buffer.from(base64Data, 'base64');
  }

  private async applyOptions(image: sharp.Sharp, options: ProcessOptions): Promise<sharp.Sharp> {
    // 旋转（需要在其他操作之前）
    if (options.rotate !== undefined) {
      const background = options.rotateBackground || '#ffffff';
      image = image.rotate(options.rotate, { background });
    }

    // 翻转
    if (options.flip) {
      image = image.flip();
    }
    if (options.flop) {
      image = image.flop();
    }

    // 尺寸调整
    if (options.resize) {
      const resizeOptions: sharp.ResizeOptions = {
        width: options.resize.width,
        height: options.resize.height,
        fit: options.resize.fit || 'cover',
        withoutEnlargement: options.resize.withoutEnlargement,
      };
      if (options.resize.background) {
        resizeOptions.background = options.resize.background;
      }
      if (options.resize.position) {
        resizeOptions.position = options.resize.position as any;
      }
      image = image.resize(resizeOptions);
    }

    // 扩展
    if (options.extend) {
      image = image.extend({
        top: options.extend.top || 0,
        bottom: options.extend.bottom || 0,
        left: options.extend.left || 0,
        right: options.extend.right || 0,
        background: options.extend.background || '#ffffff',
      });
    }

    // 裁边
    if (options.trim) {
      const trimOptions = typeof options.trim === 'object' ? options.trim : {};
      if (trimOptions.threshold !== undefined) {
        image = image.trim({ threshold: trimOptions.threshold });
      } else {
        image = image.trim();
      }
    }

    // 裁剪
    if (options.extract) {
      image = image.extract(options.extract);
    }

    // 颜色处理
    if (options.grayscale) {
      image = image.grayscale();
    }

    if (options.tint) {
      image = image.tint(options.tint);
    }

    if (options.modulate) {
      image = image.modulate({
        brightness: options.modulate.brightness,
        saturation: options.modulate.saturation,
        hue: options.modulate.hue,
      });
    }

    // 滤镜
    if (options.blur && options.blur > 0) {
      image = image.blur(options.blur);
    }

    if (options.sharpen) {
      image = image.sharpen(
        options.sharpen.sigma,
        options.sharpen.flat,
        options.sharpen.jagged
      );
    }

    if (options.median && options.median > 0) {
      image = image.median(options.median);
    }

    if (options.gamma) {
      const gammaValue = Array.isArray(options.gamma) ? options.gamma : [options.gamma];
      image = image.gamma(...gammaValue);
    }

    if (options.negate) {
      image = image.negate();
    }

    if (options.normalise) {
      image = image.normalise();
    }

    // 合成
    if (options.composite && options.composite.length > 0) {
      const compositeInputs = options.composite.map(item => {
        const inputBuffer = this.decodeBase64(item.input);
        return {
          input: inputBuffer,
          gravity: item.gravity as any,
          top: item.top,
          left: item.left,
          blend: item.blend as any,
        };
      });
      image = image.composite(compositeInputs);
    }

    // 文字水印
    if (options.textWatermark) {
      const metadata = await image.metadata();
      const imageWidth = metadata.width || 800;
      const imageHeight = metadata.height || 600;

      const textWatermarkBuffer = await this.createTextWatermark(
        options.textWatermark,
        imageWidth,
        imageHeight
      );

      image = image.composite([{
        input: textWatermarkBuffer,
        gravity: options.textWatermark.gravity as any || 'southeast',
        top: options.textWatermark.offsetY,
        left: options.textWatermark.offsetX,
      }]);
    }

    return image;
  }

  private applyFormat(image: sharp.Sharp, format: string, options: ProcessOptions): sharp.Sharp {
    switch (format) {
      case 'jpeg':
        return image.jpeg({
          quality: options.quality || 80,
          progressive: options.progressive || false,
          mozjpeg: options.mozjpeg || false,
        });

      case 'png':
        return image.png({
          compressionLevel: options.compressionLevel ?? 6,
          progressive: options.progressive || false,
        });

      case 'webp':
        return image.webp({
          quality: options.quality || 80,
          lossless: options.lossless || false,
          effort: options.effort ?? 4,
        });

      case 'avif':
        return image.avif({
          quality: options.quality || 50,
          lossless: options.lossless || false,
          effort: options.effort ?? 4,
        });

      case 'gif':
        return image.gif();

      case 'tiff':
        return image.tiff({
          quality: options.quality || 80,
          compression: 'lzw',
        });

      default:
        return image.png();
    }
  }

  private parseExif(exifBuffer: Buffer): Record<string, any> {
    // 简单的 EXIF 解析，返回原始数据
    // 实际项目中可以使用 exif-reader 库进行更详细的解析
    try {
      const exifReader = require('exif-reader');
      return exifReader(exifBuffer);
    } catch (e) {
      // 如果没有 exif-reader，返回空对象
      return {};
    }
  }

  private parseIcc(iccBuffer: Buffer): { name: string; description?: string } {
    // 简单的 ICC 解析
    // ICC 配置文件的描述通常在固定位置
    try {
      // 尝试提取 ICC 配置文件名称
      const name = iccBuffer.toString('utf8', 48, 80).replace(/\0/g, '').trim() || 'Unknown';
      return { name };
    } catch (e) {
      return { name: 'Unknown' };
    }
  }

  /**
   * 创建文字水印 SVG
   */
  private async createTextWatermark(
    options: NonNullable<ProcessOptions['textWatermark']>,
    imageWidth: number,
    imageHeight: number
  ): Promise<Buffer> {
    const {
      text,
      font = 'Microsoft YaHei, SimHei, Arial, sans-serif', // 支持中文字体
      fontSize = 24,
      color = '#ffffff',
      opacity = 0.5,
      rotate = 0,
      tile = false,
      tileSpacingX = 100,
      tileSpacingY = 80,
    } = options;

    // 解析颜色 - 支持多种格式
    let r = 255, g = 255, b = 255;
    const colorStr = color.trim();

    if (colorStr.startsWith('#')) {
      // 处理 #RGB 或 #RRGGBB 格式
      const hex = colorStr.slice(1);
      if (hex.length === 3) {
        r = parseInt(hex[0] + hex[0], 16);
        g = parseInt(hex[1] + hex[1], 16);
        b = parseInt(hex[2] + hex[2], 16);
      } else if (hex.length >= 6) {
        r = parseInt(hex.substring(0, 2), 16);
        g = parseInt(hex.substring(2, 4), 16);
        b = parseInt(hex.substring(4, 6), 16);
      }
    } else if (colorStr.startsWith('rgb')) {
      // 处理 rgb(r, g, b) 格式
      const match = colorStr.match(/\d+/g);
      if (match && match.length >= 3) {
        r = parseInt(match[0], 10);
        g = parseInt(match[1], 10);
        b = parseInt(match[2], 10);
      }
    }

    // 确保值在有效范围内
    r = Math.max(0, Math.min(255, isNaN(r) ? 255 : r));
    g = Math.max(0, Math.min(255, isNaN(g) ? 255 : g));
    b = Math.max(0, Math.min(255, isNaN(b) ? 255 : b));
    const a = Math.max(0, Math.min(1, opacity));

    // 处理多行文本
    const lines = text.split('\n');
    const lineHeight = fontSize * 1.4; // 增加行高以适应中文
    const textHeight = lines.length * lineHeight;

    // 估算文本宽度（中文字符约等于 fontSize，英文约 0.6 * fontSize）
    const maxLineWidth = Math.max(...lines.map(line => {
      let width = 0;
      for (const char of line) {
        // 判断是否为中文字符
        if (/[\u4e00-\u9fa5]/.test(char)) {
          width += fontSize; // 中文字符宽度约等于字体大小
        } else {
          width += fontSize * 0.6; // 英文字符宽度约为字体大小的 0.6
        }
      }
      return width;
    }));

    const padding = 20;

    if (tile) {
      // 平铺模式：创建覆盖整个图片的水印
      const singleWatermarkWidth = maxLineWidth + tileSpacingX;
      const singleWatermarkHeight = textHeight + tileSpacingY;

      // 计算需要多少个水印来覆盖整个图片（考虑旋转后的扩展）
      const diagonal = Math.sqrt(imageWidth * imageWidth + imageHeight * imageHeight);
      const cols = Math.ceil(diagonal / singleWatermarkWidth) + 2;
      const rows = Math.ceil(diagonal / singleWatermarkHeight) + 2;

      // 生成平铺的水印
      const watermarks: string[] = [];
      const startX = -singleWatermarkWidth;
      const startY = -singleWatermarkHeight;

      for (let row = 0; row < rows; row++) {
        for (let col = 0; col < cols; col++) {
          const x = startX + col * singleWatermarkWidth;
          const y = startY + row * singleWatermarkHeight;

          // 生成单个水印的文本行
          const textLines = lines.map((line, index) => {
            const textY = y + fontSize + index * lineHeight;
            return `<text x="${x}" y="${textY}" font-family="${font}" font-size="${fontSize}" fill="rgba(${r},${g},${b},${a})">${this.escapeXml(line)}</text>`;
          }).join('\n');

          watermarks.push(textLines);
        }
      }

      // 创建覆盖整个图片的 SVG
      const svg = `<svg width="${imageWidth}" height="${imageHeight}" xmlns="http://www.w3.org/2000/svg">
  <g transform="rotate(${rotate}, ${imageWidth / 2}, ${imageHeight / 2})">
    ${watermarks.join('\n    ')}
  </g>
</svg>`;

      return Buffer.from(svg);
    } else {
      // 单个水印模式 - 需要考虑旋转后的尺寸
      const baseWidth = maxLineWidth + padding * 2;
      const baseHeight = textHeight + padding * 2;

      // 计算旋转后需要的尺寸（使用对角线长度确保不被裁剪）
      const radians = Math.abs(rotate) * Math.PI / 180;
      const rotatedWidth = Math.ceil(baseWidth * Math.cos(radians) + baseHeight * Math.sin(radians));
      const rotatedHeight = Math.ceil(baseWidth * Math.sin(radians) + baseHeight * Math.cos(radians));

      // SVG 尺寸取旋转后的最大值
      const svgWidth = Math.max(baseWidth, rotatedWidth) + padding * 2;
      const svgHeight = Math.max(baseHeight, rotatedHeight) + padding * 2;

      // 文本起始位置（居中）
      const textStartX = (svgWidth - maxLineWidth) / 2;
      const textStartY = (svgHeight - textHeight) / 2;

      // 生成文本行
      const textLines = lines.map((line, index) => {
        const y = textStartY + fontSize + index * lineHeight;
        return `<text x="${textStartX}" y="${y}" font-family="${font}" font-size="${fontSize}" fill="rgba(${r},${g},${b},${a})">${this.escapeXml(line)}</text>`;
      }).join('\n    ');

      // 创建 SVG - 围绕中心点旋转
      const svg = `<svg width="${svgWidth}" height="${svgHeight}" xmlns="http://www.w3.org/2000/svg">
  <g transform="rotate(${rotate}, ${svgWidth / 2}, ${svgHeight / 2})">
    ${textLines}
  </g>
</svg>`;

      return Buffer.from(svg);
    }
  }

  /**
   * 转义 XML 特殊字符
   */
  private escapeXml(text: string): string {
    return text
      .replace(/&/g, '&amp;')
      .replace(/</g, '&lt;')
      .replace(/>/g, '&gt;')
      .replace(/"/g, '&quot;')
      .replace(/'/g, '&apos;');
  }
}

// 导出单例
export const imageService = new ImageService();

import { v4 as uuidv4 } from 'uuid';
import * as crypto from 'crypto';
import { ItemBase, ItemType } from '@shared/types';
import { DatabaseManager } from './Database';
import { SyncCursor } from '../sync/StorageAdapter';
import {
  decryptLocalPayload,
  encryptLocalPayload,
  isLocalPayloadEncrypted,
} from './LocalPayloadCrypto';

const LOCALLY_ENCRYPTED_ITEM_TYPES = new Set<ItemType>([
  'note',
  'excel_note',
  'vault_entry',
]);

export class ItemsManager {
  private db: DatabaseManager;

  constructor(db: DatabaseManager) {
    this.db = db;
    const droppedPlaintextSearch = this.dropPlaintextSearchArtifacts();
    const migratedPayloads = this.migratePayloadEncryptionScope();
    if (droppedPlaintextSearch || migratedPayloads > 0) {
      this.compactDatabase();
    }
  }

  // ========== 同步游标管理（本地存储，按服务器独立）==========

  /**
   * 生成服务器标识符（用于区分不同的同步后端）
   * @param serverType 服务器类型 ('webdav' | 'server')
   * @param serverUrl 服务器 URL
   */
  private generateServerKey(serverType: string, serverUrl: string): string {
    // 使用 URL 的哈希作为标识符，避免 URL 中的特殊字符问题
    const urlHash = crypto.createHash('md5').update(serverUrl).digest('hex').substring(0, 8);
    return `sync_cursor:${serverType}:${urlHash}`;
  }

  /**
   * 获取本地同步游标（按服务器独立存储）
   * @param serverType 服务器类型 ('webdav' | 'server')
   * @param serverUrl 服务器 URL
   */
  getLocalSyncCursor(serverType?: string, serverUrl?: string): SyncCursor | null {
    try {
      // 如果提供了服务器信息，使用新的按服务器存储方式
      const key = serverType && serverUrl 
        ? this.generateServerKey(serverType, serverUrl)
        : 'sync_cursor';  // 兼容旧版本

      const result = this.db.get<{ value: string }>(
        'SELECT value FROM sync_meta WHERE key = ?',
        [key]
      );
      if (!result || !result.value || result.value === '0') {
        return null;
      }
      return JSON.parse(result.value);
    } catch (error) {
      console.error('Failed to get local sync cursor:', error);
      return null;
    }
  }

  /**
   * 设置本地同步游标（按服务器独立存储）
   * @param cursor 游标数据
   * @param serverType 服务器类型 ('webdav' | 'server')
   * @param serverUrl 服务器 URL
   */
  setLocalSyncCursor(cursor: SyncCursor, serverType?: string, serverUrl?: string): boolean {
    try {
      const key = serverType && serverUrl 
        ? this.generateServerKey(serverType, serverUrl)
        : 'sync_cursor';

      this.db.run(
        'INSERT OR REPLACE INTO sync_meta (key, value) VALUES (?, ?)',
        [key, JSON.stringify(cursor)]
      );
      return true;
    } catch (error) {
      console.error('Failed to set local sync cursor:', error);
      return false;
    }
  }

  /**
   * 清除本地同步游标（按服务器独立存储）
   * @param serverType 服务器类型 ('webdav' | 'server')
   * @param serverUrl 服务器 URL
   */
  clearLocalSyncCursor(serverType?: string, serverUrl?: string): boolean {
    try {
      const key = serverType && serverUrl 
        ? this.generateServerKey(serverType, serverUrl)
        : 'sync_cursor';

      this.db.run(
        'INSERT OR REPLACE INTO sync_meta (key, value) VALUES (?, ?)',
        [key, '0']
      );
      return true;
    } catch (error) {
      console.error('Failed to clear local sync cursor:', error);
      return false;
    }
  }

  /**
   * 清除所有同步游标（用于完全重置）
   */
  clearAllSyncCursors(): boolean {
    try {
      this.db.run(
        "DELETE FROM sync_meta WHERE key LIKE 'sync_cursor%'"
      );
      return true;
    } catch (error) {
      console.error('Failed to clear all sync cursors:', error);
      return false;
    }
  }

  // 计算内容哈希
  private computeHash(payload: string): string {
    return crypto.createHash('sha256').update(payload).digest('hex').substring(0, 16);
  }

  private decryptItem(item: ItemBase): ItemBase {
    if (!isLocalPayloadEncrypted(item.payload)) {
      return item;
    }
    return {
      ...item,
      payload: decryptLocalPayload(item.payload),
    };
  }

  private decryptItems(items: ItemBase[]): ItemBase[] {
    return items.map(item => this.decryptItem(item));
  }

  private shouldEncryptPayload(type: ItemType): boolean {
    return LOCALLY_ENCRYPTED_ITEM_TYPES.has(type);
  }

  private preparePayloadForStorage(type: ItemType, payload: string): string {
    if (this.shouldEncryptPayload(type)) {
      return encryptLocalPayload(payload);
    }

    // Keep non-sensitive local payloads plaintext. This also normalizes rows
    // that may have been encrypted by an older local-only development build.
    return isLocalPayloadEncrypted(payload) ? decryptLocalPayload(payload) : payload;
  }

  private migratePayloadEncryptionScope(): number {
    const items = this.db.query<{ id: string; type: ItemType; payload: string }>(
      'SELECT id, type, payload FROM items'
    );

    const updates = items
      .map(item => ({
        ...item,
        nextPayload: this.preparePayloadForStorage(item.type, item.payload),
      }))
      .filter(item => item.nextPayload !== item.payload);

    if (updates.length === 0) return 0;

    this.db.transaction(() => {
      for (const item of updates) {
        this.db.run('UPDATE items SET payload = ? WHERE id = ?', [
          item.nextPayload,
          item.id,
        ]);
      }
    });
    console.log(`[ItemsManager] Normalized ${updates.length} local payloads`);
    return updates.length;
  }

  private dropPlaintextSearchArtifacts(): boolean {
    const artifacts = this.db.query<{ name: string }>(
      `SELECT name FROM sqlite_master
       WHERE name IN (
         'notes_fts_insert',
         'notes_fts_update',
         'notes_fts_delete',
         'notes_fts',
         'items_fts'
       )`
    );
    if (artifacts.length === 0) {
      return false;
    }

    this.db.getDatabase().exec(`
      DROP TRIGGER IF EXISTS notes_fts_insert;
      DROP TRIGGER IF EXISTS notes_fts_update;
      DROP TRIGGER IF EXISTS notes_fts_delete;
      DROP TABLE IF EXISTS notes_fts;
      DROP TABLE IF EXISTS items_fts;
    `);
    return true;
  }

  private compactDatabase(): void {
    try {
      this.db.getDatabase().pragma('wal_checkpoint(TRUNCATE)');
      this.db.getDatabase().exec('VACUUM');
      this.db.getDatabase().pragma('wal_checkpoint(TRUNCATE)');
    } catch (error) {
      console.warn('[ItemsManager] Failed to compact database after local encryption migration:', error);
    }
  }

  getAllForExport(): ItemBase[] {
    return this.decryptItems(this.db.query<ItemBase>('SELECT * FROM items'));
  }

  getRawById(id: string): ItemBase | undefined {
    return this.db.get<ItemBase>('SELECT * FROM items WHERE id = ?', [id]);
  }

  upsertFromPlainItem(item: ItemBase, syncStatus: ItemBase['sync_status'] = item.sync_status): ItemBase {
    const storedPayload = this.preparePayloadForStorage(item.type, item.payload);
    this.db.run(
      `INSERT OR REPLACE INTO items (id, type, created_time, updated_time, deleted_time, payload,
       content_hash, sync_status, local_rev, remote_rev, encryption_applied, schema_version)
       VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)`,
      [
        item.id, item.type, item.created_time, item.updated_time, item.deleted_time,
        storedPayload, item.content_hash, syncStatus, item.local_rev || 1,
        item.remote_rev, item.encryption_applied || 0, item.schema_version || 1,
      ]
    );
    return this.decryptItem({
      ...item,
      payload: storedPayload,
      sync_status: syncStatus,
    });
  }

  // 创建新 Item
  create<T extends object>(type: ItemType, payload: T): ItemBase {
    const now = Date.now();

    // 检查 payload 中是否有 _id 字段（用于创建带固定 ID 的记录）
    const payloadWithId = payload as T & { _id?: string };
    const customId = payloadWithId._id;

    // 如果有自定义 ID，从 payload 中移除 _id 字段
    if (customId) {
      delete payloadWithId._id;
    }

    const payloadStr = JSON.stringify(payloadWithId);
    const item: ItemBase = {
      id: customId || uuidv4(),
      type,
      created_time: now,
      updated_time: now,
      deleted_time: null,
      payload: payloadStr,
      content_hash: this.computeHash(payloadStr),
      sync_status: 'modified',
      local_rev: 1,
      remote_rev: null,
      encryption_applied: 0,
      schema_version: 1,
    };

    console.log(`[ItemsManager] Creating item: type=${type}, id=${item.id}, sync_status=${item.sync_status}`);

    this.db.run(
      `INSERT INTO items (id, type, created_time, updated_time, deleted_time, payload, 
       content_hash, sync_status, local_rev, remote_rev, encryption_applied, schema_version)
       VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)`,
      [
        item.id, item.type, item.created_time, item.updated_time, item.deleted_time,
        this.preparePayloadForStorage(item.type, item.payload), item.content_hash, item.sync_status, item.local_rev,
        item.remote_rev, item.encryption_applied, item.schema_version,
      ]
    );

    // 验证创建后的状态
    const created = this.getById(item.id);
    console.log(`[ItemsManager] Created item verified: id=${item.id}, sync_status=${created?.sync_status}`);

    return item;
  }

  // 创建带指定 ID 的 Item（用于同步时保持远端 ID）
  createWithId(item: ItemBase): ItemBase {
    return this.upsertFromPlainItem(item, 'clean');
  }

  // 获取单个 Item
  getById(id: string): ItemBase | undefined {
    const item = this.db.get<ItemBase>('SELECT * FROM items WHERE id = ? AND deleted_time IS NULL', [id]);
    return item ? this.decryptItem(item) : undefined;
  }

  // 获取单个 Item（包括已删除的）
  getByIdIncludeDeleted(id: string): ItemBase | undefined {
    const item = this.db.get<ItemBase>('SELECT * FROM items WHERE id = ?', [id]);
    return item ? this.decryptItem(item) : undefined;
  }

  // 获取所有指定类型的 Items
  getByType(type: ItemType): ItemBase[] {
    return this.decryptItems(this.db.query<ItemBase>(
      'SELECT * FROM items WHERE type = ? AND deleted_time IS NULL ORDER BY updated_time DESC',
      [type]
    ));
  }

  // 更新 Item（合并更新，保留未修改的字段）
  update<T extends object>(id: string, payload: T): ItemBase | undefined {
    const existing = this.getById(id);
    if (!existing) return undefined;

    // 解析现有的 payload 并合并新的更新
    let existingPayload: object = {};
    try {
      existingPayload = JSON.parse(existing.payload);
    } catch (e) {
      console.error('Failed to parse existing payload:', e);
    }

    // 合并：新的 payload 覆盖旧的字段，保留未修改的字段
    const mergedPayload = { ...existingPayload, ...payload };

    const now = Date.now();
    const payloadStr = JSON.stringify(mergedPayload);
    const newHash = this.computeHash(payloadStr);

    // 只有内容变化时才更新
    if (newHash === existing.content_hash) {
      console.log(`[ItemsManager] update: no content change for id=${id}, type=${existing.type}`);
      return existing;
    }

    console.log(`[ItemsManager] update: updating id=${id}, type=${existing.type}, old_sync_status=${existing.sync_status}, new_sync_status=modified`);

    this.db.run(
      `UPDATE items SET payload = ?, content_hash = ?, updated_time = ?, 
       local_rev = local_rev + 1, sync_status = 'modified' WHERE id = ?`,
      [this.preparePayloadForStorage(existing.type, payloadStr), newHash, now, id]
    );

    const updated = this.getById(id);
    console.log(`[ItemsManager] update: verified id=${id}, sync_status=${updated?.sync_status}`);
    return updated;
  }

  // 从远端同步更新 Item（不改变 sync_status 为 modified）
  updateFromRemote(item: ItemBase): ItemBase | undefined {
    const existing = this.getById(item.id);
    if (!existing) return undefined;

    // 直接使用远端的数据覆盖本地，包括 deleted_time
    this.db.run(
      `UPDATE items SET payload = ?, content_hash = ?, updated_time = ?, 
       remote_rev = ?, sync_status = 'clean', deleted_time = ? WHERE id = ?`,
      [
        this.preparePayloadForStorage(item.type, item.payload),
        item.content_hash,
        item.updated_time,
        item.remote_rev,
        item.deleted_time ?? null,
        item.id,
      ]
    );

    return this.getById(item.id);
  }

  // 从远端同步标记删除（直接设置 deleted_time，不改变 local_rev）
  markDeletedFromRemote(id: string, deletedTime: number): boolean {
    const result = this.db.run(
      `UPDATE items SET deleted_time = ?, sync_status = 'clean' WHERE id = ?`,
      [deletedTime, id]
    );
    return result.changes > 0;
  }

  // 软删除 Item
  softDelete(id: string): boolean {
    const result = this.db.run(
      `UPDATE items SET deleted_time = ?, sync_status = 'deleted', 
       local_rev = local_rev + 1 WHERE id = ? AND deleted_time IS NULL`,
      [Date.now(), id]
    );
    return result.changes > 0;
  }

  // 恢复已删除的 Item
  restore(id: string): boolean {
    const result = this.db.run(
      `UPDATE items SET deleted_time = NULL, sync_status = 'modified', 
       local_rev = local_rev + 1 WHERE id = ? AND deleted_time IS NOT NULL`,
      [id]
    );
    return result.changes > 0;
  }

  // 永久删除 Item
  hardDelete(id: string): boolean {
    const result = this.db.run('DELETE FROM items WHERE id = ?', [id]);
    return result.changes > 0;
  }

  // 获取已删除的 Items（回收站）
  getDeleted(type?: ItemType): ItemBase[] {
    if (type) {
      return this.decryptItems(this.db.query<ItemBase>(
        'SELECT * FROM items WHERE type = ? AND deleted_time IS NOT NULL ORDER BY deleted_time DESC',
        [type]
      ));
    }
    return this.decryptItems(this.db.query<ItemBase>(
      'SELECT * FROM items WHERE deleted_time IS NOT NULL ORDER BY deleted_time DESC'
    ));
  }

  // 获取需要同步的 Items
  getPendingSync(): ItemBase[] {
    const items = this.decryptItems(this.db.query<ItemBase>(
      "SELECT * FROM items WHERE sync_status IN ('modified', 'deleted') ORDER BY updated_time ASC"
    ));
    console.log(`[ItemsManager] getPendingSync: found ${items.length} items`);
    if (items.length > 0) {
      const byType = items.reduce((acc, i) => {
        acc[i.type] = (acc[i.type] || 0) + 1;
        return acc;
      }, {} as Record<string, number>);
      console.log('[ItemsManager] getPendingSync by type:', byType);
    }
    return items;
  }

  // 标记同步完成
  markSynced(id: string, remoteRev: string): boolean {
    const result = this.db.run(
      "UPDATE items SET sync_status = 'clean', remote_rev = ? WHERE id = ?",
      [remoteRev, id]
    );
    return result.changes > 0;
  }

  // 强制标记所有数据为待同步（用于首次同步或强制重新同步）
  markAllForSync(): number {
    const result = this.db.run(
      "UPDATE items SET sync_status = 'modified' WHERE deleted_time IS NULL AND sync_status = 'clean'"
    );
    return result.changes;
  }

  // 重置同步状态（清除所有同步记录，用于切换同步服务器）
  resetSyncStatus(): number {
    const result = this.db.run(
      "UPDATE items SET sync_status = 'modified', remote_rev = NULL WHERE deleted_time IS NULL"
    );
    return result.changes;
  }

  // 标记为冲突
  markConflict(id: string): boolean {
    const result = this.db.run("UPDATE items SET sync_status = 'conflict' WHERE id = ?", [id]);
    return result.changes > 0;
  }

  // 搜索 Items（基础实现，后续用 FTS5 增强）
  search(query: string, type?: ItemType): ItemBase[] {
    const normalized = query.toLowerCase();
    const items = type
      ? this.getByType(type)
      : this.decryptItems(this.db.query<ItemBase>(
          'SELECT * FROM items WHERE deleted_time IS NULL ORDER BY updated_time DESC'
        ));
    return items.filter(item => item.payload.toLowerCase().includes(normalized));
  }

  // 递归获取所有子文件夹 ID
  private getAllChildFolderIds(folderId: string): string[] {
    const childIds: string[] = [];
    const directChildren = this.getByType('folder').filter(folder => {
      try {
        return (JSON.parse(folder.payload) as { parent_id?: string | null }).parent_id === folderId;
      } catch {
        return false;
      }
    });
    for (const child of directChildren) {
      childIds.push(child.id);
      childIds.push(...this.getAllChildFolderIds(child.id));
    }
    return childIds;
  }

  // 按文件夹获取笔记（包括子文件夹中的笔记）
  // folderId === null 时返回所有笔记（用于"所有笔记"视图）
  getNotesByFolder(folderId: string | null): ItemBase[] {
    if (folderId === null) {
      // 返回所有笔记，不限制文件夹
      return this.decryptItems(this.db.query<ItemBase>(
        `SELECT * FROM items WHERE type = 'note' AND deleted_time IS NULL 
         ORDER BY updated_time DESC`
      ));
    }

    // 获取当前文件夹及所有子文件夹的 ID
    const allFolderIds = [folderId, ...this.getAllChildFolderIds(folderId)];

    return this.getByType('note').filter(note => {
      try {
        return allFolderIds.includes((JSON.parse(note.payload) as { folder_id?: string | null }).folder_id || '');
      } catch {
        return false;
      }
    });
  }

  // 获取置顶笔记
  getPinnedNotes(): ItemBase[] {
    return this.getByType('note').filter(note => {
      try {
        return Boolean((JSON.parse(note.payload) as { is_pinned?: boolean }).is_pinned);
      } catch {
        return false;
      }
    });
  }

  // 统计信息
  getStats(): { total: number; byType: Record<string, number> } {
    const total = this.db.get<{ count: number }>(
      'SELECT COUNT(*) as count FROM items WHERE deleted_time IS NULL'
    );
    const byType = this.db.query<{ type: string; count: number }>(
      'SELECT type, COUNT(*) as count FROM items WHERE deleted_time IS NULL GROUP BY type'
    );

    return {
      total: total?.count || 0,
      byType: byType.reduce(
        (acc, row) => {
          acc[row.type] = row.count;
          return acc;
        },
        {} as Record<string, number>
      ),
    };
  }
}

export default ItemsManager;

/**
 * Web Clipper 服务
 * 提供本地 HTTP 服务，接收浏览器扩展发送的网页剪藏请求
 */

import * as http from 'http';
import * as https from 'https';
import * as path from 'path';
import * as fs from 'fs';
import * as crypto from 'crypto';
import { BrowserWindow, ipcMain, app } from 'electron';
import { ItemsManager } from '../../core/database/ItemsManager';

const CLIPPER_PORT = 27183;
const CLIPPER_HOST = '127.0.0.1';

export interface ClipImage {
  src: string;
  alt: string;
}

export interface ClipRequest {
  title: string;
  content: string;
  url: string;
  folderId?: string | null;
  tags?: string[];
  format?: 'html' | 'markdown';
  images?: ClipImage[];
  downloadImages?: boolean;
}

export interface ClipResponse {
  success: boolean;
  noteId?: string;
  error?: string;
}

export class ClipperService {
  private server: http.Server | null = null;
  private itemsManager: ItemsManager | null = null;
  private mainWindow: BrowserWindow | null = null;
  private pendingClip: ClipRequest | null = null;

  constructor() {
    this.setupIpcHandlers();
  }

  /**
   * 设置 ItemsManager 引用
   */
  setItemsManager(manager: ItemsManager) {
    this.itemsManager = manager;
  }

  /**
   * 设置主窗口引用
   */
  setMainWindow(window: BrowserWindow) {
    this.mainWindow = window;
  }

  /**
   * 启动 HTTP 服务
   */
  start(): Promise<void> {
    return new Promise((resolve, reject) => {
      if (this.server) {
        resolve();
        return;
      }

      this.server = http.createServer((req, res) => {
        this.handleRequest(req, res);
      });

      this.server.on('error', (err: NodeJS.ErrnoException) => {
        if (err.code === 'EADDRINUSE') {
          console.log(`Clipper port ${CLIPPER_PORT} is in use, trying next port...`);
          // 端口被占用时尝试下一个端口
          this.server?.listen(CLIPPER_PORT + 1, CLIPPER_HOST);
        } else {
          reject(err);
        }
      });

      this.server.listen(CLIPPER_PORT, CLIPPER_HOST, () => {
        console.log(`Web Clipper service started on http://${CLIPPER_HOST}:${CLIPPER_PORT}`);
        resolve();
      });
    });
  }

  /**
   * 停止 HTTP 服务
   */
  stop(): Promise<void> {
    return new Promise((resolve) => {
      if (this.server) {
        this.server.close(() => {
          this.server = null;
          console.log('Web Clipper service stopped');
          resolve();
        });
      } else {
        resolve();
      }
    });
  }

  /**
   * 处理 HTTP 请求
   */
  private handleRequest(req: http.IncomingMessage, res: http.ServerResponse) {
    // 设置 CORS 头，允许浏览器扩展访问
    res.setHeader('Access-Control-Allow-Origin', '*');
    res.setHeader('Access-Control-Allow-Methods', 'GET, POST, OPTIONS');
    res.setHeader('Access-Control-Allow-Headers', 'Content-Type');

    // 处理预检请求
    if (req.method === 'OPTIONS') {
      res.writeHead(204);
      res.end();
      return;
    }

    const url = req.url || '';

    // 健康检查端点
    if (req.method === 'GET' && url === '/api/status') {
      this.handleStatus(res);
      return;
    }

    // 获取文件夹列表
    if (req.method === 'GET' && url === '/api/folders') {
      this.handleGetFolders(res);
      return;
    }

    // 剪藏端点
    if (req.method === 'POST' && url === '/api/clip') {
      this.handleClip(req, res);
      return;
    }

    // 获取书签文件夹列表
    if (req.method === 'GET' && url === '/api/bookmark-folders') {
      this.handleGetBookmarkFolders(res);
      return;
    }

    // 保存书签端点
    if (req.method === 'POST' && url === '/api/bookmark') {
      this.handleSaveBookmark(req, res);
      return;
    }

    // 404
    res.writeHead(404, { 'Content-Type': 'application/json' });
    res.end(JSON.stringify({ error: 'Not found' }));
  }

  /**
   * 处理状态检查
   */
  private handleStatus(res: http.ServerResponse) {
    res.writeHead(200, { 'Content-Type': 'application/json' });
    res.end(JSON.stringify({
      status: 'ok',
      app: '暮城笔记',
      version: '1.0.0',
    }));
  }

  /**
   * 获取文件夹列表
   */
  private async handleGetFolders(res: http.ServerResponse) {
    try {
      if (!this.itemsManager) {
        res.writeHead(500, { 'Content-Type': 'application/json' });
        res.end(JSON.stringify({ error: 'Service not ready' }));
        return;
      }

      const folders = this.itemsManager.getByType('folder');
      const folderList = folders
        .filter(f => !f.deleted_time)
        .map(f => {
          const payload = JSON.parse(f.payload);
          console.log(`[Clipper] Folder: ${payload.name}, parent_id: ${payload.parent_id}`);
          return {
            id: f.id,
            name: payload.name || '未命名文件夹',
            // 笔记文件夹使用 parent_id（下划线格式）
            parentId: payload.parent_id || null,
          };
        });

      console.log(`[Clipper] Returning ${folderList.length} folders`);
      res.writeHead(200, { 'Content-Type': 'application/json' });
      res.end(JSON.stringify({ folders: folderList }));
    } catch (err: any) {
      console.error('[Clipper] Error getting folders:', err);
      res.writeHead(500, { 'Content-Type': 'application/json' });
      res.end(JSON.stringify({ error: err.message }));
    }
  }

  /**
   * 获取书签文件夹列表
   */
  private async handleGetBookmarkFolders(res: http.ServerResponse) {
    try {
      if (!this.itemsManager) {
        res.writeHead(500, { 'Content-Type': 'application/json' });
        res.end(JSON.stringify({ error: 'Service not ready' }));
        return;
      }

      const folders = this.itemsManager.getByType('bookmark_folder');
      const folderList = folders
        .filter(f => !f.deleted_time)
        .map(f => {
          const payload = JSON.parse(f.payload);
          return {
            id: f.id,
            name: payload.name || '未命名文件夹',
            parentId: payload.parent_id || null,
          };
        });

      res.writeHead(200, { 'Content-Type': 'application/json' });
      res.end(JSON.stringify({ folders: folderList }));
    } catch (err: any) {
      res.writeHead(500, { 'Content-Type': 'application/json' });
      res.end(JSON.stringify({ error: err.message }));
    }
  }

  /**
   * 处理保存书签请求
   */
  private handleSaveBookmark(req: http.IncomingMessage, res: http.ServerResponse) {
    let body = '';

    req.on('data', (chunk) => {
      body += chunk.toString();
    });

    req.on('end', async () => {
      try {
        const data = JSON.parse(body);

        // 验证必要字段
        if (!data.name || !data.url) {
          res.writeHead(400, { 'Content-Type': 'application/json' });
          res.end(JSON.stringify({ success: false, error: '缺少必要字段' }));
          return;
        }

        if (!this.itemsManager) {
          res.writeHead(500, { 'Content-Type': 'application/json' });
          res.end(JSON.stringify({ success: false, error: 'Service not ready' }));
          return;
        }

        // 创建书签
        const payload = {
          name: data.name,
          url: data.url,
          description: data.description || '',
          folder_id: data.folderId || null,
          icon: data.icon || null,
          tags: data.tags || [],
        };

        const bookmark = this.itemsManager.create('bookmark', payload);

        res.writeHead(200, { 'Content-Type': 'application/json' });
        res.end(JSON.stringify({ success: true, bookmarkId: bookmark.id }));
      } catch (err: any) {
        res.writeHead(400, { 'Content-Type': 'application/json' });
        res.end(JSON.stringify({ success: false, error: '无效的请求数据' }));
      }
    });
  }

  /**
   * 处理剪藏请求
   */
  private handleClip(req: http.IncomingMessage, res: http.ServerResponse) {
    let body = '';

    req.on('data', (chunk) => {
      body += chunk.toString();
    });

    req.on('end', async () => {
      try {
        const clipData: ClipRequest = JSON.parse(body);

        // 验证必要字段
        if (!clipData.title || !clipData.content) {
          res.writeHead(400, { 'Content-Type': 'application/json' });
          res.end(JSON.stringify({ success: false, error: '缺少必要字段' }));
          return;
        }

        if (!this.itemsManager) {
          res.writeHead(500, { 'Content-Type': 'application/json' });
          res.end(JSON.stringify({ success: false, error: 'Service not ready' }));
          return;
        }

        // 直接创建笔记
        const payload = {
          title: clipData.title,
          content: clipData.content,
          folder_id: clipData.folderId || null,
          is_pinned: false,
          is_locked: false,
          lock_password_hash: null,
          tags: clipData.tags || [],
        };

        const note = this.itemsManager.create('note', payload);

        // 如果需要下载图片
        if (clipData.downloadImages && clipData.images && clipData.images.length > 0) {
          const processedContent = await this.processImages(clipData.content, clipData.images, note.id);
          this.itemsManager.update(note.id, { content: processedContent });
        }

        // 聚焦窗口并通知保存成功
        if (this.mainWindow && !this.mainWindow.isDestroyed()) {
          if (this.mainWindow.isMinimized()) {
            this.mainWindow.restore();
          }
          this.mainWindow.focus();
          // 通知渲染进程刷新笔记列表
          this.mainWindow.webContents.send('note-created', { noteId: note.id });
        }

        res.writeHead(200, { 'Content-Type': 'application/json' });
        res.end(JSON.stringify({ success: true, noteId: note.id, message: '笔记已保存' }));
      } catch (err: any) {
        res.writeHead(400, { 'Content-Type': 'application/json' });
        res.end(JSON.stringify({ success: false, error: '无效的请求数据' }));
      }
    });
  }

  /**
   * 下载图片并保存到本地资源目录
   */
  private async downloadImage(imageUrl: string, noteId: string): Promise<{ localUrl: string; resourceId: string } | null> {
    return new Promise((resolve) => {
      try {
        const protocol = imageUrl.startsWith('https') ? https : http;

        const request = protocol.get(imageUrl, { timeout: 10000 }, (response) => {
          // 处理重定向
          if (response.statusCode === 301 || response.statusCode === 302) {
            const redirectUrl = response.headers.location;
            if (redirectUrl) {
              this.downloadImage(redirectUrl, noteId).then(resolve);
              return;
            }
          }

          if (response.statusCode !== 200) {
            console.log(`Failed to download image: ${imageUrl}, status: ${response.statusCode}`);
            resolve(null);
            return;
          }

          const chunks: Buffer[] = [];
          response.on('data', (chunk) => chunks.push(chunk));
          response.on('end', () => {
            try {
              const buffer = Buffer.concat(chunks);

              // 检查文件大小（限制 10MB）
              if (buffer.length > 10 * 1024 * 1024) {
                console.log(`Image too large: ${imageUrl}`);
                resolve(null);
                return;
              }

              // 获取文件扩展名
              const contentType = response.headers['content-type'] || '';
              let ext = '.jpg';
              if (contentType.includes('png')) ext = '.png';
              else if (contentType.includes('gif')) ext = '.gif';
              else if (contentType.includes('webp')) ext = '.webp';
              else if (contentType.includes('svg')) ext = '.svg';

              // 从 URL 获取扩展名作为备选
              const urlExt = path.extname(new URL(imageUrl).pathname).toLowerCase();
              if (['.jpg', '.jpeg', '.png', '.gif', '.webp'].includes(urlExt)) {
                ext = urlExt === '.jpeg' ? '.jpg' : urlExt;
              }

              // 生成资源 ID
              const resourceId = crypto.randomUUID();
              const filename = `${resourceId}${ext}`;

              // 保存到资源目录
              const resourcesDir = path.join(app.getPath('userData'), 'resources');
              if (!fs.existsSync(resourcesDir)) {
                fs.mkdirSync(resourcesDir, { recursive: true });
              }

              const resourcePath = path.join(resourcesDir, filename);
              fs.writeFileSync(resourcePath, buffer);

              // 创建资源记录
              if (this.itemsManager) {
                const fileHash = crypto.createHash('sha256').update(buffer).digest('hex');
                const payload = {
                  _id: resourceId,
                  filename: path.basename(imageUrl) || filename,
                  mime_type: contentType || `image/${ext.slice(1)}`,
                  size: buffer.length,
                  note_id: noteId,
                  file_hash: fileHash,
                };
                this.itemsManager.create('resource', payload);
              }

              const localUrl = `resource://${resourceId}${ext}`;
              console.log(`Downloaded image: ${imageUrl} -> ${localUrl}`);
              resolve({ localUrl, resourceId });
            } catch (err) {
              console.error('Failed to save image:', err);
              resolve(null);
            }
          });
          response.on('error', () => resolve(null));
        });

        request.on('error', () => resolve(null));
        request.on('timeout', () => {
          request.destroy();
          resolve(null);
        });
      } catch (err) {
        console.error('Download image error:', err);
        resolve(null);
      }
    });
  }

  /**
   * 处理内容中的图片，下载并替换为本地资源
   */
  private async processImages(content: string, images: ClipImage[], noteId: string): Promise<string> {
    let processedContent = content;

    for (const image of images) {
      try {
        const result = await this.downloadImage(image.src, noteId);
        if (result) {
          // 替换 Markdown 中的图片 URL
          // 匹配 ![alt](url) 格式
          const escapedSrc = image.src.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
          const regex = new RegExp(`!\\[([^\\]]*)\\]\\(${escapedSrc}\\)`, 'g');
          processedContent = processedContent.replace(regex, `![$1](${result.localUrl})`);
        }
      } catch (err) {
        console.error(`Failed to process image: ${image.src}`, err);
      }
    }

    return processedContent;
  }

  /**
   * 设置 IPC 处理器
   */
  private setupIpcHandlers() {
    // 确认剪藏（支持下载图片）
    ipcMain.handle('clipper:confirm', async (_, data: { 
      title: string; 
      content: string; 
      folderId?: string; 
      tags?: string[];
      downloadImages?: boolean;
      images?: ClipImage[];
    }) => {
      try {
        if (!this.itemsManager) {
          return { success: false, error: 'Service not ready' };
        }

        // 先创建笔记获取 ID
        const payload = {
          title: data.title,
          content: data.content,
          folder_id: data.folderId || null,
          is_pinned: false,
          is_locked: false,
          lock_password_hash: null,
          tags: data.tags || [],
        };

        const note = this.itemsManager.create('note', payload);

        // 如果需要下载图片
        if (data.downloadImages && data.images && data.images.length > 0) {
          const processedContent = await this.processImages(data.content, data.images, note.id);
          // 更新笔记内容
          this.itemsManager.update(note.id, { content: processedContent });
        }

        this.pendingClip = null;

        return { success: true, noteId: note.id };
      } catch (err: any) {
        return { success: false, error: err.message };
      }
    });

    // 取消剪藏
    ipcMain.handle('clipper:cancel', async () => {
      this.pendingClip = null;
      return { success: true };
    });

    // 获取待处理的剪藏
    ipcMain.handle('clipper:getPending', async () => {
      return this.pendingClip;
    });
  }

  /**
   * 获取服务端口
   */
  getPort(): number {
    return CLIPPER_PORT;
  }
}

