// 首次同步检测结果
export interface FirstSyncCheckResult {
  isFirstSync: boolean;
  remoteHasData: boolean;
  localItemCount: number;
}

// 初始化同步服务
export async function initializeSyncService(config: SyncServiceConfig): Promise<boolean> {
  try {
    // 停止现有的调度器
    if (syncScheduler) {
      syncScheduler.stop();
      syncScheduler = null;
    }

    if (!config.enabled || !config.url) {
      syncEngine = null;
      currentAdapter = null;
      currentServerIdentifier = null;
      return true;
    }

    // 创建服务器标识（用于独立存储游标）
    currentServerIdentifier = {
      type: config.type,
      url: config.url,
    };

    // 创建适配器
    if (config.type === 'webdav') {
      // 移除 URL 末尾斜杠
      const baseUrl = config.url.replace(/\/+$/, '');
      // 确保 syncPath 以 / 开头
      const syncPath = config.syncPath
        ? config.syncPath.startsWith('/')
          ? config.syncPath
          : '/' + config.syncPath
        : '/mucheng-notes';

      const webdavConfig: WebDAVConfig = {
        url: baseUrl,
        username: config.username || '',
        password: config.password || '',
        basePath: syncPath, // 将 syncPath 作为 basePath 传递
      };
      currentAdapter = new WebDAVAdapter(webdavConfig);
    } else {
      const serverConfig: ServerConfig = {
        url: config.url,
        apiKey: config.apiKey || '',
        token: config.serverToken,
      };
      const serverAdapter = new ServerAdapter(serverConfig);

      // 设置认证信息
      if (config.serverToken) {
        serverAdapter.setAuth(
          config.serverToken,
          config.serverRefreshToken,
          config.serverTokenExpires
        );
      }

      // 保存凭据用于自动重新登录（refresh token 过期时）
      // 自建服务器用 serverUsername/serverPassword，WebDAV 用 username/password
      const credUsername = config.serverUsername || config.username;
      const credPassword = config.serverPassword || config.password;
      if (credUsername && credPassword && config.serverSyncKey) {
        serverAdapter.saveCredentials(credUsername, credPassword, config.serverSyncKey);
      }

      // 设置重新登录回调（通知渲染进程）
      serverAdapter.setReloginRequiredCallback(() => {
        console.warn('[SyncService] Session expired, user needs to re-login');
        BrowserWindow.getAllWindows().forEach(win => {
          win.webContents.send('sync:reloginRequired');
        });
      });

      // 设置 token 刷新回调
      serverAdapter.setTokenRefreshCallback((token, refreshToken, expiresIn) => {
        // 保存新 token 到配置文件（确保持久化）
        try {
          const existingConfig = loadSyncConfig() || {};
          const updatedConfig = {
            ...existingConfig,
            server_token: token,
            server_refresh_token: refreshToken,
            server_token_expires: Date.now() + expiresIn * 1000,
          };
          saveSyncConfig(updatedConfig);
          console.log('[SyncService] Token refreshed and saved to config file');
        } catch (e) {
          console.error('[SyncService] Failed to save refreshed token to config:', e);
        }

        // 通知渲染进程更新 token
        const windows = BrowserWindow.getAllWindows();
        windows.forEach(win => {
          win.webContents.send('sync:tokenRefreshed', { token, refreshToken, expiresIn });
        });
      });

      // 检查 token 是否已过期或即将过期，主动刷新
      if (config.serverRefreshToken) {
        const tokenExpired = config.serverTokenExpires && config.serverTokenExpires < Date.now();
        const tokenExpiringSoon =
          config.serverTokenExpires && config.serverTokenExpires - Date.now() < 5 * 60 * 1000;

        if (tokenExpired || tokenExpiringSoon) {
          console.log('[SyncService] Token expired or expiring soon, refreshing...');
          const refreshed = await serverAdapter.refreshAccessToken();
          if (!refreshed) {
            console.warn('[SyncService] Failed to refresh token, sync will not start');
            return false;
          } else {
            console.log('[SyncService] Token refreshed successfully');
          }
        }
      }

      currentAdapter = serverAdapter;
    }

    // 确保 adapter 已创建
    if (!currentAdapter) {
      console.error('Failed to create storage adapter');
      return false;
    }

    // 测试连接
    const connected = await currentAdapter.testConnection();
    if (!connected) {
      console.error('Failed to connect to sync server');
      return false;
    }

    // 创建同步引擎（明文同步，不再需要加密）
    const itemsManager = getItemsManager();
    const resourcesDir = path.join(app.getPath('userData'), 'resources');
    const syncOptions: Partial<SyncOptions> = {
      conflictStrategy: 'create-copy',
      syncModules: config.syncModules || DEFAULT_SYNC_MODULES,
      serverIdentifier: currentServerIdentifier, // 传递服务器标识
      resourcesDir, // 传递资源目录路径
    };
    syncEngine = new SyncEngine(currentAdapter, itemsManager, syncOptions);

    // 检测是否首次同步（远端没有元数据或没有同步游标）
    // 如果是首次同步，自动标记所有本地数据为待同步
    try {
      const remoteMeta = await currentAdapter.getRemoteMeta();
      const syncCursor = await currentAdapter.getSyncCursor();
      const remoteHasData = await syncEngine.checkRemoteHasData();

      // 如果远端没有上次同步时间，说明是首次同步到这个服务器
      if (!remoteMeta.last_sync_time && !syncCursor) {
        console.log('First sync detected, marking all local data for sync...');
        const count = syncEngine.resetSyncStatus();
        console.log(`Marked ${count} items for sync`);

        // 如果远端已有数据，记录警告（可能会产生冲突）
        if (remoteHasData) {
          console.warn('Remote server already has data. Conflicts may occur during first sync.');
        }
      }
    } catch (e) {
      console.warn('Failed to check first sync status:', e);
    }

    // 创建调度器
    // 启动时不自动同步，只按时间间隔定时同步，用户可手动触发同步
    // syncOnChange 设为 false，不在内容变更时触发同步，只按时间间隔同步
    syncScheduler = new SyncScheduler(syncEngine, {
      autoSyncOnStart: false, // 启动时不自动同步，避免网络问题导致卡顿
      syncInterval: config.syncInterval,
      syncOnChange: false, // 不在内容变更时触发同步
      changeDebounce: 30,
      initialLastSyncTime: config.lastSyncTime, // 从配置加载上次同步时间
      onSyncComplete: (lastSyncTime: number) => {
        // 同步完成后通知渲染进程更新持久化存储
        const windows = BrowserWindow.getAllWindows();
        windows.forEach(win => {
          win.webContents.send('sync:lastSyncTimeUpdated', lastSyncTime);
        });
      },
    });

    return true;
  } catch (error) {
    console.error('Failed to initialize sync service:', error);
    return false;
  }
}

// 启动同步调度
export function startSyncScheduler(): void {
  if (syncScheduler) {
    syncScheduler.start();
  }
}

// 停止同步调度
export function stopSyncScheduler(): void {
  if (syncScheduler) {
    syncScheduler.stop();
  }
}

// 手动触发同步
export async function triggerSync(): Promise<SyncResult | null> {
  if (!syncScheduler) {
    return null;
  }
  return syncScheduler.triggerSync(true);
}

// 获取同步状态
export function getSyncState(): SyncState | null {
  if (!syncScheduler) {
    return null;
  }
  return syncScheduler.getState();
}

// 通知内容变更
export function notifySyncChange(): void {
  if (syncScheduler) {
    syncScheduler.notifyChange();
  }
}

// 测试连接
export async function testSyncConnection(config: SyncServiceConfig): Promise<boolean> {
  console.log('[SyncService] testSyncConnection called with config:', {
    type: config.type,
    url: config.url,
    syncPath: config.syncPath,
    username: config.username,
    passwordLength: config.password?.length || 0,
  });

  if (!config.url) {
    console.error('[SyncService] No URL provided');
    return false;
  }

  try {
    let adapter: StorageAdapter;

    if (config.type === 'webdav') {
      // 移除 URL 末尾斜杠
      const baseUrl = config.url.replace(/\/+$/, '');
      // 确保 syncPath 以 / 开头
      const syncPath = config.syncPath
        ? config.syncPath.startsWith('/')
          ? config.syncPath
          : '/' + config.syncPath
        : '/mucheng-notes';

      console.log('[SyncService] Creating WebDAV adapter with:', {
        url: baseUrl,
        syncPath,
        username: config.username,
        passwordLength: config.password?.length || 0,
      });

      const webdavConfig: WebDAVConfig = {
        url: baseUrl,
        username: config.username || '',
        password: config.password || '',
        basePath: syncPath,
      };

      console.log('[SyncService] WebDAV config created, creating adapter...');
      adapter = new WebDAVAdapter(webdavConfig);
      console.log('[SyncService] WebDAV adapter created successfully');
    } else {
      const serverConfig: ServerConfig = {
        url: config.url,
        apiKey: config.apiKey || '',
        token: config.serverToken,
      };
      const serverAdapter = new ServerAdapter(serverConfig);

      // 设置认证信息
      if (config.serverToken) {
        serverAdapter.setAuth(
          config.serverToken,
          config.serverRefreshToken,
          config.serverTokenExpires
        );
      }

      adapter = serverAdapter;
    }

    console.log('[SyncService] Calling adapter.testConnection()...');
    const startTime = Date.now();
    const result = await adapter.testConnection();
    const duration = Date.now() - startTime;
    console.log('[SyncService] testConnection result:', result, `(${duration}ms)`);
    return result;
  } catch (error: any) {
    console.error('[SyncService] testSyncConnection error:', error);
    if (error instanceof Error) {
      console.error('[SyncService] Error name:', error.name);
      console.error('[SyncService] Error message:', error.message);
      console.error('[SyncService] Error stack:', error.stack);
    }
    // 检查是否是网络错误
    if (error?.code) {
      console.error('[SyncService] Error code:', error.code);
    }
    return false;
  }
}

// 注册 IPC handlers
export function registerSyncIpcHandlers(): void {
  // 初始化同步
  ipcMain.handle(
    'sync:initialize',
    async (_event: IpcMainInvokeEvent, config: SyncServiceConfig) => {
      return initializeSyncService(config);
    }
  );

  // 启动同步调度
  ipcMain.handle('sync:start', () => {
    startSyncScheduler();
    return true;
  });

  // 停止同步调度
  ipcMain.handle('sync:stop', () => {
    stopSyncScheduler();
    return true;
  });

  // 手动同步
  ipcMain.handle('sync:trigger', async () => {
    return triggerSync();
  });

  // 获取状态
  ipcMain.handle('sync:getState', () => {
    return getSyncState();
  });

  // 通知变更
  ipcMain.handle('sync:notifyChange', () => {
    notifySyncChange();
    return true;
  });

  // 测试连接
  ipcMain.handle(
    'sync:testConnection',
    async (_event: IpcMainInvokeEvent, config: SyncServiceConfig) => {
      try {
        console.log('[SyncService IPC] Received testConnection request:', {
          type: config.type,
          url: config.url,
          syncPath: config.syncPath,
          username: config.username,
          passwordLength: config.password?.length || 0,
        });
        const result = await testSyncConnection(config);
        console.log('[SyncService IPC] testConnection result:', result);
        return result;
      } catch (error) {
        console.error('[SyncService IPC] testConnection error:', error);
        return false;
      }
    }
  );

  // 强制重新同步（标记所有数据为待同步）
  ipcMain.handle('sync:forceResync', async () => {
    if (!syncEngine) {
      return { success: false, count: 0, error: '同步服务未初始化' };
    }
    try {
      const count = syncEngine.forceMarkAllForSync();
      return { success: true, count };
    } catch (error) {
      return { success: false, count: 0, error: (error as Error).message };
    }
  });

  // 重置同步状态（用于切换服务器）
  ipcMain.handle('sync:resetStatus', async () => {
    if (!syncEngine) {
      return { success: false, count: 0, error: '同步服务未初始化' };
    }
    try {
      const count = syncEngine.resetSyncStatus();
      return { success: true, count };
    } catch (error) {
      return { success: false, count: 0, error: (error as Error).message };
    }
  });

  // 获取本地同步游标（调试用）
  ipcMain.handle(
    'sync:getLocalCursor',
    async (_event: IpcMainInvokeEvent, serverType?: string, serverUrl?: string) => {
      const itemsManager = getItemsManager();
      // 如果没有提供服务器信息，使用当前配置的服务器
      const type = serverType || currentServerIdentifier?.type;
      const url = serverUrl || currentServerIdentifier?.url;
      const cursor = itemsManager.getLocalSyncCursor(type, url);
      console.log('[SyncService] Local sync cursor for', type, url, ':', cursor);
      return cursor;
    }
  );

  // 清除本地同步游标（强制重新拉取所有变更）
  ipcMain.handle(
    'sync:clearLocalCursor',
    async (_event: IpcMainInvokeEvent, serverType?: string, serverUrl?: string) => {
      const itemsManager = getItemsManager();
      // 如果没有提供服务器信息，使用当前配置的服务器
      const type = serverType || currentServerIdentifier?.type;
      const url = serverUrl || currentServerIdentifier?.url;
      const success = itemsManager.clearLocalSyncCursor(type, url);
      console.log('[SyncService] Cleared local sync cursor for', type, url, ', success:', success);
      return { success };
    }
  );

  // 检查首次同步状态
  ipcMain.handle('sync:checkFirstSync', async () => {
    if (!syncEngine || !currentAdapter) {
      return { isFirstSync: false, remoteHasData: false, localItemCount: 0 };
    }
    try {
      const remoteMeta = await currentAdapter.getRemoteMeta();
      const syncCursor = await currentAdapter.getSyncCursor();
      const remoteHasData = await syncEngine.checkRemoteHasData();
      const itemsManager = getItemsManager();
      const stats = itemsManager.getStats();

      return {
        isFirstSync: !remoteMeta.last_sync_time && !syncCursor,
        remoteHasData,
        localItemCount: stats.total,
      };
    } catch (error) {
      console.error('Failed to check first sync status:', error);
      return { isFirstSync: false, remoteHasData: false, localItemCount: 0 };
    }
  });
}

/**
 * RenameTool - PDF 批量重命名工具
 * 支持多文件上传、命名规则选择、模板占位符替换
 */

import React, { useState, useCallback, useMemo } from 'react';
import {
  Upload,
  Button,
  Space,
  Typography,
  Table,
  Input,
  Select,
  Row,
  Col,
  message,
  Card,
  Tag,
  Tooltip,
  Popconfirm,
} from 'antd';
import {
  InboxOutlined,
  DownloadOutlined,
  DeleteOutlined,
  EditOutlined,
  ClearOutlined,
  QuestionCircleOutlined,
} from '@ant-design/icons';
import type { ColumnsType } from 'antd/es/table';

const { Text, Title } = Typography;
const { Dragger } = Upload;
const { Option } = Select;

// ============ 类型定义 ============

interface FileItem {
  id: string;
  file: File;
  originalName: string;
  newName: string;
}

type NamingRule = 'template' | 'prefix' | 'suffix' | 'replace' | 'sequence';

interface RenameConfig {
  rule: NamingRule;
  template: string;
  prefix: string;
  suffix: string;
  searchText: string;
  replaceText: string;
  startNumber: number;
  padding: number;
}

// ============ 模板占位符说明 ============

const TEMPLATE_PLACEHOLDERS = [
  { placeholder: '{name}', description: '原文件名（不含扩展名）' },
  { placeholder: '{ext}', description: '文件扩展名' },
  { placeholder: '{n}', description: '序号（从1开始）' },
  { placeholder: '{nn}', description: '两位序号（01, 02...）' },
  { placeholder: '{nnn}', description: '三位序号（001, 002...）' },
  { placeholder: '{date}', description: '当前日期（YYYY-MM-DD）' },
  { placeholder: '{time}', description: '当前时间（HH-mm-ss）' },
];

// ============ 工具函数 ============

/**
 * 应用命名模板
 */
export function applyTemplate(
  template: string,
  originalName: string,
  index: number,
  config: RenameConfig
): string {
  const nameWithoutExt = originalName.replace(/\.pdf$/i, '');
  const ext = 'pdf';
  const now = new Date();
  const date = now.toISOString().split('T')[0];
  const time = now.toTimeString().split(' ')[0].replace(/:/g, '-');
  const num = config.startNumber + index;

  let result = template
    .replace(/{name}/g, nameWithoutExt)
    .replace(/{ext}/g, ext)
    .replace(/{nnn}/g, String(num).padStart(3, '0'))
    .replace(/{nn}/g, String(num).padStart(2, '0'))
    .replace(/{n}/g, String(num))
    .replace(/{date}/g, date)
    .replace(/{time}/g, time);

  // 确保有 .pdf 扩展名
  if (!result.toLowerCase().endsWith('.pdf')) {
    result += '.pdf';
  }

  return result;
}

/**
 * 根据规则生成新文件名
 */
function generateNewName(
  originalName: string,
  index: number,
  config: RenameConfig
): string {
  const nameWithoutExt = originalName.replace(/\.pdf$/i, '');

  switch (config.rule) {
    case 'template':
      return applyTemplate(config.template, originalName, index, config);

    case 'prefix':
      return `${config.prefix}${nameWithoutExt}.pdf`;

    case 'suffix':
      return `${nameWithoutExt}${config.suffix}.pdf`;

    case 'replace':
      if (!config.searchText) return originalName;
      const replaced = nameWithoutExt.replace(
        new RegExp(escapeRegExp(config.searchText), 'g'),
        config.replaceText
      );
      return `${replaced}.pdf`;

    case 'sequence':
      const num = config.startNumber + index;
      const paddedNum = String(num).padStart(config.padding, '0');
      return `${paddedNum}_${nameWithoutExt}.pdf`;

    default:
      return originalName;
  }
}

/**
 * 转义正则表达式特殊字符
 */
function escapeRegExp(string: string): string {
  return string.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
}

// ============ 主组件 ============

const RenameTool: React.FC = () => {
  const [files, setFiles] = useState<FileItem[]>([]);
  const [config, setConfig] = useState<RenameConfig>({
    rule: 'template',
    template: '{name}_{nn}',
    prefix: 'new_',
    suffix: '_copy',
    searchText: '',
    replaceText: '',
    startNumber: 1,
    padding: 2,
  });

  // 处理文件上传
  const handleUpload = useCallback((file: File) => {
    if (!file.name.toLowerCase().endsWith('.pdf')) {
      message.error('请上传 PDF 文件');
      return false;
    }

    const newItem: FileItem = {
      id: `${Date.now()}_${Math.random().toString(36).substr(2, 9)}`,
      file,
      originalName: file.name,
      newName: file.name,
    };

    setFiles(prev => [...prev, newItem]);
    return false; // 阻止自动上传
  }, []);

  // 更新所有文件的新名称
  const updateAllNewNames = useCallback(() => {
    setFiles(prev =>
      prev.map((item, index) => ({
        ...item,
        newName: generateNewName(item.originalName, index, config),
      }))
    );
  }, [config]);

  // 当配置改变时更新预览
  React.useEffect(() => {
    if (files.length > 0) {
      updateAllNewNames();
    }
  }, [config, updateAllNewNames]);

  // 删除文件
  const handleDelete = useCallback((id: string) => {
    setFiles(prev => prev.filter(f => f.id !== id));
  }, []);

  // 清空所有文件
  const handleClearAll = useCallback(() => {
    setFiles([]);
  }, []);

  // 手动编辑单个文件名
  const handleEditName = useCallback((id: string, newName: string) => {
    setFiles(prev =>
      prev.map(f => (f.id === id ? { ...f, newName } : f))
    );
  }, []);

  // 下载重命名后的文件
  const handleDownload = useCallback(async () => {
    if (files.length === 0) {
      message.warning('请先添加文件');
      return;
    }

    try {
      for (const item of files) {
        const blob = new Blob([await item.file.arrayBuffer()], {
          type: 'application/pdf',
        });
        const url = URL.createObjectURL(blob);
        const a = document.createElement('a');
        a.href = url;
        a.download = item.newName;
        document.body.appendChild(a);
        a.click();
        document.body.removeChild(a);
        URL.revokeObjectURL(url);
      }
      message.success(`已下载 ${files.length} 个文件`);
    } catch (error) {
      console.error('Download failed:', error);
      message.error('下载失败');
    }
  }, [files]);

  // 表格列定义
  const columns: ColumnsType<FileItem> = useMemo(
    () => [
      {
        title: '序号',
        key: 'index',
        width: 60,
        render: (_, __, index) => index + 1,
      },
      {
        title: '原文件名',
        dataIndex: 'originalName',
        key: 'originalName',
        ellipsis: true,
      },
      {
        title: '新文件名',
        dataIndex: 'newName',
        key: 'newName',
        render: (newName, record) => (
          <Input
            value={newName}
            onChange={e => handleEditName(record.id, e.target.value)}
            size="small"
            suffix={<EditOutlined style={{ color: '#999' }} />}
          />
        ),
      },
      {
        title: '操作',
        key: 'action',
        width: 80,
        render: (_, record) => (
          <Button
            type="text"
            danger
            icon={<DeleteOutlined />}
            onClick={() => handleDelete(record.id)}
          />
        ),
      },
    ],
    [handleEditName, handleDelete]
  );

  // 渲染规则配置
  const renderRuleConfig = () => {
    switch (config.rule) {
      case 'template':
        return (
          <Space direction="vertical" style={{ width: '100%' }} size="small">
            <Input
              placeholder="输入模板，如：{name}_{nn}"
              value={config.template}
              onChange={e => setConfig(prev => ({ ...prev, template: e.target.value }))}
              addonAfter={
                <Tooltip
                  title={
                    <div>
                      {TEMPLATE_PLACEHOLDERS.map(p => (
                        <div key={p.placeholder}>
                          <code>{p.placeholder}</code>: {p.description}
                        </div>
                      ))}
                    </div>
                  }
                >
                  <QuestionCircleOutlined />
                </Tooltip>
              }
            />
            <Space wrap size="small">
              {TEMPLATE_PLACEHOLDERS.slice(0, 5).map(p => (
                <Tag
                  key={p.placeholder}
                  style={{ cursor: 'pointer' }}
                  onClick={() =>
                    setConfig(prev => ({
                      ...prev,
                      template: prev.template + p.placeholder,
                    }))
                  }
                >
                  {p.placeholder}
                </Tag>
              ))}
            </Space>
          </Space>
        );

      case 'prefix':
        return (
          <Input
            placeholder="输入前缀"
            value={config.prefix}
            onChange={e => setConfig(prev => ({ ...prev, prefix: e.target.value }))}
            addonBefore="前缀"
          />
        );

      case 'suffix':
        return (
          <Input
            placeholder="输入后缀"
            value={config.suffix}
            onChange={e => setConfig(prev => ({ ...prev, suffix: e.target.value }))}
            addonBefore="后缀"
          />
        );

      case 'replace':
        return (
          <Space.Compact style={{ width: '100%' }}>
            <Input
              placeholder="查找文本"
              value={config.searchText}
              onChange={e => setConfig(prev => ({ ...prev, searchText: e.target.value }))}
              style={{ width: '50%' }}
            />
            <Input
              placeholder="替换为"
              value={config.replaceText}
              onChange={e => setConfig(prev => ({ ...prev, replaceText: e.target.value }))}
              style={{ width: '50%' }}
            />
          </Space.Compact>
        );

      case 'sequence':
        return (
          <Space>
            <Input
              type="number"
              value={config.startNumber}
              onChange={e => setConfig(prev => ({ ...prev, startNumber: parseInt(e.target.value) || 1 }))}
              addonBefore="起始"
              style={{ width: 120 }}
            />
            <Input
              type="number"
              value={config.padding}
              onChange={e => setConfig(prev => ({ ...prev, padding: parseInt(e.target.value) || 1 }))}
              addonBefore="位数"
              style={{ width: 120 }}
              min={1}
              max={6}
            />
          </Space>
        );

      default:
        return null;
    }
  };

  return (
    <div style={{ padding: 16 }}>
      {/* 参数设置区 */}
      <Card size="small" style={{ marginBottom: 16 }}>
        <Row gutter={[16, 12]} align="middle">
          <Col span={24}>
            <Dragger
              accept=".pdf"
              multiple
              showUploadList={false}
              beforeUpload={handleUpload}
              style={{ padding: '12px 0' }}
            >
              <p className="ant-upload-drag-icon" style={{ marginBottom: 8 }}>
                <InboxOutlined style={{ fontSize: 32, color: '#1890ff' }} />
              </p>
              <p className="ant-upload-text" style={{ marginBottom: 4 }}>
                点击或拖拽 PDF 文件到此处
              </p>
              <p className="ant-upload-hint">支持多个 PDF 文件批量上传</p>
            </Dragger>
          </Col>

          <Col xs={24} sm={8}>
            <Select
              value={config.rule}
              onChange={rule => setConfig(prev => ({ ...prev, rule }))}
              style={{ width: '100%' }}
            >
              <Option value="template">模板命名</Option>
              <Option value="prefix">添加前缀</Option>
              <Option value="suffix">添加后缀</Option>
              <Option value="replace">查找替换</Option>
              <Option value="sequence">序号命名</Option>
            </Select>
          </Col>

          <Col xs={24} sm={16}>
            {renderRuleConfig()}
          </Col>

          <Col span={24}>
            <Space>
              <Button
                type="primary"
                icon={<DownloadOutlined />}
                onClick={handleDownload}
                disabled={files.length === 0}
              >
                下载全部 ({files.length})
              </Button>
              <Popconfirm
                title="确定清空所有文件？"
                onConfirm={handleClearAll}
                disabled={files.length === 0}
              >
                <Button
                  icon={<ClearOutlined />}
                  disabled={files.length === 0}
                >
                  清空
                </Button>
              </Popconfirm>
            </Space>
          </Col>
        </Row>
      </Card>

      {/* 文件列表 */}
      {files.length > 0 ? (
        <Table
          dataSource={files}
          columns={columns}
          rowKey="id"
          size="small"
          pagination={files.length > 10 ? { pageSize: 10 } : false}
          scroll={{ y: 400 }}
        />
      ) : (
        <div style={{ textAlign: 'center', padding: 40, color: '#999' }}>
          <Text type="secondary">请上传 PDF 文件进行批量重命名</Text>
        </div>
      )}
    </div>
  );
};

export default RenameTool;

import * as fs from 'fs';
import * as path from 'path';
import { ItemBase, NotePayload } from '@shared/types';
import { ItemsManager } from '../database/ItemsManager';
import { PDFDocument, rgb, StandardFonts, PDFFont } from 'pdf-lib';
import fontkit from '@pdf-lib/fontkit';

// Windows 系统字体路径（支持中文的字体）
const CHINESE_FONT_PATHS = [
  'C:/Windows/Fonts/msyh.ttc',      // 微软雅黑
  'C:/Windows/Fonts/simhei.ttf',    // 黑体
  'C:/Windows/Fonts/simsun.ttc',    // 宋体
  'C:/Windows/Fonts/simkai.ttf',    // 楷体
  '/System/Library/Fonts/PingFang.ttc',           // macOS 苹方
  '/System/Library/Fonts/STHeiti Light.ttc',      // macOS 华文黑体
  '/usr/share/fonts/truetype/droid/DroidSansFallbackFull.ttf', // Linux
];

/**
 * 查找可用的中文字体
 */
function findChineseFont(): string | null {
  for (const fontPath of CHINESE_FONT_PATHS) {
    if (fs.existsSync(fontPath)) {
      return fontPath;
    }
  }
  return null;
}

/**
 * 检测文本是否包含非 ASCII 字符（如中文）
 */
function containsNonAscii(text: string): boolean {
  return /[^\x00-\x7F]/.test(text);
}

export interface ExportOptions {
  format: 'markdown' | 'pdf' | 'html';
  includeAttachments: boolean;
  outputDir: string;
}

export interface PdfExportOptions {
  pageSize: 'a4' | 'letter';
  margins: { top: number; right: number; bottom: number; left: number };
  fontSize: number;
  includeTitle: boolean;
  includeMetadata: boolean;
}

export interface ExportResult {
  success: boolean;
  filePath: string;
  attachmentPaths: string[];
  error?: string;
}

export class ExportManager {
  private itemsManager: ItemsManager;
  private resourcesDir: string;

  constructor(itemsManager: ItemsManager, resourcesDir: string) {
    this.itemsManager = itemsManager;
    this.resourcesDir = resourcesDir;
  }

  // 导出单个笔记为 Markdown
  async exportToMarkdown(noteId: string, outputDir: string, includeAttachments: boolean = true): Promise<ExportResult> {
    const note = this.itemsManager.getById(noteId);
    if (!note) {
      return { success: false, filePath: '', attachmentPaths: [], error: 'Note not found' };
    }

    const payload = JSON.parse(note.payload) as NotePayload;
    const safeTitle = this.sanitizeFilename(payload.title || 'Untitled');
    const outputPath = path.join(outputDir, `${safeTitle}.md`);

    if (!fs.existsSync(outputDir)) {
      fs.mkdirSync(outputDir, { recursive: true });
    }

    let content = payload.content;
    const attachmentPaths: string[] = [];

    if (includeAttachments) {
      const attachmentsDir = path.join(outputDir, `${safeTitle}_attachments`);
      const { processedContent, copiedAttachments } = await this.processAttachments(
        content,
        noteId,
        attachmentsDir
      );
      content = processedContent;
      attachmentPaths.push(...copiedAttachments);
    }

    const frontMatter = this.generateFrontMatter(payload, note);
    const fullContent = `${frontMatter}\n${content}`;

    fs.writeFileSync(outputPath, fullContent, 'utf8');

    return { success: true, filePath: outputPath, attachmentPaths };
  }

  // 批量导出笔记
  async exportMultiple(noteIds: string[], options: ExportOptions): Promise<ExportResult[]> {
    const results: ExportResult[] = [];
    for (const noteId of noteIds) {
      const result = await this.exportToMarkdown(noteId, options.outputDir, options.includeAttachments);
      results.push(result);
    }
    return results;
  }

  // 导出所有笔记
  async exportAll(options: ExportOptions): Promise<ExportResult[]> {
    const notes = this.itemsManager.getByType('note');
    const noteIds = notes.map(n => n.id);
    return this.exportMultiple(noteIds, options);
  }

  // 导出为 HTML
  async exportToHtml(noteId: string, outputDir: string): Promise<ExportResult> {
    const note = this.itemsManager.getById(noteId);
    if (!note) {
      return { success: false, filePath: '', attachmentPaths: [], error: 'Note not found' };
    }

    const payload = JSON.parse(note.payload) as NotePayload;
    const safeTitle = this.sanitizeFilename(payload.title || 'Untitled');
    const outputPath = path.join(outputDir, `${safeTitle}.html`);

    if (!fs.existsSync(outputDir)) {
      fs.mkdirSync(outputDir, { recursive: true });
    }

    const html = `<!DOCTYPE html>
<html lang="zh-CN">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <title>${this.escapeHtml(payload.title)}</title>
  <style>
    body { font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif; max-width: 800px; margin: 0 auto; padding: 20px; line-height: 1.6; }
    h1 { border-bottom: 1px solid #eee; padding-bottom: 10px; }
    pre { background: #f5f5f5; padding: 10px; border-radius: 4px; overflow-x: auto; }
    code { background: #f5f5f5; padding: 2px 4px; border-radius: 2px; }
    img { max-width: 100%; }
  </style>
</head>
<body>
  <h1>${this.escapeHtml(payload.title)}</h1>
  <div class="content">
    ${this.markdownToHtml(payload.content)}
  </div>
</body>
</html>`;

    fs.writeFileSync(outputPath, html, 'utf8');

    return { success: true, filePath: outputPath, attachmentPaths: [] };
  }

  // 生成 YAML front matter
  private generateFrontMatter(payload: NotePayload, item: ItemBase): string {
    const lines = ['---'];
    lines.push(`title: "${payload.title.replace(/"/g, '\\"')}"`);
    lines.push(`created: ${new Date(item.created_time).toISOString()}`);
    lines.push(`updated: ${new Date(item.updated_time).toISOString()}`);

    if (payload.tags.length > 0) {
      lines.push(`tags: [${payload.tags.map(t => `"${t}"`).join(', ')}]`);
    }

    if (payload.is_pinned) {
      lines.push('pinned: true');
    }

    lines.push('---');
    return lines.join('\n');
  }

  // 处理附件
  private async processAttachments(
    content: string,
    noteId: string,
    attachmentsDir: string
  ): Promise<{ processedContent: string; copiedAttachments: string[] }> {
    const copiedAttachments: string[] = [];
    const resourcePattern = /!\[([^\]]*)\]\(resource:\/\/([^)]+)\)/g;
    let processedContent = content;

    const matches = [...content.matchAll(resourcePattern)];
    if (matches.length === 0) {
      return { processedContent, copiedAttachments };
    }

    if (!fs.existsSync(attachmentsDir)) {
      fs.mkdirSync(attachmentsDir, { recursive: true });
    }

    for (const match of matches) {
      const [fullMatch, altText, resourceRef] = match;
      const resourceId = resourceRef.split('.')[0];

      const files = fs.readdirSync(this.resourcesDir);
      const resourceFile = files.find(f => f.startsWith(resourceId));

      if (resourceFile) {
        const sourcePath = path.join(this.resourcesDir, resourceFile);
        const destPath = path.join(attachmentsDir, resourceFile);

        fs.copyFileSync(sourcePath, destPath);
        copiedAttachments.push(destPath);

        const relativePath = `./${path.basename(attachmentsDir)}/${resourceFile}`;
        processedContent = processedContent.replace(fullMatch, `![${altText}](${relativePath})`);
      }
    }

    return { processedContent, copiedAttachments };
  }

  // 简单的 Markdown 转 HTML
  private markdownToHtml(markdown: string): string {
    let html = markdown;

    // 标题
    html = html.replace(/^### (.*$)/gm, '<h3>$1</h3>');
    html = html.replace(/^## (.*$)/gm, '<h2>$1</h2>');
    html = html.replace(/^# (.*$)/gm, '<h1>$1</h1>');

    // 粗体和斜体
    html = html.replace(/\*\*([^*]+)\*\*/g, '<strong>$1</strong>');
    html = html.replace(/\*([^*]+)\*/g, '<em>$1</em>');

    // 代码块
    html = html.replace(/```(\w*)\n([\s\S]*?)```/g, '<pre><code class="language-$1">$2</code></pre>');
    html = html.replace(/`([^`]+)`/g, '<code>$1</code>');

    // 链接和图片
    html = html.replace(/!\[([^\]]*)\]\(([^)]+)\)/g, '<img src="$2" alt="$1">');
    html = html.replace(/\[([^\]]+)\]\(([^)]+)\)/g, '<a href="$2">$1</a>');

    // 列表
    html = html.replace(/^\- (.*$)/gm, '<li>$1</li>');
    html = html.replace(/(<li>.*<\/li>\n?)+/g, '<ul>$&</ul>');

    // 段落
    html = html.replace(/\n\n/g, '</p><p>');
    html = `<p>${html}</p>`;

    return html;
  }

  // 清理文件名
  private sanitizeFilename(filename: string): string {
    return filename
      .replace(/[<>:"/\\|?*]/g, '_')
      .replace(/\s+/g, '_')
      .substring(0, 100);
  }

  // HTML 转义
  private escapeHtml(text: string): string {
    return text
      .replace(/&/g, '&amp;')
      .replace(/</g, '&lt;')
      .replace(/>/g, '&gt;')
      .replace(/"/g, '&quot;')
      .replace(/'/g, '&#039;');
  }

  // 导出为 PDF（使用 pdf-lib）
  async exportToPdf(
    noteId: string,
    outputDir: string,
    options: Partial<PdfExportOptions> = {}
  ): Promise<ExportResult> {
    const note = this.itemsManager.getById(noteId);
    if (!note) {
      return { success: false, filePath: '', attachmentPaths: [], error: 'Note not found' };
    }

    const payload = JSON.parse(note.payload) as NotePayload;
    const safeTitle = this.sanitizeFilename(payload.title || 'Untitled');
    const outputPath = path.join(outputDir, `${safeTitle}.pdf`);

    if (!fs.existsSync(outputDir)) {
      fs.mkdirSync(outputDir, { recursive: true });
    }

    const defaultOptions: PdfExportOptions = {
      pageSize: 'a4',
      margins: { top: 72, right: 72, bottom: 72, left: 72 },
      fontSize: 12,
      includeTitle: true,
      includeMetadata: true,
    };

    const opts = { ...defaultOptions, ...options };

    try {
      const pdfDoc = await PDFDocument.create();

      // 检测内容是否包含中文，选择合适的字体
      const contentText = payload.title + payload.content;
      let font: PDFFont;
      let boldFont: PDFFont;

      if (containsNonAscii(contentText)) {
        // 包含中文，使用系统中文字体
        const chineseFontPath = findChineseFont();
        if (!chineseFontPath) {
          return {
            success: false,
            filePath: '',
            attachmentPaths: [],
            error: '未找到支持中文的系统字体，请确保系统已安装中文字体（如微软雅黑、黑体等）'
          };
        }

        pdfDoc.registerFontkit(fontkit);
        const fontBytes = fs.readFileSync(chineseFontPath);
        font = await pdfDoc.embedFont(fontBytes);
        boldFont = font; // 中文字体通常没有单独的粗体文件，使用同一字体
      } else {
        // 纯 ASCII，使用标准字体
        font = await pdfDoc.embedFont(StandardFonts.Helvetica);
        boldFont = await pdfDoc.embedFont(StandardFonts.HelveticaBold);
      }

      // 页面尺寸
      const pageSizes = {
        a4: { width: 595.28, height: 841.89 },
        letter: { width: 612, height: 792 },
      };
      const pageSize = pageSizes[opts.pageSize];

      // 可用区域
      const contentWidth = pageSize.width - opts.margins.left - opts.margins.right;
      const contentHeight = pageSize.height - opts.margins.top - opts.margins.bottom;

      // 准备内容
      const lines: { text: string; bold: boolean; size: number }[] = [];

      // 添加标题
      if (opts.includeTitle && payload.title) {
        lines.push({ text: payload.title, bold: true, size: opts.fontSize * 1.5 });
        lines.push({ text: '', bold: false, size: opts.fontSize }); // 空行
      }

      // 添加元数据
      if (opts.includeMetadata) {
        const createdDate = new Date(note.created_time).toLocaleDateString('zh-CN');
        lines.push({ text: `创建时间: ${createdDate}`, bold: false, size: opts.fontSize * 0.8 });
        if (payload.tags.length > 0) {
          lines.push({ text: `标签: ${payload.tags.join(', ')}`, bold: false, size: opts.fontSize * 0.8 });
        }
        lines.push({ text: '', bold: false, size: opts.fontSize }); // 空行
      }

      // 处理内容（简单的文本处理）
      const contentLines = this.processContentForPdf(payload.content, opts.fontSize);
      lines.push(...contentLines);

      // 渲染到 PDF
      let currentPage = pdfDoc.addPage([pageSize.width, pageSize.height]);
      let y = pageSize.height - opts.margins.top;

      for (const line of lines) {
        const lineFont = line.bold ? boldFont : font;
        const lineHeight = line.size * 1.4;

        // 检查是否需要新页
        if (y - lineHeight < opts.margins.bottom) {
          currentPage = pdfDoc.addPage([pageSize.width, pageSize.height]);
          y = pageSize.height - opts.margins.top;
        }

        // 自动换行
        const words = line.text.split('');
        let currentLine = '';

        for (const char of words) {
          const testLine = currentLine + char;
          const testWidth = lineFont.widthOfTextAtSize(testLine, line.size);

          if (testWidth > contentWidth && currentLine.length > 0) {
            // 绘制当前行
            currentPage.drawText(currentLine, {
              x: opts.margins.left,
              y: y - line.size,
              size: line.size,
              font: lineFont,
              color: rgb(0, 0, 0),
            });
            y -= lineHeight;
            currentLine = char;

            // 检查是否需要新页
            if (y - lineHeight < opts.margins.bottom) {
              currentPage = pdfDoc.addPage([pageSize.width, pageSize.height]);
              y = pageSize.height - opts.margins.top;
            }
          } else {
            currentLine = testLine;
          }
        }

        // 绘制剩余文本
        if (currentLine.length > 0) {
          currentPage.drawText(currentLine, {
            x: opts.margins.left,
            y: y - line.size,
            size: line.size,
            font: lineFont,
            color: rgb(0, 0, 0),
          });
        }

        y -= lineHeight;
      }

      // 设置元数据
      pdfDoc.setTitle(payload.title);
      pdfDoc.setCreator('暮城笔记');
      pdfDoc.setProducer('暮城笔记 PDF Export');

      // 保存 PDF
      const pdfBytes = await pdfDoc.save();
      fs.writeFileSync(outputPath, pdfBytes);

      return { success: true, filePath: outputPath, attachmentPaths: [] };
    } catch (error) {
      console.error('Failed to export PDF:', error);
      return { 
        success: false, 
        filePath: '', 
        attachmentPaths: [], 
        error: `PDF export failed: ${error}` 
      };
    }
  }

  // 处理内容为 PDF 行
  private processContentForPdf(
    content: string,
    fontSize: number
  ): { text: string; bold: boolean; size: number }[] {
    const lines: { text: string; bold: boolean; size: number }[] = [];

    // 移除 Markdown 格式，保留纯文本
    const plainText = content
      // 移除代码块
      .replace(/```[\s\S]*?```/g, '[代码块]')
      // 移除行内代码
      .replace(/`([^`]+)`/g, '$1')
      // 移除图片
      .replace(/!\[([^\]]*)\]\([^)]+\)/g, '[图片: $1]')
      // 移除链接，保留文本
      .replace(/\[([^\]]+)\]\([^)]+\)/g, '$1')
      // 移除粗体
      .replace(/\*\*([^*]+)\*\*/g, '$1')
      // 移除斜体
      .replace(/\*([^*]+)\*/g, '$1')
      // 处理标题
      .replace(/^### (.*)$/gm, '$1')
      .replace(/^## (.*)$/gm, '$1')
      .replace(/^# (.*)$/gm, '$1')
      // 处理列表
      .replace(/^[\-\*] /gm, '• ')
      .replace(/^\d+\. /gm, '• ');

    // 按行分割
    const textLines = plainText.split('\n');

    for (const line of textLines) {
      lines.push({ text: line, bold: false, size: fontSize });
    }

    return lines;
  }
}


export default ExportManager;

/**
 * Excel 导入导出服务
 * 支持 .xlsx 和 .csv 文件的导入导出
 */

import {
  ExcelNotePayload,
  ExcelSheet,
  ExcelRow,
  ExcelCell,
  CellValue,
  CellStyle,
  createDefaultExcelSheet,
} from '../../shared/types';

// 导入导出错误
export class ImportExportError extends Error {
  constructor(message: string, public code: string) {
    super(message);
    this.name = 'ImportExportError';
  }
}

export const ImportExportErrors = {
  INVALID_FORMAT: 'INVALID_FORMAT',
  FILE_CORRUPTED: 'FILE_CORRUPTED',
  FILE_TOO_LARGE: 'FILE_TOO_LARGE',
  EXPORT_FAILED: 'EXPORT_FAILED',
} as const;

// 最大文件大小 (10MB)
const MAX_FILE_SIZE = 10 * 1024 * 1024;

/**
 * 导入导出服务
 */
export class ImportExportService {
  /**
   * 导入 XLSX 文件
   */
  async importXlsx(file: File): Promise<ExcelNotePayload> {
    if (file.size > MAX_FILE_SIZE) {
      throw new ImportExportError('文件过大，请选择小于 10MB 的文件', ImportExportErrors.FILE_TOO_LARGE);
    }

    try {
      // 动态导入 xlsx 库
      const XLSX = await import('xlsx');

      const arrayBuffer = await file.arrayBuffer();
      const workbook = XLSX.read(arrayBuffer, { type: 'array' });

      const sheets: ExcelSheet[] = [];

      for (const sheetName of workbook.SheetNames) {
        const worksheet = workbook.Sheets[sheetName];
        const sheet = this.worksheetToExcelSheet(worksheet, sheetName, XLSX);
        sheets.push(sheet);
      }

      if (sheets.length === 0) {
        sheets.push(createDefaultExcelSheet('Sheet1'));
      }

      const title = file.name.replace(/\.(xlsx|xls)$/i, '') || '导入的表格';

      return {
        title,
        description: '',
        folder_id: null,
        is_pinned: false,
        is_locked: false,
        lock_password_hash: null,
        tags: [],
        sheets,
        active_sheet_index: 0,
      };
    } catch (error) {
      if (error instanceof ImportExportError) throw error;
      throw new ImportExportError('无法解析 Excel 文件，文件可能已损坏', ImportExportErrors.FILE_CORRUPTED);
    }
  }

  /**
   * 导入 CSV 文件
   */
  async importCsv(file: File): Promise<ExcelNotePayload> {
    if (file.size > MAX_FILE_SIZE) {
      throw new ImportExportError('文件过大，请选择小于 10MB 的文件', ImportExportErrors.FILE_TOO_LARGE);
    }

    try {
      const text = await file.text();
      const sheet = this.csvToExcelSheet(text, 'Sheet1');

      const title = file.name.replace(/\.csv$/i, '') || '导入的表格';

      return {
        title,
        description: '',
        folder_id: null,
        is_pinned: false,
        is_locked: false,
        lock_password_hash: null,
        tags: [],
        sheets: [sheet],
        active_sheet_index: 0,
      };
    } catch (error) {
      if (error instanceof ImportExportError) throw error;
      throw new ImportExportError('无法解析 CSV 文件', ImportExportErrors.FILE_CORRUPTED);
    }
  }

  /**
   * 导出为 XLSX
   */
  async exportToXlsx(payload: ExcelNotePayload): Promise<Blob> {
    try {
      const XLSX = await import('xlsx');

      const workbook = XLSX.utils.book_new();

      for (const sheet of payload.sheets) {
        const worksheet = this.excelSheetToWorksheet(sheet, XLSX);
        XLSX.utils.book_append_sheet(workbook, worksheet, sheet.name);
      }

      const buffer = XLSX.write(workbook, { type: 'array', bookType: 'xlsx' });
      return new Blob([buffer], { type: 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet' });
    } catch (error) {
      throw new ImportExportError('导出失败，请重试', ImportExportErrors.EXPORT_FAILED);
    }
  }

  /**
   * 导出为 CSV
   */
  async exportToCsv(sheet: ExcelSheet): Promise<Blob> {
    try {
      const csv = this.excelSheetToCsv(sheet);
      return new Blob([csv], { type: 'text/csv;charset=utf-8' });
    } catch (error) {
      throw new ImportExportError('导出失败，请重试', ImportExportErrors.EXPORT_FAILED);
    }
  }

  // ==================== 私有方法 ====================

  /**
   * 将 xlsx worksheet 转换为 ExcelSheet
   */
  private worksheetToExcelSheet(worksheet: any, name: string, XLSX: any): ExcelSheet {
    const range = XLSX.utils.decode_range(worksheet['!ref'] || 'A1');
    const rows: ExcelRow[] = [];
    const columnWidths: number[] = [];
    const rowHeights: number[] = [];

    // 获取列宽
    if (worksheet['!cols']) {
      for (let i = 0; i < worksheet['!cols'].length; i++) {
        const col = worksheet['!cols'][i];
        columnWidths.push(col?.wpx || col?.wch ? col.wch * 8 : 100);
      }
    }

    // 获取行高
    if (worksheet['!rows']) {
      for (let i = 0; i < worksheet['!rows'].length; i++) {
        const row = worksheet['!rows'][i];
        rowHeights.push(row?.hpx || row?.hpt ? row.hpt * 1.33 : 25);
      }
    }

    // 遍历单元格
    for (let r = range.s.r; r <= range.e.r; r++) {
      const cells: ExcelCell[] = [];

      for (let c = range.s.c; c <= range.e.c; c++) {
        const cellAddress = XLSX.utils.encode_cell({ r, c });
        const cell = worksheet[cellAddress];

        if (cell) {
          const value = this.xlsxCellToValue(cell);
          const style = this.xlsxCellToStyle(cell);

          cells.push({
            column_index: c,
            value,
            formula: cell.f ? `=${cell.f}` : null,
            style,
          });
        }
      }

      if (cells.length > 0) {
        rows.push({ row_index: r, cells });
      }
    }

    return {
      id: `sheet-${Date.now()}-${Math.random().toString(36).substring(2, 11)}`,
      name,
      rows,
      column_widths: columnWidths,
      row_heights: rowHeights,
      frozen_rows: 0,
      frozen_columns: 0,
    };
  }

  /**
   * 将 xlsx 单元格值转换为 CellValue
   */
  private xlsxCellToValue(cell: any): CellValue {
    if (cell.t === 'n') return cell.v as number;
    if (cell.t === 'b') return cell.v as boolean;
    if (cell.t === 's' || cell.t === 'str') return cell.v as string;
    if (cell.v !== undefined) return String(cell.v);
    return null;
  }

  /**
   * 将 xlsx 单元格样式转换为 CellStyle
   */
  private xlsxCellToStyle(cell: any): CellStyle | null {
    // xlsx 库的样式信息有限，这里只做基础转换
    if (!cell.s) return null;

    const style = cell.s;
    return {
      font_bold: style.font?.bold || false,
      font_italic: style.font?.italic || false,
      font_color: style.font?.color?.rgb ? `#${style.font.color.rgb}` : null,
      background_color: style.fill?.fgColor?.rgb ? `#${style.fill.fgColor.rgb}` : null,
      text_align: style.alignment?.horizontal || 'left',
      vertical_align: style.alignment?.vertical || 'middle',
      number_format: null,
    };
  }

  /**
   * 将 CSV 文本转换为 ExcelSheet
   */
  private csvToExcelSheet(csv: string, name: string): ExcelSheet {
    const rows: ExcelRow[] = [];
    const lines = this.parseCsvLines(csv);

    lines.forEach((line, rowIndex) => {
      const cells: ExcelCell[] = [];

      line.forEach((value, colIndex) => {
        // 尝试解析为数字
        const numValue = parseFloat(value);
        const cellValue: CellValue = !isNaN(numValue) && value.trim() !== '' ? numValue : value;

        cells.push({
          column_index: colIndex,
          value: cellValue,
          formula: null,
          style: null,
        });
      });

      if (cells.length > 0) {
        rows.push({ row_index: rowIndex, cells });
      }
    });

    return {
      id: `sheet-${Date.now()}-${Math.random().toString(36).substring(2, 11)}`,
      name,
      rows,
      column_widths: [],
      row_heights: [],
      frozen_rows: 0,
      frozen_columns: 0,
    };
  }

  /**
   * 解析 CSV 行（处理引号和逗号）
   */
  private parseCsvLines(csv: string): string[][] {
    const lines: string[][] = [];
    let currentLine: string[] = [];
    let currentField = '';
    let inQuotes = false;

    for (let i = 0; i < csv.length; i++) {
      const char = csv[i];
      const nextChar = csv[i + 1];

      if (inQuotes) {
        if (char === '"' && nextChar === '"') {
          currentField += '"';
          i++; // 跳过下一个引号
        } else if (char === '"') {
          inQuotes = false;
        } else {
          currentField += char;
        }
      } else {
        if (char === '"') {
          inQuotes = true;
        } else if (char === ',') {
          currentLine.push(currentField);
          currentField = '';
        } else if (char === '\n' || (char === '\r' && nextChar === '\n')) {
          currentLine.push(currentField);
          lines.push(currentLine);
          currentLine = [];
          currentField = '';
          if (char === '\r') i++; // 跳过 \n
        } else if (char !== '\r') {
          currentField += char;
        }
      }
    }

    // 处理最后一行
    if (currentField || currentLine.length > 0) {
      currentLine.push(currentField);
      lines.push(currentLine);
    }

    return lines;
  }

  /**
   * 将 ExcelSheet 转换为 xlsx worksheet
   */
  private excelSheetToWorksheet(sheet: ExcelSheet, XLSX: any): any {
    const data: any[][] = [];

    // 找出最大行列
    let maxRow = 0;
    let maxCol = 0;
    for (const row of sheet.rows) {
      maxRow = Math.max(maxRow, row.row_index);
      for (const cell of row.cells) {
        maxCol = Math.max(maxCol, cell.column_index);
      }
    }

    // 初始化数据数组
    for (let r = 0; r <= maxRow; r++) {
      data[r] = [];
      for (let c = 0; c <= maxCol; c++) {
        data[r][c] = null;
      }
    }

    // 填充数据
    for (const row of sheet.rows) {
      for (const cell of row.cells) {
        data[row.row_index][cell.column_index] = cell.value;
      }
    }

    const worksheet = XLSX.utils.aoa_to_sheet(data);

    // 设置列宽
    if (sheet.column_widths.length > 0) {
      worksheet['!cols'] = sheet.column_widths.map(w => ({ wch: w / 8 }));
    }

    // 设置行高
    if (sheet.row_heights.length > 0) {
      worksheet['!rows'] = sheet.row_heights.map(h => ({ hpt: h / 1.33 }));
    }

    return worksheet;
  }

  /**
   * 将 ExcelSheet 转换为 CSV 字符串
   */
  private excelSheetToCsv(sheet: ExcelSheet): string {
    // 找出最大行列
    let maxRow = 0;
    let maxCol = 0;
    for (const row of sheet.rows) {
      maxRow = Math.max(maxRow, row.row_index);
      for (const cell of row.cells) {
        maxCol = Math.max(maxCol, cell.column_index);
      }
    }

    // 构建数据矩阵
    const data: CellValue[][] = [];
    for (let r = 0; r <= maxRow; r++) {
      data[r] = [];
      for (let c = 0; c <= maxCol; c++) {
        data[r][c] = null;
      }
    }

    for (const row of sheet.rows) {
      for (const cell of row.cells) {
        data[row.row_index][cell.column_index] = cell.value;
      }
    }

    // 转换为 CSV
    const lines = data.map(row =>
      row.map(cell => this.escapeCsvField(cell)).join(',')
    );

    return lines.join('\n');
  }

  /**
   * 转义 CSV 字段
   */
  private escapeCsvField(value: CellValue): string {
    if (value === null || value === undefined) return '';

    const str = String(value);

    // 如果包含逗号、引号或换行，需要用引号包裹
    if (str.includes(',') || str.includes('"') || str.includes('\n')) {
      return `"${str.replace(/"/g, '""')}"`;
    }

    return str;
  }
}

