  TokenPair
} from '../types';

const DUMMY_PASSWORD_HASH = '$2b$10$dvFS1xZDvA9KGkEJ0XtO9ufCVUoaloQtVY7gOF8FlB1xktHKPv9Vq';

// 错误码
export const AuthErrorCodes = {
  NO_AUTH: 'AUTH_001',
  INVALID_TOKEN: 'AUTH_002',
  REFRESH_TOKEN_INVALID: 'AUTH_003',
  INVALID_CREDENTIALS: 'AUTH_004',
  SYNC_KEY_MISMATCH: 'AUTH_005',
  ACCOUNT_DISABLED: 'AUTH_006',
  USERNAME_EXISTS: 'AUTH_007',
  WEAK_PASSWORD: 'AUTH_008',
  SHORT_SYNC_KEY: 'AUTH_009',
  RATE_LIMITED: 'AUTH_010',
  ACCOUNT_LOCKED: 'AUTH_011',
  NO_ADMIN: 'AUTH_012',
  REGISTRATION_DISABLED: 'AUTH_016'
};

export class AuthService {
  /**
   * 检查是否有任何用户存在
   */
  hasAnyUser(): boolean {
    const db = getDatabase();
    const row = db.prepare('SELECT COUNT(*) as count FROM users').get() as { count: number };
    return row.count > 0;
  }

  /**
   * 检查注册是否开放
   */
  isRegistrationEnabled(): boolean {
    const db = getDatabase();
    // 如果没有任何用户，始终允许注册（第一个用户）
    if (!this.hasAnyUser()) {
      return true;
    }
    const row = db.prepare('SELECT value FROM system_settings WHERE key = ?').get('registration_enabled') as { value: string } | undefined;
    return row?.value === 'true';
  }

  /**
   * 设置注册开关（仅管理员）
   */
  setRegistrationEnabled(enabled: boolean): void {
    const db = getDatabase();
    const now = Date.now();
    db.prepare('INSERT OR REPLACE INTO system_settings (key, value, updated_at) VALUES (?, ?, ?)')
      .run('registration_enabled', enabled ? 'true' : 'false', now);
  }

  /**
   * 获取系统状态
   */
  getSystemStatus(): { initialized: boolean; registrationEnabled: boolean; userCount: number } {
    const db = getDatabase();
    const countRow = db.prepare('SELECT COUNT(*) as count FROM users').get() as { count: number };
    const initialized = countRow.count > 0;
    return {
      initialized,
      registrationEnabled: this.isRegistrationEnabled(),
      userCount: countRow.count
    };
  }

  /**
   * 用户注册
   */
  async register(
    username: string,
    password: string,
    syncKey: string,
    role: UserRole = 'user'
  ): Promise<RegisterResult> {
    const db = getDatabase();
    const isFirstUser = !this.hasAnyUser();

    // 如果不是第一个用户，检查注册是否开放
    if (!isFirstUser && !this.isRegistrationEnabled()) {
      return { success: false, error: '注册已关闭', errorCode: AuthErrorCodes.REGISTRATION_DISABLED };
    }

    // 第一个用户自动成为管理员
    const actualRole: UserRole = isFirstUser ? 'admin' : role;

    // 验证用户名
    const usernameValidation = validateUsername(username);
    if (!usernameValidation.valid) {
      return { success: false, error: usernameValidation.error, errorCode: 'AUTH_013' };
    }

    // 验证密码强度
    const passwordValidation = validatePasswordStrength(password);
    if (!passwordValidation.valid) {
      return { success: false, error: passwordValidation.error, errorCode: AuthErrorCodes.WEAK_PASSWORD };
    }

    // 验证密码不能与用户名相同
    if (password.toLowerCase() === username.toLowerCase()) {
      return { success: false, error: '密码不能与用户名相同', errorCode: AuthErrorCodes.WEAK_PASSWORD };
    }

    // 验证同步密钥长度
    const syncKeyValidation = validateSyncKeyLength(syncKey);
    if (!syncKeyValidation.valid) {
      return { success: false, error: syncKeyValidation.error, errorCode: AuthErrorCodes.SHORT_SYNC_KEY };
    }

    // 检查用户名是否已存在
    const existingUser = db.prepare('SELECT id FROM users WHERE username = ?').get(username);
    if (existingUser) {
      return { success: false, error: '用户名已存在', errorCode: AuthErrorCodes.USERNAME_EXISTS };
    }

    // 创建用户
    const userId = generateId();
    const passwordHash = await hashPassword(password);
    const syncKeyFingerprint = computeSyncKeyFingerprint(syncKey);
    const now = Date.now();

    db.prepare(`
      INSERT INTO users (id, username, password_hash, sync_key_fingerprint, role, status, created_at, updated_at)
      VALUES (?, ?, ?, ?, ?, 'active', ?, ?)
    `).run(userId, username, passwordHash, syncKeyFingerprint, actualRole, now, now);

    // 如果是第一个用户（管理员），默认关闭注册
    if (isFirstUser) {
      this.setRegistrationEnabled(false);
    }

    return { success: true, userId, isAdmin: actualRole === 'admin' };
  }

  /**
   * 用户登录
   */
  async login(
    username: string,
    password: string,
    syncKey: string,
    deviceInfo?: string,
    ipAddress?: string
  ): Promise<LoginResult> {
    const db = getDatabase();

    // 查找用户（不泄露用户是否存在）
    const user = db.prepare('SELECT * FROM users WHERE username = ?').get(username) as User | undefined;

    // 统一的错误消息，不泄露用户是否存在
    const genericError = { success: false, error: '用户名或密码错误', errorCode: AuthErrorCodes.INVALID_CREDENTIALS };

    if (!user) {
      // 执行一次假的密码验证，防止时序攻击
      await verifyPassword(password, DUMMY_PASSWORD_HASH);
      return genericError;
    }

    // 检查用户状态
    if (user.status === 'disabled') {
      return { success: false, error: '账号已被禁用', errorCode: AuthErrorCodes.ACCOUNT_DISABLED };
    }

    // 验证密码
    const passwordValid = await verifyPassword(password, user.password_hash);
    if (!passwordValid) {
      return genericError;
    }

    // 验证同步密钥
    const syncKeyFingerprint = computeSyncKeyFingerprint(syncKey);
    if (syncKeyFingerprint !== user.sync_key_fingerprint) {
      return { success: false, error: '同步密钥验证失败', errorCode: AuthErrorCodes.SYNC_KEY_MISMATCH };
    }

    // 生成令牌
    const tokens = tokenService.generateTokenPair(
      user.id,
      user.sync_key_fingerprint,
      user.role,
      deviceInfo,
      ipAddress
    );

    // 更新最后登录时间
    db.prepare('UPDATE users SET last_login_at = ? WHERE id = ?').run(Date.now(), user.id);

    return {
      success: true,
      accessToken: tokens.accessToken,
      refreshToken: tokens.refreshToken,
      expiresIn: tokens.expiresIn,
      user: {
        id: user.id,
        username: user.username,
        role: user.role,
        status: user.status,
        created_at: user.created_at,
        last_login_at: Date.now()
      }
    };
  }

  /**
   * 刷新令牌
   */
  refreshToken(refreshToken: string): (TokenPair & { userId: string }) | null {
    return tokenService.refreshTokens(refreshToken);
  }

  /**
   * 登出
   */
  logout(sessionId: string): void {
    tokenService.revokeSession(sessionId);
  }

  /**
   * 登出所有设备
   */
  logoutAll(userId: string): void {
    tokenService.revokeAllUserSessions(userId);
  }

  /**
   * 修改密码
   */
  async changePassword(
    userId: string,
    currentPassword: string,
    newPassword: string
  ): Promise<{ success: boolean; error?: string; errorCode?: string }> {
    const db = getDatabase();

    // 获取用户
    const user = db.prepare('SELECT * FROM users WHERE id = ?').get(userId) as User | undefined;
    if (!user) {
      return { success: false, error: '用户不存在', errorCode: 'AUTH_014' };
    }

    // 验证当前密码
    const passwordValid = await verifyPassword(currentPassword, user.password_hash);
    if (!passwordValid) {
      return { success: false, error: '当前密码错误', errorCode: AuthErrorCodes.INVALID_CREDENTIALS };
    }

    // 验证新密码强度
    const passwordValidation = validatePasswordStrength(newPassword);
    if (!passwordValidation.valid) {
      return { success: false, error: passwordValidation.error, errorCode: AuthErrorCodes.WEAK_PASSWORD };
    }

    // 验证新密码不能与用户名相同
    if (newPassword.toLowerCase() === user.username.toLowerCase()) {
      return { success: false, error: '密码不能与用户名相同', errorCode: AuthErrorCodes.WEAK_PASSWORD };
    }

    // 更新密码
    const newPasswordHash = await hashPassword(newPassword);
    db.prepare('UPDATE users SET password_hash = ?, updated_at = ? WHERE id = ?')
      .run(newPasswordHash, Date.now(), userId);

    // 使所有会话失效
    tokenService.revokeAllUserSessions(userId);

    return { success: true };
  }

  /**
   * 重置密码（使用同步密钥验证）
   */
  async resetPassword(
    username: string,
    syncKey: string,
    newPassword: string
  ): Promise<{ success: boolean; error?: string; errorCode?: string }> {
    const db = getDatabase();

    // 查找用户
    const user = db.prepare('SELECT * FROM users WHERE username = ?').get(username) as User | undefined;
    if (!user) {
      return { success: false, error: '用户不存在', errorCode: 'AUTH_014' };
    }

    // 验证同步密钥
    const syncKeyFingerprint = computeSyncKeyFingerprint(syncKey);
    if (syncKeyFingerprint !== user.sync_key_fingerprint) {
      return { success: false, error: '同步密钥验证失败', errorCode: AuthErrorCodes.SYNC_KEY_MISMATCH };
    }

    // 验证新密码强度
    const passwordValidation = validatePasswordStrength(newPassword);
    if (!passwordValidation.valid) {
      return { success: false, error: passwordValidation.error, errorCode: AuthErrorCodes.WEAK_PASSWORD };
    }

    // 验证新密码不能与用户名相同
    if (newPassword.toLowerCase() === user.username.toLowerCase()) {
      return { success: false, error: '密码不能与用户名相同', errorCode: AuthErrorCodes.WEAK_PASSWORD };
    }

    // 更新密码
    const newPasswordHash = await hashPassword(newPassword);
    db.prepare('UPDATE users SET password_hash = ?, updated_at = ? WHERE id = ?')
      .run(newPasswordHash, Date.now(), user.id);

    // 使所有会话失效
    tokenService.revokeAllUserSessions(user.id);

    return { success: true };
  }

  /**
   * 更新同步密钥
   */
  async updateSyncKey(
    userId: string,
    password: string,
    oldSyncKey: string,
    newSyncKey: string
  ): Promise<{ success: boolean; error?: string; errorCode?: string }> {
    const db = getDatabase();

    // 获取用户
    const user = db.prepare('SELECT * FROM users WHERE id = ?').get(userId) as User | undefined;
    if (!user) {
      return { success: false, error: '用户不存在', errorCode: 'AUTH_014' };
    }

    // 验证密码
    const passwordValid = await verifyPassword(password, user.password_hash);
    if (!passwordValid) {
      return { success: false, error: '密码错误', errorCode: AuthErrorCodes.INVALID_CREDENTIALS };
    }

    // 验证旧同步密钥
    const oldSyncKeyFingerprint = computeSyncKeyFingerprint(oldSyncKey);
    if (oldSyncKeyFingerprint !== user.sync_key_fingerprint) {
      return { success: false, error: '旧同步密钥验证失败', errorCode: AuthErrorCodes.SYNC_KEY_MISMATCH };
    }

    // 验证新同步密钥长度
    const syncKeyValidation = validateSyncKeyLength(newSyncKey);
    if (!syncKeyValidation.valid) {
      return { success: false, error: syncKeyValidation.error, errorCode: AuthErrorCodes.SHORT_SYNC_KEY };
    }

    // 更新同步密钥指纹
    const newSyncKeyFingerprint = computeSyncKeyFingerprint(newSyncKey);
    db.prepare('UPDATE users SET sync_key_fingerprint = ?, updated_at = ? WHERE id = ?')
      .run(newSyncKeyFingerprint, Date.now(), userId);

    // 使所有会话失效
    tokenService.revokeAllUserSessions(userId);

    return { success: true };
  }

  /**
   * 获取用户信息
   */
  getUser(userId: string): UserInfo | null {
    const db = getDatabase();
    const user = db.prepare('SELECT id, username, role, status, created_at, last_login_at FROM users WHERE id = ?')
      .get(userId) as UserInfo | undefined;
    return user || null;
  }

  /**
   * 通过用户名获取用户
   */
  getUserByUsername(username: string): User | null {
    const db = getDatabase();
    const user = db.prepare('SELECT * FROM users WHERE username = ?').get(username) as User | undefined;
    return user || null;
  }

  /**
   * 验证同步密钥指纹
   */
  verifySyncKeyFingerprint(userId: string, fingerprint: string): boolean {
    const db = getDatabase();
    const user = db.prepare('SELECT sync_key_fingerprint FROM users WHERE id = ?')
      .get(userId) as { sync_key_fingerprint: string } | undefined;
    return user?.sync_key_fingerprint === fingerprint;
  }
}

// 导出单例
export const authService = new AuthService();

import React, { useCallback } from 'react';
import { Button, Tooltip, Divider, Dropdown, Space } from 'antd';
import type { MenuProps } from 'antd';
import {
  BoldOutlined,
  ItalicOutlined,
  StrikethroughOutlined,
  OrderedListOutlined,
  UnorderedListOutlined,
  CheckSquareOutlined,
  CodeOutlined,
  LinkOutlined,
  PictureOutlined,
  TableOutlined,
  LineOutlined,
  FontSizeOutlined,
  BlockOutlined,
  MenuOutlined,
  UndoOutlined,
  RedoOutlined,
  FullscreenOutlined,
  FullscreenExitOutlined,
  PaperClipOutlined,
} from '@ant-design/icons';

interface MarkdownToolbarProps {
  textareaRef: React.RefObject<HTMLTextAreaElement>;
  content: string;
  onContentChange: (content: string) => void;
  onInsertImage?: () => void;
  onInsertAttachment?: () => void;
  isFullscreen?: boolean;
  onToggleFullscreen?: () => void;
  disabled?: boolean;
}

// 工具栏按钮样式
const toolbarButtonStyle: React.CSSProperties = {
  padding: '4px 8px',
  minWidth: 32,
  height: 28,
};

const MarkdownToolbar: React.FC<MarkdownToolbarProps> = ({
  textareaRef,
  content,
  onContentChange,
  onInsertImage,
  onInsertAttachment,
  isFullscreen = false,
  onToggleFullscreen,
  disabled = false,
}) => {
  // 获取选中文本的位置信息
  const getSelection = useCallback(() => {
    const textarea = textareaRef.current;
    if (!textarea) return { start: 0, end: 0, text: '' };
    return {
      start: textarea.selectionStart,
      end: textarea.selectionEnd,
      text: content.substring(textarea.selectionStart, textarea.selectionEnd),
    };
  }, [textareaRef, content]);

  // 插入文本并更新光标位置
  const insertText = useCallback((
    before: string,
    after: string = '',
    placeholder: string = '',
    selectPlaceholder: boolean = true
  ) => {
    const textarea = textareaRef.current;
    if (!textarea) return;

    const { start, end, text } = getSelection();
    const selectedText = text || placeholder;
    const newContent = content.substring(0, start) + before + selectedText + after + content.substring(end);

    onContentChange(newContent);

    // 延迟设置光标位置
    setTimeout(() => {
      textarea.focus();
      if (text) {
        // 如果有选中文本，选中插入后的文本
        textarea.setSelectionRange(start + before.length, start + before.length + selectedText.length);
      } else if (selectPlaceholder && placeholder) {
        // 选中占位符
        textarea.setSelectionRange(start + before.length, start + before.length + placeholder.length);
      } else {
        // 光标放在插入内容之后
        textarea.setSelectionRange(start + before.length + selectedText.length + after.length, start + before.length + selectedText.length + after.length);
      }
    }, 0);
  }, [textareaRef, content, getSelection, onContentChange]);

  // 在行首插入文本
  const insertAtLineStart = useCallback((prefix: string) => {
    const textarea = textareaRef.current;
    if (!textarea) return;

    const { start } = getSelection();
    // 找到当前行的开始位置
    const lineStart = content.lastIndexOf('\n', start - 1) + 1;
    const newContent = content.substring(0, lineStart) + prefix + content.substring(lineStart);

    onContentChange(newContent);

    setTimeout(() => {
      textarea.focus();
      textarea.setSelectionRange(start + prefix.length, start + prefix.length);
    }, 0);
  }, [textareaRef, content, getSelection, onContentChange]);

  // 切换行首前缀（如列表）
  const toggleLinePrefix = useCallback((prefix: string) => {
    const textarea = textareaRef.current;
    if (!textarea) return;

    const { start, end } = getSelection();
    const lineStart = content.lastIndexOf('\n', start - 1) + 1;
    const lineEnd = content.indexOf('\n', end);
    const actualLineEnd = lineEnd === -1 ? content.length : lineEnd;
    const lineContent = content.substring(lineStart, actualLineEnd);

    let newContent: string;
    let newCursorPos: number;

    if (lineContent.startsWith(prefix)) {
      // 移除前缀
      newContent = content.substring(0, lineStart) + lineContent.substring(prefix.length) + content.substring(actualLineEnd);
      newCursorPos = Math.max(lineStart, start - prefix.length);
    } else {
      // 添加前缀
      newContent = content.substring(0, lineStart) + prefix + lineContent + content.substring(actualLineEnd);
      newCursorPos = start + prefix.length;
    }

    onContentChange(newContent);

    setTimeout(() => {
      textarea.focus();
      textarea.setSelectionRange(newCursorPos, newCursorPos);
    }, 0);
  }, [textareaRef, content, getSelection, onContentChange]);

  // 插入代码块
  const insertCodeBlock = useCallback((language: string = '') => {
    const { text } = getSelection();
    if (text) {
      insertText('```' + language + '\n', '\n```', text, false);
    } else {
      insertText('```' + language + '\n', '\n```', '代码', true);
    }
  }, [getSelection, insertText]);

  // 插入表格
  const insertTable = useCallback((rows: number = 3, cols: number = 3) => {
    const header = '| ' + Array(cols).fill('表头').join(' | ') + ' |';
    const separator = '| ' + Array(cols).fill('---').join(' | ') + ' |';
    const bodyRows = Array(rows - 1).fill('| ' + Array(cols).fill('内容').join(' | ') + ' |').join('\n');
    const table = '\n' + header + '\n' + separator + '\n' + bodyRows + '\n';
    insertText(table, '', '', false);
  }, [insertText]);

  // 标题菜单
  const headingMenuItems: MenuProps['items'] = [
    { key: 'h1', label: '一级标题', onClick: () => insertAtLineStart('# ') },
    { key: 'h2', label: '二级标题', onClick: () => insertAtLineStart('## ') },
    { key: 'h3', label: '三级标题', onClick: () => insertAtLineStart('### ') },
    { key: 'h4', label: '四级标题', onClick: () => insertAtLineStart('#### ') },
    { key: 'h5', label: '五级标题', onClick: () => insertAtLineStart('##### ') },
    { key: 'h6', label: '六级标题', onClick: () => insertAtLineStart('###### ') },
  ];

  // 代码块语言菜单
  const codeMenuItems: MenuProps['items'] = [
    { key: 'plain', label: '纯文本', onClick: () => insertCodeBlock('') },
    { type: 'divider' },
    { key: 'javascript', label: 'JavaScript', onClick: () => insertCodeBlock('javascript') },
    { key: 'typescript', label: 'TypeScript', onClick: () => insertCodeBlock('typescript') },
    { key: 'python', label: 'Python', onClick: () => insertCodeBlock('python') },
    { key: 'java', label: 'Java', onClick: () => insertCodeBlock('java') },
    { key: 'cpp', label: 'C/C++', onClick: () => insertCodeBlock('cpp') },
    { key: 'csharp', label: 'C#', onClick: () => insertCodeBlock('csharp') },
    { key: 'go', label: 'Go', onClick: () => insertCodeBlock('go') },
    { key: 'rust', label: 'Rust', onClick: () => insertCodeBlock('rust') },
    { key: 'sql', label: 'SQL', onClick: () => insertCodeBlock('sql') },
    { key: 'html', label: 'HTML', onClick: () => insertCodeBlock('html') },
    { key: 'css', label: 'CSS', onClick: () => insertCodeBlock('css') },
    { key: 'json', label: 'JSON', onClick: () => insertCodeBlock('json') },
    { key: 'yaml', label: 'YAML', onClick: () => insertCodeBlock('yaml') },
    { key: 'markdown', label: 'Markdown', onClick: () => insertCodeBlock('markdown') },
    { key: 'bash', label: 'Bash/Shell', onClick: () => insertCodeBlock('bash') },
  ];

  // 表格菜单
  const tableMenuItems: MenuProps['items'] = [
    { key: '2x2', label: '2 × 2 表格', onClick: () => insertTable(2, 2) },
    { key: '3x3', label: '3 × 3 表格', onClick: () => insertTable(3, 3) },
    { key: '4x4', label: '4 × 4 表格', onClick: () => insertTable(4, 4) },
    { key: '5x3', label: '5 × 3 表格', onClick: () => insertTable(5, 3) },
  ];

  return (
    <div
      style={{
        display: 'flex',
        alignItems: 'center',
        padding: '4px 8px',
        borderBottom: '1px solid var(--border-color, #f0f0f0)',
        background: 'var(--bg-secondary, #fafafa)',
        flexWrap: 'wrap',
        gap: 2,
      }}
    >
      {/* 标题 */}
      <Dropdown menu={{ items: headingMenuItems }} trigger={['click']} disabled={disabled}>
        <Tooltip title="标题">
          <Button type="text" size="small" style={toolbarButtonStyle} icon={<FontSizeOutlined />} disabled={disabled} />
        </Tooltip>
      </Dropdown>

      <Divider type="vertical" style={{ margin: '0 4px' }} />

      {/* 文本格式 */}
      <Tooltip title="粗体 (Ctrl+B)">
        <Button
          type="text"
          size="small"
          style={toolbarButtonStyle}
          icon={<BoldOutlined />}
          onClick={() => insertText('**', '**', '粗体文本')}
          disabled={disabled}
        />
      </Tooltip>
      <Tooltip title="斜体 (Ctrl+I)">
        <Button
          type="text"
          size="small"
          style={toolbarButtonStyle}
          icon={<ItalicOutlined />}
          onClick={() => insertText('*', '*', '斜体文本')}
          disabled={disabled}
        />
      </Tooltip>
      <Tooltip title="删除线">
        <Button
          type="text"
          size="small"
          style={toolbarButtonStyle}
          icon={<StrikethroughOutlined />}
          onClick={() => insertText('~~', '~~', '删除线文本')}
          disabled={disabled}
        />
      </Tooltip>
      <Tooltip title="行内代码">
        <Button
          type="text"
          size="small"
          style={toolbarButtonStyle}
          icon={<CodeOutlined />}
          onClick={() => insertText('`', '`', 'code')}
          disabled={disabled}
        />
      </Tooltip>

      <Divider type="vertical" style={{ margin: '0 4px' }} />

      {/* 列表 */}
      <Tooltip title="无序列表">
        <Button
          type="text"
          size="small"
          style={toolbarButtonStyle}
          icon={<UnorderedListOutlined />}
          onClick={() => toggleLinePrefix('- ')}
          disabled={disabled}
        />
      </Tooltip>
      <Tooltip title="有序列表">
        <Button
          type="text"
          size="small"
          style={toolbarButtonStyle}
          icon={<OrderedListOutlined />}
          onClick={() => toggleLinePrefix('1. ')}
          disabled={disabled}
        />
      </Tooltip>
      <Tooltip title="任务列表">
        <Button
          type="text"
          size="small"
          style={toolbarButtonStyle}
          icon={<CheckSquareOutlined />}
          onClick={() => toggleLinePrefix('- [ ] ')}
          disabled={disabled}
        />
      </Tooltip>

      <Divider type="vertical" style={{ margin: '0 4px' }} />

      {/* 引用和代码块 */}
      <Tooltip title="引用">
        <Button
          type="text"
          size="small"
          style={toolbarButtonStyle}
