/**
 * Excel 工具栏组件
 * 提供格式化、撤销重做等操作按钮
 */

import React from 'react';
import { Button, Tooltip, Divider, Select, ColorPicker, Badge } from 'antd';
import {
  BoldOutlined,
  ItalicOutlined,
  UndoOutlined,
  RedoOutlined,
  AlignLeftOutlined,
  AlignCenterOutlined,
  AlignRightOutlined,
  VerticalAlignTopOutlined,
  VerticalAlignMiddleOutlined,
  VerticalAlignBottomOutlined,
  BgColorsOutlined,
  FontColorsOutlined,
  ImportOutlined,
  ExportOutlined,
  MergeCellsOutlined,
  SplitCellsOutlined,
  SearchOutlined,
  SortAscendingOutlined,
  SortDescendingOutlined,
  FilterOutlined,
} from '@ant-design/icons';
import { CellStyle, NumberFormat } from '@shared/types';

interface ExcelToolbarProps {
  selectedStyle: CellStyle | null;
  canUndo: boolean;
  canRedo: boolean;
  hasSelection: boolean;
  isMerged: boolean;
  hasActiveFilters: boolean;
  showFilterButtons: boolean;
  isSaving?: boolean;
  lastSaved?: Date | null;
  onSave?: () => void;
  onStyleChange: (style: Partial<CellStyle>) => void;
  onUndo: () => void;
  onRedo: () => void;
  onImport: () => void;
  onExportXlsx: () => void;
  onExportCsv: () => void;
  onMergeCells: () => void;
  onUnmergeCells: () => void;
  onFind: () => void;
  onReplace: () => void;
  onSortAsc: () => void;
  onSortDesc: () => void;
  onToggleFilter: () => void;
  onClearFilters: () => void;
}

const numberFormatOptions = [
  { value: 'general', label: '常规' },
  { value: 'number', label: '数字' },
  { value: 'percentage', label: '百分比' },
  { value: 'currency', label: '货币' },
  { value: 'date', label: '日期' },
];

// 将选择值转换为 NumberFormat 对象
const valueToNumberFormat = (value: string): NumberFormat | null => {
  switch (value) {
    case 'general':
      return { type: 'general' };
    case 'number':
      return { type: 'number', decimals: 2 };
    case 'percentage':
      return { type: 'percentage', decimals: 2 };
    case 'currency':
      return { type: 'currency', symbol: '¥', decimals: 2 };
    case 'date':
      return { type: 'date', pattern: 'YYYY-MM-DD' };
    default:
      return null;
  }
};

// 将 NumberFormat 对象转换为选择值
const numberFormatToValue = (format: NumberFormat | null | undefined): string => {
  if (!format) return 'general';
  return format.type;
};

export const ExcelToolbar: React.FC<ExcelToolbarProps> = ({
  selectedStyle,
  canUndo,
  canRedo,
  hasSelection,
  isMerged,
  hasActiveFilters,
  showFilterButtons,
  isSaving = false,
  lastSaved = null,
  onSave,
  onStyleChange,
  onUndo,
  onRedo,
  onImport,
  onExportXlsx,
  onExportCsv,
  onMergeCells,
  onUnmergeCells,
  onFind,
  onReplace,
  onSortAsc,
  onSortDesc,
  onToggleFilter,
  onClearFilters,
}) => {
  return (
    <div className="excel-toolbar" style={{ 
      display: 'flex', 
      alignItems: 'center', 
      gap: 4, 
      padding: '8px 12px',
      borderBottom: '1px solid #e8e8e8',
      background: '#fafafa',
      flexWrap: 'wrap',
    }}>
      {/* 保存按钮和状态 */}
      {onSave && (
        <>
