        />
      </Tooltip>
      <Tooltip title="右对齐">
        <Button 
          icon={<AlignRightOutlined />}
          type={selectedStyle?.text_align === 'right' ? 'primary' : 'default'}
          onClick={() => onStyleChange({ text_align: 'right' })}
          size="small"
        />
      </Tooltip>

      <Divider type="vertical" />

      {/* 垂直对齐 */}
      <Tooltip title="顶部对齐">
        <Button 
          icon={<VerticalAlignTopOutlined />}
