import { app, ipcMain, IpcMainInvokeEvent, dialog } from 'electron';
import { DatabaseManager, ItemsManager } from '@core/database';
import { ItemBase, ItemType } from '@shared/types';
import * as fs from 'fs';
import * as path from 'path';
import * as crypto from 'crypto';

let dbManager: DatabaseManager | null = null;
let itemsManager: ItemsManager | null = null;

// 导出数据格式版本
const EXPORT_VERSION = '1.0';

interface ExportData {
  version: string;
  exportTime: number;
  appVersion: string;
  checksum: string;
  items: Array<{
    id: string;
    type: string;
    created_time: number;
    updated_time: number;
    deleted_time: number | null;
    payload: string;
    content_hash: string;
    sync_status: string;
    local_rev: number;
    remote_rev: string | null;
    encryption_applied: number;
    schema_version: number;
  }>;
  resources: Array<{
    filename: string;
    data: string; // base64
  }>;
  syncConfig?: object | null;
  aiSettings?: string | null; // localStorage JSON string
}

export function initializeDatabase(): void {
  const userDataPath = app.getPath('userData');
  dbManager = new DatabaseManager(userDataPath);
  dbManager.initialize();
  itemsManager = new ItemsManager(dbManager);

  registerIpcHandlers();
}

export function getItemsManager(): ItemsManager {
  if (!itemsManager) throw new Error('Database not initialized');
  return itemsManager;
}

export function closeDatabase(): void {
  if (dbManager) {
    dbManager.close();
    dbManager = null;
    itemsManager = null;
  }
}

function registerIpcHandlers(): void {
  // 创建 Item
  ipcMain.handle('items:create', (_event: IpcMainInvokeEvent, type: ItemType, payload: object) => {
    return getItemsManager().create(type, payload);
  });

  // 获取单个 Item
  ipcMain.handle('items:getById', (_event: IpcMainInvokeEvent, id: string) => {
    return getItemsManager().getById(id);
  });

  // 获取单个 Item（包括已删除的）
  ipcMain.handle('items:getByIdIncludeDeleted', (_event: IpcMainInvokeEvent, id: string) => {
    return getItemsManager().getByIdIncludeDeleted(id);
  });

  // 获取指定类型的所有 Items
  ipcMain.handle('items:getByType', (_event: IpcMainInvokeEvent, type: ItemType) => {
    return getItemsManager().getByType(type);
  });

  // 更新 Item
  ipcMain.handle('items:update', (_event: IpcMainInvokeEvent, id: string, payload: object) => {
    return getItemsManager().update(id, payload);
  });

  // 软删除 Item
  ipcMain.handle('items:delete', (_event: IpcMainInvokeEvent, id: string) => {
    return getItemsManager().softDelete(id);
  });

  // 永久删除 Item（从回收站彻底删除）
  ipcMain.handle('items:hardDelete', (_event: IpcMainInvokeEvent, id: string) => {
    return getItemsManager().hardDelete(id);
  });

  // 恢复 Item
  ipcMain.handle('items:restore', (_event: IpcMainInvokeEvent, id: string) => {
    return getItemsManager().restore(id);
  });

  // 搜索
  ipcMain.handle('items:search', (_event: IpcMainInvokeEvent, query: string, type?: ItemType) => {
    return getItemsManager().search(query, type);
  });

  // 按文件夹获取笔记
  ipcMain.handle('items:getNotesByFolder', (_event: IpcMainInvokeEvent, folderId: string | null) => {
    return getItemsManager().getNotesByFolder(folderId);
  });

  // 获取置顶笔记
  ipcMain.handle('items:getPinnedNotes', () => {
    return getItemsManager().getPinnedNotes();
  });

  // 获取已删除的 Items
  ipcMain.handle('items:getDeleted', (_event: IpcMainInvokeEvent, type?: ItemType) => {
    return getItemsManager().getDeleted(type);
  });

  // 获取统计信息
  ipcMain.handle('items:getStats', () => {
    return getItemsManager().getStats();
  });

  // 导出数据
  ipcMain.handle('data:export', async (_event: IpcMainInvokeEvent, options: { includeResources: boolean }) => {
    try {
      // 弹出保存对话框
      const result = await dialog.showSaveDialog({
        title: '导出数据',
        defaultPath: `mucheng-notes-backup-${new Date().toISOString().slice(0, 10)}.mcdata`,
        filters: [
          { name: '暮城笔记数据', extensions: ['mcdata'] },
          { name: '所有文件', extensions: ['*'] }
        ]
      });

      if (result.canceled || !result.filePath) {
        return { success: false, error: '已取消' };
      }

      const userDataPath = app.getPath('userData');

      // 获取所有数据。ItemsManager 返回的是明文 payload，避免把本地落盘密文导出。
      const items = getItemsManager().getAllForExport();

      // 读取同步配置
      let syncConfig: object | null = null;
      const syncConfigPath = path.join(userDataPath, 'sync-config.json');
      if (fs.existsSync(syncConfigPath)) {
        try { syncConfig = JSON.parse(fs.readFileSync(syncConfigPath, 'utf8')); } catch {}
      }

      // 读取 AI 设置（从数据库中的 ai-config-singleton 条目）
      let aiSettings: string | null = null;
      const aiConfigItem = getItemsManager().getByIdIncludeDeleted('ai-config-singleton');
      if (aiConfigItem) {
        aiSettings = aiConfigItem.payload;
      }

      // 准备导出数据
      const exportData: ExportData = {
        version: EXPORT_VERSION,
        exportTime: Date.now(),
        appVersion: app.getVersion(),
        checksum: '',
        items: items,
        resources: [],
        syncConfig,
        aiSettings,
      };

      // 导出资源文件
      if (options.includeResources) {
        const resourcesDir = path.join(userDataPath, 'resources');
        if (fs.existsSync(resourcesDir)) {
          const files = fs.readdirSync(resourcesDir);
          for (const filename of files) {
            const filePath = path.join(resourcesDir, filename);
            const stat = fs.statSync(filePath);
            if (stat.isFile()) {
              const data = fs.readFileSync(filePath);
              exportData.resources.push({
                filename,
                data: data.toString('base64')
              });
            }
          }
        }
      }

      // 计算校验和
      const dataStr = JSON.stringify({ items: exportData.items, resources: exportData.resources });
      exportData.checksum = crypto.createHash('sha256').update(dataStr).digest('hex');

      // 写入文件
      fs.writeFileSync(result.filePath, JSON.stringify(exportData, null, 2), 'utf8');

      return {
        success: true,
        filePath: result.filePath,
        itemsCount: items.length,
        resourcesCount: exportData.resources.length
      };
    } catch (error) {
      console.error('Export failed:', error);
      return { success: false, error: (error as Error).message };
    }
  });

  // 导入数据
  ipcMain.handle('data:import', async (_event: IpcMainInvokeEvent, options: { mode: 'merge' | 'replace' }) => {
    try {
      // 弹出打开对话框
      const result = await dialog.showOpenDialog({
        title: '导入数据',
        filters: [
          { name: '暮城笔记数据', extensions: ['mcdata', 'mcbak'] },
          { name: '所有文件', extensions: ['*'] }
        ],
        properties: ['openFile']
      });

      if (result.canceled || result.filePaths.length === 0) {
        return { success: false, error: '已取消' };
      }

      const filePath = result.filePaths[0];
      const content = fs.readFileSync(filePath, 'utf8');
      const importData: ExportData = JSON.parse(content);

      // 验证数据格式
      if (!importData.version || !importData.items) {
        return { success: false, error: '无效的数据文件格式' };
      }

      // 验证校验和
      const dataStr = JSON.stringify({ items: importData.items, resources: importData.resources || [] });
      const checksum = crypto.createHash('sha256').update(dataStr).digest('hex');
      if (importData.checksum && checksum !== importData.checksum) {
        return { success: false, error: '数据校验失败，文件可能已损坏' };
      }

      const userDataPath = app.getPath('userData');
      let itemsImported = 0;
      let itemsSkipped = 0;
      let resourcesImported = 0;

      // 如果是替换模式，先清空现有数据
      if (options.mode === 'replace') {
        dbManager!.run('DELETE FROM items');
        // 清空资源目录
        const resourcesDir = path.join(userDataPath, 'resources');
        if (fs.existsSync(resourcesDir)) {
          const files = fs.readdirSync(resourcesDir);
          for (const file of files) {
            fs.unlinkSync(path.join(resourcesDir, file));
          }
        }
      }

      // 导入数据
      dbManager!.transaction(() => {
        for (const item of importData.items) {
          const importItem = item as ItemBase;
          if (options.mode === 'merge') {
            // 合并模式：检查是否已存在
            const existing = getItemsManager().getRawById(importItem.id);
            if (existing) {
              // 比较更新时间，保留较新的
              if (existing.updated_time >= importItem.updated_time) {
                itemsSkipped++;
                continue;
              }
            }
          }

          // 插入或更新。导入文件中的 payload 是明文，通过 ItemsManager 写入时会本地加密。
          getItemsManager().upsertFromPlainItem(
            {
              ...importItem,
              local_rev: importItem.local_rev || 1,
              encryption_applied: importItem.encryption_applied || 0,
              schema_version: importItem.schema_version || 1,
            },
            'modified'
          );
          itemsImported++;
        }
      });

      // 导入资源文件
      if (importData.resources && importData.resources.length > 0) {
        const resourcesDir = path.join(userDataPath, 'resources');
        if (!fs.existsSync(resourcesDir)) {
          fs.mkdirSync(resourcesDir, { recursive: true });
        }

        for (const resource of importData.resources) {
          const destPath = path.join(resourcesDir, resource.filename);
          // 合并模式下，如果文件已存在则跳过
          if (options.mode === 'merge' && fs.existsSync(destPath)) {
            continue;
          }
          const data = Buffer.from(resource.data, 'base64');
          fs.writeFileSync(destPath, data);
          resourcesImported++;
        }
      }

      // 还原同步配置
      if (importData.syncConfig) {
        const syncConfigPath = path.join(userDataPath, 'sync-config.json');
        // 合并模式下不覆盖已有同步配置
        if (options.mode === 'replace' || !fs.existsSync(syncConfigPath)) {
          fs.writeFileSync(syncConfigPath, JSON.stringify(importData.syncConfig, null, 2), 'utf8');
        }
      }

      return {
        success: true,
        itemsImported,
        itemsSkipped,
        resourcesImported,
        totalItems: importData.items.length,
        totalResources: importData.resources?.length || 0,
        syncConfigImported: !!importData.syncConfig,
        aiSettingsImported: !!importData.aiSettings,
      };
    } catch (error) {
      console.error('Import failed:', error);
      return { success: false, error: (error as Error).message };
    }
  });

  // 获取导入文件预览信息
  ipcMain.handle('data:previewImport', async () => {
    try {
      const result = await dialog.showOpenDialog({
        title: '选择要导入的数据文件',
        filters: [
          { name: '暮城笔记数据', extensions: ['mcdata', 'mcbak'] },
          { name: '所有文件', extensions: ['*'] }
        ],
        properties: ['openFile']
      });

      if (result.canceled || result.filePaths.length === 0) {
        return { success: false, error: '已取消' };
      }

      const filePath = result.filePaths[0];
      const content = fs.readFileSync(filePath, 'utf8');
      const importData: ExportData = JSON.parse(content);

      // 统计各类型数量
      const typeCounts: Record<string, number> = {};
      for (const item of importData.items) {
        typeCounts[item.type] = (typeCounts[item.type] || 0) + 1;
      }

      return {
        success: true,
        filePath,
        version: importData.version,
        exportTime: importData.exportTime,
        appVersion: importData.appVersion,
        itemsCount: importData.items.length,
        resourcesCount: importData.resources?.length || 0,
        typeCounts
      };
    } catch (error) {
      console.error('Preview import failed:', error);
      return { success: false, error: (error as Error).message };
    }
  });
}

/**
 * FormFillTool - PDF 表单填写工具
 * 支持检测和填写 PDF 表单字段
 */

import React, { useState, useCallback } from 'react';
import {
  Upload,
  Button,
  Space,
  Typography,
  Card,
  Row,
  Col,
  message,
  Spin,
  Input,
  Checkbox,
  Select,
  Form,
  Empty,
  Tag,
  Alert,
} from 'antd';
import {
  InboxOutlined,
  DownloadOutlined,
  ClearOutlined,
  FormOutlined,
  FileTextOutlined,
  CheckSquareOutlined,
} from '@ant-design/icons';
import { pdfApi, FormField } from '../../services/pdfApi';

const { Text } = Typography;
const { Dragger } = Upload;
const { Option } = Select;

// ============ 类型定义 ============

interface FormValues {
  [fieldName: string]: any;
}

// ============ 主组件 ============

const FormFillTool: React.FC = () => {
  const [pdfData, setPdfData] = useState<ArrayBuffer | null>(null);
  const [fileName, setFileName] = useState<string>('');
  const [formFields, setFormFields] = useState<FormField[]>([]);
  const [formValues, setFormValues] = useState<FormValues>({});
  const [loading, setLoading] = useState(false);
  const [processing, setProcessing] = useState(false);

  // 处理文件上传
  const handleUpload = useCallback(async (file: File) => {
    if (!file.name.toLowerCase().endsWith('.pdf')) {
      message.error('请上传 PDF 文件');
      return false;
    }

    try {
      setLoading(true);
      const arrayBuffer = await file.arrayBuffer();

      // 复制 ArrayBuffer 以避免 detached 问题
      const bufferCopy = arrayBuffer.slice(0);

      // 验证 PDF
      const header = new Uint8Array(bufferCopy.slice(0, 5));
      const pdfHeader = String.fromCharCode(...header);
      if (!pdfHeader.startsWith('%PDF-')) {
        message.error('无效的 PDF 文件');
        return false;
      }

      setPdfData(bufferCopy);
      setFileName(file.name);

      // 获取表单字段
      const fields = await pdfApi.getFormFields(bufferCopy.slice(0));
      setFormFields(fields);

      // 初始化表单值
      const initialValues: FormValues = {};
      fields.forEach(field => {
        initialValues[field.name] = field.value;
      });
      setFormValues(initialValues);

      if (fields.length === 0) {
        message.info('此 PDF 没有可填写的表单字段');
      } else {
        message.success(`检测到 ${fields.length} 个表单字段`);
      }

      return false;
    } catch (error) {
      console.error('Failed to load PDF:', error);
      message.error('PDF 加载失败');
      return false;
    } finally {
      setLoading(false);
    }
  }, []);

  // 更新字段值
  const handleFieldChange = useCallback((fieldName: string, value: any) => {
    setFormValues(prev => ({
      ...prev,
      [fieldName]: value,
    }));
  }, []);

  // 清空所有字段
  const handleClearAll = useCallback(() => {
    const clearedValues: FormValues = {};
    formFields.forEach(field => {
      if (field.type === 'checkbox') {
        clearedValues[field.name] = false;
      } else {
        clearedValues[field.name] = '';
      }
    });
    setFormValues(clearedValues);
    message.success('已清空所有字段');
  }, [formFields]);

  // 保存填写后的 PDF
  const handleSave = useCallback(async () => {
    if (!pdfData) {
      message.warning('请先上传 PDF 文件');
      return;
    }

    try {
      setProcessing(true);
      // 复制 ArrayBuffer 以避免 detached 问题
      const filledPdf = await pdfApi.fillForm(pdfData.slice(0), formValues);

      // 下载文件
      const blob = new Blob([filledPdf], { type: 'application/pdf' });
      const url = URL.createObjectURL(blob);
      const a = document.createElement('a');
      a.href = url;
      a.download = fileName.replace('.pdf', '_filled.pdf');
      document.body.appendChild(a);
      a.click();
      document.body.removeChild(a);
      URL.revokeObjectURL(url);

      message.success('表单保存成功');
    } catch (error) {
      console.error('Failed to save form:', error);
      message.error('保存失败');
    } finally {
      setProcessing(false);
    }
  }, [pdfData, formValues, fileName]);

  // 渲染字段输入控件
  const renderFieldInput = (field: FormField) => {
    const value = formValues[field.name];

    switch (field.type) {
      case 'text':
        return (
          <Input
            value={value || ''}
            onChange={e => handleFieldChange(field.name, e.target.value)}
            placeholder={`输入 ${field.name}`}
          />
        );

      case 'checkbox':
        return (
          <Checkbox
            checked={!!value}
            onChange={e => handleFieldChange(field.name, e.target.checked)}
          >
            {field.name}
          </Checkbox>
        );

      case 'radio':
        return (
          <Select
            value={value || undefined}
            onChange={v => handleFieldChange(field.name, v)}
            placeholder="选择选项"
            style={{ width: '100%' }}
          >
            {field.options?.map(opt => (
              <Option key={opt} value={opt}>{opt}</Option>
            ))}
          </Select>
        );

      case 'dropdown':
        return (
          <Select
            value={value || undefined}
            onChange={v => handleFieldChange(field.name, v)}
            placeholder="选择选项"
            style={{ width: '100%' }}
          >
            {field.options?.map(opt => (
              <Option key={opt} value={opt}>{opt}</Option>
            ))}
          </Select>
        );

      case 'button':
        return (
          <Tag color="default">按钮字段（不可编辑）</Tag>
        );

      default:
        return (
          <Input
            value={value || ''}
            onChange={e => handleFieldChange(field.name, e.target.value)}
            placeholder={`输入 ${field.name}`}
          />
        );
    }
  };

  // 获取字段类型图标
  const getFieldTypeIcon = (type: FormField['type']) => {
    switch (type) {
      case 'text':
        return <FileTextOutlined />;
      case 'checkbox':
        return <CheckSquareOutlined />;
      case 'radio':
      case 'dropdown':
        return <FormOutlined />;
      default:
        return <FormOutlined />;
    }
  };

  // 按页面分组字段
  const fieldsByPage = formFields.reduce((acc, field) => {
    const page = field.page;
    if (!acc[page]) {
      acc[page] = [];
    }
    acc[page].push(field);
    return acc;
  }, {} as Record<number, FormField[]>);

  return (
    <div style={{ padding: 16 }}>
      <Spin spinning={loading || processing}>
        {/* 参数设置区 */}
        <Card size="small" style={{ marginBottom: 16 }}>
          <Row gutter={[16, 12]} align="middle">
            {!pdfData ? (
              <Col span={24}>
                <Dragger
                  accept=".pdf"
                  showUploadList={false}
                  beforeUpload={handleUpload}
                  style={{ padding: '12px 0' }}
                >
                  <p className="ant-upload-drag-icon" style={{ marginBottom: 8 }}>
                    <InboxOutlined style={{ fontSize: 32, color: '#1890ff' }} />
                  </p>
                  <p className="ant-upload-text" style={{ marginBottom: 4 }}>
                    点击或拖拽 PDF 文件到此处
                  </p>
                  <p className="ant-upload-hint">支持带有表单字段的 PDF 文件</p>
                </Dragger>
              </Col>
            ) : (
              <>
                <Col flex="auto">
                  <Space>
                    <Text strong>{fileName}</Text>
                    <Tag color="blue">{formFields.length} 个字段</Tag>
                  </Space>
                </Col>
                <Col>
                  <Space>
                    <Upload accept=".pdf" showUploadList={false} beforeUpload={handleUpload}>
                      <Button>更换文件</Button>
                    </Upload>
                    <Button
                      icon={<ClearOutlined />}
                      onClick={handleClearAll}
                      disabled={formFields.length === 0}
                    >
                      清空
                    </Button>
                    <Button
                      type="primary"
                      icon={<DownloadOutlined />}
                      onClick={handleSave}
                      disabled={formFields.length === 0}
                    >
                      保存
                    </Button>
                  </Space>
                </Col>
              </>
            )}
          </Row>
        </Card>

        {/* 表单字段区 */}
        {pdfData && (
          <>
            {formFields.length === 0 ? (
              <Empty
                image={Empty.PRESENTED_IMAGE_SIMPLE}
                description="此 PDF 没有可填写的表单字段"
              />
            ) : (
              <div style={{ maxHeight: 500, overflow: 'auto' }}>
                {Object.entries(fieldsByPage).map(([page, fields]) => (
                  <Card
                    key={page}
                    size="small"
                    title={`第 ${page} 页`}
                    style={{ marginBottom: 12 }}
                  >
                    <Form layout="vertical" size="small">
                      {fields.map(field => (
                        <Form.Item
                          key={field.name}
                          label={
                            <Space>
                              {getFieldTypeIcon(field.type)}
                              <span>{field.name}</span>
                              <Tag>{field.type}</Tag>
                            </Space>
                          }
                          style={{ marginBottom: 12 }}
                        >
                          {renderFieldInput(field)}
                        </Form.Item>
                      ))}
                    </Form>
                  </Card>
                ))}
              </div>
            )}

            {formFields.length > 0 && (
              <Alert
                type="info"
                showIcon
                message="提示"
                description="填写完成后点击「保存」按钮下载填写后的 PDF 文件。某些复杂表单可能无法完全支持。"
                style={{ marginTop: 16 }}
              />
            )}
          </>
        )}
      </Spin>
    </div>
  );
};

export default FormFillTool;

/**
 * SecurityTool - PDF 安全与加密工具
 * 支持设置密码保护和权限控制
 */

import React, { useState, useCallback } from 'react';
import {
  Upload,
  Button,
  Space,
  Typography,
  Card,
  Row,
  Col,
  message,
  Spin,
  Input,
  Checkbox,
  Form,
  Alert,
  Tabs,
  Divider,
} from 'antd';
import {
  InboxOutlined,
  DownloadOutlined,
  LockOutlined,
  UnlockOutlined,
  KeyOutlined,
} from '@ant-design/icons';
import { pdfApi } from '../../services/pdfApi';

const { Text, Title } = Typography;
const { Dragger } = Upload;
const { Password } = Input;

// ============ 类型定义 ============

interface SecuritySettings {
  userPassword: string;
  ownerPassword: string;
  permissions: {
    printing: boolean;
    copying: boolean;
    modifying: boolean;
  };
}

// ============ 主组件 ============

const SecurityTool: React.FC = () => {
  const [pdfData, setPdfData] = useState<ArrayBuffer | null>(null);
  const [fileName, setFileName] = useState<string>('');
  const [loading, setLoading] = useState(false);
  const [processing, setProcessing] = useState(false);
  const [activeTab, setActiveTab] = useState<'encrypt' | 'decrypt'>('encrypt');

  // 加密设置
  const [settings, setSettings] = useState<SecuritySettings>({
    userPassword: '',
    ownerPassword: '',
    permissions: {
      printing: true,
      copying: true,
      modifying: true,
    },
  });

  // 解密密码
  const [decryptPassword, setDecryptPassword] = useState('');

  // 处理文件上传
  const handleUpload = useCallback(async (file: File) => {
    if (!file.name.toLowerCase().endsWith('.pdf')) {
      message.error('请上传 PDF 文件');
      return false;
    }

    try {
      setLoading(true);
      const arrayBuffer = await file.arrayBuffer();

      // 复制 ArrayBuffer 以避免 detached 问题
      const bufferCopy = arrayBuffer.slice(0);

      // 验证 PDF
      const header = new Uint8Array(bufferCopy.slice(0, 5));
      const pdfHeader = String.fromCharCode(...header);
      if (!pdfHeader.startsWith('%PDF-')) {
        message.error('无效的 PDF 文件');
        return false;
      }

      setPdfData(bufferCopy);
      setFileName(file.name);
      message.success('PDF 加载成功');
      return false;
    } catch (error) {
      console.error('Failed to load PDF:', error);
      message.error('PDF 加载失败');
      return false;
    } finally {
      setLoading(false);
    }
  }, []);

  // 加密 PDF
  const handleEncrypt = useCallback(async () => {
    if (!pdfData) {
      message.warning('请先上传 PDF 文件');
      return;
    }

    if (!settings.userPassword && !settings.ownerPassword) {
      message.warning('请至少设置一个密码');
      return;
    }

    try {
      setProcessing(true);
      // 复制 ArrayBuffer 以避免 detached 问题
      const encryptedPdf = await pdfApi.setSecurity({
        file: pdfData.slice(0),
        userPassword: settings.userPassword || undefined,
        ownerPassword: settings.ownerPassword || undefined,
        permissions: settings.permissions,
      });

      // 下载文件
      const blob = new Blob([encryptedPdf], { type: 'application/pdf' });
      const url = URL.createObjectURL(blob);
      const a = document.createElement('a');
      a.href = url;
      a.download = fileName.replace('.pdf', '_encrypted.pdf');
      document.body.appendChild(a);
      a.click();
      document.body.removeChild(a);
      URL.revokeObjectURL(url);

      message.success('PDF 加密成功');
    } catch (error) {
      console.error('Failed to encrypt PDF:', error);
      message.error('加密失败');
    } finally {
      setProcessing(false);
    }
  }, [pdfData, settings, fileName]);

  // 解密 PDF
  const handleDecrypt = useCallback(async () => {
    if (!pdfData) {
      message.warning('请先上传 PDF 文件');
      return;
    }

    try {
      setProcessing(true);
      // 复制 ArrayBuffer 以避免 detached 问题
      const decryptedPdf = await pdfApi.removeSecurity(pdfData.slice(0), decryptPassword);

      // 下载文件
      const blob = new Blob([decryptedPdf], { type: 'application/pdf' });
      const url = URL.createObjectURL(blob);
      const a = document.createElement('a');
      a.href = url;
      a.download = fileName.replace('.pdf', '_decrypted.pdf');
      document.body.appendChild(a);
      a.click();
      document.body.removeChild(a);
      URL.revokeObjectURL(url);

      message.success('PDF 解密成功');
    } catch (error) {
      console.error('Failed to decrypt PDF:', error);
      message.error('解密失败，请检查密码是否正确');
    } finally {
      setProcessing(false);
    }
  }, [pdfData, decryptPassword, fileName]);

  // 渲染加密面板
  const renderEncryptPanel = () => (
    <Form layout="vertical" size="small">
      <Form.Item label="用户密码（打开文档时需要）">
        <Password
          value={settings.userPassword}
          onChange={e => setSettings(prev => ({ ...prev, userPassword: e.target.value }))}
          placeholder="留空则不设置用户密码"
          prefix={<KeyOutlined />}
        />
      </Form.Item>

      <Form.Item label="所有者密码（修改权限时需要）">
        <Password
          value={settings.ownerPassword}
          onChange={e => setSettings(prev => ({ ...prev, ownerPassword: e.target.value }))}
          placeholder="留空则不设置所有者密码"
          prefix={<KeyOutlined />}
        />
      </Form.Item>

      <Divider style={{ margin: '12px 0' }}>权限设置</Divider>

      <Form.Item>
        <Space direction="vertical">
          <Checkbox
            checked={settings.permissions.printing}
            onChange={e => setSettings(prev => ({
              ...prev,
              permissions: { ...prev.permissions, printing: e.target.checked },
            }))}
          >
            允许打印
          </Checkbox>
          <Checkbox
            checked={settings.permissions.copying}
            onChange={e => setSettings(prev => ({
              ...prev,
              permissions: { ...prev.permissions, copying: e.target.checked },
            }))}
          >
            允许复制内容
          </Checkbox>
          <Checkbox
            checked={settings.permissions.modifying}
            onChange={e => setSettings(prev => ({
              ...prev,
              permissions: { ...prev.permissions, modifying: e.target.checked },
            }))}
          >
            允许修改
          </Checkbox>
        </Space>
      </Form.Item>

      <Form.Item>
        <Button
          type="primary"
          icon={<LockOutlined />}
          onClick={handleEncrypt}
          disabled={!pdfData}
          block
        >
          加密并下载
        </Button>
      </Form.Item>

      <Alert
        type="warning"
        showIcon
        message="注意"
        description="pdf-lib 库对加密支持有限，某些 PDF 阅读器可能无法正确识别权限设置。建议使用专业工具进行重要文档的加密。"
      />
    </Form>
  );

  // 渲染解密面板
  const renderDecryptPanel = () => (
    <Form layout="vertical" size="small">
      <Form.Item label="输入密码">
        <Password
          value={decryptPassword}
          onChange={e => setDecryptPassword(e.target.value)}
          placeholder="输入 PDF 密码"
          prefix={<KeyOutlined />}
        />
      </Form.Item>

      <Form.Item>
        <Button
          type="primary"
          icon={<UnlockOutlined />}
          onClick={handleDecrypt}
          disabled={!pdfData}
          block
        >
          解密并下载
        </Button>
      </Form.Item>

      <Alert
        type="info"
        showIcon
        message="提示"
        description="如果 PDF 设置了用户密码，需要输入正确的密码才能解密。如果只设置了所有者密码，可能可以直接打开但无法修改。"
      />
    </Form>
  );

  const tabItems = [
    {
      key: 'encrypt',
      label: (
        <span>
          <LockOutlined />
          加密
        </span>
      ),
      children: renderEncryptPanel(),
    },
    {
      key: 'decrypt',
      label: (
        <span>
          <UnlockOutlined />
          解密
        </span>
      ),
      children: renderDecryptPanel(),
    },
  ];

  return (
    <div style={{ padding: 16 }}>
      <Spin spinning={loading || processing}>
        {/* 文件上传区 */}
        <Card size="small" style={{ marginBottom: 16 }}>
          <Row gutter={[16, 12]} align="middle">
            {!pdfData ? (
              <Col span={24}>
                <Dragger
                  accept=".pdf"
                  showUploadList={false}
                  beforeUpload={handleUpload}
                  style={{ padding: '12px 0' }}
                >
                  <p className="ant-upload-drag-icon" style={{ marginBottom: 8 }}>
                    <InboxOutlined style={{ fontSize: 32, color: '#1890ff' }} />
                  </p>
                  <p className="ant-upload-text" style={{ marginBottom: 4 }}>
                    点击或拖拽 PDF 文件到此处
                  </p>
                  <p className="ant-upload-hint">支持加密或解密 PDF 文件</p>
                </Dragger>
              </Col>
            ) : (
              <>
                <Col flex="auto">
                  <Text strong>{fileName}</Text>
                </Col>
                <Col>
                  <Upload accept=".pdf" showUploadList={false} beforeUpload={handleUpload}>
                    <Button>更换文件</Button>
                  </Upload>
                </Col>
              </>
            )}
          </Row>
        </Card>

        {/* 加密/解密选项 */}
        {pdfData && (
          <Card size="small">
            <Tabs
              activeKey={activeTab}
              onChange={key => setActiveTab(key as 'encrypt' | 'decrypt')}
              items={tabItems}
            />
          </Card>
        )}
      </Spin>
    </div>
  );
};

export default SecurityTool;

/**
 * ImageToPdfTool - 图片转 PDF 工具
 * 支持多图上传、拖拽排序、页面尺寸和放置方式选择
 */

import React, { useState, useCallback, useMemo } from 'react';
import {
  Upload,
  Button,
  Space,
  Typography,
  Card,
  Row,
  Col,
  message,
  Spin,
  Select,
  Image,
  Empty,
  Popconfirm,
} from 'antd';
import {
  InboxOutlined,
  DownloadOutlined,
  DeleteOutlined,
  ClearOutlined,
  PictureOutlined,
  HolderOutlined,
} from '@ant-design/icons';
import { pdfApi } from '../../services/pdfApi';

const { Text } = Typography;
const { Dragger } = Upload;
const { Option } = Select;

// ============ 类型定义 ============

interface ImageItem {
  id: string;
  file: File;
  preview: string;
  name: string;
}

type PageSize = 'fit' | 'a4' | 'letter';
type Placement = 'center' | 'stretch' | 'fit';

// ============ 主组件 ============

const ImageToPdfTool: React.FC = () => {
  const [images, setImages] = useState<ImageItem[]>([]);
  const [pageSize, setPageSize] = useState<PageSize>('a4');
  const [placement, setPlacement] = useState<Placement>('fit');
  const [processing, setProcessing] = useState(false);
  const [draggedIndex, setDraggedIndex] = useState<number | null>(null);

  // 处理图片上传
  const handleUpload = useCallback((file: File) => {
    const validTypes = ['image/jpeg', 'image/png', 'image/jpg'];
    if (!validTypes.includes(file.type)) {
      message.error('仅支持 JPG/PNG 格式图片');
      return false;
    }

    const preview = URL.createObjectURL(file);
    const newItem: ImageItem = {
      id: `${Date.now()}_${Math.random().toString(36).substr(2, 9)}`,
      file,
      preview,
      name: file.name,
    };

    setImages(prev => [...prev, newItem]);
    return false;
  }, []);

  // 删除图片
  const handleDelete = useCallback((id: string) => {
    setImages(prev => {
      const item = prev.find(img => img.id === id);
      if (item) {
        URL.revokeObjectURL(item.preview);
      }
      return prev.filter(img => img.id !== id);
    });
  }, []);

  // 清空所有图片
  const handleClearAll = useCallback(() => {
    images.forEach(img => URL.revokeObjectURL(img.preview));
    setImages([]);
  }, [images]);

  // 拖拽开始
  const handleDragStart = useCallback((index: number) => {
    setDraggedIndex(index);
  }, []);

  // 拖拽结束
  const handleDragEnd = useCallback(() => {
    setDraggedIndex(null);
  }, []);

  // 拖拽放置
  const handleDrop = useCallback((targetIndex: number) => {
    if (draggedIndex === null || draggedIndex === targetIndex) return;

    setImages(prev => {
      const newImages = [...prev];
      const [draggedItem] = newImages.splice(draggedIndex, 1);
      newImages.splice(targetIndex, 0, draggedItem);
      return newImages;
    });
    setDraggedIndex(null);
  }, [draggedIndex]);

  // 转换为 PDF
  const handleConvert = useCallback(async () => {
    if (images.length === 0) {
      message.warning('请先添加图片');
      return;
    }

    try {
      setProcessing(true);

      // 读取所有图片数据并复制 ArrayBuffer 以避免 detached 问题
      const imageBuffers = await Promise.all(
        images.map(async img => {
          const arrayBuffer = await img.file.arrayBuffer();
          return arrayBuffer.slice(0);
        })
      );

      // 调用 API 转换
      const pdfBuffer = await pdfApi.imagesToPdf({
        images: imageBuffers,
        pageSize,
        placement,
      });

      // 下载 PDF
      const blob = new Blob([pdfBuffer], { type: 'application/pdf' });
      const url = URL.createObjectURL(blob);
      const a = document.createElement('a');
      a.href = url;
      a.download = 'images_to_pdf.pdf';
      document.body.appendChild(a);
      a.click();
      document.body.removeChild(a);
      URL.revokeObjectURL(url);

      message.success('PDF 生成成功');
    } catch (error) {
      console.error('Failed to convert images to PDF:', error);
      message.error('转换失败');
    } finally {
      setProcessing(false);
    }
  }, [images, pageSize, placement]);

  return (
    <div style={{ padding: 16 }}>
      <Spin spinning={processing}>
        {/* 参数设置区 */}
        <Card size="small" style={{ marginBottom: 16 }}>
          <Row gutter={[16, 12]} align="middle">
            <Col span={24}>
              <Dragger
                accept=".jpg,.jpeg,.png"
                multiple
                showUploadList={false}
                beforeUpload={handleUpload}
                style={{ padding: '12px 0' }}
              >
                <p className="ant-upload-drag-icon" style={{ marginBottom: 8 }}>
                  <InboxOutlined style={{ fontSize: 32, color: '#1890ff' }} />
                </p>
                <p className="ant-upload-text" style={{ marginBottom: 4 }}>
                  点击或拖拽图片到此处
                </p>
                <p className="ant-upload-hint">支持 JPG/PNG 格式，可多选</p>
              </Dragger>
            </Col>

            <Col xs={12} sm={6}>
              <Text type="secondary" style={{ fontSize: 12 }}>页面尺寸</Text>
              <Select
                value={pageSize}
                onChange={setPageSize}
                style={{ width: '100%' }}
                size="small"
              >
                <Option value="fit">适应图片</Option>
                <Option value="a4">A4</Option>
                <Option value="letter">Letter</Option>
              </Select>
            </Col>

            <Col xs={12} sm={6}>
              <Text type="secondary" style={{ fontSize: 12 }}>放置方式</Text>
              <Select
                value={placement}
                onChange={setPlacement}
                style={{ width: '100%' }}
                size="small"
                disabled={pageSize === 'fit'}
              >
                <Option value="fit">保持比例</Option>
                <Option value="center">居中</Option>
                <Option value="stretch">拉伸填充</Option>
              </Select>
            </Col>

            <Col xs={24} sm={12}>
              <Space style={{ width: '100%', justifyContent: 'flex-end' }}>
                <Popconfirm
                  title="确定清空所有图片？"
                  onConfirm={handleClearAll}
                  disabled={images.length === 0}
                >
                  <Button
                    icon={<ClearOutlined />}
                    disabled={images.length === 0}
                  >
                    清空
                  </Button>
                </Popconfirm>
                <Button
                  type="primary"
                  icon={<DownloadOutlined />}
                  onClick={handleConvert}
                  disabled={images.length === 0}
                >
                  生成 PDF ({images.length})
                </Button>
              </Space>
            </Col>
          </Row>
        </Card>

        {/* 图片列表 */}
        {images.length > 0 ? (
          <div
            style={{
              display: 'grid',
              gridTemplateColumns: 'repeat(auto-fill, minmax(120px, 1fr))',
              gap: 12,
              maxHeight: 400,
              overflow: 'auto',
              padding: 4,
            }}
          >
            {images.map((img, index) => (
              <div
                key={img.id}
                draggable
                onDragStart={() => handleDragStart(index)}
                onDragEnd={handleDragEnd}
                onDragOver={e => e.preventDefault()}
                onDrop={() => handleDrop(index)}
                style={{
                  position: 'relative',
                  border: draggedIndex === index ? '2px dashed #1890ff' : '1px solid #d9d9d9',
                  borderRadius: 4,
                  padding: 4,
                  background: '#fff',
                  cursor: 'grab',
                  opacity: draggedIndex === index ? 0.5 : 1,
                }}
              >
                <div
                  style={{
                    position: 'absolute',
                    top: 4,
                    left: 4,
                    background: 'rgba(0,0,0,0.5)',
                    color: '#fff',
                    padding: '2px 6px',
                    borderRadius: 4,
                    fontSize: 12,
                    zIndex: 1,
                  }}
                >
                  {index + 1}
                </div>
                <div
                  style={{
                    position: 'absolute',
                    top: 4,
                    right: 4,
                    zIndex: 1,
                  }}
                >
                  <Button
                    type="text"
                    size="small"
                    danger
                    icon={<DeleteOutlined />}
                    onClick={e => {
                      e.stopPropagation();
                      handleDelete(img.id);
                    }}
                    style={{ background: 'rgba(255,255,255,0.8)' }}
                  />
                </div>
                <Image
                  src={img.preview}
                  alt={img.name}
                  style={{
                    width: '100%',
                    height: 100,
                    objectFit: 'cover',
                    borderRadius: 2,
                  }}
                  preview={false}
                />
                <div
                  style={{
                    fontSize: 11,
                    color: '#666',
                    overflow: 'hidden',
                    textOverflow: 'ellipsis',
                    whiteSpace: 'nowrap',
                    marginTop: 4,
                    textAlign: 'center',
                  }}
                  title={img.name}
                >
                  {img.name}
                </div>
                <div
                  style={{
                    position: 'absolute',
                    bottom: 24,
                    left: '50%',
                    transform: 'translateX(-50%)',
                    color: '#999',
                  }}
                >
                  <HolderOutlined />
                </div>
              </div>
            ))}
          </div>
        ) : (
          <Empty
            image={<PictureOutlined style={{ fontSize: 48, color: '#d9d9d9' }} />}
            description="请上传图片"
          />
        )}

        {images.length > 1 && (
          <Text type="secondary" style={{ display: 'block', marginTop: 12, textAlign: 'center' }}>
            拖拽图片可调整顺序
          </Text>
        )}
      </Spin>
    </div>
  );
};

export default ImageToPdfTool;

/**
 * ConvertTool - PDF 转换工具组件
 * 提供多种 PDF 转换功能：灰度转换、PDF/A 转换、修复、版本转换、线性化
 * 需要 Ghostscript 支持
 */

import React, { useState, useCallback, useEffect } from 'react';
import { Card, Row, Col, Typography, Upload, Button, Space, message, Radio, Statistic, Alert, Tag, Tabs, Tooltip } from 'antd';
import { 
  UploadOutlined, InboxOutlined, DownloadOutlined, CheckCircleOutlined, WarningOutlined,
  BgColorsOutlined, SafetyCertificateOutlined, ToolOutlined, SwapOutlined, GlobalOutlined
} from '@ant-design/icons';
import { pdfApi, ConvertResult } from '../../services/pdfApi';
import { formatFileSize, validatePdfHeader, downloadFile } from './utils';

const { Text, Title } = Typography;
const { Dragger } = Upload;

// ============ 类型定义 ============

interface PDFFile {
  name: string;
  data: ArrayBuffer;
  size: number;
}

interface GhostscriptStatus {
  available: boolean;
  path: string | null;
  version?: string | null;
}

type ConvertType = 'grayscale' | 'pdfa' | 'repair' | 'version' | 'linearize';
type PDFALevel = '1b' | '2b' | '3b';
type PDFVersion = '1.4' | '1.5' | '1.6' | '1.7' | '2.0';

// ============ ConvertTool 组件 ============

const ConvertTool: React.FC = () => {
  const [pdfFile, setPdfFile] = useState<PDFFile | null>(null);
  const [convertType, setConvertType] = useState<ConvertType>('grayscale');
  const [pdfaLevel, setPdfaLevel] = useState<PDFALevel>('2b');
  const [pdfVersion, setPdfVersion] = useState<PDFVersion>('1.4');
  const [processing, setProcessing] = useState(false);
  const [result, setResult] = useState<ConvertResult | null>(null);
  const [gsStatus, setGsStatus] = useState<GhostscriptStatus | null>(null);
  const [checkingGs, setCheckingGs] = useState(true);

  // 检查 Ghostscript 可用性
  useEffect(() => {
    const checkGs = async () => {
      try {
        const status = await pdfApi.checkGhostscript();
        setGsStatus(status);
      } catch (error) {
        console.error('Failed to check Ghostscript:', error);
        setGsStatus({ available: false, path: null });
      } finally {
        setCheckingGs(false);
      }
    };
    checkGs();
  }, []);


  // 文件上传处理
  const handleFileUpload = useCallback(async (file: File): Promise<boolean> => {
    if (!file.name.toLowerCase().endsWith('.pdf')) {
      message.error('请上传 PDF 文件');
      return false;
    }

    try {
      const arrayBuffer = await file.arrayBuffer();
      const bufferCopy = arrayBuffer.slice(0);

      if (!validatePdfHeader(bufferCopy)) {
        message.error('无效的 PDF 文件');
        return false;
      }

      setPdfFile({
        name: file.name,
        data: bufferCopy,
        size: file.size,
      });
      setResult(null);

      message.success(`已加载: ${file.name} (${formatFileSize(file.size)})`);
      return true;
    } catch (error) {
      console.error('Failed to load PDF:', error);
      message.error('PDF 加载失败');
      return false;
    }
  }, []);

  // 执行转换
  const handleConvert = useCallback(async () => {
    if (!pdfFile) {
      message.warning('请先上传 PDF 文件');
      return;
    }

    if (!gsStatus?.available) {
      message.error('Ghostscript 不可用，无法执行转换');
      return;
    }

    setProcessing(true);
    setResult(null);

    try {
      let convertResult: ConvertResult;

      switch (convertType) {
        case 'grayscale':
          convertResult = await pdfApi.toGrayscale(pdfFile.data.slice(0));
          break;
        case 'pdfa':
          convertResult = await pdfApi.toPDFA({ file: pdfFile.data.slice(0), level: pdfaLevel });
          break;
        case 'repair':
          convertResult = await pdfApi.repair(pdfFile.data.slice(0));
          break;
        case 'version':
          convertResult = await pdfApi.convertVersion({ file: pdfFile.data.slice(0), version: pdfVersion });
          break;
        case 'linearize':
          convertResult = await pdfApi.linearize(pdfFile.data.slice(0));
          break;
        default:
          throw new Error('未知的转换类型');
      }

      setResult(convertResult);
      message.success('转换完成');
    } catch (error) {
      console.error('Convert failed:', error);
      message.error('转换失败: ' + (error as Error).message);
    } finally {
      setProcessing(false);
    }
  }, [pdfFile, convertType, pdfaLevel, pdfVersion, gsStatus]);

  // 下载转换后的文件
  const handleDownload = useCallback(() => {
    if (!result || !pdfFile) return;

    const suffixMap: Record<ConvertType, string> = {
      grayscale: '_grayscale',
      pdfa: `_pdfa${pdfaLevel}`,
      repair: '_repaired',
      version: `_v${pdfVersion}`,
      linearize: '_web',
    };

    downloadFile(result.data, pdfFile.name.replace('.pdf', `${suffixMap[convertType]}.pdf`));
  }, [result, pdfFile, convertType, pdfaLevel, pdfVersion]);

  // Ghostscript 不可用时显示提示
  if (!checkingGs && !gsStatus?.available) {
    return (
      <div style={{ padding: 24 }}>
        <Alert
          message="Ghostscript 未安装"
          description="PDF 转换功能需要 Ghostscript 支持。请安装 Ghostscript 后重试。"
          type="error"
          showIcon
        />
      </div>
    );
  }

  // 未上传文件时显示上传区域
  if (!pdfFile) {
    return (
      <div style={{ padding: 24 }}>
        {!checkingGs && gsStatus?.available && (
          <Alert
            message="Ghostscript 已就绪"
            description={`版本: ${gsStatus.version || '未知'}`}
            type="success"
            showIcon
            icon={<CheckCircleOutlined />}
            style={{ marginBottom: 16 }}
          />
        )}

        <Dragger
          accept=".pdf"
          showUploadList={false}
          beforeUpload={handleFileUpload}
          style={{ padding: 40 }}
        >
          <p className="ant-upload-drag-icon">
            <InboxOutlined style={{ fontSize: 48, color: '#1890ff' }} />
          </p>
          <p className="ant-upload-text">点击或拖拽 PDF 文件到此处</p>
          <p className="ant-upload-hint">支持灰度转换、PDF/A 转换、修复、版本转换、Web 优化</p>
        </Dragger>
      </div>
    );
  }


  // 转换类型配置
  const convertTypes = [
    { key: 'grayscale', label: '灰度转换', icon: <BgColorsOutlined />, desc: '将彩色 PDF 转为灰度，减小文件大小' },
    { key: 'pdfa', label: 'PDF/A', icon: <SafetyCertificateOutlined />, desc: '转换为符合存档标准的 PDF/A 格式' },
    { key: 'repair', label: '修复', icon: <ToolOutlined />, desc: '尝试修复损坏的 PDF 文件' },
    { key: 'version', label: '版本转换', icon: <SwapOutlined />, desc: '转换 PDF 版本以提高兼容性' },
    { key: 'linearize', label: 'Web 优化', icon: <GlobalOutlined />, desc: '优化 PDF 以便在 Web 上快速查看' },
  ];

  return (
    <div>
      {/* 上方：参数设置区 */}
      <Card size="small" style={{ marginBottom: 12 }}>
        <Row gutter={16} align="middle">
          <Col span={6}>
            <Space>
              <Upload accept=".pdf" showUploadList={false} beforeUpload={handleFileUpload}>
                <Button icon={<UploadOutlined />} size="small">更换文件</Button>
              </Upload>
              <Text ellipsis style={{ maxWidth: 120 }}>{pdfFile.name}</Text>
              <Text type="secondary">({formatFileSize(pdfFile.size)})</Text>
            </Space>
          </Col>
          <Col span={12}>
            <Tabs
              activeKey={convertType}
              onChange={(key) => { setConvertType(key as ConvertType); setResult(null); }}
              size="small"
              items={convertTypes.map(t => ({
                key: t.key,
                label: (
                  <Tooltip title={t.desc}>
                    <Space size={4}>{t.icon}{t.label}</Space>
                  </Tooltip>
                ),
              }))}
            />
          </Col>
          <Col span={6} style={{ textAlign: 'right' }}>
            <Button
              type="primary"
              onClick={handleConvert}
              loading={processing}
            >
              转换
            </Button>
          </Col>
        </Row>

        {/* 额外参数 */}
        {convertType === 'pdfa' && (
          <Row style={{ marginTop: 12 }}>
            <Col span={24}>
              <Space>
                <Text type="secondary">PDF/A 级别：</Text>
                <Radio.Group value={pdfaLevel} onChange={(e) => setPdfaLevel(e.target.value)} size="small">
                  <Radio.Button value="1b">PDF/A-1b</Radio.Button>
                  <Radio.Button value="2b">PDF/A-2b</Radio.Button>
                  <Radio.Button value="3b">PDF/A-3b</Radio.Button>
                </Radio.Group>
                <Text type="secondary" style={{ fontSize: 12 }}>
                  {pdfaLevel === '1b' ? '基础存档格式' : pdfaLevel === '2b' ? '支持透明度和图层' : '支持嵌入任意文件'}
                </Text>
              </Space>
            </Col>
          </Row>
        )}

        {convertType === 'version' && (
          <Row style={{ marginTop: 12 }}>
            <Col span={24}>
              <Space>
                <Text type="secondary">目标版本：</Text>
                <Radio.Group value={pdfVersion} onChange={(e) => setPdfVersion(e.target.value)} size="small">
                  <Radio.Button value="1.4">1.4</Radio.Button>
                  <Radio.Button value="1.5">1.5</Radio.Button>
                  <Radio.Button value="1.6">1.6</Radio.Button>
                  <Radio.Button value="1.7">1.7</Radio.Button>
                  <Radio.Button value="2.0">2.0</Radio.Button>
                </Radio.Group>
                <Text type="secondary" style={{ fontSize: 12 }}>
                  {pdfVersion === '1.4' ? '最广泛兼容' : pdfVersion === '2.0' ? '最新标准' : ''}
                </Text>
              </Space>
            </Col>
          </Row>
        )}
      </Card>

      {/* 下方：转换结果展示 */}
      <Card size="small" title="转换结果">
        {!result ? (
          <div style={{ textAlign: 'center', padding: 60, color: '#999' }}>
            {processing ? (
              <Text>正在转换...</Text>
            ) : (
              <Text>选择转换类型后点击"转换"按钮</Text>
            )}
          </div>
        ) : (
          <div>
            <Row gutter={24} style={{ marginBottom: 24 }}>
              <Col span={8}>
                <Statistic title="原始大小" value={formatFileSize(result.originalSize)} />
              </Col>
              <Col span={8}>
                <Statistic title="转换后大小" value={formatFileSize(result.convertedSize)} />
              </Col>
              <Col span={8}>
                <Statistic 
                  title="大小变化" 
                  value={((result.convertedSize - result.originalSize) / result.originalSize * 100).toFixed(1)} 
                  suffix="%" 
                  valueStyle={{ color: result.convertedSize <= result.originalSize ? '#3f8600' : '#cf1322' }}
                  prefix={result.convertedSize <= result.originalSize ? '↓' : '↑'}
                />
              </Col>
            </Row>

            <Button 
              type="primary" 
              icon={<DownloadOutlined />} 
              onClick={handleDownload}
              size="large"
            >
              下载转换后的 PDF
            </Button>
          </div>
        )}
      </Card>
    </div>
  );
};

export default ConvertTool;

/**
 * DeletePagesTool - PDF 页面删除工具组件
 * 采用上下布局：上方为参数设置区，下方为页面缩略图网格
 */

import React, { useState, useCallback } from 'react';
import { 
  Card, Row, Col, Typography, Upload, Button, Space, message, 
  Input, Popconfirm, Spin, Alert
} from 'antd';
import { 
  UploadOutlined, InboxOutlined, DownloadOutlined, 
  DeleteOutlined, UndoOutlined, WarningOutlined
} from '@ant-design/icons';
import { pdfApi } from '../../services/pdfApi';
import PDFThumbnails from './PDFThumbnails';
import { parsePageRanges } from './utils';

const { Text } = Typography;
const { Dragger } = Upload;

// ============ 类型定义 ============

interface PDFFile {
  name: string;
  data: ArrayBuffer;
  size: number;
}

// ============ DeletePagesTool 组件 ============

const DeletePagesTool: React.FC = () => {
  const [pdfFile, setPdfFile] = useState<PDFFile | null>(null);
  const [totalPages, setTotalPages] = useState(0);
  const [selectedPages, setSelectedPages] = useState<number[]>([]);
  const [pageRangeInput, setPageRangeInput] = useState('');
  const [processing, setProcessing] = useState(false);
  const [resultData, setResultData] = useState<ArrayBuffer | null>(null);
  const [previewKey, setPreviewKey] = useState(0);

  // PDF 文件上传处理
  const handlePdfUpload = useCallback(async (file: File): Promise<boolean> => {
    if (!file.name.toLowerCase().endsWith('.pdf')) {
      message.error('请上传 PDF 文件');
      return false;
    }

    try {
      const arrayBuffer = await file.arrayBuffer();

      // 复制 ArrayBuffer 以避免 detached 问题
      const bufferCopy = arrayBuffer.slice(0);

      const header = new Uint8Array(bufferCopy.slice(0, 5));
      const pdfHeader = String.fromCharCode(...header);
      if (!pdfHeader.startsWith('%PDF-')) {
        message.error('无效的 PDF 文件');
        return false;
      }

      // 获取 PDF 信息
      const info = await pdfApi.getInfo(bufferCopy.slice(0));

      setPdfFile({
        name: file.name,
        data: bufferCopy,
        size: file.size,
      });
      setTotalPages(info.pageCount);
      setSelectedPages([]);
      setPageRangeInput('');
      setResultData(null);
      setPreviewKey(prev => prev + 1);

      message.success(`已加载: ${file.name} (${info.pageCount} 页)`);
      return true;
    } catch (error) {
      console.error('Failed to load PDF:', error);
      message.error('PDF 加载失败');
      return false;
    }
  }, []);

  // 处理页面选择（点击缩略图）
  const handlePageSelect = useCallback((pages: number[]) => {
    setSelectedPages(pages);
    setPageRangeInput(pages.join(', '));
  }, []);

  // 处理单个页面删除（点击缩略图上的删除按钮）
  const handleSinglePageDelete = useCallback(async (page: number) => {
    if (!pdfFile) return;

    // 检查是否会删除所有页面
    if (totalPages <= 1) {
      message.error('不能删除所有页面，PDF 文件必须至少保留一页');
      return;
    }

    setProcessing(true);

    try {
      const sourceData = resultData || pdfFile.data;
      // 复制 ArrayBuffer 以避免 detached 问题
      const result = await pdfApi.deletePages({
        file: sourceData.slice(0),
        pages: [page],
      });

      // 更新状态
      const newTotalPages = totalPages - 1;
      setResultData(result);
      setTotalPages(newTotalPages);
      // 从选中列表中移除已删除的页面，并调整页码
      setSelectedPages(prev => prev.filter(p => p !== page).map(p => p > page ? p - 1 : p));
      setPageRangeInput('');
      setPreviewKey(prev => prev + 1);

      message.success(`已删除第 ${page} 页，剩余 ${newTotalPages} 页`);
    } catch (error) {
      console.error('Delete page failed:', error);
      message.error('删除失败: ' + (error as Error).message);
    } finally {
      setProcessing(false);
    }
  }, [pdfFile, totalPages, resultData]);

  // 处理页面范围输入变化
  const handlePageRangeChange = useCallback((value: string) => {
    setPageRangeInput(value);
    const pages = parsePageRanges(value, totalPages);
    setSelectedPages(pages);
  }, [totalPages]);

  // 执行删除
  const handleDelete = useCallback(async () => {
    if (!pdfFile) {
      message.warning('请先上传 PDF 文件');
      return;
    }

    if (selectedPages.length === 0) {
      message.warning('请选择要删除的页面');
      return;
    }

    if (selectedPages.length >= totalPages) {
      message.error('不能删除所有页面');
      return;
    }

    setProcessing(true);

    try {
      const sourceData = resultData || pdfFile.data;
      // 复制 ArrayBuffer 以避免 detached 问题
      const result = await pdfApi.deletePages({
        file: sourceData.slice(0),
        pages: selectedPages,
      });

      // 更新状态
      const newTotalPages = totalPages - selectedPages.length;
      setResultData(result);
      setTotalPages(newTotalPages);
      setSelectedPages([]);
      setPageRangeInput('');
      setPreviewKey(prev => prev + 1);

      message.success(`已删除 ${selectedPages.length} 页，剩余 ${newTotalPages} 页`);
    } catch (error) {
      console.error('Delete failed:', error);
      message.error('删除失败: ' + (error as Error).message);
    } finally {
      setProcessing(false);
    }
  }, [pdfFile, selectedPages, totalPages, resultData]);

  // 重置
  const handleReset = useCallback(async () => {
    if (pdfFile) {
      // 复制 ArrayBuffer 以避免 detached 问题
      const info = await pdfApi.getInfo(pdfFile.data.slice(0));
      setResultData(null);
      setTotalPages(info.pageCount);
      setSelectedPages([]);
      setPageRangeInput('');
      setPreviewKey(prev => prev + 1);
      message.info('已重置为原始状态');
    }
  }, [pdfFile]);

  // 下载结果
  const handleDownload = useCallback(() => {
    const dataToDownload = resultData || pdfFile?.data;
    if (!dataToDownload || !pdfFile) return;

    const blob = new Blob([dataToDownload], { type: 'application/pdf' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = pdfFile.name.replace('.pdf', '_deleted.pdf');
    document.body.appendChild(a);
    a.click();
    document.body.removeChild(a);
    URL.revokeObjectURL(url);
  }, [resultData, pdfFile]);

  // 检查是否会删除所有页面
  const willDeleteAll = selectedPages.length >= totalPages;

  // 未上传文件时显示上传区域
  if (!pdfFile) {
    return (
      <div style={{ padding: 24 }}>
        <Dragger
          accept=".pdf"
          showUploadList={false}
          beforeUpload={handlePdfUpload}
          style={{ padding: 40 }}
        >
          <p className="ant-upload-drag-icon">
            <InboxOutlined style={{ fontSize: 48, color: '#1890ff' }} />
          </p>
          <p className="ant-upload-text">点击或拖拽 PDF 文件到此处</p>
          <p className="ant-upload-hint">选择并删除 PDF 中的指定页面</p>
        </Dragger>
      </div>
    );
  }

  return (
    <div>
      {/* 上方：参数设置区 */}
      <Card size="small" style={{ marginBottom: 12 }}>
        <Row gutter={16} align="middle">
          <Col span={5}>
            <Space>
              <Upload accept=".pdf" showUploadList={false} beforeUpload={handlePdfUpload}>
                <Button icon={<UploadOutlined />} size="small">更换文件</Button>
              </Upload>
              <Text ellipsis style={{ maxWidth: 100 }}>{pdfFile.name}</Text>
            </Space>
          </Col>
          <Col span={6}>
            <Text type="secondary">页面范围：</Text>
            <Input
              value={pageRangeInput}
              onChange={(e) => handlePageRangeChange(e.target.value)}
              placeholder="如: 1,3,5-7"
              size="small"
              style={{ width: 120 }}
            />
          </Col>
          <Col span={5}>
            <Text type="secondary">
              已选择 {selectedPages.length}/{totalPages} 页
            </Text>
          </Col>
          <Col span={8} style={{ textAlign: 'right' }}>
            <Space>
              {resultData && (
                <Button 
                  icon={<UndoOutlined />} 
                  onClick={handleReset}
                >
                  重置
                </Button>
              )}
              <Popconfirm
                title="确认删除"
                description={`确定要删除选中的 ${selectedPages.length} 页吗？此操作不可撤销。`}
                onConfirm={handleDelete}
                okText="删除"
                cancelText="取消"
                okButtonProps={{ danger: true }}
                disabled={selectedPages.length === 0 || willDeleteAll}
              >
                <Button 
                  danger
                  icon={<DeleteOutlined />} 
                  loading={processing}
                  disabled={selectedPages.length === 0 || willDeleteAll}
                >
                  删除选中页
                </Button>
              </Popconfirm>
              <Button 
                icon={<DownloadOutlined />} 
                onClick={handleDownload}
                disabled={!pdfFile}
              >
                下载
              </Button>
            </Space>
          </Col>
        </Row>

        {willDeleteAll && selectedPages.length > 0 && (
          <Alert
            message="不能删除所有页面"
            description="PDF 文件必须至少保留一页"
            type="warning"
            showIcon
            icon={<WarningOutlined />}
            style={{ marginTop: 12 }}
          />
        )}
      </Card>

      {/* 下方：页面缩略图网格 */}
      <Card 
        size="small" 
        title={`页面缩略图 ${resultData ? '（已修改）' : ''}`}
        extra={
          <Text type="secondary">
            点击选择要删除的页面
          </Text>
        }
        style={{ height: 'calc(100vh - 300px)' }}
        styles={{ body: { height: 'calc(100% - 40px)', overflow: 'auto', padding: 12 } }}
      >
        <Spin spinning={processing}>
          <PDFThumbnails
            key={previewKey}
            pdfData={resultData || pdfFile.data}
            selectedPages={selectedPages}
            onPageSelect={handlePageSelect}
            multiSelect={true}
            showDeleteButton={true}
            onPageDelete={handleSinglePageDelete}
          />
        </Spin>
      </Card>
    </div>
  );
};

export default DeletePagesTool;

/**
 * RotateTool - PDF 旋转调整工具组件
 * 采用上下布局：上方为参数设置区，下方为页面缩略图网格
 * 支持单个页面直接旋转操作
 */

import React, { useState, useCallback, useEffect } from 'react';
import { 
  Card, Row, Col, Typography, Upload, Button, Space, message, 
  Checkbox, Spin
} from 'antd';
import { 
  UploadOutlined, InboxOutlined, DownloadOutlined, 
  RotateLeftOutlined, RotateRightOutlined, UndoOutlined
} from '@ant-design/icons';
import { pdfApi } from '../../services/pdfApi';
import PDFThumbnails from './PDFThumbnails';

const { Text } = Typography;
const { Dragger } = Upload;

// ============ 类型定义 ============

interface PDFFile {
  name: string;
  data: ArrayBuffer;
  size: number;
}

type RotationAngle = 90 | -90 | 180;
type RotationType = 'cw' | 'ccw' | 'flip-h' | 'flip-v';

// ============ RotateTool 组件 ============

const RotateTool: React.FC = () => {
  const [pdfFile, setPdfFile] = useState<PDFFile | null>(null);
  const [totalPages, setTotalPages] = useState(0);
  const [selectedPages, setSelectedPages] = useState<number[]>([]);
  const [processing, setProcessing] = useState(false);
  const [resultData, setResultData] = useState<ArrayBuffer | null>(null);
  const [selectAll, setSelectAll] = useState(true);
  const [previewKey, setPreviewKey] = useState(0);

  // PDF 文件上传处理
  const handlePdfUpload = useCallback(async (file: File): Promise<boolean> => {
    if (!file.name.toLowerCase().endsWith('.pdf')) {
      message.error('请上传 PDF 文件');
      return false;
    }

    try {
      const arrayBuffer = await file.arrayBuffer();

      // 复制 ArrayBuffer 以避免 detached 问题
      const bufferCopy = arrayBuffer.slice(0);

      const header = new Uint8Array(bufferCopy.slice(0, 5));
      const pdfHeader = String.fromCharCode(...header);
      if (!pdfHeader.startsWith('%PDF-')) {
        message.error('无效的 PDF 文件');
        return false;
      }

      // 获取 PDF 信息
      const info = await pdfApi.getInfo(bufferCopy.slice(0));

      setPdfFile({
        name: file.name,
        data: bufferCopy,
        size: file.size,
      });
      setTotalPages(info.pageCount);
      setResultData(null);
      setSelectedPages([]);
      setSelectAll(true);
      setPreviewKey(prev => prev + 1);

      message.success(`已加载: ${file.name} (${info.pageCount} 页)`);
      return true;
    } catch (error) {
      console.error('Failed to load PDF:', error);
      message.error('PDF 加载失败');
      return false;
    }
  }, []);

  // 当总页数变化时，如果选择全部，更新选中页面
  useEffect(() => {
    if (selectAll && totalPages > 0) {
      setSelectedPages(Array.from({ length: totalPages }, (_, i) => i + 1));
    }
  }, [selectAll, totalPages]);

  // 处理页面选择
  const handlePageSelect = useCallback((pages: number[]) => {
    setSelectedPages(pages);
    setSelectAll(pages.length === totalPages);
  }, [totalPages]);

  // 处理全选切换
  const handleSelectAllChange = useCallback((checked: boolean) => {
    setSelectAll(checked);
    if (checked) {
      setSelectedPages(Array.from({ length: totalPages }, (_, i) => i + 1));
    } else {
      setSelectedPages([]);
    }
  }, [totalPages]);

  // 执行旋转
  const handleRotate = useCallback(async (angle: RotationAngle) => {
    if (!pdfFile) {
      message.warning('请先上传 PDF 文件');
      return;
    }

    if (selectedPages.length === 0) {
      message.warning('请选择要旋转的页面');
      return;
    }

    setProcessing(true);

    try {
      const sourceData = resultData || pdfFile.data;
      // 复制 ArrayBuffer 以避免 detached 问题
      const result = await pdfApi.rotate({
        file: sourceData.slice(0),
        pages: selectedPages,
        angle,
      });

      setResultData(result);
      // 不再更新 previewKey，避免所有缩略图闪烁
      // setPreviewKey(prev => prev + 1);

      const angleText = angle === 90 ? '顺时针 90°' : angle === -90 ? '逆时针 90°' : '180°';
      message.success(`已旋转 ${selectedPages.length} 页 (${angleText})`);
    } catch (error) {
      console.error('Rotate failed:', error);
      message.error('旋转失败: ' + (error as Error).message);
    } finally {
      setProcessing(false);
    }
  }, [pdfFile, selectedPages, resultData]);

  // 单个页面旋转（用于缩略图上的快捷操作）
  const handleSinglePageRotate = useCallback(async (page: number, type: RotationType) => {
    if (!pdfFile) return;

    setProcessing(true);

    try {
      const sourceData = resultData || pdfFile.data;
      let angle: RotationAngle;

      switch (type) {
        case 'cw':
          angle = 90;
          break;
        case 'ccw':
          angle = -90;
          break;
        case 'flip-h':
        case 'flip-v':
          angle = 180;
          break;
        default:
          angle = 90;
      }

      // 复制 ArrayBuffer 以避免 detached 问题
      const result = await pdfApi.rotate({
        file: sourceData.slice(0),
        pages: [page],
        angle,
      });

      setResultData(result);
      setPreviewKey(prev => prev + 1); // 只在单页旋转时更新预览

      const typeText = type === 'cw' ? '顺时针' : type === 'ccw' ? '逆时针' : '翻转';
      message.success(`第 ${page} 页已${typeText}旋转`);
    } catch (error) {
      console.error('Single page rotate failed:', error);
      message.error('旋转失败: ' + (error as Error).message);
    } finally {
      setProcessing(false);
    }
  }, [pdfFile, resultData]);

  // 重置
  const handleReset = useCallback(() => {
    if (pdfFile) {
      setResultData(null);
      setPreviewKey(prev => prev + 1);
      message.info('已重置为原始状态');
    }
  }, [pdfFile]);

  // 下载结果
  const handleDownload = useCallback(() => {
    const dataToDownload = resultData || pdfFile?.data;
    if (!dataToDownload || !pdfFile) return;

    const blob = new Blob([dataToDownload], { type: 'application/pdf' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = pdfFile.name.replace('.pdf', '_rotated.pdf');
    document.body.appendChild(a);
    a.click();
    document.body.removeChild(a);
    URL.revokeObjectURL(url);
  }, [resultData, pdfFile]);

  // 未上传文件时显示上传区域
  if (!pdfFile) {
    return (
      <div style={{ padding: 24 }}>
        <Dragger
          accept=".pdf"
          showUploadList={false}
          beforeUpload={handlePdfUpload}
          style={{ padding: 40 }}
        >
          <p className="ant-upload-drag-icon">
            <InboxOutlined style={{ fontSize: 48, color: '#1890ff' }} />
          </p>
          <p className="ant-upload-text">点击或拖拽 PDF 文件到此处</p>
          <p className="ant-upload-hint">旋转 PDF 页面（90°、-90°、180°）</p>
        </Dragger>
      </div>
    );
  }

  return (
    <div>
      {/* 上方：参数设置区 */}
      <Card size="small" style={{ marginBottom: 12 }}>
        <Row gutter={16} align="middle">
          <Col span={5}>
            <Space>
              <Upload accept=".pdf" showUploadList={false} beforeUpload={handlePdfUpload}>
                <Button icon={<UploadOutlined />} size="small">更换文件</Button>
              </Upload>
              <Text ellipsis style={{ maxWidth: 120 }}>{pdfFile.name}</Text>
            </Space>
          </Col>
          <Col span={6}>
            <Space>
              <Text type="secondary">旋转角度：</Text>
              <Button.Group>
                <Button 
                  icon={<RotateLeftOutlined />} 
                  onClick={() => handleRotate(-90)}
                  loading={processing}
                  title="逆时针 90°"
                >
                  -90°
                </Button>
                <Button 
                  onClick={() => handleRotate(180)}
                  loading={processing}
                  title="旋转 180°"
                >
                  180°
                </Button>
                <Button 
                  icon={<RotateRightOutlined />} 
                  onClick={() => handleRotate(90)}
                  loading={processing}
                  title="顺时针 90°"
                >
                  90°
                </Button>
              </Button.Group>
            </Space>
          </Col>
          <Col span={5}>
            <Checkbox 
              checked={selectAll}
              onChange={(e) => handleSelectAllChange(e.target.checked)}
            >
              选择所有页面
            </Checkbox>
            <Text type="secondary" style={{ marginLeft: 8 }}>
              ({selectedPages.length}/{totalPages} 页)
            </Text>
          </Col>
          <Col span={8} style={{ textAlign: 'right' }}>
            <Space>
              {resultData && (
                <Button 
                  icon={<UndoOutlined />} 
                  onClick={handleReset}
                >
                  重置
                </Button>
              )}
              <Button 
                type="primary"
                icon={<DownloadOutlined />} 
                onClick={handleDownload}
                disabled={!pdfFile}
              >
                下载
              </Button>
            </Space>
          </Col>
        </Row>
      </Card>

      {/* 下方：页面缩略图网格 */}
      <Card 
        size="small" 
        title={`页面缩略图 ${resultData ? '（已修改）' : ''}`}
        style={{ height: 'calc(100vh - 280px)' }}
        styles={{ body: { height: 'calc(100% - 40px)', overflow: 'auto', padding: 12 } }}
      >
        <Spin spinning={processing}>
          <PDFThumbnails
            key={previewKey}
            pdfData={resultData || pdfFile.data}
            selectedPages={selectedPages}
            onPageSelect={handlePageSelect}
            multiSelect={true}
            showRotateButtons={true}
            onPageRotate={handleSinglePageRotate}
          />
        </Spin>
      </Card>
    </div>
  );
};

