export class TemplateManager {
  private itemsManager: ItemsManager;
  private templates: Map<string, NoteTemplate> = new Map();

  constructor(itemsManager: ItemsManager) {
    this.itemsManager = itemsManager;
    this.loadTemplates();
  }

  // 加载模板
  private loadTemplates(): void {
    // 加载系统模板
    for (const template of DEFAULT_TEMPLATES) {
      const id = `system-${template.name}`;
      this.templates.set(id, {
        ...template,
        id,
        createdAt: 0,
        updatedAt: 0,
      });
    }

    // 加载用户自定义模板
    const userTemplates = this.itemsManager.getByType('template' as any);
    for (const item of userTemplates) {
      const template = JSON.parse(item.payload) as NoteTemplate;
      this.templates.set(template.id, template);
    }
  }

  // 获取所有模板
  getAllTemplates(): NoteTemplate[] {
    return Array.from(this.templates.values());
  }

  // 获取单个模板
  getTemplate(id: string): NoteTemplate | undefined {
    return this.templates.get(id);
  }

  // 创建自定义模板
  createTemplate(template: Omit<NoteTemplate, 'id' | 'createdAt' | 'updatedAt' | 'isSystem'>): NoteTemplate {
    const now = Date.now();
    const newTemplate: NoteTemplate = {
      ...template,
      id: `user-${now}`,
      isSystem: false,
      createdAt: now,
      updatedAt: now,
    };

    // 保存到数据库
    this.itemsManager.create('template' as any, newTemplate);
    this.templates.set(newTemplate.id, newTemplate);

    return newTemplate;
  }

  // 更新模板
  updateTemplate(id: string, updates: Partial<NoteTemplate>): NoteTemplate | null {
    const template = this.templates.get(id);
    if (!template || template.isSystem) return null;

    const updatedTemplate: NoteTemplate = {
      ...template,
      ...updates,
      id: template.id,
      isSystem: false,
      updatedAt: Date.now(),
    };

    this.itemsManager.update(id, updatedTemplate);
    this.templates.set(id, updatedTemplate);

    return updatedTemplate;
  }

  // 删除模板
  deleteTemplate(id: string): boolean {
    const template = this.templates.get(id);
    if (!template || template.isSystem) return false;

    this.itemsManager.softDelete(id);
    this.templates.delete(id);
    return true;
  }

  // 应用模板生成笔记内容
  applyTemplate(templateId: string, variables: Record<string, string> = {}): { title: string; content: string } {
    const template = this.templates.get(templateId);
    if (!template) {
      return { title: '新建笔记', content: '' };
    }

    let content = template.content;

    // 替换内置变量
    const now = new Date();
    const builtinVars: Record<string, string> = {
      '{{TODAY}}': now.toLocaleDateString('zh-CN'),
      '{{NOW}}': now.toLocaleTimeString('zh-CN', { hour: '2-digit', minute: '2-digit' }),
      '{{DATETIME}}': now.toLocaleString('zh-CN'),
      '{{YEAR}}': now.getFullYear().toString(),
      '{{MONTH}}': (now.getMonth() + 1).toString().padStart(2, '0'),
      '{{DAY}}': now.getDate().toString().padStart(2, '0'),
    };

    for (const [key, value] of Object.entries(builtinVars)) {
      content = content.replace(new RegExp(key, 'g'), value);
    }

    // 替换用户变量
    for (const variable of template.variables) {
      const value = variables[variable.name] || variable.defaultValue || '';
      // 先替换默认值中的内置变量
      let finalValue = value;
      for (const [key, val] of Object.entries(builtinVars)) {
        finalValue = finalValue.replace(new RegExp(key, 'g'), val);
      }
      content = content.replace(new RegExp(`{{${variable.name}}}`, 'g'), finalValue);
    }

    // 生成标题
    let title = template.name;
    if (variables['title']) {
      title = variables['title'];
    } else if (template.name === '日记') {
      title = `${builtinVars['{{TODAY}}']} 日记`;
    }

    return { title, content };
  }

  // 从现有笔记创建模板
  createTemplateFromNote(noteContent: string, name: string, description: string): NoteTemplate {
    // 检测可能的变量
    const variablePattern = /\{\{(\w+)\}\}/g;
    const matches = [...noteContent.matchAll(variablePattern)];
    const variables: TemplateVariable[] = [];

    const seenVars = new Set<string>();
    for (const match of matches) {
      const varName = match[1];
      if (!seenVars.has(varName) && !['TODAY', 'NOW', 'DATETIME', 'YEAR', 'MONTH', 'DAY'].includes(varName)) {
        seenVars.add(varName);
        variables.push({
          name: varName,
          type: 'text',
          label: varName,
        });
      }
    }

    return this.createTemplate({
      name,
      description,
      icon: '📄',
      content: noteContent,
      variables,
    });
  }
}

export default TemplateManager;

/**
 * CompressTool - PDF 压缩工具组件
 * 采用上下布局：上方为参数设置区，下方为压缩结果展示
 * 使用 Ghostscript 进行 PDF 压缩（必需）
 */

import React, { useState, useCallback, useEffect } from 'react';
import { Card, Row, Col, Typography, Upload, Button, Space, message, Radio, Progress, Statistic, Alert, Tag } from 'antd';
import { UploadOutlined, InboxOutlined, DownloadOutlined, CompressOutlined, CheckCircleOutlined, WarningOutlined } from '@ant-design/icons';
import { pdfApi } from '../../services/pdfApi';
import { formatFileSize, validatePdfHeader, downloadFile } from './utils';

const { Text } = Typography;
const { Dragger } = Upload;

// ============ 类型定义 ============

interface PDFFile {
  name: string;
  data: ArrayBuffer;
  size: number;
}

interface CompressResult {
  data: ArrayBuffer;
  originalSize: number;
  compressedSize: number;
  ratio: number;
}

type CompressLevel = 'low' | 'medium' | 'high';

interface GhostscriptStatus {
  available: boolean;
  path: string | null;
  version?: string | null;
}

// ============ CompressTool 组件 ============

const CompressTool: React.FC = () => {
  const [pdfFile, setPdfFile] = useState<PDFFile | null>(null);
  const [level, setLevel] = useState<CompressLevel>('medium');
  const [processing, setProcessing] = useState(false);
  const [result, setResult] = useState<CompressResult | null>(null);
  const [gsStatus, setGsStatus] = useState<GhostscriptStatus | null>(null);
  const [checkingGs, setCheckingGs] = useState(true);

  // 检查 Ghostscript 可用性
  useEffect(() => {
    const checkGs = async () => {
      try {
        const status = await pdfApi.checkGhostscript();
        setGsStatus(status);
      } catch (error) {
        console.error('Failed to check Ghostscript:', error);
        setGsStatus({ available: false, path: null });
      } finally {
        setCheckingGs(false);
      }
    };
    checkGs();
  }, []);

  // 文件上传处理
  const handleFileUpload = useCallback(async (file: File): Promise<boolean> => {
    if (!file.name.toLowerCase().endsWith('.pdf')) {
      message.error('请上传 PDF 文件');
      return false;
    }

    try {
      const arrayBuffer = await file.arrayBuffer();

      // 复制 ArrayBuffer 以避免 detached 问题
      const bufferCopy = arrayBuffer.slice(0);

      if (!validatePdfHeader(bufferCopy)) {
        message.error('无效的 PDF 文件');
        return false;
      }

      setPdfFile({
        name: file.name,
        data: bufferCopy,
        size: file.size,
      });
      setResult(null);

      message.success(`已加载: ${file.name} (${formatFileSize(file.size)})`);
      return true;
    } catch (error) {
      console.error('Failed to load PDF:', error);
      message.error('PDF 加载失败');
      return false;
    }
  }, []);


  // 执行压缩
  const handleCompress = useCallback(async () => {
    if (!pdfFile) {
      message.warning('请先上传 PDF 文件');
      return;
    }

    setProcessing(true);
    setResult(null);

    try {
      // 复制 ArrayBuffer 以避免 detached 问题
      const compressResult = await pdfApi.compress({
        file: pdfFile.data.slice(0),
        level,
      });

      setResult({
        data: compressResult.data,
        originalSize: compressResult.originalSize,
        compressedSize: compressResult.compressedSize,
        ratio: compressResult.ratio, // 保留原始值，可能为负
      });

      if (compressResult.compressedSize >= compressResult.originalSize) {
        message.warning('压缩后文件反而变大，建议保留原文件');
      } else {
        message.success(`压缩完成，节省 ${compressResult.ratio.toFixed(1)}%`);
      }
    } catch (error) {
      console.error('Compress failed:', error);
      message.error('压缩失败: ' + (error as Error).message);
    } finally {
      setProcessing(false);
    }
  }, [pdfFile, level]);

  // 下载压缩后的文件
  const handleDownload = useCallback(() => {
    if (!result || !pdfFile) return;
    downloadFile(result.data, pdfFile.name.replace('.pdf', '_compressed.pdf'));
  }, [result, pdfFile]);

  // 未上传文件时显示上传区域
  if (!pdfFile) {
    return (
      <div style={{ padding: 24 }}>
        {/* Ghostscript 状态提示 */}
        {!checkingGs && (
          <Alert
            message={gsStatus?.available ? 'Ghostscript 已就绪' : 'Ghostscript 未安装'}
            description={
              gsStatus?.available 
                ? `使用 Ghostscript 进行高质量压缩 (版本: ${gsStatus.version || '未知'})`
                : 'PDF 压缩功能需要 Ghostscript 支持，请先安装 Ghostscript。'
            }
            type={gsStatus?.available ? 'success' : 'error'}
            showIcon
            icon={gsStatus?.available ? <CheckCircleOutlined /> : <WarningOutlined />}
            style={{ marginBottom: 16 }}
          />
        )}

        <Dragger
          accept=".pdf"
          showUploadList={false}
          beforeUpload={handleFileUpload}
          disabled={!gsStatus?.available}
          style={{ padding: 40, opacity: gsStatus?.available ? 1 : 0.5 }}
        >
          <p className="ant-upload-drag-icon">
            <InboxOutlined style={{ fontSize: 48, color: gsStatus?.available ? '#1890ff' : '#999' }} />
          </p>
          <p className="ant-upload-text">
            {gsStatus?.available ? '点击或拖拽 PDF 文件到此处' : 'Ghostscript 未安装，无法使用压缩功能'}
          </p>
          <p className="ant-upload-hint">
            {gsStatus?.available 
              ? '使用 Ghostscript 进行高质量图片压缩'
              : '请先安装 Ghostscript 后再使用此功能'
            }
          </p>
        </Dragger>
      </div>
    );
  }

  const levelDescriptions: Record<CompressLevel, { label: string; desc: string }> = {
    low: { label: '低压缩', desc: '300 DPI - 保持高质量' },
    medium: { label: '中压缩', desc: '150 DPI - 平衡质量与大小' },
    high: { label: '高压缩', desc: '72 DPI - 最小文件' },
  };


  return (
    <div>
      {/* 上方：参数设置区 */}
      <Card size="small" style={{ marginBottom: 12 }}>
        <Row gutter={16} align="middle">
          <Col span={5}>
            <Space>
              <Upload accept=".pdf" showUploadList={false} beforeUpload={handleFileUpload}>
                <Button icon={<UploadOutlined />} size="small">更换文件</Button>
              </Upload>
              <Text ellipsis style={{ maxWidth: 100 }}>{pdfFile.name}</Text>
            </Space>
          </Col>
          <Col span={4}>
            <Text type="secondary">原始大小：</Text>
            <Text strong>{formatFileSize(pdfFile.size)}</Text>
          </Col>
          <Col span={9}>
            <Space>
              <Text type="secondary">压缩级别：</Text>
              <Radio.Group value={level} onChange={(e) => setLevel(e.target.value)} size="small">
                <Radio.Button value="low">{levelDescriptions.low.label}</Radio.Button>
                <Radio.Button value="medium">{levelDescriptions.medium.label}</Radio.Button>
                <Radio.Button value="high">{levelDescriptions.high.label}</Radio.Button>
              </Radio.Group>
              <Text type="secondary" style={{ fontSize: 12 }}>
                {levelDescriptions[level].desc}
              </Text>
            </Space>
          </Col>
          <Col span={6} style={{ textAlign: 'right' }}>
            <Space>
              <Tag color="green" icon={<CheckCircleOutlined />}>Ghostscript</Tag>
              <Button
                type="primary"
                icon={<CompressOutlined />}
                onClick={handleCompress}
                loading={processing}
              >
                压缩
              </Button>
            </Space>
          </Col>
        </Row>
      </Card>

      {/* 下方：压缩结果展示 */}
      <Card size="small" title="压缩结果">

        {!result ? (
          <div style={{ textAlign: 'center', padding: 60, color: '#999' }}>
            {processing ? (
              <Space direction="vertical">
                <Progress type="circle" percent={0} status="active" />
                <Text>正在压缩...</Text>
              </Space>
            ) : (
              <Text>选择压缩级别后点击"压缩"按钮</Text>
            )}
          </div>
        ) : (
          <div>
            <Row gutter={24} style={{ marginBottom: 24 }}>
              <Col span={6}>
                <Statistic title="原始大小" value={formatFileSize(result.originalSize)} />
              </Col>
              <Col span={6}>
                <Statistic title="压缩后大小" value={formatFileSize(result.compressedSize)} />
              </Col>
              <Col span={6}>
                <Statistic 
                  title="节省比例" 
                  value={Math.abs(result.ratio).toFixed(1)} 
                  suffix="%" 
                  prefix={result.ratio < 0 ? '+' : ''}
                  valueStyle={{ color: result.ratio > 0 ? '#3f8600' : '#cf1322' }}
                />
              </Col>
              <Col span={6}>
                <Statistic 
                  title={result.ratio >= 0 ? "节省空间" : "增加空间"}
                  value={formatFileSize(Math.abs(result.originalSize - result.compressedSize))} 
                  valueStyle={{ color: result.ratio > 0 ? '#3f8600' : '#cf1322' }}
                />
              </Col>
            </Row>

            {/* 可视化对比 */}
            <div style={{ marginBottom: 24 }}>
              <Text type="secondary">大小对比：</Text>
              <div style={{ display: 'flex', alignItems: 'center', marginTop: 8 }}>
                <div style={{ flex: 1 }}>
                  <div style={{ 
                    height: 24, 
                    background: '#1890ff', 
                    width: '100%',
                    borderRadius: 4,
                  }} />
                  <Text style={{ fontSize: 12 }}>原始: {formatFileSize(result.originalSize)}</Text>
                </div>
                <div style={{ width: 20 }} />
                <div style={{ flex: Math.max(0.1, result.compressedSize / result.originalSize) }}>
                  <div style={{ 
                    height: 24, 
                    background: result.ratio > 0 ? '#52c41a' : '#faad14', 
                    width: '100%',
                    borderRadius: 4,
                  }} />
                  <Text style={{ fontSize: 12 }}>压缩后: {formatFileSize(result.compressedSize)}</Text>
                </div>
              </div>
            </div>

            <Button 
              type="primary" 
              icon={<DownloadOutlined />} 
              onClick={handleDownload}
              size="large"
            >
              下载{result.ratio < 0 ? '处理后' : '压缩后'}的 PDF
            </Button>

            {result.compressedSize >= result.originalSize && (
              <Text type="warning" style={{ marginLeft: 12 }}>
                ⚠️ 压缩后文件变大，建议保留原文件
              </Text>
            )}
          </div>
        )}
      </Card>
    </div>
  );
};

export default CompressTool;

/**
 * MetadataTool - PDF 元数据编辑工具
 * 支持查看和编辑 PDF 文档的元数据信息
 */

import React, { useState, useCallback, useEffect } from 'react';
import {
  Upload,
  Button,
  Space,
  Typography,
  Card,
  Row,
  Col,
  message,
  Spin,
  Input,
  Form,
  Descriptions,
  Tag,
} from 'antd';
import {
  InboxOutlined,
  DownloadOutlined,
  EditOutlined,
  InfoCircleOutlined,
  SaveOutlined,
} from '@ant-design/icons';
import { pdfApi, PDFMetadata } from '../../services/pdfApi';

const { Text, Title } = Typography;
const { Dragger } = Upload;
const { TextArea } = Input;

// ============ 主组件 ============

const MetadataTool: React.FC = () => {
  const [pdfData, setPdfData] = useState<ArrayBuffer | null>(null);
  const [fileName, setFileName] = useState<string>('');
  const [loading, setLoading] = useState(false);
  const [processing, setProcessing] = useState(false);
  const [isEditing, setIsEditing] = useState(false);

  // 元数据
  const [metadata, setMetadata] = useState<PDFMetadata>({
    title: '',
    author: '',
    subject: '',
    keywords: '',
    creator: '',
    producer: '',
  });

  // 处理文件上传
  const handleUpload = useCallback(async (file: File) => {
    if (!file.name.toLowerCase().endsWith('.pdf')) {
      message.error('请上传 PDF 文件');
      return false;
    }

    try {
      setLoading(true);
      const arrayBuffer = await file.arrayBuffer();

      // 复制 ArrayBuffer 以避免 detached 问题
      const bufferCopy = arrayBuffer.slice(0);

      // 验证 PDF
      const header = new Uint8Array(bufferCopy.slice(0, 5));
      const pdfHeader = String.fromCharCode(...header);
      if (!pdfHeader.startsWith('%PDF-')) {
        message.error('无效的 PDF 文件');
        return false;
      }

      setPdfData(bufferCopy);
      setFileName(file.name);

      // 获取元数据
      const meta = await pdfApi.getMetadata(bufferCopy.slice(0));
      setMetadata(meta);
      setIsEditing(false);

      message.success('PDF 加载成功');
      return false;
    } catch (error) {
      console.error('Failed to load PDF:', error);
      message.error('PDF 加载失败');
      return false;
    } finally {
      setLoading(false);
    }
  }, []);

  // 保存元数据
  const handleSave = useCallback(async () => {
    if (!pdfData) {
      message.warning('请先上传 PDF 文件');
      return;
    }

    try {
      setProcessing(true);
      // 复制 ArrayBuffer 以避免 detached 问题
      const updatedPdf = await pdfApi.setMetadata({
        file: pdfData.slice(0),
        ...metadata,
      });

      // 更新本地数据
      setPdfData(updatedPdf);

      // 下载文件
      const blob = new Blob([updatedPdf], { type: 'application/pdf' });
      const url = URL.createObjectURL(blob);
      const a = document.createElement('a');
      a.href = url;
      a.download = fileName.replace('.pdf', '_metadata.pdf');
      document.body.appendChild(a);
      a.click();
      document.body.removeChild(a);
      URL.revokeObjectURL(url);

      setIsEditing(false);
      message.success('元数据保存成功');
    } catch (error) {
      console.error('Failed to save metadata:', error);
      message.error('保存失败');
    } finally {
      setProcessing(false);
    }
  }, [pdfData, metadata, fileName]);

  // 渲染查看模式
  const renderViewMode = () => (
    <Descriptions column={1} size="small" bordered>
      <Descriptions.Item label="标题">
        {metadata.title || <Text type="secondary">未设置</Text>}
      </Descriptions.Item>
      <Descriptions.Item label="作者">
        {metadata.author || <Text type="secondary">未设置</Text>}
      </Descriptions.Item>
      <Descriptions.Item label="主题">
        {metadata.subject || <Text type="secondary">未设置</Text>}
      </Descriptions.Item>
      <Descriptions.Item label="关键词">
        {metadata.keywords ? (
          <Space wrap>
            {metadata.keywords.split(',').map((kw, i) => (
              <Tag key={i}>{kw.trim()}</Tag>
            ))}
          </Space>
        ) : (
          <Text type="secondary">未设置</Text>
        )}
      </Descriptions.Item>
      <Descriptions.Item label="创建程序">
        {metadata.creator || <Text type="secondary">未设置</Text>}
      </Descriptions.Item>
      <Descriptions.Item label="PDF 生成器">
        {metadata.producer || <Text type="secondary">未设置</Text>}
      </Descriptions.Item>
    </Descriptions>
  );

  // 渲染编辑模式
  const renderEditMode = () => (
    <Form layout="vertical" size="small">
      <Form.Item label="标题">
        <Input
          value={metadata.title || ''}
          onChange={e => setMetadata(prev => ({ ...prev, title: e.target.value }))}
          placeholder="输入文档标题"
        />
      </Form.Item>

      <Form.Item label="作者">
        <Input
          value={metadata.author || ''}
          onChange={e => setMetadata(prev => ({ ...prev, author: e.target.value }))}
          placeholder="输入作者名称"
        />
      </Form.Item>

      <Form.Item label="主题">
        <Input
          value={metadata.subject || ''}
          onChange={e => setMetadata(prev => ({ ...prev, subject: e.target.value }))}
          placeholder="输入文档主题"
        />
      </Form.Item>

      <Form.Item label="关键词" extra="多个关键词用逗号分隔">
        <TextArea
          value={metadata.keywords || ''}
          onChange={e => setMetadata(prev => ({ ...prev, keywords: e.target.value }))}
          placeholder="输入关键词，用逗号分隔"
          rows={2}
        />
      </Form.Item>

      <Form.Item label="创建程序">
        <Input
          value={metadata.creator || ''}
          onChange={e => setMetadata(prev => ({ ...prev, creator: e.target.value }))}
          placeholder="输入创建程序名称"
        />
      </Form.Item>

      <Form.Item label="PDF 生成器">
        <Input
          value={metadata.producer || ''}
          onChange={e => setMetadata(prev => ({ ...prev, producer: e.target.value }))}
          placeholder="输入 PDF 生成器名称"
          disabled
        />
        <Text type="secondary" style={{ fontSize: 12 }}>
          此字段由 PDF 库自动设置
        </Text>
      </Form.Item>
    </Form>
  );

  return (
    <div style={{ padding: 16 }}>
      <Spin spinning={loading || processing}>
        {/* 文件上传区 */}
        <Card size="small" style={{ marginBottom: 16 }}>
          <Row gutter={[16, 12]} align="middle">
            {!pdfData ? (
              <Col span={24}>
                <Dragger
                  accept=".pdf"
                  showUploadList={false}
                  beforeUpload={handleUpload}
                  style={{ padding: '12px 0' }}
                >
                  <p className="ant-upload-drag-icon" style={{ marginBottom: 8 }}>
                    <InboxOutlined style={{ fontSize: 32, color: '#1890ff' }} />
                  </p>
                  <p className="ant-upload-text" style={{ marginBottom: 4 }}>
                    点击或拖拽 PDF 文件到此处
                  </p>
                  <p className="ant-upload-hint">查看和编辑 PDF 元数据信息</p>
                </Dragger>
              </Col>
            ) : (
              <>
                <Col flex="auto">
                  <Space>
                    <InfoCircleOutlined />
                    <Text strong>{fileName}</Text>
                  </Space>
                </Col>
                <Col>
                  <Space>
                    <Upload accept=".pdf" showUploadList={false} beforeUpload={handleUpload}>
                      <Button>更换文件</Button>
                    </Upload>
                    {isEditing ? (
                      <>
                        <Button onClick={() => setIsEditing(false)}>取消</Button>
                        <Button
                          type="primary"
                          icon={<SaveOutlined />}
                          onClick={handleSave}
                        >
                          保存
                        </Button>
                      </>
                    ) : (
                      <Button
                        type="primary"
                        icon={<EditOutlined />}
                        onClick={() => setIsEditing(true)}
                      >
                        编辑
                      </Button>
                    )}
                  </Space>
                </Col>
              </>
            )}
          </Row>
        </Card>

        {/* 元数据显示/编辑区 */}
        {pdfData && (
          <Card
            size="small"
            title={
              <Space>
                <InfoCircleOutlined />
                <span>文档元数据</span>
                {isEditing && <Tag color="blue">编辑中</Tag>}
              </Space>
            }
          >
            {isEditing ? renderEditMode() : renderViewMode()}
          </Card>
        )}
      </Spin>
    </div>
  );
};

export default MetadataTool;

/**
 * CompareTool - PDF 对比工具
 * 支持双文件上传、并排预览、同步导航和缩放
 */

import React, { useState, useCallback, useRef, useEffect } from 'react';
import {
  Upload,
  Button,
  Space,
  Typography,
  Card,
  Row,
  Col,
  message,
  Spin,
  Switch,
  InputNumber,
  Divider,
} from 'antd';
import {
  InboxOutlined,
  ZoomInOutlined,
  ZoomOutOutlined,
  LeftOutlined,
  RightOutlined,
  SyncOutlined,
} from '@ant-design/icons';
import PDFPreview from './PDFPreview';

const { Text } = Typography;
const { Dragger } = Upload;

// ============ 类型定义 ============

interface PDFFile {
  data: ArrayBuffer | null;
  name: string;
  pageCount: number;
}

// ============ 主组件 ============

const CompareTool: React.FC = () => {
  const [leftPdf, setLeftPdf] = useState<PDFFile>({ data: null, name: '', pageCount: 0 });
  const [rightPdf, setRightPdf] = useState<PDFFile>({ data: null, name: '', pageCount: 0 });
  const [loading, setLoading] = useState<'left' | 'right' | null>(null);

  // 同步控制
  const [syncNavigation, setSyncNavigation] = useState(true);
  const [syncZoom, setSyncZoom] = useState(true);

  // 当前状态
  const [currentPage, setCurrentPage] = useState(1);
  const [zoom, setZoom] = useState(100);

  // 处理文件上传
  const handleUpload = useCallback(async (file: File, side: 'left' | 'right') => {
    if (!file.name.toLowerCase().endsWith('.pdf')) {
      message.error('请上传 PDF 文件');
      return false;
    }

    try {
      setLoading(side);
      const arrayBuffer = await file.arrayBuffer();

      // 验证 PDF
      const header = new Uint8Array(arrayBuffer.slice(0, 5));
      const pdfHeader = String.fromCharCode(...header);
      if (!pdfHeader.startsWith('%PDF-')) {
        message.error('无效的 PDF 文件');
        return false;
      }

      const pdfFile: PDFFile = {
        data: arrayBuffer,
        name: file.name,
        pageCount: 0, // 将由 PDFPreview 更新
      };

      if (side === 'left') {
        setLeftPdf(pdfFile);
      } else {
        setRightPdf(pdfFile);
      }

      message.success(`${side === 'left' ? '左侧' : '右侧'} PDF 加载成功`);
      return false;
    } catch (error) {
      console.error('Failed to load PDF:', error);
      message.error('PDF 加载失败');
      return false;
    } finally {
      setLoading(null);
    }
  }, []);

  // 更新页数
  const handlePageCountChange = useCallback((side: 'left' | 'right', count: number) => {
    if (side === 'left') {
      setLeftPdf(prev => ({ ...prev, pageCount: count }));
    } else {
      setRightPdf(prev => ({ ...prev, pageCount: count }));
    }
  }, []);

  // 页面导航
  const handlePageChange = useCallback((page: number) => {
    const maxPage = Math.max(leftPdf.pageCount, rightPdf.pageCount);
    if (page >= 1 && page <= maxPage) {
      setCurrentPage(page);
    }
  }, [leftPdf.pageCount, rightPdf.pageCount]);

  // 缩放控制
  const handleZoomChange = useCallback((newZoom: number) => {
    if (newZoom >= 25 && newZoom <= 400) {
      setZoom(newZoom);
    }
  }, []);

  const maxPage = Math.max(leftPdf.pageCount, rightPdf.pageCount);

  // 渲染上传区域
  const renderUploadArea = (side: 'left' | 'right') => {
    const pdf = side === 'left' ? leftPdf : rightPdf;
    const isLoading = loading === side;

    if (pdf.data) {
      return (
        <div style={{ height: '100%', display: 'flex', flexDirection: 'column' }}>
          <div style={{ padding: '8px 12px', borderBottom: '1px solid #f0f0f0', background: '#fafafa' }}>
            <Row justify="space-between" align="middle">
              <Col>
                <Text strong ellipsis style={{ maxWidth: 150 }} title={pdf.name}>
                  {pdf.name}
                </Text>
                <Text type="secondary" style={{ marginLeft: 8 }}>
                  ({pdf.pageCount} 页)
                </Text>
              </Col>
              <Col>
                <Upload
                  accept=".pdf"
                  showUploadList={false}
                  beforeUpload={file => handleUpload(file, side)}
                >
                  <Button size="small">更换</Button>
                </Upload>
              </Col>
            </Row>
          </div>
          <div style={{ flex: 1, overflow: 'hidden' }}>
            <PDFPreview
              pdfData={pdf.data}
              currentPage={syncNavigation ? currentPage : undefined}
              zoom={syncZoom ? zoom : undefined}
              onPageChange={syncNavigation ? handlePageChange : undefined}
              onTotalPagesChange={count => handlePageCountChange(side, count)}
              showControls={!syncNavigation || !syncZoom}
            />
          </div>
        </div>
      );
    }

    return (
      <Spin spinning={isLoading}>
        <Dragger
          accept=".pdf"
          showUploadList={false}
          beforeUpload={file => handleUpload(file, side)}
          style={{ height: 300, display: 'flex', alignItems: 'center', justifyContent: 'center' }}
        >
          <p className="ant-upload-drag-icon">
            <InboxOutlined style={{ fontSize: 32, color: '#1890ff' }} />
          </p>
          <p className="ant-upload-text">
            {side === 'left' ? '上传左侧 PDF' : '上传右侧 PDF'}
          </p>
          <p className="ant-upload-hint">点击或拖拽文件</p>
        </Dragger>
      </Spin>
    );
  };

  return (
    <div style={{ padding: 16, height: '100%', display: 'flex', flexDirection: 'column' }}>
      {/* 控制栏 */}
      <Card size="small" style={{ marginBottom: 12 }}>
        <Row gutter={16} align="middle">
          <Col>
            <Space>
              <Text>同步导航</Text>
              <Switch
                checked={syncNavigation}
                onChange={setSyncNavigation}
                size="small"
              />
            </Space>
          </Col>
          <Col>
            <Space>
              <Text>同步缩放</Text>
              <Switch
                checked={syncZoom}
                onChange={setSyncZoom}
                size="small"
              />
            </Space>
          </Col>

          {(syncNavigation || syncZoom) && (
            <>
              <Divider type="vertical" />

              {syncNavigation && maxPage > 0 && (
                <Col>
                  <Space>
                    <Button
                      size="small"
                      icon={<LeftOutlined />}
                      onClick={() => handlePageChange(currentPage - 1)}
                      disabled={currentPage <= 1}
                    />
                    <InputNumber
                      size="small"
                      min={1}
                      max={maxPage}
                      value={currentPage}
                      onChange={v => v && handlePageChange(v)}
                      style={{ width: 60 }}
                    />
                    <Text type="secondary">/ {maxPage}</Text>
                    <Button
                      size="small"
                      icon={<RightOutlined />}
                      onClick={() => handlePageChange(currentPage + 1)}
                      disabled={currentPage >= maxPage}
                    />
                  </Space>
                </Col>
              )}

              {syncZoom && (
                <Col>
                  <Space>
                    <Button
                      size="small"
                      icon={<ZoomOutOutlined />}
                      onClick={() => handleZoomChange(zoom - 25)}
                      disabled={zoom <= 25}
                    />
                    <InputNumber
                      size="small"
                      min={25}
                      max={400}
                      value={zoom}
                      onChange={v => v && handleZoomChange(v)}
                      formatter={v => `${v}%`}
                      parser={v => parseInt(v?.replace('%', '') || '100', 10)}
                      style={{ width: 70 }}
                    />
                    <Button
                      size="small"
                      icon={<ZoomInOutlined />}
                      onClick={() => handleZoomChange(zoom + 25)}
                      disabled={zoom >= 400}
                    />
                  </Space>
                </Col>
              )}
            </>
          )}
        </Row>
      </Card>

      {/* 并排预览区 */}
      <Row gutter={12} style={{ flex: 1, minHeight: 0 }}>
        <Col span={12} style={{ height: '100%' }}>
          <Card
            size="small"
            title="左侧文档"
            style={{ height: '100%', display: 'flex', flexDirection: 'column' }}
            bodyStyle={{ flex: 1, padding: 0, overflow: 'hidden' }}
          >
            {renderUploadArea('left')}
          </Card>
        </Col>
        <Col span={12} style={{ height: '100%' }}>
          <Card
            size="small"
            title="右侧文档"
            style={{ height: '100%', display: 'flex', flexDirection: 'column' }}
            bodyStyle={{ flex: 1, padding: 0, overflow: 'hidden' }}
          >
            {renderUploadArea('right')}
          </Card>
        </Col>
      </Row>
    </div>
  );
};

export default CompareTool;

import * as fs from 'fs';
import * as path from 'path';
import * as crypto from 'crypto';
import { DatabaseManager } from '../database/Database';
import { ItemsManager } from '../database/ItemsManager';
import { CryptoEngine } from '../crypto/CryptoEngine';
import { ItemBase } from '@shared/types';

export interface BackupOptions {
  includeResources: boolean;
  encrypt: boolean;
  password?: string;
}

export interface BackupMetadata {
  version: string;
  created_at: number;
  app_version: string;
  encrypted: boolean;
  items_count: number;
  resources_count: number;
  checksum: string;
}

export interface BackupResult {
  success: boolean;
  filePath: string;
  metadata: BackupMetadata;
  error?: string;
}

export interface RestoreResult {
  success: boolean;
  itemsRestored: number;
  resourcesRestored: number;
  error?: string;
}

export class BackupManager {
  private dbManager: DatabaseManager;
  private itemsManager: ItemsManager;
  private userDataPath: string;
  private cryptoEngine: CryptoEngine;

  constructor(dbManager: DatabaseManager, userDataPath: string) {
    this.dbManager = dbManager;
    this.itemsManager = new ItemsManager(dbManager);
    this.userDataPath = userDataPath;
    this.cryptoEngine = new CryptoEngine();
  }

  // 创建完整备份
  async createBackup(outputPath: string, options: BackupOptions): Promise<BackupResult> {
    try {
      const timestamp = Date.now();
      const backupData: Record<string, unknown> = {
        metadata: {
          version: '1.0',
          created_at: timestamp,
          app_version: '1.0.0',
          encrypted: options.encrypt,
          items_count: 0,
          resources_count: 0,
          checksum: '',
        },
        items: [],
        resources: [],
      };

      // 导出所有 items
      const items = this.itemsManager.getAllForExport() as unknown as Record<string, unknown>[];
      backupData.items = items;
      (backupData.metadata as BackupMetadata).items_count = items.length;

      // 导出资源文件（如果需要）
      if (options.includeResources) {
        const resourcesDir = path.join(this.userDataPath, 'resources');
        if (fs.existsSync(resourcesDir)) {
          const resourceFiles = fs.readdirSync(resourcesDir);
          const resources: Array<{ filename: string; data: string }> = [];

          for (const filename of resourceFiles) {
            const filePath = path.join(resourcesDir, filename);
            const data = fs.readFileSync(filePath);
            resources.push({
              filename,
              data: data.toString('base64'),
            });
          }

          backupData.resources = resources;
          (backupData.metadata as BackupMetadata).resources_count = resources.length;
        }
      }

      // 计算校验和
      const dataStr = JSON.stringify({ items: backupData.items, resources: backupData.resources });
      (backupData.metadata as BackupMetadata).checksum = crypto
        .createHash('sha256')
        .update(dataStr)
        .digest('hex');

      // 序列化
      let outputData = JSON.stringify(backupData, null, 2);

      // 加密（如果需要）
      if (options.encrypt && options.password) {
        const encrypted = this.cryptoEngine.encryptWithPassword(outputData, options.password);
        outputData = JSON.stringify({ encrypted: true, data: encrypted });
      }

      // 写入文件
      const finalPath = outputPath.endsWith('.mcbak') ? outputPath : `${outputPath}.mcbak`;
      fs.writeFileSync(finalPath, outputData, 'utf8');

      return {
        success: true,
        filePath: finalPath,
        metadata: backupData.metadata as BackupMetadata,
      };
    } catch (error) {
      return {
        success: false,
        filePath: '',
        metadata: {} as BackupMetadata,
        error: (error as Error).message,
      };
    }
  }

  // 从备份恢复
  async restoreBackup(backupPath: string, password?: string): Promise<RestoreResult> {
    try {
      // 读取备份文件
      let content = fs.readFileSync(backupPath, 'utf8');
      let backupData: Record<string, unknown>;

      // 检查是否加密
      const parsed = JSON.parse(content);
      if (parsed.encrypted) {
        if (!password) {
          return { success: false, itemsRestored: 0, resourcesRestored: 0, error: 'Password required for encrypted backup' };
        }
        const decrypted = this.cryptoEngine.decryptWithPassword(parsed.data, password);
        backupData = JSON.parse(decrypted);
      } else {
        backupData = parsed;
      }

      // 验证校验和
      const dataStr = JSON.stringify({ items: backupData.items, resources: backupData.resources });
      const checksum = crypto.createHash('sha256').update(dataStr).digest('hex');
      if (checksum !== (backupData.metadata as BackupMetadata).checksum) {
        return { success: false, itemsRestored: 0, resourcesRestored: 0, error: 'Backup checksum verification failed' };
      }

      // 恢复 items
      const items = backupData.items as Array<Record<string, unknown>>;
      let itemsRestored = 0;

      this.dbManager.transaction(() => {
        for (const item of items) {
          this.itemsManager.upsertFromPlainItem(item as unknown as ItemBase);
          itemsRestored++;
        }
      });

      // 恢复资源文件
      const resources = backupData.resources as Array<{ filename: string; data: string }>;
      let resourcesRestored = 0;

      if (resources && resources.length > 0) {
        const resourcesDir = path.join(this.userDataPath, 'resources');
        if (!fs.existsSync(resourcesDir)) {
          fs.mkdirSync(resourcesDir, { recursive: true });
        }

        for (const resource of resources) {
          const filePath = path.join(resourcesDir, resource.filename);
          const data = Buffer.from(resource.data, 'base64');
          fs.writeFileSync(filePath, data);
          resourcesRestored++;
        }
      }

      return { success: true, itemsRestored, resourcesRestored };
    } catch (error) {
      return {
        success: false,
        itemsRestored: 0,
        resourcesRestored: 0,
        error: (error as Error).message,
      };
    }
  }

  // 验证备份文件
  async verifyBackup(backupPath: string, password?: string): Promise<{ valid: boolean; metadata?: BackupMetadata; error?: string }> {
    try {
      let content = fs.readFileSync(backupPath, 'utf8');
      const parsed = JSON.parse(content);

      if (parsed.encrypted) {
        if (!password) {
          return { valid: false, error: 'Password required for encrypted backup' };
        }
        const decrypted = this.cryptoEngine.decryptWithPassword(parsed.data, password);
        const backupData = JSON.parse(decrypted);

        // 验证校验和
        const dataStr = JSON.stringify({ items: backupData.items, resources: backupData.resources });
        const checksum = crypto.createHash('sha256').update(dataStr).digest('hex');

        if (checksum !== backupData.metadata.checksum) {
          return { valid: false, error: 'Checksum verification failed' };
        }

        return { valid: true, metadata: backupData.metadata };
      } else {
        const dataStr = JSON.stringify({ items: parsed.items, resources: parsed.resources });
        const checksum = crypto.createHash('sha256').update(dataStr).digest('hex');

        if (checksum !== parsed.metadata.checksum) {
          return { valid: false, error: 'Checksum verification failed' };
        }

        return { valid: true, metadata: parsed.metadata };
      }
    } catch (error) {
      return { valid: false, error: (error as Error).message };
    }
  }

  // 列出可用备份
  listBackups(backupDir: string): Array<{ filename: string; path: string; size: number; modified: Date }> {
    if (!fs.existsSync(backupDir)) {
      return [];
    }

    const files = fs.readdirSync(backupDir);
    return files
      .filter(f => f.endsWith('.mcbak'))
      .map(filename => {
        const filePath = path.join(backupDir, filename);
        const stats = fs.statSync(filePath);
        return {
          filename,
          path: filePath,
          size: stats.size,
          modified: stats.mtime,
        };
      })
      .sort((a, b) => b.modified.getTime() - a.modified.getTime());
  }

  // 自动备份（增量）
  async createIncrementalBackup(backupDir: string): Promise<BackupResult> {
    const timestamp = new Date().toISOString().replace(/[:.]/g, '-');
    const filename = `backup-${timestamp}.mcbak`;
    const outputPath = path.join(backupDir, filename);

    return this.createBackup(outputPath, {
      includeResources: true,
      encrypt: false,
    });
  }

  // 清理旧备份
  cleanOldBackups(backupDir: string, keepCount: number = 10): number {
    const backups = this.listBackups(backupDir);
    let deleted = 0;

    if (backups.length > keepCount) {
      const toDelete = backups.slice(keepCount);
      for (const backup of toDelete) {
        fs.unlinkSync(backup.path);
        deleted++;
      }
    }

    return deleted;
  }
}

