    Screen.Notes,
    Screen.Bookmarks,
    Screen.Todos,
    Screen.AI,
    Screen.Vault,
    Screen.Transfer
)

/**
 * 需要显示底部导航的主页面路由
 */
private val mainScreenRoutes = listOf(
    Screen.Notes.route,
    Screen.Bookmarks.route,
    Screen.Todos.route,
    Screen.AI.route,
    Screen.Vault.route,
    Screen.Transfer.route,
    Screen.Settings.route
