export const tokenService = new TokenService();

/**
 * ReorderTool - PDF 页面重排工具组件
 * 采用上下布局：上方为参数设置区，下方为可拖拽排序的页面缩略图网格
 */

import React, { useState, useCallback } from 'react';
import { 
  Card, Row, Col, Typography, Upload, Button, Space, message, Spin
} from 'antd';
import { 
  UploadOutlined, InboxOutlined, DownloadOutlined, UndoOutlined, SaveOutlined
} from '@ant-design/icons';
import { pdfApi } from '../../services/pdfApi';
import PDFThumbnails from './PDFThumbnails';
import { downloadFile } from './utils';

const { Text } = Typography;
const { Dragger } = Upload;

// ============ 类型定义 ============

interface PDFFile {
  name: string;
  data: ArrayBuffer;
  size: number;
}

// ============ ReorderTool 组件 ============

const ReorderTool: React.FC = () => {
  const [pdfFile, setPdfFile] = useState<PDFFile | null>(null);
  const [totalPages, setTotalPages] = useState(0);
  const [pageOrder, setPageOrder] = useState<number[]>([]);
  const [processing, setProcessing] = useState(false);
  const [resultData, setResultData] = useState<ArrayBuffer | null>(null);
  const [hasChanges, setHasChanges] = useState(false);
  const [previewKey, setPreviewKey] = useState(0);

  // PDF 文件上传处理
  const handlePdfUpload = useCallback(async (file: File): Promise<boolean> => {
    if (!file.name.toLowerCase().endsWith('.pdf')) {
      message.error('请上传 PDF 文件');
      return false;
    }

    try {
      const arrayBuffer = await file.arrayBuffer();

      // 复制 ArrayBuffer 以避免 detached 问题
      const bufferCopy = arrayBuffer.slice(0);

      const header = new Uint8Array(bufferCopy.slice(0, 5));
      const pdfHeader = String.fromCharCode(...header);
      if (!pdfHeader.startsWith('%PDF-')) {
        message.error('无效的 PDF 文件');
        return false;
      }

      // 获取 PDF 信息
      const info = await pdfApi.getInfo(bufferCopy.slice(0));

      setPdfFile({
        name: file.name,
        data: bufferCopy,
        size: file.size,
      });
      setTotalPages(info.pageCount);
      setPageOrder(Array.from({ length: info.pageCount }, (_, i) => i + 1));
      setResultData(null);
      setHasChanges(false);
      setPreviewKey(prev => prev + 1);

      message.success(`已加载: ${file.name} (${info.pageCount} 页)`);
      return true;
    } catch (error) {
      console.error('Failed to load PDF:', error);
      message.error('PDF 加载失败');
      return false;
    }
  }, []);

  // 处理页面重排
  const handlePageReorder = useCallback((newOrder: number[]) => {
    setPageOrder(newOrder);
    // 检查是否有变化
    const originalOrder = Array.from({ length: totalPages }, (_, i) => i + 1);
    const changed = JSON.stringify(newOrder) !== JSON.stringify(originalOrder);
    setHasChanges(changed);
  }, [totalPages]);

  // 应用重排
  const handleApply = useCallback(async () => {
    if (!pdfFile || !hasChanges) return;

    setProcessing(true);

    try {
      // 复制 ArrayBuffer 以避免 detached 问题
      const result = await pdfApi.reorder({
        file: pdfFile.data.slice(0),
        newOrder: pageOrder,
      });

      setResultData(result);
      setPreviewKey(prev => prev + 1);
      message.success('页面重排完成');
    } catch (error) {
      console.error('Reorder failed:', error);
      message.error('重排失败: ' + (error as Error).message);
    } finally {
      setProcessing(false);
    }
  }, [pdfFile, pageOrder, hasChanges]);

  // 重置
  const handleReset = useCallback(() => {
    if (pdfFile) {
      setPageOrder(Array.from({ length: totalPages }, (_, i) => i + 1));
      setResultData(null);
      setHasChanges(false);
      setPreviewKey(prev => prev + 1);
      message.info('已重置为原始顺序');
    }
  }, [pdfFile, totalPages]);

  // 下载结果
  const handleDownload = useCallback(() => {
    const dataToDownload = resultData || pdfFile?.data;
    if (!dataToDownload || !pdfFile) return;
    downloadFile(dataToDownload, pdfFile.name.replace('.pdf', '_reordered.pdf'));
  }, [resultData, pdfFile]);

  // 未上传文件时显示上传区域
  if (!pdfFile) {
    return (
      <div style={{ padding: 24 }}>
        <Dragger
          accept=".pdf"
          showUploadList={false}
          beforeUpload={handlePdfUpload}
          style={{ padding: 40 }}
        >
          <p className="ant-upload-drag-icon">
            <InboxOutlined style={{ fontSize: 48, color: '#1890ff' }} />
          </p>
          <p className="ant-upload-text">点击或拖拽 PDF 文件到此处</p>
          <p className="ant-upload-hint">拖拽页面缩略图来重新排列页面顺序</p>
        </Dragger>
      </div>
    );
  }

  return (
    <div>
      {/* 上方：参数设置区 */}
      <Card size="small" style={{ marginBottom: 12 }}>
        <Row gutter={16} align="middle">
          <Col span={6}>
            <Space>
              <Upload accept=".pdf" showUploadList={false} beforeUpload={handlePdfUpload}>
                <Button icon={<UploadOutlined />} size="small">更换文件</Button>
              </Upload>
              <Text ellipsis style={{ maxWidth: 120 }}>{pdfFile.name}</Text>
            </Space>
          </Col>
          <Col span={6}>
            <Text type="secondary">共 {totalPages} 页</Text>
            {hasChanges && (
              <Text type="warning" style={{ marginLeft: 12 }}>
                (已修改顺序)
              </Text>
            )}
          </Col>
          <Col span={12} style={{ textAlign: 'right' }}>
            <Space>
              <Button 
                icon={<UndoOutlined />} 
                onClick={handleReset}
                disabled={!hasChanges && !resultData}
              >
                重置
              </Button>
              <Button 
                type="primary"
                icon={<SaveOutlined />} 
                onClick={handleApply}
                loading={processing}
                disabled={!hasChanges}
              >
                应用
              </Button>
              <Button 
                icon={<DownloadOutlined />} 
                onClick={handleDownload}
                disabled={!pdfFile}
              >
                下载
              </Button>
            </Space>
          </Col>
        </Row>
      </Card>

      {/* 下方：可拖拽排序的页面缩略图网格 */}
      <Card 
        size="small" 
        title="拖拽页面调整顺序"
        extra={
          <Text type="secondary">
            当前顺序: {pageOrder.join(', ')}
          </Text>
        }
        style={{ height: 'calc(100vh - 280px)' }}
        styles={{ body: { height: 'calc(100% - 40px)', overflow: 'auto', padding: 12 } }}
      >
        <Spin spinning={processing}>
          <PDFThumbnails
            key={previewKey}
            pdfData={resultData || pdfFile.data}
            selectedPages={[]}
            onPageSelect={() => {}}
            onPageReorder={handlePageReorder}
            draggable={true}
            multiSelect={false}
          />
        </Spin>
      </Card>
    </div>
  );
};

export default ReorderTool;

import { getDatabase } from '../database';
import { ItemBase, CountResult } from '../types';
import { ChangeService } from './ChangeService';
import { userService } from './UserService';

export class ItemService {
  private changeService: ChangeService;
  private userId?: string;

  constructor(userId?: string) {
    this.changeService = new ChangeService();
    this.userId = userId;
  }

  private prepareUserScope(): void {
    userService.claimLegacyDataForSingleUser(this.userId);
  }

  // 获取单个数据项
  getItem(id: string): ItemBase | null {
    this.prepareUserScope();
    const db = getDatabase();
    let stmt;
    let row;

    if (this.userId) {
      // 用户隔离：只能获取自己的数据
      stmt = db.prepare('SELECT * FROM items WHERE id = ? AND user_id = ?');
      row = stmt.get(id, this.userId) as ItemBase | undefined;
    } else {
      // 向后兼容：无用户隔离
      stmt = db.prepare('SELECT * FROM items WHERE id = ?');
      row = stmt.get(id) as ItemBase | undefined;
    }

    return row || null;
  }

  // 创建或更新数据项
  putItem(item: Partial<ItemBase> & { id: string; type: string; payload: string; content_hash: string }): { remoteRev: string } {
    this.prepareUserScope();
    const db = getDatabase();
    const now = Date.now();
    const remoteRev = now.toString();

    const existing = this.getItem(item.id);

    if (existing) {
      // 更新现有数据项
      const stmt = db.prepare(`
        UPDATE items SET
          type = ?,
          payload = ?,
          content_hash = ?,
          remote_rev = ?,
          deleted_time = ?,
          updated_time = ?,
          sync_status = ?,
          local_rev = ?,
          encryption_applied = ?,
          schema_version = ?,
          user_id = COALESCE(user_id, ?)
        WHERE id = ?
      `);

      stmt.run(
        item.type,
        item.payload,
        item.content_hash,
        remoteRev,
        item.deleted_time ?? null,
        item.updated_time ?? now,
        item.sync_status ?? 'clean',
        item.local_rev ?? existing.local_rev,
        item.encryption_applied ?? existing.encryption_applied,
        item.schema_version ?? existing.schema_version,
        this.userId || null,
        item.id
      );
    } else {
      // 创建新数据项
      const stmt = db.prepare(`
        INSERT INTO items (
          id, type, payload, content_hash, remote_rev, deleted_time,
          created_time, updated_time, sync_status, local_rev,
          encryption_applied, schema_version, user_id
        ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
      `);

      stmt.run(
        item.id,
        item.type,
        item.payload,
        item.content_hash,
        remoteRev,
        item.deleted_time ?? null,
        item.created_time ?? now,
        item.updated_time ?? now,
        item.sync_status ?? 'clean',
        item.local_rev ?? 0,
        item.encryption_applied ?? 0,
        item.schema_version ?? 1,
        this.userId || null
      );
    }

    // 记录变更
    this.changeService.recordChange({
      item_id: item.id,
      type: item.type as ItemBase['type'],
      updated_time: item.updated_time ?? now,
      deleted_time: item.deleted_time ?? null,
      content_hash: item.content_hash,
    }, this.userId);

    return { remoteRev };
  }

  // 硬删除数据项
  deleteItem(id: string): boolean {
    this.prepareUserScope();
    const db = getDatabase();
    const existing = this.getItem(id);

    if (!existing) {
      return false;
    }

    let stmt;
    if (this.userId) {
      stmt = db.prepare('DELETE FROM items WHERE id = ? AND user_id = ?');
      stmt.run(id, this.userId);
    } else {
      stmt = db.prepare('DELETE FROM items WHERE id = ?');
      stmt.run(id);
    }

    // 记录删除变更
    const now = Date.now();
    this.changeService.recordChange({
      item_id: id,
      type: existing.type,
      updated_time: now,
      deleted_time: now,
      content_hash: existing.content_hash,
    }, this.userId);

    return true;
  }

  // 批量操作
  batchPut(items: Array<Partial<ItemBase> & { id: string; type: string; payload: string; content_hash: string }>): { success: boolean; results: Array<{ id: string; remoteRev: string }> } {
    const db = getDatabase();
    const results: Array<{ id: string; remoteRev: string }> = [];

    const transaction = db.transaction(() => {
      for (const item of items) {
        const { remoteRev } = this.putItem(item);
        results.push({ id: item.id, remoteRev });
      }
    });

    transaction();

    return { success: true, results };
  }

  // 获取数据项计数
  getCount(type?: string): CountResult {
    this.prepareUserScope();
    const db = getDatabase();

    // 构建用户过滤条件
    const userFilter = this.userId 
      ? 'AND user_id = ?' 
      : '';
    const userParams = this.userId ? [this.userId] : [];

    // 总计数（不包括软删除的）
    let total: number;

    if (type) {
      const stmt = db.prepare(`SELECT COUNT(*) as count FROM items WHERE type = ? AND deleted_time IS NULL ${userFilter}`);
      total = (stmt.get(type, ...userParams) as { count: number }).count;
    } else {
      const stmt = db.prepare(`SELECT COUNT(*) as count FROM items WHERE deleted_time IS NULL ${userFilter}`);
      total = (stmt.get(...userParams) as { count: number }).count;
    }

    // 按类型统计
    const byTypeStmt = db.prepare(`
      SELECT type, COUNT(*) as count 
      FROM items 
      WHERE deleted_time IS NULL ${userFilter}
      GROUP BY type
    `);
    const byTypeRows = byTypeStmt.all(...userParams) as Array<{ type: string; count: number }>;
    const byType: Record<string, number> = {};
    for (const row of byTypeRows) {
      byType[row.type] = row.count;
    }

    return {
      hasData: total > 0,
      itemCount: total,
      byType,
    };
  }

  // 清理软删除的数据项
  cleanupSoftDeleted(before: number): number {
    this.prepareUserScope();
    const db = getDatabase();

    let stmt;
    if (this.userId) {
      stmt = db.prepare(`
        DELETE FROM items 
        WHERE deleted_time IS NOT NULL AND deleted_time < ? AND user_id = ?
      `);
      const result = stmt.run(before, this.userId);
      return result.changes;
    } else {
      stmt = db.prepare(`
        DELETE FROM items 
        WHERE deleted_time IS NOT NULL AND deleted_time < ?
      `);
      const result = stmt.run(before);
      return result.changes;
    }
  }
}

package com.mucheng.notes.data.sync

import com.mucheng.notes.data.local.dao.ItemDao
import com.mucheng.notes.data.local.dao.ResourceCacheDao
import com.mucheng.notes.data.local.entity.ResourceCacheEntity
import com.mucheng.notes.data.remote.WebDAVAdapter
import com.mucheng.notes.domain.model.payload.ResourcePayload
import kotlinx.serialization.json.Json
import java.io.File
import java.security.MessageDigest
import javax.inject.Inject
import javax.inject.Singleton

/**
 * 资源文件同步管理器
 * 
 * 负责资源文件（图片、附件等）的上传、下载和本地缓存管理。
 * 资源文件的本地路径不参与同步，使用单独的 resource_cache 表管理。
 */
@Singleton
class ResourceSyncManager @Inject constructor(
    private val webDAVAdapter: WebDAVAdapter,
    private val itemDao: ItemDao,
    private val resourceCacheDao: ResourceCacheDao,
    private val cacheDir: File
) {

    private val json = Json { ignoreUnknownKeys = true }

    /**
     * 上传本地资源到 WebDAV
     * @param resourceId items 表中的 resource 记录 ID
     */
    suspend fun uploadResource(resourceId: String): Result<Unit> {
        // 获取本地缓存路径
        val cache = resourceCacheDao.getByResourceId(resourceId)
            ?: return Result.failure(Exception("No local cache for resource: $resourceId"))

        val localFile = File(cache.localPath)
        if (!localFile.exists()) {
            return Result.failure(Exception("Local file not found: ${cache.localPath}"))
        }

        // 获取 ResourcePayload 验证哈希
        val item = itemDao.getById(resourceId)
            ?: return Result.failure(Exception("Resource item not found: $resourceId"))

        val payload = try {
            json.decodeFromString<ResourcePayload>(item.payload)
        } catch (e: Exception) {
            return Result.failure(Exception("Failed to parse ResourcePayload: ${e.message}"))
        }

        val data = localFile.readBytes()
        val hash = computeSHA256(data)

        // 验证哈希一致性
        if (hash != payload.fileHash) {
            return Result.failure(Exception("Hash mismatch: expected ${payload.fileHash}, got $hash"))
        }

        return webDAVAdapter.uploadResource(resourceId, data)
            .map { /* 上传成功 */ }
    }

    /**
     * 下载远程资源到本地缓存
     * @param resourceId items 表中的 resource 记录 ID
     */
    suspend fun downloadResource(resourceId: String): Result<File> {
        // 获取 ResourcePayload 以验证下载的文件
        val item = itemDao.getById(resourceId)
            ?: return Result.failure(Exception("Resource item not found: $resourceId"))

        val payload = try {
            json.decodeFromString<ResourcePayload>(item.payload)
        } catch (e: Exception) {
            return Result.failure(Exception("Failed to parse ResourcePayload: ${e.message}"))
        }

        val result = webDAVAdapter.downloadResource(resourceId)
        return result.mapCatching { data ->
            // 验证下载文件的哈希
            val hash = computeSHA256(data)
            if (hash != payload.fileHash) {
                throw Exception("Downloaded file hash mismatch: expected ${payload.fileHash}, got $hash")
            }

            // 确保缓存目录存在
            if (!cacheDir.exists()) {
                cacheDir.mkdirs()
            }

            // 保存到本地缓存
            val cacheFile = File(cacheDir, resourceId)
            cacheFile.writeBytes(data)

            // 更新缓存记录
            val now = System.currentTimeMillis()
            resourceCacheDao.upsert(
                ResourceCacheEntity(
                    resourceId = resourceId,
                    localPath = cacheFile.absolutePath,
                    downloadedAt = now,
                    lastAccessedAt = now
                )
            )

            cacheFile
        }
    }

    /**
     * 获取资源文件（优先本地缓存，否则下载）
     * @param resourceId items 表中的 resource 记录 ID
     */
    suspend fun getResource(resourceId: String): Result<File> {
        val cache = resourceCacheDao.getByResourceId(resourceId)
        if (cache != null) {
            val file = File(cache.localPath)
            if (file.exists()) {
                // 更新访问时间
                resourceCacheDao.upsert(
                    cache.copy(lastAccessedAt = System.currentTimeMillis())
                )
                return Result.success(file)
            }
        }
        return downloadResource(resourceId)
    }

    /**
     * 删除资源（本地缓存和远程）
     * @param resourceId items 表中的 resource 记录 ID
     */
    suspend fun deleteResource(resourceId: String): Result<Unit> {
        // 删除本地缓存
        val cache = resourceCacheDao.getByResourceId(resourceId)
        if (cache != null) {
            val file = File(cache.localPath)
            if (file.exists()) {
                file.delete()
            }
            resourceCacheDao.delete(resourceId)
        }

        // 删除远程资源
        return try {
            webDAVAdapter.deleteResource(resourceId)
            Result.success(Unit)
        } catch (e: Exception) {
            Result.failure(e)
        }
    }

    /**
     * 清理过期缓存
     * @param maxAge 最大缓存时间（毫秒），默认 7 天
     */
    suspend fun cleanupCache(maxAge: Long = 7 * 24 * 60 * 60 * 1000L) {
        val threshold = System.currentTimeMillis() - maxAge

        // 获取要删除的缓存记录
        val allCaches = resourceCacheDao.getAll()
        val expiredCaches = allCaches.filter { it.lastAccessedAt < threshold }

        // 删除文件和数据库记录
        expiredCaches.forEach { cache ->
            val file = File(cache.localPath)
            if (file.exists()) {
                file.delete()
            }
        }

        // 批量删除数据库记录
        resourceCacheDao.deleteOlderThan(threshold)

        // 清理孤立文件（数据库中没有记录的文件）
        cacheDir.listFiles()?.forEach { file ->
            val hasRecord = allCaches.any { it.resourceId == file.name }
            if (!hasRecord && System.currentTimeMillis() - file.lastModified() > maxAge) {
                file.delete()
            }
        }
    }

    /**
     * 获取缓存统计信息
     */
    suspend fun getCacheStats(): CacheStats {
        val caches = resourceCacheDao.getAll()
        var totalSize = 0L
        var fileCount = 0

        caches.forEach { cache ->
            val file = File(cache.localPath)
            if (file.exists()) {
                totalSize += file.length()
                fileCount++
            }
        }

        return CacheStats(
            fileCount = fileCount,
            totalSize = totalSize,
            recordCount = caches.size
        )
    }

    /**
     * 计算 SHA-256 哈希
     */
    private fun computeSHA256(data: ByteArray): String {
        val digest = MessageDigest.getInstance("SHA-256")
        return digest.digest(data).joinToString("") { "%02x".format(it) }
    }
}

/**
 * 缓存统计信息
 */
data class CacheStats(
    val fileCount: Int,
    val totalSize: Long,
    val recordCount: Int
)

/**
 * ExtractPagesTool - PDF 页面提取工具组件
 * 采用上下布局：上方为参数设置区，下方为页面缩略图网格
 */

import React, { useState, useCallback } from 'react';
import { 
  Card, Row, Col, Typography, Upload, Button, Space, message, 
  Input, Spin
} from 'antd';
import { 
  UploadOutlined, InboxOutlined, DownloadOutlined, ScissorOutlined
} from '@ant-design/icons';
import { pdfApi } from '../../services/pdfApi';
import PDFThumbnails from './PDFThumbnails';
import { parsePageRanges } from './utils';

const { Text } = Typography;
const { Dragger } = Upload;

// ============ 类型定义 ============

interface PDFFile {
  name: string;
  data: ArrayBuffer;
  size: number;
}

// ============ ExtractPagesTool 组件 ============

const ExtractPagesTool: React.FC = () => {
  const [pdfFile, setPdfFile] = useState<PDFFile | null>(null);
  const [totalPages, setTotalPages] = useState(0);
  const [selectedPages, setSelectedPages] = useState<number[]>([]);
  const [pageRangeInput, setPageRangeInput] = useState('');
  const [processing, setProcessing] = useState(false);
  const [previewKey, setPreviewKey] = useState(0);

  // PDF 文件上传处理
  const handlePdfUpload = useCallback(async (file: File): Promise<boolean> => {
    if (!file.name.toLowerCase().endsWith('.pdf')) {
      message.error('请上传 PDF 文件');
      return false;
    }

    try {
      const arrayBuffer = await file.arrayBuffer();

      // 复制 ArrayBuffer 以避免 detached 问题
      const bufferCopy = arrayBuffer.slice(0);

      const header = new Uint8Array(bufferCopy.slice(0, 5));
      const pdfHeader = String.fromCharCode(...header);
      if (!pdfHeader.startsWith('%PDF-')) {
        message.error('无效的 PDF 文件');
        return false;
      }

      const info = await pdfApi.getInfo(bufferCopy.slice(0));

      setPdfFile({
        name: file.name,
        data: bufferCopy,
        size: file.size,
      });
      setTotalPages(info.pageCount);
      setSelectedPages([]);
      setPageRangeInput('');
      setPreviewKey(prev => prev + 1);

      message.success(`已加载: ${file.name} (${info.pageCount} 页)`);
      return true;
    } catch (error) {
      console.error('Failed to load PDF:', error);
      message.error('PDF 加载失败');
      return false;
    }
  }, []);

  // 处理页面选择
  const handlePageSelect = useCallback((pages: number[]) => {
    setSelectedPages(pages);
    setPageRangeInput(pages.join(', '));
  }, []);

  // 处理页面范围输入变化
  const handlePageRangeChange = useCallback((value: string) => {
    setPageRangeInput(value);
    const pages = parsePageRanges(value, totalPages);
    setSelectedPages(pages);
  }, [totalPages]);

  // 执行提取
  const handleExtract = useCallback(async () => {
    if (!pdfFile) {
      message.warning('请先上传 PDF 文件');
      return;
    }

    if (selectedPages.length === 0) {
      message.warning('请选择要提取的页面');
      return;
    }

    setProcessing(true);

    try {
      // 复制 ArrayBuffer 以避免 detached 问题
      const result = await pdfApi.extractPages({
        file: pdfFile.data.slice(0),
        pages: selectedPages,
      });

      // 下载提取的 PDF
      const blob = new Blob([result], { type: 'application/pdf' });
      const url = URL.createObjectURL(blob);
      const a = document.createElement('a');
      a.href = url;
      a.download = pdfFile.name.replace('.pdf', `_pages_${selectedPages.join('-')}.pdf`);
      document.body.appendChild(a);
      a.click();
      document.body.removeChild(a);
      URL.revokeObjectURL(url);

      message.success(`已提取 ${selectedPages.length} 页`);
    } catch (error) {
      console.error('Extract failed:', error);
      message.error('提取失败: ' + (error as Error).message);
    } finally {
      setProcessing(false);
    }
  }, [pdfFile, selectedPages]);

  // 未上传文件时显示上传区域
  if (!pdfFile) {
    return (
      <div style={{ padding: 24 }}>
        <Dragger
          accept=".pdf"
          showUploadList={false}
          beforeUpload={handlePdfUpload}
          style={{ padding: 40 }}
        >
          <p className="ant-upload-drag-icon">
            <InboxOutlined style={{ fontSize: 48, color: '#1890ff' }} />
          </p>
          <p className="ant-upload-text">点击或拖拽 PDF 文件到此处</p>
          <p className="ant-upload-hint">从 PDF 中提取指定页面生成新文件</p>
        </Dragger>
      </div>
    );
  }

  return (
    <div>
      {/* 上方：参数设置区 */}
      <Card size="small" style={{ marginBottom: 12 }}>
        <Row gutter={16} align="middle">
          <Col span={5}>
            <Space>
              <Upload accept=".pdf" showUploadList={false} beforeUpload={handlePdfUpload}>
                <Button icon={<UploadOutlined />} size="small">更换文件</Button>
              </Upload>
              <Text ellipsis style={{ maxWidth: 100 }}>{pdfFile.name}</Text>
            </Space>
          </Col>
          <Col span={6}>
            <Text type="secondary">页面范围：</Text>
            <Input
              value={pageRangeInput}
              onChange={(e) => handlePageRangeChange(e.target.value)}
              placeholder="如: 1,3,5-7"
              size="small"
              style={{ width: 120 }}
            />
          </Col>
          <Col span={5}>
            <Text type="secondary">
              已选择 {selectedPages.length}/{totalPages} 页
            </Text>
          </Col>
          <Col span={8} style={{ textAlign: 'right' }}>
            <Button 
              type="primary"
              icon={<ScissorOutlined />} 
              onClick={handleExtract}
              loading={processing}
              disabled={selectedPages.length === 0}
            >
              提取并下载
            </Button>
          </Col>
        </Row>
      </Card>

      {/* 下方：页面缩略图网格 */}
      <Card 
        size="small" 
        title="页面缩略图"
        extra={<Text type="secondary">点击选择要提取的页面</Text>}
        style={{ height: 'calc(100vh - 280px)' }}
        styles={{ body: { height: 'calc(100% - 40px)', overflow: 'auto', padding: 12 } }}
      >
        <Spin spinning={processing}>
          <PDFThumbnails
            key={previewKey}
            pdfData={pdfFile.data}
            selectedPages={selectedPages}
            onPageSelect={handlePageSelect}
            multiSelect={true}
          />
        </Spin>
      </Card>
    </div>
  );
};

export default ExtractPagesTool;

/**
 * Image API - 渲染进程图片处理接口
 */

// ============ 类型定义 ============

export interface ImageMetadata {
