import * as crypto from 'crypto';
import { CryptoEngine } from '../crypto/CryptoEngine';

export interface LockConfig {
  enabled: boolean;
  type: 'pin' | 'password';
  autoLockTimeout: number;  // 分钟，0 表示不自动锁定
  lockOnMinimize: boolean;
  lockOnScreenLock: boolean;
}

export interface LockState {
  isLocked: boolean;
  lastUnlockTime: number | null;
  failedAttempts: number;
  lockedUntil: number | null;  // 多次失败后的锁定时间
}

export class AppLock {
  private config: LockConfig;
  private state: LockState;
  private passwordHash: string | null = null;
  private salt: string | null = null;
  private cryptoEngine: CryptoEngine;
  private autoLockTimer: NodeJS.Timeout | null = null;
  private onLockCallback: (() => void) | null = null;

  constructor(cryptoEngine: CryptoEngine) {
    this.cryptoEngine = cryptoEngine;
    this.config = {
      enabled: false,
      type: 'password',
      autoLockTimeout: 5,
      lockOnMinimize: false,
      lockOnScreenLock: true,
    };
    this.state = {
      isLocked: false,
      lastUnlockTime: null,
      failedAttempts: 0,
      lockedUntil: null,
    };
  }

  // 设置锁定密码
  setPassword(password: string): void {
    this.salt = crypto.randomBytes(32).toString('hex');
    this.passwordHash = this.hashPassword(password, this.salt);
    this.config.enabled = true;
  }

  // 验证密码
  verifyPassword(password: string): boolean {
    if (!this.passwordHash || !this.salt) return false;

    // 检查是否被临时锁定
    if (this.state.lockedUntil && Date.now() < this.state.lockedUntil) {
      return false;
    }

    const hash = this.hashPassword(password, this.salt);
    const isValid = hash === this.passwordHash;

    if (isValid) {
      this.state.failedAttempts = 0;
      this.state.lockedUntil = null;
    } else {
      this.state.failedAttempts++;
      // 5次失败后锁定5分钟
      if (this.state.failedAttempts >= 5) {
        this.state.lockedUntil = Date.now() + 5 * 60 * 1000;
      }
    }

    return isValid;
  }

  // 修改密码
  changePassword(oldPassword: string, newPassword: string): boolean {
    if (!this.verifyPassword(oldPassword)) {
      return false;
    }
    this.setPassword(newPassword);
    return true;
  }

  // 移除密码保护
  removePassword(password: string): boolean {
    if (!this.verifyPassword(password)) {
      return false;
    }
    this.passwordHash = null;
    this.salt = null;
    this.config.enabled = false;
    return true;
  }

  // 锁定应用
  lock(): void {
    if (!this.config.enabled) return;
    this.state.isLocked = true;
    this.stopAutoLockTimer();
    this.onLockCallback?.();
  }

  // 解锁应用
  unlock(password: string): boolean {
    if (!this.config.enabled) {
      this.state.isLocked = false;
      return true;
    }

    if (this.verifyPassword(password)) {
      this.state.isLocked = false;
      this.state.lastUnlockTime = Date.now();
      this.startAutoLockTimer();
      return true;
    }

    return false;
  }

  // 获取锁定状态
  getState(): LockState {
    return { ...this.state };
  }

  // 获取配置
  getConfig(): LockConfig {
    return { ...this.config };
  }

  // 更新配置
  updateConfig(config: Partial<LockConfig>): void {
    this.config = { ...this.config, ...config };

    if (this.config.autoLockTimeout > 0 && !this.state.isLocked) {
      this.startAutoLockTimer();
    } else {
      this.stopAutoLockTimer();
    }
  }

  // 设置锁定回调
  onLock(callback: () => void): void {
    this.onLockCallback = callback;
  }

  // 重置活动计时器（用户有操作时调用）
  resetActivityTimer(): void {
    if (this.config.enabled && this.config.autoLockTimeout > 0 && !this.state.isLocked) {
      this.startAutoLockTimer();
    }
  }

  // 获取剩余锁定时间
  getRemainingLockTime(): number {
    if (!this.state.lockedUntil) return 0;
    return Math.max(0, this.state.lockedUntil - Date.now());
  }

  // 导出锁定配置（不包含密码）
  exportConfig(): { config: LockConfig; hasPassword: boolean } {
    return {
      config: this.config,
      hasPassword: !!this.passwordHash,
    };
  }

  // 导入锁定配置
  importConfig(config: LockConfig): void {
    this.config = config;
  }

  // 哈希密码
  private hashPassword(password: string, salt: string): string {
    return crypto.pbkdf2Sync(password, salt, 100000, 64, 'sha512').toString('hex');
  }

  // 启动自动锁定计时器
  private startAutoLockTimer(): void {
    this.stopAutoLockTimer();

    if (this.config.autoLockTimeout <= 0) return;

    const timeout = this.config.autoLockTimeout * 60 * 1000;
    this.autoLockTimer = setTimeout(() => {
      this.lock();
    }, timeout);
  }

  // 停止自动锁定计时器
  private stopAutoLockTimer(): void {
    if (this.autoLockTimer) {
      clearTimeout(this.autoLockTimer);
      this.autoLockTimer = null;
    }
  }
}

export default AppLock;

import * as fs from 'fs';
import * as path from 'path';
import * as crypto from 'crypto';
import { v4 as uuidv4 } from 'uuid';
import { ItemsManager } from '../database/ItemsManager';
import { ResourcePayload } from '@shared/types';

export class ResourceManager {
  private resourcesDir: string;
  private itemsManager: ItemsManager;

  constructor(userDataPath: string, itemsManager: ItemsManager) {
    this.resourcesDir = path.join(userDataPath, 'resources');
    this.itemsManager = itemsManager;
    this.ensureResourcesDir();
  }

  private ensureResourcesDir(): void {
    if (!fs.existsSync(this.resourcesDir)) {
      fs.mkdirSync(this.resourcesDir, { recursive: true });
    }
  }

  // 计算文件哈希
  private computeFileHash(buffer: Buffer): string {
    return crypto.createHash('sha256').update(buffer).digest('hex');
  }

  // 获取文件扩展名
  private getExtension(filename: string): string {
    const ext = path.extname(filename);
    return ext ? ext.toLowerCase() : '';
  }

  // 保存资源文件
  async saveResource(
    buffer: Buffer,
    filename: string,
    mimeType: string,
    noteId: string
  ): Promise<{ id: string; path: string }> {
    const fileHash = this.computeFileHash(buffer);
    const ext = this.getExtension(filename);
    const resourceId = uuidv4();
    const resourceFilename = `${resourceId}${ext}`;
    const resourcePath = path.join(this.resourcesDir, resourceFilename);

    // 写入文件
    fs.writeFileSync(resourcePath, buffer);

    // 创建资源记录
    const payload: ResourcePayload = {
      filename,
      mime_type: mimeType,
      size: buffer.length,
      note_id: noteId,
      file_hash: fileHash,
    };

    this.itemsManager.create('resource', payload);

    return { id: resourceId, path: resourcePath };
  }

  // 从剪贴板保存图片
  async saveFromClipboard(
    base64Data: string,
    noteId: string
  ): Promise<{ id: string; path: string; markdownRef: string }> {
    // 解析 base64 数据
    const matches = base64Data.match(/^data:(.+);base64,(.+)$/);
    if (!matches) {
      throw new Error('Invalid base64 data');
    }

    const mimeType = matches[1];
    const data = matches[2];
    const buffer = Buffer.from(data, 'base64');

    // 根据 MIME 类型确定扩展名
    const extMap: Record<string, string> = {
      'image/png': '.png',
      'image/jpeg': '.jpg',
      'image/gif': '.gif',
      'image/webp': '.webp',
    };
    const ext = extMap[mimeType] || '.png';
    const filename = `clipboard-${Date.now()}${ext}`;

    const result = await this.saveResource(buffer, filename, mimeType, noteId);
    const markdownRef = `![${filename}](resource://${result.id}${ext})`;

    return { ...result, markdownRef };
  }

  // 从文件路径保存
  async saveFromFile(
    filePath: string,
    noteId: string
  ): Promise<{ id: string; path: string; markdownRef: string }> {
    const buffer = fs.readFileSync(filePath);
    const filename = path.basename(filePath);
    const mimeType = this.getMimeType(filename);

    const result = await this.saveResource(buffer, filename, mimeType, noteId);
    const ext = this.getExtension(filename);
    const markdownRef = `![${filename}](resource://${result.id}${ext})`;

    return { ...result, markdownRef };
  }

  // 获取资源文件路径
  getResourcePath(resourceId: string, ext: string = ''): string {
    return path.join(this.resourcesDir, `${resourceId}${ext}`);
  }

  // 读取资源文件
  readResource(resourceId: string, ext: string = ''): Buffer | null {
    const resourcePath = this.getResourcePath(resourceId, ext);
    if (fs.existsSync(resourcePath)) {
      return fs.readFileSync(resourcePath);
    }
    return null;
  }

  // 删除资源文件
  deleteResource(resourceId: string, ext: string = ''): boolean {
    const resourcePath = this.getResourcePath(resourceId, ext);
    if (fs.existsSync(resourcePath)) {
      fs.unlinkSync(resourcePath);
      return true;
    }
    return false;
  }

  // 获取笔记的所有资源
  getNoteResources(noteId: string): string[] {
    const resources = this.itemsManager.getByType('resource');
    return resources
      .filter(r => {
        const payload = JSON.parse(r.payload) as ResourcePayload;
        return payload.note_id === noteId;
      })
      .map(r => r.id);
  }

  // 验证资源完整性
  verifyResource(resourceId: string, ext: string = ''): boolean {
    const item = this.itemsManager.getById(resourceId);
    if (!item) return false;

    const payload = JSON.parse(item.payload) as ResourcePayload;
    const buffer = this.readResource(resourceId, ext);
    if (!buffer) return false;

    const currentHash = this.computeFileHash(buffer);
    return currentHash === payload.file_hash;
  }

  // 获取 MIME 类型
  private getMimeType(filename: string): string {
    const ext = this.getExtension(filename);
    const mimeTypes: Record<string, string> = {
      '.png': 'image/png',
      '.jpg': 'image/jpeg',
      '.jpeg': 'image/jpeg',
      '.gif': 'image/gif',
      '.webp': 'image/webp',
      '.pdf': 'application/pdf',
      '.doc': 'application/msword',
      '.docx': 'application/vnd.openxmlformats-officedocument.wordprocessingml.document',
      '.txt': 'text/plain',
      '.md': 'text/markdown',
    };
    return mimeTypes[ext] || 'application/octet-stream';
  }

  // 获取资源统计
  getStats(): { count: number; totalSize: number } {
    const resources = this.itemsManager.getByType('resource');
    let totalSize = 0;

    for (const resource of resources) {
      const payload = JSON.parse(resource.payload) as ResourcePayload;
      totalSize += payload.size;
    }

    return { count: resources.length, totalSize };
  }
}

export default ResourceManager;

package com.mucheng.notes.data.sync

import android.content.Context
import android.net.ConnectivityManager
import android.net.Network
import android.net.NetworkCapabilities
import android.net.NetworkRequest
import androidx.core.content.getSystemService
import com.mucheng.notes.domain.repository.SyncRepository
import dagger.hilt.android.qualifiers.ApplicationContext
import kotlinx.coroutines.CoroutineScope
import kotlinx.coroutines.Dispatchers
import kotlinx.coroutines.SupervisorJob
import kotlinx.coroutines.channels.awaitClose
import kotlinx.coroutines.flow.Flow
import kotlinx.coroutines.flow.MutableStateFlow
import kotlinx.coroutines.flow.StateFlow
import kotlinx.coroutines.flow.asStateFlow
import kotlinx.coroutines.flow.callbackFlow
import kotlinx.coroutines.launch
import javax.inject.Inject
import javax.inject.Singleton

/**
 * 离线队列管理器接口
 */
interface OfflineQueueManager {
    /**
     * 检查当前是否在线
     */
    fun isOnline(): Boolean

    /**
     * 观察网络连接状态
     */
    fun observeConnectivity(): Flow<Boolean>

    /**
     * 获取当前连接状态
     */
    fun getConnectivityState(): StateFlow<Boolean>

    /**
     * 处理队列（网络恢复时自动触发同步）
     */
    suspend fun processQueue()

    /**
     * 启动网络监听
     */
    fun startMonitoring()

    /**
     * 停止网络监听
     */
    fun stopMonitoring()
}

/**
 * 离线队列管理器实现
 * 
 * 监听网络状态变化，在网络恢复时自动触发同步。
 */
@Singleton
class OfflineQueueManagerImpl @Inject constructor(
    @ApplicationContext private val context: Context
) : OfflineQueueManager {

    private val connectivityManager = context.getSystemService<ConnectivityManager>()
    private val scope = CoroutineScope(SupervisorJob() + Dispatchers.IO)

    private val _connectivityState = MutableStateFlow(checkNetworkAvailable())

    private var networkCallback: ConnectivityManager.NetworkCallback? = null
    private var syncRepository: SyncRepository? = null

    /**
     * 设置 SyncRepository（避免循环依赖）
     */
    fun setSyncRepository(repository: SyncRepository) {
        syncRepository = repository
    }

    override fun isOnline(): Boolean = checkNetworkAvailable()

    override fun observeConnectivity(): Flow<Boolean> = callbackFlow {
        val callback = object : ConnectivityManager.NetworkCallback() {
            override fun onAvailable(network: Network) {
                trySend(true)
                // 网络恢复时自动触发同步
                scope.launch {
                    processQueue()
                }
            }

            override fun onLost(network: Network) {
                trySend(false)
            }

            override fun onCapabilitiesChanged(
                network: Network,
                networkCapabilities: NetworkCapabilities
            ) {
                val hasInternet = networkCapabilities.hasCapability(
                    NetworkCapabilities.NET_CAPABILITY_INTERNET
                )
                trySend(hasInternet)
            }
        }

        val request = NetworkRequest.Builder()
            .addCapability(NetworkCapabilities.NET_CAPABILITY_INTERNET)
            .build()

        connectivityManager?.registerNetworkCallback(request, callback)

        // 发送初始状态
        trySend(checkNetworkAvailable())

        awaitClose {
            connectivityManager?.unregisterNetworkCallback(callback)
        }
    }

    override fun getConnectivityState(): StateFlow<Boolean> = _connectivityState.asStateFlow()

    override suspend fun processQueue() {
        if (isOnline()) {
            try {
                syncRepository?.sync()
            } catch (e: Exception) {
                // 同步失败，下次网络恢复时重试
            }
        }
    }

    override fun startMonitoring() {
        if (networkCallback != null) return

        networkCallback = object : ConnectivityManager.NetworkCallback() {
            override fun onAvailable(network: Network) {
                _connectivityState.value = true
                // 网络恢复时自动触发同步
                scope.launch {
                    processQueue()
                }
            }

            override fun onLost(network: Network) {
                _connectivityState.value = false
            }

            override fun onCapabilitiesChanged(
                network: Network,
                networkCapabilities: NetworkCapabilities
            ) {
                val hasInternet = networkCapabilities.hasCapability(
                    NetworkCapabilities.NET_CAPABILITY_INTERNET
                )
                _connectivityState.value = hasInternet
            }
        }

        val request = NetworkRequest.Builder()
            .addCapability(NetworkCapabilities.NET_CAPABILITY_INTERNET)
            .build()

        connectivityManager?.registerNetworkCallback(request, networkCallback!!)
    }

    override fun stopMonitoring() {
        networkCallback?.let {
            connectivityManager?.unregisterNetworkCallback(it)
            networkCallback = null
        }
    }

    /**
     * 检查网络是否可用
     */
    private fun checkNetworkAvailable(): Boolean {
        val network = connectivityManager?.activeNetwork ?: return false
        val capabilities = connectivityManager.getNetworkCapabilities(network) ?: return false

        return capabilities.hasCapability(NetworkCapabilities.NET_CAPABILITY_INTERNET) &&
               capabilities.hasCapability(NetworkCapabilities.NET_CAPABILITY_VALIDATED)
    }
}

import { ItemBase, ItemType, NotePayload, FolderPayload, TagPayload } from '@shared/types';

// 获取 electronAPI（通过 preload 暴露）
const getElectronAPI = () => {
  if (typeof window !== 'undefined' && (window as any).electronAPI) {
    return (window as any).electronAPI;
  }
  return null;
};

// 通用 Items API
export const itemsApi = {
  create: <T extends object>(type: ItemType, payload: T): Promise<ItemBase> => {
    const api = getElectronAPI();
    return api?.items?.create(type, payload) ?? Promise.resolve(null as any);
  },

  getById: (id: string): Promise<ItemBase | undefined> => {
    const api = getElectronAPI();
    return api?.items?.getById(id) ?? Promise.resolve(undefined);
  },

  getByIdIncludeDeleted: (id: string): Promise<ItemBase | undefined> => {
    const api = getElectronAPI();
    return api?.items?.getByIdIncludeDeleted(id) ?? Promise.resolve(undefined);
  },

  getByType: (type: ItemType): Promise<ItemBase[]> => {
    const api = getElectronAPI();
    return api?.items?.getByType(type) ?? Promise.resolve([]);
  },

  update: <T extends object>(id: string, payload: T): Promise<ItemBase | undefined> => {
    const api = getElectronAPI();
    return api?.items?.update(id, payload) ?? Promise.resolve(undefined);
  },

  delete: (id: string): Promise<boolean> => {
    const api = getElectronAPI();
    return api?.items?.delete(id) ?? Promise.resolve(false);
  },

  hardDelete: (id: string): Promise<boolean> => {
    const api = getElectronAPI();
    return api?.items?.hardDelete(id) ?? Promise.resolve(false);
  },

  restore: (id: string): Promise<boolean> => {
    const api = getElectronAPI();
    return api?.items?.restore(id) ?? Promise.resolve(false);
  },

  search: (query: string, type?: ItemType): Promise<ItemBase[]> => {
    const api = getElectronAPI();
    return api?.items?.search(query, type) ?? Promise.resolve([]);
  },

  getDeleted: (type?: ItemType): Promise<ItemBase[]> => {
    const api = getElectronAPI();
    return api?.items?.getDeleted(type) ?? Promise.resolve([]);
  },

  getStats: (): Promise<{ total: number; byType: Record<string, number> }> => {
    const api = getElectronAPI();
    return api?.items?.getStats() ?? Promise.resolve({ total: 0, byType: {} });
  },
};

// 笔记专用 API
export const notesApi = {
  create: (payload: NotePayload): Promise<ItemBase> =>
    itemsApi.create('note', payload),

  getAll: (): Promise<ItemBase[]> =>
    itemsApi.getByType('note'),

  getByFolder: (folderId: string | null): Promise<ItemBase[]> => {
    const api = getElectronAPI();
    return api?.items?.getNotesByFolder(folderId) ?? Promise.resolve([]);
  },

  // 获取所有笔记（包括普通笔记和 Excel 笔记）
  getAllWithExcel: async (folderId: string | null): Promise<ItemBase[]> => {
    const api = getElectronAPI();
    if (!api?.items) return [];

    // 获取普通笔记
    const notes = await (api.items.getNotesByFolder(folderId) ?? Promise.resolve([]));

    // 获取 Excel 笔记
    const excelNotes = await (api.items.getByType('excel_note') ?? Promise.resolve([]));

    // 过滤 Excel 笔记（按文件夹）
    const filteredExcelNotes = excelNotes.filter((item: ItemBase) => {
      try {
        const payload = JSON.parse(item.payload);
        if (folderId === null) return true; // 所有笔记
        if (folderId === 'uncategorized') return !payload.folder_id;
        return payload.folder_id === folderId;
      } catch {
        return false;
      }
    });

    return [...notes, ...filteredExcelNotes];
  },

  getPinned: (): Promise<ItemBase[]> => {
    const api = getElectronAPI();
    return api?.items?.getPinnedNotes() ?? Promise.resolve([]);
  },

  // 获取所有置顶笔记（包括 Excel）
  getPinnedWithExcel: async (): Promise<ItemBase[]> => {
    const api = getElectronAPI();
    if (!api?.items) return [];

    const pinnedNotes = await (api.items.getPinnedNotes() ?? Promise.resolve([]));
    const excelNotes = await (api.items.getByType('excel_note') ?? Promise.resolve([]));

    const pinnedExcelNotes = excelNotes.filter((item: ItemBase) => {
      try {
        const payload = JSON.parse(item.payload);
        return payload.is_pinned === true;
      } catch {
        return false;
      }
    });

    return [...pinnedNotes, ...pinnedExcelNotes];
  },

  update: (id: string, payload: NotePayload): Promise<ItemBase | undefined> =>
    itemsApi.update(id, payload),

  delete: (id: string): Promise<boolean> =>
    itemsApi.delete(id),

  search: (query: string): Promise<ItemBase[]> =>
    itemsApi.search(query, 'note'),
};

// 文件夹专用 API
export const foldersApi = {
  create: (payload: FolderPayload): Promise<ItemBase> =>
    itemsApi.create('folder', payload),

