export const auditService = new AuditService();

import fs from 'fs';
import path from 'path';
import { config } from '../config';
import { getDatabase } from '../database';
import { userService } from './UserService';

const RESOURCE_ID_PATTERN = /^[A-Za-z0-9._-]{1,255}$/;

export class ResourceService {
  private resourceDir: string;
  private userId?: string;

  constructor(userId?: string) {
    this.resourceDir = config.resourcesPath;
    this.userId = userId;
    this.ensureDir();
  }

  private ensureDir(): void {
    if (!fs.existsSync(this.resourceDir)) {
      fs.mkdirSync(this.resourceDir, { recursive: true });
    }
  }

  private isValidResourceId(id: string): boolean {
    return RESOURCE_ID_PATTERN.test(id) && !id.includes('..');
  }

  private getResourcePath(id: string): string {
    if (!this.isValidResourceId(id)) {
      throw new Error('Invalid resource id');
    }

    // 使用 ID 前两位作为子目录，避免单目录文件过多
    const subDir = id.substring(0, 2);

    // 如果有用户 ID，在用户目录下存储
    let dir: string;
    if (this.userId) {
      dir = path.join(this.resourceDir, 'users', this.userId, subDir);
    } else {
      // 向后兼容：无用户隔离时使用共享目录
      dir = path.join(this.resourceDir, 'shared', subDir);
    }

    if (!fs.existsSync(dir)) {
      fs.mkdirSync(dir, { recursive: true });
    }
    return path.join(dir, id);
  }

  private getItemIdFromResourceName(id: string): string {
    const ext = path.extname(id);
    return ext ? id.slice(0, -ext.length) : id;
  }

  private canAccessResource(id: string): boolean {
    if (!this.isValidResourceId(id)) {
      return false;
    }

    if (!this.userId) {
      return true;
    }

    userService.claimLegacyDataForSingleUser(this.userId);
    const itemId = this.getItemIdFromResourceName(id);
    const db = getDatabase();
    const row = db
      .prepare('SELECT id FROM items WHERE id = ? AND type = ? AND user_id = ?')
      .get(itemId, 'resource', this.userId) as { id: string } | undefined;

    return !!row;
  }

  // 获取资源文件（支持向后兼容）
  getResource(id: string): Buffer | null {
    if (!this.canAccessResource(id)) {
      return null;
    }

    // 首先尝试用户目录
    const userPath = this.getResourcePath(id);
    if (fs.existsSync(userPath)) {
      return fs.readFileSync(userPath);
    }

    // 向后兼容：尝试旧的共享目录结构
    const subDir = id.substring(0, 2);
    const legacyPath = path.join(this.resourceDir, subDir, id);
    if (fs.existsSync(legacyPath)) {
      return fs.readFileSync(legacyPath);
    }

    // 尝试 shared 目录
    const sharedPath = path.join(this.resourceDir, 'shared', subDir, id);
    if (fs.existsSync(sharedPath)) {
      return fs.readFileSync(sharedPath);
    }

    return null;
  }

  // 保存资源文件
  putResource(id: string, data: Buffer): boolean {
    if (!this.canAccessResource(id)) {
      return false;
    }

    const filePath = this.getResourcePath(id);
    fs.writeFileSync(filePath, data);
    return true;
  }

  // 删除资源文件
  deleteResource(id: string): boolean {
    if (!this.canAccessResource(id)) {
      return false;
    }

    // 首先尝试用户目录
    const userPath = this.getResourcePath(id);
    if (fs.existsSync(userPath)) {
      fs.unlinkSync(userPath);
      return true;
    }

    // 向后兼容：尝试旧的共享目录结构
    const subDir = id.substring(0, 2);
    const legacyPath = path.join(this.resourceDir, subDir, id);
    if (fs.existsSync(legacyPath)) {
      fs.unlinkSync(legacyPath);
      return true;
    }

    // 尝试 shared 目录
    const sharedPath = path.join(this.resourceDir, 'shared', subDir, id);
    if (fs.existsSync(sharedPath)) {
      fs.unlinkSync(sharedPath);
      return true;
    }

    return false;
  }

  // 获取存储统计
  getStorageStats(): { used: number; fileCount: number } {
    let used = 0;
    let fileCount = 0;

    const walkDir = (dir: string): void => {
      if (!fs.existsSync(dir)) return;

      const entries = fs.readdirSync(dir, { withFileTypes: true });
      for (const entry of entries) {
        const fullPath = path.join(dir, entry.name);
        if (entry.isDirectory()) {
          walkDir(fullPath);
        } else if (entry.isFile()) {
          const stats = fs.statSync(fullPath);
          used += stats.size;
          fileCount++;
        }
      }
    };

    // 如果有用户 ID，只统计用户目录
    if (this.userId) {
      walkDir(path.join(this.resourceDir, 'users', this.userId));
    } else {
      walkDir(this.resourceDir);
    }

    return { used, fileCount };
  }
}

/**
 * LAN Transfer Assistant - 通知服务
 */

package com.mucheng.notes.service

import android.app.NotificationChannel
import android.app.NotificationManager
import android.app.PendingIntent
import android.content.Context
import android.content.Intent
import android.os.Build
import androidx.core.app.NotificationCompat
import androidx.core.app.NotificationManagerCompat
import com.mucheng.notes.R
import com.mucheng.notes.presentation.MainActivity

/**
 * 传输通知服务
 */
object TransferNotificationService {

    private const val CHANNEL_ID = "transfer_channel"
    private const val CHANNEL_NAME = "传输助手"
    private const val CHANNEL_DESCRIPTION = "传输助手消息通知"

    private const val NOTIFICATION_ID_MESSAGE = 1001
    private const val NOTIFICATION_ID_FILE = 1002
    private const val NOTIFICATION_ID_TRANSFER_PROGRESS = 1003

    /**
     * 创建通知渠道
     */
    fun createNotificationChannel(context: Context) {
        if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.O) {
            val importance = NotificationManager.IMPORTANCE_DEFAULT
            val channel = NotificationChannel(CHANNEL_ID, CHANNEL_NAME, importance).apply {
                description = CHANNEL_DESCRIPTION
                enableVibration(true)
                setShowBadge(true)
            }

            val notificationManager = context.getSystemService(Context.NOTIFICATION_SERVICE) as NotificationManager
            notificationManager.createNotificationChannel(channel)
        }
    }

    /**
     * 显示新消息通知
     */
    fun showMessageNotification(
        context: Context,
        senderName: String,
        messageContent: String,
        sessionId: String
    ) {
        createNotificationChannel(context)

        val intent = Intent(context, MainActivity::class.java).apply {
            flags = Intent.FLAG_ACTIVITY_NEW_TASK or Intent.FLAG_ACTIVITY_CLEAR_TOP
            putExtra("navigate_to", "transfer")
            putExtra("session_id", sessionId)
        }

        val pendingIntent = PendingIntent.getActivity(
            context,
            0,
            intent,
            PendingIntent.FLAG_UPDATE_CURRENT or PendingIntent.FLAG_IMMUTABLE
        )

        val notification = NotificationCompat.Builder(context, CHANNEL_ID)
            .setSmallIcon(R.drawable.ic_launcher_foreground)
            .setContentTitle(senderName)
            .setContentText(messageContent)
            .setPriority(NotificationCompat.PRIORITY_DEFAULT)
            .setAutoCancel(true)
            .setContentIntent(pendingIntent)
            .setCategory(NotificationCompat.CATEGORY_MESSAGE)
            .build()

        try {
            NotificationManagerCompat.from(context).notify(NOTIFICATION_ID_MESSAGE, notification)
        } catch (e: SecurityException) {
            // 没有通知权限
            android.util.Log.w("TransferNotification", "No notification permission")
        }
    }

    /**
     * 显示文件接收通知
     */
    fun showFileReceivedNotification(
        context: Context,
        senderName: String,
        filename: String,
        sessionId: String
    ) {
        createNotificationChannel(context)

        val intent = Intent(context, MainActivity::class.java).apply {
            flags = Intent.FLAG_ACTIVITY_NEW_TASK or Intent.FLAG_ACTIVITY_CLEAR_TOP
            putExtra("navigate_to", "transfer")
            putExtra("session_id", sessionId)
        }

        val pendingIntent = PendingIntent.getActivity(
            context,
            0,
            intent,
            PendingIntent.FLAG_UPDATE_CURRENT or PendingIntent.FLAG_IMMUTABLE
        )

        val notification = NotificationCompat.Builder(context, CHANNEL_ID)
            .setSmallIcon(R.drawable.ic_launcher_foreground)
            .setContentTitle("收到文件")
            .setContentText("$senderName 发送了文件: $filename")
            .setPriority(NotificationCompat.PRIORITY_DEFAULT)
            .setAutoCancel(true)
            .setContentIntent(pendingIntent)
            .setCategory(NotificationCompat.CATEGORY_MESSAGE)
            .build()

        try {
            NotificationManagerCompat.from(context).notify(NOTIFICATION_ID_FILE, notification)
        } catch (e: SecurityException) {
            android.util.Log.w("TransferNotification", "No notification permission")
        }
    }

    /**
     * 显示文件传输进度通知
     */
    fun showTransferProgressNotification(
        context: Context,
        filename: String,
        progress: Int,
        isUpload: Boolean
    ) {
        createNotificationChannel(context)

        val title = if (isUpload) "正在发送文件" else "正在接收文件"

        val notification = NotificationCompat.Builder(context, CHANNEL_ID)
            .setSmallIcon(R.drawable.ic_launcher_foreground)
            .setContentTitle(title)
            .setContentText(filename)
            .setPriority(NotificationCompat.PRIORITY_LOW)
            .setProgress(100, progress, false)
            .setOngoing(true)
            .setCategory(NotificationCompat.CATEGORY_PROGRESS)
            .build()

        try {
            NotificationManagerCompat.from(context).notify(NOTIFICATION_ID_TRANSFER_PROGRESS, notification)
        } catch (e: SecurityException) {
            android.util.Log.w("TransferNotification", "No notification permission")
        }
    }

    /**
     * 取消传输进度通知
     */
    fun cancelTransferProgressNotification(context: Context) {
        NotificationManagerCompat.from(context).cancel(NOTIFICATION_ID_TRANSFER_PROGRESS)
    }

    /**
     * 取消所有通知
     */
    fun cancelAllNotifications(context: Context) {
        NotificationManagerCompat.from(context).cancelAll()
    }
}

package com.mucheng.notes.security

import android.content.Context
import android.content.SharedPreferences
import androidx.biometric.BiometricPrompt
import androidx.core.content.ContextCompat
import androidx.fragment.app.FragmentActivity
import dagger.hilt.android.qualifiers.ApplicationContext
import kotlinx.coroutines.suspendCancellableCoroutine
import javax.inject.Inject
import javax.inject.Singleton
import kotlin.coroutines.resume
import androidx.biometric.BiometricManager as AndroidBiometricManager

/**
 * BiometricManager 实现
 */
@Singleton
class BiometricManagerImpl @Inject constructor(
    @ApplicationContext private val context: Context
) : BiometricManager {

    companion object {
        private const val PREFS_NAME = "biometric_prefs"
        private const val KEY_BIOMETRIC_ENABLED = "biometric_enabled"
    }

    private val prefs: SharedPreferences by lazy {
        context.getSharedPreferences(PREFS_NAME, Context.MODE_PRIVATE)
    }

    private val androidBiometricManager: AndroidBiometricManager by lazy {
        AndroidBiometricManager.from(context)
    }

    override fun canAuthenticate(): BiometricStatus {
        return when (androidBiometricManager.canAuthenticate(
            AndroidBiometricManager.Authenticators.BIOMETRIC_STRONG
        )) {
            AndroidBiometricManager.BIOMETRIC_SUCCESS -> BiometricStatus.AVAILABLE
            AndroidBiometricManager.BIOMETRIC_ERROR_NO_HARDWARE -> BiometricStatus.NO_HARDWARE
            AndroidBiometricManager.BIOMETRIC_ERROR_HW_UNAVAILABLE -> BiometricStatus.HARDWARE_UNAVAILABLE
            AndroidBiometricManager.BIOMETRIC_ERROR_NONE_ENROLLED -> BiometricStatus.NONE_ENROLLED
            else -> BiometricStatus.HARDWARE_UNAVAILABLE
        }
    }

    override suspend fun authenticate(
        activity: FragmentActivity,
        title: String,
        subtitle: String,
        negativeButtonText: String
    ): AuthResult = suspendCancellableCoroutine { continuation ->
        val executor = ContextCompat.getMainExecutor(activity)

        val biometricPrompt = BiometricPrompt(
            activity,
            executor,
            object : BiometricPrompt.AuthenticationCallback() {
                override fun onAuthenticationSucceeded(result: BiometricPrompt.AuthenticationResult) {
                    if (continuation.isActive) {
                        continuation.resume(AuthResult.Success)
                    }
                }

                override fun onAuthenticationError(errorCode: Int, errString: CharSequence) {
                    if (continuation.isActive) {
                        when (errorCode) {
                            BiometricPrompt.ERROR_USER_CANCELED,
                            BiometricPrompt.ERROR_CANCELED -> continuation.resume(AuthResult.Cancelled)
                            BiometricPrompt.ERROR_NEGATIVE_BUTTON -> continuation.resume(AuthResult.Fallback)
                            else -> continuation.resume(AuthResult.Error(errorCode, errString.toString()))
                        }
                    }
                }

                override fun onAuthenticationFailed() {
                    // 单次失败，不结束认证流程
                }
            }
        )

        val promptInfo = BiometricPrompt.PromptInfo.Builder()
            .setTitle(title)
            .setSubtitle(subtitle)
            .setNegativeButtonText(negativeButtonText)
            .setAllowedAuthenticators(AndroidBiometricManager.Authenticators.BIOMETRIC_STRONG)
            .build()

        biometricPrompt.authenticate(promptInfo)
    }

    /**
     * 从 Activity 执行生物识别认证
     */
    fun authenticateFromActivity(
        activity: FragmentActivity,
        title: String,
        subtitle: String,
        negativeButtonText: String,
        callback: (AuthResult) -> Unit
    ) {
        val executor = ContextCompat.getMainExecutor(activity)

        val biometricPrompt = BiometricPrompt(
            activity,
            executor,
            object : BiometricPrompt.AuthenticationCallback() {
                override fun onAuthenticationSucceeded(result: BiometricPrompt.AuthenticationResult) {
                    callback(AuthResult.Success)
                }

                override fun onAuthenticationError(errorCode: Int, errString: CharSequence) {
                    when (errorCode) {
                        BiometricPrompt.ERROR_USER_CANCELED,
                        BiometricPrompt.ERROR_CANCELED -> callback(AuthResult.Cancelled)
                        BiometricPrompt.ERROR_NEGATIVE_BUTTON -> callback(AuthResult.Fallback)
                        else -> callback(AuthResult.Error(errorCode, errString.toString()))
                    }
                }

                override fun onAuthenticationFailed() {
                    // 单次失败，不结束认证流程
                }
            }
        )

        val promptInfo = BiometricPrompt.PromptInfo.Builder()
            .setTitle(title)
            .setSubtitle(subtitle)
            .setNegativeButtonText(negativeButtonText)
            .setAllowedAuthenticators(AndroidBiometricManager.Authenticators.BIOMETRIC_STRONG)
            .build()

        biometricPrompt.authenticate(promptInfo)
    }

    override fun isBiometricEnabled(): Boolean {
        return prefs.getBoolean(KEY_BIOMETRIC_ENABLED, false)
    }

    override fun setBiometricEnabled(enabled: Boolean) {
        prefs.edit().putBoolean(KEY_BIOMETRIC_ENABLED, enabled).apply()
    }
}

package com.mucheng.notes.security

import android.security.keystore.KeyGenParameterSpec
import android.security.keystore.KeyProperties
import java.security.KeyStore
import javax.crypto.Cipher
import javax.crypto.KeyGenerator
import javax.crypto.SecretKey
import javax.crypto.spec.GCMParameterSpec
import javax.inject.Inject
import javax.inject.Singleton

/**
 * Android Keystore 管理器
 * 
 * 使用 Android Keystore 安全存储主密钥。
 * 主密钥用于加密/解密同步数据的加密密钥。
 */
@Singleton
class KeystoreManager @Inject constructor() {

    companion object {
        private const val KEYSTORE_PROVIDER = "AndroidKeyStore"
        private const val KEY_ALIAS = "mucheng_master_key"
        private const val ALGORITHM = "AES/GCM/NoPadding"
        private const val KEY_SIZE = 256
        private const val AUTH_TAG_SIZE = 128
        private const val IV_SIZE = 12
    }

    private val keyStore: KeyStore = KeyStore.getInstance(KEYSTORE_PROVIDER).apply {
        load(null)
    }

    /**
     * 检查主密钥是否存在
     */
    fun hasMasterKey(): Boolean {
        return keyStore.containsAlias(KEY_ALIAS)
    }

    /**
     * 生成主密钥（如果不存在）
     */
    fun generateMasterKey() {
        if (hasMasterKey()) return

        val keyGenerator = KeyGenerator.getInstance(
            KeyProperties.KEY_ALGORITHM_AES,
            KEYSTORE_PROVIDER
        )

        val keySpec = KeyGenParameterSpec.Builder(
            KEY_ALIAS,
            KeyProperties.PURPOSE_ENCRYPT or KeyProperties.PURPOSE_DECRYPT
        )
            .setBlockModes(KeyProperties.BLOCK_MODE_GCM)
            .setEncryptionPaddings(KeyProperties.ENCRYPTION_PADDING_NONE)
            .setKeySize(KEY_SIZE)
            .setUserAuthenticationRequired(false) // 可以改为 true 以要求用户认证
            .build()

        keyGenerator.init(keySpec)
        keyGenerator.generateKey()
    }

    /**
     * 使用主密钥加密数据
     * @param plaintext 要加密的数据
     * @return 加密后的数据（IV + ciphertext）
     */
    fun encrypt(plaintext: ByteArray): ByteArray {
        val secretKey = getSecretKey()
        val cipher = Cipher.getInstance(ALGORITHM)
        cipher.init(Cipher.ENCRYPT_MODE, secretKey)

        val iv = cipher.iv
        val ciphertext = cipher.doFinal(plaintext)

        // 返回 IV + ciphertext
        return iv + ciphertext
    }

    /**
     * 使用主密钥解密数据
     * @param encryptedData 加密的数据（IV + ciphertext）
     * @return 解密后的数据
     */
    fun decrypt(encryptedData: ByteArray): ByteArray {
        require(encryptedData.size > IV_SIZE) { "Invalid encrypted data" }

        val iv = encryptedData.copyOfRange(0, IV_SIZE)
        val ciphertext = encryptedData.copyOfRange(IV_SIZE, encryptedData.size)

        val secretKey = getSecretKey()
        val cipher = Cipher.getInstance(ALGORITHM)
        val gcmSpec = GCMParameterSpec(AUTH_TAG_SIZE, iv)
        cipher.init(Cipher.DECRYPT_MODE, secretKey, gcmSpec)

        return cipher.doFinal(ciphertext)
    }

    /**
     * 加密同步密钥
     * @param syncKey 同步密钥（32 字节）
     * @return 加密后的同步密钥
     */
    fun encryptSyncKey(syncKey: ByteArray): ByteArray {
        require(syncKey.size == 32) { "Sync key must be 32 bytes" }
        return encrypt(syncKey)
    }

    /**
     * 解密同步密钥
     * @param encryptedSyncKey 加密的同步密钥
     * @return 解密后的同步密钥（32 字节）
     */
    fun decryptSyncKey(encryptedSyncKey: ByteArray): ByteArray {
        val decrypted = decrypt(encryptedSyncKey)
        require(decrypted.size == 32) { "Decrypted sync key must be 32 bytes" }
        return decrypted
    }

    /**
     * 删除主密钥
     */
    fun deleteMasterKey() {
        if (hasMasterKey()) {
            keyStore.deleteEntry(KEY_ALIAS)
        }
    }

    /**
     * 获取 Keystore 中的密钥
     */
    private fun getSecretKey(): SecretKey {
        val entry = keyStore.getEntry(KEY_ALIAS, null) as? KeyStore.SecretKeyEntry
            ?: throw IllegalStateException("Master key not found")
        return entry.secretKey
    }
}

