/**
 * 待办提醒广播接收器
 */
class ReminderReceiver : BroadcastReceiver() {

    override fun onReceive(context: Context, intent: Intent) {
        val todoId = intent.getStringExtra(EXTRA_TODO_ID) ?: return
        val todoTitle = intent.getStringExtra(EXTRA_TODO_TITLE) ?: "待办提醒"

        showNotification(context, todoId, todoTitle)
    }

    private fun showNotification(context: Context, todoId: String, title: String) {
        val notificationManager = context.getSystemService(Context.NOTIFICATION_SERVICE) as NotificationManager

        // 创建通知渠道 (Android 8.0+)
        if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.O) {
            val channel = NotificationChannel(
                CHANNEL_ID,
                "待办提醒",
                NotificationManager.IMPORTANCE_HIGH
            ).apply {
                description = "待办事项提醒通知"
                enableVibration(true)
            }
            notificationManager.createNotificationChannel(channel)
        }

        // 点击通知打开应用
        val intent = Intent(context, MainActivity::class.java).apply {
            flags = Intent.FLAG_ACTIVITY_NEW_TASK or Intent.FLAG_ACTIVITY_CLEAR_TASK
            putExtra(EXTRA_TODO_ID, todoId)
        }
        val pendingIntent = PendingIntent.getActivity(
            context,
            todoId.hashCode(),
            intent,
            PendingIntent.FLAG_UPDATE_CURRENT or PendingIntent.FLAG_IMMUTABLE
        )

        val notification = NotificationCompat.Builder(context, CHANNEL_ID)
            .setSmallIcon(R.drawable.ic_notification)
            .setContentTitle("待办提醒")
            .setContentText(title)
            .setPriority(NotificationCompat.PRIORITY_HIGH)
            .setAutoCancel(true)
            .setContentIntent(pendingIntent)
            .build()

        notificationManager.notify(todoId.hashCode(), notification)
    }

    companion object {
        const val CHANNEL_ID = "todo_reminder"
        const val EXTRA_TODO_ID = "todo_id"
        const val EXTRA_TODO_TITLE = "todo_title"
    }
}

/**
 * 提醒管理器
 */
class ReminderManager(private val context: Context) {

    private val alarmManager = context.getSystemService(Context.ALARM_SERVICE) as AlarmManager

    /**
     * 设置提醒
     */
    fun setReminder(todoId: String, title: String, triggerTime: Long) {
        val intent = Intent(context, ReminderReceiver::class.java).apply {
            putExtra(ReminderReceiver.EXTRA_TODO_ID, todoId)
            putExtra(ReminderReceiver.EXTRA_TODO_TITLE, title)
        }

        val pendingIntent = PendingIntent.getBroadcast(
            context,
            todoId.hashCode(),
            intent,
            PendingIntent.FLAG_UPDATE_CURRENT or PendingIntent.FLAG_IMMUTABLE
        )

        // 使用精确闹钟
        if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.M) {
            alarmManager.setExactAndAllowWhileIdle(
                AlarmManager.RTC_WAKEUP,
                triggerTime,
                pendingIntent
            )
        } else {
            alarmManager.setExact(
                AlarmManager.RTC_WAKEUP,
                triggerTime,
                pendingIntent
            )
        }
    }

    /**
     * 取消提醒
     */
    fun cancelReminder(todoId: String) {
        val intent = Intent(context, ReminderReceiver::class.java)
        val pendingIntent = PendingIntent.getBroadcast(
            context,
            todoId.hashCode(),
            intent,
            PendingIntent.FLAG_UPDATE_CURRENT or PendingIntent.FLAG_IMMUTABLE
        )
        alarmManager.cancel(pendingIntent)
    }
}

package com.mucheng.notes.security

import android.content.Context
import android.content.SharedPreferences
import androidx.security.crypto.EncryptedSharedPreferences
import androidx.security.crypto.MasterKey
import dagger.hilt.android.qualifiers.ApplicationContext
import java.security.MessageDigest
import javax.inject.Inject
import javax.inject.Singleton

/**
 * AppLockManager 实现
 */
@Singleton
class AppLockManagerImpl @Inject constructor(
    @ApplicationContext private val context: Context
) : AppLockManager {

    companion object {
        private const val PREFS_NAME = "app_lock_prefs"
        private const val KEY_LOCK_ENABLED = "lock_enabled"
        private const val KEY_LOCK_TYPE = "lock_type"
        private const val KEY_PIN_HASH = "pin_hash"
        private const val KEY_PIN_LENGTH = "pin_length"
        private const val KEY_PATTERN_HASH = "pattern_hash"
        private const val KEY_LAST_UNLOCK = "last_unlock"
        private const val KEY_LOCK_TIMEOUT = "lock_timeout"

        private const val DEFAULT_TIMEOUT = 5 * 60 * 1000L // 5 分钟
        private const val DEFAULT_PIN_LENGTH = 4
    }

    private val prefs: SharedPreferences by lazy {
        val masterKey = MasterKey.Builder(context)
            .setKeyScheme(MasterKey.KeyScheme.AES256_GCM)
            .build()

        EncryptedSharedPreferences.create(
            context,
            PREFS_NAME,
            masterKey,
            EncryptedSharedPreferences.PrefKeyEncryptionScheme.AES256_SIV,
            EncryptedSharedPreferences.PrefValueEncryptionScheme.AES256_GCM
        )
    }

    override fun isLockEnabled(): Boolean {
        return prefs.getBoolean(KEY_LOCK_ENABLED, false)
    }

    override fun setLockEnabled(enabled: Boolean) {
        prefs.edit().putBoolean(KEY_LOCK_ENABLED, enabled).apply()
    }

    override fun getLockType(): LockType {
        val typeStr = prefs.getString(KEY_LOCK_TYPE, LockType.NONE.name)
        return try {
            LockType.valueOf(typeStr ?: LockType.NONE.name)
        } catch (e: Exception) {
            LockType.NONE
        }
    }

    override fun setLockType(type: LockType) {
        prefs.edit().putString(KEY_LOCK_TYPE, type.name).apply()
    }

    override suspend fun verifyPin(pin: String): Boolean {
        val storedHash = prefs.getString(KEY_PIN_HASH, null) ?: return false
        val inputHash = hashString(pin)
        return storedHash == inputHash
    }

    override suspend fun verifyPattern(pattern: List<Int>): Boolean {
        val storedHash = prefs.getString(KEY_PATTERN_HASH, null) ?: return false
        val inputHash = hashString(pattern.joinToString(","))
        return storedHash == inputHash
    }

    override fun setPin(pin: String) {
        val hash = hashString(pin)
        prefs.edit()
            .putString(KEY_PIN_HASH, hash)
            .putInt(KEY_PIN_LENGTH, pin.length)
            .apply()
    }

    override fun getPinLength(): Int {
        return prefs.getInt(KEY_PIN_LENGTH, DEFAULT_PIN_LENGTH)
    }

    override fun setPattern(pattern: List<Int>) {
        val hash = hashString(pattern.joinToString(","))
        prefs.edit().putString(KEY_PATTERN_HASH, hash).apply()
    }

    override fun shouldLock(): Boolean {
        if (!isLockEnabled()) return false

        val lastUnlock = prefs.getLong(KEY_LAST_UNLOCK, 0)
        val timeout = getLockTimeout()

        return System.currentTimeMillis() - lastUnlock > timeout
    }

    override fun recordUnlock() {
        prefs.edit().putLong(KEY_LAST_UNLOCK, System.currentTimeMillis()).apply()
    }

    override fun getLockTimeout(): Long {
        return prefs.getLong(KEY_LOCK_TIMEOUT, DEFAULT_TIMEOUT)
    }

    override fun setLockTimeout(timeout: Long) {
        prefs.edit().putLong(KEY_LOCK_TIMEOUT, timeout).apply()
    }

    /**
     * 计算字符串的 SHA-256 哈希
     */
    private fun hashString(input: String): String {
        val digest = MessageDigest.getInstance("SHA-256")
        val hashBytes = digest.digest(input.toByteArray(Charsets.UTF_8))
        return hashBytes.joinToString("") { "%02x".format(it) }
    }
}

package com.mucheng.notes.security

import android.content.Context
import android.content.SharedPreferences
import android.util.Base64
import android.util.Log
import androidx.security.crypto.EncryptedSharedPreferences
import androidx.security.crypto.MasterKey
import net.zetetic.database.sqlcipher.SQLiteDatabase
import java.security.SecureRandom

/**
 * Manages the SQLCipher passphrase for the local Room database.
 *
 * The passphrase is device-local and wrapped by AndroidX Security/Keystore.
 * Existing installations that used the historical hardcoded passphrase are
 * opened once and rekeyed to the generated passphrase.
 */
object DatabaseKeyManager {
    private const val TAG = "DatabaseKeyManager"
    private const val PREFS_NAME = "database_key_prefs"
    private const val KEY_PASSPHRASE = "sqlcipher_passphrase_v1"
    private const val KEY_MIGRATED_LEGACY = "legacy_passphrase_migrated"
    private const val PASSPHRASE_BYTES = 32
    private val LEGACY_PASSPHRASE = "mucheng_notes_db_key".toByteArray(Charsets.UTF_8)

    fun getOrCreatePassphrase(context: Context, databaseName: String): ByteArray {
        val appContext = context.applicationContext
        System.loadLibrary("sqlcipher")

        val prefs = getPrefs(appContext)
        val passphrase = getStoredPassphrase(prefs) ?: generatePassphrase().also {
            prefs.edit()
                .putString(KEY_PASSPHRASE, Base64.encodeToString(it, Base64.NO_WRAP))
                .apply()
        }

        migrateLegacyDatabaseIfNeeded(appContext, databaseName, prefs, passphrase)
        return passphrase.copyOf()
    }

    private fun getPrefs(context: Context): SharedPreferences {
        val masterKey = MasterKey.Builder(context)
            .setKeyScheme(MasterKey.KeyScheme.AES256_GCM)
            .build()

        return EncryptedSharedPreferences.create(
            context,
            PREFS_NAME,
            masterKey,
            EncryptedSharedPreferences.PrefKeyEncryptionScheme.AES256_SIV,
            EncryptedSharedPreferences.PrefValueEncryptionScheme.AES256_GCM
        )
    }

    private fun getStoredPassphrase(prefs: SharedPreferences): ByteArray? {
        val encoded = prefs.getString(KEY_PASSPHRASE, null) ?: return null
        return Base64.decode(encoded, Base64.NO_WRAP)
    }

    private fun generatePassphrase(): ByteArray {
        val passphrase = ByteArray(PASSPHRASE_BYTES)
        SecureRandom().nextBytes(passphrase)
        return passphrase
    }

    private fun migrateLegacyDatabaseIfNeeded(
        context: Context,
        databaseName: String,
        prefs: SharedPreferences,
        newPassphrase: ByteArray
    ) {
        if (prefs.getBoolean(KEY_MIGRATED_LEGACY, false)) return

        val databasePath = context.getDatabasePath(databaseName)
        if (!databasePath.exists()) {
            prefs.edit().putBoolean(KEY_MIGRATED_LEGACY, true).apply()
            return
        }

        if (canOpenDatabase(databasePath.absolutePath, newPassphrase)) {
            prefs.edit().putBoolean(KEY_MIGRATED_LEGACY, true).apply()
            return
        }

        var database: SQLiteDatabase? = null
        try {
            database = SQLiteDatabase.openDatabase(
                databasePath.absolutePath,
                LEGACY_PASSPHRASE,
                null,
                SQLiteDatabase.OPEN_READWRITE,
                null
            )
            database.changePassword(newPassphrase)
            prefs.edit().putBoolean(KEY_MIGRATED_LEGACY, true).apply()
            Log.i(TAG, "Migrated local database passphrase from legacy key")
        } catch (error: Exception) {
            Log.e(TAG, "Failed to migrate legacy database passphrase", error)
            throw error
        } finally {
            database?.close()
        }
    }

    private fun canOpenDatabase(path: String, passphrase: ByteArray): Boolean {
        var database: SQLiteDatabase? = null
        return try {
            database = SQLiteDatabase.openDatabase(
                path,
                passphrase,
                null,
                SQLiteDatabase.OPEN_READONLY,
                null
            )
            database.rawQuery("SELECT count(*) FROM sqlite_master", emptyArray<String>()).use { cursor ->
                cursor.moveToFirst()
            }
            true
        } catch (_: Exception) {
            false
        } finally {
            database?.close()
        }
    }
}

package com.mucheng.notes.security

import okhttp3.CertificatePinner
import okhttp3.ConnectionSpec
import okhttp3.OkHttpClient
import java.util.concurrent.TimeUnit
import javax.inject.Inject
import javax.inject.Singleton

/**
 * 网络安全管理器接口
 */
interface NetworkSecurityManager {
    /**
     * 获取安全的 OkHttpClient
     */
    fun getSecureOkHttpClient(): OkHttpClient

    /**
     * 获取证书固定配置
     */
    fun getCertificatePinner(): CertificatePinner
}

/**
 * 网络安全管理器实现
 * 提供 Certificate Pinning 和安全的 HTTP 客户端
 */
@Singleton
class NetworkSecurityManagerImpl @Inject constructor() : NetworkSecurityManager {

    companion object {
        // OpenAI API 证书指纹 (需要定期更新)
        private const val OPENAI_PIN_1 = "sha256/AAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAA="
        private const val OPENAI_PIN_2 = "sha256/BBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBB="

        // Anthropic API 证书指纹
        private const val ANTHROPIC_PIN_1 = "sha256/CCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCC="
        private const val ANTHROPIC_PIN_2 = "sha256/DDDDDDDDDDDDDDDDDDDDDDDDDDDDDDDDDDDDDDDDDDD="
    }

    private val _certificatePinner: CertificatePinner by lazy {
        CertificatePinner.Builder()
            // OpenAI
            .add("api.openai.com", OPENAI_PIN_1)
            .add("api.openai.com", OPENAI_PIN_2)
            // Anthropic
            .add("api.anthropic.com", ANTHROPIC_PIN_1)
            .add("api.anthropic.com", ANTHROPIC_PIN_2)
            .build()
    }

    private val secureClient: OkHttpClient by lazy {
        OkHttpClient.Builder()
            // 证书固定
            .certificatePinner(_certificatePinner)
            // 仅使用现代 TLS
            .connectionSpecs(listOf(ConnectionSpec.MODERN_TLS))
            // 超时设置
            .connectTimeout(30, TimeUnit.SECONDS)
            .readTimeout(60, TimeUnit.SECONDS)
            .writeTimeout(30, TimeUnit.SECONDS)
            // 禁用重定向（安全考虑）
            .followRedirects(false)
            .followSslRedirects(false)
            .build()
    }

    override fun getSecureOkHttpClient(): OkHttpClient = secureClient

    override fun getCertificatePinner(): CertificatePinner = _certificatePinner

    /**
     * 创建自定义证书固定的客户端
     * 用于用户自定义的 API 端点
     */
    fun createClientWithCustomPins(pins: Map<String, List<String>>): OkHttpClient {
        val pinnerBuilder = CertificatePinner.Builder()

        for ((host, pinList) in pins) {
            for (pin in pinList) {
                pinnerBuilder.add(host, pin)
            }
        }

        return OkHttpClient.Builder()
            .certificatePinner(pinnerBuilder.build())
            .connectionSpecs(listOf(ConnectionSpec.MODERN_TLS))
            .connectTimeout(30, TimeUnit.SECONDS)
            .readTimeout(60, TimeUnit.SECONDS)
            .writeTimeout(30, TimeUnit.SECONDS)
            .build()
    }

    /**
     * 创建不带证书固定的客户端（用于用户自定义服务器）
     * 注意：仅在用户明确选择时使用
     */
    fun createClientWithoutPinning(): OkHttpClient {
        return OkHttpClient.Builder()
            .connectionSpecs(listOf(ConnectionSpec.MODERN_TLS, ConnectionSpec.COMPATIBLE_TLS))
            .connectTimeout(30, TimeUnit.SECONDS)
            .readTimeout(60, TimeUnit.SECONDS)
            .writeTimeout(30, TimeUnit.SECONDS)
            .build()
    }
}

