 * 主 Activity
 * 继承 AppCompatActivity (FragmentActivity 子类) 以支持生物识别
 */
@AndroidEntryPoint
class MainActivity : AppCompatActivity() {

    @Inject
    lateinit var appLockManager: AppLockManager

    // Activity 级别的 SettingsViewModel，所有子组件共享
    private val settingsViewModel: SettingsViewModel by viewModels()

    override fun onCreate(savedInstanceState: Bundle?) {
        super.onCreate(savedInstanceState)

        // 启用边缘到边缘显示
        enableEdgeToEdge()
        WindowCompat.setDecorFitsSystemWindows(window, false)

        // 启用预测性返回手势 (Android 13+)
        if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.TIRAMISU) {
            onBackInvokedDispatcher.registerOnBackInvokedCallback(
                OnBackInvokedDispatcher.PRIORITY_DEFAULT
            ) {
                // 处理返回逻辑
                handleBackPressed()
            }
        }

        setContent {
            MuchengNotesTheme {
                MainApp(
                    shouldShowLockScreen = appLockManager.shouldLock(),
                    onUnlock = { appLockManager.recordUnlock() },
                    settingsViewModel = settingsViewModel
                )
            }
        }
    }

    override fun onResume() {
        super.onResume()
        // 检查是否需要锁定
        if (appLockManager.shouldLock()) {
            // 显示锁屏
        }
    }

    override fun onPause() {
        super.onPause()
        // 记录暂停时间用于超时检测
    }

    private fun handleBackPressed() {
        // 自定义返回处理
        finish()
    }
}

@Composable
fun MainApp(
    shouldShowLockScreen: Boolean,
    onUnlock: () -> Unit,
    settingsViewModel: SettingsViewModel
) {
    var isLocked by remember { mutableStateOf(shouldShowLockScreen) }

    if (isLocked) {
        LockScreen(onUnlocked = { 
            isLocked = false
            onUnlock() 
        })
    } else {
        val navController = rememberNavController()
        // 直接使用 MainNavigation，传入共享的 SettingsViewModel
        MainNavigation(navController = navController, settingsViewModel = settingsViewModel)
    }
}

import { getDatabase } from '../database';
import { RemoteChange, ChangeListResult, ItemType } from '../types';
import { userService } from './UserService';

export interface ChangeInput {
  item_id: string;
  type: ItemType;
  updated_time: number;
  deleted_time: number | null;
  content_hash: string;
}

export class ChangeService {
  // 记录变更
  recordChange(change: ChangeInput, userId?: string): void {
    const db = getDatabase();
    const now = Date.now();

    const stmt = db.prepare(`
      INSERT INTO changes (item_id, type, updated_time, deleted_time, content_hash, created_at, user_id)
      VALUES (?, ?, ?, ?, ?, ?, ?)
    `);

    stmt.run(
      change.item_id,
      change.type,
      change.updated_time,
      change.deleted_time,
      change.content_hash,
      now,
      userId || null
    );
  }

  // 获取变更列表
  listChanges(cursor?: string, limit: number = 100, userId?: string): ChangeListResult {
    userService.claimLegacyDataForSingleUser(userId);
    const db = getDatabase();
    const cursorNum = cursor ? parseInt(cursor, 10) : 0;

    // 构建用户过滤条件
    const userFilter = userId 
      ? 'AND user_id = ?' 
      : '';
    const userParams = userId ? [userId] : [];

    // 获取变更列表（多取一条用于判断 hasMore）
    const stmt = db.prepare(`
      SELECT change_id, item_id, type, updated_time, deleted_time, content_hash
      FROM changes
      WHERE change_id > ? ${userFilter}
      ORDER BY change_id ASC
      LIMIT ?
    `);

    const rows = stmt.all(cursorNum, ...userParams, limit + 1) as RemoteChange[];

    const hasMore = rows.length > limit;
    const changes = hasMore ? rows.slice(0, limit) : rows;
    const nextCursor = changes.length > 0 ? changes[changes.length - 1].change_id.toString() : null;

    return {
      changes,
      nextCursor,
      hasMore,
    };
  }

  // 检查游标是否已过期（游标对应的变更记录已被清理）
  isCursorExpired(cursor: string, userId?: string): boolean {
    userService.claimLegacyDataForSingleUser(userId);
    const db = getDatabase();
    const cursorNum = parseInt(cursor, 10);
    if (isNaN(cursorNum)) return false;

    const userFilter = userId ? 'AND user_id = ?' : '';
    const userParams = userId ? [userId] : [];

    // 查找比游标更新的最早一条变更
    const stmt = db.prepare(`
      SELECT MIN(change_id) as min_id FROM changes
      WHERE change_id > 0 ${userFilter}
    `);
    const row = stmt.get(...userParams) as { min_id: number | null };

    if (row.min_id === null) return false; // 没有任何变更，不算过期

    // 如果最早现存变更的 change_id 大于游标，说明中间有变更被清理掉了
    return row.min_id > cursorNum + 1;
  }

  // 清理过期变更
  cleanupBefore(timestamp: number, userId?: string): number {
    userService.claimLegacyDataForSingleUser(userId);
    const db = getDatabase();
    const stmt = userId
      ? db.prepare('DELETE FROM changes WHERE created_at < ? AND user_id = ?')
      : db.prepare('DELETE FROM changes WHERE created_at < ?');
    const result = userId ? stmt.run(timestamp, userId) : stmt.run(timestamp);
    return result.changes;
  }
}

import express from 'express';
import path from 'path';
import { config } from './config';
import { corsMiddleware } from './middleware/cors';
import { loggerMiddleware } from './middleware/logger';
import { authMiddleware } from './middleware/auth';
import { apiRateLimiter, syncRateLimiter } from './middleware/rateLimiter';
import { errorHandler } from './middleware/errorHandler';

import healthRouter from './routes/health';
import statusRouter from './routes/status';
import metaRouter from './routes/meta';
import itemsRouter from './routes/items';
import changesRouter from './routes/changes';
import resourcesRouter from './routes/resources';
import syncRouter from './routes/sync';
import authRouter from './routes/auth';
import userRouter from './routes/user';
import adminRouter from './routes/admin';

const app = express();

if (config.trustProxy) {
  app.set('trust proxy', 1);
}

// 中间件
app.use(corsMiddleware);
app.use(loggerMiddleware);
app.use((req, res, next) => {
  if (config.secureMode && !req.secure) {
    res.status(400).json({
      error: {
        code: 'SECURE_CONNECTION_REQUIRED',
        message: 'HTTPS is required',
      },
    });
    return;
  }
  next();
});
app.use((_req, res, next) => {
  res.setHeader('X-Content-Type-Options', 'nosniff');
  res.setHeader('X-Frame-Options', 'DENY');
  res.setHeader('Referrer-Policy', 'no-referrer');
  res.setHeader('Permissions-Policy', 'camera=(), microphone=(), geolocation=()');
  if (config.secureMode) {
    res.setHeader('Strict-Transport-Security', 'max-age=31536000; includeSubDomains');
  }
  next();
});
app.use(express.json({ limit: config.jsonBodyLimit }));

// 静态文件服务（管理界面）
app.use(express.static(path.join(__dirname, 'public')));

// 健康检查（无需认证）
app.use('/api/health', healthRouter);

// API 频率限制
app.use(apiRateLimiter);

// 认证路由（部分端点无需认证）
app.use('/api/auth', authRouter);

// 认证中间件（其他路由需要认证）
app.use(authMiddleware);

// 用户路由
app.use('/api/user', userRouter);

// 管理员路由
app.use('/api/admin', adminRouter);

// API 路由（使用同步专用的宽松限制）
app.use('/api/status', statusRouter);
app.use('/api/meta', syncRateLimiter, metaRouter);
app.use('/api/items', syncRateLimiter, itemsRouter);
app.use('/api/changes', syncRateLimiter, changesRouter);
app.use('/api/resources', syncRateLimiter, resourcesRouter);
app.use('/api/sync', syncRateLimiter, syncRouter);

// 所有非 API 路由返回管理界面（SPA 支持）
app.get('*', (req, res) => {
  if (!req.path.startsWith('/api')) {
    res.sendFile(path.join(__dirname, 'public', 'index.html'));
  }
});

// 错误处理
app.use(errorHandler);

export default app;

import React, { useEffect } from 'react';
import { createRoot } from 'react-dom/client';
import { ConfigProvider, theme } from 'antd';
import { StyleProvider } from '@ant-design/cssinjs';
import zhCN from 'antd/locale/zh_CN';
import App from './App';
import { SettingsProvider, useSettings } from './contexts/SettingsContext';
import './styles/global.css';

// Polyfill for Promise.withResolvers (required by pdfjs-dist 5.x)
if (typeof (Promise as any).withResolvers !== 'function') {
  (Promise as any).withResolvers = function <T>() {
    let resolve: (value: T | PromiseLike<T>) => void;
    let reject: (reason?: any) => void;
    const promise = new Promise<T>((res, rej) => {
      resolve = res;
      reject = rej;
    });
    return { promise, resolve: resolve!, reject: reject! };
  };
}

// 在 React 渲染前立即应用主题，避免闪烁
(function applyInitialTheme() {
  try {
    const savedSettings = localStorage.getItem('mucheng-settings');
    if (savedSettings) {
      const settings = JSON.parse(savedSettings);
      const theme = settings.theme;
      const systemDark = window.matchMedia('(prefers-color-scheme: dark)').matches;

      const isDark = theme === 'dark' || (theme === 'system' && systemDark);
      if (isDark) {
        document.body.classList.add('dark-mode');
      }
    }
  } catch (e) {
    console.warn('Failed to apply initial theme:', e);
  }
})();

// 主题包装组件
const ThemedApp: React.FC = () => {
  const { isDarkMode } = useSettings();

  // 同步 body class 以支持全局 CSS 深色模式
  useEffect(() => {
    if (isDarkMode) {
      document.body.classList.add('dark-mode');
    } else {
      document.body.classList.remove('dark-mode');
    }
  }, [isDarkMode]);

  return (
    <StyleProvider hashPriority="high">
      <ConfigProvider
        locale={zhCN}
        theme={{
          algorithm: isDarkMode ? theme.darkAlgorithm : theme.defaultAlgorithm,
          token: {
            colorPrimary: '#1890ff',
          },
        }}
      >
        <App />
      </ConfigProvider>
    </StyleProvider>
  );
};

const container = document.getElementById('root');
if (!container) throw new Error('Root element not found');

const root = createRoot(container);

root.render(
  <React.StrictMode>
    <SettingsProvider>
      <ThemedApp />
    </SettingsProvider>
  </React.StrictMode>
);

package com.mucheng.notes.data.local

import android.content.Context
import androidx.room.Database
import androidx.room.Room
import androidx.room.RoomDatabase
import com.mucheng.notes.data.local.dao.ItemDao
import com.mucheng.notes.data.local.dao.ResourceCacheDao
import com.mucheng.notes.data.local.entity.ItemEntity
import com.mucheng.notes.data.local.entity.ResourceCacheEntity
import net.zetetic.database.sqlcipher.SupportOpenHelperFactory

/**
 * Room Database with SQLCipher encryption
 */
@Database(
    entities = [
        ItemEntity::class,
        ResourceCacheEntity::class
    ],
    version = 1,
    exportSchema = false
)
abstract class AppDatabase : RoomDatabase() {

    abstract fun itemDao(): ItemDao
    abstract fun resourceCacheDao(): ResourceCacheDao

    companion object {
        const val DATABASE_NAME = "mucheng_notes.db"

        @Volatile
        private var INSTANCE: AppDatabase? = null

        /**
         * 获取加密数据库实例
         * @param context Application context
         * @param passphrase 数据库加密密码
         */
        fun getInstance(context: Context, passphrase: ByteArray): AppDatabase {
            return INSTANCE ?: synchronized(this) {
                INSTANCE ?: buildDatabase(context, passphrase).also { INSTANCE = it }
            }
        }

        /**
         * 获取未加密数据库实例（仅用于测试）
         */
        fun getTestInstance(context: Context): AppDatabase {
            return Room.inMemoryDatabaseBuilder(
                context.applicationContext,
                AppDatabase::class.java
            ).build()
        }

        private fun buildDatabase(context: Context, passphrase: ByteArray): AppDatabase {
            val factory = SupportOpenHelperFactory(passphrase, null, false)

            return Room.databaseBuilder(
                context.applicationContext,
                AppDatabase::class.java,
                DATABASE_NAME
            )
                .openHelperFactory(factory)
                .fallbackToDestructiveMigration() // TODO: 实现正式迁移策略
                .build()
        }

        /**
         * 关闭数据库连接
         */
        fun closeDatabase() {
            INSTANCE?.close()
            INSTANCE = null
        }
    }
}

import app from './app';
import { config, ensureDataDirs, checkSecurityConfig } from './config';
import { getDatabase, closeDatabase } from './database';
import { CleanupScheduler } from './services/CleanupScheduler';
import { log } from './middleware/logger';
import { transferRelayServer } from './transfer/relay';
import { createServer } from 'http';

// 确保数据目录存在
ensureDataDirs();

// 执行安全配置检查
checkSecurityConfig();

// 初始化数据库
getDatabase();

// 启动清理调度器
const cleanupScheduler = new CleanupScheduler();
cleanupScheduler.start();

// 创建 HTTP 服务器
const server = createServer(app);

// 初始化 Transfer 中继服务器
if (config.transferRelayEnabled) {
  transferRelayServer.initialize(server);
  log('info', `Transfer relay server enabled on path ${config.transferRelayPath}`);
}

// 启动服务器
server.listen(config.port, () => {
  log('info', `Sync server started on port ${config.port}`);
  log('info', `Database: ${config.databasePath}`);
  log('info', `Resources: ${config.resourcesPath}`);
  if (config.transferRelayEnabled) {
    log('info', `Transfer relay: enabled (max ${config.transferMaxConnections} connections)`);
  }
});

// 优雅关闭
function gracefulShutdown(signal: string): void {
  log('info', `Received ${signal}, shutting down gracefully...`);

  // 停止清理调度器
  cleanupScheduler.stop();

  // 关闭 Transfer 中继服务器
  if (config.transferRelayEnabled) {
    transferRelayServer.close();
    log('info', 'Transfer relay server closed');
  }

  // 关闭 HTTP 服务器
  server.close(() => {
    log('info', 'HTTP server closed');

    // 关闭数据库连接
    closeDatabase();
    log('info', 'Database connection closed');

    process.exit(0);
  });

  // 强制关闭超时
  setTimeout(() => {
    log('error', 'Forced shutdown after timeout');
    process.exit(1);
  }, 10000);
}

process.on('SIGTERM', () => gracefulShutdown('SIGTERM'));
process.on('SIGINT', () => gracefulShutdown('SIGINT'));

