    const existingMerged = currentSheet.merged_cells || [];
    for (const merged of existingMerged) {
      // 检查是否有重叠
      const overlaps = !(
        maxRow < merged.start_row ||
        minRow > merged.end_row ||
        maxCol < merged.start_col ||
        minCol > merged.end_col
      );
      if (overlaps) {
        console.warn('合并区域与现有合并单元格冲突');
        return false;
      }
    }

