                }
            },
            dismissButton = {
                TextButton(onClick = { 
                    showDeleteEntryDialog = false
                    selectedEntry = null
                }) {
                    Text("取消")
                }
            }
        )
    }

    // 创建文件夹对话框
    if (showCreateFolderDialog) {
        var folderName by remember { mutableStateOf("") }
        AlertDialog(
            onDismissRequest = { showCreateFolderDialog = false },
            title = { Text("新建文件夹") },
            text = {
