                            listOf(
                                "识别文字 (OCR)",
                                "描述图片内容",
                                "整理成表格",
                                "提取关键信息"
                            ).forEach { suggestion ->
                                AssistChip(
                                    onClick = { imagePrompt = suggestion },
                                    label = { Text(suggestion, fontSize = 12.sp) },
                                    enabled = !uiState.aiImageProcessingLoading
