/**
 * 聊天视图
 */
@Composable
private fun ChatView(
    uiState: TransferUiState,
    onBack: () -> Unit,
    onSendMessage: (String) -> Unit,
    onSendFile: (android.net.Uri) -> Unit,
    onOpenFile: (String) -> Unit,
    onOpenFolder: (String) -> Unit,
    modifier: Modifier = Modifier
) {
    val session = uiState.sessions.find { it.id == uiState.selectedSessionId }
    var inputText by remember { mutableStateOf("") }
    val listState = rememberLazyListState()

    // 文件选择器
    val filePickerLauncher = rememberLauncherForActivityResult(
        ActivityResultContracts.GetContent()
    ) { uri ->
        uri?.let { onSendFile(it) }
    }

    // 自动滚动到底部
    LaunchedEffect(uiState.messages.size) {
        if (uiState.messages.isNotEmpty()) {
            listState.animateScrollToItem(uiState.messages.size - 1)
        }
    }

    Column(modifier = modifier) {
        // 顶部栏
        Surface(
            tonalElevation = 2.dp,
            modifier = Modifier.fillMaxWidth()
        ) {
            Row(
                verticalAlignment = Alignment.CenterVertically,
                modifier = Modifier
                    .fillMaxWidth()
                    .padding(8.dp)
            ) {
                IconButton(onClick = onBack) {
                    Icon(Icons.AutoMirrored.Filled.ArrowBack, contentDescription = "返回")
                }
                Column(modifier = Modifier.weight(1f)) {
                    Text(
                        text = session?.peerDeviceName ?: "会话",
                        style = MaterialTheme.typography.titleMedium
                    )
                    Text(
                        text = if (session?.endedAt == null) "进行中" else "已结束",
                        style = MaterialTheme.typography.bodySmall,
                        color = MaterialTheme.colorScheme.outline
                    )
                }
            }
        }

        // 消息列表
        LazyColumn(
            state = listState,
            modifier = Modifier
                .fillMaxWidth()
                .weight(1f),
            contentPadding = PaddingValues(16.dp),
            verticalArrangement = Arrangement.spacedBy(8.dp)
        ) {
            if (uiState.messages.isEmpty()) {
                item {
                    Box(
                        modifier = Modifier
                            .fillMaxWidth()
                            .padding(48.dp),
                        contentAlignment = Alignment.Center
                    ) {
                        Text(
                            text = "暂无消息\n发送第一条消息开始聊天",
                            style = MaterialTheme.typography.bodyMedium,
                            color = MaterialTheme.colorScheme.outline,
                            textAlign = TextAlign.Center
                        )
                    }
                }
            } else {
                items(uiState.messages) { message ->
                    val fileEntity = if ((message.type == "file" || message.type == "image") && message.fileId != null) {
                        uiState.files.find { it.id == message.fileId }
                    } else null
                    MessageBubble(
                        message = message,
                        fileEntity = fileEntity,
                        onOpenFile = { fileId -> onOpenFile(fileId) },
                        onOpenFolder = { fileId -> onOpenFolder(fileId) }
                    )
                }
            }
        }

        // 输入区域
        Surface(
            tonalElevation = 2.dp,
            modifier = Modifier.fillMaxWidth()
        ) {
            Row(
                verticalAlignment = Alignment.CenterVertically,
                modifier = Modifier
                    .fillMaxWidth()
                    .padding(8.dp)
            ) {
                // 附件按钮
                IconButton(onClick = { filePickerLauncher.launch("*/*") }) {
                    Icon(Icons.Default.AttachFile, contentDescription = "发送文件")
                }

                // 输入框
                OutlinedTextField(
                    value = inputText,
                    onValueChange = { inputText = it },
                    placeholder = { Text("输入消息...") },
                    modifier = Modifier
                        .weight(1f)
                        .padding(horizontal = 8.dp),
                    maxLines = 4,
                    keyboardOptions = KeyboardOptions(imeAction = ImeAction.Send),
                    keyboardActions = KeyboardActions(
                        onSend = {
                            if (inputText.isNotBlank()) {
                                onSendMessage(inputText)
                                inputText = ""
                            }
                        }
                    ),
                    shape = RoundedCornerShape(24.dp)
                )

                // 发送按钮
                IconButton(
                    onClick = {
                        if (inputText.isNotBlank()) {
                            onSendMessage(inputText)
                            inputText = ""
                        }
                    },
                    enabled = inputText.isNotBlank()
                ) {
                    Icon(
                        Icons.AutoMirrored.Filled.Send,
                        contentDescription = "发送",
                        tint = if (inputText.isNotBlank()) 
                            MaterialTheme.colorScheme.primary 
                        else 
                            MaterialTheme.colorScheme.outline
                    )
                }
            }
        }
    }
}

/**
 * 消息气泡
 */
@OptIn(ExperimentalFoundationApi::class)
@Composable
private fun MessageBubble(
    message: TransferMessageEntity,
    fileEntity: TransferFileEntity? = null,
    onOpenFile: (String) -> Unit = {},
    onOpenFolder: (String) -> Unit = {}
) {
    val isSent = message.direction == MessageDirection.SENT.value
    val isFileMessage = message.type == "file" || message.type == "image"
    val isImageMessage = message.type == "image" || fileEntity?.mimeType?.startsWith("image/") == true
    val dateFormat = remember { SimpleDateFormat("HH:mm", Locale.getDefault()) }
    val context = LocalContext.current
    val clipboardManager = LocalClipboardManager.current
    var showMenu by remember { mutableStateOf(false) }
    val canOpenFile = fileEntity?.localPath != null
    val copyText = message.content.ifBlank { if (isFileMessage) "文件" else "" }

    Row(
        modifier = Modifier.fillMaxWidth(),
        horizontalArrangement = if (isSent) Arrangement.End else Arrangement.Start
    ) {
        Box {
            Surface(
                shape = RoundedCornerShape(
                    topStart = 16.dp,
                    topEnd = 16.dp,
                    bottomStart = if (isSent) 16.dp else 4.dp,
                    bottomEnd = if (isSent) 4.dp else 16.dp
                ),
                color = if (isSent)
                    MaterialTheme.colorScheme.primary
                else
                    MaterialTheme.colorScheme.surfaceVariant,
                modifier = Modifier
                    .widthIn(max = 280.dp)
                    .combinedClickable(
                        onClick = {
                            if (isFileMessage && canOpenFile) {
                                fileEntity?.let { onOpenFile(it.id) }
                            }
                        },
                        onLongClick = { showMenu = true }
                    )
            ) {
                Column(modifier = Modifier.padding(12.dp)) {
                    if (isFileMessage) {
                        if (isImageMessage) {
                            TransferImagePreview(
                                localPath = fileEntity?.localPath,
                                isSent = isSent,
                                onClick = {
                                    if (canOpenFile) {
                                        fileEntity?.let { onOpenFile(it.id) }
                                    }
                                },
                                modifier = Modifier
                                    .width(220.dp)
                                    .heightIn(min = 120.dp, max = 220.dp)
                                    .clip(RoundedCornerShape(12.dp))
                            )
                            Spacer(modifier = Modifier.height(8.dp))
                        }
                        Row(
                            verticalAlignment = Alignment.CenterVertically,
                            horizontalArrangement = Arrangement.spacedBy(8.dp),
                            modifier = Modifier.padding(vertical = 4.dp)
                        ) {
                            Icon(
                                imageVector = if (message.type == "image") Icons.Filled.Image else Icons.Filled.AttachFile,
                                contentDescription = "File",
                                modifier = Modifier.size(20.dp),
                                tint = if (isSent)
                                    MaterialTheme.colorScheme.onPrimary
                                else
                                    MaterialTheme.colorScheme.onSurfaceVariant
                            )
                            Text(
                                text = message.content.ifBlank { "文件" },
                                style = MaterialTheme.typography.bodyMedium,
                                color = if (isSent)
                                    MaterialTheme.colorScheme.onPrimary
                                else
                                    MaterialTheme.colorScheme.onSurfaceVariant
                            )
                        }
                        if (canOpenFile) {
                            Row(
                                horizontalArrangement = Arrangement.spacedBy(8.dp),
                                modifier = Modifier.padding(top = 4.dp)
                            ) {
                                TextButton(
                                    onClick = { fileEntity?.let { onOpenFile(it.id) } },
                                    contentPadding = PaddingValues(horizontal = 8.dp, vertical = 0.dp)
                                ) {
                                    Text("打开", style = MaterialTheme.typography.labelSmall)
                                }
                                TextButton(
                                    onClick = { fileEntity?.let { onOpenFolder(it.id) } },
                                    contentPadding = PaddingValues(horizontal = 8.dp, vertical = 0.dp)
                                ) {
                                    Text("文件位置", style = MaterialTheme.typography.labelSmall)
                                }
                            }
                        }
                    } else {
                        Text(
                            text = message.content,
                            style = MaterialTheme.typography.bodyMedium,
                            color = if (isSent)
                                MaterialTheme.colorScheme.onPrimary
                            else
                                MaterialTheme.colorScheme.onSurfaceVariant
                        )
                    }
                    Spacer(modifier = Modifier.height(4.dp))
                    Text(
                        text = dateFormat.format(Date(message.createdAt)),
                        style = MaterialTheme.typography.labelSmall,
                        color = if (isSent)
                            MaterialTheme.colorScheme.onPrimary.copy(alpha = 0.7f)
                        else
                            MaterialTheme.colorScheme.outline
                    )
                }
            }

            DropdownMenu(
                expanded = showMenu,
                onDismissRequest = { showMenu = false }
            ) {
                DropdownMenuItem(
                    text = { Text(if (isFileMessage) "复制文件名" else "复制消息") },
                    onClick = {
                        clipboardManager.setText(AnnotatedString(copyText))
                        showMenu = false
                        Toast.makeText(context, "已复制", Toast.LENGTH_SHORT).show()
                    },
                    enabled = copyText.isNotBlank()
                )
                if (isFileMessage && canOpenFile) {
                    DropdownMenuItem(
                        text = { Text("打开") },
                        onClick = {
                            fileEntity?.let { onOpenFile(it.id) }
                            showMenu = false
                        }
                    )
                    DropdownMenuItem(
                        text = { Text("文件位置") },
                        onClick = {
                            fileEntity?.let { onOpenFolder(it.id) }
                            showMenu = false
                        }
                    )
                }
            }
        }
    }
}

