@OptIn(ExperimentalFoundationApi::class)
@Composable
private fun NoteCard(
    note: NoteItem,
    onClick: () -> Unit,
    onLongClick: () -> Unit,
    showContextMenu: Boolean,
    onDismissMenu: () -> Unit,
    onTogglePin: () -> Unit,
    onDelete: () -> Unit,
    onMoveToFolder: () -> Unit,
    onLock: () -> Unit,
    onUnlock: () -> Unit,
    isPinned: Boolean
) {
    Box {
        Card(
            modifier = Modifier
                .fillMaxWidth()
                .combinedClickable(
                    onClick = onClick,
                    onLongClick = onLongClick
                ),
            colors = CardDefaults.cardColors(
                containerColor = if (note.isPinned) 
                    MaterialTheme.colorScheme.primaryContainer 
                else 
                    MaterialTheme.colorScheme.surface
            )
        ) {
            Column(
                modifier = Modifier
                    .fillMaxWidth()
                    .padding(horizontal = 16.dp, vertical = 12.dp)
            ) {
                Row(
                    modifier = Modifier.fillMaxWidth(),
                    horizontalArrangement = Arrangement.SpaceBetween,
                    verticalAlignment = Alignment.CenterVertically
                ) {
                    Row(
                        modifier = Modifier.weight(1f),
                        verticalAlignment = Alignment.CenterVertically
                    ) {
                        // Excel 笔记显示表格图标
                        if (note.isExcelNote) {
                            Icon(
                                Icons.Default.TableChart,
                                contentDescription = "Excel 笔记",
                                tint = MaterialTheme.colorScheme.primary,
                                modifier = Modifier.padding(end = 8.dp).size(20.dp)
                            )
                        }
                        Text(
                            text = note.title.ifEmpty { "无标题" },
                            style = MaterialTheme.typography.titleMedium,
                            maxLines = 1,
                            overflow = TextOverflow.Ellipsis
                        )
                    }

                    Row(verticalAlignment = Alignment.CenterVertically) {
                        Text(
                            text = formatTime(note.updatedTime),
                            style = MaterialTheme.typography.bodySmall,
                            color = MaterialTheme.colorScheme.outline
                        )
                        if (note.isPinned) {
                            Icon(
                                Icons.Default.PushPin,
                                contentDescription = stringResource(R.string.note_pinned),
                                tint = MaterialTheme.colorScheme.primary,
                                modifier = Modifier.padding(start = 4.dp).size(16.dp)
                            )
                        }
                        if (note.isLocked) {
                            Icon(
                                Icons.Default.Lock,
                                contentDescription = stringResource(R.string.note_locked),
                                tint = MaterialTheme.colorScheme.outline,
                                modifier = Modifier.padding(start = 4.dp).size(16.dp)
                            )
                        }
                    }
                }

                // Excel 笔记显示预览信息
                if (note.isExcelNote && note.content.isNotEmpty()) {
                    Text(
                        text = note.content,
                        style = MaterialTheme.typography.bodySmall,
                        color = MaterialTheme.colorScheme.outline,
                        maxLines = 1,
                        overflow = TextOverflow.Ellipsis,
                        modifier = Modifier.padding(top = 4.dp)
                    )
                }
            }
        }

        // 长按上下文菜单
        DropdownMenu(
            expanded = showContextMenu,
            onDismissRequest = onDismissMenu
        ) {
            DropdownMenuItem(
                text = { Text(if (isPinned) "取消置顶" else "置顶") },
                onClick = onTogglePin,
                leadingIcon = {
                    Icon(
                        if (isPinned) Icons.Default.StarBorder else Icons.Default.Star,
                        contentDescription = null
                    )
                }
            )
            DropdownMenuItem(
                text = { Text("移动到文件夹") },
                onClick = onMoveToFolder,
                leadingIcon = {
                    Icon(Icons.Default.Folder, contentDescription = null)
                }
            )
            // 锁定/解锁选项
            DropdownMenuItem(
                text = { Text(if (note.isLocked) "解锁笔记" else "锁定笔记") },
                onClick = if (note.isLocked) onUnlock else onLock,
                leadingIcon = {
                    Icon(
                        if (note.isLocked) Icons.Default.LockOpen else Icons.Default.Lock,
                        contentDescription = null
                    )
                }
            )
            DropdownMenuItem(
                text = { Text("删除") },
                onClick = onDelete,
                leadingIcon = {
                    Icon(
                        Icons.Default.Delete,
                        contentDescription = null,
                        tint = MaterialTheme.colorScheme.error
                    )
                }
            )
        }
    }
}

private fun formatTime(timestamp: Long): String {
    val sdf = SimpleDateFormat("yyyy-MM-dd HH:mm", Locale.getDefault())
    return sdf.format(Date(timestamp))
}

/**
 * 文件夹对话框模式
 */
private sealed class FolderDialogMode {
    data class Create(val parentId: String?) : FolderDialogMode()
    data class Edit(val folderId: String) : FolderDialogMode()
}

/**
 * 文件夹编辑/创建对话框
 */
@Composable
private fun FolderDialog(
    mode: FolderDialogMode,
    folderName: String,
    onNameChange: (String) -> Unit,
    onConfirm: () -> Unit,
    onDismiss: () -> Unit
) {
    val title = when (mode) {
        is FolderDialogMode.Create -> if (mode.parentId != null) "新建子文件夹" else "新建文件夹"
        is FolderDialogMode.Edit -> "重命名文件夹"
    }

    AlertDialog(
        onDismissRequest = onDismiss,
        title = { Text(title) },
        text = {
            OutlinedTextField(
                value = folderName,
                onValueChange = onNameChange,
                label = { Text("文件夹名称") },
                singleLine = true,
                modifier = Modifier.fillMaxWidth()
            )
        },
        confirmButton = {
            TextButton(
                onClick = onConfirm,
                enabled = folderName.isNotBlank()
            ) {
                Text("确定")
            }
        },
        dismissButton = {
            TextButton(onClick = onDismiss) {
                Text("取消")
            }
        }
    )
}

/**
 * 移动到文件夹对话框
 */
@Composable
private fun MoveToFolderDialog(
    folders: List<ViewModelFolderItem>,
    currentFolderId: String?,
    onSelect: (String?) -> Unit,
    onDismiss: () -> Unit
) {
    var selectedFolderId by remember { mutableStateOf(currentFolderId) }

    AlertDialog(
        onDismissRequest = onDismiss,
        title = { Text("移动到文件夹") },
        text = {
            LazyColumn {
                // 根目录选项
                item {
                    Row(
                        modifier = Modifier
                            .fillMaxWidth()
                            .clickable { selectedFolderId = null }
                            .padding(vertical = 8.dp),
                        verticalAlignment = Alignment.CenterVertically
                    ) {
                        RadioButton(
                            selected = selectedFolderId == null,
                            onClick = { selectedFolderId = null }
                        )
                        Spacer(modifier = Modifier.width(8.dp))
                        Icon(Icons.Default.Folder, contentDescription = null)
                        Spacer(modifier = Modifier.width(8.dp))
                        Text("根目录（无文件夹）")
                    }
                }

                // 文件夹列表
                items(folders) { folder ->
                    Row(
                        modifier = Modifier
                            .fillMaxWidth()
                            .clickable { selectedFolderId = folder.id }
                            .padding(vertical = 8.dp),
                        verticalAlignment = Alignment.CenterVertically
                    ) {
                        RadioButton(
                            selected = selectedFolderId == folder.id,
                            onClick = { selectedFolderId = folder.id }
                        )
                        Spacer(modifier = Modifier.width(8.dp))
                        Icon(Icons.Default.Folder, contentDescription = null)
                        Spacer(modifier = Modifier.width(8.dp))
                        Text(folder.name)
                    }
                }
            }
        },
        confirmButton = {
            TextButton(onClick = { onSelect(selectedFolderId) }) {
                Text("确定")
            }
        },
        dismissButton = {
            TextButton(onClick = onDismiss) {
                Text("取消")
            }
        }
    )
}

