import {
  Input, Button, Select, Slider, Empty, message, Tooltip, Popover, Modal, Form, Upload
} from 'antd';
import {
  SendOutlined, PlusOutlined, DeleteOutlined, EditOutlined,
  RobotOutlined, SettingOutlined, FileTextOutlined, PictureOutlined, CloseCircleOutlined
} from '@ant-design/icons';
import { useAISettings, useAIConversations, useAIMessages, AIMessage } from '../hooks/useAI';
import { validateImage, fileToBase64, compressImage, getImageFromClipboard } from '../utils/imageUtils';

const { TextArea } = Input;

// 预设系统提示词
const PRESET_PROMPTS = [
  { id: 'default', name: '默认助手', prompt: '你是一个有帮助的AI助手。' },
  { id: 'coder', name: '代码专家', prompt: '你是一个专业的编程助手，擅长多种编程语言。请提供简洁、高效、可维护的代码，并解释关键逻辑。' },
  { id: 'writer', name: '写作助手', prompt: '你是一个专业的写作助手，擅长各类文案、文章的撰写和润色。请注意语言流畅、逻辑清晰、表达准确。' },
  { id: 'translator', name: '翻译专家', prompt: '你是一个专业的翻译助手，精通中英文互译。请提供准确、自然、符合目标语言习惯的翻译。' },
  { id: 'analyst', name: '数据分析师', prompt: '你是一个数据分析专家，擅长数据处理、统计分析和可视化。请提供专业的分析建议和解决方案。' },
  { id: 'teacher', name: '学习导师', prompt: '你是一个耐心的学习导师，善于用简单易懂的方式解释复杂概念。请循序渐进地引导学习。' },
  { id: 'creative', name: '创意顾问', prompt: '你是一个富有创意的顾问，擅长头脑风暴和创意思维。请提供新颖、独特的想法和建议。' },
  { id: 'custom', name: '自定义', prompt: '' },
];

const AIAssistantPanel: React.FC = () => {
  const { settings } = useAISettings();
  const { conversations, createConversation, deleteConversation, updateConversation } = useAIConversations();

  const [currentConversationId, setCurrentConversationId] = useState<string | null>(null);
  const { messages, streaming, streamingContent, sendMessage } = useAIMessages(currentConversationId);

  const [inputValue, setInputValue] = useState('');
  const [localMessages, setLocalMessages] = useState<AIMessage[]>([]);
  const [sending, setSending] = useState(false);
  const [selectedImages, setSelectedImages] = useState<string[]>([]);

  // 新建对话弹窗状态
  const [newConvModalVisible, setNewConvModalVisible] = useState(false);
  const [newConvForm] = Form.useForm();

  // UI状态
  const [editingTitle, setEditingTitle] = useState<string | null>(null);
  const [newTitle, setNewTitle] = useState('');

  const messagesEndRef = useRef<HTMLDivElement>(null);

  // 获取所有可用模型
  const allModels = settings.channels.flatMap(c =>
    c.models.map(m => ({ ...m, channelName: c.name, channel: c }))
  );

  // 当前对话
  const currentConversation = conversations.find(c => c.id === currentConversationId);

  // 当前对话的设置（从对话中读取，或使用默认值）
  const currentModel = currentConversation?.model || (allModels.length > 0 ? allModels[0].id : '');
  const currentTemperature = currentConversation?.temperature ?? 0.7;
  const currentMaxTokens = currentConversation?.maxTokens ?? 4096;
  const currentSystemPrompt = currentConversation?.systemPrompt || '你是一个有帮助的AI助手。';
  // 从对话中读取保存的渠道 ID（关键修复：避免不同渠道的同名模型混淆）
  const savedChannelId = currentConversation?.channelId;

  // 当前选中的渠道（用于级联选择）
  const [selectedChannelId, setSelectedChannelId] = useState<string | null>(null);

  // 根据当前模型和渠道查找模型信息
  // 优先使用保存的渠道 ID（解决不同渠道有相同模型 ID 的问题）
  const currentModelInfo = savedChannelId
    ? allModels.find(m => m.id === currentModel && m.channel?.id === savedChannelId)
    : allModels.find(m => m.id === currentModel);
  const currentChannelId = savedChannelId || currentModelInfo?.channel?.id || selectedChannelId;

  // 当前渠道下的模型列表
  const currentChannelModels = currentChannelId
    ? settings.channels.find(c => c.id === currentChannelId)?.models || []
    : [];

  // 合并本地消息和服务器消息
  const displayMessages = [...messages, ...localMessages].sort((a, b) => a.createdAt - b.createdAt);

  // 滚动到底部
  useEffect(() => {
    messagesEndRef.current?.scrollIntoView({ behavior: 'smooth' });
  }, [displayMessages, streamingContent, sending]);

  // 清除本地消息当服务器消息更新
  useEffect(() => {
    if (messages.length > 0) {
      setLocalMessages([]);
    }
  }, [messages]);

  // 打开新建对话弹窗
  const handleOpenNewConvModal = () => {
    const defaultChannel = settings.channels.length > 0 ? settings.channels[0] : null;
    const defaultModel = defaultChannel && defaultChannel.models.length > 0 ? defaultChannel.models[0].id : '';
    const defaultChannelId = defaultChannel?.id || '';

    // 先重置表单，确保清除之前的状态
    newConvForm.resetFields();
    // 使用 setTimeout 确保重置完成后再设置新值
    setTimeout(() => {
      newConvForm.setFieldsValue({
        title: '新对话',
        channelId: defaultChannelId,
        model: defaultModel,
        temperature: 0.7,
        maxTokens: 4096,
        presetPrompt: 'default',
        systemPrompt: PRESET_PROMPTS[0].prompt,
      });
      setSelectedChannelId(defaultChannelId);
    }, 0);
    setNewConvModalVisible(true);
  };

  // 创建新对话
  const handleCreateConversation = async () => {
    try {
      const values = await newConvForm.validateFields();
      if (!values.model) {
        message.error('请先在设置中配置AI渠道和模型');
        return;
      }
      const conv = await createConversation(
        values.title,
        values.model,
        values.systemPrompt,
        values.temperature,
        values.maxTokens,
        false,  // webSearchEnabled
        values.channelId  // 传递渠道 ID
      );
      if (conv) {
        setCurrentConversationId(conv.id);
        setLocalMessages([]);
        setNewConvModalVisible(false);
        message.success('对话创建成功');
      } else {
        message.error('创建对话失败');
      }
    } catch (err) {
      console.error('Create conversation error:', err);
    }
  };

  // Handle Image Upload
  const handleImageUpload = async (file: File) => {
    const validation = validateImage(file);
    if (!validation.valid) {
      message.error(validation.error);
      return false;
    }

    try {
      message.loading({ content: '处理图片中...', key: 'image-upload' });
      let base64 = await fileToBase64(file);
      base64 = await compressImage(base64);
      setSelectedImages(prev => [...prev, base64]);
      message.success({ content: '图片已添加', key: 'image-upload' });
    } catch (error) {
      message.error({ content: '图片处理失败', key: 'image-upload' });
    }
    return false;
  };

  // Handle Paste
  const handlePaste = async (e: React.ClipboardEvent<HTMLTextAreaElement>) => {
    try {
      const file = await getImageFromClipboard(e);
      if (file) {
        e.preventDefault();
        await handleImageUpload(file);
      }
    } catch (error) {
      console.error('粘贴图片失败:', error);
    }
  };

  // Remove Image
  const handleRemoveImage = (index: number) => {
    setSelectedImages(prev => prev.filter((_, i) => i !== index));
  };

  const handleSend = async () => {
    if ((!inputValue.trim() && selectedImages.length === 0) || sending) return;

    if (!currentConversationId) {
      message.warning('请先创建或选择一个对话');
      handleOpenNewConvModal();
      return;
    }

    // 调试日志：追踪模型切换问题
    console.log('[AI Assistant] handleSend - Debug Info:', {
      currentConversationId,
      'currentConversation?.model': currentConversation?.model,
      'currentConversation?.channelId': currentConversation?.channelId,
      currentModel,
      savedChannelId,
      currentChannelId,
      'currentModelInfo?.id': currentModelInfo?.id,
      'currentModelInfo?.channel?.id': currentModelInfo?.channel?.id,
      'currentModelInfo?.channel?.name': currentModelInfo?.channel?.name,
    });

    // 使用 currentModelInfo（已经使用 channelId 精确匹配），避免不同渠道同名模型的问题
    if (!currentModelInfo) {
      message.error('当前对话的模型不可用，请检查AI渠道设置');
      return;
    }

    const userMsg: AIMessage = {
      id: `local-${Date.now()}`,
      conversationId: currentConversationId,
      role: 'user',
      content: inputValue,
      model: currentModel,
      createdAt: Date.now(),
      images: [...selectedImages]
    };
    setLocalMessages(prev => [...prev, userMsg]);

    const content = inputValue;
    const imagesToSend = [...selectedImages];
    setInputValue('');
    setSelectedImages([]);
    setSending(true);

    try {
      console.log('[AI Assistant] Sending message with:', {
        model: currentModel,
        channelName: currentModelInfo.channel.name,
        channelType: currentModelInfo.channel.type,
        apiUrl: currentModelInfo.channel.api_url,
      });
      await sendMessage(
        content,
        currentModelInfo.channel,  // 使用正确匹配的渠道
        currentModel,
        currentSystemPrompt,
        currentTemperature,
        currentMaxTokens,
        imagesToSend
      );
    } catch (err: any) {
      message.error(err.message || 'AI请求失败');
    } finally {
      setSending(false);
    }
  };

  const handleSelectConversation = (id: string) => {
    // 切换对话时重置所有状态
    setSending(false);
    setCurrentConversationId(id);
    setLocalMessages([]);
    setSelectedImages([]);
  };

  const handleDeleteConversation = async (id: string, e: React.MouseEvent) => {
    e.stopPropagation();
    await deleteConversation(id);
    if (currentConversationId === id) {
      setCurrentConversationId(null);
      setLocalMessages([]);
      setSelectedImages([]);
    }
  };

  // 更新当前对话的模型（同时保存渠道 ID，避免同名模型混淆）
  const handleModelChange = (modelId: string, channelId?: string) => {
    if (currentConversationId) {
      const targetChannelId = channelId || selectedChannelId || currentChannelId || undefined;
      console.log('[AI Assistant] Model change:', { modelId, channelId: targetChannelId });
      updateConversation(currentConversationId, {
        model: modelId,
        channel_id: targetChannelId  // 同时保存渠道 ID
      });
    }
  };



  // 更新当前对话的系统提示词
  const handleSystemPromptChange = (prompt: string) => {
    if (currentConversationId) {
      updateConversation(currentConversationId, { system_prompt: prompt });
    }
  };

  // 获取当前预设ID
  const getCurrentPresetId = () => {
    const preset = PRESET_PROMPTS.find(p => p.prompt === currentSystemPrompt);
    return preset ? preset.id : 'custom';
  };

  // 模型选择弹出内容（级联选择：先选渠道再选模型）
  const modelPopoverContent = (
    <div style={{ width: 280 }}>
      <div style={{ marginBottom: 8, fontWeight: 500, color: '#666' }}>选择模型</div>
      {!currentConversationId ? (
        <div style={{ color: '#999', fontSize: 12 }}>请先创建或选择对话</div>
      ) : (
        <>
          <div style={{ marginBottom: 8 }}>
            <div style={{ marginBottom: 4, fontSize: 12, color: '#999' }}>AI 渠道</div>
            <Select
              style={{ width: '100%' }}
              value={currentChannelId}
              onChange={(channelId) => {
                setSelectedChannelId(channelId);
                // 切换渠道时，自动选择该渠道的第一个模型，并传递渠道 ID
                const channel = settings.channels.find(c => c.id === channelId);
                if (channel && channel.models.length > 0) {
                  handleModelChange(channel.models[0].id, channelId);
                }
              }}
              placeholder="选择渠道"
              options={settings.channels.map(c => ({ value: c.id, label: c.name }))}
            />
          </div>
          <div>
            <div style={{ marginBottom: 4, fontSize: 12, color: '#999' }}>模型</div>
            <Select
              style={{ width: '100%' }}
              value={currentModel}
              onChange={(modelId) => handleModelChange(modelId, currentChannelId || undefined)}
              placeholder="选择模型"
              disabled={!currentChannelId}
              options={currentChannelModels.map(m => ({ value: m.id, label: m.name }))}
            />
          </div>
        </>
      )}
    </div>
  );

  // 参数设置弹出内容 (使用独立组件管理状态)
  const settingsPopoverContent = (
    <ConversationSettings
      conversationId={currentConversationId}
      temperature={currentTemperature}
      maxTokens={currentMaxTokens}
      onUpdate={(updates) => currentConversationId && updateConversation(currentConversationId, updates)}
    />
  );

  // 系统提示词弹出内容
  const promptPopoverContent = (
    <div style={{ width: 280 }}>
      <div style={{ marginBottom: 8, fontWeight: 500, color: '#666' }}>系统提示词</div>
      {!currentConversationId ? (
        <div style={{ color: '#999', fontSize: 12 }}>请先创建或选择对话</div>
      ) : (
        <>
          <Select
            style={{ width: '100%', marginBottom: 8 }}
            value={getCurrentPresetId()}
            onChange={(presetId) => {
              const preset = PRESET_PROMPTS.find(p => p.id === presetId);
              if (preset && presetId !== 'custom') {
                handleSystemPromptChange(preset.prompt);
              }
            }}
            options={PRESET_PROMPTS.map(p => ({ value: p.id, label: p.name }))}
          />
          <TextArea
            rows={3}
            value={currentSystemPrompt}
            onChange={e => handleSystemPromptChange(e.target.value)}
            placeholder="输入系统提示词..."
            style={{ fontSize: 12 }}
          />
        </>
      )}
    </div>
  );

  return (
    <div style={{ display: 'flex', height: '100%', background: '#f5f5f5' }}>
      {/* 左侧对话列表 */}
      <div style={{
        width: 220,
        background: '#fff',
        borderRight: '1px solid #e8e8e8',
        display: 'flex',
        flexDirection: 'column',
      }}>
        <div style={{ padding: '12px', borderBottom: '1px solid #f0f0f0' }}>
          <Button type="primary" block icon={<PlusOutlined />} onClick={handleOpenNewConvModal}>
            新建对话
          </Button>
        </div>
        <div style={{ flex: 1, overflow: 'auto', padding: '8px' }}>
          {conversations.length === 0 ? (
            <Empty description="暂无对话" image={Empty.PRESENTED_IMAGE_SIMPLE} style={{ marginTop: 40 }} />
          ) : (
            conversations.map(conv => (
              <div
                key={conv.id}
                onClick={() => handleSelectConversation(conv.id)}
                style={{
                  padding: '10px 12px',
                  marginBottom: 4,
                  background: conv.id === currentConversationId ? '#e6f7ff' : 'transparent',
                  borderRadius: 6,
                  cursor: 'pointer',
                  display: 'flex',
                  alignItems: 'center',
                  justifyContent: 'space-between',
                  transition: 'background 0.2s',
                }}
                onMouseEnter={e => {
                  if (conv.id !== currentConversationId) {
                    (e.currentTarget as HTMLDivElement).style.background = '#f5f5f5';
                  }
                }}
                onMouseLeave={e => {
                  if (conv.id !== currentConversationId) {
                    (e.currentTarget as HTMLDivElement).style.background = 'transparent';
                  }
                }}
              >
                {editingTitle === conv.id ? (
                  <Input
                    size="small"
                    value={newTitle}
                    onChange={e => setNewTitle(e.target.value)}
                    onBlur={async () => {
                      if (newTitle.trim()) await updateConversation(conv.id, { title: newTitle });
                      setEditingTitle(null);
                    }}
                    onPressEnter={async () => {
                      if (newTitle.trim()) await updateConversation(conv.id, { title: newTitle });
                      setEditingTitle(null);
                    }}
                    onClick={e => e.stopPropagation()}
                    autoFocus
                    style={{ flex: 1 }}
                  />
                ) : (
                  <>
                    <span style={{
                      flex: 1,
                      overflow: 'hidden',
                      textOverflow: 'ellipsis',
                      whiteSpace: 'nowrap',
                      fontSize: 13,
                    }}>
                      {conv.title}
                    </span>
                    <div style={{ display: 'flex', gap: 2, opacity: 0.6 }}>
                      <Button
                        type="text"
                        size="small"
                        icon={<EditOutlined style={{ fontSize: 12 }} />}
                        onClick={e => { e.stopPropagation(); setEditingTitle(conv.id); setNewTitle(conv.title); }}
                        style={{ padding: '0 4px', height: 20 }}
                      />
                      <Button
                        type="text"
                        size="small"
                        danger
                        icon={<DeleteOutlined style={{ fontSize: 12 }} />}
                        onClick={e => handleDeleteConversation(conv.id, e)}
                        style={{ padding: '0 4px', height: 20 }}
                      />
                    </div>
                  </>
                )}
              </div>
            ))
          )}
        </div>
      </div>

      {/* 右侧对话区域 */}
      <div style={{ flex: 1, display: 'flex', flexDirection: 'column' }}>
        {/* 顶部标题栏 */}
        <div style={{
          padding: '12px 16px',
          background: '#fff',
          borderBottom: '1px solid #e8e8e8',
          display: 'flex',
          alignItems: 'center',
          gap: 8,
        }}>
          <RobotOutlined style={{ fontSize: 18, color: '#1890ff' }} />
          <span style={{ fontWeight: 500 }}>
            {currentConversation?.title || '请选择或创建对话'}
          </span>
          {currentConversation && (
            <span style={{ fontSize: 11, color: '#999', marginLeft: 8 }}>
              模型: {currentModelInfo?.name || currentModel}
            </span>
          )}
        </div>

        {/* 消息列表 */}
        <div style={{ flex: 1, overflow: 'auto', padding: 16 }}>
          {!currentConversationId ? (
            <Empty
              description="请先创建或选择一个对话"
              style={{ marginTop: 60 }}
            >
              <Button type="primary" onClick={handleOpenNewConvModal}>新建对话</Button>
            </Empty>
          ) : displayMessages.length === 0 && !streaming && !sending ? (
            <Empty description="开始新对话" style={{ marginTop: 60 }} />
          ) : (
            <>
              {displayMessages.map((msg) => (
                <MessageBubble key={msg.id} message={msg} />
              ))}
              {/* 流式响应 */}
              {streaming && streamingContent && (
                <MessageBubble
                  message={{
                    id: 'streaming',
                    conversationId: currentConversationId || '',
                    role: 'assistant',
                    content: streamingContent,
                    model: currentModel,
                    createdAt: Date.now(),
                  }}
                />
              )}
              {/* 等待AI回复的提示 */}
              {sending && !streamingContent && (
                <MessageBubble
                  message={{
                    id: 'loading-placeholder',
                    conversationId: currentConversationId || '',
                    role: 'assistant',
                    content: 'AI 正在思考...',
                    model: currentModel,
                    createdAt: Date.now(),
                  }}
                />
              )}
              <div ref={messagesEndRef} />
            </>
          )}
        </div>

        {/* 输入区域 */}
        <div style={{ background: '#fff', borderTop: '1px solid #e8e8e8', padding: '12px 16px' }}>
          {/* 图片预览 */}
          {selectedImages.length > 0 && (
            <div style={{
              display: 'flex',
              flexWrap: 'wrap',
              gap: 8,
              marginBottom: 8,
              padding: 8,
              background: '#fafafa',
              borderRadius: 4
            }}>
              {selectedImages.map((img, idx) => (
                <div key={idx} style={{ position: 'relative' }}>
                  <img src={img} style={{ width: 60, height: 60, borderRadius: 4, objectFit: 'cover' }} />
                  <CloseCircleOutlined
                    onClick={() => handleRemoveImage(idx)}
                    style={{ position: 'absolute', top: -6, right: -6, color: '#ff4d4f', cursor: 'pointer', background: '#fff', borderRadius: '50%' }}
                  />
                </div>
              ))}
            </div>
          )}

          {/* 工具栏 */}
          <div style={{ display: 'flex', alignItems: 'center', marginBottom: 8, gap: 4 }}>
            <Popover content={modelPopoverContent} trigger="click" placement="topLeft">
              <Tooltip title="选择模型">
                <Button type="text" size="small" style={{ color: currentConversationId ? '#666' : '#ccc' }}>
                  @{currentModelInfo?.name || '模型'}
                </Button>
              </Tooltip>
            </Popover>
            <Popover content={settingsPopoverContent} trigger="click" placement="top">
              <Tooltip title="参数设置">
                <Button type="text" size="small" icon={<SettingOutlined />} style={{ color: currentConversationId ? '#666' : '#ccc' }} />
              </Tooltip>
            </Popover>
            <Popover content={promptPopoverContent} trigger="click" placement="top">
              <Tooltip title="系统提示词">
                <Button type="text" size="small" icon={<FileTextOutlined />} style={{ color: currentConversationId ? '#666' : '#ccc' }} />
              </Tooltip>
            </Popover>
          </div>

          {/* 输入框 */}
          <div style={{ display: 'flex', gap: 8, alignItems: 'flex-end' }}>
            <Upload
              accept="image/*"
              showUploadList={false}
              beforeUpload={handleImageUpload}
              multiple
            >
              <Tooltip title="上传图片">
                <Button
                  icon={<PictureOutlined />}
                  disabled={sending || streaming || !currentConversationId}
                  style={{ height: 32 }}
                />
              </Tooltip>
            </Upload>
            <div style={{ flex: 1 }}>
              <TextArea
                value={inputValue}
                onChange={e => setInputValue(e.target.value)}
                onPaste={handlePaste}
                onKeyDown={e => {
                  if (e.key === 'Enter' && !e.shiftKey) { e.preventDefault(); handleSend(); }
                }}
                placeholder={currentConversationId ? "输入消息，Enter发送，Shift+Enter换行，支持粘贴图片" : "请先创建或选择对话"}
                autoSize={{ minRows: 1, maxRows: 4 }}
                disabled={sending || streaming || !currentConversationId}
              />
            </div>
            <Button
              type="primary"
              icon={<SendOutlined />}
              onClick={handleSend}
              loading={sending || streaming}
              disabled={(!inputValue.trim() && selectedImages.length === 0) || !currentConversationId}
              style={{ height: 32 }}
            />
          </div>
        </div>
      </div>

      {/* 新建对话弹窗 */}
      <Modal
        title="新建对话"
        open={newConvModalVisible}
        onOk={handleCreateConversation}
        onCancel={() => setNewConvModalVisible(false)}
        okText="创建"
        cancelText="取消"
        width={500}
        destroyOnClose
      >
        <Form form={newConvForm} layout="vertical" style={{ marginTop: 16 }}>
          <Form.Item
            name="title"
            label="对话名称"
            rules={[{ required: true, message: '请输入对话名称' }]}
          >
            <Input placeholder="输入对话名称" />
          </Form.Item>

          <Form.Item
            name="channelId"
            label="AI 渠道"
            rules={[{ required: true, message: '请选择渠道' }]}
          >
            <Select
              placeholder="选择渠道"
              options={settings.channels.map(c => ({ value: c.id, label: c.name }))}
              notFoundContent={<span style={{ color: '#999' }}>请先在设置中配置AI渠道</span>}
              onChange={(channelId) => {
                setSelectedChannelId(channelId);
                // 切换渠道时，清空模型选择并自动选择第一个模型
                const channel = settings.channels.find(c => c.id === channelId);
                if (channel && channel.models.length > 0) {
                  newConvForm.setFieldValue('model', channel.models[0].id);
                } else {
                  newConvForm.setFieldValue('model', undefined);
                }
              }}
            />
          </Form.Item>

          <Form.Item
            name="model"
            label="选择模型"
            rules={[{ required: true, message: '请选择模型' }]}
          >
            <Select
              placeholder="选择模型"
              disabled={!selectedChannelId}
              options={
                selectedChannelId
                  ? settings.channels.find(c => c.id === selectedChannelId)?.models.map(m => ({ value: m.id, label: m.name })) || []
                  : []
              }
              notFoundContent={<span style={{ color: '#999' }}>请先选择渠道</span>}
            />
          </Form.Item>

          <Form.Item name="presetPrompt" label="预设提示词">
            <Select
              options={PRESET_PROMPTS.map(p => ({ value: p.id, label: p.name }))}
              onChange={(presetId) => {
                const preset = PRESET_PROMPTS.find(p => p.id === presetId);
                if (preset) {
                  newConvForm.setFieldValue('systemPrompt', preset.prompt);
                }
              }}
            />
          </Form.Item>

          <Form.Item name="systemPrompt" label="系统提示词">
            <TextArea rows={3} placeholder="输入系统提示词..." />
          </Form.Item>

          <Form.Item name="temperature" label={`温度 (${newConvForm.getFieldValue('temperature') || 0.7})`}>
            <Slider min={0} max={2} step={0.1} />
          </Form.Item>

          <Form.Item name="maxTokens" label={`最大Token (${newConvForm.getFieldValue('maxTokens') || 4096})`}>
            <Slider min={256} max={32768} step={256} />
          </Form.Item>
        </Form>
      </Modal>
    </div>
  );
};

