  /**
   * 监听文件传入事件
   */
  onFileIncoming(callback: (data: any) => void): () => void {
    if (!transferApi) return () => { };
    return transferApi.onFileIncoming(callback);
  },

  /**
   * 监听文件分块事件
   */
  onFileChunk(callback: (data: any) => void): () => void {
    if (!transferApi) return () => { };
    return transferApi.onFileChunk(callback);
  },

  /**
   * 监听文件完成事件
   */
  onFileComplete(callback: (data: any) => void): () => void {
    if (!transferApi) return () => { };
    return transferApi.onFileComplete(callback);
  },

  /**
   * 监听会话创建事件（设备连接时自动创建的会话）
   */
  onSessionCreated(callback: (data: { sessionId: string; peerDeviceId: string; peerDeviceName: string }) => void): () => void {
    if (!transferApi) return () => { };
    return transferApi.onSessionCreated(callback);
  },

  // ============================================
  // 辅助方法
  // ============================================

  /**
   * 生成新的消息 ID
   */
  generateMessageId(): string {
    return uuidv4();
  },

  /**
   * 生成新的会话 ID
   */
  generateSessionId(): string {
    return uuidv4();
  },

  /**
   * 生成新的文件传输 ID
   */
  generateFileId(): string {
    return uuidv4();
  },

  /**
   * 格式化文件大小
   */
  formatFileSize(bytes: number): string {
    if (bytes === 0) return '0 B';
    const k = 1024;
    const sizes = ['B', 'KB', 'MB', 'GB'];
    const i = Math.floor(Math.log(bytes) / Math.log(k));
    return parseFloat((bytes / Math.pow(k, i)).toFixed(2)) + ' ' + sizes[i];
  },

  /**
   * 获取文件 MIME 类型
   */
  getMimeType(filename: string): string {
    const ext = filename.split('.').pop()?.toLowerCase() || '';
    const mimeTypes: Record<string, string> = {
      // 图片
      'jpg': 'image/jpeg',
      'jpeg': 'image/jpeg',
      'png': 'image/png',
      'gif': 'image/gif',
      'webp': 'image/webp',
      'svg': 'image/svg+xml',
      // 文档
      'pdf': 'application/pdf',
      'doc': 'application/msword',
      'docx': 'application/vnd.openxmlformats-officedocument.wordprocessingml.document',
      'xls': 'application/vnd.ms-excel',
      'xlsx': 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet',
      'ppt': 'application/vnd.ms-powerpoint',
      'pptx': 'application/vnd.openxmlformats-officedocument.presentationml.presentation',
      // 文本
      'txt': 'text/plain',
      'md': 'text/markdown',
      'json': 'application/json',
      'xml': 'application/xml',
      'html': 'text/html',
      'css': 'text/css',
      'js': 'application/javascript',
      // 压缩
      'zip': 'application/zip',
      'rar': 'application/x-rar-compressed',
      '7z': 'application/x-7z-compressed',
      // 音视频
      'mp3': 'audio/mpeg',
      'mp4': 'video/mp4',
      'avi': 'video/x-msvideo',
      'mov': 'video/quicktime',
      'apk': 'application/vnd.android.package-archive',
    };
    return mimeTypes[ext] || 'application/octet-stream';
  },
};

export default transferClient;

