                Column(verticalArrangement = Arrangement.spacedBy(8.dp)) {
                    Row(horizontalArrangement = Arrangement.spacedBy(8.dp)) {
                        QuadrantSelectChip(
                            label = "紧急重要",
                            color = MaterialTheme.colorScheme.error,
                            selected = selectedQuadrant == TodoQuadrant.URGENT_IMPORTANT,
                            onClick = { selectedQuadrant = TodoQuadrant.URGENT_IMPORTANT },
                            modifier = Modifier.weight(1f)
                        )
                        QuadrantSelectChip(
                            label = "重要不紧急",
                            color = MaterialTheme.colorScheme.primary,
                            selected = selectedQuadrant == TodoQuadrant.NOT_URGENT_IMPORTANT,
                            onClick = { selectedQuadrant = TodoQuadrant.NOT_URGENT_IMPORTANT },
                            modifier = Modifier.weight(1f)
                        )
                    }
                    Row(horizontalArrangement = Arrangement.spacedBy(8.dp)) {
                        QuadrantSelectChip(
                            label = "紧急不重要",
                            color = MaterialTheme.colorScheme.tertiary,
                            selected = selectedQuadrant == TodoQuadrant.URGENT_NOT_IMPORTANT,
                            onClick = { selectedQuadrant = TodoQuadrant.URGENT_NOT_IMPORTANT },
                            modifier = Modifier.weight(1f)
                        )
                        QuadrantSelectChip(
                            label = "不紧急不重要",
                            color = MaterialTheme.colorScheme.outline,
                            selected = selectedQuadrant == TodoQuadrant.NOT_URGENT_NOT_IMPORTANT,
                            onClick = { selectedQuadrant = TodoQuadrant.NOT_URGENT_NOT_IMPORTANT },
                            modifier = Modifier.weight(1f)
                        )
                    }
                }

                HorizontalDivider()

                // 到期时间
                Row(
                    modifier = Modifier
                        .fillMaxWidth()
                        .clickable { showDateTimePicker { dueDate = it } }
                        .padding(vertical = 8.dp),
                    verticalAlignment = Alignment.CenterVertically
                ) {
                    Icon(
                        Icons.Outlined.Event,
                        contentDescription = null,
                        tint = MaterialTheme.colorScheme.primary
                    )
                    Spacer(modifier = Modifier.width(12.dp))
                    Column(modifier = Modifier.weight(1f)) {
                        Text("到期时间", style = MaterialTheme.typography.bodyMedium)
                        Text(
                            text = dueDate?.let { dateFormat.format(Date(it)) } ?: "未设置",
                            style = MaterialTheme.typography.bodySmall,
                            color = MaterialTheme.colorScheme.outline
                        )
                    }
                    if (dueDate != null) {
                        IconButton(onClick = { dueDate = null }) {
                            Icon(Icons.Default.Close, contentDescription = "清除", modifier = Modifier.size(20.dp))
                        }
                    }
                }

                // 提醒时间
                Row(
                    modifier = Modifier
                        .fillMaxWidth()
                        .clickable { showDateTimePicker { reminderTime = it } }
                        .padding(vertical = 8.dp),
                    verticalAlignment = Alignment.CenterVertically
                ) {
                    Icon(
                        Icons.Outlined.Notifications,
                        contentDescription = null,
                        tint = MaterialTheme.colorScheme.tertiary
                    )
                    Spacer(modifier = Modifier.width(12.dp))
                    Column(modifier = Modifier.weight(1f)) {
                        Text("提醒时间", style = MaterialTheme.typography.bodyMedium)
                        Text(
                            text = reminderTime?.let { dateFormat.format(Date(it)) } ?: "未设置",
                            style = MaterialTheme.typography.bodySmall,
                            color = MaterialTheme.colorScheme.outline
                        )
                    }
                    if (reminderTime != null) {
                        IconButton(onClick = { reminderTime = null }) {
                            Icon(Icons.Default.Close, contentDescription = "清除", modifier = Modifier.size(20.dp))
                        }
                    }
                }
            }
        },
        confirmButton = {
            TextButton(
                onClick = { onConfirm(todoTitle, description, selectedQuadrant, dueDate, reminderTime) },
                enabled = todoTitle.isNotBlank()
            ) {
                Text("确定")
            }
        },
        dismissButton = {
            TextButton(onClick = onDismiss) {
                Text("取消")
            }
        }
    )
}

@Composable
private fun QuadrantSelectChip(
    label: String,
    color: Color,
    selected: Boolean,
    onClick: () -> Unit,
    modifier: Modifier = Modifier
) {
    Surface(
        modifier = modifier
            .clip(RoundedCornerShape(8.dp))
            .clickable(onClick = onClick),
        color = if (selected) color.copy(alpha = 0.15f) else MaterialTheme.colorScheme.surfaceVariant,
        shape = RoundedCornerShape(8.dp)
    ) {
        Row(
            modifier = Modifier.padding(horizontal = 12.dp, vertical = 10.dp),
            verticalAlignment = Alignment.CenterVertically,
            horizontalArrangement = Arrangement.Center
        ) {
            if (selected) {
                Icon(
                    Icons.Default.Check,
                    contentDescription = null,
                    tint = color,
                    modifier = Modifier.size(16.dp)
                )
                Spacer(modifier = Modifier.width(4.dp))
            }
            Text(
                text = label,
                style = MaterialTheme.typography.labelMedium,
                color = if (selected) color else MaterialTheme.colorScheme.onSurfaceVariant
            )
        }
    }
}

import { ItemBase, ItemType, SyncModules, SYNC_MODULE_TYPES, ResourcePayload } from '@shared/types';
import { StorageAdapter, RemoteChange, CHANGE_LOG_RETENTION } from './StorageAdapter';
import { ItemsManager } from '../database/ItemsManager';
import * as fs from 'fs';
import * as path from 'path';

export interface SyncResult {
  success: boolean;
  pushed: number;
  pulled: number;
  conflicts: number;
  errors: string[];
  duration: number;
  cleanedChangeLogs?: number;  // 清理的变更日志数量
}

// 同步进度信息
export interface SyncProgress {
  phase: 'idle' | 'connecting' | 'pushing' | 'pulling' | 'committing' | 'done' | 'error';
  message: string;
  current?: number;
  total?: number;
  detail?: string;
}

export type SyncProgressCallback = (progress: SyncProgress) => void;

// 服务器标识信息（用于区分不同的同步后端）
export interface ServerIdentifier {
  type: 'webdav' | 'server';
  url: string;
}

export interface SyncOptions {
  conflictStrategy: 'remote-wins' | 'local-wins' | 'create-copy';
  syncModules: SyncModules;
  onProgress?: SyncProgressCallback;
  serverIdentifier?: ServerIdentifier;  // 服务器标识，用于独立存储游标
  resourcesDir?: string;  // 资源文件目录路径
}

export class SyncEngine {
  private adapter: StorageAdapter;
  private itemsManager: ItemsManager;
  private options: SyncOptions;
  private allowedTypes: Set<ItemType>;
  private progressCallback: SyncProgressCallback | null = null;
  private serverIdentifier: ServerIdentifier | null = null;
  private resourcesDir: string | null = null;

  constructor(
    adapter: StorageAdapter,
    itemsManager: ItemsManager,
    options: Partial<SyncOptions> = {}
  ) {
    this.adapter = adapter;
    this.itemsManager = itemsManager;
    this.options = {
      conflictStrategy: 'create-copy',
      syncModules: {
        notes: true,
        bookmarks: true,
        vault: true,
        diagrams: true,
        todos: true,
        ai: true,
      },
      ...options,
    };
    this.allowedTypes = this.buildAllowedTypes();
    this.progressCallback = options.onProgress || null;
    this.serverIdentifier = options.serverIdentifier || null;
    this.resourcesDir = options.resourcesDir || null;
  }

  // 设置资源目录
  setResourcesDir(dir: string): void {
    this.resourcesDir = dir;
    console.log('[SyncEngine] Resources directory set:', dir);
  }

  // 设置服务器标识（用于独立存储游标）
  setServerIdentifier(identifier: ServerIdentifier): void {
    this.serverIdentifier = identifier;
    console.log('[SyncEngine] Server identifier set:', identifier.type, identifier.url);
  }

  // 获取当前服务器的游标
  private getServerCursor(): { cursor: string | null; timestamp: number | null } {
    if (this.serverIdentifier) {
      const cursorData = this.itemsManager.getLocalSyncCursor(
        this.serverIdentifier.type,
        this.serverIdentifier.url
      );
      return {
        cursor: cursorData?.cursor || null,
        timestamp: cursorData?.timestamp || null,
      };
    }
    // 兼容旧版本
    const cursorData = this.itemsManager.getLocalSyncCursor();
    return {
      cursor: cursorData?.cursor || null,
      timestamp: cursorData?.timestamp || null,
    };
  }

  // 保存当前服务器的游标
  private setServerCursor(cursor: string, timestamp: number): boolean {
    if (this.serverIdentifier) {
      return this.itemsManager.setLocalSyncCursor(
        { cursor, timestamp },
        this.serverIdentifier.type,
        this.serverIdentifier.url
      );
    }
    // 兼容旧版本
    return this.itemsManager.setLocalSyncCursor({ cursor, timestamp });
  }

  // 清除当前服务器的游标
  private clearServerCursor(): boolean {
    if (this.serverIdentifier) {
      return this.itemsManager.clearLocalSyncCursor(
        this.serverIdentifier.type,
        this.serverIdentifier.url
      );
    }
    // 兼容旧版本
    return this.itemsManager.clearLocalSyncCursor();
  }

  // 报告进度
  private reportProgress(progress: SyncProgress): void {
    if (this.progressCallback) {
      this.progressCallback(progress);
    }
  }

  // 根据模块配置构建允许同步的类型集合
  private buildAllowedTypes(): Set<ItemType> {
    const types = new Set<ItemType>();
    const modules = this.options.syncModules;

    console.log('[SyncEngine] Building allowed types, syncModules:', modules);

    for (const [module, enabled] of Object.entries(modules)) {
      if (enabled) {
        const moduleTypes = SYNC_MODULE_TYPES[module as keyof SyncModules];
        console.log(`[SyncEngine] Module ${module} enabled, types:`, moduleTypes);
        if (moduleTypes) {
          moduleTypes.forEach(t => types.add(t));
        }
      }
    }

    console.log('[SyncEngine] Final allowed types:', [...types]);
    return types;
  }

  // 检查类型是否允许同步
  private shouldSyncType(type: ItemType): boolean {
    return this.allowedTypes.has(type);
  }

  // 执行完整同步
  async sync(): Promise<SyncResult> {
    const startTime = Date.now();
    const result: SyncResult = {
      success: false,
      pushed: 0,
      pulled: 0,
      conflicts: 0,
      errors: [],
      duration: 0,
      cleanedChangeLogs: 0,
    };

    try {
      // 1. Push 阶段 - 上传本地变更
      this.reportProgress({ phase: 'pushing', message: '正在检查本地变更...' });
      const pushResult = await this.pushChanges();
      result.pushed = pushResult.count;
      result.errors.push(...pushResult.errors);

      // 2. Pull 阶段 - 拉取远端变更
      this.reportProgress({ phase: 'pulling', message: '正在检查远端变更...' });
      const pullResult = await this.pullChanges();
      result.pulled = pullResult.count;
      result.conflicts = pullResult.conflicts;
      result.errors.push(...pullResult.errors);

      // 3. Commit 阶段 - 更新同步状态
      this.reportProgress({ phase: 'committing', message: '正在完成同步...' });
      await this.commitSync();

      // 4. 清理过期的变更日志
      if (this.adapter.cleanupChangeLogs) {
        const cleanupBefore = Date.now() - CHANGE_LOG_RETENTION;
        result.cleanedChangeLogs = await this.adapter.cleanupChangeLogs(cleanupBefore);
      }

      result.success = result.errors.length === 0;

      const durationSec = ((Date.now() - startTime) / 1000).toFixed(1);
      this.reportProgress({ 
        phase: 'done', 
        message: `同步完成 (${durationSec}s)`,
        detail: `上传 ${result.pushed} 项, 下载 ${result.pulled} 项${result.conflicts > 0 ? `, ${result.conflicts} 个冲突` : ''}`
      });
    } catch (error) {
      this.reportProgress({ phase: 'error', message: '同步失败', detail: (error as Error).message });
      result.errors.push(`Sync failed: ${(error as Error).message}`);
    }

    result.duration = Date.now() - startTime;
    return result;
  }

  // Push 阶段：上传本地变更
  private async pushChanges(): Promise<{ count: number; errors: string[] }> {
    const errors: string[] = [];
    let count = 0;

    // 调试：检查数据库中所有 excel_note 的状态
    const allExcelNotes = this.itemsManager.getByType('excel_note');
    console.log('[SyncEngine] All excel_note in database:', allExcelNotes.length);
    allExcelNotes.forEach(note => {
      console.log(`[SyncEngine] Excel note: id=${note.id}, sync_status=${note.sync_status}, deleted_time=${note.deleted_time}`);
    });

    const allPendingItems = this.itemsManager.getPendingSync();
    console.log('[SyncEngine] All pending items:', allPendingItems.length);
    console.log('[SyncEngine] All pending items by type:', allPendingItems.reduce((acc, i) => {
      acc[i.type] = (acc[i.type] || 0) + 1;
      return acc;
    }, {} as Record<string, number>));
    console.log('[SyncEngine] Allowed types:', [...this.allowedTypes]);

    // 检查是否有 excel_note 类型
    const excelNotes = allPendingItems.filter(i => i.type === 'excel_note');
    if (excelNotes.length > 0) {
      console.log('[SyncEngine] Found excel_note items in pending:', excelNotes.map(i => ({ id: i.id, sync_status: i.sync_status })));
    } else {
      console.log('[SyncEngine] No excel_note items in pending sync');
    }

    const pendingItems = allPendingItems.filter(item => this.shouldSyncType(item.type));
    console.log('[SyncEngine] Filtered pending items:', pendingItems.length, 'types:', [...new Set(pendingItems.map(i => i.type))]);

    const total = pendingItems.length;
    if (total === 0) {
      this.reportProgress({ phase: 'pushing', message: '没有本地变更需要上传' });
      return { count: 0, errors: [] };
    }

    this.reportProgress({ phase: 'pushing', message: `正在上传 ${total} 项变更...`, current: 0, total });

    for (const item of pendingItems) {
      try {
        // 明文同步：确保 encryption_applied = 0
        const itemToUpload: ItemBase = {
          ...item,
          encryption_applied: 0 as const,
        };

        // 上传 item 元数据
        const result = await this.adapter.putItem(itemToUpload);

        if (result.success) {
          let resourceUploadFailed = false;

          // 如果是资源类型，同时上传资源文件
          if (item.type === 'resource' && this.resourcesDir) {
            try {
              const payload = JSON.parse(item.payload) as ResourcePayload;
              // 从 item.id 和 payload.filename 获取文件扩展名
              const ext = path.extname(payload.filename).toLowerCase() || '.bin';
              const resourceFilePath = path.join(this.resourcesDir, `${item.id}${ext}`);

              if (fs.existsSync(resourceFilePath)) {
                const fileData = fs.readFileSync(resourceFilePath);
                const resourceId = `${item.id}${ext}`;
                const uploadSuccess = await this.adapter.putResource(resourceId, fileData, payload.mime_type);
                if (!uploadSuccess) {
                  resourceUploadFailed = true;
                  console.warn(`[SyncEngine] Failed to upload resource file: ${resourceId}`);
                } else {
                  console.log(`[SyncEngine] Uploaded resource file: ${resourceId}`);
                }
              } else {
                resourceUploadFailed = true;
                console.warn(`[SyncEngine] Resource file not found: ${resourceFilePath}`);
              }
            } catch (resourceError) {
              resourceUploadFailed = true;
              console.error(`[SyncEngine] Error uploading resource file for ${item.id}:`, resourceError);
            }
          }

          if (resourceUploadFailed) {
            errors.push(`Failed to upload resource file for item ${item.id}`);
            continue;
          }

          this.itemsManager.markSynced(item.id, result.remoteRev);
          count++;
          this.reportProgress({ 
            phase: 'pushing', 
            message: `正在上传... (${count}/${total})`,
            current: count,
            total,
            detail: `上传: ${item.type}`
          });
        } else {
          const errorDetail = result.error ? `: ${result.error}` : '';
          errors.push(`Failed to push item ${item.id}${errorDetail}`);
        }
      } catch (error) {
        errors.push(`Error pushing item ${item.id}: ${(error as Error).message}`);
      }
    }

    this.reportProgress({ phase: 'pushing', message: `已上传 ${count} 项`, current: count, total });
    return { count, errors };
  }

  // Pull 阶段：拉取远端变更
  private async pullChanges(): Promise<{ count: number; conflicts: number; errors: string[] }> {
    const errors: string[] = [];
    let count = 0;
    let conflicts = 0;

    // ✅ 从本地数据库获取游标（按服务器独立存储）
    const { cursor: localCursor, timestamp: localTimestamp } = this.getServerCursor();
    let currentCursor = localCursor;

    // 检查游标格式是否兼容
    // 自建服务器使用纯数字格式（change_id），WebDAV 使用文件名格式（{timestamp}.json）
    if (currentCursor) {
      const isWebDAVFormat = currentCursor.endsWith('.json');
      const isServerType = this.serverIdentifier?.type === 'server';

      // 如果当前是自建服务器但游标是 WebDAV 格式，清除游标
      if (isServerType && isWebDAVFormat) {
        console.log('[SyncEngine] Detected WebDAV cursor format for server sync, clearing');
        this.clearServerCursor();
        currentCursor = null;
      }
      // 如果当前是自建服务器且游标是异常大的数字（时间戳误设为游标），清除游标
      // change_id 是自增整数，正常不会超过 10 亿；时间戳是 13 位数字（万亿级别）
      else if (isServerType && /^\d+$/.test(currentCursor) && parseInt(currentCursor, 10) > 1_000_000_000) {
        console.log('[SyncEngine] Detected abnormally large cursor for server sync (likely timestamp), clearing:', currentCursor);
        this.clearServerCursor();
        currentCursor = null;
      }
      // 如果当前是 WebDAV 但游标不是 .json 格式（说明是旧的错误格式），清除游标
      // 注意：WebDAV 游标必须是 "{timestamp}.json" 格式，纯数字是错误的历史遗留
      else if (!isServerType && this.serverIdentifier?.type === 'webdav' && !isWebDAVFormat) {
        console.log('[SyncEngine] Detected non-WebDAV cursor format for WebDAV sync, clearing');
        this.clearServerCursor();
        currentCursor = null;
      }
    }

    console.log('[SyncEngine] Pull starting with cursor:', currentCursor, 'timestamp:', localTimestamp, 'server:', this.serverIdentifier);
    console.log('[SyncEngine] Adapter type:', this.adapter.constructor.name);
    this.reportProgress({ phase: 'pulling', message: '正在获取远端变更列表...' });

    // ✅ 触发全量拉取的两种情况：
    // 1. 游标为 null（新客户端首次同步）
    // 2. 游标已过期（长时间离线，变更日志已被清理）
    const cursorExpired = currentCursor && this.adapter.isCursorExpired
      ? await this.adapter.isCursorExpired(currentCursor)
      : false;

    if ((!currentCursor || cursorExpired) && this.adapter.listAllItems) {
      const remoteHasData = this.adapter.hasExistingData
        ? await this.adapter.hasExistingData()
        : false;

      if (remoteHasData) {
        if (cursorExpired) {
          console.log('[SyncEngine] Cursor expired (change logs cleaned up) — falling back to full pull');
          this.reportProgress({ phase: 'pulling', message: '变更日志已过期，正在全量拉取远端数据...' });
          // 清除过期游标，避免后续误用
          this.clearServerCursor();
        } else {
          console.log('[SyncEngine] No cursor found and remote has data — performing full pull');
          this.reportProgress({ phase: 'pulling', message: '首次同步，正在全量拉取远端数据...' });
        }

        const allItems = await this.adapter.listAllItems();
        const filteredItems = allItems.filter(item => this.shouldSyncType(item.type));
        console.log(`[SyncEngine] Full pull: ${filteredItems.length} items to process (filtered from ${allItems.length})`);

        const total = filteredItems.length;
        for (const remoteItem of filteredItems) {
          try {
            // 跳过已删除的 item
            if (remoteItem.deleted_time !== null) {
              const localItem = this.itemsManager.getByIdIncludeDeleted(remoteItem.id);
              if (localItem) {
                this.itemsManager.markDeletedFromRemote(remoteItem.id, remoteItem.deleted_time);
              }
              continue;
            }

            const localItem = this.itemsManager.getByIdIncludeDeleted(remoteItem.id);

            if (!localItem) {
              // 本地没有，直接创建
              this.itemsManager.createWithId(remoteItem);
              count++;
            } else if (localItem.content_hash !== remoteItem.content_hash) {
              // 内容不同，检查冲突
              if (localItem.sync_status === 'modified') {
                // 有冲突，创建副本
                const conflictPayload = JSON.parse(localItem.payload);
                conflictPayload.title = `${conflictPayload.title || 'Untitled'} (冲突副本)`;
                conflictPayload.is_conflict = true;
                this.itemsManager.create(localItem.type, conflictPayload);
                this.itemsManager.updateFromRemote(remoteItem);
                conflicts++;
              } else {
                // 远端更新，覆盖本地
                this.itemsManager.updateFromRemote(remoteItem);
              }
              count++;
            }
            // 内容相同则跳过

            if (count % 50 === 0) {
              this.reportProgress({
                phase: 'pulling',
                message: `正在全量下载... (${count}/${total})`,
                current: count,
                total,
              });
            }

            // 同时下载资源文件
            if (remoteItem.type === 'resource' && this.resourcesDir) {
              try {
                const payload = JSON.parse(remoteItem.payload) as ResourcePayload;
                const ext = path.extname(payload.filename).toLowerCase() || '.bin';
                const resourceId = `${remoteItem.id}${ext}`;
                const resourceFilePath = path.join(this.resourcesDir, resourceId);

                if (!fs.existsSync(resourceFilePath)) {
                  if (!fs.existsSync(this.resourcesDir)) {
                    fs.mkdirSync(this.resourcesDir, { recursive: true });
                  }
                  const fileData = await this.adapter.getResource(resourceId);
                  if (fileData) {
                    fs.writeFileSync(resourceFilePath, fileData);
                  }
                }
              } catch (resourceError) {
                console.error(`[SyncEngine] Error downloading resource for ${remoteItem.id}:`, resourceError);
              }
            }
          } catch (error) {
            errors.push(`Error processing item ${remoteItem.id}: ${(error as Error).message}`);
          }
        }

        // 全量拉取完成后，将游标设置为服务器最新的 change_id
        // 这样后续增量同步就能正常工作
        let newCursor: string;
        const serverAdapter = this.adapter as any;
        const lastChangeId = serverAdapter.getLastFullPullChangeId ? serverAdapter.getLastFullPullChangeId() : null;
        if (lastChangeId !== null && lastChangeId !== undefined) {
          // 自建服务器：用数字 change_id（包括 0，表示 changes 表为空）
          newCursor = lastChangeId.toString();
        } else if (this.serverIdentifier?.type === 'webdav') {
          // WebDAV：游标必须是 "{timestamp}.json" 格式，与变更文件名一致
          // 用当前时间戳生成一个游标，确保后续增量同步能正确定位
          newCursor = `${Date.now()}.json`;
        } else {
          newCursor = Date.now().toString();
        }
        this.setServerCursor(newCursor, Date.now());
        console.log('[SyncEngine] Full pull complete, set cursor to:', newCursor);

        this.reportProgress({
          phase: 'pulling',
          message: `全量下载完成，共 ${count} 项`,
          current: count,
          total,
        });

        return { count, conflicts, errors };
      }
    }

    // ✅ 增量同步：有游标时走变更日志路径
    let lastSuccessfulCursor = currentCursor;  // 记录最后成功处理的游标
    console.log('[SyncEngine] Entering incremental sync path with cursor:', currentCursor);

    // 循环拉取所有变更
    let hasMore = true;
    let totalChanges = 0;
    let iterations = 0;
    const maxIterations = 100; // 防止无限循环

    while (hasMore && iterations < maxIterations) {
      iterations++;

      try {
        const { changes, nextCursor, hasMore: more } = await this.adapter.listChanges(currentCursor);
        hasMore = more;

        console.log(`[SyncEngine] listChanges: cursor=${currentCursor}, got ${changes.length} changes, hasMore=${more}, nextCursor=${nextCursor}`);
        if (changes.length > 0) {
          console.log(`[SyncEngine] First change: id=${changes[0].change_id}, item_id=${changes[0].item_id}, type=${changes[0].type}`);
          console.log(`[SyncEngine] Last change: id=${changes[changes.length-1].change_id}, item_id=${changes[changes.length-1].item_id}`);
        }

        const filteredChanges = changes.filter(c => this.shouldSyncType(c.type));
        totalChanges += filteredChanges.length;

        if (filteredChanges.length > 0) {
          this.reportProgress({ 
            phase: 'pulling', 
            message: `正在下载... (${count}/${totalChanges})`,
            current: count,
            total: totalChanges
          });
        }

        let batchSuccessful = true;
        for (const change of filteredChanges) {
          try {
            const result = await this.processRemoteChange(change);
            if (result.success && !result.skipped) {
              count++;
              this.reportProgress({ 
                phase: 'pulling', 
                message: `正在下载... (${count}/${totalChanges})`,
                current: count,
                total: totalChanges,
                detail: `下载: ${change.type}`
              });
            }
            if (result.conflict) {
              conflicts++;
            }
            if (result.error) {
              errors.push(result.error);
              batchSuccessful = false;
            }
          } catch (error) {
            errors.push(`Error processing change ${change.item_id}: ${(error as Error).message}`);
            batchSuccessful = false;
          }
        }

        // 每批次处理完成后更新本地游标（增量更新，避免重复处理）
        if (nextCursor && batchSuccessful) {
          lastSuccessfulCursor = nextCursor;
          // ✅ 保存到本地数据库（按服务器独立存储）
          this.setServerCursor(lastSuccessfulCursor, Date.now());
          console.log('[SyncEngine] Updated cursor to:', lastSuccessfulCursor, 'for server:', this.serverIdentifier);
        }

        currentCursor = nextCursor;
      } catch (error) {
        console.error('Error in pullChanges iteration:', error);
        errors.push(`Pull changes error: ${(error as Error).message}`);
        hasMore = false; // 出错时停止循环
      }
    }

    if (iterations >= maxIterations) {
      console.warn('Pull changes reached max iterations limit');
      errors.push('Pull changes reached iteration limit');
    }

    if (count === 0) {
      this.reportProgress({ phase: 'pulling', message: '没有远端变更需要下载' });
    } else {
      this.reportProgress({ phase: 'pulling', message: `已下载 ${count} 项`, current: count, total: totalChanges });
    }

    return { count, conflicts, errors };
  }

  // 处理单个远端变更
  private async processRemoteChange(change: RemoteChange): Promise<{
    success: boolean;
    conflict: boolean;
    skipped?: boolean;
    error?: string;
  }> {
    // 使用包含已删除项的查询，确保能找到本地已存在的数据
    const localItem = this.itemsManager.getByIdIncludeDeleted(change.item_id);
    console.log(`[SyncEngine] processRemoteChange: item_id=${change.item_id}, type=${change.type}, deleted=${change.deleted_time !== null}, localExists=${!!localItem}, localSyncStatus=${localItem?.sync_status}, localHash=${localItem?.content_hash?.substring(0, 8)}, remoteHash=${change.content_hash?.substring(0, 8)}`);

    // 简化逻辑：远端标记删除，本地直接删除
    if (change.deleted_time !== null) {
      if (localItem) {
        // 本地有数据，直接标记删除
        this.itemsManager.markDeletedFromRemote(change.item_id, change.deleted_time);
        console.log(`[SyncEngine] Marked local item ${change.item_id} as deleted from remote`);
      }
      // 本地没有数据，不需要处理（已删除的数据不需要创建）
      return { success: true, conflict: false };
    }

    // 以下处理非删除的变更
    if (localItem && localItem.deleted_time === null && localItem.sync_status === 'clean') {
      // 本地未删除且状态为 clean，检查是否需要更新
      if (localItem.content_hash === change.content_hash) {
        return { success: true, conflict: false, skipped: true };
      }
    }

    // 检查是否有冲突
    if (localItem && localItem.deleted_time === null && localItem.sync_status === 'modified') {
      return this.handleConflict(localItem, change);
    }

    // 拉取远端完整数据
    const remoteItem = await this.adapter.getItem(change.item_id);
    if (!remoteItem) {
      console.warn(`Remote item ${change.item_id} not found, skipping`);
      return { success: true, conflict: false };
    }

    // 如果是资源类型，下载资源文件
    if (change.type === 'resource' && this.resourcesDir) {
      try {
        const payload = JSON.parse(remoteItem.payload) as ResourcePayload;
        const ext = path.extname(payload.filename).toLowerCase() || '.bin';
        const resourceId = `${remoteItem.id}${ext}`;
        const resourceFilePath = path.join(this.resourcesDir, resourceId);

        if (!fs.existsSync(this.resourcesDir)) {
          fs.mkdirSync(this.resourcesDir, { recursive: true });
        }

        const fileData = await this.adapter.getResource(resourceId);
        if (fileData) {
          fs.writeFileSync(resourceFilePath, fileData);
        }
      } catch (resourceError) {
        console.error(`[SyncEngine] Error downloading resource file for ${change.item_id}:`, resourceError);
      }
    }

    // 写入本地
    if (localItem && localItem.deleted_time === null) {
      this.itemsManager.updateFromRemote(remoteItem);
    } else {
      this.itemsManager.createWithId(remoteItem);
    }

    return { success: true, conflict: false };
  }

  // 处理冲突
  private async handleConflict(localItem: ItemBase, remoteChange: RemoteChange): Promise<{
    success: boolean;
    conflict: boolean;
    skipped?: boolean;
    error?: string;
  }> {
    const remoteItem = await this.adapter.getItem(remoteChange.item_id);
    if (!remoteItem) {
      return { success: false, conflict: true, error: 'Remote item not found during conflict resolution' };
    }

    switch (this.options.conflictStrategy) {
      case 'remote-wins':
        // 远端覆盖本地（使用专门的同步更新方法）
        this.itemsManager.updateFromRemote(remoteItem);
        return { success: true, conflict: true };

      case 'local-wins':
        // 保持本地，下次 push 会覆盖远端
        return { success: true, conflict: true };

      case 'create-copy':
      default:
        // 创建冲突副本
        const conflictPayload = JSON.parse(localItem.payload);
        conflictPayload.title = `${conflictPayload.title || 'Untitled'} (冲突副本)`;
        conflictPayload.is_conflict = true;

        this.itemsManager.create(localItem.type, conflictPayload);

        // 用远端版本覆盖原记录（使用专门的同步更新方法）
        this.itemsManager.updateFromRemote(remoteItem);

        return { success: true, conflict: true };
    }
  }

  // 验证加密密钥
  // Commit 阶段
  private async commitSync(): Promise<void> {
    // 更新远端元数据
    const meta = await this.adapter.getRemoteMeta();
    meta.last_sync_time = Date.now();
    await this.adapter.putRemoteMeta(meta);
  }

  // 设置同步选项
  setOptions(options: Partial<SyncOptions>): void {
    this.options = { ...this.options, ...options };
    // 如果模块配置变化，重新构建允许的类型集合
    if (options.syncModules) {
      this.allowedTypes = this.buildAllowedTypes();
    }
    // 更新进度回调
    if (options.onProgress !== undefined) {
      this.progressCallback = options.onProgress;
    }
  }

  // 设置进度回调
  setProgressCallback(callback: SyncProgressCallback | null): void {
    this.progressCallback = callback;
  }

  // 获取同步状态
  async getStatus(): Promise<{
    pendingPush: number;
    lastSyncTime: number | null;
    isLocked: boolean;
  }> {
    const pendingItems = this.itemsManager.getPendingSync()
      .filter(item => this.shouldSyncType(item.type));
    const { timestamp } = this.getServerCursor();

    return {
      pendingPush: pendingItems.length,
      lastSyncTime: timestamp,
      isLocked: false,  // 锁机制已移除
    };
  }

  // 强制标记所有数据为待同步
  forceMarkAllForSync(): number {
    return this.itemsManager.markAllForSync();
  }

  // 重置同步状态（用于切换服务器或强制完全重新同步）
  resetSyncStatus(): number {
    // 清除当前服务器的同步游标，这样下次同步会从头开始拉取所有变更
    this.clearServerCursor();
    console.log('[SyncEngine] Cleared sync cursor for server:', this.serverIdentifier);

    return this.itemsManager.resetSyncStatus();
  }

  // 检查远端是否已有数据（用于首次同步检测）
  async checkRemoteHasData(): Promise<boolean> {
    if (this.adapter.hasExistingData) {
      return this.adapter.hasExistingData();
    }
    // 回退：检查远端元数据
    const meta = await this.adapter.getRemoteMeta();
    return meta.last_sync_time !== null;
  }
}

export default SyncEngine;

/**
 * LAN Transfer Assistant - 中继服务器
 * 
 * 当设备无法直接通过局域网连接时，提供消息和文件转发服务
 */

import { Server as SocketIOServer, Socket } from 'socket.io';
import { Server as HttpServer } from 'http';
import { config } from '../config';

// ============================================
// 常量定义
// ============================================

const SOCKET_EVENTS = {
  // 设备相关
  DEVICE_REGISTER: 'device:register',
  DEVICE_LIST: 'device:list',
  DEVICE_ONLINE: 'device:online',
  DEVICE_OFFLINE: 'device:offline',

  // 配对相关
  PAIR_REQUEST: 'pair:request',
  PAIR_ACCEPT: 'pair:accept',
  PAIR_REJECT: 'pair:reject',
  PAIR_SUCCESS: 'pair:success',

  // 消息相关
  MESSAGE_SEND: 'message:send',
  MESSAGE_RECEIVE: 'message:receive',
  MESSAGE_READ: 'message:read',

  // 文件传输相关
  FILE_START: 'file:start',
  FILE_CHUNK: 'file:chunk',
  FILE_COMPLETE: 'file:complete',
  FILE_INCOMING: 'file:incoming',
  FILE_PROGRESS: 'file:progress',
  FILE_CANCEL: 'file:cancel',
  FILE_ERROR: 'file:error',

  // 通用
  ERROR: 'error',
  HEARTBEAT: 'heartbeat',
  DISCONNECT: 'disconnect',
};

// ============================================
// 类型定义
// ============================================

interface ConnectedDevice {
  id: string;
  name: string;
  type: 'desktop' | 'android';
  socketId: string;
  connectedAt: number;
  lastHeartbeat: number;
}

interface RateLimitInfo {
  messageCount: number;
  lastReset: number;
  fileTransferCount: number;
}

interface PairSession {
  sessionId: string;
  deviceIds: [string, string];
  createdAt: number;
}

interface FileTransferSession {
  fileId: string;
  sessionId: string;
  senderId: string;
  targetDeviceId: string;
  createdAt: number;
}

// ============================================
// TransferRelayServer 类
// ============================================

export class TransferRelayServer {
  private io: SocketIOServer | null = null;
  private connectedDevices: Map<string, ConnectedDevice> = new Map();
  private socketToDevice: Map<string, string> = new Map();
  private rateLimits: Map<string, RateLimitInfo> = new Map();
  private pairSessions: Map<string, PairSession> = new Map();
  private fileTransfers: Map<string, FileTransferSession> = new Map();

  private heartbeatInterval: NodeJS.Timeout | null = null;
  private cleanupInterval: NodeJS.Timeout | null = null;

  // 配置
  private readonly maxConnections: number;
  private readonly messageRateLimit: number;
  private readonly fileTransferLimit: number;
  private readonly sessionTimeout: number;
  private readonly heartbeatInterval_ms: number;

  // 中继密钥
  private readonly relayKey: string;

  constructor() {
    this.maxConnections = config.transfer?.maxConnections || 100;
    this.messageRateLimit = config.transfer?.messageRateLimit || 60; // 每分钟
    this.fileTransferLimit = config.transfer?.fileTransferLimit || 10; // 每分钟
    this.sessionTimeout = config.transfer?.sessionTimeout || 30 * 60 * 1000; // 30分钟
    this.heartbeatInterval_ms = config.transfer?.heartbeatInterval || 30 * 1000; // 30秒
    this.relayKey = config.transfer?.relayKey || config.transferRelayKey || '';
  }

  /**
   * 初始化中继服务器
   */
  initialize(httpServer: HttpServer): void {
    this.io = new SocketIOServer(httpServer, {
      path: config.transferRelayPath,
      cors: {
        origin: '*',
        methods: ['GET', 'POST'],
      },
      maxHttpBufferSize: 64 * 1024 * 2, // 128KB for chunks
    });

    this.setupSocketHandlers();
    this.startHeartbeatCheck();
    this.startCleanupTask();

    console.log(`[TransferRelay] Initialized on path ${config.transferRelayPath}`);
  }

  /**
   * 关闭中继服务器
   */
  close(): void {
    if (this.heartbeatInterval) {
      clearInterval(this.heartbeatInterval);
      this.heartbeatInterval = null;
    }

    if (this.cleanupInterval) {
      clearInterval(this.cleanupInterval);
      this.cleanupInterval = null;
    }

    if (this.io) {
      this.io.close();
      this.io = null;
    }

    this.connectedDevices.clear();
    this.socketToDevice.clear();
    this.rateLimits.clear();
    this.pairSessions.clear();
    this.fileTransfers.clear();

    console.log('[TransferRelay] Closed');
  }

  /**
   * 获取统计信息
   */
  getStats(): {
    connectedDevices: number;
    maxConnections: number;
  } {
    return {
      connectedDevices: this.connectedDevices.size,
      maxConnections: this.maxConnections,
    };
  }

  // ============================================
  // Socket 事件处理
  // ============================================

  private setupSocketHandlers(): void {
    if (!this.io) return;

    // 连接时验证密钥
    this.io.use((socket, next) => {
      const relayKey = socket.handshake.auth?.relayKey || socket.handshake.query?.relayKey;

      if (!this.relayKey || !relayKey || relayKey !== this.relayKey) {
        console.log(`[TransferRelay] Connection rejected: invalid relay key from ${socket.id}`);
        return next(new Error('INVALID_RELAY_KEY'));
      }

      next();
    });

    this.io.on('connection', (socket: Socket) => {
      console.log(`[TransferRelay] New connection: ${socket.id}`);

      // 设备注册
      socket.on(SOCKET_EVENTS.DEVICE_REGISTER, (data: {
        deviceId: string;
        deviceName: string;
        deviceType: 'desktop' | 'android';
      }) => {
        this.handleDeviceRegister(socket, data);
      });

      // 配对请求
      socket.on(SOCKET_EVENTS.PAIR_REQUEST, (data: { targetDeviceId: string }) => {
        this.handlePairRequest(socket, data);
      });

      // 配对接受
      socket.on(SOCKET_EVENTS.PAIR_ACCEPT, (data: { requesterId: string; sessionId: string }) => {
        this.handlePairAccept(socket, data);
      });

      // 配对拒绝
      socket.on(SOCKET_EVENTS.PAIR_REJECT, (data: { requesterId: string }) => {
        this.handlePairReject(socket, data);
      });

      // 消息发送
      socket.on(SOCKET_EVENTS.MESSAGE_SEND, (data: any) => {
        this.handleMessageSend(socket, data);
      });

      // 消息已读
      socket.on(SOCKET_EVENTS.MESSAGE_READ, (data: any) => {
        this.handleMessageRead(socket, data);
      });

      // 文件传输开始
      socket.on(SOCKET_EVENTS.FILE_START, (data: any) => {
        this.handleFileStart(socket, data);
      });

      // 文件分块
      socket.on(SOCKET_EVENTS.FILE_CHUNK, (data: any) => {
        this.handleFileChunk(socket, data);
      });

      // 文件传输完成
      socket.on(SOCKET_EVENTS.FILE_COMPLETE, (data: any) => {
        this.handleFileComplete(socket, data);
      });

      // 文件传输取消
      socket.on(SOCKET_EVENTS.FILE_CANCEL, (data: any) => {
        this.handleFileCancel(socket, data);
      });

      // 心跳
      socket.on(SOCKET_EVENTS.HEARTBEAT, () => {
        this.handleHeartbeat(socket);
      });

      // 断开连接
      socket.on(SOCKET_EVENTS.DISCONNECT, () => {
        this.handleDisconnect(socket);
      });
    });
  }

  private handleDeviceRegister(
    socket: Socket,
    data: { deviceId: string; deviceName: string; deviceType: 'desktop' | 'android' }
  ): void {
    const { deviceId, deviceName, deviceType } = data;

    // 检查连接数限制
    if (this.connectedDevices.size >= this.maxConnections) {
      socket.emit(SOCKET_EVENTS.ERROR, {
        code: 'E402',
        message: '服务器连接数已满',
      });
      socket.disconnect(true);
      return;
    }

    // 检查是否已存在相同设备 ID
    if (this.connectedDevices.has(deviceId)) {
      const existingDevice = this.connectedDevices.get(deviceId)!;
      // 断开旧连接
      const oldSocket = this.io?.sockets.sockets.get(existingDevice.socketId);
      if (oldSocket) {
        oldSocket.disconnect(true);
      }
      this.socketToDevice.delete(existingDevice.socketId);
    }

    const device: ConnectedDevice = {
      id: deviceId,
      name: deviceName,
      type: deviceType,
      socketId: socket.id,
      connectedAt: Date.now(),
      lastHeartbeat: Date.now(),
    };

    this.connectedDevices.set(deviceId, device);
    this.socketToDevice.set(socket.id, deviceId);
    this.rateLimits.set(deviceId, {
      messageCount: 0,
      lastReset: Date.now(),
      fileTransferCount: 0,
    });

    console.log(`[TransferRelay] Device registered: ${deviceName} (${deviceId})`);

    // 发送设备列表给新设备
    socket.emit(SOCKET_EVENTS.DEVICE_LIST, this.getDeviceListForClient(deviceId));

    // 广播新设备上线
    socket.broadcast.emit(SOCKET_EVENTS.DEVICE_ONLINE, {
      device: {
        id: device.id,
        name: device.name,
        type: device.type,
      },
    });
  }

  private handlePairRequest(socket: Socket, data: { targetDeviceId: string }): void {
    const requesterId = this.socketToDevice.get(socket.id);
    if (!requesterId) return;

    const requester = this.connectedDevices.get(requesterId);
    const target = this.connectedDevices.get(data.targetDeviceId);

    if (!requester || !target) {
      socket.emit(SOCKET_EVENTS.ERROR, {
        code: 'E301',
        message: '目标设备不存在',
      });
      return;
    }

    // 转发配对请求给目标设备
    const targetSocket = this.io?.sockets.sockets.get(target.socketId);
    if (targetSocket) {
      targetSocket.emit(SOCKET_EVENTS.PAIR_REQUEST, {
        requesterId,
        requesterName: requester.name,
      });
    }
  }

  private handlePairAccept(socket: Socket, data: { requesterId: string; sessionId: string }): void {
    const accepterId = this.socketToDevice.get(socket.id);
    if (!accepterId) return;

    const requester = this.connectedDevices.get(data.requesterId);
    const accepter = this.connectedDevices.get(accepterId);

    if (!requester || !accepter) return;

    this.pairSessions.set(data.sessionId, {
      sessionId: data.sessionId,
      deviceIds: [data.requesterId, accepterId],
      createdAt: Date.now(),
    });

    // 通知请求方配对成功
    const requesterSocket = this.io?.sockets.sockets.get(requester.socketId);
    if (requesterSocket) {
      requesterSocket.emit(SOCKET_EVENTS.PAIR_SUCCESS, {
        sessionId: data.sessionId,
        peerId: accepterId,
        peerName: accepter.name,
      });
    }

    // 通知接受方配对成功
    socket.emit(SOCKET_EVENTS.PAIR_SUCCESS, {
      sessionId: data.sessionId,
      peerId: data.requesterId,
      peerName: requester.name,
    });
  }

  private handlePairReject(socket: Socket, data: { requesterId: string }): void {
    const requester = this.connectedDevices.get(data.requesterId);
    if (requester) {
      const requesterSocket = this.io?.sockets.sockets.get(requester.socketId);
      if (requesterSocket) {
        requesterSocket.emit(SOCKET_EVENTS.ERROR, {
          code: 'E104',
          message: '配对请求被拒绝',
        });
      }
    }
  }

  private handleMessageSend(socket: Socket, data: any): void {
    const senderId = this.socketToDevice.get(socket.id);
    console.log(`[TransferRelay] MESSAGE_SEND from socket ${socket.id}, senderId: ${senderId}`);

    if (!senderId) {
      console.log(`[TransferRelay] Sender not registered, ignoring message`);
      return;
    }

    // 检查限流
    if (!this.checkRateLimit(senderId, 'message')) {
      socket.emit(SOCKET_EVENTS.ERROR, {
        code: 'E403',
        message: '消息发送过于频繁，请稍后再试',
      });
      return;
    }

    const { targetDeviceId, sessionId, message } = data;
    if (!this.isValidPairSession(sessionId, senderId, targetDeviceId)) {
      socket.emit(SOCKET_EVENTS.ERROR, {
        code: 'E304',
        message: '无效的配对会话',
      });
      return;
    }

    const target = this.connectedDevices.get(targetDeviceId);

    if (!target) {
      console.log(`[TransferRelay] Target device ${targetDeviceId} NOT FOUND in connected devices`);
      socket.emit(SOCKET_EVENTS.ERROR, {
        code: 'E301',
        message: '目标设备不在线',
      });
      return;
    }

    // 转发消息
    const targetSocket = this.io?.sockets.sockets.get(target.socketId);
    if (targetSocket) {
      targetSocket.emit(SOCKET_EVENTS.MESSAGE_RECEIVE, {
        senderId,
        sessionId,
        message,
      });
    } else {
      console.log(`[TransferRelay] Target socket not found for socketId: ${target.socketId}`);
    }
  }

  private handleMessageRead(socket: Socket, data: any): void {
    const readerId = this.socketToDevice.get(socket.id);
    if (!readerId) return;

    const { targetDeviceId, messageIds } = data;
    const target = this.connectedDevices.get(targetDeviceId);

    if (target) {
      const targetSocket = this.io?.sockets.sockets.get(target.socketId);
      if (targetSocket) {
        targetSocket.emit(SOCKET_EVENTS.MESSAGE_READ, {
          readerId,
          messageIds,
        });
      }
    }
  }

  private handleFileStart(socket: Socket, data: any): void {
    const senderId = this.socketToDevice.get(socket.id);
    if (!senderId) return;

    // 检查限流
    if (!this.checkRateLimit(senderId, 'file')) {
      socket.emit(SOCKET_EVENTS.ERROR, {
        code: 'E403',
        message: '文件传输过于频繁，请稍后再试',
      });
      return;
    }

    const { targetDeviceId, sessionId, fileInfo } = data;
    if (!this.isValidPairSession(sessionId, senderId, targetDeviceId)) {
      socket.emit(SOCKET_EVENTS.ERROR, {
        code: 'E304',
        message: '无效的配对会话',
      });
      return;
    }

    if (
      config.transferMaxFileSize > 0 &&
      typeof fileInfo?.fileSize === 'number' &&
      fileInfo.fileSize > config.transferMaxFileSize
    ) {
      socket.emit(SOCKET_EVENTS.ERROR, {
        code: 'E201',
        message: '文件过大',
      });
      return;
    }

    const target = this.connectedDevices.get(targetDeviceId);

    if (!target) {
      socket.emit(SOCKET_EVENTS.ERROR, {
        code: 'E301',
        message: '目标设备不在线',
      });
      return;
    }

    // 转发文件开始事件
    const targetSocket = this.io?.sockets.sockets.get(target.socketId);
    if (targetSocket) {
      this.fileTransfers.set(fileInfo.id, {
        fileId: fileInfo.id,
        sessionId,
        senderId,
        targetDeviceId,
        createdAt: Date.now(),
      });

      targetSocket.emit(SOCKET_EVENTS.FILE_INCOMING, {
        senderId,
        sessionId,
        fileInfo,
      });
    }
  }

  private handleFileChunk(socket: Socket, data: any): void {
    const senderId = this.socketToDevice.get(socket.id);
    if (!senderId) return;

    const { targetDeviceId, fileId, chunkIndex, chunk, totalChunks } = data;
    const target = this.connectedDevices.get(targetDeviceId);
    const transfer = this.fileTransfers.get(fileId);

    if (!target || !transfer) return;
    if (transfer.senderId !== senderId || transfer.targetDeviceId !== targetDeviceId) {
      socket.emit(SOCKET_EVENTS.ERROR, {
        code: 'E304',
        message: '无效的文件传输会话',
      });
      return;
    }

    // 直接转发文件分块（不存储）
    const targetSocket = this.io?.sockets.sockets.get(target.socketId);
    if (targetSocket) {
      targetSocket.emit(SOCKET_EVENTS.FILE_CHUNK, {
        senderId,
        sessionId: transfer.sessionId,
        fileId,
        chunkIndex,
        chunk,
        totalChunks,
      });
    }
  }

  private handleFileComplete(socket: Socket, data: any): void {
    const senderId = this.socketToDevice.get(socket.id);
    if (!senderId) return;

    const { targetDeviceId, fileId, fileHash } = data;
    const target = this.connectedDevices.get(targetDeviceId);
    const transfer = this.fileTransfers.get(fileId);

    if (!target || !transfer) return;
    if (transfer.senderId !== senderId || transfer.targetDeviceId !== targetDeviceId) {
      socket.emit(SOCKET_EVENTS.ERROR, {
        code: 'E304',
        message: '无效的文件传输会话',
      });
      return;
    }

    const targetSocket = this.io?.sockets.sockets.get(target.socketId);
    if (targetSocket) {
      targetSocket.emit(SOCKET_EVENTS.FILE_COMPLETE, {
        senderId,
        sessionId: transfer.sessionId,
        fileId,
        fileHash,
      });
    }
    this.fileTransfers.delete(fileId);
  }

  private handleFileCancel(_socket: Socket, data: any): void {
    const { targetDeviceId, fileId, senderId: dataSenderId } = data;

    // 如果 data 中没有 senderId，从 socket 获取
    const senderId = dataSenderId || this.socketToDevice.get(_socket.id);
    if (!senderId) return;

    const target = this.connectedDevices.get(targetDeviceId);
    const transfer = this.fileTransfers.get(fileId);

    if (!transfer) {
      return;
    }
    if (transfer.senderId !== senderId || transfer.targetDeviceId !== targetDeviceId) {
      _socket.emit(SOCKET_EVENTS.ERROR, {
        code: 'E304',
        message: '无效的文件传输会话',
      });
      return;
    }

    if (target) {
      const targetSocket = this.io?.sockets.sockets.get(target.socketId);
      if (targetSocket) {
        targetSocket.emit(SOCKET_EVENTS.FILE_CANCEL, {
          senderId,
          sessionId: transfer.sessionId,
          fileId,
        });
      }
    }
    this.fileTransfers.delete(fileId);
  }

  private handleHeartbeat(socket: Socket): void {
    const deviceId = this.socketToDevice.get(socket.id);
    if (deviceId) {
      const device = this.connectedDevices.get(deviceId);
      if (device) {
        device.lastHeartbeat = Date.now();
      }
    }
  }

  private handleDisconnect(socket: Socket): void {
    const deviceId = this.socketToDevice.get(socket.id);
    if (!deviceId) return;

    const device = this.connectedDevices.get(deviceId);
    if (device) {
      console.log(`[TransferRelay] Device disconnected: ${device.name} (${deviceId})`);

      this.connectedDevices.delete(deviceId);
      this.socketToDevice.delete(socket.id);
      this.rateLimits.delete(deviceId);
      for (const [sessionId, session] of this.pairSessions) {
        if (session.deviceIds.includes(deviceId)) {
          this.pairSessions.delete(sessionId);
        }
      }
      for (const [fileId, transfer] of this.fileTransfers) {
        if (transfer.senderId === deviceId || transfer.targetDeviceId === deviceId) {
          this.fileTransfers.delete(fileId);
        }
      }

      // 广播设备下线
      this.io?.emit(SOCKET_EVENTS.DEVICE_OFFLINE, { deviceId });
    }
  }

  // ============================================
  // 辅助方法
  // ============================================

  private getDeviceListForClient(excludeDeviceId: string): Array<{
    id: string;
    name: string;
    type: 'desktop' | 'android';
  }> {
    return Array.from(this.connectedDevices.values())
      .filter(d => d.id !== excludeDeviceId)
      .map(d => ({
        id: d.id,
        name: d.name,
        type: d.type,
      }));
  }

  private checkRateLimit(deviceId: string, type: 'message' | 'file'): boolean {
    const limit = this.rateLimits.get(deviceId);
    if (!limit) return false;

    const now = Date.now();

    // 每分钟重置计数
    if (now - limit.lastReset > 60000) {
      limit.messageCount = 0;
      limit.fileTransferCount = 0;
      limit.lastReset = now;
    }

    if (type === 'message') {
      if (limit.messageCount >= this.messageRateLimit) {
        return false;
      }
      limit.messageCount++;
    } else {
      if (limit.fileTransferCount >= this.fileTransferLimit) {
        return false;
      }
      limit.fileTransferCount++;
    }

    return true;
  }

  private isValidPairSession(
    sessionId: string | undefined,
    senderId: string,
    targetDeviceId: string
  ): boolean {
    if (!sessionId) {
      return false;
    }

    const session = this.pairSessions.get(sessionId);
    if (!session) {
      return false;
    }

    const devices = new Set(session.deviceIds);
    return devices.has(senderId) && devices.has(targetDeviceId);
  }

  private startHeartbeatCheck(): void {
    this.heartbeatInterval = setInterval(() => {
      const now = Date.now();

      for (const [deviceId, device] of this.connectedDevices) {
        if (now - device.lastHeartbeat > this.sessionTimeout) {
          console.log(`[TransferRelay] Device timeout: ${device.name}`);
          const socket = this.io?.sockets.sockets.get(device.socketId);
          if (socket) {
            socket.disconnect(true);
          }
        }
      }
    }, this.heartbeatInterval_ms);
  }

  private startCleanupTask(): void {
    // 每小时清理一次过期的限流记录
    this.cleanupInterval = setInterval(() => {
      const now = Date.now();
      for (const [deviceId, limit] of this.rateLimits) {
        if (!this.connectedDevices.has(deviceId) && now - limit.lastReset > 3600000) {
          this.rateLimits.delete(deviceId);
        }
      }

      for (const [sessionId, session] of this.pairSessions) {
        if (now - session.createdAt > this.sessionTimeout) {
          this.pairSessions.delete(sessionId);
        }
      }

      for (const [fileId, transfer] of this.fileTransfers) {
        if (now - transfer.createdAt > this.sessionTimeout) {
          this.fileTransfers.delete(fileId);
        }
      }
    }, 3600000);
  }
}

// 单例导出
export const transferRelayServer = new TransferRelayServer();

import React, { useState, useRef, useEffect, useCallback } from 'react';
import {
  Modal, Input, Button, List, Avatar, Dropdown, Select, Slider,
  Empty, Spin, message, Tooltip, Popconfirm, Switch, Upload
} from 'antd';
import {
  SendOutlined, PlusOutlined, DeleteOutlined, EditOutlined,
  RobotOutlined, UserOutlined, SettingOutlined, MenuOutlined,
  CopyOutlined, InfoCircleOutlined, PictureOutlined, CloseCircleOutlined,
} from '@ant-design/icons';
import { useAISettings, useAIConversations, useAIMessages } from '../hooks/useAI';
import { validateImage, fileToBase64, compressImage, getImageFromClipboard } from '../utils/imageUtils';

const { TextArea } = Input;

interface AIAssistantProps {
  open: boolean;
  onClose: () => void;
}

const AIAssistant: React.FC<AIAssistantProps> = ({ open, onClose }) => {
  const { settings } = useAISettings();
  const { conversations, createConversation, updateConversation, deleteConversation } = useAIConversations();

  const [selectedConversationId, setSelectedConversationId] = useState<string | null>(null);
  const [inputValue, setInputValue] = useState('');
  const [showSettings, setShowSettings] = useState(false);
  const [editingTitle, setEditingTitle] = useState<string | null>(null);
  const [newTitle, setNewTitle] = useState('');
  const [selectedImages, setSelectedImages] = useState<string[]>([]); // 选中的图片（base64）

  // 当前对话设置
  const [currentChannelId, setCurrentChannelId] = useState('');
  const [currentModel, setCurrentModel] = useState('');
  const [currentTemperature, setCurrentTemperature] = useState(0.7);
  const [currentMaxTokens, setCurrentMaxTokens] = useState(4096);
  const [currentSystemPrompt, setCurrentSystemPrompt] = useState('');
  const [currentWebSearchEnabled, setCurrentWebSearchEnabled] = useState(false);

  const { messages, streaming, streamingContent, sendMessage, deleteMessage } = useAIMessages(selectedConversationId);
  const messagesEndRef = useRef<HTMLDivElement>(null);
  const messagesContainerRef = useRef<HTMLDivElement>(null);
  const inputRef = useRef<any>(null);
  const prevMessagesLengthRef = useRef(0);
  const isUserScrollingRef = useRef(false); // 标记用户是否正在手动滚动

  // 获取当前选中的对话
  const currentConversation = conversations.find(c => c.id === selectedConversationId);

  // 获取所有可用的渠道和模型
  const enabledChannels = settings.channels.filter(c => c.enabled);
  const allModels = enabledChannels.flatMap(c => c.models.map(m => ({ ...m, channelName: c.name, channel: c })));

  // 获取当前选中渠道的模型列表
  const currentChannel = enabledChannels.find(c => c.id === currentChannelId);
  const currentChannelModels = currentChannel?.models || [];

  // 初始化默认渠道和模型
  useEffect(() => {
    if (enabledChannels.length > 0) {
      // 如果没有选中渠道，设置默认渠道
      if (!currentChannelId) {
        const defaultModel = settings.default_model || allModels[0]?.id;
        const modelInfo = allModels.find(m => m.id === defaultModel);
        if (modelInfo) {
          setCurrentChannelId(modelInfo.channel.id);
          setCurrentModel(defaultModel);
        } else if (enabledChannels[0]) {
          setCurrentChannelId(enabledChannels[0].id);
          if (enabledChannels[0].models.length > 0) {
            setCurrentModel(enabledChannels[0].models[0].id);
          }
        }
      }
    }
  }, [enabledChannels, allModels, currentChannelId, settings.default_model]);

  // 加载对话设置
  useEffect(() => {
    if (currentConversation) {
      const convModel = currentConversation.model || settings.default_model || '';
      const modelInfo = allModels.find(m => m.id === convModel);
      if (modelInfo) {
        setCurrentChannelId(modelInfo.channel.id);
      }
      setCurrentModel(convModel);
      setCurrentTemperature(currentConversation.temperature);
      setCurrentMaxTokens(currentConversation.maxTokens);
      setCurrentSystemPrompt(currentConversation.systemPrompt);
      setCurrentWebSearchEnabled(currentConversation.webSearchEnabled);
    }
  }, [currentConversation, settings.default_model, allModels]);

  // 切换渠道时自动选择该渠道的第一个模型
  const handleChannelChange = useCallback((channelId: string) => {
    setCurrentChannelId(channelId);
    const channel = enabledChannels.find(c => c.id === channelId);
    if (channel && channel.models.length > 0) {
      const newModel = channel.models[0].id;
      setCurrentModel(newModel);
      // 保存到对话
      if (selectedConversationId) {
        updateConversation(selectedConversationId, { model: newModel });
      }
    }
  }, [enabledChannels, selectedConversationId, updateConversation]);

  // 切换模型时自动保存到对话
  const handleModelChange = useCallback(async (newModel: string) => {
    setCurrentModel(newModel);
    if (selectedConversationId) {
      await updateConversation(selectedConversationId, { model: newModel });
    }
  }, [selectedConversationId, updateConversation]);

  // 滚动到底部 - 只在发送新消息或流式输出时自动滚动
  useEffect(() => {
    // 检测是否有新消息（用户发送或 AI 回复完成）
    const hasNewMessage = messages.length > prevMessagesLengthRef.current;
    prevMessagesLengthRef.current = messages.length;

    // 只在以下情况自动滚动：
    // 1. 有新消息且用户没有在手动滚动查看历史记录
    // 2. 正在流式输出且用户没有在手动滚动
    if (!isUserScrollingRef.current && (hasNewMessage || streaming)) {
      messagesEndRef.current?.scrollIntoView({ behavior: 'smooth' });
    }
  }, [messages, streamingContent, streaming]);

  // 监听滚动事件，判断用户是否在查看历史记录
  const handleScroll = useCallback(() => {
    const container = messagesContainerRef.current;
    if (!container) return;

    // 如果用户滚动到接近底部（距离底部 100px 以内），认为用户不再查看历史记录
    const isNearBottom = container.scrollHeight - container.scrollTop - container.clientHeight < 100;

    // 更新用户滚动状态
    isUserScrollingRef.current = !isNearBottom;
  }, []);

  // 创建新对话
  const handleNewConversation = async () => {
    const defaultModel = settings.default_model || (allModels[0]?.id || '');
    const conv = await createConversation('新对话', defaultModel, '', 0.7, 4096, false);
    if (conv) {
      setSelectedConversationId(conv.id);
    }
  };

  // 发送消息
  const handleSend = async () => {
    if (!inputValue.trim() && selectedImages.length === 0) return;

    const content = inputValue.trim();
    const images = [...selectedImages];

    if (!currentChannel) {
      message.error('请先选择渠道');
      return;
    }
    const modelInfo = currentChannelModels.find(m => m.id === currentModel);
    if (!modelInfo) {
      message.error('请先选择模型');
      return;
    }

    // 立即清空输入框和图片，提升响应感
    setInputValue('');
    setSelectedImages([]);
    isUserScrollingRef.current = false; // 发送消息时重置滚动状态，确保能看到新消息

    if (!selectedConversationId) {
      // 自动创建新对话
      const defaultModel = currentModel || settings.default_model || (allModels[0]?.id || '');
      const conv = await createConversation('新对话', defaultModel, currentSystemPrompt, currentTemperature, currentMaxTokens, currentWebSearchEnabled);
      if (conv) {
        setSelectedConversationId(conv.id);
        // 等待状态更新后发送（使用 requestAnimationFrame 确保 UI 更新）
        requestAnimationFrame(() => {
          handleSendToConversation(conv.id, content, currentChannel, images);
        });
      }
      return;
    }
    await handleSendToConversation(selectedConversationId, content, currentChannel, images);
  };

  const handleSendToConversation = async (convId: string, content: string, channel: any, images: string[] = []) => {
    if (!content && images.length === 0) return;

    try {
      await sendMessage(
        content,
        channel,
        currentModel,
        currentSystemPrompt,
        currentTemperature,
        currentMaxTokens,
        images
      );

      // 更新对话标题（如果是第一条消息）- 后台执行，不阻塞
      if (messages.length === 0) {
        const title = content.slice(0, 20) + (content.length > 20 ? '...' : '') || '图片对话';
        updateConversation(convId, { title }).catch(console.error);
      }
    } catch (err: any) {
      message.error(err.message || 'AI 请求失败');
    }
  };

  // 删除对话
  const handleDeleteConversation = async (id: string) => {
    await deleteConversation(id);
    if (selectedConversationId === id) {
      setSelectedConversationId(null);
    }
  };

  // 重命名对话
  const handleRename = async (id: string) => {
    if (newTitle.trim()) {
      await updateConversation(id, { title: newTitle.trim() });
    }
    setEditingTitle(null);
    setNewTitle('');
  };

  // 保存对话设置
  const handleSaveSettings = async () => {
    if (selectedConversationId) {
      await updateConversation(selectedConversationId, {
        model: currentModel,
        temperature: currentTemperature,
        max_tokens: currentMaxTokens,
        system_prompt: currentSystemPrompt,
        web_search_enabled: currentWebSearchEnabled,
      });
      message.success('设置已保存');
    }
    setShowSettings(false);
  };

  // 键盘事件
  const handleKeyDown = (e: React.KeyboardEvent) => {
    if (e.key === 'Enter' && !e.shiftKey) {
      e.preventDefault();
      handleSend();
    }
  };

  // 复制消息内容
  const handleCopyMessage = async (content: string) => {
    try {
      await navigator.clipboard.writeText(content);
      message.success('已复制到剪贴板');
    } catch (err) {
      message.error('复制失败');
    }
  };

  // 删除消息
  const handleDeleteMessage = async (messageId: string) => {
    const success = await deleteMessage(messageId);
    if (success) {
      message.success('消息已删除');
    } else {
      message.error('删除失败');
    }
  };

  // 处理图片上传
  const handleImageUpload = async (file: File) => {
    const validation = validateImage(file);
    if (!validation.valid) {
      message.error(validation.error);
      return false;
    }

    try {
      message.loading({ content: '处理图片中...', key: 'image-upload' });
      let base64 = await fileToBase64(file);

      // 压缩图片
      base64 = await compressImage(base64);

      setSelectedImages(prev => [...prev, base64]);
      message.success({ content: '图片已添加', key: 'image-upload' });
    } catch (error) {
      message.error({ content: '图片处理失败', key: 'image-upload' });
    }

    return false; // 阻止默认上传行为
  };

  // 处理粘贴图片
  const handlePaste = async (e: React.ClipboardEvent<HTMLTextAreaElement>) => {
    try {
      const file = await getImageFromClipboard(e);
      if (file) {
        e.preventDefault();
        console.log('检测到粘贴图片:', file.name);
        await handleImageUpload(file);
      }
    } catch (error) {
      console.error('粘贴图片失败:', error);
    }
  };

  // 删除选中的图片
  const handleRemoveImage = (index: number) => {
    setSelectedImages(prev => prev.filter((_, i) => i !== index));
  };

  if (!settings.enabled) {
    return (
      <Modal
        open={open}
        onCancel={onClose}
        footer={null}
        width={800}
        title="智能助理"
        styles={{ body: { padding: 40, textAlign: 'center' } }}
      >
        <Empty
          description="AI 功能未启用"
          image={Empty.PRESENTED_IMAGE_SIMPLE}
        >
          <p style={{ color: '#888', marginBottom: 16 }}>请在设置中启用 AI 功能并配置渠道</p>
        </Empty>
      </Modal>
    );
  }

  return (
    <Modal
      open={open}
      onCancel={onClose}
      footer={null}
      width={900}
      title={null}
      closable={true}
      styles={{ body: { padding: 0 } }}
    >
      <div style={{ display: 'flex', height: 600 }}>
        {/* 左侧对话列表 */}
        <div style={{ width: 220, borderRight: '1px solid #f0f0f0', display: 'flex', flexDirection: 'column' }}>
          <div style={{ padding: '16px 12px', borderBottom: '1px solid #f0f0f0' }}>
            <Button type="primary" icon={<PlusOutlined />} block onClick={handleNewConversation}>
              新建对话
            </Button>
          </div>
          <div style={{ flex: 1, overflow: 'auto' }}>
            {conversations.length === 0 ? (
              <Empty description="暂无对话" image={Empty.PRESENTED_IMAGE_SIMPLE} style={{ marginTop: 40 }} />
            ) : (
              <List
                dataSource={conversations}
                renderItem={(conv) => (
                  <div
                    key={conv.id}
                    onClick={() => setSelectedConversationId(conv.id)}
                    style={{
                      padding: '10px 12px',
                      cursor: 'pointer',
                      background: selectedConversationId === conv.id ? '#e6f4ff' : 'transparent',
                      borderLeft: selectedConversationId === conv.id ? '3px solid #1890ff' : '3px solid transparent',
                      display: 'flex',
                      alignItems: 'center',
                      justifyContent: 'space-between',
                    }}
                  >
                    {editingTitle === conv.id ? (
                      <Input
                        size="small"
                        value={newTitle}
                        onChange={e => setNewTitle(e.target.value)}
                        onBlur={() => handleRename(conv.id)}
                        onPressEnter={() => handleRename(conv.id)}
                        autoFocus
                        style={{ flex: 1 }}
                      />
                    ) : (
                      <>
                        <span style={{ flex: 1, overflow: 'hidden', textOverflow: 'ellipsis', whiteSpace: 'nowrap', fontSize: 13 }}>
                          {conv.title}
                        </span>
                        <Dropdown
                          menu={{
                            items: [
                              { key: 'rename', icon: <EditOutlined />, label: '重命名', onClick: () => { setEditingTitle(conv.id); setNewTitle(conv.title); } },
                              { key: 'delete', icon: <DeleteOutlined />, label: '删除', danger: true, onClick: () => handleDeleteConversation(conv.id) },
                            ],
                          }}
                          trigger={['click']}
                        >
                          <Button type="text" size="small" icon={<MenuOutlined />} onClick={e => e.stopPropagation()} />
                        </Dropdown>
                      </>
                    )}
                  </div>
                )}
              />
            )}
          </div>
        </div>

        {/* 右侧聊天区域 */}
        <div style={{ flex: 1, display: 'flex', flexDirection: 'column' }}>
          {/* 顶部工具栏 */}
          <div style={{ padding: '12px 16px', borderBottom: '1px solid #f0f0f0', display: 'flex', alignItems: 'center', gap: 8 }}>
            <RobotOutlined style={{ fontSize: 20, color: '#1890ff' }} />
            <span style={{ fontWeight: 500 }}>智能助理</span>
            <div style={{ flex: 1 }} />
            {/* 渠道选择 */}
            <Select
              value={currentChannelId}
              onChange={handleChannelChange}
              style={{ width: 140 }}
