import { createClient, WebDAVClient } from 'webdav';
import {
  StorageAdapter,
  RemoteChange,
  RemoteMeta,
  SyncCursor,
  WebDAVConfig,
  CHANGE_LOG_RETENTION,
} from './StorageAdapter';
import { ItemBase } from '@shared/types';

// WebDAV 目录结构
const PATHS = {
  META: 'workspace.json',
  ITEMS: 'items',
  RESOURCES: 'resources',
  CHANGES: 'changes',
  CURSOR: 'sync-cursor.json',
  KEY_FINGERPRINT: '.encryption-key-fingerprint',
};

// 默认超时时间（毫秒）
const DEFAULT_TIMEOUT = 30000; // 30秒

// 重试配置
const RETRY_CONFIG = {
  maxRetries: 3,
  baseDelay: 1000, // 1秒
  maxDelay: 10000, // 10秒
};

// 请求间隔（毫秒）- 避免服务器限流
const REQUEST_DELAY = 200;

export class WebDAVAdapter implements StorageAdapter {
  private client: WebDAVClient;
  private basePath: string;
  private timeout: number;
  private directoriesChecked: Set<string> = new Set(); // 缓存已检查的目录

  constructor(config: WebDAVConfig) {
    this.client = createClient(config.url, {
      username: config.username,
      password: config.password,
      maxBodyLength: 100 * 1024 * 1024, // 100MB
      maxContentLength: 100 * 1024 * 1024,
    });
    this.basePath = config.basePath || '/mucheng-notes';
    this.timeout = DEFAULT_TIMEOUT;
  }

  // 带超时的 Promise 包装器
  private async withTimeout<T>(promise: Promise<T>, timeoutMs: number = this.timeout): Promise<T> {
    return Promise.race([
      promise,
      new Promise<T>((_, reject) => 
        setTimeout(() => reject(new Error(`Operation timed out after ${timeoutMs}ms`)), timeoutMs)
      )
    ]);
  }

  // 延迟函数
  private delay(ms: number): Promise<void> {
    return new Promise(resolve => setTimeout(resolve, ms));
  }

  // 带重试的操作
  private async withRetry<T>(
    operation: () => Promise<T>,
    operationName: string
  ): Promise<T> {
    let lastError: Error | null = null;

    for (let attempt = 0; attempt < RETRY_CONFIG.maxRetries; attempt++) {
      try {
        if (attempt > 0) {
          // 指数退避延迟
          const delayMs = Math.min(
            RETRY_CONFIG.baseDelay * Math.pow(2, attempt - 1),
            RETRY_CONFIG.maxDelay
          );
          console.log(`[WebDAVAdapter] Retry ${attempt}/${RETRY_CONFIG.maxRetries} for ${operationName} after ${delayMs}ms`);
          await this.delay(delayMs);
        }
        return await operation();
      } catch (error) {
        lastError = error as Error;
        const errorMsg = lastError.message || '';

        // 检查是否是可重试的错误
        const isRetryable = 
          errorMsg.includes('ETIMEDOUT') ||
          errorMsg.includes('ECONNRESET') ||
          errorMsg.includes('ECONNREFUSED') ||
          errorMsg.includes('socket hang up') ||
          errorMsg.includes('network') ||
          errorMsg.includes('timeout');

        if (!isRetryable) {
          throw lastError;
        }

        console.warn(`[WebDAVAdapter] ${operationName} failed (attempt ${attempt + 1}): ${errorMsg}`);
      }
    }

    throw lastError;
  }

  private getPath(relativePath: string): string {
    return `${this.basePath}/${relativePath}`;
  }

  async testConnection(): Promise<boolean> {
    console.log('[WebDAVAdapter] testConnection called');
    console.log('[WebDAVAdapter] basePath:', this.basePath);

    try {
      console.log('[WebDAVAdapter] Testing connection to:', this.basePath);

      // 第一步：尝试列出根目录来验证认证
      console.log('[WebDAVAdapter] Step 1: Testing authentication by listing root...');
      try {
        const rootContents = await this.withTimeout(this.client.getDirectoryContents('/'), 10000);
        console.log('[WebDAVAdapter] Root directory accessible, found', Array.isArray(rootContents) ? rootContents.length : 0, 'items');
      } catch (authError: any) {
        console.error('[WebDAVAdapter] Authentication test failed:', authError?.message || authError);
        // 检查是否是 401/403 错误
        if (authError?.response?.status === 401 || authError?.response?.status === 403) {
          console.error('[WebDAVAdapter] Authentication failed - check username/password');
          return false;
        }
        // 其他错误可能是网络问题，继续尝试
        console.log('[WebDAVAdapter] Will continue despite root listing error...');
      }

      // 第二步：检查/创建基础目录
      console.log('[WebDAVAdapter] Step 2: Checking if base path exists...');
      let exists = false;
      try {
        exists = await this.withTimeout(this.client.exists(this.basePath), 10000);
        console.log('[WebDAVAdapter] Base path exists:', exists);
      } catch (existsError: any) {
        console.error('[WebDAVAdapter] Error checking base path:', existsError?.message || existsError);
        // 如果检查失败，可能是认证问题或网络问题
        // 尝试直接创建目录
        console.log('[WebDAVAdapter] Will try to create directory anyway...');
      }

      if (!exists) {
        // 逐级创建目录
        console.log('[WebDAVAdapter] Step 3: Creating base directory...');
        try {
          await this.ensureDirectory(this.basePath);
          console.log('[WebDAVAdapter] Base directory created');
        } catch (createError: any) {
          console.error('[WebDAVAdapter] Error creating base directory:', createError?.message || createError);
          // 目录可能已存在，继续检查子目录
        }
      }

      // 第三步：检查/创建子目录
      console.log('[WebDAVAdapter] Step 4: Checking/creating sub-directories...');
      const subDirs = [PATHS.ITEMS, PATHS.RESOURCES, PATHS.CHANGES];
      let subDirSuccess = 0;
      for (const dir of subDirs) {
        const dirPath = this.getPath(dir);
        try {
          const dirExists = await this.withTimeout(this.client.exists(dirPath), 10000);
          if (!dirExists) {
            await this.withTimeout(this.client.createDirectory(dirPath), 10000);
            console.log(`[WebDAVAdapter] Created sub-directory: ${dir}`);
          } else {
            console.log(`[WebDAVAdapter] Sub-directory exists: ${dir}`);
          }
          subDirSuccess++;
        } catch (subDirError: any) {
          console.error(`[WebDAVAdapter] Error with sub-directory ${dir}:`, subDirError?.message || subDirError);
          // 继续检查其他目录
        }
      }

      // 如果至少有一个子目录操作成功，认为连接成功
      if (subDirSuccess > 0) {
        console.log(`[WebDAVAdapter] Connection test successful (${subDirSuccess}/${subDirs.length} sub-dirs ok)`);
        // 标记已检查的目录，避免后续重复检查
        for (const dir of subDirs) {
          this.directoriesChecked.add(this.getPath(dir));
        }
        return true;
      }

      // 如果所有子目录操作都失败，尝试一个简单的写入测试
      console.log('[WebDAVAdapter] Step 5: Trying simple write test...');
      try {
        const testPath = this.getPath('.connection-test');
        await this.withTimeout(this.client.putFileContents(testPath, 'test'), 10000);
        await this.withTimeout(this.client.deleteFile(testPath), 10000);
        console.log('[WebDAVAdapter] Write test successful');
        return true;
      } catch (writeError: any) {
        console.error('[WebDAVAdapter] Write test failed:', writeError?.message || writeError);
      }

      console.log('[WebDAVAdapter] Connection test failed - no operations succeeded');
      return false;
    } catch (error: any) {
      console.error('[WebDAVAdapter] Connection test failed with exception:', error);
      // 打印更详细的错误信息
      if (error instanceof Error) {
        console.error('[WebDAVAdapter] Error name:', error.name);
        console.error('[WebDAVAdapter] Error message:', error.message);
        console.error('[WebDAVAdapter] Error stack:', error.stack);
      }
      // 检查是否是 HTTP 错误
      if (error?.response) {
        console.error('[WebDAVAdapter] HTTP Status:', error.response?.status);
        console.error('[WebDAVAdapter] HTTP StatusText:', error.response?.statusText);
        console.error('[WebDAVAdapter] HTTP Data:', error.response?.data);
      }
      // 检查是否是 axios 错误
      if (error?.code) {
        console.error('[WebDAVAdapter] Error code:', error.code);
      }
      if (error?.config) {
        console.error('[WebDAVAdapter] Request URL:', error.config?.url);
        console.error('[WebDAVAdapter] Request method:', error.config?.method);
      }
      return false;
    }
  }

  // 逐级创建目录
  private async ensureDirectory(path: string): Promise<void> {
    const parts = path.split('/').filter(p => p);
    let currentPath = '';

    for (const part of parts) {
      currentPath += '/' + part;
      try {
        const exists = await this.withTimeout(this.client.exists(currentPath));
        if (!exists) {
          await this.withTimeout(this.client.createDirectory(currentPath));
        }
      } catch (e) {
        // 目录可能已存在，忽略错误
        console.warn(`Directory creation warning for ${currentPath}:`, e);
      }
    }
  }

  async getRemoteMeta(): Promise<RemoteMeta> {
    try {
      const metaPath = this.getPath(PATHS.META);
      const exists = await this.withTimeout(this.client.exists(metaPath));
      if (exists) {
        const content = await this.withTimeout(
          this.client.getFileContents(metaPath, { format: 'text' })
        );
        return JSON.parse(content as string);
      }
    } catch (error) {
      console.error('Failed to get remote meta:', error);
    }

    // 返回默认元数据
    return {
      version: '1.0',
      capabilities: ['items', 'resources', 'changes'],
      last_sync_time: null,
    };
  }

  async putRemoteMeta(meta: RemoteMeta): Promise<boolean> {
    try {
      const metaPath = this.getPath(PATHS.META);
      await this.withTimeout(
        this.client.putFileContents(metaPath, JSON.stringify(meta, null, 2))
      );
      return true;
    } catch (error) {
      console.error('Failed to put remote meta:', error);
      return false;
    }
  }

  async listChanges(cursor: string | null, limit: number = 100): Promise<{
    changes: RemoteChange[];
    nextCursor: string | null;
    hasMore: boolean;
  }> {
    try {
      const changesDir = this.getPath(PATHS.CHANGES);

      // 检查目录是否存在（带超时）
      let dirExists = false;
      try {
        dirExists = await this.withTimeout(this.client.exists(changesDir));
      } catch (e) {
        console.warn('Failed to check changes directory existence:', e);
        return { changes: [], nextCursor: null, hasMore: false };
      }

      if (!dirExists) {
        // 目录不存在，尝试创建
        try {
          await this.withTimeout(this.client.createDirectory(changesDir));
        } catch (e) {
          console.warn('Failed to create changes directory:', e);
        }
        return { changes: [], nextCursor: null, hasMore: false };
      }

      let files: Array<{ basename: string }> = [];
      try {
        files = await this.withTimeout(
          this.client.getDirectoryContents(changesDir)
        ) as Array<{ basename: string }>;
      } catch (e) {
        console.warn('Failed to list changes directory:', e);
        return { changes: [], nextCursor: null, hasMore: false };
      }

      // 过滤并排序 JSON 文件
      const sortedFiles = files
        .filter(f => f.basename && f.basename.endsWith('.json'))
        .sort((a, b) => a.basename.localeCompare(b.basename));

      // 如果没有变更文件，直接返回
      if (sortedFiles.length === 0) {
        return { changes: [], nextCursor: null, hasMore: false };
      }

      // 找到游标位置
      let startIndex = 0;
      if (cursor) {
        const cursorIndex = sortedFiles.findIndex(f => f.basename === cursor);
        if (cursorIndex >= 0) {
          // 游标文件存在，从它的下一个开始
          startIndex = cursorIndex + 1;
        } else {
          // 游标文件不存在（例如全量拉取后设置的时间点游标），
          // 按文件名字符串比较找到第一个比游标新的文件
          // 文件名格式为 "{timestamp}.json"，字符串排序等价于时间戳排序
          const firstNewerIndex = sortedFiles.findIndex(f => f.basename > cursor);
          startIndex = firstNewerIndex >= 0 ? firstNewerIndex : sortedFiles.length;
        }
      }

      // 如果游标已经在末尾，没有更多变更
      if (startIndex >= sortedFiles.length) {
        return { changes: [], nextCursor: null, hasMore: false };
      }

      // 读取变更
      const changes: RemoteChange[] = [];
      const endIndex = Math.min(startIndex + limit, sortedFiles.length);

      for (let i = startIndex; i < endIndex; i++) {
        try {
          const content = await this.withTimeout(
            this.client.getFileContents(
              `${changesDir}/${sortedFiles[i].basename}`,
              { format: 'text' }
            )
          );
          const change = JSON.parse(content as string) as RemoteChange;
          changes.push(change);
        } catch (e) {
          console.warn(`Failed to read change file ${sortedFiles[i].basename}:`, e);
          // 跳过损坏的文件，继续处理
        }
      }

      const hasMore = endIndex < sortedFiles.length;
      const nextCursor = changes.length > 0 ? sortedFiles[endIndex - 1].basename : null;

      return { changes, nextCursor, hasMore };
    } catch (error) {
      console.error('Failed to list changes:', error);
      // 出错时返回空结果，避免卡住
      return { changes: [], nextCursor: null, hasMore: false };
    }
  }

  async getItem(id: string): Promise<ItemBase | null> {
    try {
      const itemPath = this.getPath(`${PATHS.ITEMS}/${id}.json`);
      const exists = await this.withTimeout(this.client.exists(itemPath));
      if (!exists) return null;

      const content = await this.withTimeout(
        this.client.getFileContents(itemPath, { format: 'text' })
      );
      return JSON.parse(content as string);
    } catch (error) {
      console.error(`Failed to get item ${id}:`, error);
      return null;
    }
  }

  async putItem(item: ItemBase): Promise<{ success: boolean; remoteRev: string; error?: string }> {
    try {
      const itemPath = this.getPath(`${PATHS.ITEMS}/${item.id}.json`);
      const content = JSON.stringify(item, null, 2);

      // 只在首次检查 items 目录（使用缓存避免重复检查）
      const itemsDir = this.getPath(PATHS.ITEMS);
      if (!this.directoriesChecked.has(itemsDir)) {
        try {
          const dirExists = await this.withTimeout(this.client.exists(itemsDir), 10000);
          if (!dirExists) {
            await this.withTimeout(this.client.createDirectory(itemsDir), 10000);
            console.log('[WebDAVAdapter] Created items directory');
          }
          this.directoriesChecked.add(itemsDir);
        } catch (dirError) {
          // 目录可能已存在，标记为已检查
          this.directoriesChecked.add(itemsDir);
          console.warn('[WebDAVAdapter] Directory check/create warning:', dirError);
        }
      }

      // 使用重试机制上传文件
      await this.withRetry(async () => {
        await this.withTimeout(
          this.client.putFileContents(itemPath, content, { overwrite: true }), 
          60000
        );
      }, `putItem(${item.id})`);

      // 添加请求间隔，避免服务器限流
      await this.delay(REQUEST_DELAY);

      // 记录变更（也使用重试）
      await this.withRetry(async () => {
        await this.recordChange(item);
      }, `recordChange(${item.id})`);

      // 使用时间戳作为版本号
      const remoteRev = Date.now().toString();
      return { success: true, remoteRev };
    } catch (error) {
      const errorMessage = (error as Error).message || 'Unknown error';
      console.error(`Failed to put item ${item.id}:`, error);
      return { success: false, remoteRev: '', error: errorMessage };
    }
  }

  async deleteItem(id: string): Promise<boolean> {
    try {
      const itemPath = this.getPath(`${PATHS.ITEMS}/${id}.json`);
      const exists = await this.withTimeout(this.client.exists(itemPath));
      if (exists) {
        await this.withTimeout(this.client.deleteFile(itemPath));
      }
      return true;
    } catch (error) {
      console.error(`Failed to delete item ${id}:`, error);
      return false;
    }
  }

  async getResource(id: string): Promise<Buffer | null> {
    try {
      const resourceDir = this.getPath(PATHS.RESOURCES);
      const files = await this.withTimeout(
        this.client.getDirectoryContents(resourceDir)
      ) as Array<{ basename: string }>;
      const file = files.find(f => f.basename.startsWith(id));

      if (!file) return null;

      const content = await this.withTimeout(
        this.client.getFileContents(
          `${resourceDir}/${file.basename}`,
          { format: 'binary' }
        ),
        60000 // 资源文件可能较大，使用60秒超时
      );
      return Buffer.from(content as ArrayBuffer);
    } catch (error) {
      console.error(`Failed to get resource ${id}:`, error);
      return null;
    }
  }

  async putResource(id: string, data: Buffer, mimeType: string): Promise<boolean> {
    try {
      // id 已经包含扩展名（如 uuid.png），直接使用
      const resourcePath = this.getPath(`${PATHS.RESOURCES}/${id}`);

      await this.withTimeout(
        this.client.putFileContents(resourcePath, data),
        60000 // 资源文件可能较大，使用60秒超时
      );
      return true;
    } catch (error) {
      console.error(`Failed to put resource ${id}:`, error);
      return false;
    }
  }

  async deleteResource(id: string): Promise<boolean> {
    try {
      const resourceDir = this.getPath(PATHS.RESOURCES);
      const files = await this.withTimeout(
        this.client.getDirectoryContents(resourceDir)
      ) as Array<{ basename: string }>;
      const file = files.find(f => f.basename.startsWith(id));

      if (file) {
        await this.withTimeout(
          this.client.deleteFile(`${resourceDir}/${file.basename}`)
        );
      }
      return true;
    } catch (error) {
      console.error(`Failed to delete resource ${id}:`, error);
      return false;
    }
  }

  // ❌ 游标已移至本地存储，不再从WebDAV读写
  // 保留这两个方法是为了兼容 StorageAdapter 接口
  // 但实际上不再使用，游标由 ItemsManager 管理
  async getSyncCursor(): Promise<SyncCursor | null> {
    console.warn('[WebDAVAdapter] getSyncCursor is deprecated. Use ItemsManager.getLocalSyncCursor() instead.');
    return null;
  }

  async setSyncCursor(cursor: SyncCursor): Promise<boolean> {
    console.warn('[WebDAVAdapter] setSyncCursor is deprecated. Use ItemsManager.setLocalSyncCursor() instead.');
    return true;
  }

  // 记录变更到变更日志
  private async recordChange(item: ItemBase): Promise<void> {
    const change: RemoteChange = {
      change_id: Date.now(),
      item_id: item.id,
      type: item.type,
      updated_time: item.updated_time,
      deleted_time: item.deleted_time,
      content_hash: item.content_hash,
    };

    // 只在首次检查 changes 目录（使用缓存）
    const changesDir = this.getPath(PATHS.CHANGES);
    if (!this.directoriesChecked.has(changesDir)) {
      try {
        const dirExists = await this.withTimeout(this.client.exists(changesDir), 10000);
        if (!dirExists) {
          await this.withTimeout(this.client.createDirectory(changesDir), 10000);
        }
        this.directoriesChecked.add(changesDir);
      } catch (dirError) {
        // 目录可能已存在，标记为已检查
        this.directoriesChecked.add(changesDir);
      }
    }

    const changePath = this.getPath(`${PATHS.CHANGES}/${change.change_id}.json`);
    await this.withTimeout(
      this.client.putFileContents(changePath, JSON.stringify(change, null, 2), { overwrite: true })
    );
  }

  // 清理过期的变更日志
  async cleanupChangeLogs(beforeTimestamp: number): Promise<number> {
    try {
      const changesDir = this.getPath(PATHS.CHANGES);
      const dirExists = await this.withTimeout(this.client.exists(changesDir));
      if (!dirExists) {
        return 0;
      }

      const files = await this.withTimeout(
        this.client.getDirectoryContents(changesDir)
      ) as Array<{ basename: string }>;

      let deletedCount = 0;
      for (const file of files) {
        if (!file.basename.endsWith('.json')) continue;

        // 从文件名提取时间戳（文件名格式：{timestamp}.json）
        const timestamp = parseInt(file.basename.replace('.json', ''), 10);
        if (isNaN(timestamp) || timestamp >= beforeTimestamp) continue;

        try {
          await this.withTimeout(
            this.client.deleteFile(`${changesDir}/${file.basename}`)
          );
          deletedCount++;
        } catch (e) {
          console.warn(`Failed to delete change log ${file.basename}:`, e);
        }
      }

      console.log(`Cleaned up ${deletedCount} expired change logs`);
      return deletedCount;
    } catch (error) {
      console.error('Failed to cleanup change logs:', error);
      return 0;
    }
  }

  // 检查游标是否已过期（游标对应的变更日志文件已被清理）
  async isCursorExpired(cursor: string): Promise<boolean> {
    try {
      const changesDir = this.getPath(PATHS.CHANGES);
      const dirExists = await this.withTimeout(this.client.exists(changesDir));
      if (!dirExists) return false; // 没有变更目录，不算过期

      const files = await this.withTimeout(
        this.client.getDirectoryContents(changesDir)
      ) as Array<{ basename: string }>;

      const sortedFiles = files
        .filter(f => f.basename && f.basename.endsWith('.json'))
        .sort((a, b) => a.basename.localeCompare(b.basename));

      if (sortedFiles.length === 0) return false;

      // 游标文件已不存在，且游标时间戳早于最早现存变更日志
      const cursorExists = sortedFiles.some(f => f.basename === cursor);
      if (cursorExists) return false;

      // 游标文件不存在，检查游标时间戳是否早于最早现存文件
      const cursorTimestamp = parseInt(cursor.replace('.json', ''), 10);
      const earliestTimestamp = parseInt(sortedFiles[0].basename.replace('.json', ''), 10);

      if (!isNaN(cursorTimestamp) && !isNaN(earliestTimestamp)) {
        // 游标比最早现存变更还旧，说明中间有数据被清理掉了
        return cursorTimestamp < earliestTimestamp;
      }

      return false;
    } catch (error) {
      console.error('[WebDAVAdapter] isCursorExpired check failed:', error);
      return false;
    }
  }

  // 全量拉取所有 item（新客户端首次同步使用，绕过变更日志）
  async listAllItems(): Promise<ItemBase[]> {
    const items: ItemBase[] = [];
    try {
      const itemsDir = this.getPath(PATHS.ITEMS);
      const dirExists = await this.withTimeout(this.client.exists(itemsDir));
      if (!dirExists) return items;

      const files = await this.withTimeout(
        this.client.getDirectoryContents(itemsDir)
      ) as Array<{ basename: string }>;

      const jsonFiles = files.filter(f => f.basename.endsWith('.json'));
      console.log(`[WebDAVAdapter] listAllItems: found ${jsonFiles.length} item files`);

      for (const file of jsonFiles) {
        try {
          const content = await this.withTimeout(
            this.client.getFileContents(`${itemsDir}/${file.basename}`, { format: 'text' })
          );
          const item = JSON.parse(content as string) as ItemBase;
          items.push(item);
        } catch (e) {
          console.warn(`[WebDAVAdapter] Failed to read item file ${file.basename}:`, e);
        }
      }
    } catch (error) {
      console.error('[WebDAVAdapter] listAllItems failed:', error);
    }
    return items;
  }

  // 检查远端是否已有数据
  async hasExistingData(): Promise<boolean> {
    try {
      const itemsDir = this.getPath(PATHS.ITEMS);
      const dirExists = await this.withTimeout(this.client.exists(itemsDir));
      if (!dirExists) {
        return false;
      }

      const files = await this.withTimeout(
        this.client.getDirectoryContents(itemsDir)
      ) as Array<{ basename: string }>;

      // 检查是否有任何 JSON 文件
      return files.some(f => f.basename.endsWith('.json'));
    } catch (error) {
      console.error('Failed to check existing data:', error);
      // 回退到检查元数据
      const meta = await this.getRemoteMeta();
      return meta.last_sync_time !== null;
    }
  }

  // 获取远端密钥指纹
  async getKeyFingerprint(): Promise<string | null> {
    try {
      const path = this.getPath(PATHS.KEY_FINGERPRINT);
      const exists = await this.withTimeout(this.client.exists(path));
      if (!exists) {
        return null;
      }
      const content = await this.withTimeout(this.client.getFileContents(path, { format: 'text' }));
      return content as string;
    } catch (error) {
      console.error('Failed to get key fingerprint:', error);
      return null;
    }
  }

  // 保存密钥指纹
  async saveKeyFingerprint(fingerprint: string): Promise<boolean> {
    try {
      const path = this.getPath(PATHS.KEY_FINGERPRINT);
      await this.withTimeout(this.client.putFileContents(path, fingerprint, { overwrite: true }));
      return true;
    } catch (error) {
      console.error('Failed to save key fingerprint:', error);
      return false;
    }
  }

  // 验证密钥指纹
  async verifyKeyFingerprint(localFingerprint: string): Promise<{ valid: boolean; remoteFingerprint: string | null }> {
    const remoteFingerprint = await this.getKeyFingerprint();

    if (remoteFingerprint === null) {
      // 远端没有指纹，检查是否有加密数据
      // 如果有加密数据但没有指纹，说明是旧版本数据或指纹丢失，应该报错
      const hasData = await this.hasExistingData();
      if (hasData) {
        // 远端有数据但没有指纹，可能是密钥不匹配
        console.error('[WebDAVAdapter] Remote has data but no key fingerprint - possible key mismatch');
        return { valid: false, remoteFingerprint: null };
      }
      // 远端没有数据，这是真正的首次同步，保存本地指纹
      await this.saveKeyFingerprint(localFingerprint);
      return { valid: true, remoteFingerprint: null };
    }

    // 验证指纹是否匹配
    const valid = remoteFingerprint === localFingerprint;
    return { valid, remoteFingerprint };
  }
}


export default WebDAVAdapter;

import { useState, useEffect, useCallback, useRef } from 'react';
import { ItemBase, AIConversationPayload, AIMessagePayload, AIChannel, AIModel, AISettings } from '@shared/types';
import { aiConversationsApi, aiMessagesApi, aiSettingsApi, callAIApi, ChatMessage } from '../services/aiApi';

export interface AIConversation {
  id: string;
  title: string;
  model: string;
  channelId: string;  // 渠道 ID（解决不同渠道同名模型混淆）
  systemPrompt: string;
  temperature: number;
  maxTokens: number;
  createdAt: number;
  updatedAt: number;
  webSearchEnabled: boolean; // 是否启用联网搜索
}

export interface AIMessage {
  id: string;
  conversationId: string;
  role: 'user' | 'assistant' | 'system';
  content: string;
  model: string;
  tokensUsed?: number;
  createdAt: number;
  isOptimistic?: boolean; // 乐观更新标记
  images?: string[]; // base64 编码的图片数组
}

// 解析 payload
function parsePayload<T>(item: ItemBase): T {
  return JSON.parse(item.payload) as T;
}

function itemToConversation(item: ItemBase): AIConversation {
  const payload = parsePayload<AIConversationPayload>(item);
  return {
    id: item.id,
    title: payload.title || '新对话',
    model: payload.model || '',
    channelId: payload.channel_id || '',  // 读取渠道 ID
    systemPrompt: payload.system_prompt || '',
    temperature: payload.temperature ?? 0.7,
    maxTokens: payload.max_tokens ?? 2048,
    createdAt: payload.created_at || item.created_time,
    updatedAt: item.updated_time,
    webSearchEnabled: payload.web_search_enabled ?? false,
  };
}

function itemToMessage(item: ItemBase): AIMessage {
  const payload = parsePayload<AIMessagePayload>(item);
  return {
    id: item.id,
    conversationId: payload.conversation_id || '',
    role: payload.role || 'user',
    content: payload.content || '',
    model: payload.model || '',
    tokensUsed: payload.tokens_used ?? 0,
    createdAt: payload.created_at || item.created_time,
    images: payload.images || [],
  };
}

export function useAISettings() {
  const [settings, setSettings] = useState<AISettings>(() => aiSettingsApi.get());

  // 监听 localStorage 变化，同步其他组件的更新
  useEffect(() => {
    const handleStorageChange = (e: StorageEvent) => {
      if (e.key === 'mucheng-ai-settings' && e.newValue) {
        try {
          setSettings(JSON.parse(e.newValue));
        } catch { /* ignore */ }
      }
    };

    // 自定义事件监听（同一窗口内的更新）
    const handleCustomEvent = () => {
      setSettings(aiSettingsApi.get());
    };

    // 同步完成后从数据库重新加载 AI 配置
    const handleSyncCompleted = async () => {
      const dbSettings = await aiSettingsApi.loadFromDb();
      if (dbSettings) {
        // 更新 localStorage 和状态
        aiSettingsApi.save(dbSettings);
        setSettings(dbSettings);
      }
    };

    window.addEventListener('storage', handleStorageChange);
    window.addEventListener('ai-settings-updated', handleCustomEvent);
    window.addEventListener('sync-completed', handleSyncCompleted);

    return () => {
      window.removeEventListener('storage', handleStorageChange);
      window.removeEventListener('ai-settings-updated', handleCustomEvent);
      window.removeEventListener('sync-completed', handleSyncCompleted);
    };
  }, []);

  const updateSettings = useCallback((updates: Partial<AISettings>) => {
    setSettings(prev => {
      const newSettings = { ...prev, ...updates };
      aiSettingsApi.save(newSettings);
      // 触发自定义事件通知其他组件
      window.dispatchEvent(new Event('ai-settings-updated'));
      return newSettings;
    });
  }, []);

  const addChannel = useCallback((channel: AIChannel) => {
    setSettings(prev => {
      const newSettings = {
        ...prev,
        channels: [...prev.channels, channel],
      };
      aiSettingsApi.save(newSettings);
      window.dispatchEvent(new Event('ai-settings-updated'));
      return newSettings;
    });
  }, []);

  const updateChannel = useCallback((channelId: string, updates: Partial<AIChannel>) => {
    setSettings(prev => {
      const newSettings = {
        ...prev,
        channels: prev.channels.map(c => c.id === channelId ? { ...c, ...updates } : c),
      };
      aiSettingsApi.save(newSettings);
      window.dispatchEvent(new Event('ai-settings-updated'));
      return newSettings;
    });
  }, []);

  const deleteChannel = useCallback((channelId: string) => {
    setSettings(prev => {
      const newSettings = {
        ...prev,
        channels: prev.channels.filter(c => c.id !== channelId),
      };
      aiSettingsApi.save(newSettings);
      window.dispatchEvent(new Event('ai-settings-updated'));
      return newSettings;
    });
  }, []);

  const addModelToChannel = useCallback((channelId: string, model: AIModel) => {
    setSettings(prev => {
      const newSettings = {
        ...prev,
        channels: prev.channels.map(c =>
          c.id === channelId
            ? { ...c, models: [...c.models, { ...model, channel_id: channelId }] }
            : c
        ),
      };
      aiSettingsApi.save(newSettings);
      window.dispatchEvent(new Event('ai-settings-updated'));
      return newSettings;
    });
  }, []);

  const deleteModelFromChannel = useCallback((channelId: string, modelId: string) => {
    setSettings(prev => {
      const newSettings = {
        ...prev,
        channels: prev.channels.map(c =>
          c.id === channelId
            ? { ...c, models: c.models.filter(m => m.id !== modelId) }
            : c
        ),
      };
      aiSettingsApi.save(newSettings);
      window.dispatchEvent(new Event('ai-settings-updated'));
      return newSettings;
    });
  }, []);

  const addMcpServer = useCallback((server: any) => {
    setSettings(prev => {
      const newSettings = {
        ...prev,
        mcp_servers: [...(prev.mcp_servers || []), server],
      };
      aiSettingsApi.save(newSettings);
      window.dispatchEvent(new Event('ai-settings-updated'));
      return newSettings;
    });
  }, []);

  const updateMcpServer = useCallback((serverId: string, updates: any) => {
    setSettings(prev => {
      const newSettings = {
        ...prev,
        mcp_servers: (prev.mcp_servers || []).map((s: any) =>
          s.id === serverId ? { ...s, ...updates } : s
        ),
      };
      aiSettingsApi.save(newSettings);
      window.dispatchEvent(new Event('ai-settings-updated'));
      return newSettings;
    });
  }, []);

  const deleteMcpServer = useCallback((serverId: string) => {
    setSettings(prev => {
      const newSettings = {
        ...prev,
        mcp_servers: (prev.mcp_servers || []).filter((s: any) => s.id !== serverId),
      };
      aiSettingsApi.save(newSettings);
      window.dispatchEvent(new Event('ai-settings-updated'));
      return newSettings;
    });
  }, []);

  return {
    settings,
    updateSettings,
    addChannel,
    updateChannel,
    deleteChannel,
    addModelToChannel,
    deleteModelFromChannel,
    addMcpServer,
    updateMcpServer,
    deleteMcpServer,
  };
}

export function useAIConversations() {
  const [conversations, setConversations] = useState<AIConversation[]>([]);
  const [loading, setLoading] = useState(true);

  // 对话列表缓存
  const conversationsCache = useRef<AIConversation[] | null>(null);

  const loadConversations = useCallback(async () => {
    // 先使用缓存快速显示
    if (conversationsCache.current && conversationsCache.current.length > 0) {
      setConversations(conversationsCache.current);
      setLoading(false);
      // 后台静默刷新
      aiConversationsApi.getAll().then(items => {
        if (items && Array.isArray(items)) {
          const list = items.map(itemToConversation);
          list.sort((a, b) => b.updatedAt - a.updatedAt);
          conversationsCache.current = list;
          setConversations(list);
        }
      }).catch(console.error);
      return;
    }

    try {
      setLoading(true);
      const items = await aiConversationsApi.getAll();
      if (items && Array.isArray(items)) {
        const list = items.map(itemToConversation);
        list.sort((a, b) => b.updatedAt - a.updatedAt);
        conversationsCache.current = list;
        setConversations(list);
      }
    } catch (err) {
      console.error('Failed to load AI conversations:', err);
    } finally {
      setLoading(false);
    }
  }, []);

  useEffect(() => {
    loadConversations();
  }, [loadConversations]);

  // 监听同步完成事件，刷新对话列表
  useEffect(() => {
    const handleSyncCompleted = () => {
      conversationsCache.current = null; // 清除缓存
      loadConversations();
    };
    window.addEventListener('sync-completed', handleSyncCompleted);
    return () => {
      window.removeEventListener('sync-completed', handleSyncCompleted);
    };
  }, [loadConversations]);

  const createConversation = useCallback(async (
    title: string,
    model: string,
    systemPrompt: string = '',
    temperature: number = 0.7,
    maxTokens: number = 4096,
    webSearchEnabled: boolean = false,
    channelId: string = ''  // 新增: 渠道 ID
  ) => {
    const now = Date.now();
    const tempId = `temp-conv-${now}`;

    // 乐观更新：立即在 UI 显示新对话
    const optimisticConv: AIConversation = {
      id: tempId,
      title,
      model,
      channelId,  // 包含渠道 ID
      systemPrompt,
      temperature,
      maxTokens,
      createdAt: now,
      updatedAt: now,
      webSearchEnabled,
    };

    setConversations(prev => {
      const updated = [optimisticConv, ...prev];
      conversationsCache.current = updated;
      return updated;
    });

    // 后台保存到数据库
    const payload: AIConversationPayload = {
      title,
      model,
      channel_id: channelId,  // 保存渠道 ID
      system_prompt: systemPrompt,
      temperature,
      max_tokens: maxTokens,
      created_at: now,
      web_search_enabled: webSearchEnabled,
    };

    try {
      const item = await aiConversationsApi.create(payload);
      if (item) {
        const realConv = itemToConversation(item);
        // 替换乐观对话为真实对话
        setConversations(prev => {
          const updated = prev.map(c => c.id === tempId ? realConv : c);
          conversationsCache.current = updated;
          return updated;
        });
        return realConv;
      }
    } catch (err) {
      // 失败时移除乐观对话
      setConversations(prev => {
        const updated = prev.filter(c => c.id !== tempId);
        conversationsCache.current = updated;
        return updated;
      });
      console.error('Failed to create conversation:', err);
    }
    return null;
  }, []);

  const updateConversation = useCallback(async (id: string, updates: Partial<AIConversationPayload>) => {
    // 乐观更新
    setConversations(prev => {
      const updated = prev.map(c => {
        if (c.id === id) {
          return {
            ...c,
            title: updates.title ?? c.title,
            model: updates.model ?? c.model,
            channelId: updates.channel_id ?? c.channelId,  // 添加渠道 ID 更新
            systemPrompt: updates.system_prompt ?? c.systemPrompt,
            temperature: updates.temperature ?? c.temperature,
            maxTokens: updates.max_tokens ?? c.maxTokens,
            webSearchEnabled: updates.web_search_enabled ?? c.webSearchEnabled,
            updatedAt: Date.now(),
          };
        }
        return c;
      });
      conversationsCache.current = updated;
      return updated;
    });

    // 后台保存
    try {
      const existingItems = await aiConversationsApi.getAll();
      const existingItem = existingItems.find(item => item.id === id);
      if (!existingItem) return null;

      const existingPayload = JSON.parse(existingItem.payload) as AIConversationPayload;
      const mergedPayload: AIConversationPayload = {
        ...existingPayload,
        ...updates,
      };

      const item = await aiConversationsApi.update(id, mergedPayload);
      if (item) {
        return itemToConversation(item);
      }
    } catch (err) {
      console.error('Failed to update conversation:', err);
      // 失败时重新加载
      loadConversations();
    }
    return null;
  }, [loadConversations]);

  const deleteConversation = useCallback(async (id: string) => {
    // 乐观更新：立即从 UI 移除
    setConversations(prev => {
      const updated = prev.filter(c => c.id !== id);
      conversationsCache.current = updated;
      return updated;
    });

    // 后台删除
    try {
      // 1. 先删除所有关联的消息（级联删除）
      const messages = await aiMessagesApi.getByConversation(id);
      for (const msg of messages) {
        await aiMessagesApi.delete(msg.id);
      }
      // 2. 再删除对话本身
      await aiConversationsApi.delete(id);
      return true;
    } catch (err) {
      console.error('Failed to delete conversation:', err);
      // 失败时重新加载
      loadConversations();
      return false;
    }
  }, [loadConversations]);

  return {
    conversations,
    loading,
    createConversation,
    updateConversation,
    deleteConversation,
    refresh: loadConversations,
  };
}

export function useAIMessages(conversationId: string | null) {
  const [messages, setMessages] = useState<AIMessage[]>([]);
  const [loading, setLoading] = useState(false);
  const [streaming, setStreaming] = useState(false);
  const [streamingContent, setStreamingContent] = useState('');

  // 消息缓存，避免频繁从数据库加载
  const messagesCache = useRef<Map<string, AIMessage[]>>(new Map());
  // 流式响应防抖
  const streamBufferRef = useRef('');
  const streamUpdateTimerRef = useRef<NodeJS.Timeout | null>(null);

  const loadMessages = useCallback(async () => {
    if (!conversationId) {
      setMessages([]);
      return;
    }

    // 先检查缓存
    const cached = messagesCache.current.get(conversationId);
    if (cached && cached.length > 0) {
      setMessages(cached);
      // 后台静默刷新
      aiMessagesApi.getByConversation(conversationId).then(items => {
        if (items) {
          const msgs = items.map(itemToMessage);
          msgs.sort((a, b) => a.createdAt - b.createdAt);
          messagesCache.current.set(conversationId, msgs);
          setMessages(msgs);
        }
      }).catch(console.error);
      return;
    }

    try {
      setLoading(true);
      const items = await aiMessagesApi.getByConversation(conversationId);
      if (items) {
        const msgs = items.map(itemToMessage);
        msgs.sort((a, b) => a.createdAt - b.createdAt);
        messagesCache.current.set(conversationId, msgs);
        setMessages(msgs);
      }
    } catch (err) {
      console.error('Failed to load AI messages:', err);
    } finally {
      setLoading(false);
    }
  }, [conversationId]);

  // 当 conversationId 改变时，只重置 UI 显示状态，不中断后台请求
  useEffect(() => {
    // 只重置当前对话的显示状态
    setStreaming(false);
    setStreamingContent('');
    streamBufferRef.current = '';
    if (streamUpdateTimerRef.current) {
      clearTimeout(streamUpdateTimerRef.current);
      streamUpdateTimerRef.current = null;
    }
    // 注意：不取消正在进行的请求，让它们在后台完成
  }, [conversationId]);

  useEffect(() => {
    loadMessages();
  }, [loadMessages]);

  // 防抖更新流式内容（每 50ms 更新一次 UI，减少重渲染）
  const updateStreamingContent = useCallback((chunk: string) => {
    streamBufferRef.current += chunk;

    if (!streamUpdateTimerRef.current) {
      streamUpdateTimerRef.current = setTimeout(() => {
        setStreamingContent(streamBufferRef.current);
        streamUpdateTimerRef.current = null;
      }, 50);
    }
  }, []);

  const sendMessage = useCallback(async (
    content: string,
    channel: AIChannel,
    model: string,
    systemPrompt: string,
    temperature: number,
    maxTokens: number,
    images: string[] = []
  ) => {
    if (!conversationId) return null;

    // 调试日志：记录传入的渠道和模型参数
    console.log('[sendMessage] Called with:', {
      conversationId,
      channelId: channel.id,
      channelName: channel.name,
      channelType: channel.type,
      model,
      apiUrl: channel.api_url,
    });

    const now = Date.now();
    const tempUserId = `temp-user-${now}`;
    const targetConversationId = conversationId; // 保存当前对话 ID，避免闭包问题

    // 1. 乐观更新：立即在 UI 显示用户消息
    const optimisticUserMsg: AIMessage = {
      id: tempUserId,
      conversationId: targetConversationId,
      role: 'user',
      content,
      model,
      createdAt: now,
      isOptimistic: true,
      images: images.length > 0 ? images : undefined,
    };

    setMessages(prev => {
      const updated = [...prev, optimisticUserMsg];
      messagesCache.current.set(targetConversationId, updated);
      return updated;
    });

    // 2. 并行：保存用户消息到数据库（不阻塞 API 请求）
    const userPayload: AIMessagePayload = {
      conversation_id: targetConversationId,
      role: 'user',
      content,
      model,
      created_at: now,
      images: images.length > 0 ? images : undefined,
    };
    const saveUserMsgPromise = aiMessagesApi.create(userPayload);

    // 3. 构建消息历史（使用当前内存中的消息，不重新从数据库加载）
    const chatMessages: ChatMessage[] = [];
    if (systemPrompt) {
      chatMessages.push({ role: 'system', content: systemPrompt });
    }
    // 使用当前消息列表（不包括刚添加的乐观消息，因为它已经在 content 中）
    // 过滤掉空内容的消息（某些 API 如月之暗面不允许空的 assistant 消息）
    messages.forEach(m => {
      // 跳过空内容的消息
      if (!m.content || m.content.trim() === '') {
        return;
      }
      // 如果消息包含图片，构建多模态内容
      if (m.images && m.images.length > 0) {
        const contentParts: Array<{ type: 'text' | 'image_url'; text?: string; image_url?: { url: string } }> = [];
        if (m.content) {
          contentParts.push({ type: 'text', text: m.content });
        }
        m.images.forEach(img => {
          contentParts.push({ type: 'image_url', image_url: { url: img } });
        });
        chatMessages.push({ role: m.role, content: contentParts });
      } else {
        chatMessages.push({ role: m.role, content: m.content });
      }
    });
    // 添加当前用户消息
    if (images.length > 0) {
      // 多模态消息
      const contentParts: Array<{ type: 'text' | 'image_url'; text?: string; image_url?: { url: string } }> = [];
      if (content) {
        contentParts.push({ type: 'text', text: content });
      }
      images.forEach(img => {
        contentParts.push({ type: 'image_url', image_url: { url: img } });
      });
      chatMessages.push({ role: 'user', content: contentParts });
    } else {
      chatMessages.push({ role: 'user', content });
    }

    // 4. 开始流式响应
    setStreaming(true);
    setStreamingContent('');
    streamBufferRef.current = '';

    // 创建一个更新函数，只在当前对话时更新 UI
    const updateStreamingContentForConversation = (chunk: string) => {
      streamBufferRef.current += chunk;

      // 只在仍然是当前对话时更新 UI
      if (conversationId === targetConversationId) {
        if (!streamUpdateTimerRef.current) {
          streamUpdateTimerRef.current = setTimeout(() => {
            setStreamingContent(streamBufferRef.current);
            streamUpdateTimerRef.current = null;
          }, 50);
        }
      }
    };

    try {
      const response = await callAIApi(channel, {
        model,
        messages: chatMessages,
        temperature,
        max_tokens: maxTokens,
        stream: true,
      }, updateStreamingContentForConversation);

      // 确保最后一次更新（只在仍然是当前对话时）
      if (conversationId === targetConversationId) {
        if (streamUpdateTimerRef.current) {
          clearTimeout(streamUpdateTimerRef.current);
          streamUpdateTimerRef.current = null;
        }
        setStreamingContent(streamBufferRef.current);
      }

      // 5. 等待用户消息保存完成
      const savedUserMsg = await saveUserMsgPromise;

      // 6. 保存助手消息（只有非空内容才保存）
      let savedAssistantMsg = null;
      if (response && response.trim()) {
        const assistantPayload: AIMessagePayload = {
          conversation_id: targetConversationId,
          role: 'assistant',
          content: response,
          model,
          created_at: Date.now(),
        };
        savedAssistantMsg = await aiMessagesApi.create(assistantPayload);
      }

      // 7. 更新消息列表（替换乐观消息为真实消息）
      // 无论当前是否在这个对话，都要更新缓存
      const newMessages = await aiMessagesApi.getByConversation(targetConversationId);
      if (newMessages) {
        const msgs = newMessages.map(itemToMessage);
        msgs.sort((a, b) => a.createdAt - b.createdAt);
        messagesCache.current.set(targetConversationId, msgs);

        // 只在仍然是当前对话时更新 UI
        if (conversationId === targetConversationId) {
          setMessages(msgs);
        }
      }

      return response;
    } catch (err) {
      // 发生错误时，移除乐观消息
      setMessages(prev => {
        const filtered = prev.filter(m => m.id !== tempUserId);
        messagesCache.current.set(targetConversationId, filtered);
        return filtered;
      });
      console.error('AI API error:', err);
      throw err;
    } finally {
      // 只在仍然是当前对话时重置 streaming 状态
      if (conversationId === targetConversationId) {
        setStreaming(false);
        setStreamingContent('');
        streamBufferRef.current = '';
      }
    }
  }, [conversationId, messages]);

  const deleteMessage = useCallback(async (messageId: string) => {
    if (!conversationId) return false;

    try {
      // 乐观更新：立即从 UI 移除
      setMessages(prev => {
        const updated = prev.filter(m => m.id !== messageId);
        messagesCache.current.set(conversationId, updated);
        return updated;
      });

      // 后台删除
      await aiMessagesApi.delete(messageId);
      return true;
    } catch (err) {
      console.error('Failed to delete message:', err);
      // 失败时重新加载
      loadMessages();
      return false;
    }
  }, [conversationId, loadMessages]);

  // 清除缓存（用于同步后刷新）
  const clearCache = useCallback(() => {
    messagesCache.current.clear();
  }, []);

  return {
    messages,
    loading,
    streaming,
    streamingContent,
    sendMessage,
    deleteMessage,
    refresh: loadMessages,
    clearCache,
  };
}

