/**
 * 书签列表页面
 */
@OptIn(ExperimentalMaterial3Api::class)
@Composable
fun BookmarksScreen(
    navController: NavController,
    bottomPadding: PaddingValues = PaddingValues(),
    viewModel: BookmarksViewModel = hiltViewModel()
) {
    val bookmarks by viewModel.bookmarks.collectAsState()
    val folders by viewModel.folders.collectAsState()
    val selectedFolderId by viewModel.selectedFolderId.collectAsState()
    val uiState by viewModel.uiState.collectAsState()

    val drawerState = rememberDrawerState(initialValue = DrawerValue.Closed)
    val scope = rememberCoroutineScope()

    // 对话框状态
    var showAddBookmarkDialog by remember { mutableStateOf(false) }
    var showEditBookmarkDialog by remember { mutableStateOf(false) }
    var showDeleteBookmarkDialog by remember { mutableStateOf(false) }
    var showRenameFolderDialog by remember { mutableStateOf(false) }
    var showDeleteFolderDialog by remember { mutableStateOf(false) }
    var showCreateFolderDialog by remember { mutableStateOf(false) }

    var selectedBookmark by remember { mutableStateOf<BookmarkItem?>(null) }
    var selectedFolderForEdit by remember { mutableStateOf<String?>(null) }
    var createFolderParentId by remember { mutableStateOf<String?>(null) }

    // 过滤书签：先按文件夹过滤，再按搜索查询过滤
    val filteredBookmarks = bookmarks.filter { bookmark ->
        // 文件夹过滤
        if (selectedFolderId != null && bookmark.folderId != selectedFolderId) {
            return@filter false
        }
        // 搜索过滤
        if (uiState.searchQuery.isNotBlank()) {
            val query = uiState.searchQuery.lowercase()
            bookmark.name.lowercase().contains(query) ||
            bookmark.url.lowercase().contains(query) ||
            (bookmark.description.lowercase().contains(query))
        } else {
            true
        }
    }

    // 转换文件夹数据
    val folderItems = folders.map { folder ->
        FolderItem(
            id = folder.id,
            name = folder.name,
            parentId = folder.parentId,
            itemCount = bookmarks.count { it.folderId == folder.id }
        )
    }

    ModalNavigationDrawer(
        drawerState = drawerState,
        drawerContent = {
            ModalDrawerSheet(
                modifier = Modifier.width(280.dp)
            ) {
                Column(
                    modifier = Modifier
                        .fillMaxHeight()
                        .padding(16.dp)
                ) {
                    Text(
                        text = "书签文件夹",
                        style = MaterialTheme.typography.titleMedium,
                        modifier = Modifier.padding(bottom = 16.dp)
                    )

                    FolderTree(
                        folders = folderItems,
                        selectedFolderId = selectedFolderId,
                        onFolderSelect = { folderId ->
                            viewModel.selectFolder(folderId)
                            scope.launch { drawerState.close() }
                        },
                        onCreateFolder = { parentId ->
                            createFolderParentId = parentId
                            showCreateFolderDialog = true
                        },
                        onEditFolder = { folderId ->
                            selectedFolderForEdit = folderId
                            showRenameFolderDialog = true
                        },
                        onDeleteFolder = { folderId ->
                            selectedFolderForEdit = folderId
                            showDeleteFolderDialog = true
                        },
                        modifier = Modifier.weight(1f),
                        allOptionLabel = "全部书签"
                    )

                    Divider(modifier = Modifier.padding(vertical = 8.dp))

                    // 设置入口
                    Row(
                        modifier = Modifier
                            .fillMaxWidth()
                            .clickable { 
                                scope.launch { drawerState.close() }
                                navController.navigate(Screen.Settings.route)
                            }
                            .padding(12.dp),
                        verticalAlignment = Alignment.CenterVertically
                    ) {
                        Icon(
                            Icons.Default.Settings,
