import {
  StorageAdapter,
  RemoteChange,
  RemoteMeta,
  SyncCursor,
  ServerConfig,
} from './StorageAdapter';
import { ItemBase } from '@shared/types';

// 认证响应类型
interface AuthResponse {
  success: boolean;
  token?: string;
  refreshToken?: string;
  expiresIn?: number;
  user?: {
    id: number;
    username: string;
    role: string;
  };
  userId?: string;
  isAdmin?: boolean;
  initialized?: boolean;
  registrationEnabled?: boolean;
  error?: string;
  message?: string;
}

export class ServerAdapter implements StorageAdapter {
  private baseUrl: string;
  private apiKey?: string;
  private token?: string;
  private refreshToken?: string;
  private tokenExpires?: number;
  private onTokenRefresh?: (token: string, refreshToken: string, expiresIn: number) => void;
  private refreshPromise: Promise<boolean> | null = null;
  // 保存登录凭据用于自动重新登录
  private savedCredentials?: { username: string; password: string; syncKey: string };
  private onReloginRequired?: () => void;

  constructor(config: ServerConfig) {
    this.baseUrl = config.url.replace(/\/+$/, '');
    this.apiKey = config.apiKey;
    this.token = config.token;
  }

  // 设置 token 刷新回调
  setTokenRefreshCallback(callback: (token: string, refreshToken: string, expiresIn: number) => void) {
    this.onTokenRefresh = callback;
  }

  // 设置重新登录回调（当 refresh token 也过期时触发）
  setReloginRequiredCallback(callback: () => void) {
    this.onReloginRequired = callback;
  }

  // 保存登录凭据（用于自动重新登录）
  saveCredentials(username: string, password: string, syncKey: string) {
    this.savedCredentials = { username, password, syncKey };
  }

  // 清除保存的凭据
  clearCredentials() {
    this.savedCredentials = undefined;
  }

  // 设置认证信息
  setAuth(token: string, refreshToken?: string, tokenExpires?: number) {
    this.token = token;
    this.refreshToken = refreshToken;
    this.tokenExpires = tokenExpires;
  }

  // 登录
  async login(username: string, password: string, syncKey: string): Promise<AuthResponse> {
    try {
      const response = await this.doFetch(`${this.baseUrl}/api/auth/login`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ username, password, syncKey }),
      });

      const data = await response.json();

      // 服务器返回 accessToken，兼容两种字段名
      const token = data.accessToken || data.token;

      if (response.ok && token) {
        this.token = token;
        this.refreshToken = data.refreshToken;
        this.tokenExpires = Date.now() + (data.expiresIn || 3600) * 1000;
        return {
          success: true,
          token: token,
          refreshToken: data.refreshToken,
          expiresIn: data.expiresIn,
          user: data.user,
        };
      }

      return {
        success: false,
        error: data.error?.message || data.message || '登录失败',
      };
    } catch (error) {
      console.error('Login failed:', error);
      return {
        success: false,
        error: (error as Error).message || '网络错误',
      };
    }
  }

  // 注册
  async register(username: string, password: string, syncKey: string): Promise<AuthResponse> {
    try {
      const response = await this.doFetch(`${this.baseUrl}/api/auth/register`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ username, password, syncKey }),
      });

      const data = await response.json();

      const token = data.accessToken || data.token;

      if (response.ok) {
        if (token) {
          this.token = token;
          this.refreshToken = data.refreshToken;
          this.tokenExpires = Date.now() + (data.expiresIn || 3600) * 1000;
        }

        return {
          success: true,
          token,
          refreshToken: data.refreshToken,
          expiresIn: data.expiresIn,
          user: data.user,
          userId: data.userId,
          isAdmin: data.isAdmin,
          message: data.message,
        };
      }

      return {
        success: false,
        error: data.error?.message || data.message || '注册失败',
      };
    } catch (error) {
      console.error('Register failed:', error);
      return {
        success: false,
        error: (error as Error).message || '网络错误',
      };
    }
  }

  // 刷新 token
  async refreshAccessToken(): Promise<boolean> {
    if (!this.refreshToken) {
      // 没有 refresh token，尝试自动重新登录
      return this.tryAutoRelogin();
    }

    try {
      const response = await this.doFetch(`${this.baseUrl}/api/auth/refresh`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ refreshToken: this.refreshToken }),
      });

      if (response.ok) {
        const data = await response.json();
        // 服务器返回 accessToken，兼容两种字段名
        const token = data.accessToken || data.token;
        this.token = token;
        this.refreshToken = data.refreshToken;
        this.tokenExpires = Date.now() + (data.expiresIn || 3600) * 1000;

        // 通知外部保存新 token
        if (this.onTokenRefresh) {
          this.onTokenRefresh(token, data.refreshToken, data.expiresIn);
        }

        return true;
      }

      // refresh token 无效或过期，尝试自动重新登录
      console.log('[ServerAdapter] Refresh token invalid, trying auto relogin...');
      return this.tryAutoRelogin();
    } catch (error) {
      console.error('Token refresh failed:', error);
      // 尝试自动重新登录
      return this.tryAutoRelogin();
    }
  }

  // 尝试自动重新登录
  private async tryAutoRelogin(): Promise<boolean> {
    if (!this.savedCredentials) {
      // 没有保存的凭据，通知需要重新登录
      if (this.onReloginRequired) {
        this.onReloginRequired();
      }
      return false;
    }

    try {
      console.log('[ServerAdapter] Attempting auto relogin...');
      const { username, password, syncKey } = this.savedCredentials;
      const result = await this.login(username, password, syncKey);

      if (result.success) {
        console.log('[ServerAdapter] Auto relogin successful');
        return true;
      }

      console.error('[ServerAdapter] Auto relogin failed:', result.error);
      // 登录失败，通知需要重新登录
      if (this.onReloginRequired) {
        this.onReloginRequired();
      }
      return false;
    } catch (error) {
      console.error('[ServerAdapter] Auto relogin error:', error);
      if (this.onReloginRequired) {
        this.onReloginRequired();
      }
      return false;
    }
  }

  // 登出
  async logout(): Promise<void> {
    if (this.token) {
      try {
        await this.doFetch(`${this.baseUrl}/api/auth/logout`, {
          method: 'POST',
          headers: this.getHeaders(),
        });
      } catch (error) {
        console.error('Logout request failed:', error);
      }
    }
    this.token = undefined;
    this.refreshToken = undefined;
    this.tokenExpires = undefined;
  }

  // 检查是否已登录
  isAuthenticated(): boolean {
    return !!this.token;
  }

  // 检查 token 是否即将过期（5分钟内）
  isTokenExpiringSoon(): boolean {
    if (!this.tokenExpires) return false;
    return this.tokenExpires - Date.now() < 5 * 60 * 1000;
  }

  // 获取服务器注册状态
  async getRegistrationStatus(): Promise<{ registrationOpen: boolean; hasUsers: boolean }> {
    try {
      const response = await this.doFetch(`${this.baseUrl}/api/health/status`, {
        method: 'GET',
        headers: { 'Content-Type': 'application/json' },
      });
      if (response.ok) {
        const data = await response.json();
        return {
          registrationOpen: data.registrationEnabled ?? data.registrationOpen ?? true,
          hasUsers: data.initialized ?? data.hasUsers ?? false,
        };
      }
      return { registrationOpen: true, hasUsers: false };
    } catch (error) {
      console.error('Failed to get registration status:', error);
      return { registrationOpen: true, hasUsers: false };
    }
  }

  private getHeaders(): Record<string, string> {
    const headers: Record<string, string> = {
      'Content-Type': 'application/json',
    };
    if (this.apiKey) {
      headers['X-API-Key'] = this.apiKey;
    }
    if (this.token) {
      headers['Authorization'] = `Bearer ${this.token}`;
    }
    return headers;
  }

  // 通用的 fetch 方法，支持 Electron 主进程
  private async doFetch(url: string, options: RequestInit): Promise<Response> {
    // 检查是否在 Electron 主进程中
    if (typeof process !== 'undefined' && process.versions && process.versions.electron) {
      try {
        const { net } = require('electron');
        if (net && net.fetch) {
          return await net.fetch(url, options);
        }
      } catch (e) {
        // 回退到全局 fetch
      }
    }
    return await fetch(url, options);
  }

  // 安全的 token 刷新方法，防止并发刷新
  private async safeRefreshToken(): Promise<boolean> {
    // 如果已经有刷新请求在进行中，等待它完成
    if (this.refreshPromise) {
      return this.refreshPromise;
    }

    // 创建新的刷新请求
    this.refreshPromise = this.refreshAccessToken().finally(() => {
      this.refreshPromise = null;
    });

    return this.refreshPromise;
  }

  private async request<T>(
    method: string,
    path: string,
    body?: unknown,
    retry = true
  ): Promise<T> {
    // 检查 token 是否即将过期，提前刷新（使用锁防止并发刷新）
    if (this.isTokenExpiringSoon() && this.refreshToken) {
      await this.safeRefreshToken();
    }

    const url = `${this.baseUrl}${path}`;
    const response = await this.doFetch(url, {
      method,
      headers: this.getHeaders(),
      body: body ? JSON.stringify(body) : undefined,
    });

    // 处理 401 错误，尝试刷新 token
    if (response.status === 401 && retry && this.refreshToken) {
      const refreshed = await this.safeRefreshToken();
      if (refreshed) {
        return this.request<T>(method, path, body, false);
      }
      // 刷新失败，抛出更明确的错误
      throw new Error('Token refresh failed: 登录已过期，请重新登录');
    }

    if (!response.ok) {
      const errorData = await response.json().catch(() => ({}));
      const errorMessage = errorData.error?.message || errorData.message || `${response.status} ${response.statusText}`;
      throw new Error(`Server request failed: ${errorMessage}`);
    }

    return response.json();
  }

  async testConnection(): Promise<boolean> {
    try {
      console.log('[ServerAdapter] testConnection called, baseUrl:', this.baseUrl);

      const url = `${this.baseUrl}/api/health`;
      console.log('[ServerAdapter] Fetching:', url);

      // 设置超时
      const controller = new AbortController();
      const timeoutId = setTimeout(() => controller.abort(), 10000); // 10秒超时

      try {
        // 尝试使用 Electron 的 net 模块（主进程）或全局 fetch（渲染进程）
        let response: Response;

        // 检查是否在 Electron 主进程中
        if (typeof process !== 'undefined' && process.versions && process.versions.electron) {
          // 在 Electron 环境中，使用 Node.js 的 http/https 模块
          const { net } = require('electron');
          if (net && net.fetch) {
            console.log('[ServerAdapter] Using Electron net.fetch');
            response = await net.fetch(url, {
              method: 'GET',
              headers: { 'Content-Type': 'application/json' },
            });
          } else {
            // 回退到全局 fetch
            console.log('[ServerAdapter] Using global fetch');
            response = await fetch(url, {
              method: 'GET',
              headers: { 'Content-Type': 'application/json' },
              signal: controller.signal,
            });
          }
        } else {
          // 非 Electron 环境，使用全局 fetch
          console.log('[ServerAdapter] Using global fetch (non-Electron)');
          response = await fetch(url, {
            method: 'GET',
            headers: { 'Content-Type': 'application/json' },
            signal: controller.signal,
          });
        }

        clearTimeout(timeoutId);
        console.log('[ServerAdapter] Response status:', response.status, response.statusText);

        if (!response.ok) {
          console.error('[ServerAdapter] Server health check failed:', response.status, response.statusText);
          return false;
        }

        const data = await response.json();
        console.log('[ServerAdapter] Health check response:', data);
        return data.status === 'ok';
      } catch (fetchError) {
        clearTimeout(timeoutId);
        throw fetchError;
      }
    } catch (error) {
      console.error('[ServerAdapter] Server connection test failed:', error);
      if (error instanceof Error) {
        console.error('[ServerAdapter] Error name:', error.name);
        console.error('[ServerAdapter] Error message:', error.message);
        if (error.name === 'AbortError') {
          console.error('[ServerAdapter] Request timed out');
        }
      }
      return false;
    }
  }

  async getRemoteMeta(): Promise<RemoteMeta> {
    try {
      return await this.request<RemoteMeta>('GET', '/api/meta');
    } catch (error) {
      console.error('Failed to get remote meta:', error);
      return {
        version: '1.0',
        capabilities: ['items', 'resources', 'changes'],
        last_sync_time: null,
      };
    }
  }

  async putRemoteMeta(meta: RemoteMeta): Promise<boolean> {
    try {
      await this.request<void>('PUT', '/api/meta', meta);
      return true;
    } catch (error) {
      console.error('Failed to put remote meta:', error);
      return false;
    }
  }

  async listChanges(cursor: string | null, limit: number = 100): Promise<{
    changes: RemoteChange[];
    nextCursor: string | null;
    hasMore: boolean;
  }> {
    try {
      const params = new URLSearchParams();
      if (cursor) params.set('cursor', cursor);
      params.set('limit', limit.toString());

      return await this.request<{
        changes: RemoteChange[];
        nextCursor: string | null;
        hasMore: boolean;
      }>('GET', `/api/changes?${params}`);
    } catch (error) {
      console.error('Failed to list changes:', error);
      return { changes: [], nextCursor: null, hasMore: false };
    }
  }

  async getItem(id: string): Promise<ItemBase | null> {
    try {
      return await this.request<ItemBase>('GET', `/api/items/${id}`);
    } catch (error) {
      console.error(`Failed to get item ${id}:`, error);
      return null;
    }
  }

  async putItem(item: ItemBase): Promise<{ success: boolean; remoteRev: string; error?: string }> {
    try {
      const result = await this.request<{ remoteRev: string }>(
        'PUT',
        `/api/items/${item.id}`,
        item
      );
      return { success: true, remoteRev: result.remoteRev };
    } catch (error) {
      const errorMessage = (error as Error).message || 'Unknown error';
      console.error(`Failed to put item ${item.id}:`, error);
      return { success: false, remoteRev: '', error: errorMessage };
    }
  }

  async deleteItem(id: string): Promise<boolean> {
    try {
      await this.request<void>('DELETE', `/api/items/${id}`);
      return true;
    } catch (error) {
      console.error(`Failed to delete item ${id}:`, error);
      return false;
    }
  }

  async getResource(id: string): Promise<Buffer | null> {
    try {
      const response = await this.doFetch(`${this.baseUrl}/api/resources/${id}`, {
        method: 'GET',
        headers: this.getHeaders(),
      });
      if (!response.ok) return null;
      const arrayBuffer = await response.arrayBuffer();
      return Buffer.from(arrayBuffer);
    } catch (error) {
      console.error(`Failed to get resource ${id}:`, error);
      return null;
    }
  }

  async putResource(id: string, data: Buffer, mimeType: string): Promise<boolean> {
    try {
      const response = await this.doFetch(`${this.baseUrl}/api/resources/${id}`, {
        method: 'PUT',
        headers: {
          ...this.getHeaders(),
          'Content-Type': mimeType,
        },
        body: data as unknown as BodyInit,
      });
      return response.ok;
    } catch (error) {
      console.error(`Failed to put resource ${id}:`, error);
      return false;
    }
  }

  async deleteResource(id: string): Promise<boolean> {
    try {
      await this.request<void>('DELETE', `/api/resources/${id}`);
      return true;
    } catch (error) {
      console.error(`Failed to delete resource ${id}:`, error);
      return false;
    }
  }

  async getSyncCursor(): Promise<SyncCursor | null> {
    try {
      return await this.request<SyncCursor>('GET', '/api/sync/cursor');
    } catch (error) {
      return null;
    }
  }

  async setSyncCursor(cursor: SyncCursor): Promise<boolean> {
    try {
      await this.request<void>('PUT', '/api/sync/cursor', cursor);
      return true;
    } catch (error) {
      console.error('Failed to set sync cursor:', error);
      return false;
    }
  }

  // 清理过期的变更日志
  async cleanupChangeLogs(beforeTimestamp: number): Promise<number> {
    try {
      const result = await this.request<{ deleted: number }>(
        'DELETE',
        `/api/changes?before=${beforeTimestamp}`
      );
      return result.deleted;
    } catch (error) {
      console.error('Failed to cleanup change logs:', error);
      return 0;
    }
  }

  // 检查游标是否已过期（游标对应的变更记录已被清理）
  async isCursorExpired(cursor: string): Promise<boolean> {
    try {
      const result = await this.request<{ expired: boolean }>(
        'GET',
        `/api/changes/cursor-check?cursor=${encodeURIComponent(cursor)}`
      );
      return result.expired;
    } catch (error) {
      console.error('[ServerAdapter] isCursorExpired check failed:', error);
      return false;
    }
  }

  // 全量拉取所有 item（新客户端首次同步使用，绕过变更日志）
  async listAllItems(): Promise<ItemBase[]> {
    try {
      const result = await this.request<{ items: ItemBase[]; latestChangeId?: number }>('GET', '/api/items/all');
      console.log(`[ServerAdapter] listAllItems: got ${result.items?.length ?? 0} items, latestChangeId: ${result.latestChangeId}`);
      // 保存 latestChangeId 供 SyncEngine 使用（注意：0 也是有效值，表示 changes 表为空）
      this._lastFullPullChangeId = result.latestChangeId ?? null;
      return result.items || [];
    } catch (error) {
      console.error('[ServerAdapter] listAllItems failed:', error);
      return [];
    }
  }

  // 全量拉取后的最新 change_id
  _lastFullPullChangeId: number | null = null;

  getLastFullPullChangeId(): number | null {
    return this._lastFullPullChangeId;
  }

  // 检查远端是否已有数据
  async hasExistingData(): Promise<boolean> {
    try {
      const result = await this.request<{ hasData: boolean; itemCount: number }>(
        'GET',
        '/api/items/count'
      );
      return result.hasData || result.itemCount > 0;
    } catch (error) {
      // 如果接口不存在，回退到检查元数据
      const meta = await this.getRemoteMeta();
      return meta.last_sync_time !== null;
    }
  }

  // 批量操作（服务器特有优化）
  async batchPutItems(items: ItemBase[]): Promise<{ success: boolean; results: Array<{ id: string; remoteRev: string }> }> {
    try {
      return await this.request<{ success: boolean; results: Array<{ id: string; remoteRev: string }> }>(
        'POST',
        '/api/items/batch',
        { items }
      );
    } catch (error) {
      console.error('Failed to batch put items:', error);
      return { success: false, results: [] };
    }
  }

  // 获取服务器状态
  async getServerStatus(): Promise<{
    healthy: boolean;
    version: string;
    storage: { used: number; total: number };
  }> {
    try {
      return await this.request<{
        healthy: boolean;
        version: string;
        storage: { used: number; total: number };
      }>('GET', '/api/status');
    } catch (error) {
      return { healthy: false, version: 'unknown', storage: { used: 0, total: 0 } };
    }
  }

  // 获取远端密钥指纹
  async getKeyFingerprint(): Promise<string | null> {
    try {
      const result = await this.request<{ fingerprint: string | null }>('GET', '/api/sync/key-fingerprint');
      return result.fingerprint;
    } catch (error) {
      console.error('Failed to get key fingerprint:', error);
      return null;
    }
  }

  // 保存密钥指纹
  async saveKeyFingerprint(fingerprint: string): Promise<boolean> {
    try {
      await this.request<void>('PUT', '/api/sync/key-fingerprint', { fingerprint });
      return true;
    } catch (error) {
      console.error('Failed to save key fingerprint:', error);
      return false;
    }
  }

  // 验证密钥指纹
  async verifyKeyFingerprint(localFingerprint: string): Promise<{ valid: boolean; remoteFingerprint: string | null }> {
    const remoteFingerprint = await this.getKeyFingerprint();

    if (remoteFingerprint === null) {
      // 远端没有指纹，这是首次同步，保存本地指纹
      await this.saveKeyFingerprint(localFingerprint);
      return { valid: true, remoteFingerprint: null };
    }

    // 验证指纹是否匹配
    const valid = remoteFingerprint === localFingerprint;
    return { valid, remoteFingerprint };
  }
}

export default ServerAdapter;

package com.mucheng.notes.data.remote

import com.mucheng.notes.data.local.entity.ItemEntity
import com.mucheng.notes.domain.model.SyncConfig
import kotlinx.coroutines.Deferred
import kotlinx.coroutines.Dispatchers
import kotlinx.coroutines.async
import kotlinx.coroutines.coroutineScope
import kotlinx.coroutines.sync.Mutex
import kotlinx.coroutines.sync.withLock
import kotlinx.coroutines.withContext
import kotlinx.serialization.Serializable
import kotlinx.serialization.encodeToString
import kotlinx.serialization.json.Json
import okhttp3.MediaType.Companion.toMediaType
import okhttp3.OkHttpClient
import okhttp3.Request
import okhttp3.RequestBody.Companion.toRequestBody
import java.util.concurrent.TimeUnit
import javax.inject.Inject
import javax.inject.Singleton

/**
 * 自建服务器认证响应
 */
@Serializable
data class AuthResponse(
    val success: Boolean = false,
    val accessToken: String? = null,
    val refreshToken: String? = null,
    val expiresIn: Int? = null,
    val user: AuthUser? = null,
    val error: AuthError? = null,
    val message: String? = null
)

@Serializable
data class AuthUser(
    val id: String,
    val username: String,
    val role: String
)

@Serializable
data class AuthError(
    val code: String? = null,
    val message: String? = null
)

/**
 * 服务器注册状态
 */
@Serializable
data class RegistrationStatus(
    val status: String = "ok",
    val initialized: Boolean = false,
    val registrationEnabled: Boolean = true,
    val timestamp: Long = 0
)

/**
 * 自建服务器同步适配器实现
 * 与桌面端 ServerAdapter.ts 保持一致
 */
@Singleton
class ServerAdapterImpl @Inject constructor() : WebDAVAdapter {

    private val json = Json {
        ignoreUnknownKeys = true
        encodeDefaults = true
        isLenient = true
        coerceInputValues = true
    }

    private val client: OkHttpClient by lazy {
        OkHttpClient.Builder()
            .connectTimeout(30, TimeUnit.SECONDS)
            .readTimeout(30, TimeUnit.SECONDS)
            .writeTimeout(30, TimeUnit.SECONDS)
            .build()
    }

    private var config: SyncConfig? = null
    private var accessToken: String? = null
    private var refreshToken: String? = null
    private var tokenExpires: Long? = null

    // Token 刷新回调
    var onTokenRefresh: ((String, String, Int) -> Unit)? = null

    // 重新登录回调（当 refresh token 也过期时触发）
    var onReloginRequired: (() -> Unit)? = null

    // 保存的登录凭据（用于自动重新登录）
    private var savedCredentials: Triple<String, String, String>? = null

    // 并发刷新保护
    private var refreshJob: Deferred<Boolean>? = null
    private val refreshMutex = Mutex()

    /**
     * 初始化服务器连接
     * 会自动检查并刷新即将过期的 token
     */
    suspend fun initialize(syncConfig: SyncConfig) {
        config = syncConfig
        accessToken = syncConfig.serverToken
        refreshToken = syncConfig.serverRefreshToken
        tokenExpires = syncConfig.serverTokenExpires

        // 主动检查 token 是否过期或即将过期
        if (accessToken != null && refreshToken != null) {
            val now = System.currentTimeMillis()
            val expires = tokenExpires ?: 0L

            if (expires <= now) {
                // Token 已过期，立即刷新
                android.util.Log.i("ServerAdapter", "Token expired, refreshing on init...")
                safeRefreshToken()
            } else if (expires - now < 5 * 60 * 1000) {
                // Token 即将过期（5分钟内），提前刷新
                android.util.Log.i("ServerAdapter", "Token expiring soon, refreshing on init...")
                safeRefreshToken()
            }
        }
    }

    /**
     * 保存登录凭据（用于自动重新登录）
     */
    fun saveCredentials(username: String, password: String, syncKey: String) {
        savedCredentials = Triple(username, password, syncKey)
    }

    /**
     * 清除保存的凭据
     */
    fun clearCredentials() {
        savedCredentials = null
    }

    private fun getConfig(): SyncConfig {
        return config ?: throw IllegalStateException("Server adapter not initialized")
    }

    private fun getBaseUrl(): String {
        val cfg = getConfig()
        return cfg.url.trimEnd('/')
    }

    /**
     * 登录
     */
    suspend fun login(username: String, password: String, syncKey: String): AuthResponse = withContext(Dispatchers.IO) {
        try {
            val url = "${getBaseUrl()}/api/auth/login"
            val body = json.encodeToString(mapOf(
                "username" to username,
                "password" to password,
                "syncKey" to syncKey
            ))

            val request = Request.Builder()
                .url(url)
                .post(body.toRequestBody("application/json".toMediaType()))
                .build()

            val response = client.newCall(request).execute()
            val responseBody = response.body?.string() ?: "{}"

            android.util.Log.d("ServerAdapter", "Login response: ${response.code} - $responseBody")

            if (response.isSuccessful) {
                val authResponse = json.decodeFromString<AuthResponse>(responseBody)
                if (authResponse.accessToken != null) {
                    accessToken = authResponse.accessToken
                    refreshToken = authResponse.refreshToken
                    tokenExpires = System.currentTimeMillis() + (authResponse.expiresIn ?: 3600) * 1000L
                }
                authResponse
            } else {
                try {
                    json.decodeFromString<AuthResponse>(responseBody)
                } catch (e: Exception) {
                    AuthResponse(success = false, message = "登录失败: HTTP ${response.code}")
                }
            }
        } catch (e: Exception) {
            android.util.Log.e("ServerAdapter", "Login failed: ${e.message}")
            AuthResponse(success = false, message = e.message ?: "网络错误")
        }
    }

    private fun persistTokenState(
        accessToken: String,
        refreshToken: String?,
        expiresIn: Int
    ) {
        onTokenRefresh?.invoke(accessToken, refreshToken ?: "", expiresIn)
    }

    /**
     * 注册
     */
    suspend fun register(username: String, password: String, syncKey: String): AuthResponse = withContext(Dispatchers.IO) {
        try {
            val url = "${getBaseUrl()}/api/auth/register"
            val body = json.encodeToString(mapOf(
                "username" to username,
                "password" to password,
                "syncKey" to syncKey
            ))

            val request = Request.Builder()
                .url(url)
                .post(body.toRequestBody("application/json".toMediaType()))
                .build()

            val response = client.newCall(request).execute()
            val responseBody = response.body?.string() ?: "{}"

            android.util.Log.d("ServerAdapter", "Register response: ${response.code} - $responseBody")

            if (response.isSuccessful) {
                json.decodeFromString<AuthResponse>(responseBody)
            } else {
                try {
                    json.decodeFromString<AuthResponse>(responseBody)
                } catch (e: Exception) {
                    AuthResponse(success = false, message = "注册失败: HTTP ${response.code}")
                }
            }
        } catch (e: Exception) {
            android.util.Log.e("ServerAdapter", "Register failed: ${e.message}")
            AuthResponse(success = false, message = e.message ?: "网络错误")
        }
    }

    /**
     * 刷新 Token（内部实现）
     */
    private suspend fun doRefreshAccessToken(): Boolean = withContext(Dispatchers.IO) {
        val currentRefreshToken = refreshToken
        if (currentRefreshToken == null) {
            // 没有 refresh token，尝试自动重新登录
            return@withContext tryAutoRelogin()
        }

        try {
            val url = "${getBaseUrl()}/api/auth/refresh"
            val body = json.encodeToString(mapOf("refreshToken" to currentRefreshToken))

            val request = Request.Builder()
                .url(url)
                .post(body.toRequestBody("application/json".toMediaType()))
                .build()

            val response = client.newCall(request).execute()

            if (response.isSuccessful) {
                val responseBody = response.body?.string() ?: "{}"
                val authResponse = json.decodeFromString<AuthResponse>(responseBody)

                if (authResponse.accessToken != null) {
                    accessToken = authResponse.accessToken
                    refreshToken = authResponse.refreshToken
                    val expiresIn = authResponse.expiresIn ?: 3600
                    tokenExpires = System.currentTimeMillis() + expiresIn * 1000L

                    // 通知外部保存新 token
                    persistTokenState(authResponse.accessToken, authResponse.refreshToken, expiresIn)
                    return@withContext true
                }
            }

            if (response.code == 401 || response.code == 403) {
                // refresh token 无效或过期，尝试自动重新登录
                android.util.Log.w("ServerAdapter", "Refresh token rejected, trying auto relogin...")
                return@withContext tryAutoRelogin()
            }

            android.util.Log.w(
                "ServerAdapter",
                "Token refresh request failed: HTTP ${response.code} ${response.message}"
            )
            return@withContext false
        } catch (e: Exception) {
            android.util.Log.e("ServerAdapter", "Token refresh failed: ${e.message}")
            return@withContext false
        }
    }

    /**
     * 安全的 token 刷新方法，防止并发刷新
     */
    suspend fun safeRefreshToken(): Boolean {
        return refreshMutex.withLock {
            // 如果已经有刷新请求在进行中，等待它完成
            refreshJob?.let { job ->
                if (job.isActive) {
                    return@withLock job.await()
                }
            }

            // 创建新的刷新请求
            val newJob = kotlinx.coroutines.coroutineScope {
                async(Dispatchers.IO) {
                    doRefreshAccessToken()
                }
            }
            refreshJob = newJob

            try {
                newJob.await()
            } finally {
                if (refreshJob == newJob) {
                    refreshJob = null
                }
            }
        }
    }

    /**
     * 刷新 Token（公开方法，使用并发保护）
     */
    suspend fun refreshAccessToken(): Boolean = safeRefreshToken()

    /**
     * 尝试自动重新登录
     */
    private suspend fun tryAutoRelogin(): Boolean {
        val credentials = savedCredentials
        if (credentials == null) {
            // 没有保存的凭据，通知需要重新登录
            android.util.Log.w("ServerAdapter", "No saved credentials, relogin required")
            onReloginRequired?.invoke()
            return false
        }

        return try {
            android.util.Log.i("ServerAdapter", "Attempting auto relogin...")
            val (username, password, syncKey) = credentials
            val result = login(username, password, syncKey)

            if (result.success && result.accessToken != null) {
                persistTokenState(result.accessToken, result.refreshToken, result.expiresIn ?: 3600)
                android.util.Log.i("ServerAdapter", "Auto relogin successful")
                true
            } else {
                android.util.Log.e("ServerAdapter", "Auto relogin failed: ${result.message}")
                if (result.error?.code != null) {
                    // 仅在服务端明确判定认证失效时清理本地登录态
                    onReloginRequired?.invoke()
                }
                false
            }
        } catch (e: Exception) {
            android.util.Log.e("ServerAdapter", "Auto relogin error: ${e.message}")
            false
        }
    }

    /**
     * 登出
     */
    suspend fun logout(): Unit = withContext(Dispatchers.IO) {
        if (accessToken != null) {
            try {
                val url = "${getBaseUrl()}/api/auth/logout"
                val request = Request.Builder()
                    .url(url)
                    .post("{}".toRequestBody("application/json".toMediaType()))
                    .addHeader("Authorization", "Bearer $accessToken")
                    .build()

                client.newCall(request).execute()
            } catch (e: Exception) {
                android.util.Log.e("ServerAdapter", "Logout request failed: ${e.message}")
            }
        }
        accessToken = null
        refreshToken = null
        tokenExpires = null
    }

    /**
     * 检查是否已登录
     */
    fun isAuthenticated(): Boolean = accessToken != null

    /**
     * 检查 token 是否即将过期（5分钟内）
     */
    fun isTokenExpiringSoon(): Boolean {
        val expires = tokenExpires ?: return false
        return expires - System.currentTimeMillis() < 5 * 60 * 1000
    }

    /**
     * 获取服务器注册状态
     */
    suspend fun getRegistrationStatus(): RegistrationStatus = withContext(Dispatchers.IO) {
        try {
            val url = "${getBaseUrl()}/api/health/status"
            val request = Request.Builder()
                .url(url)
                .get()
                .build()

            val response = client.newCall(request).execute()
            if (response.isSuccessful) {
                val responseBody = response.body?.string() ?: "{}"
                json.decodeFromString<RegistrationStatus>(responseBody)
            } else {
                RegistrationStatus()
            }
        } catch (e: Exception) {
            android.util.Log.e("ServerAdapter", "Failed to get registration status: ${e.message}")
            RegistrationStatus()
        }
    }

    /**
     * 执行带认证的请求
     */
    private suspend fun <T> request(
        method: String,
        path: String,
        body: String? = null,
        retry: Boolean = true,
        parser: (String) -> T
    ): T? = withContext(Dispatchers.IO) {
        // 检查 token 是否即将过期，提前刷新（使用并发保护）
        if (isTokenExpiringSoon() && refreshToken != null) {
            safeRefreshToken()
        }

        val url = "${getBaseUrl()}$path"
        val requestBuilder = Request.Builder().url(url)

        // 添加认证头
        val token = accessToken
        if (token != null) {
            requestBuilder.addHeader("Authorization", "Bearer $token")
        } else {
            android.util.Log.w("ServerAdapter", "No access token available for request: $method $path")
        }

        // 设置请求方法和 body
        when (method) {
            "GET" -> requestBuilder.get()
            "POST" -> requestBuilder.post((body ?: "{}").toRequestBody("application/json".toMediaType()))
            "PUT" -> requestBuilder.put((body ?: "{}").toRequestBody("application/json".toMediaType()))
            "DELETE" -> requestBuilder.delete()
        }

        try {
            android.util.Log.d("ServerAdapter", "Request: $method $url, hasToken=${token != null}")
            val response = client.newCall(requestBuilder.build()).execute()

            // 处理 401 错误，尝试刷新 token（使用并发保护）
            if (response.code == 401 && retry && refreshToken != null) {
                android.util.Log.w("ServerAdapter", "Got 401, attempting token refresh")
                val refreshed = safeRefreshToken()
                if (refreshed) {
                    return@withContext request(method, path, body, false, parser)
                }
                android.util.Log.e("ServerAdapter", "Token refresh failed, relogin may be required")
            }

            if (response.isSuccessful) {
                val responseBody = response.body?.string() ?: "{}"
                parser(responseBody)
            } else {
                val errorBody = response.body?.string() ?: ""
                android.util.Log.e("ServerAdapter", "Request failed: $method $path -> ${response.code} ${response.message}, body: $errorBody")
                null
            }
        } catch (e: Exception) {
            android.util.Log.e("ServerAdapter", "Request error: $method $path -> ${e.javaClass.simpleName}: ${e.message}")
            null
        }
    }

    // ========== WebDAVAdapter 接口实现 ==========

    override suspend fun testConnection(): Boolean = withContext(Dispatchers.IO) {
        try {
            val url = "${getBaseUrl()}/api/health"
            val request = Request.Builder()
                .url(url)
                .get()
                .build()

            val response = client.newCall(request).execute()
            response.isSuccessful
        } catch (e: Exception) {
            android.util.Log.e("ServerAdapter", "Connection test failed: ${e.message}")
            false
        }
    }

    override suspend fun getItem(id: String): ItemEntity? {
        return request("GET", "/api/items/$id") { responseBody ->
            json.decodeFromString<ItemEntity>(responseBody)
        }
    }

    override suspend fun putItem(item: ItemEntity): Result<String> = withContext(Dispatchers.IO) {
        try {
            val body = json.encodeToString(item)
            val result = request("PUT", "/api/items/${item.id}", body) { responseBody ->
                @Serializable
                data class PutResult(val remoteRev: String)
                json.decodeFromString<PutResult>(responseBody)
            }

            if (result != null) {
                Result.success(result.remoteRev)
            } else {
                Result.failure(Exception("上传项目失败: ${item.id} - 服务器无响应"))
            }
        } catch (e: Exception) {
            android.util.Log.e("ServerAdapter", "Failed to put item ${item.id}: ${e.message}")
            Result.failure(Exception("上传项目失败: ${item.id}: ${e.message}"))
        }
    }

    override suspend fun deleteItem(id: String): Boolean {
        return request("DELETE", "/api/items/$id") { true } ?: false
    }

    override suspend fun listChanges(cursor: String?, limit: Int): ChangeListResult {
        val params = buildString {
            append("?limit=$limit")
            if (cursor != null) append("&cursor=$cursor")
        }

        val result = request("GET", "/api/changes$params") { responseBody ->
            json.decodeFromString<ChangeListResult>(responseBody)
        }

        if (result == null) {
            throw Exception("获取变更列表失败 - 请检查网络连接和认证状态")
        }

        return result
    }

    override suspend fun getSyncCursor(): SyncCursor? {
        return request("GET", "/api/sync/cursor") { responseBody ->
            json.decodeFromString<SyncCursor>(responseBody)
        }
    }

    override suspend fun setSyncCursor(cursor: SyncCursor): Boolean {
        val body = json.encodeToString(cursor)
        return request("PUT", "/api/sync/cursor", body) { true } ?: false
    }

    override suspend fun uploadResource(resourceId: String, data: ByteArray): Result<String> = withContext(Dispatchers.IO) {
        try {
            val url = "${getBaseUrl()}/api/resources/$resourceId"
            val requestBuilder = Request.Builder()
                .url(url)
                .put(data.toRequestBody("application/octet-stream".toMediaType()))

            accessToken?.let {
                requestBuilder.addHeader("Authorization", "Bearer $it")
            }

            val response = client.newCall(requestBuilder.build()).execute()
            if (response.isSuccessful) {
                Result.success(System.currentTimeMillis().toString())
            } else {
                Result.failure(Exception("上传失败: ${response.code}"))
            }
        } catch (e: Exception) {
            Result.failure(e)
        }
    }

    override suspend fun downloadResource(resourceId: String): Result<ByteArray> = withContext(Dispatchers.IO) {
        try {
            val url = "${getBaseUrl()}/api/resources/$resourceId"
            val requestBuilder = Request.Builder().url(url).get()

            accessToken?.let {
                requestBuilder.addHeader("Authorization", "Bearer $it")
            }

            val response = client.newCall(requestBuilder.build()).execute()
            if (response.isSuccessful) {
                val data = response.body?.bytes() ?: ByteArray(0)
                Result.success(data)
            } else {
                Result.failure(Exception("下载失败: ${response.code}"))
            }
        } catch (e: Exception) {
            Result.failure(e)
        }
    }

    override suspend fun deleteResource(resourceId: String): Boolean {
        return request("DELETE", "/api/resources/$resourceId") { true } ?: false
    }

    override suspend fun listResources(): List<String> {
        return request("GET", "/api/resources") { responseBody ->
            @Serializable
            data class ResourceList(val resources: List<String>)
            json.decodeFromString<ResourceList>(responseBody).resources
        } ?: emptyList()
    }

    override suspend fun getKeyIdentifier(): String? {
        return request("GET", "/api/meta") { responseBody ->
            @Serializable
            data class Meta(val key_identifier: String? = null)
            json.decodeFromString<Meta>(responseBody).key_identifier
        }
    }

    override suspend fun setKeyIdentifier(keyId: String): Boolean {
        val body = json.encodeToString(mapOf("key_identifier" to keyId))
        return request("PUT", "/api/meta", body) { true } ?: false
    }

    override suspend fun hasData(): Boolean {
        return request("GET", "/api/items/count") { responseBody ->
            @Serializable
            data class CountResult(val hasData: Boolean = false, val itemCount: Int = 0)
            val result = json.decodeFromString<CountResult>(responseBody)
            result.hasData || result.itemCount > 0
        } ?: false
    }

    // 全量拉取后的最新 change_id
    private var _lastFullPullChangeId: Long? = null

    override suspend fun listAllItems(): List<ItemEntity> {
        return request("GET", "/api/items/all") { responseBody ->
            @Serializable
            data class AllItemsResult(val items: List<ItemEntity>, val latestChangeId: Long = 0)
            val result = json.decodeFromString<AllItemsResult>(responseBody)
            android.util.Log.d("ServerAdapter", "listAllItems: got ${result.items.size} items, latestChangeId=${result.latestChangeId}")
            // 保存 latestChangeId，包括 0（表示 changes 表为空，游标从 0 开始）
            _lastFullPullChangeId = result.latestChangeId  // 不再过滤 0，让 SyncEngine 处理
            result.items
        } ?: emptyList()
    }

    override suspend fun isCursorExpired(cursor: String): Boolean {
        return request("GET", "/api/changes/cursor-check?cursor=${java.net.URLEncoder.encode(cursor, "UTF-8")}") { responseBody ->
            @Serializable
            data class CursorCheckResult(val expired: Boolean = false)
            json.decodeFromString<CursorCheckResult>(responseBody).expired
        } ?: false
    }

    override fun getLastFullPullChangeId(): Long? {
        return _lastFullPullChangeId
    }

    override suspend fun getKeyFingerprint(): String? {
        return request("GET", "/api/sync/key-fingerprint") { responseBody ->
            @Serializable
            data class FingerprintResult(val fingerprint: String? = null)
            json.decodeFromString<FingerprintResult>(responseBody).fingerprint
        }
    }

    override suspend fun saveKeyFingerprint(fingerprint: String): Boolean {
        val body = json.encodeToString(mapOf("fingerprint" to fingerprint))
        return request("PUT", "/api/sync/key-fingerprint", body) { true } ?: false
    }

    override suspend fun verifyKeyFingerprint(localFingerprint: String): KeyFingerprintResult {
        val remoteFingerprint = getKeyFingerprint()

        if (remoteFingerprint == null) {
            // 远端没有指纹，这是首次同步，保存本地指纹
            saveKeyFingerprint(localFingerprint)
            return KeyFingerprintResult(valid = true, remoteFingerprint = null)
        }

        // 验证指纹是否匹配
        val valid = remoteFingerprint == localFingerprint
        return KeyFingerprintResult(valid = valid, remoteFingerprint = remoteFingerprint)
    }
}

