                folderId = folderId,
                favorite = favorite,
                notes = notes,
                username = username,
                password = password,
                totpSecrets = totpSecrets,
                uris = uris,
                cardHolderName = cardHolderName,
                cardNumber = cardNumber,
                cardBrand = cardBrand,
                cardExpMonth = cardExpMonth,
                cardExpYear = cardExpYear,
                cardCvv = cardCvv,
                identityTitle = identityTitle,
                identityFirstName = identityFirstName,
                identityLastName = identityLastName,
                identityEmail = identityEmail,
                identityPhone = identityPhone,
                identityAddress = identityAddress,
                customFields = customFields
            )
            itemRepository.update(id, json.encodeToString(payload))
        }
    }

    /**
     * 切换收藏状态
     */
    fun toggleFavorite(id: String) {
        viewModelScope.launch {
            val existing = itemRepository.getById(id) ?: return@launch
            val oldPayload = json.decodeFromString<VaultEntryPayload>(existing.payload)
            val newPayload = oldPayload.copy(favorite = !oldPayload.favorite)
            itemRepository.update(id, json.encodeToString(newPayload))
        }
    }

    /**
     * 生成随机密码
     */
    fun generatePassword(
        length: Int = 16,
        includeUppercase: Boolean = true,
        includeLowercase: Boolean = true,
        includeNumbers: Boolean = true,
        includeSymbols: Boolean = true
    ): String {
        val chars = StringBuilder()
        if (includeUppercase) chars.append("ABCDEFGHIJKLMNOPQRSTUVWXYZ")
        if (includeLowercase) chars.append("abcdefghijklmnopqrstuvwxyz")
        if (includeNumbers) chars.append("0123456789")
        if (includeSymbols) chars.append("!@#\$%^&*()_+-=[]{}|;:,.<>?")

        if (chars.isEmpty()) chars.append("abcdefghijklmnopqrstuvwxyz")

        val random = java.security.SecureRandom()
        return (1..length)
            .map { chars[random.nextInt(chars.length)] }
            .joinToString("")
    }

    private fun ItemEntity.toVaultEntryItem(): VaultEntryItem {
        return try {
            val payload = json.decodeFromString<VaultEntryPayload>(this.payload)
            VaultEntryItem(
                id = this.id,
                name = payload.name,
                entryType = payload.entryType,
                folderId = payload.folderId,
                favorite = payload.favorite,
                notes = payload.notes,
                username = payload.username,
                password = payload.password,
                totpSecrets = payload.totpSecrets,
                uris = payload.uris,
                cardHolderName = payload.cardHolderName,
                cardNumber = payload.cardNumber,
                cardBrand = payload.cardBrand,
                cardExpMonth = payload.cardExpMonth,
                cardExpYear = payload.cardExpYear,
                cardCvv = payload.cardCvv,
                identityTitle = payload.identityTitle,
                identityFirstName = payload.identityFirstName,
                identityLastName = payload.identityLastName,
                identityEmail = payload.identityEmail,
                identityPhone = payload.identityPhone,
                identityAddress = payload.identityAddress,
                customFields = payload.customFields,
                updatedTime = this.updatedTime
            )
        } catch (e: Exception) {
            android.util.Log.e("VaultViewModel", "Failed to parse vault entry payload: ${e.message}")
            e.printStackTrace()
            // 返回一个默认的条目，避免崩溃
            VaultEntryItem(
                id = this.id,
                name = "解析错误",
                entryType = VaultEntryType.LOGIN,
                folderId = null,
                favorite = false,
                notes = "",
                username = "",
                password = "",
                totpSecrets = emptyList(),
                uris = emptyList(),
                cardHolderName = "",
                cardNumber = "",
                cardBrand = "",
                cardExpMonth = "",
                cardExpYear = "",
                cardCvv = "",
                identityTitle = "",
                identityFirstName = "",
                identityLastName = "",
                identityEmail = "",
                identityPhone = "",
                identityAddress = "",
                customFields = emptyList(),
                updatedTime = this.updatedTime
            )
        }
    }

    private fun ItemEntity.toVaultFolderItem(): VaultFolderItem {
        return try {
            val payload = json.decodeFromString<VaultFolderPayload>(this.payload)
            VaultFolderItem(
                id = this.id,
                name = payload.name,
                parentId = payload.parentId
            )
        } catch (e: Exception) {
            android.util.Log.e("VaultViewModel", "Failed to parse vault folder payload: ${e.message}")
            // 返回一个默认的文件夹，避免崩溃
            VaultFolderItem(
                id = this.id,
                name = "解析错误",
                parentId = null
            )
        }
    }
}

/**
 * 密码库条目展示模型
 */
data class VaultEntryItem(
    val id: String,
    val name: String,
    val entryType: VaultEntryType,
    val folderId: String?,
    val favorite: Boolean,
    val notes: String,
    val username: String,
    val password: String,
    val totpSecrets: List<com.mucheng.notes.domain.model.payload.VaultTotp>,
    val uris: List<com.mucheng.notes.domain.model.payload.VaultUri>,
    // 银行卡字段
    val cardHolderName: String,
    val cardNumber: String,
    val cardBrand: String,
    val cardExpMonth: String,
    val cardExpYear: String,
    val cardCvv: String,
    // 身份字段
    val identityTitle: String,
    val identityFirstName: String,
    val identityLastName: String,
    val identityEmail: String,
    val identityPhone: String,
    val identityAddress: String,
    // 自定义字段
    val customFields: List<com.mucheng.notes.domain.model.payload.VaultCustomField>,
    val updatedTime: Long
)

/**
 * 密码库文件夹展示模型
 */
data class VaultFolderItem(
    val id: String,
    val name: String,
    val parentId: String?
)

import React, { useState } from 'react';
import { Menu, Button, Dropdown, Input, Modal, message, Tooltip } from 'antd';
import {
  FileTextOutlined,
  FolderOutlined,
  FolderOpenOutlined,
  FolderAddOutlined,
  TagOutlined,
  StarOutlined,
  DeleteOutlined,
  PlusOutlined,
  SettingOutlined,
  EditOutlined,
  RobotOutlined,
  AppstoreOutlined,
  CheckSquareOutlined,
  SafetyOutlined,
  LinkOutlined,
  SyncOutlined,
  NodeIndexOutlined,
  SwapOutlined,
  RightOutlined,
  DownOutlined,
  FileExcelOutlined,
} from '@ant-design/icons';
import type { MenuProps } from 'antd';
import { Folder } from '../hooks/useFolders';
import { Tag } from '../hooks/useTags';

interface SidebarProps {
  selectedFolderId: string | null;
  selectedView: 'all' | 'starred' | 'trash' | 'folder' | 'tag';
  folders: Folder[];
  tags: Tag[];
  aiEnabled?: boolean;
  todoEnabled?: boolean;
  vaultEnabled?: boolean;
  bookmarkEnabled?: boolean;
  toolboxEnabled?: boolean;
  diagramEnabled?: boolean;
  transferEnabled?: boolean;
  excelEnabled?: boolean;
  currentTool?: string | null;
  onSelectFolder: (folderId: string | null) => void;
  onSelectView: (view: 'all' | 'starred' | 'trash') => void;
  onSelectTag: (tagId: string) => void;
  onSelectTool?: (tool: string | null) => void;
  onCreateNote?: () => void;
  onQuickCreateNote?: () => void;
  onCreateFolder?: (name: string, parentId?: string | null) => Promise<void>;
  onDeleteFolder?: (folderId: string) => Promise<void>;
  onRenameFolder?: (folderId: string, newName: string) => Promise<void>;
  onDeleteTag?: (tagId: string) => Promise<void>;
  onOpenSettings?: () => void;
  onSync?: () => void;
  syncStatus?: 'idle' | 'syncing' | 'error' | 'offline';
}

const Sidebar: React.FC<SidebarProps> = ({
  selectedFolderId,
  selectedView,
  folders,
  tags,
  aiEnabled,
  todoEnabled,
  vaultEnabled,
  bookmarkEnabled,
  toolboxEnabled,
  diagramEnabled,
  transferEnabled,
  excelEnabled,
  currentTool,
  onSelectFolder,
  onSelectView,
  onSelectTag,
  onSelectTool,
  onCreateNote,
  onQuickCreateNote,
  onCreateFolder,
  onDeleteFolder,
  onRenameFolder,
  onDeleteTag,
  onOpenSettings,
  onSync,
  syncStatus,
}) => {
  const [newFolderModalOpen, setNewFolderModalOpen] = useState(false);
  const [newFolderName, setNewFolderName] = useState('');
  const [newFolderParentId, setNewFolderParentId] = useState<string | null>(null);
  const [renameFolderModalOpen, setRenameFolderModalOpen] = useState(false);
  const [renameFolderId, setRenameFolderId] = useState<string | null>(null);
  const [renameFolderName, setRenameFolderName] = useState('');
  const [expandedFolders, setExpandedFolders] = useState<Set<string>>(new Set());

  React.useEffect(() => {
    if (!selectedFolderId || selectedFolderId === 'uncategorized') {
      return;
    }

    setExpandedFolders(prev => {
      const next = new Set(prev);
      let changed = false;
      let currentId: string | null = selectedFolderId;

      while (currentId) {
        if (!next.has(currentId)) {
          next.add(currentId);
          changed = true;
        }
        const currentFolder = folders.find(folder => folder.id === currentId);
        currentId = currentFolder?.parentId || null;
      }

      return changed ? next : prev;
    });
  }, [folders, selectedFolderId]);

  const expandFolder = (folderId: string) => {
    setExpandedFolders(prev => {
      if (prev.has(folderId)) {
        return prev;
      }
      const next = new Set(prev);
      next.add(folderId);
      return next;
    });
  };

  const handleFolderSelect = (folderId: string) => {
    const hasChildren = folders.some(f => f.parentId === folderId);

    if (hasChildren && selectedFolderId === folderId) {
      setExpandedFolders(prev => {
        const next = new Set(prev);
        if (next.has(folderId)) {
          next.delete(folderId);
        } else {
          next.add(folderId);
        }
        return next;
      });
    } else if (hasChildren) {
      expandFolder(folderId);
    }

    onSelectFolder(folderId);
  };

  // 切换文件夹展开/折叠状态
  const toggleFolderExpand = (folderId: string, e: React.MouseEvent) => {
    e.stopPropagation();
    setExpandedFolders(prev => {
      const next = new Set(prev);
      if (next.has(folderId)) {
        next.delete(folderId);
      } else {
        next.add(folderId);
      }
      return next;
    });
  };
  // 目录右键菜单
  const getFolderContextMenu = (folder: Folder): MenuProps['items'] => [
    {
      key: 'newSubfolder',
      icon: <FolderAddOutlined />,
      label: '新建子目录',
      onClick: (e) => {
        e.domEvent.stopPropagation();
        setNewFolderParentId(folder.id);
        setNewFolderModalOpen(true);
      },
    },
    { 
      key: 'rename', 
      icon: <EditOutlined />, 
      label: '重命名',
      onClick: (e) => {
        e.domEvent.stopPropagation();
        setRenameFolderId(folder.id);
        setRenameFolderName(folder.name);
        setRenameFolderModalOpen(true);
      },
    },
    { type: 'divider' },
    { 
      key: 'delete', 
      icon: <DeleteOutlined />, 
      label: '删除',
      danger: true,
      onClick: (e) => {
        e.domEvent.stopPropagation();
        Modal.confirm({
          title: '删除目录',
          content: `确定要删除目录 "${folder.name}" 吗？目录内的笔记不会被删除。`,
          okText: '删除',
          okType: 'danger',
          cancelText: '取消',
          onOk: () => onDeleteFolder?.(folder.id),
        });
      },
    },
  ];

  // 标签右键菜单
  const getTagContextMenu = (tag: Tag): MenuProps['items'] => [
    { 
      key: 'delete', 
      icon: <DeleteOutlined />, 
      label: '删除标签',
      danger: true,
      onClick: (e) => {
        e.domEvent.stopPropagation();
        Modal.confirm({
          title: '删除标签',
          content: `确定要删除标签 "${tag.name}" 吗？`,
          okText: '删除',
          okType: 'danger',
          cancelText: '取消',
          onOk: () => onDeleteTag?.(tag.id),
        });
      },
    },
  ];

  // 递归构建子目录
  const buildSubFolderItems = (parentId: string, level: number = 1): MenuProps['items'] => {
    const childFolders = folders.filter(f => f.parentId === parentId);

    if (childFolders.length === 0) {
      return [];
    }

    const items: MenuProps['items'] = [];
    // 计算缩进：每级增加 16px
    const indentPadding = level * 16;

    childFolders.forEach(folder => {
      const hasChildren = folders.some(f => f.parentId === folder.id);
      const isExpanded = expandedFolders.has(folder.id);
      const isSelected = selectedFolderId === folder.id;

      items.push({
        key: `folder-${folder.id}`,
        label: (
          <Dropdown menu={{ items: getFolderContextMenu(folder) }} trigger={['contextMenu']}>
            <span
              style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between', width: '100%', paddingLeft: indentPadding }}
            >
              <span style={{ display: 'flex', alignItems: 'center', gap: 8, flex: 1, overflow: 'hidden' }}>
                {isSelected ? <FolderOpenOutlined style={{ color: folder.color || '#1890ff' }} /> : <FolderOutlined style={{ color: folder.color || undefined }} />}
                <span style={{ overflow: 'hidden', textOverflow: 'ellipsis' }}>{folder.name}</span>
              </span>
              {hasChildren && (
                <span 
                  onClick={(e) => toggleFolderExpand(folder.id, e)}
                  style={{ padding: '0 4px', cursor: 'pointer', display: 'flex', alignItems: 'center' }}
                >
                  {isExpanded ? <DownOutlined style={{ fontSize: 10 }} /> : <RightOutlined style={{ fontSize: 10 }} />}
                </span>
              )}
            </span>
          </Dropdown>
        ),
      });

      // 如果展开了，添加子目录
      if (hasChildren && isExpanded) {
        const subItems = buildSubFolderItems(folder.id, level + 1);
        if (subItems) {
          items.push(...subItems);
        }
      }
    });

    return items;
  };

  // 获取一级目录
  const rootFolders = folders.filter(f => f.parentId === null);

  // 构建标签子菜单
  const tagChildren = tags.map(tag => ({
    key: `tag-${tag.id}`,
    icon: <TagOutlined style={{ color: tag.color || '#1890ff' }} />,
    label: (
      <Dropdown menu={{ items: getTagContextMenu(tag) }} trigger={['contextMenu']}>
        <span style={{ display: 'block' }}>{tag.name}</span>
      </Dropdown>
    ),
  }));

  // 构建一级目录列表
  const buildRootFolderItems = (): MenuProps['items'] => {
    const items: MenuProps['items'] = [];

    rootFolders.forEach(folder => {
      const hasChildren = folders.some(f => f.parentId === folder.id);
      const isExpanded = expandedFolders.has(folder.id);
      const isSelected = selectedFolderId === folder.id;

      items.push({
        key: `folder-${folder.id}`,
        icon: isSelected ? <FolderOpenOutlined style={{ color: folder.color || '#1890ff' }} /> : <FolderOutlined style={{ color: folder.color || undefined }} />,
        label: (
          <Dropdown menu={{ items: getFolderContextMenu(folder) }} trigger={['contextMenu']}>
            <span
              style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between', width: '100%' }}
            >
              <span style={{ flex: 1, overflow: 'hidden', textOverflow: 'ellipsis' }}>{folder.name}</span>
              {hasChildren && (
                <span 
                  onClick={(e) => toggleFolderExpand(folder.id, e)}
                  style={{ padding: '0 4px', cursor: 'pointer', display: 'flex', alignItems: 'center' }}
                >
                  {isExpanded ? <DownOutlined style={{ fontSize: 10 }} /> : <RightOutlined style={{ fontSize: 10 }} />}
                </span>
              )}
            </span>
          </Dropdown>
        ),
      });

      // 如果展开了，添加子目录
      if (hasChildren && isExpanded) {
        const subItems = buildSubFolderItems(folder.id, 1);
        if (subItems) {
          items.push(...subItems);
        }
      }
    });

    return items;
  };

  // 构建菜单项
  const menuItems: MenuProps['items'] = [
    // 待办事项（固定在顶部）
    ...(todoEnabled ? [{
      key: 'todo',
      icon: <CheckSquareOutlined />,
      label: '待办事项',
    }] : []),
    // 所有笔记（带添加目录按钮）
    { 
      key: 'all', 
      icon: <FileTextOutlined />, 
      label: (
        <span style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', width: '100%' }}>
          <span>所有笔记</span>
          <FolderAddOutlined 
            onClick={(e) => {
              e.stopPropagation();
              setNewFolderParentId(null);
              setNewFolderModalOpen(true);
            }}
            style={{ cursor: 'pointer', color: '#1890ff' }}
            title="添加目录"
          />
        </span>
      ),
    },
    // 未分类
    {
      key: 'uncategorized',
      icon: <FolderOutlined style={{ color: '#999' }} />,
      label: '未分类',
    },
    // 一级目录
    ...(buildRootFolderItems() || []),
    { type: 'divider' },
    // 星标笔记
    { key: 'starred', icon: <StarOutlined />, label: '星标笔记' },
    // 标签
    { 
      key: 'tags-group', 
      icon: <TagOutlined />, 
      label: '标签',
      children: tagChildren.length > 0 ? tagChildren : [
        { key: 'no-tags', label: '暂无标签', disabled: true }
      ],
    },
    { type: 'divider' },
    // 回收站
    { key: 'trash', icon: <DeleteOutlined />, label: '回收站' },
  ];

  const createMenuItems: MenuProps['items'] = [
    { key: 'template', label: '从模板创建', icon: <FileTextOutlined />, onClick: onCreateNote },
    { key: 'blank', label: '空白笔记', icon: <FileTextOutlined />, onClick: onQuickCreateNote },
    ...(excelEnabled ? [{ 
      key: 'excel', 
      label: 'Excel 笔记', 
      icon: <FileExcelOutlined />,
      onClick: () => onSelectTool?.('excel-create'),
    }] : []),
  ];

  const handleMenuClick = ({ key }: { key: string }) => {
    // 处理待办事项菜单点击
    if (key === 'todo') {
      onSelectTool?.('todo');
      return;
    }

    // 点击笔记相关菜单时，清除当前工具选择
    if (currentTool) {
      onSelectTool?.(null);
    }

    if (key === 'all') {
      onSelectView('all');
      onSelectFolder(null);
    } else if (key === 'uncategorized') {
      // 未分类 - 显示没有文件夹的笔记，使用特殊标识 'uncategorized'
      onSelectFolder('uncategorized');
    } else if (key === 'starred') {
      onSelectView('starred');
    } else if (key === 'trash') {
      onSelectView('trash');
    } else if (key.startsWith('folder-')) {
      const folderId = key.replace('folder-', '');
      handleFolderSelect(folderId);
    } else if (key.startsWith('tag-')) {
      const tagId = key.replace('tag-', '');
      onSelectTag(tagId);
    }
  };

  const handleCreateFolder = async () => {
    if (!newFolderName.trim()) {
      message.warning('请输入目录名称');
      return;
    }
    if (onCreateFolder) {
      await onCreateFolder(newFolderName.trim(), newFolderParentId);
      setNewFolderName('');
      setNewFolderParentId(null);
      setNewFolderModalOpen(false);
      message.success('目录已创建');
    }
  };

  const handleRenameFolder = async () => {
    if (!renameFolderName.trim()) {
      message.warning('请输入目录名称');
      return;
    }
    if (onRenameFolder && renameFolderId) {
      await onRenameFolder(renameFolderId, renameFolderName.trim());
      setRenameFolderName('');
      setRenameFolderId(null);
      setRenameFolderModalOpen(false);
      message.success('目录已重命名');
    }
  };

  // 计算选中的 key
  const getSelectedKeys = () => {
    if (currentTool === 'todo') return ['todo'];
    if (selectedView === 'starred') return ['starred'];
    if (selectedView === 'trash') return ['trash'];
    if (selectedFolderId === 'uncategorized') return ['uncategorized'];
    if (selectedFolderId) return [`folder-${selectedFolderId}`];
    return ['all'];
  };

  // 获取所有需要展开的目录 key（标签组）
  const getDefaultOpenKeys = () => {
    const openKeys: string[] = [];

    // 展开标签组
    if (tags.length > 0) {
      openKeys.push('tags-group');
    }

    return openKeys;
  };


  return (
    <div className="sidebar-container" style={{ display: 'flex', flexDirection: 'column', height: '100%' }}>
      {/* 工具栏区域 - 单行布局 */}
      <div style={{ padding: '8px 10px', borderBottom: '1px solid var(--border-color, #f0f0f0)' }}>
        <div style={{ display: 'flex', gap: 3, flexWrap: 'wrap' }}>
          {aiEnabled && (
            <Tooltip title="智能助理">
              <Button
                type={currentTool === 'ai' ? 'primary' : 'text'}
                icon={<RobotOutlined />}
                size="small"
                onClick={() => onSelectTool?.(currentTool === 'ai' ? null : 'ai')}
              />
            </Tooltip>
          )}
          {vaultEnabled && (
            <Tooltip title="密码库">
              <Button
                type={currentTool === 'vault' ? 'primary' : 'text'}
                icon={<SafetyOutlined />}
                size="small"
                onClick={() => onSelectTool?.(currentTool === 'vault' ? null : 'vault')}
              />
            </Tooltip>
          )}
          {bookmarkEnabled && (
            <Tooltip title="书签">
              <Button
                type={currentTool === 'bookmark' ? 'primary' : 'text'}
                icon={<LinkOutlined />}
                size="small"
                onClick={() => onSelectTool?.(currentTool === 'bookmark' ? null : 'bookmark')}
              />
            </Tooltip>
          )}
          {toolboxEnabled && (
            <Tooltip title="工具箱">
              <Button
                type={currentTool === 'toolbox' ? 'primary' : 'text'}
                icon={<AppstoreOutlined />}
                size="small"
                onClick={() => onSelectTool?.(currentTool === 'toolbox' ? null : 'toolbox')}
              />
            </Tooltip>
          )}
          {diagramEnabled && (
            <Tooltip title="脑图">
              <Button
                type={currentTool === 'diagram' ? 'primary' : 'text'}
                icon={<NodeIndexOutlined />}
                size="small"
                onClick={() => onSelectTool?.(currentTool === 'diagram' ? null : 'diagram')}
              />
            </Tooltip>
          )}
          {transferEnabled && (
            <Tooltip title="传输助手">
              <Button
                type={currentTool === 'transfer' ? 'primary' : 'text'}
                icon={<SwapOutlined />}
                size="small"
                onClick={() => onSelectTool?.(currentTool === 'transfer' ? null : 'transfer')}
              />
            </Tooltip>
          )}
        </div>
      </div>

      {/* 新建笔记按钮 */}
      <div style={{ padding: '8px 12px', borderBottom: '1px solid #f0f0f0' }}>
        <Dropdown menu={{ items: createMenuItems }} trigger={['click']}>
          <Button type="primary" icon={<PlusOutlined />} size="small" style={{ width: '100%' }}>
            新建笔记
          </Button>
        </Dropdown>
      </div>

      <div style={{ flex: 1, overflow: 'auto' }}>
        <Menu
          mode="inline"
          selectedKeys={getSelectedKeys()}
          defaultOpenKeys={getDefaultOpenKeys()}
          onClick={handleMenuClick}
          items={menuItems}
          className="sidebar-menu"
          style={{ background: 'transparent', borderRight: 0 }}
          inlineIndent={16}
        />
      </div>

      <div style={{ padding: '8px 12px', borderTop: '1px solid #f0f0f0', display: 'flex', gap: 8 }}>
        <Tooltip title="设置">
          <Button
            type="text"
            icon={<SettingOutlined />}
            onClick={onOpenSettings}
            size="small"
            style={{ color: '#666' }}
          />
        </Tooltip>
        <Tooltip title={syncStatus === 'syncing' ? '同步中...' : '立即同步'}>
          <Button
            type="text"
            icon={<SyncOutlined spin={syncStatus === 'syncing'} />}
            onClick={onSync}
            size="small"
            style={{ color: syncStatus === 'error' ? '#ff4d4f' : '#666' }}
            disabled={syncStatus === 'syncing'}
          />
        </Tooltip>
      </div>

      <Modal
        title={newFolderParentId ? "新建子目录" : "新建目录"}
        open={newFolderModalOpen}
        onOk={handleCreateFolder}
        onCancel={() => {
          setNewFolderModalOpen(false);
          setNewFolderName('');
          setNewFolderParentId(null);
        }}
        okText="创建"
        cancelText="取消"
      >
        <Input
          placeholder="目录名称"
          value={newFolderName}
          onChange={e => setNewFolderName(e.target.value)}
          onPressEnter={handleCreateFolder}
          autoFocus
        />
      </Modal>

      <Modal
        title="重命名目录"
        open={renameFolderModalOpen}
        onOk={handleRenameFolder}
        onCancel={() => {
          setRenameFolderModalOpen(false);
          setRenameFolderName('');
          setRenameFolderId(null);
        }}
        okText="确定"
        cancelText="取消"
      >
        <Input
          placeholder="目录名称"
          value={renameFolderName}
          onChange={e => setRenameFolderName(e.target.value)}
          onPressEnter={handleRenameFolder}
          autoFocus
        />
      </Modal>
    </div>
  );
};

export default Sidebar;

/**
 * LAN Transfer Assistant - 聊天视图组件
 */

import React, { useState, useEffect, useRef, useCallback } from 'react';
import {
  Layout,
  Input,
  Button,
  Space,
  Typography,
  Avatar,
  Upload,
  Progress,
  Tooltip,
  Modal,
  message,
  Spin,
} from 'antd';
import {
  SendOutlined,
  PaperClipOutlined,
  FileOutlined,
  FileImageOutlined,
  FilePdfOutlined,
  FileZipOutlined,
  CloseOutlined,
  DownloadOutlined,
  FolderOpenOutlined,
  EyeOutlined,
  CheckCircleOutlined,
  UserOutlined,
  DesktopOutlined,
} from '@ant-design/icons';
import {
  transferClient,
  TransferSession,
  TransferMessage,
  TransferFile,
} from '../../services/transferClient';
import { useSettings } from '../../contexts/SettingsContext';

const { Header, Content, Footer } = Layout;
const { Text } = Typography;
const { TextArea } = Input;

interface ChatViewProps {
  session: TransferSession;
  onClose: () => void;
}

export const ChatView: React.FC<ChatViewProps> = ({ session, onClose }) => {
  const { isDarkMode } = useSettings();
  const [messages, setMessages] = useState<TransferMessage[]>([]);
  const [files, setFiles] = useState<TransferFile[]>([]);
  const [inputValue, setInputValue] = useState('');
  const [loading, setLoading] = useState(true);
  const [sending, setSending] = useState(false);
  const [previewImage, setPreviewImage] = useState<string | null>(null);
  const messagesEndRef = useRef<HTMLDivElement>(null);

  const electronAPI = (window as any).electronAPI;

  const handleOpenFile = useCallback(
    async (filePath: string) => {
      if (!filePath || !electronAPI?.openPath) return;
      try {
        await electronAPI.openPath(filePath);
      } catch (e) {
        console.error('[ChatView] Failed to open file:', e);
        message.error('打开文件失败');
      }
    },
    [electronAPI]
  );

  const handleOpenFolder = useCallback(
    async (filePath: string) => {
      if (!filePath || !electronAPI?.openPath) return;
      try {
        const lastSep = Math.max(filePath.lastIndexOf('/'), filePath.lastIndexOf('\\'));
        const folder = lastSep >= 0 ? filePath.substring(0, lastSep) : filePath;
        await electronAPI.openPath(folder);
      } catch (e) {
        console.error('[ChatView] Failed to open folder:', e);
        message.error('打开文件夹失败');
      }
    },
    [electronAPI]
  );

  useEffect(() => {
    const loadData = async () => {
      try {
        setLoading(true);
        const [msgs, fls] = await Promise.all([
          transferClient.getMessagesBySession(session.id),
          transferClient.getFilesBySession(session.id),
        ]);
        setMessages(msgs);
        setFiles(fls);
        await transferClient.markSessionMessagesAsRead(session.id);
      } catch (error) {
        console.error('Failed to load messages:', error);
      } finally {
        setLoading(false);
      }
    };
    loadData();
  }, [session.id]);

  useEffect(() => {
    const unsubMessage = transferClient.onMessageReceived(data => {
      if (data.senderId === session.peer_device_id) {
        const newMessage: TransferMessage = {
          id: data.message?.id || transferClient.generateMessageId(),
          session_id: session.id,
          direction: 'received',
          type: data.message?.type || 'text',
          content: data.message?.content || '',
          file_id: data.message?.fileId || null,
          created_at: Date.now(),
          read_at: Date.now(),
        };
        setMessages(prev => [...prev, newMessage]);
        transferClient.sendMessageReadReceipt(data.senderId, [newMessage.id]);
      }
    });

    const unsubFileIncoming = transferClient.onFileIncoming(data => {
      if (data.senderId === session.peer_device_id) {
        const newFile: TransferFile = {
          id: data.fileInfo.id,
          session_id: session.id,
          filename: data.fileInfo.filename,
          file_size: data.fileInfo.fileSize,
          mime_type: data.fileInfo.mimeType,
          local_path: null,
          direction: 'received',
          status: 'pending',
          progress: 0,
          file_hash: null,
          created_at: Date.now(),
          completed_at: null,
        };
        setFiles(prev => [...prev, newFile]);
      }
    });

    const unsubFileChunk = transferClient.onFileChunk(data => {
      setFiles(prev =>
        prev.map(f =>
          f.id === data.fileId
            ? {
                ...f,
                progress: ((data.chunkIndex + 1) / data.totalChunks) * 100,
                status: 'transferring',
              }
            : f
        )
      );
    });

    const unsubFileComplete = transferClient.onFileComplete(data => {
      setFiles(prev =>
        prev.map(f =>
          f.id === data.fileId
            ? {
                ...f,
                progress: 100,
                status: 'completed',
                completed_at: Date.now(),
                local_path: data.localPath || f.local_path,
              }
            : f
        )
      );
      transferClient.completeFileTransfer(data.fileId, data.localPath || '', data.fileHash);
    });

    const handleRelayRefresh = async (event: Event) => {
      const customEvent = event as CustomEvent<{ sessionId: string }>;
      if (customEvent.detail.sessionId === session.id) {
        try {
          const msgs = await transferClient.getMessagesBySession(session.id);
          setMessages(msgs);
        } catch (error) {
          console.error('Failed to refresh messages:', error);
        }
      }
    };
    window.addEventListener('transfer:refresh-messages', handleRelayRefresh);

    return () => {
      unsubMessage();
      unsubFileIncoming();
      unsubFileChunk();
      unsubFileComplete();
      window.removeEventListener('transfer:refresh-messages', handleRelayRefresh);
    };
  }, [session.id, session.peer_device_id]);

  useEffect(() => {
    messagesEndRef.current?.scrollIntoView({ behavior: 'smooth' });
  }, [messages, files]);

  const handleSend = useCallback(async () => {
    if (!inputValue.trim()) return;
    try {
      setSending(true);
      const newMessage: TransferMessage = {
        id: transferClient.generateMessageId(),
        session_id: session.id,
        direction: 'sent',
        type: 'text',
        content: inputValue.trim(),
        file_id: null,
        created_at: Date.now(),
        read_at: null,
      };
      setMessages(prev => [...prev, newMessage]);
      setInputValue('');

      await transferClient.sendTextMessage(session.peer_device_id, session.id, newMessage.content);
    } catch (error) {
      message.error('发送失败');
    } finally {
      setSending(false);
    }
  }, [inputValue, session.id, session.peer_device_id, session.connection_type]);

  const sendFilePath = useCallback(
    async (filePath: string) => {
      const result = await transferClient.sendFile(session.peer_device_id, session.id, filePath);

      const newFile: TransferFile = {
        id: result.id,
        session_id: session.id,
        filename: result.filename,
        file_size: result.fileSize,
        mime_type: result.mimeType,
        local_path: filePath,
        direction: 'sent',
        status: 'completed',
        progress: 100,
        file_hash: null,
        created_at: Date.now(),
        completed_at: Date.now(),
      };
      setFiles(prev => [...prev, newFile]);
      return result;
    },
    [session.id, session.peer_device_id]
  );

  const blobToDataUrl = (blob: Blob): Promise<string> =>
    new Promise((resolve, reject) => {
      const reader = new FileReader();
      reader.onload = () => {
        if (typeof reader.result === 'string') {
          resolve(reader.result);
        } else {
          reject(new Error('无法读取剪贴板文件'));
        }
      };
      reader.onerror = () => reject(reader.error || new Error('无法读取剪贴板文件'));
      reader.readAsDataURL(blob);
    });

  const getClipboardFilename = (file: File, index: number): string => {
    if (file.name && file.name !== 'image.png') return file.name;
    const extension = file.type.split('/')[1]?.replace('jpeg', 'jpg') || 'bin';
    const timestamp = new Date()
      .toISOString()
      .replace(/[:.]/g, '-')
      .replace('T', '-')
      .slice(0, 19);
    return `clipboard-${timestamp}${index > 0 ? `-${index + 1}` : ''}.${extension}`;
  };

  const handlePaste = useCallback(
    async (e: React.ClipboardEvent<HTMLTextAreaElement>) => {
      const clipboardData = e.clipboardData;
      if (!clipboardData) return;

      const pastedFiles = Array.from(clipboardData.files || []);
      const itemFiles = Array.from(clipboardData.items || [])
        .filter(item => item.kind === 'file')
        .map(item => item.getAsFile())
        .filter((file): file is File => !!file);
      const uniqueFiles = [...pastedFiles];
      for (const file of itemFiles) {
        if (!uniqueFiles.some(existing => existing.name === file.name && existing.size === file.size)) {
          uniqueFiles.push(file);
        }
      }

      if (uniqueFiles.length === 0) return;

      e.preventDefault();
      e.stopPropagation();

      try {
        for (let i = 0; i < uniqueFiles.length; i++) {
          const file = uniqueFiles[i];
          let filePath = (file as any).path as string | undefined;
          if (!filePath) {
            const dataUrl = await blobToDataUrl(file);
            filePath = await transferClient.saveTempFile(getClipboardFilename(file, i), dataUrl);
          }
          const result = await sendFilePath(filePath);
          message.success(`文件 ${result.filename} 已发送`);
        }
      } catch (error: any) {
        console.error('[ChatView] Failed to send pasted file:', error);
        message.error(error.message || '粘贴发送失败');
      }
    },
    [sendFilePath]
  );

  const handleKeyDown = (e: React.KeyboardEvent) => {
    if (e.key === 'Enter' && !e.shiftKey) {
      e.preventDefault();
      handleSend();
    }
  };

  const getFileIcon = (mimeType: string) => {
    if (mimeType?.startsWith('image/')) return <FileImageOutlined />;
    if (mimeType === 'application/pdf') return <FilePdfOutlined />;
    if (mimeType?.includes('zip') || mimeType?.includes('rar')) return <FileZipOutlined />;
    return <FileOutlined />;
  };

  const formatTime = (timestamp: number) => {
    const date = new Date(timestamp);
    return `${date.getHours().toString().padStart(2, '0')}:${date.getMinutes().toString().padStart(2, '0')}`;
  };

  const isImageFile = (file: TransferFile) => {
    return file.mime_type?.startsWith('image/') && file.local_path && file.status === 'completed';
  };

  const renderMessageItem = (msg: TransferMessage) => {
    const isSent = msg.direction === 'sent';
    return (
      <div
        key={msg.id}
        style={{
          display: 'flex',
          justifyContent: isSent ? 'flex-end' : 'flex-start',
          marginBottom: 12,
          padding: '0 16px',
        }}
      >
        {!isSent && (
          <Avatar size="small" icon={<UserOutlined />} style={{ marginRight: 8, flexShrink: 0 }} />
        )}
        <div
          style={{
            maxWidth: '70%',
            padding: '8px 12px',
            borderRadius: isSent ? '12px 12px 4px 12px' : '12px 12px 12px 4px',
            background: isSent ? '#1890ff' : isDarkMode ? '#303030' : '#f0f0f0',
            color: isSent ? '#fff' : undefined,
          }}
        >
          <Text style={{ color: isSent ? '#fff' : undefined, whiteSpace: 'pre-wrap' }}>
            {msg.content}
          </Text>
          <div style={{ textAlign: 'right', marginTop: 4 }}>
            <Text
              style={{ fontSize: 10, color: isSent ? 'rgba(255,255,255,0.7)' : undefined }}
              type={isSent ? undefined : 'secondary'}
            >
              {formatTime(msg.created_at)}
              {isSent && msg.read_at && <CheckCircleOutlined style={{ marginLeft: 4 }} />}
            </Text>
          </div>
        </div>
        {isSent && (
          <Avatar
            size="small"
            icon={<DesktopOutlined />}
            style={{ marginLeft: 8, flexShrink: 0, background: '#1890ff' }}
          />
        )}
      </div>
    );
  };

  const renderFileItem = (file: TransferFile) => {
    const isSent = file.direction === 'sent';
    const isImage = isImageFile(file);
    return (
      <div
        key={file.id}
        style={{
          display: 'flex',
          justifyContent: isSent ? 'flex-end' : 'flex-start',
          marginBottom: 12,
          padding: '0 16px',
        }}
      >
        {!isSent && (
          <Avatar size="small" icon={<UserOutlined />} style={{ marginRight: 8, flexShrink: 0 }} />
        )}
        <div
          style={{
            maxWidth: '70%',
            padding: '12px',
            borderRadius: 8,
            background: isDarkMode ? '#303030' : '#f5f5f5',
            border: `1px solid ${isDarkMode ? '#434343' : '#e8e8e8'}`,
          }}
        >
          {isImage && (
            <div
              style={{ marginBottom: 8, cursor: 'pointer' }}
              onClick={() => setPreviewImage(file.local_path!)}
            >
              <img
                src={file.local_path || ''}
                alt={file.filename}
                style={{ maxWidth: '100%', maxHeight: 200, borderRadius: 4, display: 'block' }}
              />
            </div>
          )}
          <Space>
            {!isImage && (
              <Avatar
                shape="square"
                size={40}
                icon={getFileIcon(file.mime_type)}
                style={{ background: '#1890ff' }}
              />
            )}
            <div>
              <Text strong ellipsis style={{ maxWidth: 150, display: 'block' }}>
                {file.filename}
              </Text>
              <Text type="secondary" style={{ fontSize: 12 }}>
                {transferClient.formatFileSize(file.file_size)}
              </Text>
            </div>
          </Space>

          {file.status === 'transferring' && (
            <Progress percent={Math.round(file.progress)} size="small" style={{ marginTop: 8 }} />
          )}

          {file.status === 'completed' && (
            <div style={{ marginTop: 4 }}>
              <Space size="small">
                {isImage && (
                  <Button
                    type="link"
                    size="small"
                    icon={<EyeOutlined />}
                    style={{ padding: 0 }}
                    onClick={() => setPreviewImage(file.local_path!)}
                  >
                    查看
                  </Button>
                )}
                <Button
                  type="link"
                  size="small"
                  icon={<DownloadOutlined />}
                  style={{ padding: 0 }}
                  onClick={() => handleOpenFile(file.local_path || '')}
                >
                  打开文件
                </Button>
                <Button
                  type="link"
                  size="small"
                  icon={<FolderOpenOutlined />}
                  style={{ padding: 0 }}
                  onClick={() => handleOpenFolder(file.local_path || '')}
                >
                  打开文件夹
                </Button>
              </Space>
            </div>
          )}

          {file.status === 'pending' && file.direction === 'received' && (
            <div style={{ marginTop: 8 }}>
              <Text type="secondary" style={{ fontSize: 12 }}>
                等待接收...
              </Text>
            </div>
          )}

          <div style={{ textAlign: 'right', marginTop: 4 }}>
            <Text type="secondary" style={{ fontSize: 10 }}>
              {formatTime(file.created_at)}
            </Text>
          </div>
        </div>
        {isSent && (
          <Avatar
            size="small"
            icon={<DesktopOutlined />}
            style={{ marginLeft: 8, flexShrink: 0, background: '#1890ff' }}
          />
        )}
      </div>
    );
  };

  const allItems = [...messages, ...files].sort((a, b) => a.created_at - b.created_at);

  return (
    <Layout style={{ height: '100%', background: 'transparent' }}>
      <Header
        style={{
          background: isDarkMode ? '#1f1f1f' : '#fff',
          padding: '0 16px',
          height: 56,
          lineHeight: '56px',
          borderBottom: `1px solid ${isDarkMode ? '#303030' : '#f0f0f0'}`,
          display: 'flex',
          justifyContent: 'space-between',
          alignItems: 'center',
        }}
      >
        <Space>
          <Avatar icon={<UserOutlined />} />
          <div>
            <Text strong>{session.peer_device_name}</Text>
            <br />
            <Text type="secondary" style={{ fontSize: 12 }}>
              {session.connection_type === 'lan' ? '局域网连接' : '中继连接'}
            </Text>
          </div>
        </Space>
        <Tooltip title="关闭">
          <Button type="text" icon={<CloseOutlined />} onClick={onClose} />
        </Tooltip>
      </Header>

      <Content
        style={{
          overflow: 'auto',
          padding: '16px 0',
          background: isDarkMode ? '#141414' : '#fafafa',
        }}
      >
        {loading ? (
          <div style={{ textAlign: 'center', padding: 48 }}>
            <Spin tip="加载消息中..." />
          </div>
        ) : allItems.length === 0 ? (
          <div style={{ textAlign: 'center', padding: 48 }}>
            <Text type="secondary">暂无消息，发送第一条消息吧</Text>
          </div>
        ) : (
          <>
            {allItems.map(item =>
              'content' in item
                ? renderMessageItem(item as TransferMessage)
                : renderFileItem(item as TransferFile)
            )}
            <div ref={messagesEndRef} />
          </>
        )}
      </Content>

      <Footer
        style={{
          background: isDarkMode ? '#1f1f1f' : '#fff',
          padding: '12px 16px',
          borderTop: `1px solid ${isDarkMode ? '#303030' : '#f0f0f0'}`,
        }}
      >
        <Space.Compact style={{ width: '100%' }}>
          <Upload
            showUploadList={false}
            beforeUpload={async file => {
              try {
                const filePath = (file as any).path;
                if (!filePath) {
                  message.error('无法获取文件路径');
                  return false;
                }

                const result = await sendFilePath(filePath);
                message.success(`文件 ${result.filename} 已发送`);
              } catch (error: any) {
                console.error('[ChatView] Failed to send file:', error);
                message.error(error.message || '文件发送失败');
              }
              return false;
            }}
          >
            <Button icon={<PaperClipOutlined />} />
          </Upload>
          <TextArea
            value={inputValue}
            onChange={e => setInputValue(e.target.value)}
            onKeyDown={handleKeyDown}
            onPaste={handlePaste}
            placeholder="输入消息..."
            autoSize={{ minRows: 1, maxRows: 4 }}
            style={{ flex: 1 }}
          />
          <Button
            type="primary"
            icon={<SendOutlined />}
            onClick={handleSend}
            loading={sending}
            disabled={!inputValue.trim()}
          />
        </Space.Compact>
      </Footer>

      <Modal
        open={!!previewImage}
        footer={null}
        onCancel={() => setPreviewImage(null)}
        width="auto"
        style={{ maxWidth: '90vw' }}
        centered
      >
        <img
          src={previewImage || ''}
          alt="preview"
          style={{ maxWidth: '100%', maxHeight: '80vh', display: 'block', margin: '0 auto' }}
        />
      </Modal>
    </Layout>
  );
};

export default ChatView;

package com.mucheng.notes.data.remote

import com.mucheng.notes.data.local.entity.ItemEntity
import com.mucheng.notes.domain.model.SyncConfig
import com.thegrizzlylabs.sardineandroid.Sardine
import com.thegrizzlylabs.sardineandroid.impl.OkHttpSardine
import kotlinx.coroutines.Dispatchers
import kotlinx.coroutines.withContext
import kotlinx.serialization.encodeToString
import kotlinx.serialization.json.Json
import javax.inject.Inject
import javax.inject.Singleton

/**
 * WebDAV 适配器实现
 * 使用 Sardine 库进行 WebDAV 操作
 */
@Singleton
class WebDAVAdapterImpl @Inject constructor() : WebDAVAdapter {

    private val json = Json {
        ignoreUnknownKeys = true
        encodeDefaults = true
        isLenient = true  // 允许更宽松的 JSON 解析
        coerceInputValues = true  // 将缺失的字段填充为默认值
    }

    private var sardine: Sardine? = null
    private var config: SyncConfig? = null

    /**
     * 初始化 WebDAV 连接
     */
    fun initialize(syncConfig: SyncConfig) {
        config = syncConfig
        sardine = OkHttpSardine().apply {
            if (!syncConfig.username.isNullOrEmpty() && !syncConfig.password.isNullOrEmpty()) {
                setCredentials(syncConfig.username, syncConfig.password)
            }
        }
    }

    private fun getSardine(): Sardine {
        return sardine ?: throw IllegalStateException("WebDAV not initialized")
    }

    private fun getConfig(): SyncConfig {
        return config ?: throw IllegalStateException("WebDAV not initialized")
    }

    private fun getItemsPath(): String {
        val cfg = getConfig()
        return "${cfg.url}${cfg.syncPath}/items"
    }

    private fun getResourcesPath(): String {
        val cfg = getConfig()
        return "${cfg.url}${cfg.syncPath}/resources"
    }

    private fun getChangesPath(): String {
        val cfg = getConfig()
        return "${cfg.url}${cfg.syncPath}/changes"
    }

    override suspend fun testConnection(): Boolean = withContext(Dispatchers.IO) {
        try {
            val cfg = getConfig()
            val sardine = getSardine()

            android.util.Log.d("WebDAV", "Testing connection to: ${cfg.url}${cfg.syncPath}")

            // 尝试访问同步目录
            val path = "${cfg.url}${cfg.syncPath}"
            val exists = sardine.exists(path)
            android.util.Log.d("WebDAV", "Path exists: $exists")

            if (!exists) {
                // 创建目录结构
                android.util.Log.d("WebDAV", "Creating directory structure...")
                sardine.createDirectory(path)
                sardine.createDirectory(getItemsPath())
                sardine.createDirectory(getResourcesPath())
                sardine.createDirectory(getChangesPath())
                android.util.Log.d("WebDAV", "Directory structure created")
            }

            android.util.Log.d("WebDAV", "Connection test successful")
            true
        } catch (e: Exception) {
            android.util.Log.e("WebDAV", "Connection test failed: ${e.message}")
            android.util.Log.e("WebDAV", "Exception type: ${e.javaClass.simpleName}")
            e.printStackTrace()
            false
        }
    }

    override suspend fun getItem(id: String): ItemEntity? = withContext(Dispatchers.IO) {
        try {
            val sardine = getSardine()
            val path = "${getItemsPath()}/$id.json"

            if (!sardine.exists(path)) {
                android.util.Log.d("WebDAV", "getItem: file does not exist: $path")
                return@withContext null
            }

            val inputStream = sardine.get(path)
            val content = inputStream.bufferedReader().use { it.readText() }
            android.util.Log.d("WebDAV", "getItem: read content for $id, length=${content.length}")

            // 添加详细的解析日志
            try {
                // 先打印原始JSON的前200字符，帮助调试
                val preview = if (content.length > 200) content.substring(0, 200) + "..." else content
                android.util.Log.d("WebDAV", "getItem: JSON preview: $preview")

                val item = json.decodeFromString<ItemEntity>(content)
                android.util.Log.d("WebDAV", "getItem: ✅ Successfully parsed item $id, type=${item.type}, encryptionApplied=${item.encryptionApplied}")
                item
            } catch (parseError: Exception) {
                // 详细的解析错误日志
                android.util.Log.e("WebDAV", "❌ JSON Parse Error for item $id:")
                android.util.Log.e("WebDAV", "  Error Type: ${parseError.javaClass.simpleName}")
                android.util.Log.e("WebDAV", "  Error Message: ${parseError.message}")
                android.util.Log.e("WebDAV", "  Content Length: ${content.length}")
                android.util.Log.e("WebDAV", "  Content Preview (first 500 chars):")
                android.util.Log.e("WebDAV", content.take(500))

                // 尝试解析为通用JSON对象，检查字段
                try {
                    val jsonElement = kotlinx.serialization.json.Json.parseToJsonElement(content)
                    android.util.Log.e("WebDAV", "  Available fields: ${jsonElement}")
                } catch (e: Exception) {
                    android.util.Log.e("WebDAV", "  Cannot parse as JSON at all: ${e.message}")
                }

                parseError.printStackTrace()
                null
            }
        } catch (e: Exception) {
            android.util.Log.e("WebDAV", "getItem: failed to get item $id: ${e.message}")
            e.printStackTrace()
            null
        }
    }

    override suspend fun putItem(item: ItemEntity): Result<String> = withContext(Dispatchers.IO) {
        try {
            val sardine = getSardine()
            val path = "${getItemsPath()}/${item.id}.json"
            val content = json.encodeToString(item)

            sardine.put(path, content.toByteArray(), "application/json")

            // 记录变更到变更日志 (与桌面端保持一致)
            recordChange(item)

            // 返回时间戳作为版本号
            val remoteRev = System.currentTimeMillis().toString()
            Result.success(remoteRev)
        } catch (e: Exception) {
            android.util.Log.e("WebDAV", "Failed to put item ${item.id}: ${e.message}")
            Result.failure(e)
        }
    }

    override suspend fun deleteItem(id: String): Boolean = withContext(Dispatchers.IO) {
        try {
            val sardine = getSardine()
            val path = "${getItemsPath()}/$id.json"

            if (sardine.exists(path)) {
                sardine.delete(path)
            }
            true
        } catch (e: Exception) {
            false
        }
    }

    override suspend fun listChanges(cursor: String?, limit: Int): ChangeListResult = withContext(Dispatchers.IO) {
        try {
            val sardine = getSardine()
            val changesPath = getChangesPath()

            // 检查 changes 目录是否存在
            val dirExists = sardine.exists(changesPath)
            if (!dirExists) {
                android.util.Log.d("WebDAV", "Changes directory does not exist, creating...")
                try {
                    sardine.createDirectory(changesPath)
                } catch (e: Exception) {
                    android.util.Log.w("WebDAV", "Failed to create changes directory: ${e.message}")
                }

                // 向后兼容：如果没有changes目录，回退到扫描items目录 (首次同步或旧版本数据)
                android.util.Log.d("WebDAV", "Falling back to items directory scan for backward compatibility")
                return@withContext listChangesFromItems(cursor, limit)
            }

            // 列出所有变更文件
            val resources = sardine.list(changesPath)

            // 过滤并排序 JSON 文件
            val sortedFiles = resources
                .filter { !it.isDirectory && it.name.endsWith(".json") }
                .sortedBy { it.name }

            android.util.Log.d("WebDAV", "Found ${sortedFiles.size} change files, cursor=$cursor")

            // 如果没有变更文件，回退到扫描items目录 (向后兼容)
            if (sortedFiles.isEmpty()) {
                android.util.Log.d("WebDAV", "No change files found, falling back to items directory scan")
                return@withContext listChangesFromItems(cursor, limit)
            }

            // 找到游标位置
            var startIndex = 0
            if (cursor != null) {
                val cursorIndex = sortedFiles.indexOfFirst { it.name == cursor }
                if (cursorIndex >= 0) {
                    // 游标文件存在，从它的下一个开始
                    startIndex = cursorIndex + 1
                } else {
                    // 游标文件不存在（例如全量拉取后设置的时间点游标），
                    // 按文件名字符串比较找到第一个比游标新的文件
                    val firstNewerIndex = sortedFiles.indexOfFirst { it.name > cursor }
                    startIndex = if (firstNewerIndex >= 0) firstNewerIndex else sortedFiles.size
                }
            }

            // 如果游标已经在末尾，没有更多变更
            if (startIndex >= sortedFiles.size) {
                android.util.Log.d("WebDAV", "Cursor at end, no more changes")
                return@withContext ChangeListResult(emptyList(), null, false)
            }

            // 读取变更
            val changes = mutableListOf<RemoteChange>()
            val endIndex = minOf(startIndex + limit, sortedFiles.size)

            for (i in startIndex until endIndex) {
                try {
                    val inputStream = sardine.get("$changesPath/${sortedFiles[i].name}")
                    val content = inputStream.bufferedReader().use { it.readText() }
                    val change = json.decodeFromString<RemoteChange>(content)
                    changes.add(change)
                } catch (e: Exception) {
                    android.util.Log.w("WebDAV", "Failed to read change file ${sortedFiles[i].name}: ${e.message}")
                    // 跳过损坏的文件，继续处理
                }
            }

            val hasMore = endIndex < sortedFiles.size
            val nextCursor = if (changes.isNotEmpty()) sortedFiles[endIndex - 1].name else null

            android.util.Log.d("WebDAV", "Loaded ${changes.size} changes, hasMore=$hasMore, nextCursor=$nextCursor")

            ChangeListResult(
                changes = changes,
                nextCursor = nextCursor,
                hasMore = hasMore
            )
        } catch (e: Exception) {
            android.util.Log.e("WebDAV", "Failed to list changes: ${e.message}")
            e.printStackTrace()
            ChangeListResult(emptyList(), null, false)
        }
    }

    // ❌ 游标已移至本地存储，不再从WebDAV读写
    // 保留这两个方法是为了兼容 WebDAVAdapter 接口
    // 但实际上不再使用，游标由 SyncEngine 的 SharedPreferences 管理
    override suspend fun getSyncCursor(): SyncCursor? = withContext(Dispatchers.IO) {
        android.util.Log.w("WebDAVAdapter", "getSyncCursor is deprecated. Use SyncEngine.getLocalSyncCursor() instead.")
        return@withContext null
    }

    override suspend fun setSyncCursor(cursor: SyncCursor): Boolean = withContext(Dispatchers.IO) {
        android.util.Log.w("WebDAVAdapter", "setSyncCursor is deprecated. Use SyncEngine.setLocalSyncCursor() instead.")
        return@withContext true
    }

    // 资源文件操作

    override suspend fun uploadResource(resourceId: String, data: ByteArray): Result<String> = withContext(Dispatchers.IO) {
        try {
            val sardine = getSardine()
            val path = "${getResourcesPath()}/$resourceId"

            sardine.put(path, data, "application/octet-stream")
            Result.success(System.currentTimeMillis().toString())
        } catch (e: Exception) {
            Result.failure(e)
        }
    }

    override suspend fun downloadResource(resourceId: String): Result<ByteArray> = withContext(Dispatchers.IO) {
        try {
            val sardine = getSardine()
            val path = "${getResourcesPath()}/$resourceId"

            val inputStream = sardine.get(path)
            val data = inputStream.readBytes()
            Result.success(data)
        } catch (e: Exception) {
            Result.failure(e)
        }
    }

    override suspend fun deleteResource(resourceId: String): Boolean = withContext(Dispatchers.IO) {
        try {
            val sardine = getSardine()
            val path = "${getResourcesPath()}/$resourceId"

            if (sardine.exists(path)) {
                sardine.delete(path)
            }
            true
        } catch (e: Exception) {
            false
        }
    }

    override suspend fun listResources(): List<String> = withContext(Dispatchers.IO) {
        try {
            val sardine = getSardine()
            val resourcesPath = getResourcesPath()

            val resources = sardine.list(resourcesPath)
            resources.filter { !it.isDirectory }.map { it.name }
        } catch (e: Exception) {
            emptyList()
        }
    }

    // 密钥标识符操作 - 从 workspace.json 读取，与电脑端保持一致

    override suspend fun getKeyIdentifier(): String? = withContext(Dispatchers.IO) {
        try {
            val sardine = getSardine()
            val cfg = getConfig()
            val metaPath = "${cfg.url}${cfg.syncPath}/workspace.json"

            if (!sardine.exists(metaPath)) return@withContext null

            val inputStream = sardine.get(metaPath)
            val content = inputStream.bufferedReader().use { it.readText() }
            val meta = json.decodeFromString<WorkspaceMeta>(content)
            meta.key_identifier
        } catch (e: Exception) {
            android.util.Log.e("WebDAV", "Failed to get key identifier: ${e.message}")
            null
        }
    }

    override suspend fun setKeyIdentifier(keyId: String): Boolean = withContext(Dispatchers.IO) {
        try {
            val sardine = getSardine()
            val cfg = getConfig()
            val metaPath = "${cfg.url}${cfg.syncPath}/workspace.json"

            // 读取现有的 workspace.json 或创建新的
            val existingMeta = try {
                if (sardine.exists(metaPath)) {
                    val inputStream = sardine.get(metaPath)
                    val content = inputStream.bufferedReader().use { it.readText() }
                    json.decodeFromString<WorkspaceMeta>(content)
                } else {
                    WorkspaceMeta()
                }
            } catch (e: Exception) {
                WorkspaceMeta()
            }

            // 更新 key_identifier
            val updatedMeta = existingMeta.copy(
                key_identifier = keyId,
                last_sync_time = System.currentTimeMillis()
            )

            val content = json.encodeToString(updatedMeta)
            sardine.put(metaPath, content.toByteArray(), "application/json")
            true
        } catch (e: Exception) {
            android.util.Log.e("WebDAV", "Failed to set key identifier: ${e.message}")
            false
        }
    }

    override suspend fun hasData(): Boolean = withContext(Dispatchers.IO) {
        try {
            val sardine = getSardine()
            val itemsPath = getItemsPath()

            // 检查 items 目录是否存在且有文件
            if (!sardine.exists(itemsPath)) {
                return@withContext false
            }

            val items = sardine.list(itemsPath)
            // 过滤掉目录本身，只检查文件
            items.any { !it.isDirectory && it.name.endsWith(".json") }
        } catch (e: Exception) {
            // 出错时假设没有数据，允许首次同步
            false
        }
    }

    override suspend fun listAllItems(): List<ItemEntity> = withContext(Dispatchers.IO) {
        try {
            val sardine = getSardine()
            val itemsPath = getItemsPath()

            if (!sardine.exists(itemsPath)) {
                return@withContext emptyList()
            }

            val resources = sardine.list(itemsPath)
            val items = mutableListOf<ItemEntity>()

            for (resource in resources) {
                if (resource.isDirectory || !resource.name.endsWith(".json")) continue
                val id = resource.name.removeSuffix(".json")
                try {
                    val item = getItem(id)
                    if (item != null) items.add(item)
                } catch (e: Exception) {
                    android.util.Log.w("WebDAV", "listAllItems: failed to read item $id: ${e.message}")
                }
            }

            android.util.Log.d("WebDAV", "listAllItems: got ${items.size} items")
            items
        } catch (e: Exception) {
            android.util.Log.e("WebDAV", "listAllItems failed: ${e.message}")
            emptyList()
        }
    }

    override suspend fun isCursorExpired(cursor: String): Boolean {
        // WebDAV 使用文件名作为游标，检查对应的变更文件是否还存在
        return withContext(Dispatchers.IO) {
            try {
                val sardine = getSardine()
                val changesPath = getChangesPath()
                if (!sardine.exists(changesPath)) return@withContext true
                val resources = sardine.list(changesPath)
                val files = resources.filter { !it.isDirectory && it.name.endsWith(".json") }.map { it.name }
                if (files.isEmpty()) return@withContext true
                // 如果游标文件名不在列表中且比最早的文件还早，说明已过期
                !files.contains(cursor) && cursor < (files.minOrNull() ?: cursor)
            } catch (e: Exception) {
                false
            }
        }
    }

    override fun getLastFullPullChangeId(): Long? {
        // WebDAV 不使用 change_id，返回 null
        return null
    }

    override suspend fun getKeyFingerprint(): String? = withContext(Dispatchers.IO) {
        try {
            val sardine = getSardine()
            val cfg = getConfig()
            val path = "${cfg.url}${cfg.syncPath}/.encryption-key-fingerprint"

            if (!sardine.exists(path)) {
                return@withContext null
            }

            val inputStream = sardine.get(path)
            val content = inputStream.bufferedReader().use { it.readText() }
            content
        } catch (e: Exception) {
            android.util.Log.e("WebDAV", "Failed to get key fingerprint: ${e.message}")
            null
        }
    }

    override suspend fun saveKeyFingerprint(fingerprint: String): Boolean = withContext(Dispatchers.IO) {
        try {
            val sardine = getSardine()
            val cfg = getConfig()
            val path = "${cfg.url}${cfg.syncPath}/.encryption-key-fingerprint"

            sardine.put(path, fingerprint.toByteArray(), "text/plain")
            true
        } catch (e: Exception) {
            android.util.Log.e("WebDAV", "Failed to save key fingerprint: ${e.message}")
            false
        }
    }

    override suspend fun verifyKeyFingerprint(localFingerprint: String): KeyFingerprintResult = withContext(Dispatchers.IO) {
        val remoteFingerprint = getKeyFingerprint()

        if (remoteFingerprint == null) {
            // 远端没有指纹，检查是否有加密数据
            // 如果有加密数据但没有指纹，说明是旧版本数据或指纹丢失，应该报错
            val hasData = hasData()
            if (hasData) {
                // 远端有数据但没有指纹，可能是密钥不匹配
                return@withContext KeyFingerprintResult(valid = false, remoteFingerprint = null)
            }
            // 远端没有数据，这是真正的首次同步，保存本地指纹
            saveKeyFingerprint(localFingerprint)
            return@withContext KeyFingerprintResult(valid = true, remoteFingerprint = null)
        }

        // 验证指纹是否匹配
        val valid = remoteFingerprint == localFingerprint
        KeyFingerprintResult(valid = valid, remoteFingerprint = remoteFingerprint)
    }

    /**
     * 记录变更到变更日志 (与桌面端保持一致)
     *
     * 对应桌面端 src/core/sync/WebDAVAdapter.ts 中的 recordChange 方法
     */
    private suspend fun recordChange(item: ItemEntity) = withContext(Dispatchers.IO) {
        try {
            val change = RemoteChange(
                changeId = System.currentTimeMillis(),
                itemId = item.id,
                type = item.type,
                updatedTime = item.updatedTime,
                deletedTime = item.deletedTime,
                contentHash = item.contentHash
            )

            val changePath = "${getChangesPath()}/${change.changeId}.json"
            val content = json.encodeToString(change)

            val sardine = getSardine()
            sardine.put(changePath, content.toByteArray(), "application/json")

            android.util.Log.d("WebDAV", "Recorded change: ${change.changeId} for item ${item.id}")
        } catch (e: Exception) {
            android.util.Log.e("WebDAV", "Failed to record change for item ${item.id}: ${e.message}")
            // 不抛出异常，避免影响主流程
        }
    }

    /**
     * 从items目录扫描变更 (向后兼容旧版本)
     *
     * 用于首次同步或从旧版本升级时的回退逻辑
     */
    private suspend fun listChangesFromItems(cursor: String?, limit: Int): ChangeListResult = withContext(Dispatchers.IO) {
        try {
            val sardine = getSardine()
            val itemsPath = getItemsPath()

            if (!sardine.exists(itemsPath)) {
                android.util.Log.d("WebDAV", "Items directory does not exist")
                return@withContext ChangeListResult(emptyList(), null, false)
            }

            // 列出所有项目文件
            val resources = sardine.list(itemsPath)

            // 解析游标 (时间戳格式，用于向后兼容)
            val cursorTime = cursor?.toLongOrNull() ?: 0L
            val isFirstSync = cursorTime == 0L

            // 过滤出需要同步的文件
            val filesToSync = resources
                .filter { !it.isDirectory && it.name.endsWith(".json") }
                .filter { resource ->
                    val modified = resource.modified?.time ?: System.currentTimeMillis()
                    isFirstSync || modified >= cursorTime
                }

            android.util.Log.d("WebDAV", "[Fallback] Found ${filesToSync.size} files to sync (total: ${resources.size})")

            // 批量读取文件内容并转换为RemoteChange格式
            val changes = mutableListOf<RemoteChange>()
            for (resource in filesToSync) {
                val id = resource.name.removeSuffix(".json")
                val modified = resource.modified?.time ?: System.currentTimeMillis()

                try {
                    val item = getItem(id)
                    if (item != null) {
                        // 转换为新的RemoteChange格式
                        changes.add(RemoteChange(
                            changeId = modified,
                            itemId = item.id,
                            type = item.type,
                            updatedTime = item.updatedTime,
                            deletedTime = item.deletedTime,
                            contentHash = item.contentHash
                        ))
                    }
                } catch (e: Exception) {
                    android.util.Log.e("WebDAV", "[Fallback] Failed to get item $id: ${e.message}")
                }
            }

            // 按时间排序
            val sortedChanges = changes.sortedBy { it.changeId }
            val nextCursor = sortedChanges.lastOrNull()?.let {
                (it.changeId + 1).toString()
            }

            android.util.Log.d("WebDAV", "[Fallback] Loaded ${changes.size} items")

            ChangeListResult(
                changes = sortedChanges,
                nextCursor = nextCursor,
                hasMore = false  // 一次性返回所有
            )
        } catch (e: Exception) {
            android.util.Log.e("WebDAV", "[Fallback] Failed to list changes from items: ${e.message}")
            e.printStackTrace()
            ChangeListResult(emptyList(), null, false)
        }
    }
}

/**
 * 工作区元数据 - 与桌面端 workspace.json 格式一致
 */
@kotlinx.serialization.Serializable
private data class WorkspaceMeta(
    val version: String = "1.0",
    val capabilities: List<String> = listOf("items", "resources", "changes"),
    val last_sync_time: Long? = null,
    val key_identifier: String? = null
)

package com.mucheng.notes.presentation.viewmodel

import android.content.Context
import android.content.SharedPreferences
import androidx.lifecycle.ViewModel
import androidx.lifecycle.viewModelScope
import com.mucheng.notes.data.local.entity.ItemEntity
import com.mucheng.notes.domain.model.ItemType
import com.mucheng.notes.domain.model.SyncStatus
import com.mucheng.notes.domain.model.payload.ExcelNotePayload
import com.mucheng.notes.domain.model.payload.FolderPayload
import com.mucheng.notes.domain.model.payload.NotePayload
import com.mucheng.notes.domain.repository.ItemRepository
import com.mucheng.notes.domain.repository.SyncRepository
import com.mucheng.notes.security.CryptoEngine
import com.mucheng.notes.security.SecureSyncStorage
import dagger.hilt.android.lifecycle.HiltViewModel
import dagger.hilt.android.qualifiers.ApplicationContext
import kotlinx.coroutines.flow.MutableStateFlow
import kotlinx.coroutines.flow.SharingStarted
import kotlinx.coroutines.flow.StateFlow
import kotlinx.coroutines.flow.asStateFlow
import kotlinx.coroutines.flow.map
import kotlinx.coroutines.flow.stateIn
import kotlinx.coroutines.launch
