 */
@OptIn(ExperimentalMaterial3Api::class)
@Composable
fun SecuritySettingsScreen(
    navController: NavController,
    viewModel: SettingsViewModel
) {
    val uiState by viewModel.uiState.collectAsState()
    val snackbarHostState = remember { SnackbarHostState() }
    val context = LocalContext.current
    val scope = rememberCoroutineScope()
    var showLockTimeoutMenu by remember { mutableStateOf(false) }

    LaunchedEffect(uiState.message) {
        uiState.message?.let {
            snackbarHostState.showSnackbar(it)
            viewModel.clearMessage()
        }
    }

    // 处理应用锁生物识别启用
    fun handleBiometricToggle(enabled: Boolean) {
        if (enabled) {
            val activity = context as? FragmentActivity
            if (activity != null) {
                viewModel.authenticateBiometricAndEnable(activity) { success, message ->
                    message?.let {
                        scope.launch { snackbarHostState.showSnackbar(it) }
                    }
                }
            } else {
                scope.launch { snackbarHostState.showSnackbar("无法获取 Activity 上下文") }
            }
        } else {
            viewModel.setBiometricEnabled(false)
        }
    }

    // 处理密码库生物识别启用
    fun handleVaultBiometricToggle(enabled: Boolean) {
        if (enabled) {
            val activity = context as? FragmentActivity
            if (activity != null) {
                viewModel.authenticateVaultBiometricAndEnable(activity) { success, message ->
                    message?.let {
                        scope.launch { snackbarHostState.showSnackbar(it) }
                    }
                }
            } else {
                scope.launch { snackbarHostState.showSnackbar("无法获取 Activity 上下文") }
            }
        } else {
            viewModel.setVaultBiometricEnabled(false)
        }
    }

    Scaffold(
        topBar = {
            TopAppBar(
                title = { Text(stringResource(R.string.settings_security)) },
                navigationIcon = {
                    IconButton(onClick = { navController.popBackStack() }) {
                        Icon(Icons.AutoMirrored.Filled.ArrowBack, contentDescription = "返回")
                    }
                }
            )
        },
        snackbarHost = { SnackbarHost(snackbarHostState) }
    ) { paddingValues ->
        if (!uiState.isInitialized) {
            Box(
                modifier = Modifier.fillMaxSize().padding(paddingValues),
                contentAlignment = Alignment.Center
            ) {
                CircularProgressIndicator()
            }
            return@Scaffold
        }

        Column(
            modifier = Modifier
                .fillMaxSize()
                .padding(paddingValues)
                .verticalScroll(rememberScrollState())
                .padding(16.dp)
        ) {
            // ========== 应用锁定部分 ==========
            Text(
                "应用锁定",
                style = MaterialTheme.typography.titleMedium,
                color = MaterialTheme.colorScheme.primary
            )
            Text(
                "启用后每次打开应用需要验证身份",
                style = MaterialTheme.typography.bodySmall,
                color = MaterialTheme.colorScheme.outline
            )
            Spacer(modifier = Modifier.height(16.dp))

            SettingsSwitch(
                title = "启用应用锁",
                checked = uiState.appLockEnabled,
                onCheckedChange = { viewModel.setAppLockEnabled(it) }
            )

            if (uiState.appLockEnabled) {
                Spacer(modifier = Modifier.height(16.dp))

                // 锁定方式
                Row(
                    modifier = Modifier.fillMaxWidth().padding(vertical = 8.dp),
                    horizontalArrangement = Arrangement.SpaceBetween,
                    verticalAlignment = Alignment.CenterVertically
                ) {
                    Text("锁定方式", style = MaterialTheme.typography.bodyLarge)
                    Text(
                        when (uiState.lockType) {
                            LockType.PIN -> "PIN 码"
                            LockType.PATTERN -> "图案"
                            LockType.BIOMETRIC -> "生物识别"
                            LockType.NONE -> "未设置"
                        },
                        style = MaterialTheme.typography.bodyMedium,
                        color = MaterialTheme.colorScheme.primary
                    )
                }

                Spacer(modifier = Modifier.height(8.dp))

                // 锁定超时
                ExposedDropdownMenuBox(
                    expanded = showLockTimeoutMenu,
                    onExpandedChange = { showLockTimeoutMenu = it }
                ) {
                    OutlinedTextField(
                        value = uiState.lockTimeout.label,
                        onValueChange = {},
                        readOnly = true,
                        label = { Text("自动锁定时间") },
                        trailingIcon = { ExposedDropdownMenuDefaults.TrailingIcon(expanded = showLockTimeoutMenu) },
                        modifier = Modifier.fillMaxWidth().menuAnchor()
                    )
                    ExposedDropdownMenu(
                        expanded = showLockTimeoutMenu,
                        onDismissRequest = { showLockTimeoutMenu = false }
                    ) {
                        LockTimeout.entries.forEach { timeout ->
                            DropdownMenuItem(
                                text = { Text(timeout.label) },
                                onClick = {
                                    viewModel.setLockTimeout(timeout)
                                    showLockTimeoutMenu = false
                                }
                            )
                        }
                    }
                }

                Spacer(modifier = Modifier.height(16.dp))

                // 生物识别
                if (uiState.biometricAvailable) {
                    SettingsSwitch(
                        title = "使用生物识别",
                        subtitle = "使用指纹或面部识别解锁应用",
                        checked = uiState.biometricEnabled,
                        onCheckedChange = { handleBiometricToggle(it) }
                    )
                    Spacer(modifier = Modifier.height(16.dp))
                }

                // 修改/重设 PIN 按钮
                Row(horizontalArrangement = Arrangement.spacedBy(8.dp)) {
                    OutlinedButton(onClick = { viewModel.showChangePinDialog() }) {
                        Text(if (uiState.lockType == LockType.NONE) "设置 PIN" else "修改 PIN")
                    }
                    if (uiState.lockType != LockType.NONE) {
                        OutlinedButton(
                            onClick = { viewModel.setAppLockEnabled(false) },
                            colors = ButtonDefaults.outlinedButtonColors(
                                contentColor = MaterialTheme.colorScheme.error
                            )
                        ) {
                            Text("移除锁定")
                        }
                    }
                }
            }

            Spacer(modifier = Modifier.height(32.dp))
            HorizontalDivider()
            Spacer(modifier = Modifier.height(24.dp))

            // ========== 密码库锁定部分 ==========
            Text(
                "密码库锁定",
                style = MaterialTheme.typography.titleMedium,
                color = MaterialTheme.colorScheme.primary
            )
            Text(
                "为密码库设置独立密码，每次访问密码库需要验证",
                style = MaterialTheme.typography.bodySmall,
                color = MaterialTheme.colorScheme.outline
            )
            Spacer(modifier = Modifier.height(16.dp))

            // 启用密码库锁定
            SettingsSwitch(
                title = "启用密码库锁定",
                subtitle = "访问密码库时需要验证密码",
                checked = uiState.vaultLockEnabled,
                onCheckedChange = { viewModel.setVaultLockEnabled(it) }
            )

            Spacer(modifier = Modifier.height(16.dp))

            // 密码库密码状态
            Row(
                modifier = Modifier.fillMaxWidth().padding(vertical = 8.dp),
                horizontalArrangement = Arrangement.SpaceBetween,
                verticalAlignment = Alignment.CenterVertically
            ) {
                Text("密码库密码", style = MaterialTheme.typography.bodyLarge)
                if (uiState.vaultPasswordSet) {
                    Row(verticalAlignment = Alignment.CenterVertically) {
                        Icon(
                            Icons.Default.CheckCircle,
                            contentDescription = null,
                            modifier = Modifier.size(16.dp),
                            tint = MaterialTheme.colorScheme.primary
                        )
                        Spacer(modifier = Modifier.width(4.dp))
                        Text(
                            "已设置",
                            style = MaterialTheme.typography.bodySmall,
                            color = MaterialTheme.colorScheme.primary
                        )
                    }
                } else {
                    Text(
                        "未设置",
                        style = MaterialTheme.typography.bodySmall,
                        color = MaterialTheme.colorScheme.outline
                    )
                }
            }

            Spacer(modifier = Modifier.height(8.dp))

            // 密码库密码操作按钮
            Row(horizontalArrangement = Arrangement.spacedBy(8.dp)) {
                OutlinedButton(onClick = { viewModel.showVaultPasswordDialog() }) {
                    Icon(
                        if (uiState.vaultPasswordSet) Icons.Default.Edit else Icons.Default.Lock,
                        contentDescription = null,
                        modifier = Modifier.size(18.dp)
                    )
                    Spacer(modifier = Modifier.width(4.dp))
                    Text(if (uiState.vaultPasswordSet) "修改密码" else "设置密码")
                }
                if (uiState.vaultPasswordSet) {
                    OutlinedButton(
                        onClick = { viewModel.removeVaultPassword() },
                        colors = ButtonDefaults.outlinedButtonColors(
                            contentColor = MaterialTheme.colorScheme.error
                        )
                    ) {
                        Icon(
                            Icons.Default.Delete,
                            contentDescription = null,
                            modifier = Modifier.size(18.dp)
                        )
                        Spacer(modifier = Modifier.width(4.dp))
                        Text("移除密码")
                    }
                }
            }

            // 密码库生物识别（仅当密码已设置时显示）
            if (uiState.vaultPasswordSet && uiState.biometricAvailable) {
                Spacer(modifier = Modifier.height(16.dp))
                SettingsSwitch(
                    title = "使用生物识别",
                    subtitle = "使用指纹或面部识别解锁密码库",
                    checked = uiState.vaultBiometricEnabled,
                    onCheckedChange = { handleVaultBiometricToggle(it) }
                )
            }

            // 提示信息
            if (uiState.vaultLockEnabled && uiState.vaultPasswordSet) {
                Spacer(modifier = Modifier.height(16.dp))
                Card(
                    modifier = Modifier.fillMaxWidth(),
                    colors = CardDefaults.cardColors(
                        containerColor = MaterialTheme.colorScheme.primaryContainer.copy(alpha = 0.3f)
                    )
                ) {
                    Row(
                        modifier = Modifier.padding(12.dp),
                        verticalAlignment = Alignment.Top
                    ) {
                        Icon(
                            Icons.Default.Info,
                            contentDescription = null,
                            tint = MaterialTheme.colorScheme.primary,
                            modifier = Modifier.size(20.dp)
                        )
                        Spacer(modifier = Modifier.width(8.dp))
                        Text(
                            "密码库锁定已启用，每次进入密码库页面都需要验证密码" +
                                    if (uiState.vaultBiometricEnabled) "或生物识别" else "",
                            style = MaterialTheme.typography.bodySmall,
                            color = MaterialTheme.colorScheme.onSurface
                        )
                    }
                }
            }
        }
    }

    // PIN 设置对话框
    if (uiState.showPinDialog) {
        PinSetupDialog(
            onDismiss = { viewModel.dismissPinDialog() },
            onConfirm = { pin -> viewModel.setPin(pin) }
        )
    }

    // 密码库密码设置对话框
    if (uiState.showVaultPasswordDialog) {
        VaultPasswordDialog(
            mode = uiState.vaultPasswordDialogMode,
            onDismiss = { viewModel.dismissVaultPasswordDialog() },
            onConfirm = { password -> viewModel.setVaultPassword(password) },
            onVerify = { password -> viewModel.verifyVaultPassword(password) }
        )
    }
}

@Composable
private fun SettingsSwitch(
    title: String,
    subtitle: String? = null,
    checked: Boolean,
    onCheckedChange: (Boolean) -> Unit,
    enabled: Boolean = true
) {
    Row(
        modifier = Modifier
            .fillMaxWidth()
            .clickable(enabled = enabled) { onCheckedChange(!checked) }
            .padding(vertical = 8.dp),
        verticalAlignment = Alignment.CenterVertically
    ) {
        Column(modifier = Modifier.weight(1f)) {
            Text(
                title,
                style = MaterialTheme.typography.bodyLarge,
                color = if (enabled) MaterialTheme.colorScheme.onSurface else MaterialTheme.colorScheme.outline
            )
            if (subtitle != null) {
                Text(
                    subtitle,
                    style = MaterialTheme.typography.bodySmall,
                    color = MaterialTheme.colorScheme.outline
                )
            }
        }
        Switch(checked = checked, onCheckedChange = onCheckedChange, enabled = enabled)
    }
}

@Composable
private fun PinSetupDialog(
    onDismiss: () -> Unit,
    onConfirm: (String) -> Unit
) {
    var pin by remember { mutableStateOf("") }
    var confirmPin by remember { mutableStateOf("") }
    var error by remember { mutableStateOf<String?>(null) }

    AlertDialog(
        onDismissRequest = onDismiss,
        title = { Text("设置 PIN") },
        text = {
            Column {
                OutlinedTextField(
                    value = pin,
                    onValueChange = { if (it.length <= 6 && it.all { c -> c.isDigit() }) pin = it },
                    label = { Text("输入 PIN (4-6 位数字)") },
                    keyboardOptions = KeyboardOptions(keyboardType = KeyboardType.NumberPassword),
                    visualTransformation = PasswordVisualTransformation(),
                    singleLine = true,
                    modifier = Modifier.fillMaxWidth()
                )
                Spacer(modifier = Modifier.height(8.dp))
                OutlinedTextField(
                    value = confirmPin,
                    onValueChange = { if (it.length <= 6 && it.all { c -> c.isDigit() }) confirmPin = it },
                    label = { Text(stringResource(R.string.confirm_password)) },
                    keyboardOptions = KeyboardOptions(keyboardType = KeyboardType.NumberPassword),
                    visualTransformation = PasswordVisualTransformation(),
                    singleLine = true,
                    modifier = Modifier.fillMaxWidth()
                )
                error?.let {
                    Spacer(modifier = Modifier.height(8.dp))
                    Text(it, color = MaterialTheme.colorScheme.error, style = MaterialTheme.typography.bodySmall)
                }
            }
        },
        confirmButton = {
            TextButton(onClick = {
                when {
                    pin.length < 4 -> error = "PIN 至少 4 位"
                    pin != confirmPin -> error = "两次输入不一致"
                    else -> onConfirm(pin)
                }
            }) {
                Text(stringResource(R.string.confirm))
            }
        },
        dismissButton = {
            TextButton(onClick = onDismiss) { Text(stringResource(R.string.cancel)) }
        }
    )
}

/**
 * 密码库密码设置对话框
 */
@Composable
private fun VaultPasswordDialog(
    mode: String, // "set" | "change"
    onDismiss: () -> Unit,
    onConfirm: (String) -> Unit,
    onVerify: (String) -> Boolean
) {
    var currentPassword by remember { mutableStateOf("") }
    var newPassword by remember { mutableStateOf("") }
    var confirmPassword by remember { mutableStateOf("") }
    var error by remember { mutableStateOf<String?>(null) }
    var showCurrentPassword by remember { mutableStateOf(false) }
    var showNewPassword by remember { mutableStateOf(false) }
    var showConfirmPassword by remember { mutableStateOf(false) }

    val isChangeMode = mode == "change"

    AlertDialog(
        onDismissRequest = onDismiss,
        title = { Text(if (isChangeMode) "修改密码库密码" else "设置密码库密码") },
        text = {
            Column(verticalArrangement = Arrangement.spacedBy(12.dp)) {
                // 修改模式需要先验证当前密码
                if (isChangeMode) {
                    OutlinedTextField(
                        value = currentPassword,
                        onValueChange = { currentPassword = it; error = null },
                        label = { Text("当前密码") },
                        singleLine = true,
                        visualTransformation = if (showCurrentPassword) VisualTransformation.None else PasswordVisualTransformation(),
                        trailingIcon = {
                            IconButton(onClick = { showCurrentPassword = !showCurrentPassword }) {
                                Icon(
                                    if (showCurrentPassword) Icons.Default.VisibilityOff else Icons.Default.Visibility,
                                    contentDescription = null
                                )
                            }
                        },
                        modifier = Modifier.fillMaxWidth()
                    )
                }

                OutlinedTextField(
                    value = newPassword,
                    onValueChange = { newPassword = it; error = null },
                    label = { Text(if (isChangeMode) "新密码" else "密码") },
                    supportingText = { Text("至少 4 个字符") },
                    singleLine = true,
                    visualTransformation = if (showNewPassword) VisualTransformation.None else PasswordVisualTransformation(),
                    trailingIcon = {
                        IconButton(onClick = { showNewPassword = !showNewPassword }) {
                            Icon(
                                if (showNewPassword) Icons.Default.VisibilityOff else Icons.Default.Visibility,
                                contentDescription = null
                            )
                        }
                    },
                    modifier = Modifier.fillMaxWidth()
                )

                OutlinedTextField(
                    value = confirmPassword,
                    onValueChange = { confirmPassword = it; error = null },
                    label = { Text("确认密码") },
                    singleLine = true,
                    visualTransformation = if (showConfirmPassword) VisualTransformation.None else PasswordVisualTransformation(),
                    trailingIcon = {
                        IconButton(onClick = { showConfirmPassword = !showConfirmPassword }) {
                            Icon(
                                if (showConfirmPassword) Icons.Default.VisibilityOff else Icons.Default.Visibility,
                                contentDescription = null
                            )
                        }
                    },
                    modifier = Modifier.fillMaxWidth()
                )

                error?.let {
                    Text(it, color = MaterialTheme.colorScheme.error, style = MaterialTheme.typography.bodySmall)
                }
            }
        },
        confirmButton = {
            TextButton(onClick = {
                when {
                    isChangeMode && currentPassword.isBlank() -> error = "请输入当前密码"
                    isChangeMode && !onVerify(currentPassword) -> error = "当前密码错误"
                    newPassword.length < 4 -> error = "密码至少 4 个字符"
                    newPassword != confirmPassword -> error = "两次输入的密码不一致"
                    else -> onConfirm(newPassword)
                }
            }) {
                Text("确定")
            }
        },
        dismissButton = {
            TextButton(onClick = onDismiss) { Text("取消") }
        }
    )
}

import React, { useState, useCallback, useEffect } from 'react';
import { Input, Button, Checkbox, Empty, Modal, message, Tooltip, Dropdown, Tag, DatePicker, Switch, notification } from 'antd';
import {
  PlusOutlined, DeleteOutlined, EditOutlined, 
  CheckOutlined, ClockCircleOutlined, MenuOutlined,
  FireOutlined, StarOutlined, CoffeeOutlined, BellOutlined,
} from '@ant-design/icons';
import { useTodos, Todo } from '../hooks/useTodos';
import { TodoQuadrant } from '@shared/types';
import dayjs from 'dayjs';

const { TextArea } = Input;

// 象限配置
const QUADRANT_CONFIG: Record<TodoQuadrant, { title: string; icon: React.ReactNode; color: string; bgColor: string }> = {
  'urgent-important': {
    title: '紧急且重要',
    icon: <FireOutlined />,
    color: '#ff4d4f',
    bgColor: '#fff2f0',
  },
  'not-urgent-important': {
    title: '重要不紧急',
    icon: <StarOutlined />,
    color: '#faad14',
    bgColor: '#fffbe6',
  },
  'urgent-not-important': {
    title: '紧急不重要',
    icon: <ClockCircleOutlined />,
    color: '#1890ff',
    bgColor: '#e6f7ff',
  },
  'not-urgent-not-important': {
    title: '不紧急不重要',
    icon: <CoffeeOutlined />,
    color: '#52c41a',
    bgColor: '#f6ffed',
  },
};

interface TodoItemProps {
  todo: Todo;
  onToggle: (id: string) => void;
  onEdit: (todo: Todo) => void;
  onDelete: (id: string) => void;
  onDragStart: (e: React.DragEvent, todo: Todo) => void;
}

const TodoItem: React.FC<TodoItemProps> = ({ todo, onToggle, onEdit, onDelete, onDragStart }) => {
  return (
    <div
      draggable
      onDragStart={(e) => onDragStart(e, todo)}
      className="todo-item"
      style={{
        padding: '8px 12px',
        borderRadius: 6,
        marginBottom: 8,
        cursor: 'grab',
        display: 'flex',
        alignItems: 'flex-start',
        gap: 8,
        opacity: todo.completed ? 0.6 : 1,
      }}
    >
      <Checkbox
        checked={todo.completed}
        onChange={() => onToggle(todo.id)}
        style={{ marginTop: 2 }}
      />
      <div style={{ flex: 1, minWidth: 0 }}>
        <div style={{
          textDecoration: todo.completed ? 'line-through' : 'none',
          color: todo.completed ? '#999' : '#333',
          fontSize: 13,
          wordBreak: 'break-word',
        }}>
          {todo.title}
        </div>
        {todo.description && (
          <div style={{ fontSize: 12, color: '#888', marginTop: 4 }}>
            {todo.description}
          </div>
        )}
        {todo.dueDate && (
          <div style={{ fontSize: 11, color: '#999', marginTop: 4, display: 'flex', alignItems: 'center', gap: 8 }}>
            <span>
              <ClockCircleOutlined style={{ marginRight: 4 }} />
              {new Date(todo.dueDate).toLocaleString()}
            </span>
            {todo.reminderEnabled && todo.reminderTime && (
              <span style={{ color: '#1890ff' }}>
                <BellOutlined style={{ marginRight: 2 }} />
                {new Date(todo.reminderTime).toLocaleString()}
              </span>
            )}
          </div>
        )}
      </div>
      <Dropdown
        menu={{
          items: [
            { key: 'edit', icon: <EditOutlined />, label: '编辑', onClick: () => onEdit(todo) },
            { type: 'divider' },
            { key: 'delete', icon: <DeleteOutlined />, label: '删除', danger: true, onClick: () => onDelete(todo.id) },
          ],
        }}
        trigger={['click']}
      >
        <Button type="text" size="small" icon={<MenuOutlined />} />
      </Dropdown>
    </div>
  );
};

interface QuadrantBoxProps {
  quadrant: TodoQuadrant;
  todos: Todo[];
  onToggle: (id: string) => void;
  onEdit: (todo: Todo) => void;
  onDelete: (id: string) => void;
  onAdd: (quadrant: TodoQuadrant) => void;
  onDragStart: (e: React.DragEvent, todo: Todo) => void;
  onDrop: (e: React.DragEvent, quadrant: TodoQuadrant) => void;
}

const QuadrantBox: React.FC<QuadrantBoxProps> = ({
  quadrant, todos, onToggle, onEdit, onDelete, onAdd, onDragStart, onDrop,
}) => {
  const [isDragOver, setIsDragOver] = useState(false);
  const config = QUADRANT_CONFIG[quadrant];

  const handleDragOver = (e: React.DragEvent) => {
    e.preventDefault();
    setIsDragOver(true);
  };

  const handleDragLeave = () => {
    setIsDragOver(false);
  };

  const handleDrop = (e: React.DragEvent) => {
    e.preventDefault();
    setIsDragOver(false);
    onDrop(e, quadrant);
  };

  const activeTodos = todos.filter(t => !t.completed);
  const completedTodos = todos.filter(t => t.completed);

  return (
    <div
      onDragOver={handleDragOver}
      onDragLeave={handleDragLeave}
      onDrop={handleDrop}
      className={`quadrant-box quadrant-${quadrant}`}
      style={{
        flex: 1,
        minWidth: 0,
        minHeight: 200,
        borderRadius: 8,
        border: `2px ${isDragOver ? 'dashed' : 'solid'} ${isDragOver ? config.color : 'var(--border-color, #f0f0f0)'}`,
        display: 'flex',
        flexDirection: 'column',
        transition: 'all 0.2s',
      }}
    >
      {/* 标题栏 */}
      <div className={`quadrant-header quadrant-header-${quadrant}`} style={{
        padding: '10px 12px',
        borderBottom: '1px solid var(--border-color, #f0f0f0)',
        display: 'flex',
        alignItems: 'center',
        justifyContent: 'space-between',
        borderRadius: '6px 6px 0 0',
      }}>
        <div style={{ display: 'flex', alignItems: 'center', gap: 6 }}>
          <span style={{ color: config.color }}>{config.icon}</span>
          <span style={{ fontWeight: 500, fontSize: 13 }}>{config.title}</span>
          <Tag style={{ marginLeft: 4 }}>{activeTodos.length}</Tag>
        </div>
        <Tooltip title="添加待办">
          <Button
            type="text"
            size="small"
            icon={<PlusOutlined />}
            onClick={() => onAdd(quadrant)}
          />
        </Tooltip>
      </div>

      {/* 待办列表 */}
      <div style={{ flex: 1, overflow: 'auto', padding: 8 }}>
        {activeTodos.length === 0 && completedTodos.length === 0 ? (
          <Empty
            image={Empty.PRESENTED_IMAGE_SIMPLE}
            description="暂无待办"
            style={{ marginTop: 20 }}
          />
        ) : (
          <>
            {activeTodos.map(todo => (
              <TodoItem
                key={todo.id}
                todo={todo}
                onToggle={onToggle}
                onEdit={onEdit}
                onDelete={onDelete}
                onDragStart={onDragStart}
              />
            ))}
            {completedTodos.length > 0 && (
              <>
                <div style={{ fontSize: 11, color: '#999', margin: '12px 0 8px', paddingLeft: 4 }}>
                  已完成 ({completedTodos.length})
                </div>
                {completedTodos.map(todo => (
                  <TodoItem
                    key={todo.id}
                    todo={todo}
                    onToggle={onToggle}
                    onEdit={onEdit}
                    onDelete={onDelete}
                    onDragStart={onDragStart}
                  />
                ))}
              </>
            )}
          </>
        )}
      </div>
    </div>
  );
};

const TodoPanel: React.FC = () => {
  const { todos, todosByQuadrant, createTodo, updateTodo, deleteTodo, toggleComplete, moveTodo } = useTodos();

  const [addModalOpen, setAddModalOpen] = useState(false);
  const [addQuadrant, setAddQuadrant] = useState<TodoQuadrant>('urgent-important');
  const [newTitle, setNewTitle] = useState('');
  const [newDescription, setNewDescription] = useState('');
  const [newDueDate, setNewDueDate] = useState<dayjs.Dayjs | null>(null);
  const [newReminderTime, setNewReminderTime] = useState<dayjs.Dayjs | null>(null);
  const [newReminderEnabled, setNewReminderEnabled] = useState(false);

  const [editModalOpen, setEditModalOpen] = useState(false);
  const [editingTodo, setEditingTodo] = useState<Todo | null>(null);
  const [editTitle, setEditTitle] = useState('');
  const [editDescription, setEditDescription] = useState('');
  const [editDueDate, setEditDueDate] = useState<dayjs.Dayjs | null>(null);
  const [editReminderTime, setEditReminderTime] = useState<dayjs.Dayjs | null>(null);
  const [editReminderEnabled, setEditReminderEnabled] = useState(false);

  const [draggingTodo, setDraggingTodo] = useState<Todo | null>(null);

  // 检查提醒
  useEffect(() => {
    const checkReminders = () => {
      const now = Date.now();
      todos.forEach(todo => {
        if (todo.reminderEnabled && todo.reminderTime && !todo.completed) {
          const diff = todo.reminderTime - now;
          // 提前1分钟内提醒
          if (diff > 0 && diff < 60000) {
            notification.info({
              message: '待办提醒',
              description: todo.title,
              icon: <BellOutlined style={{ color: '#1890ff' }} />,
              duration: 10,
            });
            // 关闭提醒避免重复
            updateTodo(todo.id, { reminder_enabled: false });
          }
        }
      });
    };

    const interval = setInterval(checkReminders, 30000);
    checkReminders();
    return () => clearInterval(interval);
  }, [todos, updateTodo]);

  const handleAdd = (quadrant: TodoQuadrant) => {
    setAddQuadrant(quadrant);
    setNewTitle('');
    setNewDescription('');
    setNewDueDate(null);
    setNewReminderTime(null);
    setNewReminderEnabled(false);
    setAddModalOpen(true);
  };

  const handleCreateTodo = async () => {
    if (!newTitle.trim()) {
      message.warning('请输入待办标题');
      return;
    }
    await createTodo(
      newTitle.trim(), 
      addQuadrant, 
      newDescription.trim(),
      newDueDate?.valueOf() || null,
      newReminderEnabled && newReminderTime ? newReminderTime.valueOf() : null
    );
    setAddModalOpen(false);
    message.success('待办已创建');
  };

  const handleEdit = (todo: Todo) => {
    setEditingTodo(todo);
    setEditTitle(todo.title);
    setEditDescription(todo.description);
    setEditDueDate(todo.dueDate ? dayjs(todo.dueDate) : null);
    setEditReminderTime(todo.reminderTime ? dayjs(todo.reminderTime) : null);
    setEditReminderEnabled(todo.reminderEnabled);
    setEditModalOpen(true);
  };

  const handleUpdateTodo = async () => {
    if (!editingTodo || !editTitle.trim()) {
      message.warning('请输入待办标题');
      return;
    }
    await updateTodo(editingTodo.id, {
      title: editTitle.trim(),
      description: editDescription.trim(),
      due_date: editDueDate?.valueOf() || null,
      reminder_time: editReminderEnabled && editReminderTime ? editReminderTime.valueOf() : null,
      reminder_enabled: editReminderEnabled && editReminderTime !== null,
    });
    setEditModalOpen(false);
    setEditingTodo(null);
    message.success('待办已更新');
  };

  const handleDelete = async (id: string) => {
    Modal.confirm({
      title: '删除待办',
      content: '确定要删除这个待办吗？',
      okText: '删除',
      okType: 'danger',
      cancelText: '取消',
      onOk: async () => {
        await deleteTodo(id);
        message.success('待办已删除');
      },
    });
  };

  const handleDragStart = (e: React.DragEvent, todo: Todo) => {
    setDraggingTodo(todo);
    e.dataTransfer.effectAllowed = 'move';
  };

  const handleDrop = async (e: React.DragEvent, targetQuadrant: TodoQuadrant) => {
    if (!draggingTodo) return;

    if (draggingTodo.quadrant !== targetQuadrant) {
      // 获取目标象限的最大优先级
      const targetTodos = todosByQuadrant[targetQuadrant];
      const maxPriority = targetTodos.length > 0
        ? Math.max(...targetTodos.map(t => t.priority))
        : 0;

      await moveTodo(draggingTodo.id, targetQuadrant, maxPriority + 1);
      message.success('待办已移动');
    }
    setDraggingTodo(null);
  };

  return (
    <div style={{ height: '100%', display: 'flex', flexDirection: 'column' }} className="todo-panel">
      {/* 标题栏 */}
      <div className="todo-header" style={{
        padding: '12px 16px',
        borderBottom: '1px solid var(--border-color, #f0f0f0)',
        display: 'flex',
        alignItems: 'center',
        justifyContent: 'space-between',
      }}>
        <div style={{ display: 'flex', alignItems: 'center', gap: 8 }}>
          <CheckOutlined style={{ fontSize: 18, color: '#1890ff' }} />
          <span style={{ fontWeight: 500, fontSize: 15 }}>待办事项</span>
        </div>
        <Button
          type="primary"
          size="small"
          icon={<PlusOutlined />}
          onClick={() => handleAdd('urgent-important')}
        >
          新建待办
        </Button>
      </div>

      {/* 四象限区域 */}
      <div style={{ flex: 1, padding: 16, overflow: 'auto' }}>
        <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gridTemplateRows: '1fr 1fr', gap: 16, height: '100%', minHeight: 500 }}>
          <QuadrantBox
            quadrant="urgent-important"
            todos={todosByQuadrant['urgent-important']}
            onToggle={toggleComplete}
            onEdit={handleEdit}
            onDelete={handleDelete}
            onAdd={handleAdd}
            onDragStart={handleDragStart}
            onDrop={handleDrop}
          />
          <QuadrantBox
            quadrant="not-urgent-important"
            todos={todosByQuadrant['not-urgent-important']}
            onToggle={toggleComplete}
            onEdit={handleEdit}
            onDelete={handleDelete}
            onAdd={handleAdd}
            onDragStart={handleDragStart}
            onDrop={handleDrop}
          />
          <QuadrantBox
            quadrant="urgent-not-important"
            todos={todosByQuadrant['urgent-not-important']}
            onToggle={toggleComplete}
            onEdit={handleEdit}
            onDelete={handleDelete}
            onAdd={handleAdd}
            onDragStart={handleDragStart}
            onDrop={handleDrop}
          />
          <QuadrantBox
            quadrant="not-urgent-not-important"
            todos={todosByQuadrant['not-urgent-not-important']}
            onToggle={toggleComplete}
            onEdit={handleEdit}
            onDelete={handleDelete}
            onAdd={handleAdd}
            onDragStart={handleDragStart}
            onDrop={handleDrop}
          />
        </div>
      </div>

      {/* 新建待办弹窗 */}
      <Modal
        title={`新建待办 - ${QUADRANT_CONFIG[addQuadrant].title}`}
        open={addModalOpen}
        onOk={handleCreateTodo}
        onCancel={() => setAddModalOpen(false)}
        okText="创建"
        cancelText="取消"
      >
        <div style={{ marginBottom: 16 }}>
          <Input
            placeholder="待办标题"
            value={newTitle}
            onChange={e => setNewTitle(e.target.value)}
            autoFocus
          />
        </div>
        <div style={{ marginBottom: 16 }}>
          <TextArea
            placeholder="描述（可选）"
            value={newDescription}
            onChange={e => setNewDescription(e.target.value)}
            rows={2}
          />
        </div>
        <div style={{ marginBottom: 16 }}>
          <label style={{ display: 'block', marginBottom: 4, fontSize: 12, color: '#666' }}>截止时间</label>
          <DatePicker
            showTime
            value={newDueDate}
            onChange={setNewDueDate}
            placeholder="选择截止时间"
            style={{ width: '100%' }}
          />
        </div>
        <div style={{ display: 'flex', alignItems: 'center', gap: 12 }}>
          <Switch
            checked={newReminderEnabled}
            onChange={setNewReminderEnabled}
            size="small"
          />
          <span style={{ fontSize: 13 }}>启用提醒</span>
          {newReminderEnabled && (
            <DatePicker
              showTime
              value={newReminderTime}
              onChange={setNewReminderTime}
              placeholder="提醒时间"
              style={{ flex: 1 }}
            />
          )}
        </div>
      </Modal>

      {/* 编辑待办弹窗 */}
      <Modal
        title="编辑待办"
        open={editModalOpen}
        onOk={handleUpdateTodo}
        onCancel={() => { setEditModalOpen(false); setEditingTodo(null); }}
        okText="保存"
        cancelText="取消"
      >
        <div style={{ marginBottom: 16 }}>
          <Input
            placeholder="待办标题"
            value={editTitle}
            onChange={e => setEditTitle(e.target.value)}
            autoFocus
          />
        </div>
        <div style={{ marginBottom: 16 }}>
          <TextArea
            placeholder="描述（可选）"
            value={editDescription}
            onChange={e => setEditDescription(e.target.value)}
            rows={2}
          />
        </div>
        <div style={{ marginBottom: 16 }}>
          <label style={{ display: 'block', marginBottom: 4, fontSize: 12, color: '#666' }}>截止时间</label>
          <DatePicker
            showTime
            value={editDueDate}
            onChange={setEditDueDate}
            placeholder="选择截止时间"
            style={{ width: '100%' }}
          />
        </div>
        <div style={{ display: 'flex', alignItems: 'center', gap: 12 }}>
          <Switch
            checked={editReminderEnabled}
            onChange={setEditReminderEnabled}
            size="small"
          />
          <span style={{ fontSize: 13 }}>启用提醒</span>
          {editReminderEnabled && (
            <DatePicker
              showTime
              value={editReminderTime}
              onChange={setEditReminderTime}
              placeholder="提醒时间"
              style={{ flex: 1 }}
            />
          )}
        </div>
      </Modal>
    </div>
  );
};

export default TodoPanel;

/**
 * PDFPreview - PDF 预览组件
 * 基于 PDF.js 实现单页渲染、缩放控制和页面导航
 */

import React, { useEffect, useRef, useState, useCallback } from 'react';
import { Spin, Space, Button, InputNumber, Select, Input, message } from 'antd';
import {
  ZoomInOutlined,
  ZoomOutOutlined,
  LeftOutlined,
  RightOutlined,
  SearchOutlined,
} from '@ant-design/icons';
import * as pdfjsLib from 'pdfjs-dist';

// 设置本地 worker 路径
pdfjsLib.GlobalWorkerOptions.workerSrc = './pdfjs/pdf.worker.min.mjs';

// 配置标准字体和 CMap 路径（用于正确渲染文字和中文）
const STANDARD_FONT_DATA_URL = './pdfjs/standard_fonts/';
const CMAP_URL = './pdfjs/cmaps/';
const CMAP_PACKED = true;

// ============ 类型定义 ============

export interface PDFPreviewProps {
  pdfData: ArrayBuffer | string | null;
  currentPage?: number;
  zoom?: number;
  showControls?: boolean;
  showSearch?: boolean;
  onPageChange?: (page: number) => void;
  onTotalPagesChange?: (total: number) => void;
  onZoomChange?: (zoom: number) => void;
  style?: React.CSSProperties;
}

type ZoomMode = 'custom' | 'fit-width' | 'fit-page';

// ============ PDFPreview 组件 ============

const PDFPreview: React.FC<PDFPreviewProps> = ({
  pdfData,
  currentPage: externalPage,
  zoom: externalZoom,
  showControls = true,
  showSearch = true,
  onPageChange,
  onTotalPagesChange,
  onZoomChange,
  style,
}) => {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const containerRef = useRef<HTMLDivElement>(null);
  const pdfDocRef = useRef<pdfjsLib.PDFDocumentProxy | null>(null);

  const [loading, setLoading] = useState(false);
  const [totalPages, setTotalPages] = useState(0);
  const [currentPage, setCurrentPage] = useState(externalPage || 1);
  const [zoom, setZoom] = useState(externalZoom || 100);
  const [zoomMode, setZoomMode] = useState<ZoomMode>('custom');
  const [searchText, setSearchText] = useState('');
  const [searchResults, setSearchResults] = useState<number[]>([]);
  const [currentSearchIndex, setCurrentSearchIndex] = useState(0);
  const [rendering, setRendering] = useState(false);

  // 用于触发渲染的状态
  const [pdfLoaded, setPdfLoaded] = useState(0);

  // 加载 PDF 文档
  useEffect(() => {
    console.log('PDFPreview: pdfData changed', { 
      hasData: !!pdfData, 
      dataType: pdfData ? (typeof pdfData === 'string' ? 'string' : 'ArrayBuffer') : 'null',
      dataSize: pdfData ? (typeof pdfData === 'string' ? pdfData.length : pdfData.byteLength) : 0
    });

    if (!pdfData) {
      pdfDocRef.current = null;
      setTotalPages(0);
      setPdfLoaded(0);
      return;
    }

    const loadPDF = async () => {
      setLoading(true);
      setRendering(false); // 重置渲染状态

      try {
        // 先清理旧的 PDF 文档
        if (pdfDocRef.current) {
          pdfDocRef.current.destroy();
          pdfDocRef.current = null;
        }

        let loadingTask: pdfjsLib.PDFDocumentLoadingTask;

        if (typeof pdfData === 'string') {
          // URL 或 Base64
          if (pdfData.startsWith('data:')) {
            const base64 = pdfData.split(',')[1];
            const binary = atob(base64);
            const bytes = new Uint8Array(binary.length);
            for (let i = 0; i < binary.length; i++) {
              bytes[i] = binary.charCodeAt(i);
            }
            loadingTask = pdfjsLib.getDocument({ 
              data: bytes,
              standardFontDataUrl: STANDARD_FONT_DATA_URL,
              cMapUrl: CMAP_URL,
              cMapPacked: CMAP_PACKED,
            });
          } else {
            loadingTask = pdfjsLib.getDocument({
              url: pdfData,
              standardFontDataUrl: STANDARD_FONT_DATA_URL,
              cMapUrl: CMAP_URL,
              cMapPacked: CMAP_PACKED,
            });
          }
        } else {
          // ArrayBuffer - 复制以避免 detached 问题
          // pdfjs 会 transfer ArrayBuffer，导致原始 buffer 被 detached
          const bufferCopy = pdfData.slice(0);
          console.log('PDFPreview: Loading ArrayBuffer', { size: bufferCopy.byteLength });
          loadingTask = pdfjsLib.getDocument({ 
            data: bufferCopy,
            standardFontDataUrl: STANDARD_FONT_DATA_URL,
            cMapUrl: CMAP_URL,
            cMapPacked: CMAP_PACKED,
          });
        }

        const pdf = await loadingTask.promise;
        console.log('PDFPreview: PDF loaded', { numPages: pdf.numPages });
        pdfDocRef.current = pdf;
        setTotalPages(pdf.numPages);
        onTotalPagesChange?.(pdf.numPages);

        // 重置到第一页或保持当前页
        const newPage = currentPage > pdf.numPages ? 1 : currentPage;
        if (newPage !== currentPage) {
          setCurrentPage(newPage);
          onPageChange?.(newPage);
        }

        // 加载完成
        setLoading(false);
        // 触发渲染
        const loadedTime = Date.now();
        console.log('PDFPreview: Setting pdfLoaded to', loadedTime);
        setPdfLoaded(loadedTime);
      } catch (error) {
        console.error('PDFPreview: Failed to load PDF:', error);
        message.error('PDF 加载失败');
        setLoading(false);
      }
    };

    loadPDF();

    return () => {
      if (pdfDocRef.current) {
        pdfDocRef.current.destroy();
        pdfDocRef.current = null;
      }
    };
  }, [pdfData]);

  // 渲染当前页面
  const renderPage = useCallback(async () => {
    console.log('PDFPreview: renderPage called', { 
      hasPdfDoc: !!pdfDocRef.current, 
      hasCanvas: !!canvasRef.current,
      currentPage,
      rendering 
    });

    if (!pdfDocRef.current || !canvasRef.current) {
      console.log('PDFPreview: Missing pdfDoc or canvas');
      return;
    }

    setRendering(true);
    try {
      const page = await pdfDocRef.current.getPage(currentPage);
      const canvas = canvasRef.current;
      const context = canvas.getContext('2d');
      if (!context) {
        console.log('PDFPreview: Failed to get canvas context');
        setRendering(false);
        return;
      }

      // 计算缩放比例
      let scale = zoom / 100;

      if (zoomMode === 'fit-width' && containerRef.current) {
        const containerWidth = containerRef.current.clientWidth - 40;
        const viewport = page.getViewport({ scale: 1 });
        scale = containerWidth / viewport.width;
        const newZoom = Math.round(scale * 100);
        if (newZoom !== zoom) {
          setZoom(newZoom);
          onZoomChange?.(newZoom);
        }
      } else if (zoomMode === 'fit-page' && containerRef.current) {
        const containerWidth = containerRef.current.clientWidth - 40;
        const containerHeight = containerRef.current.clientHeight - 40;
        const viewport = page.getViewport({ scale: 1 });
        const scaleX = containerWidth / viewport.width;
        const scaleY = containerHeight / viewport.height;
        scale = Math.min(scaleX, scaleY);
        const newZoom = Math.round(scale * 100);
        if (newZoom !== zoom) {
          setZoom(newZoom);
          onZoomChange?.(newZoom);
        }
      }

      const viewport = page.getViewport({ scale });

      // 设置 canvas 尺寸
      const outputScale = window.devicePixelRatio || 1;
      canvas.width = Math.floor(viewport.width * outputScale);
      canvas.height = Math.floor(viewport.height * outputScale);
      canvas.style.width = `${Math.floor(viewport.width)}px`;
      canvas.style.height = `${Math.floor(viewport.height)}px`;

      console.log('PDFPreview: Rendering page', { 
        page: currentPage, 
        scale, 
        canvasWidth: canvas.width,
        canvasHeight: canvas.height,
        canvasStyleWidth: canvas.style.width,
        canvasStyleHeight: canvas.style.height,
        containerWidth: containerRef.current?.clientWidth,
        containerHeight: containerRef.current?.clientHeight,
      });

      // 清除之前的内容
      context.setTransform(1, 0, 0, 1, 0, 0);
      context.clearRect(0, 0, canvas.width, canvas.height);
      context.scale(outputScale, outputScale);

      // 渲染页面
      await page.render({
        canvasContext: context,
        viewport,
      } as any).promise;

      // 验证渲染结果
      const imageData = context.getImageData(0, 0, Math.min(100, canvas.width), Math.min(100, canvas.height));
      const hasContent = imageData.data.some((v, i) => i % 4 !== 3 && v !== 255); // 检查是否有非白色像素
      console.log('PDFPreview: Page rendered successfully', { 
        hasContent,
        canvasVisible: canvas.offsetWidth > 0 && canvas.offsetHeight > 0,
        canvasInDOM: document.body.contains(canvas)
      });
    } catch (error) {
      console.error('PDFPreview: Failed to render page:', error);
    } finally {
      setRendering(false);
    }
  }, [currentPage, zoom, zoomMode, onZoomChange]);

  // 当页面或缩放变化时重新渲染
  useEffect(() => {
    console.log('PDFPreview: Render effect triggered', { pdfLoaded, loading, hasPdfDoc: !!pdfDocRef.current });
    if (pdfLoaded > 0 && pdfDocRef.current && !loading) {
      // 使用 setTimeout 确保状态已更新
      const timer = setTimeout(() => {
        renderPage();
      }, 100);
      return () => clearTimeout(timer);
    }
  }, [currentPage, zoom, zoomMode, pdfLoaded, loading]);

  // 同步外部页码
  useEffect(() => {
    if (externalPage && externalPage !== currentPage && externalPage >= 1 && externalPage <= totalPages) {
      setCurrentPage(externalPage);
    }
  }, [externalPage, totalPages]);

  // 同步外部缩放
  useEffect(() => {
    if (externalZoom && externalZoom !== zoom) {
      setZoom(externalZoom);
      setZoomMode('custom');
    }
  }, [externalZoom]);

  // 页面导航
  const goToPage = (page: number) => {
    const newPage = Math.max(1, Math.min(page, totalPages));
    setCurrentPage(newPage);
    onPageChange?.(newPage);
  };

  const prevPage = () => goToPage(currentPage - 1);
  const nextPage = () => goToPage(currentPage + 1);

  // 缩放控制
  const handleZoomIn = () => {
    const newZoom = Math.min(zoom + 25, 400);
    setZoom(newZoom);
    setZoomMode('custom');
    onZoomChange?.(newZoom);
  };

  const handleZoomOut = () => {
    const newZoom = Math.max(zoom - 25, 25);
    setZoom(newZoom);
    setZoomMode('custom');
    onZoomChange?.(newZoom);
  };

  const handleZoomChange = (value: number | null) => {
    if (value) {
      setZoom(value);
      setZoomMode('custom');
      onZoomChange?.(value);
    }
  };

  const handleZoomModeChange = (mode: ZoomMode) => {
    setZoomMode(mode);
    if (mode === 'custom') {
      setZoom(100);
      onZoomChange?.(100);
    }
  };

  // 搜索功能
  const handleSearch = async () => {
    if (!searchText || !pdfDocRef.current) return;

    const results: number[] = [];
    for (let i = 1; i <= totalPages; i++) {
      const page = await pdfDocRef.current.getPage(i);
      const textContent = await page.getTextContent();
      const text = textContent.items.map((item: any) => item.str).join(' ');
      if (text.toLowerCase().includes(searchText.toLowerCase())) {
        results.push(i);
      }
    }

    setSearchResults(results);
    setCurrentSearchIndex(0);

    if (results.length > 0) {
      goToPage(results[0]);
      message.success(`找到 ${results.length} 个结果`);
    } else {
      message.info('未找到匹配内容');
    }
  };

  const nextSearchResult = () => {
    if (searchResults.length === 0) return;
    const nextIndex = (currentSearchIndex + 1) % searchResults.length;
    setCurrentSearchIndex(nextIndex);
    goToPage(searchResults[nextIndex]);
  };

  const prevSearchResult = () => {
    if (searchResults.length === 0) return;
    const prevIndex = (currentSearchIndex - 1 + searchResults.length) % searchResults.length;
    setCurrentSearchIndex(prevIndex);
    goToPage(searchResults[prevIndex]);
  };

  // 键盘快捷键
  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
      if (e.target instanceof HTMLInputElement) return;

      switch (e.key) {
        case 'ArrowLeft':
        case 'PageUp':
          e.preventDefault();
          prevPage();
          break;
        case 'ArrowRight':
        case 'PageDown':
          e.preventDefault();
          nextPage();
          break;
        case 'Home':
          e.preventDefault();
          goToPage(1);
          break;
        case 'End':
          e.preventDefault();
          goToPage(totalPages);
          break;
        case '+':
        case '=':
          if (e.ctrlKey || e.metaKey) {
            e.preventDefault();
            handleZoomIn();
          }
          break;
        case '-':
          if (e.ctrlKey || e.metaKey) {
            e.preventDefault();
            handleZoomOut();
          }
          break;
      }
    };

    window.addEventListener('keydown', handleKeyDown);
    return () => window.removeEventListener('keydown', handleKeyDown);
  }, [currentPage, totalPages, zoom]);

  return (
    <div style={{ display: 'flex', flexDirection: 'column', height: '100%', minHeight: 0, ...style }}>
      {/* 控制栏 */}
      {showControls && (
        <div style={{ 
          padding: '8px 12px', 
          borderBottom: '1px solid #f0f0f0',
          display: 'flex',
          alignItems: 'center',
          gap: 8,
          flexWrap: 'wrap',
        }}>
          {/* 页面导航 */}
          <Space size={4}>
            <Button icon={<LeftOutlined />} size="small" onClick={prevPage} disabled={currentPage <= 1} />
            <InputNumber
              size="small"
              min={1}
              max={totalPages}
              value={currentPage}
              onChange={(v) => v && goToPage(v)}
              style={{ width: 60 }}
            />
            <span style={{ color: '#666' }}>/ {totalPages}</span>
            <Button icon={<RightOutlined />} size="small" onClick={nextPage} disabled={currentPage >= totalPages} />
          </Space>

          <div style={{ width: 1, height: 20, background: '#e8e8e8' }} />

          {/* 缩放控制 */}
          <Space size={4}>
            <Button icon={<ZoomOutOutlined />} size="small" onClick={handleZoomOut} />
            <InputNumber
              size="small"
              min={25}
              max={400}
              value={zoom}
              onChange={handleZoomChange}
              formatter={(v) => `${v}%`}
              parser={(v) => parseInt(v?.replace('%', '') || '100')}
              style={{ width: 70 }}
            />
            <Button icon={<ZoomInOutlined />} size="small" onClick={handleZoomIn} />
            <Select
              size="small"
              value={zoomMode}
              onChange={handleZoomModeChange}
              style={{ width: 100 }}
              options={[
                { value: 'custom', label: '自定义' },
                { value: 'fit-width', label: '适应宽度' },
                { value: 'fit-page', label: '适应页面' },
              ]}
            />
          </Space>

          {/* 搜索 */}
          {showSearch && (
            <>
              <div style={{ width: 1, height: 20, background: '#e8e8e8' }} />
              <Space size={4}>
                <Input
                  size="small"
                  placeholder="搜索..."
                  value={searchText}
                  onChange={(e) => setSearchText(e.target.value)}
                  onPressEnter={handleSearch}
                  style={{ width: 120 }}
                  suffix={<SearchOutlined onClick={handleSearch} style={{ cursor: 'pointer' }} />}
                />
                {searchResults.length > 0 && (
                  <>
                    <span style={{ fontSize: 12, color: '#666' }}>
                      {currentSearchIndex + 1}/{searchResults.length}
                    </span>
                    <Button size="small" onClick={prevSearchResult}>上一个</Button>
                    <Button size="small" onClick={nextSearchResult}>下一个</Button>
                  </>
                )}
              </Space>
            </>
          )}
        </div>
      )}

      {/* PDF 渲染区域 */}
      <div
        ref={containerRef}
        style={{
          flex: 1,
          minHeight: 0,
          overflow: 'auto',
          display: 'flex',
          justifyContent: 'center',
          alignItems: 'flex-start',
          padding: 20,
          background: '#f5f5f5',
        }}
      >
        {loading ? (
          <Spin tip="加载中..." />
        ) : pdfData ? (
          <canvas
            ref={canvasRef}
            style={{
              boxShadow: '0 2px 8px rgba(0,0,0,0.15)',
              background: '#fff',
            }}
          />
        ) : (
          <div style={{ color: '#999', textAlign: 'center', padding: 40 }}>
            请上传 PDF 文件
          </div>
        )}
      </div>
    </div>
  );
};

export default PDFPreview;

/**
 * PDFThumbnails - PDF 缩略图网格组件
 * 实现缩略图渲染、懒加载、页面选择和拖拽排序
 */

import React, { useEffect, useRef, useState, useCallback, useMemo } from 'react';
import { Spin, Checkbox, Button, Tooltip } from 'antd';
import { DeleteOutlined, DragOutlined, RotateLeftOutlined, RotateRightOutlined, SwapOutlined } from '@ant-design/icons';
import * as pdfjsLib from 'pdfjs-dist';

// 设置本地 worker 路径
pdfjsLib.GlobalWorkerOptions.workerSrc = './pdfjs/pdf.worker.min.mjs';

// 配置标准字体和 CMap 路径（用于正确渲染文字和中文）
const STANDARD_FONT_DATA_URL = './pdfjs/standard_fonts/';
const CMAP_URL = './pdfjs/cmaps/';
const CMAP_PACKED = true;

// ============ 类型定义 ============

type RotationType = 'cw' | 'ccw' | 'flip-h' | 'flip-v';

export interface PDFThumbnailsProps {
  pdfData: ArrayBuffer | string | null;
  selectedPages: number[];
  onPageSelect: (pages: number[]) => void;
  onPageReorder?: (newOrder: number[]) => void;
  draggable?: boolean;
  showDeleteButton?: boolean;
  onPageDelete?: (page: number) => void;
  showRotateButtons?: boolean;
  onPageRotate?: (page: number, type: RotationType) => void;
  multiSelect?: boolean;
  thumbnailWidth?: number;
  style?: React.CSSProperties;
}

interface ThumbnailState {
  page: number;
  imageUrl: string | null;
  loading: boolean;
}

// ============ PDFThumbnails 组件 ============

const PDFThumbnails: React.FC<PDFThumbnailsProps> = ({
  pdfData,
  selectedPages,
  onPageSelect,
  onPageReorder,
  draggable = false,
  showDeleteButton = false,
  onPageDelete,
  showRotateButtons = false,
  onPageRotate,
  multiSelect = true,
  thumbnailWidth = 120,
  style,
}) => {
  const pdfDocRef = useRef<pdfjsLib.PDFDocumentProxy | null>(null);
  const containerRef = useRef<HTMLDivElement>(null);
  const [totalPages, setTotalPages] = useState(0);
  const [thumbnails, setThumbnails] = useState<ThumbnailState[]>([]);
  const [loading, setLoading] = useState(false);
  const [draggedPage, setDraggedPage] = useState<number | null>(null);
  const [dragOverPage, setDragOverPage] = useState<number | null>(null);
  const [pageOrder, setPageOrder] = useState<number[]>([]);

  // 加载 PDF 文档
  useEffect(() => {
    if (!pdfData) {
      pdfDocRef.current = null;
      setTotalPages(0);
      setThumbnails([]);
      setPageOrder([]);
      return;
    }

    const loadPDF = async () => {
      setLoading(true);
      try {
        let loadingTask: pdfjsLib.PDFDocumentLoadingTask;

        if (typeof pdfData === 'string') {
          if (pdfData.startsWith('data:')) {
            const base64 = pdfData.split(',')[1];
            const binary = atob(base64);
            const bytes = new Uint8Array(binary.length);
            for (let i = 0; i < binary.length; i++) {
              bytes[i] = binary.charCodeAt(i);
            }
            loadingTask = pdfjsLib.getDocument({ 
              data: bytes,
              standardFontDataUrl: STANDARD_FONT_DATA_URL,
              cMapUrl: CMAP_URL,
              cMapPacked: CMAP_PACKED,
            });
          } else {
            loadingTask = pdfjsLib.getDocument({
              url: pdfData,
              standardFontDataUrl: STANDARD_FONT_DATA_URL,
              cMapUrl: CMAP_URL,
              cMapPacked: CMAP_PACKED,
            });
          }
        } else {
          // 复制 ArrayBuffer 以避免 detached 问题
          // pdfjs 会 transfer ArrayBuffer，导致原始 buffer 被 detached
          const bufferCopy = pdfData.slice(0);
          loadingTask = pdfjsLib.getDocument({ 
            data: bufferCopy,
            standardFontDataUrl: STANDARD_FONT_DATA_URL,
            cMapUrl: CMAP_URL,
            cMapPacked: CMAP_PACKED,
          });
        }

        const pdf = await loadingTask.promise;
        pdfDocRef.current = pdf;
        setTotalPages(pdf.numPages);

        // 初始化页面顺序
        const order = Array.from({ length: pdf.numPages }, (_, i) => i + 1);
        setPageOrder(order);

        // 初始化缩略图状态
        const initialThumbnails: ThumbnailState[] = order.map(page => ({
          page,
          imageUrl: null,
          loading: false,
        }));
        setThumbnails(initialThumbnails);
      } catch (error) {
        console.error('Failed to load PDF:', error);
      } finally {
        setLoading(false);
      }
    };

    loadPDF();

    return () => {
      pdfDocRef.current?.destroy();
      pdfDocRef.current = null;
    };
  }, [pdfData]);

  // 渲染单个缩略图
  const renderThumbnail = useCallback(async (pageNum: number): Promise<string | null> => {
    if (!pdfDocRef.current) return null;

    try {
      const page = await pdfDocRef.current.getPage(pageNum);
      const viewport = page.getViewport({ scale: 1 });
      const scale = thumbnailWidth / viewport.width;
      const scaledViewport = page.getViewport({ scale });

      const canvas = document.createElement('canvas');
      const context = canvas.getContext('2d');
      if (!context) return null;

      canvas.width = scaledViewport.width;
      canvas.height = scaledViewport.height;

      await page.render({
        canvas: canvas,
        canvasContext: context,
        viewport: scaledViewport,
      }).promise;

      return canvas.toDataURL('image/png');
    } catch (error) {
      console.error(`Failed to render thumbnail for page ${pageNum}:`, error);
      return null;
    }
  }, [thumbnailWidth]);

  // 懒加载：使用 IntersectionObserver 监测可见性
  useEffect(() => {
    if (!containerRef.current || thumbnails.length === 0 || !pdfDocRef.current) return;

    // 延迟一帧确保 DOM 已更新
    const timeoutId = setTimeout(() => {
      if (!containerRef.current) return;

      const observer = new IntersectionObserver(
        (entries) => {
          entries.forEach(async (entry) => {
            if (entry.isIntersecting) {
              const pageNum = parseInt(entry.target.getAttribute('data-page') || '0');
              if (pageNum > 0) {
                const thumbnail = thumbnails.find(t => t.page === pageNum);
                if (thumbnail && !thumbnail.imageUrl && !thumbnail.loading) {
                  // 标记为加载中
                  setThumbnails(prev => prev.map(t => 
                    t.page === pageNum ? { ...t, loading: true } : t
                  ));

                  const imageUrl = await renderThumbnail(pageNum);

                  setThumbnails(prev => prev.map(t => 
                    t.page === pageNum ? { ...t, imageUrl, loading: false } : t
                  ));
                }
              }
            }
          });
        },
        { root: containerRef.current, rootMargin: '100px', threshold: 0.1 }
      );

      // 观察所有缩略图容器
      const thumbnailElements = containerRef.current?.querySelectorAll('[data-page]');
      thumbnailElements?.forEach(el => observer.observe(el));

      // 保存 observer 引用以便清理
      return () => observer.disconnect();
    }, 50);

    return () => clearTimeout(timeoutId);
  }, [thumbnails, renderThumbnail]);

  // 页面选择处理
  const handlePageClick = useCallback((page: number, event: React.MouseEvent) => {
    if (multiSelect) {
      if (event.ctrlKey || event.metaKey) {
        // Ctrl/Cmd + 点击：切换选择
        if (selectedPages.includes(page)) {
          onPageSelect(selectedPages.filter(p => p !== page));
        } else {
          onPageSelect([...selectedPages, page]);
        }
      } else if (event.shiftKey && selectedPages.length > 0) {
        // Shift + 点击：范围选择
        const lastSelected = selectedPages[selectedPages.length - 1];
        const start = Math.min(lastSelected, page);
        const end = Math.max(lastSelected, page);
        const range = Array.from({ length: end - start + 1 }, (_, i) => start + i);
        const newSelection = [...new Set([...selectedPages, ...range])];
        onPageSelect(newSelection);
      } else {
        // 普通点击：单选
        onPageSelect([page]);
      }
    } else {
      onPageSelect([page]);
    }
  }, [multiSelect, selectedPages, onPageSelect]);

  // 复选框选择处理
  const handleCheckboxChange = useCallback((page: number, checked: boolean) => {
    if (checked) {
      onPageSelect([...selectedPages, page]);
    } else {
      onPageSelect(selectedPages.filter(p => p !== page));
    }
  }, [selectedPages, onPageSelect]);

  // 全选/取消全选
  const handleSelectAll = useCallback(() => {
    if (selectedPages.length === totalPages) {
      onPageSelect([]);
    } else {
      onPageSelect(pageOrder);
    }
  }, [selectedPages, totalPages, pageOrder, onPageSelect]);

  // 拖拽处理
  const handleDragStart = useCallback((page: number, event: React.DragEvent) => {
    if (!draggable) return;
    setDraggedPage(page);
    event.dataTransfer.effectAllowed = 'move';
    event.dataTransfer.setData('text/plain', String(page));
  }, [draggable]);

  const handleDragOver = useCallback((page: number, event: React.DragEvent) => {
    if (!draggable || draggedPage === null) return;
    event.preventDefault();
    event.dataTransfer.dropEffect = 'move';
    if (page !== draggedPage) {
      setDragOverPage(page);
    }
  }, [draggable, draggedPage]);

  const handleDragLeave = useCallback(() => {
    setDragOverPage(null);
  }, []);

  const handleDrop = useCallback((targetPage: number, event: React.DragEvent) => {
    event.preventDefault();
    if (!draggable || draggedPage === null || draggedPage === targetPage) {
      setDraggedPage(null);
      setDragOverPage(null);
      return;
    }

    // 重新排序
    const newOrder = [...pageOrder];
    const draggedIndex = newOrder.indexOf(draggedPage);
    const targetIndex = newOrder.indexOf(targetPage);

    newOrder.splice(draggedIndex, 1);
    newOrder.splice(targetIndex, 0, draggedPage);

    setPageOrder(newOrder);
    onPageReorder?.(newOrder);

    setDraggedPage(null);
    setDragOverPage(null);
  }, [draggable, draggedPage, pageOrder, onPageReorder]);

  const handleDragEnd = useCallback(() => {
    setDraggedPage(null);
    setDragOverPage(null);
  }, []);

  // 删除页面
  const handleDelete = useCallback((page: number, event: React.MouseEvent) => {
    event.stopPropagation();
    onPageDelete?.(page);
  }, [onPageDelete]);

  // 旋转页面
  const handleRotate = useCallback((page: number, type: RotationType, event: React.MouseEvent) => {
    event.stopPropagation();
    onPageRotate?.(page, type);
  }, [onPageRotate]);

  // 按当前顺序排列的缩略图
  const orderedThumbnails = useMemo(() => {
    return pageOrder.map(page => thumbnails.find(t => t.page === page)).filter(Boolean) as ThumbnailState[];
  }, [pageOrder, thumbnails]);

  if (loading) {
    return (
      <div style={{ display: 'flex', justifyContent: 'center', alignItems: 'center', padding: 40 }}>
        <Spin tip="加载中..." />
      </div>
    );
  }

  if (!pdfData || totalPages === 0) {
    return (
      <div style={{ textAlign: 'center', padding: 40, color: '#999' }}>
        请上传 PDF 文件
      </div>
    );
  }

  return (
    <div style={{ ...style }}>
      {/* 工具栏 */}
      {multiSelect && (
        <div style={{ marginBottom: 8, display: 'flex', alignItems: 'center', gap: 8 }}>
          <Button size="small" onClick={handleSelectAll}>
            {selectedPages.length === totalPages ? '取消全选' : '全选'}
          </Button>
          <span style={{ color: '#666', fontSize: 12 }}>
            已选择 {selectedPages.length} / {totalPages} 页
          </span>
        </div>
      )}

      {/* 缩略图网格 */}
      <div
        ref={containerRef}
        style={{
          display: 'grid',
          gridTemplateColumns: `repeat(auto-fill, minmax(${thumbnailWidth + 20}px, 1fr))`,
          gap: 12,
          maxHeight: 400,
          overflowY: 'auto',
          padding: 8,
        }}
      >
        {orderedThumbnails.map((thumbnail, index) => {
          const isSelected = selectedPages.includes(thumbnail.page);
          const isDragging = draggedPage === thumbnail.page;
          const isDragOver = dragOverPage === thumbnail.page;

          return (
            <div
              key={thumbnail.page}
              data-page={thumbnail.page}
              draggable={draggable}
              onDragStart={(e) => handleDragStart(thumbnail.page, e)}
              onDragOver={(e) => handleDragOver(thumbnail.page, e)}
              onDragLeave={handleDragLeave}
              onDrop={(e) => handleDrop(thumbnail.page, e)}
              onDragEnd={handleDragEnd}
              onClick={(e) => handlePageClick(thumbnail.page, e)}
              style={{
                position: 'relative',
                padding: 8,
                border: `2px solid ${isSelected ? '#1890ff' : isDragOver ? '#52c41a' : '#e8e8e8'}`,
                borderRadius: 4,
                background: isSelected ? '#e6f7ff' : isDragOver ? '#f6ffed' : '#fff',
                cursor: draggable ? 'grab' : 'pointer',
                opacity: isDragging ? 0.5 : 1,
                transition: 'all 0.2s',
                userSelect: 'none',
              }}
            >
              {/* 拖拽手柄 */}
              {draggable && (
                <div style={{ position: 'absolute', top: 4, left: 4, color: '#999' }}>
                  <DragOutlined />
                </div>
              )}

              {/* 复选框 */}
              {multiSelect && (
                <div style={{ position: 'absolute', top: 4, right: 4 }}>
                  <Checkbox
                    checked={isSelected}
                    onChange={(e) => handleCheckboxChange(thumbnail.page, e.target.checked)}
                    onClick={(e) => e.stopPropagation()}
                  />
                </div>
              )}

              {/* 缩略图 */}
              <div style={{ 
                width: thumbnailWidth, 
                minHeight: thumbnailWidth * 1.4,
                display: 'flex',
                alignItems: 'center',
                justifyContent: 'center',
                background: '#f5f5f5',
              }}>
                {thumbnail.loading ? (
                  <Spin size="small" />
                ) : thumbnail.imageUrl ? (
                  <img
                    src={thumbnail.imageUrl}
                    alt={`Page ${thumbnail.page}`}
                    style={{ maxWidth: '100%', maxHeight: '100%', boxShadow: '0 1px 4px rgba(0,0,0,0.1)' }}
                  />
                ) : (
                  <div style={{ color: '#999', fontSize: 12 }}>加载中...</div>
                )}
              </div>

              {/* 页码 */}
              <div style={{ 
                textAlign: 'center', 
                marginTop: 4, 
                fontSize: 12,
                color: isSelected ? '#1890ff' : '#666',
                fontWeight: isSelected ? 'bold' : 'normal',
              }}>
                {draggable ? `${index + 1}` : thumbnail.page}
                {draggable && thumbnail.page !== index + 1 && (
                  <span style={{ color: '#999', marginLeft: 4 }}>(原{thumbnail.page})</span>
                )}
              </div>

              {/* 删除按钮 */}
              {showDeleteButton && (
                <Tooltip title="删除此页">
                  <Button
                    type="text"
                    size="small"
                    danger
                    icon={<DeleteOutlined />}
                    onClick={(e) => handleDelete(thumbnail.page, e)}
                    style={{ position: 'absolute', bottom: 4, right: 4 }}
                  />
                </Tooltip>
              )}

              {/* 旋转按钮组 */}
              {showRotateButtons && (
                <div style={{ 
                  position: 'absolute', 
                  bottom: 4, 
                  left: '50%', 
                  transform: 'translateX(-50%)',
                  display: 'flex',
                  gap: 2,
                  background: 'rgba(255,255,255,0.9)',
                  borderRadius: 4,
                  padding: '2px 4px',
                }}>
                  <Tooltip title="逆时针旋转">
                    <Button
                      type="text"
                      size="small"
                      icon={<RotateLeftOutlined />}
                      onClick={(e) => handleRotate(thumbnail.page, 'ccw', e)}
                      style={{ padding: '0 4px', height: 24 }}
                    />
                  </Tooltip>
                  <Tooltip title="顺时针旋转">
                    <Button
                      type="text"
                      size="small"
                      icon={<RotateRightOutlined />}
                      onClick={(e) => handleRotate(thumbnail.page, 'cw', e)}
                      style={{ padding: '0 4px', height: 24 }}
                    />
                  </Tooltip>
                  <Tooltip title="翻转 180°">
                    <Button
                      type="text"
                      size="small"
                      icon={<SwapOutlined style={{ transform: 'rotate(90deg)' }} />}
                      onClick={(e) => handleRotate(thumbnail.page, 'flip-v', e)}
                      style={{ padding: '0 4px', height: 24 }}
                    />
                  </Tooltip>
                </div>
              )}
            </div>
          );
        })}
      </div>
    </div>
  );
};

export default PDFThumbnails;

/**
 * LAN Transfer Assistant - 独立数据库管理
 * 
 * 使用独立的 SQLite 数据库文件 (transfer.db)，与主应用数据库分离
 */

import Database from 'better-sqlite3';
import * as path from 'path';
import * as fs from 'fs';
import { TRANSFER_CONSTANTS } from '@shared/transfer/constants';

// ============================================
// 数据库 Schema
// ============================================

const SCHEMA_VERSION = TRANSFER_CONSTANTS.SCHEMA_VERSION;

const CREATE_TABLES_SQL = `
-- 设备表
CREATE TABLE IF NOT EXISTS transfer_devices (
  id TEXT PRIMARY KEY,
  name TEXT NOT NULL,
  type TEXT NOT NULL CHECK (type IN ('desktop', 'android')),
  last_ip TEXT,
  last_port INTEGER,
  last_seen INTEGER NOT NULL,
  is_favorite INTEGER DEFAULT 0,
  created_at INTEGER NOT NULL
);

-- 会话表
CREATE TABLE IF NOT EXISTS transfer_sessions (
  id TEXT PRIMARY KEY,
  peer_device_id TEXT NOT NULL,
  peer_device_name TEXT NOT NULL,
  connection_type TEXT NOT NULL CHECK (connection_type IN ('lan', 'relay')),
  started_at INTEGER NOT NULL,
  ended_at INTEGER,
  FOREIGN KEY (peer_device_id) REFERENCES transfer_devices(id) ON DELETE CASCADE
);

-- 消息表
CREATE TABLE IF NOT EXISTS transfer_messages (
  id TEXT PRIMARY KEY,
  session_id TEXT NOT NULL,
  direction TEXT NOT NULL CHECK (direction IN ('sent', 'received')),
  type TEXT NOT NULL CHECK (type IN ('text', 'file', 'image')),
  content TEXT NOT NULL,
  file_id TEXT,
  created_at INTEGER NOT NULL,
  read_at INTEGER,
  FOREIGN KEY (session_id) REFERENCES transfer_sessions(id) ON DELETE CASCADE,
  FOREIGN KEY (file_id) REFERENCES transfer_files(id) ON DELETE SET NULL
);

-- 文件传输表
CREATE TABLE IF NOT EXISTS transfer_files (
  id TEXT PRIMARY KEY,
  session_id TEXT NOT NULL,
  filename TEXT NOT NULL,
  file_size INTEGER NOT NULL,
  mime_type TEXT NOT NULL,
  local_path TEXT,
  direction TEXT NOT NULL CHECK (direction IN ('sent', 'received')),
  status TEXT NOT NULL CHECK (status IN ('pending', 'transferring', 'completed', 'failed', 'cancelled')),
  progress REAL DEFAULT 0,
  file_hash TEXT,
  created_at INTEGER NOT NULL,
  completed_at INTEGER,
  FOREIGN KEY (session_id) REFERENCES transfer_sessions(id) ON DELETE CASCADE
);

-- Schema 版本表
CREATE TABLE IF NOT EXISTS transfer_schema_version (
  version INTEGER PRIMARY KEY,
  applied_at INTEGER NOT NULL
);

-- 索引
CREATE INDEX IF NOT EXISTS idx_sessions_peer_device ON transfer_sessions(peer_device_id);
CREATE INDEX IF NOT EXISTS idx_messages_session ON transfer_messages(session_id);
CREATE INDEX IF NOT EXISTS idx_messages_created ON transfer_messages(created_at);
CREATE INDEX IF NOT EXISTS idx_files_session ON transfer_files(session_id);
CREATE INDEX IF NOT EXISTS idx_files_status ON transfer_files(status);
CREATE INDEX IF NOT EXISTS idx_devices_last_seen ON transfer_devices(last_seen);
CREATE INDEX IF NOT EXISTS idx_devices_favorite ON transfer_devices(is_favorite);
`;

// ============================================
// 数据模型接口
// ============================================

export interface TransferDevice {
  id: string;
  name: string;
  type: 'desktop' | 'android';
  last_ip: string | null;
  last_port: number | null;
  last_seen: number;
  is_favorite: number;
  created_at: number;
}

export interface TransferSession {
  id: string;
  peer_device_id: string;
  peer_device_name: string;
  connection_type: 'lan' | 'relay';
  started_at: number;
  ended_at: number | null;
}

export interface TransferMessage {
  id: string;
  session_id: string;
  direction: 'sent' | 'received';
  type: 'text' | 'file' | 'image';
  content: string;
  file_id: string | null;
  created_at: number;
  read_at: number | null;
}

export interface TransferFile {
  id: string;
  session_id: string;
  filename: string;
  file_size: number;
  mime_type: string;
  local_path: string | null;
  direction: 'sent' | 'received';
  status: 'pending' | 'transferring' | 'completed' | 'failed' | 'cancelled';
  progress: number;
  file_hash: string | null;
  created_at: number;
  completed_at: number | null;
}

// ============================================
// TransferDatabase 类
// ============================================

export class TransferDatabase {
  private db: Database.Database | null = null;
  private dbPath: string;

  constructor(userDataPath: string) {
    this.dbPath = path.join(userDataPath, TRANSFER_CONSTANTS.DATABASE_NAME);
  }

  /**
   * 初始化数据库
   */
  initialize(): void {
    // 确保目录存在
    const dir = path.dirname(this.dbPath);
    if (!fs.existsSync(dir)) {
      fs.mkdirSync(dir, { recursive: true });
    }

    this.db = new Database(this.dbPath);
    this.db.pragma('journal_mode = WAL');
    this.db.pragma('foreign_keys = ON');

    this.initializeSchema();
  }

  /**
   * 初始化 Schema
   */
  private initializeSchema(): void {
    if (!this.db) throw new Error('Database not initialized');

    // 检查 schema 版本
    const versionTable = this.db
      .prepare("SELECT name FROM sqlite_master WHERE type='table' AND name='transfer_schema_version'")
      .get();

    if (!versionTable) {
      // 首次初始化
      this.db.exec(CREATE_TABLES_SQL);
      this.db.prepare('INSERT INTO transfer_schema_version (version, applied_at) VALUES (?, ?)')
        .run(SCHEMA_VERSION, Date.now());
      console.log(`[TransferDatabase] Initialized with schema version ${SCHEMA_VERSION}`);
    } else {
      // 检查是否需要升级
      const currentVersion = this.db
        .prepare('SELECT MAX(version) as version FROM transfer_schema_version')
        .get() as { version: number } | undefined;

      if (!currentVersion || currentVersion.version < SCHEMA_VERSION) {
        this.migrateSchema(currentVersion?.version || 0);
      }
    }
  }

  /**
   * Schema 迁移
   */
  private migrateSchema(fromVersion: number): void {
    console.log(`[TransferDatabase] Migrating from version ${fromVersion} to ${SCHEMA_VERSION}`);
    // 预留迁移逻辑
  }

  /**
   * 关闭数据库
   */
  close(): void {
    if (this.db) {
      this.db.close();
      this.db = null;
    }
  }

  /**
   * 获取数据库实例
   */
  getDatabase(): Database.Database {
    if (!this.db) throw new Error('Database not initialized');
    return this.db;
  }

  // ============================================
  // 设备 CRUD
  // ============================================

  createDevice(device: Omit<TransferDevice, 'created_at'>): TransferDevice {
    if (!this.db) throw new Error('Database not initialized');

    const now = Date.now();
    const stmt = this.db.prepare(`
      INSERT INTO transfer_devices (id, name, type, last_ip, last_port, last_seen, is_favorite, created_at)
      VALUES (?, ?, ?, ?, ?, ?, ?, ?)
    `);

    stmt.run(
      device.id,
      device.name,
      device.type,
      device.last_ip,
      device.last_port,
      device.last_seen,
      device.is_favorite,
      now
    );

    return { ...device, created_at: now };
  }

  getDeviceById(id: string): TransferDevice | undefined {
    if (!this.db) throw new Error('Database not initialized');
    return this.db.prepare('SELECT * FROM transfer_devices WHERE id = ?').get(id) as TransferDevice | undefined;
  }

  getAllDevices(): TransferDevice[] {
    if (!this.db) throw new Error('Database not initialized');
    return this.db.prepare('SELECT * FROM transfer_devices ORDER BY is_favorite DESC, last_seen DESC').all() as TransferDevice[];
  }

  updateDevice(id: string, updates: Partial<TransferDevice>): boolean {
    if (!this.db) throw new Error('Database not initialized');

    const fields = Object.keys(updates).filter(k => k !== 'id');
    if (fields.length === 0) return false;

    const setClause = fields.map(f => `${f} = ?`).join(', ');
    const values = fields.map(f => (updates as any)[f]);

    const result = this.db.prepare(`UPDATE transfer_devices SET ${setClause} WHERE id = ?`).run(...values, id);
    return result.changes > 0;
  }

  deleteDevice(id: string): boolean {
    if (!this.db) throw new Error('Database not initialized');
    const result = this.db.prepare('DELETE FROM transfer_devices WHERE id = ?').run(id);
    return result.changes > 0;
  }

  // ============================================
  // 会话 CRUD
  // ============================================

  createSession(session: TransferSession): TransferSession {
    if (!this.db) throw new Error('Database not initialized');

    const stmt = this.db.prepare(`
      INSERT INTO transfer_sessions (id, peer_device_id, peer_device_name, connection_type, started_at, ended_at)
      VALUES (?, ?, ?, ?, ?, ?)
    `);

    stmt.run(
      session.id,
      session.peer_device_id,
      session.peer_device_name,
      session.connection_type,
      session.started_at,
      session.ended_at
    );

    return session;
  }

  getSessionById(id: string): TransferSession | undefined {
    if (!this.db) throw new Error('Database not initialized');
    return this.db.prepare('SELECT * FROM transfer_sessions WHERE id = ?').get(id) as TransferSession | undefined;
  }

  getAllSessions(): TransferSession[] {
    if (!this.db) throw new Error('Database not initialized');
    return this.db.prepare('SELECT * FROM transfer_sessions ORDER BY started_at DESC').all() as TransferSession[];
  }

  getSessionsByDevice(deviceId: string): TransferSession[] {
    if (!this.db) throw new Error('Database not initialized');
    return this.db.prepare('SELECT * FROM transfer_sessions WHERE peer_device_id = ? ORDER BY started_at DESC')
      .all(deviceId) as TransferSession[];
  }

  endSession(id: string): boolean {
    if (!this.db) throw new Error('Database not initialized');
    const result = this.db.prepare('UPDATE transfer_sessions SET ended_at = ? WHERE id = ?').run(Date.now(), id);
    return result.changes > 0;
  }

  deleteSession(id: string): boolean {
    if (!this.db) throw new Error('Database not initialized');
    const result = this.db.prepare('DELETE FROM transfer_sessions WHERE id = ?').run(id);
    return result.changes > 0;
  }

  // ============================================
  // 消息 CRUD
  // ============================================

  createMessage(message: TransferMessage): TransferMessage {
    if (!this.db) throw new Error('Database not initialized');

    const stmt = this.db.prepare(`
      INSERT INTO transfer_messages (id, session_id, direction, type, content, file_id, created_at, read_at)
      VALUES (?, ?, ?, ?, ?, ?, ?, ?)
    `);

    stmt.run(
      message.id,
      message.session_id,
      message.direction,
      message.type,
      message.content,
      message.file_id,
      message.created_at,
      message.read_at
    );

    return message;
  }

  getMessageById(id: string): TransferMessage | undefined {
    if (!this.db) throw new Error('Database not initialized');
    return this.db.prepare('SELECT * FROM transfer_messages WHERE id = ?').get(id) as TransferMessage | undefined;
  }

  getMessagesBySession(sessionId: string, limit = 100, offset = 0): TransferMessage[] {
    if (!this.db) throw new Error('Database not initialized');
    return this.db.prepare(`
      SELECT * FROM transfer_messages 
      WHERE session_id = ? 
      ORDER BY created_at ASC 
      LIMIT ? OFFSET ?
    `).all(sessionId, limit, offset) as TransferMessage[];
  }

  markMessageAsRead(id: string): boolean {
    if (!this.db) throw new Error('Database not initialized');
    const result = this.db.prepare('UPDATE transfer_messages SET read_at = ? WHERE id = ? AND read_at IS NULL')
      .run(Date.now(), id);
    return result.changes > 0;
  }

  markSessionMessagesAsRead(sessionId: string): number {
    if (!this.db) throw new Error('Database not initialized');
    const result = this.db.prepare(`
      UPDATE transfer_messages SET read_at = ? 
      WHERE session_id = ? AND direction = 'received' AND read_at IS NULL
    `).run(Date.now(), sessionId);
    return result.changes;
  }

  deleteMessage(id: string): boolean {
    if (!this.db) throw new Error('Database not initialized');
    const result = this.db.prepare('DELETE FROM transfer_messages WHERE id = ?').run(id);
    return result.changes > 0;
  }

  // ============================================
  // 文件传输 CRUD
  // ============================================

  createFileTransfer(file: TransferFile): TransferFile {
    if (!this.db) throw new Error('Database not initialized');

    const stmt = this.db.prepare(`
      INSERT INTO transfer_files (id, session_id, filename, file_size, mime_type, local_path, direction, status, progress, file_hash, created_at, completed_at)
      VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
    `);

    stmt.run(
      file.id,
      file.session_id,
      file.filename,
      file.file_size,
      file.mime_type,
      file.local_path,
      file.direction,
      file.status,
      file.progress,
      file.file_hash,
      file.created_at,
      file.completed_at
    );

    return file;
  }

  getFileById(id: string): TransferFile | undefined {
    if (!this.db) throw new Error('Database not initialized');
    return this.db.prepare('SELECT * FROM transfer_files WHERE id = ?').get(id) as TransferFile | undefined;
  }

  getFilesBySession(sessionId: string): TransferFile[] {
    if (!this.db) throw new Error('Database not initialized');
    return this.db.prepare('SELECT * FROM transfer_files WHERE session_id = ? ORDER BY created_at DESC')
      .all(sessionId) as TransferFile[];
  }

  updateFileProgress(id: string, progress: number): boolean {
    if (!this.db) throw new Error('Database not initialized');
    const result = this.db.prepare('UPDATE transfer_files SET progress = ?, status = ? WHERE id = ?')
      .run(progress, 'transferring', id);
    return result.changes > 0;
  }

  completeFileTransfer(id: string, localPath: string, fileHash?: string): boolean {
    if (!this.db) throw new Error('Database not initialized');
    const result = this.db.prepare(`
      UPDATE transfer_files 
      SET status = 'completed', progress = 100, local_path = ?, file_hash = ?, completed_at = ?
      WHERE id = ?
    `).run(localPath, fileHash || null, Date.now(), id);
    return result.changes > 0;
  }

  failFileTransfer(id: string): boolean {
    if (!this.db) throw new Error('Database not initialized');
    const result = this.db.prepare("UPDATE transfer_files SET status = 'failed' WHERE id = ?").run(id);
    return result.changes > 0;
  }

  cancelFileTransfer(id: string): boolean {
    if (!this.db) throw new Error('Database not initialized');
    const result = this.db.prepare("UPDATE transfer_files SET status = 'cancelled' WHERE id = ?").run(id);
    return result.changes > 0;
  }

  deleteFile(id: string): boolean {
    if (!this.db) throw new Error('Database not initialized');
    const result = this.db.prepare('DELETE FROM transfer_files WHERE id = ?').run(id);
    return result.changes > 0;
  }

  // ============================================
  // 清理方法
  // ============================================

  /**
   * 清理过期会话（超过指定天数）
   */
  cleanupOldSessions(daysOld: number): number {
    if (!this.db) throw new Error('Database not initialized');
    const cutoff = Date.now() - (daysOld * 24 * 60 * 60 * 1000);
    const result = this.db.prepare('DELETE FROM transfer_sessions WHERE ended_at IS NOT NULL AND ended_at < ?').run(cutoff);
    return result.changes;
  }

  /**
   * 清理失败的文件传输记录
   */
  cleanupFailedTransfers(): number {
    if (!this.db) throw new Error('Database not initialized');
    const result = this.db.prepare("DELETE FROM transfer_files WHERE status IN ('failed', 'cancelled')").run();
    return result.changes;
  }

  /**
   * 获取统计信息
   */
  getStats(): { devices: number; sessions: number; messages: number; files: number } {
    if (!this.db) throw new Error('Database not initialized');

    const devices = (this.db.prepare('SELECT COUNT(*) as count FROM transfer_devices').get() as { count: number }).count;
    const sessions = (this.db.prepare('SELECT COUNT(*) as count FROM transfer_sessions').get() as { count: number }).count;
    const messages = (this.db.prepare('SELECT COUNT(*) as count FROM transfer_messages').get() as { count: number }).count;
    const files = (this.db.prepare('SELECT COUNT(*) as count FROM transfer_files').get() as { count: number }).count;

    return { devices, sessions, messages, files };
  }
}

export default TransferDatabase;

/**
 * LAN Transfer Assistant - 中继服务器客户端
 *
 * 当局域网直连不可用时，通过中继服务器进行消息和文件转发
 */

import { io, Socket } from 'socket.io-client';
import { v4 as uuidv4 } from 'uuid';
import * as fs from 'fs';
import * as path from 'path';
import * as crypto from 'crypto';
import { TRANSFER_CONSTANTS, SOCKET_EVENTS, DeviceType } from '@shared/transfer/constants';

// ============================================
// 类型定义
// ============================================

export interface RelayConfig {
  serverUrl: string;
  relayKey: string;
  deviceId: string;
  deviceName: string;
}

export interface RelayDevice {
  id: string;
  name: string;
  type: DeviceType;
}

export interface RelayClientEvents {
  connected: () => void;
  disconnected: (reason: string) => void;
  error: (error: any) => void;
  'device:list': (devices: RelayDevice[]) => void;
  'device:online': (device: RelayDevice) => void;
  'device:offline': (deviceId: string) => void;
  'pair:request': (data: { requesterId: string; requesterName: string }) => void;
  'pair:success': (data: { sessionId: string; peerId: string; peerName: string }) => void;
  'message:received': (data: any) => void;
  'file:incoming': (data: any) => void;
  'file:chunk': (data: any) => void;
  'file:complete': (data: any) => void;
}

type EventCallback<T> = (data: T) => void;

// ============================================
// RelayClient 类
// ============================================

export class RelayClient {
  private socket: Socket | null = null;
  private config: RelayConfig | null = null;
  private eventListeners: Map<string, Set<EventCallback<any>>> = new Map();
  private heartbeatInterval: NodeJS.Timeout | null = null;
  private reconnectAttempts = 0;
  private maxReconnectAttempts = 5;
  private isConnecting = false;
  private onlineDevices: RelayDevice[] = [];

  // ============================================
  // 事件系统
  // ============================================

  on<K extends keyof RelayClientEvents>(event: K, callback: RelayClientEvents[K]): void {
    if (!this.eventListeners.has(event)) {
      this.eventListeners.set(event, new Set());
    }
    this.eventListeners.get(event)!.add(callback as EventCallback<any>);
  }

  off<K extends keyof RelayClientEvents>(event: K, callback: RelayClientEvents[K]): void {
    const listeners = this.eventListeners.get(event);
    if (listeners) {
      listeners.delete(callback as EventCallback<any>);
    }
  }

  private emit<K extends keyof RelayClientEvents>(
    event: K,
    data?: Parameters<RelayClientEvents[K]>[0]
  ): void {
    const listeners = this.eventListeners.get(event);
    if (listeners) {
      listeners.forEach(callback => callback(data as any));
    }
  }

  // ============================================
  // 连接管理
  // ============================================

  /**
   * 获取中继状态
   */
  getStatus() {
    return {
      connected: this.socket?.connected || false,
      serverUrl: this.config?.serverUrl || null,
      connecting: this.isConnecting,
      error: null,
    };
  }

  /**
   * 获取在线设备
   */
  getConnectedDevices() {
    return this.onlineDevices;
  }

  private resolveRelayEndpoint(serverUrl: string): { url: string; path: string } {
    const trimmedUrl = serverUrl.trim();
    try {
      const parsed = new URL(trimmedUrl);
      const relayPath =
        parsed.pathname && parsed.pathname !== '/'
          ? parsed.pathname.replace(/\/$/, '') || '/transfer'
          : '/transfer';
      parsed.pathname = '';
      parsed.search = '';
      parsed.hash = '';
      return {
        url: parsed.toString().replace(/\/$/, ''),
        path: relayPath,
      };
    } catch {
      return {
        url: trimmedUrl.replace(/\/$/, ''),
        path: '/transfer',
      };
    }
  }
  // ============================================

  /**
   * 连接到中继服务器
   */
  async connect(config: RelayConfig): Promise<void> {
    if (this.socket?.connected) {
      console.log('[RelayClient] Already connected');
      return;
    }

    if (this.isConnecting) {
      console.log('[RelayClient] Connection in progress');
      return;
    }

    this.isConnecting = true;
    this.config = config;

    return new Promise((resolve, reject) => {
      try {
        // 构建连接 URL
        const endpoint = this.resolveRelayEndpoint(config.serverUrl);

        this.socket = io(endpoint.url, {
          path: endpoint.path,
          auth: {
            relayKey: config.relayKey,
          },
          transports: ['websocket', 'polling'],
          reconnection: true,
          reconnectionAttempts: this.maxReconnectAttempts,
          reconnectionDelay: 1000,
          reconnectionDelayMax: 5000,
          timeout: 10000,
        });

        // 连接成功
        this.socket.on('connect', () => {
          console.log('[RelayClient] Connected to relay server');
          this.isConnecting = false;
          this.reconnectAttempts = 0;

          // 注册设备
          this.registerDevice();
          this.startHeartbeat();
          this.emit('connected');
          resolve();
        });

        // 连接错误
        this.socket.on('connect_error', error => {
          console.error('[RelayClient] Connection error:', error.message);
          this.isConnecting = false;

          if (error.message === 'INVALID_RELAY_KEY') {
            this.emit('error', { code: 'INVALID_KEY', message: '中继密钥无效' });
            reject(new Error('中继密钥无效'));
          } else {
            this.emit('error', { code: 'CONNECTION_ERROR', message: error.message });
            reject(error);
          }
        });

        // 断开连接
        this.socket.on('disconnect', reason => {
          console.log('[RelayClient] Disconnected:', reason);
          this.stopHeartbeat();
          this.emit('disconnected', reason);
        });

        // 设置事件处理
        this.setupEventHandlers();
      } catch (error) {
        this.isConnecting = false;
        reject(error);
      }
    });
  }

  /**
   * 断开连接
   */
  disconnect(): void {
    this.stopHeartbeat();

    if (this.socket) {
      this.socket.disconnect();
      this.socket = null;
    }

    this.config = null;
    this.isConnecting = false;
    console.log('[RelayClient] Disconnected');
  }

  /**
   * 检查是否已连接
   */
  isConnected(): boolean {
    return this.socket?.connected || false;
  }

  // ============================================
  // 设备注册
  // ============================================

  private registerDevice(): void {
    if (!this.socket || !this.config) return;

    this.socket.emit(SOCKET_EVENTS.DEVICE_REGISTER, {
      deviceId: this.config.deviceId,
      deviceName: this.config.deviceName,
      deviceType: 'desktop' as DeviceType,
    });
  }

  // ============================================
  // 事件处理
  // ============================================

  private setupEventHandlers(): void {
    if (!this.socket) return;

    // 设备列表
    this.socket.on(SOCKET_EVENTS.DEVICE_LIST, (devices: RelayDevice[]) => {
      this.onlineDevices = devices;
      this.emit('device:list', devices);
    });

    // 设备上线
    this.socket.on(SOCKET_EVENTS.DEVICE_ONLINE, (data: { device: RelayDevice }) => {
      const exists = this.onlineDevices.some(d => d.id === data.device.id);
      if (!exists) {
        this.onlineDevices.push(data.device);
      }
      this.emit('device:online', data.device);
    });

    // 设备下线
    this.socket.on(SOCKET_EVENTS.DEVICE_OFFLINE, (data: { deviceId: string }) => {
      this.onlineDevices = this.onlineDevices.filter(d => d.id !== data.deviceId);
      this.emit('device:offline', data.deviceId);
    });

    // 配对请求
    this.socket.on(
      SOCKET_EVENTS.PAIR_REQUEST,
      (data: { requesterId: string; requesterName: string }) => {
        this.emit('pair:request', data);
      }
    );

    // 配对成功
    this.socket.on(
      SOCKET_EVENTS.PAIR_SUCCESS,
      (data: { sessionId: string; peerId: string; peerName: string }) => {
        this.emit('pair:success', data);
      }
    );

    // 消息接收
    this.socket.on(SOCKET_EVENTS.MESSAGE_RECEIVE, (data: any) => {
      console.log('[RelayClient] MESSAGE_RECEIVE event:', JSON.stringify(data));
      this.emit('message:received', data);
    });

    // 文件传入
    this.socket.on(SOCKET_EVENTS.FILE_INCOMING, (data: any) => {
      console.log(`[RelayClient] File incoming: ${data.fileInfo?.filename || 'unknown'}`);
      this.emit('file:incoming', data);
    });

    // 文件分块
    this.socket.on(SOCKET_EVENTS.FILE_CHUNK, (data: any) => {
      this.emit('file:chunk', data);
    });

    // 文件完成
    this.socket.on(SOCKET_EVENTS.FILE_COMPLETE, (data: any) => {
      this.emit('file:complete', data);
    });

    // 错误
    this.socket.on(SOCKET_EVENTS.ERROR, (error: any) => {
      console.error('[RelayClient] Server error:', error);
      this.emit('error', error);
    });
  }

  // ============================================
  // 配对操作
  // ============================================

  /**
   * 发送配对请求
   */
  sendPairRequest(targetDeviceId: string): void {
    if (!this.socket) return;
    this.socket.emit(SOCKET_EVENTS.PAIR_REQUEST, { targetDeviceId });
  }

  /**
   * 接受配对请求
   */
  acceptPairRequest(requesterId: string): string {
    if (!this.socket) return '';
    const sessionId = uuidv4();
    this.socket.emit(SOCKET_EVENTS.PAIR_ACCEPT, { requesterId, sessionId });
    return sessionId;
  }

  /**
   * 拒绝配对请求
   */
  rejectPairRequest(requesterId: string): void {
    if (!this.socket) return;
    this.socket.emit(SOCKET_EVENTS.PAIR_REJECT, { requesterId });
  }

  // ============================================
  // 消息操作
  // ============================================

  /**
   * 发送消息
   */
  sendMessage(
    targetDeviceId: string,
    sessionId: string,
    message: { id: string; type: string; content: string }
  ): boolean {
    if (!this.socket) return false;

    this.socket.emit(SOCKET_EVENTS.MESSAGE_SEND, {
      targetDeviceId,
      sessionId,
      message,
    });

    return true;
  }

  /**
   * 发送已读回执
   */
  sendMessageRead(targetDeviceId: string, messageIds: string[]): void {
    if (!this.socket) return;

    this.socket.emit(SOCKET_EVENTS.MESSAGE_READ, {
      targetDeviceId,
      messageIds,
    });
  }

  // ============================================
  // 文件操作
  // ============================================

  /**
   * 发送文件
   */
  async sendFile(
    targetDeviceId: string,
    sessionId: string,
    filePath: string
  ): Promise<{ id: string; filename: string; fileSize: number; mimeType: string }> {
    if (!this.socket) {
      throw new Error('未连接到中继服务器');
    }

    // 读取文件信息
    const stats = fs.statSync(filePath);
    const filename = path.basename(filePath);
    const fileId = uuidv4();
    const fileSize = stats.size;
    const totalChunks = Math.ceil(fileSize / TRANSFER_CONSTANTS.CHUNK_SIZE);

    // 获取 MIME 类型
    const ext = path.extname(filename).toLowerCase().slice(1);
    const mimeTypes: Record<string, string> = {
      jpg: 'image/jpeg',
      jpeg: 'image/jpeg',
      png: 'image/png',
      gif: 'image/gif',
      pdf: 'application/pdf',
      doc: 'application/msword',
      txt: 'text/plain',
      zip: 'application/zip',
      mp3: 'audio/mpeg',
      mp4: 'video/mp4',
      apk: 'application/vnd.android.package-archive',
    };
    const mimeType = mimeTypes[ext] || 'application/octet-stream';

    // 发送文件开始事件
    this.socket.emit(SOCKET_EVENTS.FILE_START, {
      targetDeviceId,
      sessionId,
      fileInfo: {
        id: fileId,
        filename,
        fileSize,
        mimeType,
        totalChunks,
      },
    });

    const fileBuffer = fs.readFileSync(filePath);
    const hash = crypto.createHash('sha256');
    hash.update(fileBuffer);
    const fileHash = hash.digest('hex');

    (async () => {
      for (let i = 0; i < totalChunks; i++) {
        const start = i * TRANSFER_CONSTANTS.CHUNK_SIZE;
        const end = Math.min(start + TRANSFER_CONSTANTS.CHUNK_SIZE, fileSize);
        const chunk = fileBuffer.slice(start, end);

        this.socket!.emit(SOCKET_EVENTS.FILE_CHUNK, {
          targetDeviceId,
          sessionId,
          fileId,
          chunkIndex: i,
          chunk: chunk.toString('base64'),
          totalChunks,
        });

        await new Promise(resolve => setTimeout(resolve, 10));
      }

      this.socket!.emit(SOCKET_EVENTS.FILE_COMPLETE, {
        targetDeviceId,
        sessionId,
        fileId,
        fileHash,
      });
      console.log(`[RelayClient] File transfer to ${targetDeviceId} completed: ${fileId}`);
    })().catch(err => {
      console.error('[RelayClient] Background file send failed:', err);
    });

    return { id: fileId, filename, fileSize, mimeType };
  }

  // ============================================
  // 心跳
  // ============================================

  private startHeartbeat(): void {
    this.stopHeartbeat();

    this.heartbeatInterval = setInterval(() => {
      if (this.socket?.connected) {
        this.socket.emit(SOCKET_EVENTS.HEARTBEAT);
      }
    }, TRANSFER_CONSTANTS.HEARTBEAT_INTERVAL);
  }

  private stopHeartbeat(): void {
    if (this.heartbeatInterval) {
      clearInterval(this.heartbeatInterval);
      this.heartbeatInterval = null;
    }
  }
}

