      details: { action: 'update_rate_limit_config', loginMaxAttempts, blockDurationMinutes },
      success: true
    });

    res.json({
      success: true,
      message: '配置已更新',
      config: getRateLimitConfig()
    });
  } catch (error) {
    console.error('Update rate limit config error:', error);
    res.status(500).json({
      error: {
        code: 'AUTH_500',
        message: '服务器内部错误'
      }
    });
  }
});

