/**
 * 锁屏界面
 * 
 * 支持 PIN 码和生物识别解锁
 */
@Composable
fun LockScreen(
    onUnlocked: () -> Unit,
    viewModel: LockScreenViewModel = hiltViewModel()
) {
    val uiState by viewModel.uiState.collectAsState()
    val context = LocalContext.current

    // 设置 Activity 用于生物识别
    LaunchedEffect(Unit) {
        (context as? FragmentActivity)?.let { activity ->
            viewModel.setActivity(activity)
        }
    }

    LaunchedEffect(uiState.isUnlocked) {
        if (uiState.isUnlocked) {
            onUnlocked()
        }
    }

    Surface(
        modifier = Modifier.fillMaxSize(),
        color = MaterialTheme.colorScheme.background
    ) {
        Column(
            modifier = Modifier
                .fillMaxSize()
                .padding(24.dp),
            horizontalAlignment = Alignment.CenterHorizontally,
            verticalArrangement = Arrangement.Center
        ) {
            // 应用图标和标题
            Text(
                text = stringResource(R.string.app_name),
                style = MaterialTheme.typography.headlineMedium,
                fontWeight = FontWeight.Bold,
                color = MaterialTheme.colorScheme.primary
            )

            Spacer(modifier = Modifier.height(8.dp))

            Text(
                text = stringResource(R.string.lock_screen_title),
                style = MaterialTheme.typography.bodyLarge,
                color = MaterialTheme.colorScheme.onSurfaceVariant
            )

            Spacer(modifier = Modifier.height(48.dp))

            when (uiState.lockType) {
                LockType.PIN -> {
                    PinInput(
                        pin = uiState.enteredPin,
                        pinLength = uiState.pinLength,
                        error = uiState.error,
                        onPinChange = { viewModel.onPinChange(it) },
                        onBiometricClick = if (uiState.biometricAvailable) {
                            { viewModel.authenticateWithBiometric() }
                        } else null
                    )
                }
                LockType.BIOMETRIC -> {
                    BiometricPrompt(
                        error = uiState.error,
                        onRetry = { viewModel.authenticateWithBiometric() },
                        onUsePinClick = { viewModel.switchToPinMode() }
                    )
                }
                LockType.PATTERN -> {
                    // TODO: 实现图案解锁
                    PatternInput(
                        error = uiState.error,
                        onPatternComplete = { viewModel.onPatternComplete(it) }
                    )
                }
                LockType.NONE -> {
                    // 不应该到达这里
                    onUnlocked()
                }
            }
        }
    }
}

/**
 * PIN 码输入组件
 */
@Composable
private fun PinInput(
    pin: String,
    pinLength: Int,
    error: String?,
    onPinChange: (String) -> Unit,
    onBiometricClick: (() -> Unit)?
) {
    Column(
        horizontalAlignment = Alignment.CenterHorizontally
    ) {
        // PIN 码显示 - 根据实际 PIN 长度显示圆点
        Row(
            horizontalArrangement = Arrangement.spacedBy(16.dp)
        ) {
            repeat(pinLength) { index ->
                PinDot(filled = index < pin.length)
            }
        }

        Spacer(modifier = Modifier.height(16.dp))

        // 错误提示
        AnimatedVisibility(
            visible = error != null,
            enter = fadeIn(),
            exit = fadeOut()
        ) {
            Text(
                text = error ?: "",
                color = MaterialTheme.colorScheme.error,
                style = MaterialTheme.typography.bodyMedium
            )
        }

        Spacer(modifier = Modifier.height(32.dp))

        // 数字键盘
        NumberPad(
            onNumberClick = { number ->
                if (pin.length < pinLength) {
                    onPinChange(pin + number)
                }
            },
            onDeleteClick = {
                if (pin.isNotEmpty()) {
                    onPinChange(pin.dropLast(1))
                }
            },
            onBiometricClick = onBiometricClick
        )
    }
}

/**
 * PIN 码圆点
 */
@Composable
private fun PinDot(filled: Boolean) {
    Box(
        modifier = Modifier
            .size(16.dp)
            .clip(CircleShape)
            .background(
                if (filled) MaterialTheme.colorScheme.primary
                else Color.Transparent
            )
            .border(
                width = 2.dp,
                color = MaterialTheme.colorScheme.primary,
                shape = CircleShape
            )
    )
}

/**
 * 数字键盘
 */
@Composable
private fun NumberPad(
    onNumberClick: (String) -> Unit,
    onDeleteClick: () -> Unit,
    onBiometricClick: (() -> Unit)?
) {
    Column(
        verticalArrangement = Arrangement.spacedBy(16.dp)
    ) {
        // 1-9
        for (row in 0..2) {
            Row(
                horizontalArrangement = Arrangement.spacedBy(24.dp)
            ) {
                for (col in 1..3) {
                    val number = row * 3 + col
                    NumberButton(
                        number = number.toString(),
                        onClick = { onNumberClick(number.toString()) }
                    )
                }
            }
        }

        // 底部行：生物识别/空、0、删除
        Row(
            horizontalArrangement = Arrangement.spacedBy(24.dp)
        ) {
            // 生物识别按钮
            if (onBiometricClick != null) {
                IconButton(
                    onClick = onBiometricClick,
