/**
 * 图案输入（简化版）
 */
@Composable
private fun PatternInput(
    error: String?,
    onPatternComplete: (List<Int>) -> Unit
) {
    var pattern by remember { mutableStateOf(listOf<Int>()) }

    Column(
        horizontalAlignment = Alignment.CenterHorizontally
    ) {
        Text(
            text = stringResource(R.string.draw_pattern),
            style = MaterialTheme.typography.bodyLarge
        )

        Spacer(modifier = Modifier.height(32.dp))

        // 3x3 图案网格
        Column(
            verticalArrangement = Arrangement.spacedBy(24.dp)
        ) {
            for (row in 0..2) {
                Row(
                    horizontalArrangement = Arrangement.spacedBy(24.dp)
                ) {
                    for (col in 0..2) {
                        val index = row * 3 + col
                        PatternDot(
                            selected = pattern.contains(index),
                            onClick = {
                                if (!pattern.contains(index)) {
                                    val newPattern = pattern + index
                                    pattern = newPattern
                                    if (newPattern.size >= 4) {
                                        onPatternComplete(newPattern)
                                        pattern = emptyList()
                                    }
                                }
                            }
                        )
                    }
                }
            }
        }

        if (error != null) {
            Spacer(modifier = Modifier.height(16.dp))

            Text(
                text = error,
                color = MaterialTheme.colorScheme.error,
                style = MaterialTheme.typography.bodyMedium
            )
        }

        Spacer(modifier = Modifier.height(16.dp))

        TextButton(onClick = { pattern = emptyList() }) {
            Text(stringResource(R.string.clear))
        }
    }
}

/**
 * 图案圆点
 */
@Composable
private fun PatternDot(
    selected: Boolean,
    onClick: () -> Unit
) {
    Box(
        modifier = Modifier
            .size(64.dp)
            .clip(CircleShape)
            .background(
                if (selected) MaterialTheme.colorScheme.primary.copy(alpha = 0.2f)
                else MaterialTheme.colorScheme.surfaceVariant
            )
            .clickable(onClick = onClick),
        contentAlignment = Alignment.Center
    ) {
        Box(
            modifier = Modifier
                .size(if (selected) 24.dp else 16.dp)
                .clip(CircleShape)
                .background(
                    if (selected) MaterialTheme.colorScheme.primary
                    else MaterialTheme.colorScheme.onSurfaceVariant.copy(alpha = 0.5f)
                )
        )
    }
}

