import {
  createContext,
  useContext,
  useState,
  useEffect,
  useCallback,
  useRef,
  ReactNode,
} from 'react';
import { AppSettings, SyncConfig, SyncModules, DEFAULT_SYNC_MODULES } from '@shared/types';

const DEFAULT_SETTINGS: AppSettings = {
  theme: 'system',
  language: 'zh-CN',
  font_size: 14,
  auto_save: true,
  auto_save_interval: 30,
  show_line_numbers: true,
  spell_check: false,
  auto_launch: false,
  close_to_tray: false,
};

const DEFAULT_SYNC_CONFIG: SyncConfig = {
  enabled: false,
  type: 'webdav',
  url: '',
  sync_path: '/mucheng-notes',
  username: '',
  password: '',
  sync_interval: 5,
  last_sync_time: null,
  sync_cursor: null,
  sync_modules: DEFAULT_SYNC_MODULES,
};

function getSyncConfigBackup(config: SyncConfig): Partial<SyncConfig> {
  return {
    ...config,
    password: undefined,
    api_key: undefined,
    server_password: undefined,
    server_sync_key: undefined,
    server_token: undefined,
    server_refresh_token: undefined,
    server_token_expires: undefined,
  };
}

interface SettingsContextType {
  settings: AppSettings;
  syncConfig: SyncConfig;
  syncConfigLoaded: boolean;
  updateSettings: (updates: Partial<AppSettings>) => void;
  updateSyncConfig: (updates: Partial<SyncConfig>) => void;
  // 独立的同步配置更新方法（参考手机端实现，每个字段独立保存）
  setSyncEnabled: (enabled: boolean) => void;
  setSyncType: (type: 'webdav' | 'server') => void;
  setSyncUrl: (url: string) => void;
  setSyncPath: (path: string) => void;
  setSyncUsername: (username: string) => void;
  setSyncPassword: (password: string) => void;
  setSyncApiKey: (apiKey: string) => void;
  setSyncInterval: (interval: number) => void;
  setSyncModule: (module: keyof SyncModules, enabled: boolean) => void;
  // 服务器认证相关
  setServerAuth: (username: string, password: string, syncKey: string) => void;
  setServerToken: (token: string, refreshToken: string, expiresIn: number) => void;
  clearServerAuth: () => void;
  resetSettings: () => void;
  isDarkMode: boolean;
}

const SettingsContext = createContext<SettingsContextType | null>(null);

export function useSettings() {
  const context = useContext(SettingsContext);
  if (!context) {
    throw new Error('useSettings must be used within a SettingsProvider');
  }
  return context;
}

interface SettingsProviderProps {
  children: ReactNode;
}

export function SettingsProvider({ children }: SettingsProviderProps) {
  // 使用惰性初始化，在组件首次渲染时就从 localStorage 读取配置
  const [settings, setSettings] = useState<AppSettings>(() => {
    const savedSettings = localStorage.getItem('mucheng-settings');
    if (savedSettings) {
      try {
        return { ...DEFAULT_SETTINGS, ...JSON.parse(savedSettings) };
      } catch (e) {
        console.error('Failed to load settings:', e);
      }
    }
    return DEFAULT_SETTINGS;
  });

  // 同步配置初始化为默认值，然后通过 useEffect 从主进程加载
  const [syncConfig, setSyncConfigState] = useState<SyncConfig>(DEFAULT_SYNC_CONFIG);
  const [syncConfigLoaded, setSyncConfigLoaded] = useState(false);
  const [systemDarkMode, setSystemDarkMode] = useState(false);

  // 使用 ref 来存储最新的配置，避免闭包问题
  const syncConfigRef = useRef<SyncConfig>(DEFAULT_SYNC_CONFIG);

  // 保存同步配置到主进程和 localStorage
  const persistSyncConfig = useCallback(async (newConfig: SyncConfig) => {
    // 更新 ref
    syncConfigRef.current = newConfig;

    // 保存到主进程文件系统
    try {
      const api = (window as any).electronAPI;
      if (api?.saveSyncConfig) {
        await api.saveSyncConfig(newConfig);
      }
    } catch (e) {
      console.error('Failed to save sync config to main process');
    }

    // localStorage 仅保存非敏感字段作为兜底备份
    localStorage.setItem('mucheng-sync-config', JSON.stringify(getSyncConfigBackup(newConfig)));
  }, []);

  // 从主进程加载同步配置
  useEffect(() => {
    const loadSyncConfig = async () => {
      try {
        let savedConfig = null;

        // 先尝试从主进程加载
        const api = (window as any).electronAPI;
        if (api?.loadSyncConfig) {
          savedConfig = await api.loadSyncConfig();
        }

        // 如果主进程配置为空或不完整，尝试从 localStorage 恢复
        if (!savedConfig || (savedConfig.enabled && !savedConfig.url)) {
          const localConfig = localStorage.getItem('mucheng-sync-config');
          if (localConfig) {
            try {
              const parsed = JSON.parse(localConfig);
              if (parsed.url) {
                console.log('[SettingsContext] Recovering config from localStorage:', parsed);
                savedConfig = parsed;
                // 同步回主进程
                if (api?.saveSyncConfig) {
                  await api.saveSyncConfig(savedConfig);
                }
              }
            } catch (e) {
              console.error('Failed to parse localStorage config:', e);
            }
          }
        }

        if (savedConfig) {
          // 深度合并 sync_modules，确保新增的模块字段有默认值
          const mergedSyncModules = {
            ...DEFAULT_SYNC_MODULES,
            ...(savedConfig.sync_modules || {}),
          };
          const mergedConfig = { 
            ...DEFAULT_SYNC_CONFIG, 
            ...savedConfig,
            sync_modules: mergedSyncModules,
          };
          setSyncConfigState(mergedConfig);
          syncConfigRef.current = mergedConfig;
        }
      } catch (e) {
        console.error('Failed to load sync config:', e);
      } finally {
        setSyncConfigLoaded(true);
      }
    };
    loadSyncConfig();

    // 监听 token 刷新事件
    const api = (window as any).electronAPI;
    if (api?.sync?.onTokenRefreshed) {
      api.sync.onTokenRefreshed((data: { token: string; refreshToken: string; expiresIn: number }) => {
        console.log('[SettingsContext] Token refreshed, updating config');
        setSyncConfigState((prev: SyncConfig) => {
          const newConfig = {
            ...prev,
            server_token: data.token,
            server_refresh_token: data.refreshToken,
            server_token_expires: Date.now() + data.expiresIn * 1000,
          };
          persistSyncConfig(newConfig);
          return newConfig;
        });
      });
    }
  }, [persistSyncConfig]);

  // 监听系统主题变化
  useEffect(() => {
    const mediaQuery = window.matchMedia('(prefers-color-scheme: dark)');
    setSystemDarkMode(mediaQuery.matches);
    const handler = (e: MediaQueryListEvent) => setSystemDarkMode(e.matches);
    mediaQuery.addEventListener('change', handler);
    return () => mediaQuery.removeEventListener('change', handler);
  }, []);

  // 同步主题设置到主进程
  useEffect(() => {
    const api = (window as any).electronAPI;
    if (api?.saveThemeSettings) {
      api.saveThemeSettings({ theme: settings.theme }).catch(() => {});
    }
  }, [settings.theme]);

  // 保存应用设置
  const saveSettings = useCallback(async (newSettings: AppSettings) => {
    localStorage.setItem('mucheng-settings', JSON.stringify(newSettings));
    try {
      const api = (window as any).electronAPI;
      if (api?.saveThemeSettings) {
        await api.saveThemeSettings({ theme: newSettings.theme });
      }
    } catch (e) {
      console.warn('Failed to save theme to main process:', e);
    }
  }, []);

  const updateSettings = useCallback(
    (updates: Partial<AppSettings>) => {
      setSettings((prev: AppSettings) => {
        const newSettings = { ...prev, ...updates };
        saveSettings(newSettings);
        return newSettings;
      });
    },
    [saveSettings]
  );

  // 通用的同步配置更新方法
  const updateSyncConfig = useCallback(
    (updates: Partial<SyncConfig>) => {
      setSyncConfigState((prev: SyncConfig) => {
        const newConfig = { ...prev, ...updates };
        // 始终保存配置（移除 syncConfigLoaded 检查，避免配置丢失）
        persistSyncConfig(newConfig);
        return newConfig;
      });
    },
    [persistSyncConfig]
  );

  // ========== 独立的同步配置更新方法（参考手机端实现） ==========

  const setSyncEnabled = useCallback(
    (enabled: boolean) => {
      updateSyncConfig({ enabled });
    },
    [updateSyncConfig]
  );

  const setSyncType = useCallback(
    (type: 'webdav' | 'server') => {
      updateSyncConfig({ type });
    },
    [updateSyncConfig]
  );

  const setSyncUrl = useCallback(
    (url: string) => {
      updateSyncConfig({ url });
    },
    [updateSyncConfig]
  );

  const setSyncPath = useCallback(
    (path: string) => {
      updateSyncConfig({ sync_path: path });
    },
    [updateSyncConfig]
  );

  const setSyncUsername = useCallback(
    (username: string) => {
      updateSyncConfig({ username });
    },
    [updateSyncConfig]
  );

  const setSyncPassword = useCallback(
    (password: string) => {
      updateSyncConfig({ password });
    },
    [updateSyncConfig]
  );

  const setSyncApiKey = useCallback(
    (apiKey: string) => {
      updateSyncConfig({ api_key: apiKey });
    },
    [updateSyncConfig]
  );

  const setSyncInterval = useCallback(
    (interval: number) => {
      updateSyncConfig({ sync_interval: interval });
    },
    [updateSyncConfig]
  );

  const setSyncModule = useCallback(
    (module: keyof SyncModules, enabled: boolean) => {
      setSyncConfigState((prev: SyncConfig) => {
        const newModules = { ...prev.sync_modules, [module]: enabled };
        const newConfig = { ...prev, sync_modules: newModules };
        persistSyncConfig(newConfig);
        return newConfig;
      });
    },
    [persistSyncConfig]
  );

  // 服务器认证相关方法
  const setServerAuth = useCallback(
    (username: string, password: string, syncKey: string) => {
      updateSyncConfig({
        server_username: username,
        server_password: password,
        server_sync_key: syncKey,
      });
    },
    [updateSyncConfig]
  );

  const setServerToken = useCallback(
    (token: string, refreshToken: string, expiresIn: number) => {
      updateSyncConfig({
        server_token: token,
        server_refresh_token: refreshToken,
        server_token_expires: Date.now() + expiresIn * 1000,
      });
    },
    [updateSyncConfig]
  );

  const clearServerAuth = useCallback(() => {
    updateSyncConfig({
      server_username: undefined,
      server_password: undefined,
      server_sync_key: undefined,
      server_token: undefined,
      server_refresh_token: undefined,
      server_token_expires: undefined,
    });
  }, [updateSyncConfig]);

  const resetSettings = useCallback(() => {
    setSettings(DEFAULT_SETTINGS);
    saveSettings(DEFAULT_SETTINGS);
  }, [saveSettings]);

  // 计算是否为深色模式
  const isDarkMode = settings.theme === 'dark' || (settings.theme === 'system' && systemDarkMode);

  return (
    <SettingsContext.Provider
      value={{
        settings,
        syncConfig,
        syncConfigLoaded,
        updateSettings,
        updateSyncConfig,
        setSyncEnabled,
        setSyncType,
        setSyncUrl,
        setSyncPath,
        setSyncUsername,
        setSyncPassword,
        setSyncApiKey,
        setSyncInterval,
        setSyncModule,
        setServerAuth,
        setServerToken,
        clearServerAuth,
        resetSettings,
        isDarkMode,
      }}
    >
      {children}
    </SettingsContext.Provider>
  );
}

/**
 * CropBox - 可视化裁剪框组件
 * 支持拖拽移动和调整大小
 */

import React, { useState, useCallback, useRef, useEffect } from 'react';

// 裁剪框状态
export interface CropBoxState {
  left: number;
  top: number;
  width: number;
  height: number;
}

// 组件属性
interface CropBoxProps {
  // 图片尺寸
  imageWidth: number;
  imageHeight: number;
  // 裁剪框状态
  cropState: CropBoxState;
  // 状态变化回调
  onChange: (state: CropBoxState) => void;
  // 容器尺寸（用于计算缩放比例）
  containerWidth?: number;
  containerHeight?: number;
  // 是否禁用
  disabled?: boolean;
  // 最小裁剪尺寸
  minWidth?: number;
  minHeight?: number;
}

// 拖拽类型
type DragType = 'move' | 'n' | 's' | 'e' | 'w' | 'ne' | 'nw' | 'se' | 'sw' | null;

const CropBox: React.FC<CropBoxProps> = ({
  imageWidth,
  imageHeight,
  cropState,
  onChange,
  containerWidth = 400,
  containerHeight = 300,
  disabled = false,
  minWidth = 10,
  minHeight = 10,
}) => {
  const containerRef = useRef<HTMLDivElement>(null);
  const [dragType, setDragType] = useState<DragType>(null);
  const [dragStart, setDragStart] = useState({ x: 0, y: 0 });
  const [initialState, setInitialState] = useState<CropBoxState>(cropState);

  // 计算缩放比例
  const scale = Math.min(
    containerWidth / imageWidth,
    containerHeight / imageHeight
  );

  // 实际显示尺寸
  const displayWidth = imageWidth * scale;
  const displayHeight = imageHeight * scale;

  // 裁剪框在显示坐标系中的位置
  const displayCrop = {
    left: cropState.left * scale,
    top: cropState.top * scale,
    width: cropState.width * scale,
    height: cropState.height * scale,
  };

  // 约束裁剪框在图片边界内
  const constrainCrop = useCallback((state: CropBoxState): CropBoxState => {
    let { left, top, width, height } = state;

    // 确保尺寸不小于最小值
    width = Math.max(minWidth, width);
    height = Math.max(minHeight, height);

    // 确保尺寸不超过图片
    width = Math.min(width, imageWidth);
    height = Math.min(height, imageHeight);

    // 确保位置在边界内
    left = Math.max(0, Math.min(left, imageWidth - width));
    top = Math.max(0, Math.min(top, imageHeight - height));

    return { left, top, width, height };
  }, [imageWidth, imageHeight, minWidth, minHeight]);

  // 开始拖拽
  const handleMouseDown = useCallback((e: React.MouseEvent, type: DragType) => {
    if (disabled) return;
    e.preventDefault();
    e.stopPropagation();

    setDragType(type);
    setDragStart({ x: e.clientX, y: e.clientY });
    setInitialState(cropState);
  }, [disabled, cropState]);

  // 拖拽中
  const handleMouseMove = useCallback((e: MouseEvent) => {
    if (!dragType) return;

    const deltaX = (e.clientX - dragStart.x) / scale;
    const deltaY = (e.clientY - dragStart.y) / scale;

    let newState = { ...initialState };

    switch (dragType) {
      case 'move':
        newState.left = initialState.left + deltaX;
        newState.top = initialState.top + deltaY;
        break;
      case 'n':
        newState.top = initialState.top + deltaY;
        newState.height = initialState.height - deltaY;
        break;
      case 's':
        newState.height = initialState.height + deltaY;
        break;
      case 'e':
        newState.width = initialState.width + deltaX;
        break;
      case 'w':
        newState.left = initialState.left + deltaX;
        newState.width = initialState.width - deltaX;
        break;
      case 'ne':
        newState.top = initialState.top + deltaY;
        newState.height = initialState.height - deltaY;
        newState.width = initialState.width + deltaX;
        break;
      case 'nw':
        newState.top = initialState.top + deltaY;
        newState.height = initialState.height - deltaY;
        newState.left = initialState.left + deltaX;
        newState.width = initialState.width - deltaX;
        break;
      case 'se':
        newState.height = initialState.height + deltaY;
        newState.width = initialState.width + deltaX;
        break;
      case 'sw':
        newState.height = initialState.height + deltaY;
        newState.left = initialState.left + deltaX;
        newState.width = initialState.width - deltaX;
        break;
    }

    onChange(constrainCrop(newState));
  }, [dragType, dragStart, initialState, scale, onChange, constrainCrop]);

  // 结束拖拽
  const handleMouseUp = useCallback(() => {
    setDragType(null);
  }, []);

  // 绑定全局鼠标事件
  useEffect(() => {
    if (dragType) {
      window.addEventListener('mousemove', handleMouseMove);
      window.addEventListener('mouseup', handleMouseUp);
      return () => {
        window.removeEventListener('mousemove', handleMouseMove);
        window.removeEventListener('mouseup', handleMouseUp);
      };
    }
  }, [dragType, handleMouseMove, handleMouseUp]);

  // 手柄样式
  const handleStyle: React.CSSProperties = {
    position: 'absolute',
    width: 10,
    height: 10,
    background: '#1890ff',
    border: '1px solid #fff',
    borderRadius: 2,
  };

  // 边缘手柄样式
  const edgeHandleStyle: React.CSSProperties = {
    position: 'absolute',
    background: 'transparent',
  };

  return (
    <div
      ref={containerRef}
      style={{
        position: 'absolute',
        top: 0,
        left: 0,
        width: '100%',
        height: '100%',
        overflow: 'visible',
      }}
    >
      {/* 遮罩层 - 上 */}
      <div
        style={{
          position: 'absolute',
          left: 0,
          top: 0,
          width: '100%',
          height: displayCrop.top,
          background: 'rgba(0, 0, 0, 0.5)',
          pointerEvents: 'none',
        }}
      />
      {/* 遮罩层 - 下 */}
      <div
        style={{
          position: 'absolute',
          left: 0,
          top: displayCrop.top + displayCrop.height,
          width: '100%',
          height: `calc(100% - ${displayCrop.top + displayCrop.height}px)`,
          background: 'rgba(0, 0, 0, 0.5)',
          pointerEvents: 'none',
        }}
      />
      {/* 遮罩层 - 左 */}
      <div
        style={{
          position: 'absolute',
          left: 0,
          top: displayCrop.top,
          width: displayCrop.left,
          height: displayCrop.height,
          background: 'rgba(0, 0, 0, 0.5)',
          pointerEvents: 'none',
        }}
      />
      {/* 遮罩层 - 右 */}
      <div
        style={{
          position: 'absolute',
          left: displayCrop.left + displayCrop.width,
          top: displayCrop.top,
          width: `calc(100% - ${displayCrop.left + displayCrop.width}px)`,
          height: displayCrop.height,
          background: 'rgba(0, 0, 0, 0.5)',
          pointerEvents: 'none',
        }}
      />

      {/* 裁剪框 */}
      <div
        style={{
          position: 'absolute',
          left: displayCrop.left,
          top: displayCrop.top,
          width: displayCrop.width,
          height: displayCrop.height,
          border: '2px dashed #1890ff',
          boxSizing: 'border-box',
          cursor: disabled ? 'default' : 'move',
        }}
        onMouseDown={(e) => handleMouseDown(e, 'move')}
      >
        {/* 尺寸标签 */}
        <div
          style={{
            position: 'absolute',
            bottom: -24,
            left: '50%',
            transform: 'translateX(-50%)',
            background: 'rgba(0, 0, 0, 0.7)',
            color: '#fff',
            padding: '2px 8px',
            borderRadius: 4,
            fontSize: 12,
            whiteSpace: 'nowrap',
          }}
        >
          {Math.round(cropState.width)} × {Math.round(cropState.height)}
        </div>

        {!disabled && (
          <>
            {/* 角落手柄 */}
            <div
              style={{ ...handleStyle, left: -5, top: -5, cursor: 'nw-resize' }}
              onMouseDown={(e) => handleMouseDown(e, 'nw')}
            />
            <div
              style={{ ...handleStyle, right: -5, top: -5, cursor: 'ne-resize' }}
              onMouseDown={(e) => handleMouseDown(e, 'ne')}
            />
            <div
              style={{ ...handleStyle, left: -5, bottom: -5, cursor: 'sw-resize' }}
              onMouseDown={(e) => handleMouseDown(e, 'sw')}
            />
            <div
              style={{ ...handleStyle, right: -5, bottom: -5, cursor: 'se-resize' }}
              onMouseDown={(e) => handleMouseDown(e, 'se')}
            />

            {/* 边缘手柄 */}
            <div
              style={{
                ...edgeHandleStyle,
                left: '50%',
                top: -5,
                width: 20,
                height: 10,
                marginLeft: -10,
                cursor: 'n-resize',
              }}
              onMouseDown={(e) => handleMouseDown(e, 'n')}
            >
              <div style={{ ...handleStyle, left: 5, top: 0 }} />
            </div>
            <div
              style={{
                ...edgeHandleStyle,
                left: '50%',
                bottom: -5,
                width: 20,
                height: 10,
                marginLeft: -10,
                cursor: 's-resize',
              }}
              onMouseDown={(e) => handleMouseDown(e, 's')}
            >
              <div style={{ ...handleStyle, left: 5, top: 0 }} />
            </div>
            <div
              style={{
                ...edgeHandleStyle,
                left: -5,
                top: '50%',
                width: 10,
                height: 20,
                marginTop: -10,
                cursor: 'w-resize',
              }}
              onMouseDown={(e) => handleMouseDown(e, 'w')}
            >
              <div style={{ ...handleStyle, left: 0, top: 5 }} />
            </div>
            <div
              style={{
                ...edgeHandleStyle,
                right: -5,
                top: '50%',
                width: 10,
                height: 20,
                marginTop: -10,
                cursor: 'e-resize',
              }}
              onMouseDown={(e) => handleMouseDown(e, 'e')}
            >
              <div style={{ ...handleStyle, left: 0, top: 5 }} />
            </div>
          </>
        )}
      </div>
    </div>
  );
};

