/**
 * 图片处理预设管理 Hook
 */
export function useImagePresets() {
  // 自定义预设
  const [customPresets, setCustomPresets] = useState<Preset[]>([]);

  // 从 localStorage 加载自定义预设
  useEffect(() => {
    try {
      const stored = localStorage.getItem(STORAGE_KEY);
      if (stored) {
        const parsed = JSON.parse(stored);
        if (Array.isArray(parsed)) {
          setCustomPresets(parsed);
        }
      }
    } catch (error) {
      console.error('Failed to load custom presets:', error);
    }
  }, []);

  // 保存自定义预设到 localStorage
  const saveToStorage = useCallback((presets: Preset[]) => {
    try {
      localStorage.setItem(STORAGE_KEY, JSON.stringify(presets));
    } catch (error) {
      console.error('Failed to save custom presets:', error);
    }
  }, []);

  /**
   * 获取指定工具类型的所有预设
   */
  const getPresets = useCallback((toolType: ImageToolType): Preset[] => {
    const builtinForTool = BUILTIN_PRESETS.filter(p => p.toolType === toolType);
    const customForTool = customPresets.filter(p => p.toolType === toolType);
    return [...builtinForTool, ...customForTool];
  }, [customPresets]);

  /**
   * 获取所有预设
   */
  const allPresets = useMemo(() => {
    return [...BUILTIN_PRESETS, ...customPresets];
  }, [customPresets]);

  /**
   * 应用预设，返回预设的选项
   */
  const applyPreset = useCallback((preset: Preset): ProcessOptions => {
    return { ...preset.options };
  }, []);

  /**
   * 保存当前设置为自定义预设
   */
  const saveCustomPreset = useCallback((
    name: string,
    description: string,
    toolType: ImageToolType,
    options: ProcessOptions
  ): Preset => {
    const newPreset: Preset = {
      id: generateId(),
      name,
      description,
      category: 'custom',
      toolType,
      options: { ...options },
    };

    const updatedPresets = [...customPresets, newPreset];
    setCustomPresets(updatedPresets);
    saveToStorage(updatedPresets);

    return newPreset;
  }, [customPresets, saveToStorage]);

  /**
   * 删除自定义预设
   */
  const deleteCustomPreset = useCallback((id: string): boolean => {
    const preset = customPresets.find(p => p.id === id);
    if (!preset) {
      return false;
    }

    const updatedPresets = customPresets.filter(p => p.id !== id);
    setCustomPresets(updatedPresets);
    saveToStorage(updatedPresets);

    return true;
  }, [customPresets, saveToStorage]);

  /**
   * 更新自定义预设
   */
  const updateCustomPreset = useCallback((
    id: string,
    updates: Partial<Omit<Preset, 'id' | 'category'>>
  ): boolean => {
    const index = customPresets.findIndex(p => p.id === id);
    if (index === -1) {
      return false;
    }

    const updatedPresets = [...customPresets];
    updatedPresets[index] = {
      ...updatedPresets[index],
      ...updates,
    };

    setCustomPresets(updatedPresets);
    saveToStorage(updatedPresets);

    return true;
  }, [customPresets, saveToStorage]);

  /**
   * 根据 ID 获取预设
   */
  const getPresetById = useCallback((id: string): Preset | undefined => {
    return allPresets.find(p => p.id === id);
  }, [allPresets]);

  /**
   * 清空所有自定义预设
   */
  const clearCustomPresets = useCallback(() => {
    setCustomPresets([]);
    saveToStorage([]);
  }, [saveToStorage]);

  return {
    // 状态
    builtinPresets: BUILTIN_PRESETS,
    customPresets,
    allPresets,

    // 方法
    getPresets,
    applyPreset,
    saveCustomPreset,
    deleteCustomPreset,
    updateCustomPreset,
    getPresetById,
    clearCustomPresets,
  };
}

export default useImagePresets;

/**
 * LAN Transfer Assistant - QR Code Scanner Component
 * 
 * 使用 ZXing 库实现二维码扫描
 */

package com.mucheng.notes.presentation.components

import android.Manifest
import android.content.pm.PackageManager
import android.util.Log
import androidx.activity.compose.rememberLauncherForActivityResult
import androidx.activity.result.contract.ActivityResultContracts
import androidx.compose.foundation.background
import androidx.compose.foundation.layout.*
import androidx.compose.foundation.shape.RoundedCornerShape
import androidx.compose.material.icons.Icons
import androidx.compose.material.icons.filled.Close
import androidx.compose.material.icons.filled.FlashOff
import androidx.compose.material.icons.filled.FlashOn
import androidx.compose.material3.*
import androidx.compose.runtime.*
import androidx.compose.ui.Alignment
import androidx.compose.ui.Modifier
import androidx.compose.ui.draw.clip
import androidx.compose.ui.graphics.Color
import androidx.compose.ui.platform.LocalContext
import androidx.compose.ui.unit.dp
import androidx.compose.ui.viewinterop.AndroidView
import androidx.compose.ui.window.Dialog
import androidx.compose.ui.window.DialogProperties
import androidx.core.content.ContextCompat
import com.journeyapps.barcodescanner.BarcodeCallback
import com.journeyapps.barcodescanner.BarcodeResult
import com.journeyapps.barcodescanner.DecoratedBarcodeView

private const val TAG = "QRScanner"

/**
 * 二维码扫描对话框
 */
@Composable
fun QRScannerDialog(
    onDismiss: () -> Unit,
    onScanned: (String) -> Unit
) {
    val context = LocalContext.current
    var hasPermission by remember {
        mutableStateOf(
            ContextCompat.checkSelfPermission(context, Manifest.permission.CAMERA) == PackageManager.PERMISSION_GRANTED
        )
    }
    var flashEnabled by remember { mutableStateOf(false) }
    var scannerView by remember { mutableStateOf<DecoratedBarcodeView?>(null) }

    val permissionLauncher = rememberLauncherForActivityResult(
        ActivityResultContracts.RequestPermission()
    ) { isGranted ->
        hasPermission = isGranted
    }

    LaunchedEffect(Unit) {
        if (!hasPermission) {
            permissionLauncher.launch(Manifest.permission.CAMERA)
        }
    }

    Dialog(
        onDismissRequest = onDismiss,
        properties = DialogProperties(
            dismissOnBackPress = true,
            dismissOnClickOutside = false,
            usePlatformDefaultWidth = false
        )
    ) {
        Surface(
            modifier = Modifier
                .fillMaxWidth(0.9f)
                .aspectRatio(0.8f),
            shape = RoundedCornerShape(16.dp),
            color = MaterialTheme.colorScheme.surface
        ) {
            Column(
                modifier = Modifier.fillMaxSize()
            ) {
                // 顶部栏
                Row(
                    modifier = Modifier
                        .fillMaxWidth()
                        .padding(8.dp),
                    horizontalArrangement = Arrangement.SpaceBetween,
                    verticalAlignment = Alignment.CenterVertically
                ) {
                    Text(
                        text = "扫描二维码",
                        style = MaterialTheme.typography.titleMedium,
                        modifier = Modifier.padding(start = 8.dp)
                    )
                    Row {
                        // 闪光灯按钮
                        IconButton(
                            onClick = {
                                flashEnabled = !flashEnabled
                                scannerView?.let { view ->
                                    if (flashEnabled) {
                                        view.setTorchOn()
                                    } else {
                                        view.setTorchOff()
                                    }
                                }
                            }
                        ) {
                            Icon(
                                imageVector = if (flashEnabled) Icons.Default.FlashOn else Icons.Default.FlashOff,
                                contentDescription = if (flashEnabled) "关闭闪光灯" else "打开闪光灯"
                            )
                        }
                        // 关闭按钮
                        IconButton(onClick = onDismiss) {
                            Icon(Icons.Default.Close, contentDescription = "关闭")
                        }
                    }
                }

                // 扫描区域
                Box(
                    modifier = Modifier
                        .fillMaxSize()
                        .padding(16.dp)
                        .clip(RoundedCornerShape(8.dp))
                        .background(Color.Black),
                    contentAlignment = Alignment.Center
                ) {
                    if (hasPermission) {
                        AndroidView(
                            factory = { ctx ->
                                DecoratedBarcodeView(ctx).apply {
                                    scannerView = this

                                    // 配置扫描
                                    decodeContinuous(object : BarcodeCallback {
                                        override fun barcodeResult(result: BarcodeResult?) {
                                            result?.text?.let { text ->
                                                Log.d(TAG, "Scanned: $text")
                                                // 暂停扫描防止重复
                                                pause()
                                                onScanned(text)
                                            }
                                        }
                                    })

                                    // 开始预览
                                    resume()
                                }
                            },
                            modifier = Modifier.fillMaxSize(),
                            onRelease = { view ->
                                view.pause()
                            }
                        )

                        // 扫描框指示器
                        ScannerOverlay()
                    } else {
                        Column(
                            horizontalAlignment = Alignment.CenterHorizontally,
                            verticalArrangement = Arrangement.Center
                        ) {
                            Text(
                                text = "需要相机权限",
                                style = MaterialTheme.typography.bodyLarge,
                                color = Color.White
                            )
                            Spacer(modifier = Modifier.height(16.dp))
                            Button(
                                onClick = { permissionLauncher.launch(Manifest.permission.CAMERA) }
                            ) {
                                Text("授予权限")
                            }
                        }
                    }
                }
            }
        }
    }

    // 生命周期管理
    DisposableEffect(Unit) {
        onDispose {
            scannerView?.pause()
        }
    }
}

/**
 * 扫描框覆盖层
