    fun loadNote(noteId: String) {
        viewModelScope.launch {
            _uiState.value = _uiState.value.copy(isLoading = true)
            try {
                val item = itemRepository.getById(noteId)
                if (item != null) {
                    val payload = try {
                        json.decodeFromString<ExcelNotePayload>(item.payload)
                    } catch (e: Exception) {
                        android.util.Log.e("ExcelDetailVM", "Full parse failed, trying lenient: ${e.message}")
                        tryLenientParse(item.payload)
                    }
                    if (payload != null) {
                        // 修复：如果 sheets 为空，创建默认工作表
                        val fixedPayload = if (payload.sheets.isEmpty()) {
                            android.util.Log.w("ExcelDetailVM", "Sheets is empty, creating default sheet")
                            payload.copy(
                                sheets = listOf(
                                    ExcelSheet(
                                        id = java.util.UUID.randomUUID().toString(),
                                        name = "Sheet1",
                                        rows = emptyList(),
                                        columnWidths = emptyList(),
                                        rowHeights = emptyList()
                                    )
                                ),
                                activeSheetIndex = 0
                            )
                        } else {
                            payload
                        }

                        val note = ExcelNoteItem(
                            id = item.id,
                            payload = fixedPayload,
                            updatedAt = item.updatedTime
                        )
                        _uiState.value = _uiState.value.copy(
                            isLoading = false,
                            note = note,
                            selectedSheetIndex = fixedPayload.activeSheetIndex
                        )
                    } else {
                        _uiState.value = _uiState.value.copy(
                            isLoading = false,
                            error = "无法解析表格数据"
                        )
                    }
                } else {
                    _uiState.value = _uiState.value.copy(
                        isLoading = false,
                        error = "笔记不存在"
                    )
                }
            } catch (e: Exception) {
                android.util.Log.e("ExcelDetailVM", "loadNote failed: ${e.message}")
                _uiState.value = _uiState.value.copy(
                    isLoading = false,
                    error = e.message
                )
            }
        }
    }

    @Suppress("UNCHECKED_CAST")
    private fun tryLenientParse(payloadStr: String): ExcelNotePayload? {
        return try {
            val element = json.parseToJsonElement(payloadStr).jsonObject
            val title = element["title"]?.jsonPrimitive?.contentOrNull ?: ""
            val sheets = (element["sheets"]?.jsonArray ?: emptyList()).mapNotNull { sheetEl ->
                try {
                    val s = sheetEl.jsonObject
                    val rows = (s["rows"]?.jsonArray ?: emptyList()).mapNotNull { rowEl ->
                        try {
                            val r = rowEl.jsonObject
                            val cells = (r["cells"]?.jsonArray ?: emptyList()).mapNotNull { cellEl ->
                                try {
                                    val c = cellEl.jsonObject
                                    ExcelCell(
                                        columnIndex = c["column_index"]?.jsonPrimitive?.intOrNull ?: 0,
                                        value = c["value"],
                                        formula = c["formula"]?.jsonPrimitive?.contentOrNull,
                                        style = c["style"]
                                    )
                                } catch (_: Exception) { null }
                            }
                            ExcelRow(
                                rowIndex = r["row_index"]?.jsonPrimitive?.intOrNull ?: 0,
                                cells = cells
                            )
                        } catch (_: Exception) { null }
                    }
                    ExcelSheet(
                        id = s["id"]?.jsonPrimitive?.contentOrNull ?: "",
                        name = s["name"]?.jsonPrimitive?.contentOrNull ?: "",
                        rows = rows,
                        columnWidths = s["column_widths"]?.jsonArray ?: emptyList(),
                        rowHeights = s["row_heights"]?.jsonArray ?: emptyList(),
                        frozenRows = s["frozen_rows"]?.jsonPrimitive?.intOrNull ?: 0,
                        frozenColumns = s["frozen_columns"]?.jsonPrimitive?.intOrNull ?: 0,
                        mergedCells = (s["merged_cells"]?.jsonArray ?: emptyList()).mapNotNull { mEl ->
                            try {
                                val m = mEl.jsonObject
                                MergedCell(
                                    startRow = m["start_row"]?.jsonPrimitive?.intOrNull ?: 0,
                                    startCol = m["start_col"]?.jsonPrimitive?.intOrNull ?: 0,
                                    endRow = m["end_row"]?.jsonPrimitive?.intOrNull ?: 0,
                                    endCol = m["end_col"]?.jsonPrimitive?.intOrNull ?: 0
                                )
                            } catch (_: Exception) { null }
                        }
                    )
                } catch (_: Exception) { null }
            }
            ExcelNotePayload(
                title = title,
                sheets = sheets,
                activeSheetIndex = element["active_sheet_index"]?.jsonPrimitive?.intOrNull ?: 0
            )
        } catch (e: Exception) {
            android.util.Log.e("ExcelDetailVM", "Lenient parse failed: ${e.message}")
            null
        }
    }

    /**
     * 切换工作表
     */
    fun selectSheet(index: Int) {
        _uiState.value = _uiState.value.copy(selectedSheetIndex = index)
    }

    /**
     * 选择单元格
     */
    fun selectCell(row: Int, col: Int) {
        _uiState.value = _uiState.value.copy(
            selectedCell = CellPosition(row, col)
        )
    }

    /**
     * 更新单元格值
     */
    fun updateCell(row: Int, col: Int, value: String) {
        val note = _uiState.value.note ?: return
        val sheetIndex = _uiState.value.selectedSheetIndex

        viewModelScope.launch {
            try {
                val sheets = note.payload.sheets.toMutableList()
                if (sheetIndex >= sheets.size) return@launch

                val sheet = sheets[sheetIndex]
                val rows = sheet.rows.toMutableList()

                // 查找或创建行
                val rowIndex = rows.indexOfFirst { it.rowIndex == row }
                val rowData = if (rowIndex >= 0) {
                    rows[rowIndex]
                } else {
                    ExcelRow(rowIndex = row, cells = emptyList()).also { rows.add(it) }
                }

                // 更新单元格
                val cells = rowData.cells.toMutableList()
                val cellIndex = cells.indexOfFirst { it.columnIndex == col }
                val cellValue = if (value.isEmpty()) null else {
                    value.toDoubleOrNull()?.let { JsonPrimitive(it) }
                        ?: JsonPrimitive(value)
                }

                val newCell = ExcelCell(
                    columnIndex = col,
                    value = cellValue,
                    formula = if (value.startsWith("=")) value else null,
                    style = cells.getOrNull(cellIndex)?.style
                )

                if (cellIndex >= 0) {
                    cells[cellIndex] = newCell
                } else {
                    cells.add(newCell)
                }

                // 更新行
                val newRow = rowData.copy(cells = cells)
                if (rowIndex >= 0) {
                    rows[rowIndex] = newRow
                }

                // 更新工作表
                sheets[sheetIndex] = sheet.copy(rows = rows)

                // 更新 payload
                val newPayload = note.payload.copy(sheets = sheets)
                val payloadJson = json.encodeToString(ExcelNotePayload.serializer(), newPayload)

                // 保存到数据库
                itemRepository.update(note.id, payloadJson)

                // 更新 UI 状态
                val newNote = note.copy(payload = newPayload)
                _uiState.value = _uiState.value.copy(note = newNote)
            } catch (e: Exception) {
                _uiState.value = _uiState.value.copy(error = e.message)
            }
        }
    }

    /**
     * 获取单元格显示值
     */
    fun getCellDisplayValue(sheet: ExcelSheet, row: Int, col: Int): String {
        val rowData = sheet.rows.find { it.rowIndex == row } ?: return ""
        val cell = rowData.cells.find { it.columnIndex == col } ?: return ""

        val value = cell.value ?: return ""
        return when (value) {
            is JsonNull -> ""
            is JsonPrimitive -> {
                value.doubleOrNull?.toString()
                    ?: value.booleanOrNull?.let { if (it) "TRUE" else "FALSE" }
                    ?: value.content
            }
            else -> value.toString()
        }
    }

    /**
     * 清除错误
     */
    fun clearError() {
        _uiState.value = _uiState.value.copy(error = null)
    }
}

/**
 * Excel 详情 UI 状态
 */
data class ExcelDetailUiState(
    val isLoading: Boolean = false,
    val note: ExcelNoteItem? = null,
    val selectedSheetIndex: Int = 0,
    val selectedCell: CellPosition = CellPosition(0, 0),
    val error: String? = null
)

import React, { useState, useCallback } from 'react';
import { Layout, Menu, Button, List, Empty, Modal, Input, message, Dropdown, Space, Typography, Tabs, Tooltip } from 'antd';
import {
  PlusOutlined,
  DeleteOutlined,
  EditOutlined,
  MoreOutlined,
  NodeIndexOutlined,
  ApartmentOutlined,
  HighlightOutlined,
  FolderOutlined,
  SearchOutlined,
} from '@ant-design/icons';
import { useDiagrams, Diagram } from '../hooks/useDiagrams';
import { DiagramType } from '@shared/types';
import MindMapEditor from './MindMapEditor';
import FlowchartEditor from './FlowchartEditor';
import WhiteboardEditor from './WhiteboardEditor';

const { Sider, Content } = Layout;
const { Text, Title } = Typography;

// 图表类型配置
const DIAGRAM_TYPES: { key: DiagramType; label: string; icon: React.ReactNode }[] = [
  { key: 'mindmap', label: '脑图', icon: <NodeIndexOutlined /> },
  { key: 'flowchart', label: '流程图', icon: <ApartmentOutlined /> },
  { key: 'whiteboard', label: '白板', icon: <HighlightOutlined /> },
];

const DiagramPanel: React.FC = () => {
  const { diagrams, loading, createDiagram, updateDiagram, deleteDiagram, getDiagramsByType } = useDiagrams();
  const [selectedType, setSelectedType] = useState<DiagramType>('mindmap');
  const [selectedDiagram, setSelectedDiagram] = useState<Diagram | null>(null);
  const [isCreating, setIsCreating] = useState(false);
  const [newName, setNewName] = useState('');
  const [isRenaming, setIsRenaming] = useState(false);
  const [renameId, setRenameId] = useState<string | null>(null);
  const [renameName, setRenameName] = useState('');
  const [searchText, setSearchText] = useState('');

  // 获取当前类型的图表列表
  const currentDiagrams = getDiagramsByType(selectedType).filter(d => 
    !searchText || d.payload.name.toLowerCase().includes(searchText.toLowerCase())
  );

  // 创建新图表
  const handleCreate = async () => {
    if (!newName.trim()) {
      message.warning('请输入名称');
      return;
    }
    const diagram = await createDiagram(newName.trim(), selectedType);
    if (diagram) {
      setSelectedDiagram(diagram);
      message.success('创建成功');
    } else {
      message.error('创建失败，请重试');
    }
    setIsCreating(false);
    setNewName('');
  };

  // 重命名
  const handleRename = async () => {
    if (!renameId || !renameName.trim()) return;
    const success = await updateDiagram(renameId, { name: renameName.trim() });
    if (success) {
      message.success('重命名成功');
      if (selectedDiagram?.id === renameId) {
        setSelectedDiagram(prev => prev ? { ...prev, payload: { ...prev.payload, name: renameName.trim() } } : null);
      }
    }
    setIsRenaming(false);
    setRenameId(null);
    setRenameName('');
  };

  // 删除
  const handleDelete = async (id: string) => {
    Modal.confirm({
      title: '确认删除',
      content: '删除后可在回收站恢复，确定要删除吗？',
      okText: '删除',
      okType: 'danger',
      cancelText: '取消',
      onOk: async () => {
        const success = await deleteDiagram(id);
        if (success) {
          message.success('已删除');
          if (selectedDiagram?.id === id) {
            setSelectedDiagram(null);
          }
        }
      },
    });
  };

  // 保存图表数据
  const handleSave = useCallback(async (data: string) => {
    if (!selectedDiagram) return;
    await updateDiagram(selectedDiagram.id, { data });
  }, [selectedDiagram, updateDiagram]);

  // 渲染编辑器
  const renderEditor = () => {
    if (!selectedDiagram) {
      return (
        <div style={{ 
          height: '100%', 
          display: 'flex', 
          alignItems: 'center', 
          justifyContent: 'center',
          flexDirection: 'column',
          gap: 16,
        }}>
          <Empty description="选择或创建一个图表开始编辑" />
          <Button type="primary" icon={<PlusOutlined />} onClick={() => setIsCreating(true)}>
            新建{DIAGRAM_TYPES.find(t => t.key === selectedType)?.label}
          </Button>
        </div>
      );
    }

    const commonProps = {
      data: selectedDiagram.payload.data,
      onSave: handleSave,
    };

    switch (selectedDiagram.payload.diagram_type) {
      case 'mindmap':
        return <MindMapEditor {...commonProps} />;
      case 'flowchart':
        return <FlowchartEditor {...commonProps} />;
      case 'whiteboard':
        return <WhiteboardEditor {...commonProps} />;
      default:
        return <Empty description="未知图表类型" />;
    }
  };

  // 列表项菜单
  const getItemMenu = (diagram: Diagram) => ({
    items: [
      {
        key: 'rename',
        icon: <EditOutlined />,
        label: '重命名',
        onClick: () => {
          setRenameId(diagram.id);
          setRenameName(diagram.payload.name);
          setIsRenaming(true);
        },
      },
      {
        key: 'delete',
        icon: <DeleteOutlined />,
        label: '删除',
        danger: true,
        onClick: () => handleDelete(diagram.id),
      },
    ],
  });

  return (
    <Layout style={{ height: '100%' }}>
      {/* 左侧列表 */}
      <Sider width={280} style={{ background: '#fafafa', borderRight: '1px solid #f0f0f0' }} className="diagram-sider">
        {/* 类型切换 */}
        <div style={{ padding: '12px', borderBottom: '1px solid #f0f0f0' }}>
          <Tabs
            activeKey={selectedType}
            onChange={(key) => {
              setSelectedType(key as DiagramType);
              setSelectedDiagram(null);
            }}
            size="small"
            items={DIAGRAM_TYPES.map(t => ({
              key: t.key,
              label: (
                <span>
                  {t.icon}
                  <span style={{ marginLeft: 4 }}>{t.label}</span>
                </span>
              ),
            }))}
          />
        </div>

        {/* 搜索和新建 */}
        <div style={{ padding: '8px 12px', borderBottom: '1px solid #f0f0f0' }}>
          <Space.Compact style={{ width: '100%' }}>
            <Input
              placeholder="搜索..."
              prefix={<SearchOutlined />}
              value={searchText}
              onChange={e => setSearchText(e.target.value)}
              allowClear
            />
            <Tooltip title={`新建${DIAGRAM_TYPES.find(t => t.key === selectedType)?.label}`}>
              <Button icon={<PlusOutlined />} onClick={() => setIsCreating(true)} />
            </Tooltip>
          </Space.Compact>
        </div>

        {/* 图表列表 */}
        <div style={{ flex: 1, overflow: 'auto', padding: '8px 0' }}>
          {currentDiagrams.length === 0 ? (
            <Empty 
              image={Empty.PRESENTED_IMAGE_SIMPLE} 
              description={searchText ? '没有找到匹配的图表' : '暂无图表'} 
              style={{ marginTop: 40 }}
            />
          ) : (
            <List
              dataSource={currentDiagrams}
              renderItem={diagram => (
                <List.Item
                  style={{
                    padding: '8px 12px',
                    cursor: 'pointer',
                    background: selectedDiagram?.id === diagram.id ? '#e6f4ff' : 'transparent',
                    borderLeft: selectedDiagram?.id === diagram.id ? '3px solid #1890ff' : '3px solid transparent',
                  }}
                  onClick={() => setSelectedDiagram(diagram)}
                >
                  <div style={{ flex: 1, minWidth: 0 }}>
                    <Text ellipsis style={{ display: 'block' }}>
                      {DIAGRAM_TYPES.find(t => t.key === diagram.payload.diagram_type)?.icon}
                      <span style={{ marginLeft: 8 }}>{diagram.payload.name}</span>
                    </Text>
                    <Text type="secondary" style={{ fontSize: 12 }}>
                      {new Date(diagram.updated_time).toLocaleString()}
                    </Text>
                  </div>
                  <Dropdown menu={getItemMenu(diagram)} trigger={['click']}>
                    <Button 
                      type="text" 
                      size="small" 
                      icon={<MoreOutlined />}
                      onClick={e => e.stopPropagation()}
                    />
                  </Dropdown>
                </List.Item>
              )}
            />
          )}
        </div>
      </Sider>

      {/* 右侧编辑器 */}
      <Content style={{ background: '#fff', position: 'relative' }}>
        {renderEditor()}
      </Content>

      {/* 新建对话框 */}
      <Modal
        title={`新建${DIAGRAM_TYPES.find(t => t.key === selectedType)?.label}`}
        open={isCreating}
        onOk={handleCreate}
        onCancel={() => { setIsCreating(false); setNewName(''); }}
        okText="创建"
        cancelText="取消"
      >
        <Input
          placeholder="请输入名称"
          value={newName}
          onChange={e => setNewName(e.target.value)}
          onPressEnter={handleCreate}
          autoFocus
        />
      </Modal>

      {/* 重命名对话框 */}
      <Modal
        title="重命名"
        open={isRenaming}
        onOk={handleRename}
        onCancel={() => { setIsRenaming(false); setRenameId(null); setRenameName(''); }}
        okText="确定"
        cancelText="取消"
      >
        <Input
          placeholder="请输入新名称"
          value={renameName}
          onChange={e => setRenameName(e.target.value)}
          onPressEnter={handleRename}
          autoFocus
        />
      </Modal>
    </Layout>
  );
};

export default DiagramPanel;

