/**
 * 文件夹数据模型
 */
data class FolderItem(
    val id: String,
    val name: String,
    val parentId: String?,
    val itemCount: Int = 0
)

/**
 * 文件夹树组件
 */
@Composable
fun FolderTree(
    folders: List<FolderItem>,
    selectedFolderId: String?,
    onFolderSelect: (String?) -> Unit,
    onCreateFolder: (String?) -> Unit,
    onEditFolder: ((String) -> Unit)? = null,
    onDeleteFolder: ((String) -> Unit)? = null,
    modifier: Modifier = Modifier,
    showAllOption: Boolean = true,
    allOptionLabel: String = "全部"
) {
    val rootFolders = folders.filter { it.parentId == null }

    Column(modifier = modifier) {
        // "全部" 选项
        if (showAllOption) {
            FolderTreeItem(
                name = allOptionLabel,
                isSelected = selectedFolderId == null,
                isExpanded = false,
                hasChildren = false,
                level = 0,
                onClick = { onFolderSelect(null) },
                onExpandToggle = {},
                onEdit = null,
                onDelete = null,
                onAddSubfolder = null
            )
        }

        // 文件夹列表
        rootFolders.forEach { folder ->
            FolderTreeNode(
                folder = folder,
                allFolders = folders,
                selectedFolderId = selectedFolderId,
                onFolderSelect = onFolderSelect,
                onCreateFolder = onCreateFolder,
                onEditFolder = onEditFolder,
                onDeleteFolder = onDeleteFolder,
                level = 0
            )
        }

        // 添加文件夹按钮
        Row(
            modifier = Modifier
                .fillMaxWidth()
                .clickable { onCreateFolder(null) }
                .padding(horizontal = 16.dp, vertical = 12.dp),
            verticalAlignment = Alignment.CenterVertically
        ) {
            Icon(
                Icons.Default.Add,
                contentDescription = "新建文件夹",
                tint = MaterialTheme.colorScheme.primary,
                modifier = Modifier.size(20.dp)
            )
            Spacer(modifier = Modifier.width(8.dp))
            Text(
                text = "新建文件夹",
                style = MaterialTheme.typography.bodyMedium,
                color = MaterialTheme.colorScheme.primary
            )
        }
    }
}

@Composable
private fun FolderTreeNode(
    folder: FolderItem,
    allFolders: List<FolderItem>,
    selectedFolderId: String?,
    onFolderSelect: (String?) -> Unit,
    onCreateFolder: (String?) -> Unit,
    onEditFolder: ((String) -> Unit)?,
    onDeleteFolder: ((String) -> Unit)?,
    level: Int
) {
    var isExpanded by remember { mutableStateOf(false) }
    val children = allFolders.filter { it.parentId == folder.id }
    val hasChildren = children.isNotEmpty()

    Column {
        FolderTreeItem(
            name = folder.name,
            itemCount = folder.itemCount,
            isSelected = selectedFolderId == folder.id,
            isExpanded = isExpanded,
            hasChildren = hasChildren,
            level = level,
            onClick = { onFolderSelect(folder.id) },
            onExpandToggle = { isExpanded = !isExpanded },
            onEdit = onEditFolder?.let { { it(folder.id) } },
            onDelete = onDeleteFolder?.let { { it(folder.id) } },
            onAddSubfolder = { onCreateFolder(folder.id) }
        )

        AnimatedVisibility(
            visible = isExpanded && hasChildren,
            enter = expandVertically(),
            exit = shrinkVertically()
        ) {
            Column {
                children.forEach { child ->
                    FolderTreeNode(
                        folder = child,
                        allFolders = allFolders,
                        selectedFolderId = selectedFolderId,
                        onFolderSelect = onFolderSelect,
                        onCreateFolder = onCreateFolder,
                        onEditFolder = onEditFolder,
                        onDeleteFolder = onDeleteFolder,
                        level = level + 1
                    )
                }
            }
        }
    }
}

@OptIn(ExperimentalFoundationApi::class)
@Composable
private fun FolderTreeItem(
    name: String,
    itemCount: Int = 0,
    isSelected: Boolean,
    isExpanded: Boolean,
    hasChildren: Boolean,
    level: Int,
    onClick: () -> Unit,
    onExpandToggle: () -> Unit,
    onEdit: (() -> Unit)?,
    onDelete: (() -> Unit)?,
    onAddSubfolder: (() -> Unit)?
) {
    var showMenu by remember { mutableStateOf(false) }

    val backgroundColor = if (isSelected) {
        MaterialTheme.colorScheme.primaryContainer
    } else {
        MaterialTheme.colorScheme.surface
    }

    Box {
        Row(
            modifier = Modifier
                .fillMaxWidth()
                .padding(start = (level * 16).dp)
                .clip(RoundedCornerShape(8.dp))
                .background(backgroundColor)
                .combinedClickable(
                    onClick = onClick,
                    onLongClick = {
                        if (onEdit != null || onDelete != null || onAddSubfolder != null) {
                            showMenu = true
                        }
                    }
                )
                .padding(horizontal = 12.dp, vertical = 10.dp),
            verticalAlignment = Alignment.CenterVertically
        ) {
            // 展开/折叠图标
            if (hasChildren) {
                Icon(
                    imageVector = if (isExpanded) Icons.Default.ExpandMore else Icons.Default.ChevronRight,
                    contentDescription = if (isExpanded) "折叠" else "展开",
                    modifier = Modifier
                        .size(20.dp)
                        .clickable { onExpandToggle() },
                    tint = MaterialTheme.colorScheme.onSurfaceVariant
                )
            } else {
                Spacer(modifier = Modifier.width(20.dp))
            }

            Spacer(modifier = Modifier.width(4.dp))

            // 文件夹图标
            Icon(
                imageVector = if (isExpanded) Icons.Default.FolderOpen else Icons.Default.Folder,
                contentDescription = null,
                modifier = Modifier.size(20.dp),
                tint = if (isSelected) MaterialTheme.colorScheme.primary else MaterialTheme.colorScheme.onSurfaceVariant
            )

            Spacer(modifier = Modifier.width(8.dp))

            // 文件夹名称
            Text(
                text = name,
                style = MaterialTheme.typography.bodyMedium,
                color = if (isSelected) MaterialTheme.colorScheme.onPrimaryContainer else MaterialTheme.colorScheme.onSurface,
                maxLines = 1,
                overflow = TextOverflow.Ellipsis,
                modifier = Modifier.weight(1f)
            )

            // 项目数量
            if (itemCount > 0) {
                Text(
                    text = itemCount.toString(),
                    style = MaterialTheme.typography.bodySmall,
                    color = MaterialTheme.colorScheme.outline
                )
            }
        }

        // 长按菜单
        DropdownMenu(
            expanded = showMenu,
            onDismissRequest = { showMenu = false },
            offset = DpOffset(x = 100.dp, y = 0.dp)
        ) {
            if (onAddSubfolder != null) {
                DropdownMenuItem(
                    text = { Text("添加子文件夹") },
                    onClick = {
                        showMenu = false
                        onAddSubfolder()
                    },
                    leadingIcon = {
                        Icon(Icons.Default.CreateNewFolder, contentDescription = null)
                    }
                )
            }
            if (onEdit != null) {
                DropdownMenuItem(
                    text = { Text("重命名") },
                    onClick = {
                        showMenu = false
                        onEdit()
                    },
                    leadingIcon = {
                        Icon(Icons.Default.Edit, contentDescription = null)
                    }
                )
            }
            if (onDelete != null) {
                DropdownMenuItem(
                    text = { Text("删除", color = MaterialTheme.colorScheme.error) },
                    onClick = {
                        showMenu = false
                        onDelete()
                    },
                    leadingIcon = {
                        Icon(
                            Icons.Default.Delete,
                            contentDescription = null,
                            tint = MaterialTheme.colorScheme.error
                        )
                    }
                )
            }
        }
    }
}

﻿package com.mucheng.notes.presentation.viewmodel

import android.content.Context
import android.content.SharedPreferences
import androidx.lifecycle.ViewModel
import androidx.lifecycle.viewModelScope
import com.mucheng.notes.data.local.entity.ItemEntity
import com.mucheng.notes.data.remote.AIApiClient
import com.mucheng.notes.data.remote.ChatMessage
import com.mucheng.notes.domain.model.ItemType
import com.mucheng.notes.domain.model.payload.AIConversationPayload
import com.mucheng.notes.domain.model.payload.AIMessagePayload
import com.mucheng.notes.domain.repository.ItemRepository
import com.mucheng.notes.presentation.screens.settings.AIChannel
import dagger.hilt.android.lifecycle.HiltViewModel
import dagger.hilt.android.qualifiers.ApplicationContext
import kotlinx.coroutines.Dispatchers
import kotlinx.coroutines.flow.MutableStateFlow
import kotlinx.coroutines.flow.SharingStarted
import kotlinx.coroutines.flow.StateFlow
import kotlinx.coroutines.flow.asStateFlow
import kotlinx.coroutines.flow.flowOn
import kotlinx.coroutines.flow.map
import kotlinx.coroutines.flow.stateIn
import kotlinx.coroutines.launch
import kotlinx.serialization.encodeToString
import kotlinx.serialization.json.Json
import javax.inject.Inject

data class AIUiState(
    val isLoading: Boolean = false,
    val error: String? = null,
    val selectedConversationId: String? = null,
    val isThinking: Boolean = false,
    val streamingMessageId: String? = null,
    val streamingContent: String = ""
)

data class ConversationItem(
    val id: String,
    val title: String,
    val model: String,
    val channelId: String?,
    val systemPrompt: String,
    val temperature: Float,
    val maxTokens: Int,
    val createdAt: Long
)

data class MessageItem(
    val id: String,
    val conversationId: String,
    val role: String,
    val content: String,
    val model: String,
    val tokensUsed: Int?,
    val createdAt: Long
)

@HiltViewModel
class AIViewModel @Inject constructor(
    private val itemRepository: ItemRepository,
    private val aiApiClient: AIApiClient,
    @ApplicationContext private val context: Context
) : ViewModel() {

    private val json = Json { 
        ignoreUnknownKeys = true 
        isLenient = true
        coerceInputValues = true
        encodeDefaults = true
    }

    private val prefs: SharedPreferences by lazy {
        context.getSharedPreferences("app_settings", Context.MODE_PRIVATE)
    }

    private val _uiState = MutableStateFlow(AIUiState())
    val uiState: StateFlow<AIUiState> = _uiState.asStateFlow()

    val conversations: StateFlow<List<ConversationItem>> = itemRepository.getByType(ItemType.AI_CONVERSATION)
        .map { items -> items.mapNotNull { it.toConversationItem() } }
        .flowOn(Dispatchers.IO)
        .stateIn(viewModelScope, SharingStarted.Lazily, emptyList())

    private var _pendingConversation: ConversationItem? = null

    val messages: StateFlow<List<MessageItem>> = itemRepository.getByType(ItemType.AI_MESSAGE)
        .map { items -> items.mapNotNull { it.toMessageItem() } }
        .flowOn(Dispatchers.IO)
        .stateIn(viewModelScope, SharingStarted.Lazily, emptyList())

    private fun getUserChannels(): List<AIChannel> {
        val channelsJson = prefs.getString("ai_channels_json", "") ?: ""
        return if (channelsJson.isNotBlank()) {
            try {
                json.decodeFromString<List<AIChannel>>(channelsJson).filter { it.enabled && it.apiKey.isNotBlank() }
            } catch (e: Exception) { emptyList() }
        } else emptyList()
    }

    private fun findChannelForModel(modelId: String, channelId: String? = null): AIChannel? {
        val channels = getUserChannels()
        // 优先按 channelId 精确匹配（桌面端同步过来的对话带有 channel_id）
        if (!channelId.isNullOrBlank()) {
            val byChannelId = channels.find { it.id == channelId }
            if (byChannelId != null) return byChannelId
        }
        // fallback：按 modelId 匹配
        return channels.find { channel -> channel.models.any { it.id == modelId } }
    }

    fun createConversation(title: String = "新对话", channelId: String? = null, model: String = "gpt-4", systemPrompt: String = "", temperature: Float = 0.7f, maxTokens: Int = 4096) {
        viewModelScope.launch {
            try {
                val payload = AIConversationPayload(title = title, model = model, channelId = channelId, systemPrompt = systemPrompt, temperature = temperature, maxTokens = maxTokens, createdAt = System.currentTimeMillis())
                val item = itemRepository.create(ItemType.AI_CONVERSATION, json.encodeToString(payload))
                _uiState.value = _uiState.value.copy(selectedConversationId = item.id, error = null)
            } catch (e: Exception) {
                e.printStackTrace()
                _uiState.value = _uiState.value.copy(error = "创建对话失败: ${e.message}")
            }
        }
    }

    fun selectConversation(conversationId: String?) {
        _uiState.value = _uiState.value.copy(selectedConversationId = conversationId)
    }

    fun sendMessageWithSettings(content: String, modelId: String, channelId: String?, systemPrompt: String, temperature: Float, maxTokens: Int) {
        val conversationId = _uiState.value.selectedConversationId ?: return
        viewModelScope.launch {
            try {
                // 1. Create user message
                val userPayload = AIMessagePayload(conversationId = conversationId, role = "user", content = content, model = "", tokensUsed = null, createdAt = System.currentTimeMillis())
                val userItem = itemRepository.create(ItemType.AI_MESSAGE, json.encodeToString(userPayload))

                _uiState.value = _uiState.value.copy(isThinking = true, error = null)

                val channel = findChannelForModel(modelId, channelId)
                if (channel == null) {
                    val errorPayload = AIMessagePayload(conversationId = conversationId, role = "assistant", content = "未找到模型对应的 AI 渠道", model = modelId, tokensUsed = null, createdAt = System.currentTimeMillis())
                    itemRepository.create(ItemType.AI_MESSAGE, json.encodeToString(errorPayload))
                    _uiState.value = _uiState.value.copy(isThinking = false)
                    return@launch
                }

                // 2. Prepare history
                // Filter out the just-created message from existing list to avoid duplication if it appeared in the flow
                val historyMessages = messages.value
                    .filter { it.conversationId == conversationId && it.id != userItem.id }
                    .sortedBy { it.createdAt }
                    .map { ChatMessage(role = it.role, content = it.content) }
                    .toMutableList()

                // Add current message (role="user")
                historyMessages.add(ChatMessage(role = "user", content = content))

                val allMessages = mutableListOf<ChatMessage>()
                if (systemPrompt.isNotBlank()) allMessages.add(ChatMessage(role = "system", content = systemPrompt))
                allMessages.addAll(historyMessages)

                // 3. Create placeholder assistant message (for later update)
                val placeholderPayload = AIMessagePayload(conversationId = conversationId, role = "assistant", content = "", model = modelId, tokensUsed = null, createdAt = System.currentTimeMillis())
                val placeholderItem = itemRepository.create(ItemType.AI_MESSAGE, json.encodeToString(placeholderPayload))

                // 4. Start streaming
                _uiState.value = _uiState.value.copy(streamingMessageId = placeholderItem.id, streamingContent = "")

                val responseBuilder = StringBuilder()
                try {
                    val apiChannel = com.mucheng.notes.domain.model.payload.AIChannel(
                        id = channel.id, name = channel.name, type = channel.type, 
                        apiUrl = channel.apiUrl, apiKey = channel.apiKey, models = emptyList(), enabled = channel.enabled
                    )

                    aiApiClient.streamChat(channel = apiChannel, model = modelId, messages = allMessages, temperature = temperature, maxTokens = maxTokens)
                        .collect { chunk -> 
                            responseBuilder.append(chunk)
                            // Update UI state only, don't write to DB yet
                            _uiState.value = _uiState.value.copy(streamingContent = responseBuilder.toString())
                        }

                    // 5. Stream finished, update DB with full content
                    val finalPayload = placeholderPayload.copy(content = responseBuilder.toString())
                    itemRepository.update(placeholderItem.id, json.encodeToString(finalPayload))

                } catch (e: Exception) {
                    // Update DB with error or partial content
                    val errorContent = if (responseBuilder.isNotEmpty()) responseBuilder.toString() + "\n[Error: ${e.message}]" else "AI 请求失败: ${e.message}"
                    val errorPayload = placeholderPayload.copy(content = errorContent)
                    itemRepository.update(placeholderItem.id, json.encodeToString(errorPayload))
                }

                // 6. Cleanup
                _uiState.value = _uiState.value.copy(isThinking = false, streamingMessageId = null, streamingContent = "")

            } catch (e: Exception) {
                _uiState.value = _uiState.value.copy(isThinking = false, error = e.message, streamingMessageId = null)
            }
        }
    }

    fun sendMessage(content: String) {
        val conversationId = _uiState.value.selectedConversationId ?: return
        val conversation = conversations.value.find { it.id == conversationId } ?: return
        sendMessageWithSettings(content, conversation.model, conversation.channelId, conversation.systemPrompt, conversation.temperature, conversation.maxTokens)
    }

    fun deleteConversation(conversationId: String) {
        viewModelScope.launch {
            messages.value.filter { it.conversationId == conversationId }.forEach { message ->
                itemRepository.softDelete(message.id)
            }
            itemRepository.softDelete(conversationId)
            if (_uiState.value.selectedConversationId == conversationId) {
                _uiState.value = _uiState.value.copy(selectedConversationId = null)
            }
        }
    }

    fun updateConversationTitle(conversationId: String, newTitle: String) {
        viewModelScope.launch {
            val item = itemRepository.getById(conversationId) ?: return@launch
            try {
                val payload = json.decodeFromString<AIConversationPayload>(item.payload)
                val updatedPayload = payload.copy(title = newTitle)
                itemRepository.update(conversationId, json.encodeToString(updatedPayload))
            } catch (e: Exception) {
                _uiState.value = _uiState.value.copy(error = "更新标题失败: ${e.message}")
            }
        }
    }


    fun updateSettings(conversationId: String, channelId: String?, model: String, systemPrompt: String, temperature: Float, maxTokens: Int) {
        viewModelScope.launch {
            val item = itemRepository.getById(conversationId) ?: return@launch
            try {
                val payloadData = json.decodeFromString<AIConversationPayload>(item.payload)
                val updatedPayload = payloadData.copy(
                    model = model,
                    channelId = channelId,
                    systemPrompt = systemPrompt,
                    temperature = temperature,
                    maxTokens = maxTokens
                )
                itemRepository.update(conversationId, json.encodeToString(updatedPayload))
            } catch (e: Exception) {
                _uiState.value = _uiState.value.copy(error = "更新设置失败: ${e.message}")
            }
        }
    }

    fun clearError() {
        _uiState.value = _uiState.value.copy(error = null)
    }

    private fun ItemEntity.toConversationItem(): ConversationItem? {
        if (type != ItemType.AI_CONVERSATION.value) return null
        return try {
            val payloadData = json.decodeFromString<AIConversationPayload>(payload)
            ConversationItem(
                id = id,
                title = payloadData.title,
                model = payloadData.model,
                channelId = payloadData.channelId,
                systemPrompt = payloadData.systemPrompt,
                temperature = payloadData.temperature,
                maxTokens = payloadData.maxTokens,
                createdAt = payloadData.createdAt
            )
        } catch (e: Exception) { null }
    }

    private fun ItemEntity.toMessageItem(): MessageItem? {
        if (type != ItemType.AI_MESSAGE.value) return null
        return try {
            val payloadData = json.decodeFromString<AIMessagePayload>(payload)
            MessageItem(
                id = id,
                conversationId = payloadData.conversationId,
                role = payloadData.role,
                content = payloadData.content,
                model = payloadData.model,
                tokensUsed = payloadData.tokensUsed,
                createdAt = payloadData.createdAt
            )
        } catch (e: Exception) { null }
    }
}

/**
 * FakerGenerator 服务
 * 使用 @faker-js/faker 生成本地化的虚假用户资料
 */

import { Faker, base, en, en_US, zh_CN, ja, ko, en_GB, de, fr, ru } from '@faker-js/faker';
import { v4 as uuidv4 } from 'uuid';
import {
  GeneratorOptions,
  GeneratedProfile,
  GeneratorCountryCode,
  GeneratorGender,
  PasswordOptions,
} from '@shared/types';

// 创建各语言的 Faker 实例，确保有完整的 fallback 链
const fakerEN_US = new Faker({ locale: [en_US, en, base] });
const fakerZH_CN = new Faker({ locale: [zh_CN, en_US, en, base] });
const fakerJA = new Faker({ locale: [ja, en_US, en, base] });
const fakerKO = new Faker({ locale: [ko, en_US, en, base] });
const fakerEN_GB = new Faker({ locale: [en_GB, en_US, en, base] });
const fakerDE = new Faker({ locale: [de, en_US, en, base] });
const fakerFR = new Faker({ locale: [fr, en_US, en, base] });
const fakerRU = new Faker({ locale: [ru, en_US, en, base] });

// Faker 实例映射
const fakerInstances: Record<GeneratorCountryCode, Faker> = {
  'en_US': fakerEN_US,
  'zh_CN': fakerZH_CN,
  'ja': fakerJA,
  'ko': fakerKO,
  'en_GB': fakerEN_GB,
  'de': fakerDE,
  'fr': fakerFR,
  'ru': fakerRU,
};

/**
 * 生成随机密码
 */
export function generatePassword(options: PasswordOptions): string {
  const { length, uppercase, lowercase, numbers, symbols } = options;

  // 至少需要一种字符类型
  if (!uppercase && !lowercase && !numbers && !symbols) {
    throw new Error('至少需要选择一种字符类型');
  }

  let chars = '';
  if (uppercase) chars += 'ABCDEFGHIJKLMNOPQRSTUVWXYZ';
  if (lowercase) chars += 'abcdefghijklmnopqrstuvwxyz';
  if (numbers) chars += '0123456789';
  if (symbols) chars += '!@#$%^&*()_+-=[]{}|;:,.<>?';

  const array = new Uint32Array(length);
  crypto.getRandomValues(array);
  return Array.from(array, x => chars[x % chars.length]).join('');
}


/**
 * 获取对应国家的 Faker 实例
 */
function getFakerInstance(country: GeneratorCountryCode): Faker {
  return fakerInstances[country] || fakerEN_US;
}

/**
 * 根据性别获取 Faker 的 sex 参数
 */
function getSexParam(gender: GeneratorGender): 'male' | 'female' | undefined {
  if (gender === 'random') {
    return Math.random() > 0.5 ? 'male' : 'female';
  }
  return gender;
}

/**
 * 格式化全名（根据国家习惯）
 */
function formatFullName(
  firstName: string,
  lastName: string,
  country: GeneratorCountryCode
): string {
  // 东亚国家姓在前
  if (['zh_CN', 'ja', 'ko'].includes(country)) {
    return `${lastName}${firstName}`;
  }
  // 西方国家名在前
  return `${firstName} ${lastName}`;
}

/**
 * 生成完整地址（包含街道、城市、州/省、邮编、国家）
 */
function generateFullAddress(faker: Faker, country: GeneratorCountryCode): string {
  const street = faker.location.streetAddress(true);
  const city = faker.location.city();
  const zipCode = faker.location.zipCode();

  // 根据国家格式化地址
  switch (country) {
    case 'zh_CN':
      // 中国格式：省 城市 街道地址 邮编
      const province = faker.location.state();
      return `${province} ${city} ${street}, ${zipCode}`;

    case 'ja':
      // 日本格式：〒邮编 都道府县 市区町村 街道
      const prefecture = faker.location.state();
      return `〒${zipCode} ${prefecture} ${city} ${street}`;

    case 'ko':
      // 韩国格式：道/市 市/区 街道 邮编
      const region = faker.location.state();
      return `${region} ${city} ${street}, ${zipCode}`;

    case 'en_US':
      // 美国格式：街道, 城市, 州 邮编
      const state = faker.location.state({ abbreviated: true });
      return `${street}, ${city}, ${state} ${zipCode}`;

    case 'en_GB':
      // 英国格式：街道, 城市, 邮编
      return `${street}, ${city}, ${zipCode}`;

    case 'de':
      // 德国格式：街道, 邮编 城市
      return `${street}, ${zipCode} ${city}`;

    case 'fr':
      // 法国格式：街道, 邮编 城市
      return `${street}, ${zipCode} ${city}`;

    case 'ru':
      // 俄罗斯格式：街道, 城市, 邮编
      return `${street}, ${city}, ${zipCode}`;

    default:
      return `${street}, ${city}, ${zipCode}`;
  }
}

/**
 * 生成单个用户资料
 */
export function generateProfile(options: GeneratorOptions): GeneratedProfile {
  const { country, gender, includeFields, passwordOptions } = options;
  const fakerInstance = getFakerInstance(country);
  const sex = getSexParam(gender);

  const profile: GeneratedProfile = {
    id: uuidv4(),
    username: fakerInstance.internet.username(),
    password: generatePassword(passwordOptions),
    generatedAt: Date.now(),
  };

  // 可选字段
  if (includeFields.name) {
    profile.firstName = fakerInstance.person.firstName(sex);
    profile.lastName = fakerInstance.person.lastName(sex);
    profile.fullName = formatFullName(profile.firstName, profile.lastName, country);
  }

  if (includeFields.address) {
    profile.address = generateFullAddress(fakerInstance, country);
  }

  if (includeFields.phone) {
    profile.phone = fakerInstance.phone.number();
  }

  if (includeFields.email) {
    // 如果有姓名，使用姓名生成邮箱
    if (profile.firstName && profile.lastName) {
      profile.email = fakerInstance.internet.email({
        firstName: profile.firstName,
        lastName: profile.lastName,
      });
    } else {
      profile.email = fakerInstance.internet.email();
    }
  }

  if (includeFields.company) {
    profile.company = fakerInstance.company.name();
  }

  return profile;
}

/**
 * 批量生成用户资料
 */
export function generateBatch(options: GeneratorOptions): GeneratedProfile[] {
  const { quantity } = options;

  // 验证数量范围
  if (quantity < 1 || quantity > 100) {
    throw new Error('生成数量必须在 1-100 之间');
  }

  const profiles: GeneratedProfile[] = [];
  for (let i = 0; i < quantity; i++) {
    profiles.push(generateProfile(options));
  }

  return profiles;
}

/**
 * 验证生成器选项
 */
export function validateGeneratorOptions(options: GeneratorOptions): string | null {
  const { quantity, passwordOptions } = options;

  // 验证数量
  if (quantity < 1 || quantity > 100) {
    return '生成数量必须在 1-100 之间';
  }

  // 验证密码长度
  if (passwordOptions.length < 8 || passwordOptions.length > 64) {
    return '密码长度必须在 8-64 之间';
  }

  // 验证至少一种字符类型
  const { uppercase, lowercase, numbers, symbols } = passwordOptions;
  if (!uppercase && !lowercase && !numbers && !symbols) {
    return '至少需要选择一种密码字符类型';
  }

  return null;
}

/**
 * 将生成的资料格式化为备注文本
 */
export function formatProfileAsNotes(profile: GeneratedProfile): string {
  const lines: string[] = [];

  if (profile.fullName) {
    lines.push(`姓名: ${profile.fullName}`);
  }
  if (profile.address) {
    lines.push(`地址: ${profile.address}`);
  }
  if (profile.phone) {
    lines.push(`电话: ${profile.phone}`);
  }
  if (profile.email) {
    lines.push(`邮箱: ${profile.email}`);
  }
  if (profile.company) {
    lines.push(`工作单位: ${profile.company}`);
  }

  return lines.join('\n');
}

/**
 * 将生成的资料格式化为完整的复制文本
 */
export function formatProfileForCopy(profile: GeneratedProfile): string {
  const lines: string[] = [
    `用户名: ${profile.username}`,
    `密码: ${profile.password}`,
  ];

  if (profile.fullName) {
    lines.push(`姓名: ${profile.fullName}`);
  }
  if (profile.address) {
    lines.push(`地址: ${profile.address}`);
  }
  if (profile.phone) {
    lines.push(`电话: ${profile.phone}`);
  }
  if (profile.email) {
    lines.push(`邮箱: ${profile.email}`);
  }
  if (profile.company) {
    lines.push(`工作单位: ${profile.company}`);
  }

  return lines.join('\n');
}

import { useState, useEffect, useCallback } from 'react';
import { ItemBase, VaultEntryPayload, VaultFolderPayload, VaultEntryType, VaultCustomField, VaultUri, VaultTotp } from '@shared/types';
import { itemsApi } from '../services/itemsApi';

export interface VaultEntry {
  id: string;
  name: string;
  entryType: VaultEntryType;
  folderId: string | null;
  favorite: boolean;
  notes: string;
  username: string;
  password: string;
  totpSecrets: VaultTotp[];
  uris: VaultUri[];
  cardHolderName: string;
  cardNumber: string;
  cardBrand: string;
  cardExpMonth: string;
  cardExpYear: string;
  cardCvv: string;
  identityTitle: string;
  identityFirstName: string;
  identityLastName: string;
  identityEmail: string;
  identityPhone: string;
  identityAddress: string;
  customFields: VaultCustomField[];
  createdAt: number;
  updatedAt: number;
}

export interface VaultFolder {
  id: string;
  name: string;
  parentId: string | null;
  createdAt: number;
}

function parsePayload<T>(item: ItemBase): T {
  return JSON.parse(item.payload) as T;
}

function itemToEntry(item: ItemBase): VaultEntry {
  const p = parsePayload<VaultEntryPayload>(item);
  return {
    id: item.id,
    name: p.name,
    entryType: p.entry_type,
    folderId: p.folder_id,
    favorite: p.favorite,
    notes: p.notes || '',
    username: p.username || '',
    password: p.password || '',
    totpSecrets: p.totp_secrets || [],
    uris: p.uris || [],
    cardHolderName: p.card_holder_name || '',
    cardNumber: p.card_number || '',
    cardBrand: p.card_brand || '',
    cardExpMonth: p.card_exp_month || '',
    cardExpYear: p.card_exp_year || '',
    cardCvv: p.card_cvv || '',
    identityTitle: p.identity_title || '',
    identityFirstName: p.identity_first_name || '',
    identityLastName: p.identity_last_name || '',
    identityEmail: p.identity_email || '',
    identityPhone: p.identity_phone || '',
    identityAddress: p.identity_address || '',
    customFields: p.custom_fields || [],
    createdAt: item.created_time,
    updatedAt: item.updated_time,
  };
}

function itemToFolder(item: ItemBase): VaultFolder {
  const p = parsePayload<VaultFolderPayload>(item);
  return {
    id: item.id,
    name: p.name,
    parentId: p.parent_id,
    createdAt: item.created_time,
  };
}

// API
const vaultEntriesApi = {
  create: (payload: VaultEntryPayload): Promise<ItemBase> =>
    itemsApi.create('vault_entry', payload),
  getAll: (): Promise<ItemBase[]> =>
    itemsApi.getByType('vault_entry'),
  update: (id: string, payload: Partial<VaultEntryPayload>): Promise<ItemBase | undefined> =>
    itemsApi.update(id, payload),
  delete: (id: string): Promise<boolean> =>
    itemsApi.delete(id),
};

const vaultFoldersApi = {
  create: (payload: VaultFolderPayload): Promise<ItemBase> =>
    itemsApi.create('vault_folder', payload),
  getAll: (): Promise<ItemBase[]> =>
    itemsApi.getByType('vault_folder'),
  update: (id: string, payload: Partial<VaultFolderPayload>): Promise<ItemBase | undefined> =>
    itemsApi.update(id, payload),
  delete: (id: string): Promise<boolean> =>
    itemsApi.delete(id),
};

export function useVaultFolders() {
  const [folders, setFolders] = useState<VaultFolder[]>([]);
  const [loading, setLoading] = useState(true);

  const loadFolders = useCallback(async () => {
    try {
      setLoading(true);
      const items = await vaultFoldersApi.getAll();
      if (items) {
        setFolders(items.filter(i => !i.deleted_time).map(itemToFolder));
      }
    } catch (err) {
      console.error('Failed to load vault folders:', err);
    } finally {
      setLoading(false);
    }
  }, []);

  useEffect(() => { loadFolders(); }, [loadFolders]);

  // 监听同步完成事件，刷新文件夹列表
  useEffect(() => {
    const handleSyncCompleted = () => {
      loadFolders();
    };
    window.addEventListener('sync-completed', handleSyncCompleted);
    return () => {
      window.removeEventListener('sync-completed', handleSyncCompleted);
    };
  }, [loadFolders]);

  const createFolder = useCallback(async (name: string, parentId: string | null = null) => {
    const item = await vaultFoldersApi.create({ name, parent_id: parentId });
    if (item) {
      await loadFolders();
      return itemToFolder(item);
    }
    return null;
  }, [loadFolders]);

  const updateFolder = useCallback(async (id: string, updates: Partial<VaultFolderPayload>) => {
    const item = await vaultFoldersApi.update(id, updates);
    if (item) { await loadFolders(); }
  }, [loadFolders]);

  const deleteFolder = useCallback(async (id: string) => {
    await vaultFoldersApi.delete(id);
    await loadFolders();
  }, [loadFolders]);

  return { folders, loading, createFolder, updateFolder, deleteFolder, refresh: loadFolders };
}

export function useVaultEntries(folderId?: string | null) {
  const [entries, setEntries] = useState<VaultEntry[]>([]);
  const [loading, setLoading] = useState(true);

  const loadEntries = useCallback(async () => {
    try {
      setLoading(true);
      const items = await vaultEntriesApi.getAll();
      if (items) {
        let list = items.filter(i => !i.deleted_time).map(itemToEntry);
        if (folderId !== undefined) {
          list = list.filter(e => e.folderId === folderId);
        }
        list.sort((a, b) => {
          if (a.favorite && !b.favorite) return -1;
          if (!a.favorite && b.favorite) return 1;
          return a.name.localeCompare(b.name);
        });
        setEntries(list);
      }
    } catch (err) {
      console.error('Failed to load vault entries:', err);
    } finally {
      setLoading(false);
    }
  }, [folderId]);

  useEffect(() => { loadEntries(); }, [loadEntries]);

  // 监听同步完成事件，刷新条目列表
  useEffect(() => {
    const handleSyncCompleted = () => {
      loadEntries();
    };
    window.addEventListener('sync-completed', handleSyncCompleted);
    return () => {
      window.removeEventListener('sync-completed', handleSyncCompleted);
    };
  }, [loadEntries]);

  const createEntry = useCallback(async (data: Partial<VaultEntryPayload>) => {
    const payload: VaultEntryPayload = {
      name: data.name || '',
      entry_type: data.entry_type || 'login',
      folder_id: data.folder_id ?? folderId ?? null,
      favorite: data.favorite || false,
      notes: data.notes || '',
      username: data.username || '',
      password: data.password || '',
      totp_secrets: data.totp_secrets || [],
      uris: data.uris || [],
      card_holder_name: data.card_holder_name || '',
      card_number: data.card_number || '',
      card_brand: data.card_brand || '',
      card_exp_month: data.card_exp_month || '',
      card_exp_year: data.card_exp_year || '',
      card_cvv: data.card_cvv || '',
      identity_title: data.identity_title || '',
      identity_first_name: data.identity_first_name || '',
      identity_last_name: data.identity_last_name || '',
      identity_email: data.identity_email || '',
      identity_phone: data.identity_phone || '',
      identity_address: data.identity_address || '',
      custom_fields: data.custom_fields || [],
    };
    const item = await vaultEntriesApi.create(payload);
    if (item) {
      await loadEntries();
      return itemToEntry(item);
    }
    return null;
  }, [folderId, loadEntries]);

  const updateEntry = useCallback(async (id: string, updates: Partial<VaultEntryPayload>) => {
    const item = await vaultEntriesApi.update(id, updates);
    if (item) { await loadEntries(); return itemToEntry(item); }
    return null;
  }, [loadEntries]);

  const deleteEntry = useCallback(async (id: string) => {
    await vaultEntriesApi.delete(id);
    await loadEntries();
  }, [loadEntries]);

  const toggleFavorite = useCallback(async (id: string) => {
    const entry = entries.find(e => e.id === id);
    if (entry) {
      await updateEntry(id, { favorite: !entry.favorite });
    }
  }, [entries, updateEntry]);

  return { entries, loading, createEntry, updateEntry, deleteEntry, toggleFavorite, refresh: loadEntries };
}

// 生成随机密码
export function generatePassword(length: number = 16, options?: {
  uppercase?: boolean;
  lowercase?: boolean;
  numbers?: boolean;
  symbols?: boolean;
}): string {
  const opts = { uppercase: true, lowercase: true, numbers: true, symbols: true, ...options };
  let chars = '';
  if (opts.uppercase) chars += 'ABCDEFGHIJKLMNOPQRSTUVWXYZ';
  if (opts.lowercase) chars += 'abcdefghijklmnopqrstuvwxyz';
  if (opts.numbers) chars += '0123456789';
  if (opts.symbols) chars += '!@#$%^&*()_+-=[]{}|;:,.<>?';

  const array = new Uint32Array(length);
  crypto.getRandomValues(array);
  return Array.from(array, x => chars[x % chars.length]).join('');
}

