// ============================================

export interface TransferError {
  code: TransferErrorCode;
  message: string;
  details?: any;
  timestamp: number;
}

/**
 * 创建传输错误对象
 */
export function createTransferError(
  code: TransferErrorCode,
  details?: any
): TransferError {
  return {
    code,
    message: ERROR_MESSAGES[code] || '未知错误',
    details,
    timestamp: Date.now(),
  };
}

