// ============================================
// 二维码数据接口
// ============================================

export interface PairingQRData {
  deviceId: string;
  deviceName: string;
  serverIp: string;
  serverPort: number;
  timestamp: number;
  expiresAt: number;
  version: string;
}

/**
 * 验证二维码是否过期
 */
export function isQRCodeExpired(qrData: PairingQRData): boolean {
  return Date.now() > qrData.expiresAt;
}

/**
 * 生成二维码数据
 */
export function createPairingQRData(
  deviceId: string,
  deviceName: string,
  serverIp: string,
  serverPort: number
): PairingQRData {
  const now = Date.now();
  return {
    deviceId,
    deviceName,
    serverIp,
    serverPort,
    timestamp: now,
    expiresAt: now + TRANSFER_CONSTANTS.QR_CODE_EXPIRY,
    version: '1.0',
  };
}

package com.mucheng.notes.presentation.viewmodel

import android.content.Context
import android.content.Intent
import android.net.Uri
import androidx.lifecycle.ViewModel
import androidx.lifecycle.viewModelScope
import com.mucheng.notes.data.local.entity.ItemEntity
import com.mucheng.notes.domain.model.ItemType
import com.mucheng.notes.domain.model.payload.BookmarkFolderPayload
import com.mucheng.notes.domain.model.payload.BookmarkPayload
import com.mucheng.notes.domain.repository.ItemRepository
import dagger.hilt.android.lifecycle.HiltViewModel
import dagger.hilt.android.qualifiers.ApplicationContext
import kotlinx.coroutines.flow.MutableStateFlow
import kotlinx.coroutines.flow.SharingStarted
import kotlinx.coroutines.flow.StateFlow
import kotlinx.coroutines.flow.asStateFlow
import kotlinx.coroutines.flow.map
import kotlinx.coroutines.flow.stateIn
import kotlinx.coroutines.launch
import kotlinx.serialization.encodeToString
import kotlinx.serialization.json.Json
import javax.inject.Inject

/**
 * 书签 UI 状态
 */
data class BookmarksUiState(
    val isLoading: Boolean = false,
    val error: String? = null,
    val selectedFolderId: String? = null,
    val searchQuery: String = ""
)

/**
 * 书签视图模型
 */
@HiltViewModel
class BookmarksViewModel @Inject constructor(
    @ApplicationContext private val context: Context,
    private val itemRepository: ItemRepository
) : ViewModel() {

    private val json = Json { 
        ignoreUnknownKeys = true 
        isLenient = true
        coerceInputValues = true  // 将 null 转换为默认值
    }

    private val _uiState = MutableStateFlow(BookmarksUiState())
    val uiState: StateFlow<BookmarksUiState> = _uiState.asStateFlow()

    private val _selectedFolderId = MutableStateFlow<String?>(null)
    val selectedFolderId: StateFlow<String?> = _selectedFolderId.asStateFlow()

    /**
     * 书签列表（实时流）
     */
    val bookmarks: StateFlow<List<BookmarkItem>> = itemRepository.getByType(ItemType.BOOKMARK)
        .map { items -> items.map { it.toBookmarkItem() } }
        .stateIn(viewModelScope, SharingStarted.Lazily, emptyList())

    /**
     * 书签文件夹列表（实时流）
     */
    val folders: StateFlow<List<BookmarkFolderItem>> = itemRepository.getByType(ItemType.BOOKMARK_FOLDER)
        .map { items -> items.map { it.toBookmarkFolderItem() } }
        .stateIn(viewModelScope, SharingStarted.Lazily, emptyList())

    /**
     * 创建书签
     */
    fun createBookmark(
        name: String,
        url: String,
        description: String = "",
        folderId: String? = null
    ) {
        viewModelScope.launch {
            val payload = BookmarkPayload(
                name = name,
                url = url,
                description = description,
                folderId = folderId,
                icon = null,
                tags = emptyList()
            )
            itemRepository.create(ItemType.BOOKMARK, json.encodeToString(payload))
        }
    }

    /**
     * 更新书签
     */
    fun updateBookmark(id: String, name: String, url: String, description: String, folderId: String? = null) {
        viewModelScope.launch {
            val existing = itemRepository.getById(id) ?: return@launch
            val oldPayload = json.decodeFromString<BookmarkPayload>(existing.payload)
            val newPayload = oldPayload.copy(
                name = name, 
                url = url, 
                description = description,
                folderId = folderId
            )
            itemRepository.update(id, json.encodeToString(newPayload))
        }
    }

    /**
     * 删除书签
     */
    fun deleteBookmark(id: String) {
        viewModelScope.launch {
            itemRepository.softDelete(id)
        }
    }

    /**
     * 打开书签（在浏览器中）
     */
    fun openBookmark(url: String) {
        try {
            val intent = Intent(Intent.ACTION_VIEW, Uri.parse(url)).apply {
                addFlags(Intent.FLAG_ACTIVITY_NEW_TASK)
            }
            context.startActivity(intent)
        } catch (e: Exception) {
            _uiState.value = _uiState.value.copy(error = "无法打开链接")
        }
    }

    /**
     * 选择文件夹
     */
    fun selectFolder(folderId: String?) {
        _selectedFolderId.value = folderId
        _uiState.value = _uiState.value.copy(selectedFolderId = folderId)
    }

    /**
     * 搜索书签
     */
    fun search(query: String) {
        _uiState.value = _uiState.value.copy(searchQuery = query)
    }

    /**
     * 创建文件夹
     */
    fun createFolder(parentId: String?) {
        viewModelScope.launch {
            val payload = BookmarkFolderPayload(name = "新建文件夹", parentId = parentId)
            itemRepository.create(ItemType.BOOKMARK_FOLDER, json.encodeToString(payload))
        }
    }

    /**
     * 创建文件夹（带名称）
     */
    fun createFolder(name: String, parentId: String?) {
        viewModelScope.launch {
            val payload = BookmarkFolderPayload(name = name, parentId = parentId)
            itemRepository.create(ItemType.BOOKMARK_FOLDER, json.encodeToString(payload))
        }
    }

    /**
     * 重命名文件夹
     */
    fun renameFolder(id: String, newName: String) {
        viewModelScope.launch {
            val existing = itemRepository.getById(id) ?: return@launch
            val oldPayload = json.decodeFromString<BookmarkFolderPayload>(existing.payload)
            val newPayload = oldPayload.copy(name = newName)
            itemRepository.update(id, json.encodeToString(newPayload))
        }
    }

    /**
     * 删除文件夹
     */
    fun deleteFolder(id: String) {
        viewModelScope.launch {
            // 将该文件夹下的书签移到根目录
            val bookmarksInFolder = bookmarks.value.filter { it.folderId == id }
            bookmarksInFolder.forEach { bookmark ->
                val existing = itemRepository.getById(bookmark.id) ?: return@forEach
                val oldPayload = json.decodeFromString<BookmarkPayload>(existing.payload)
                val newPayload = oldPayload.copy(folderId = null)
                itemRepository.update(bookmark.id, json.encodeToString(newPayload))
            }

            // 将子文件夹移到根目录
            val subFolders = folders.value.filter { it.parentId == id }
            subFolders.forEach { folder ->
                val existing = itemRepository.getById(folder.id) ?: return@forEach
                val oldPayload = json.decodeFromString<BookmarkFolderPayload>(existing.payload)
                val newPayload = oldPayload.copy(parentId = null)
                itemRepository.update(folder.id, json.encodeToString(newPayload))
            }

            // 删除文件夹
            itemRepository.softDelete(id)
        }
    }

    /**
     * 移动书签到文件夹
     */
    fun moveBookmarkToFolder(bookmarkId: String, folderId: String?) {
        viewModelScope.launch {
            val existing = itemRepository.getById(bookmarkId) ?: return@launch
            val oldPayload = json.decodeFromString<BookmarkPayload>(existing.payload)
            val newPayload = oldPayload.copy(folderId = folderId)
            itemRepository.update(bookmarkId, json.encodeToString(newPayload))
        }
    }

    private fun ItemEntity.toBookmarkItem(): BookmarkItem {
        val payload = json.decodeFromString<BookmarkPayload>(this.payload)
        return BookmarkItem(
            id = this.id,
            name = payload.name,
            url = payload.url,
            description = payload.description,
            folderId = payload.folderId,
            icon = payload.icon,
            tags = payload.tags,
            updatedTime = this.updatedTime
        )
    }

    private fun ItemEntity.toBookmarkFolderItem(): BookmarkFolderItem {
        val payload = json.decodeFromString<BookmarkFolderPayload>(this.payload)
        return BookmarkFolderItem(
            id = this.id,
            name = payload.name,
            parentId = payload.parentId
        )
    }
}

/**
 * 书签展示模型
 */
data class BookmarkItem(
    val id: String,
    val name: String,
    val url: String,
    val description: String,
    val folderId: String?,
    val icon: String?,
    val tags: List<String>,
    val updatedTime: Long
)

/**
 * 书签文件夹展示模型
 */
data class BookmarkFolderItem(
    val id: String,
    val name: String,
    val parentId: String?
)

import Database from 'better-sqlite3';

// 数据库版本号 - 用于迁移
const SCHEMA_VERSION = 4;

export function initializeSchema(db: Database.Database): void {
  // items 表 - 存储所有同步数据项
  db.exec(`
    CREATE TABLE IF NOT EXISTS items (
      id TEXT PRIMARY KEY,
      type TEXT NOT NULL,
      payload TEXT NOT NULL,
      content_hash TEXT NOT NULL,
      remote_rev TEXT,
      deleted_time INTEGER,
      created_time INTEGER NOT NULL,
      updated_time INTEGER NOT NULL,
      sync_status TEXT DEFAULT 'clean',
      local_rev INTEGER DEFAULT 0,
      encryption_applied INTEGER DEFAULT 0,
      schema_version INTEGER DEFAULT 1,
      user_id TEXT
    )
  `);

  // changes 表 - 变更日志
  db.exec(`
    CREATE TABLE IF NOT EXISTS changes (
      change_id INTEGER PRIMARY KEY AUTOINCREMENT,
      item_id TEXT NOT NULL,
      type TEXT NOT NULL,
      updated_time INTEGER NOT NULL,
      deleted_time INTEGER,
      content_hash TEXT NOT NULL,
      created_at INTEGER NOT NULL,
      user_id TEXT
    )
  `);

  // metadata 表 - 服务器元数据
  db.exec(`
    CREATE TABLE IF NOT EXISTS metadata (
      key TEXT PRIMARY KEY,
      value TEXT NOT NULL,
      updated_at INTEGER NOT NULL
    )
  `);

  // key_fingerprints 表 - 密钥指纹
  db.exec(`
    CREATE TABLE IF NOT EXISTS key_fingerprints (
      api_key_hash TEXT PRIMARY KEY,
      fingerprint TEXT NOT NULL,
      created_at INTEGER NOT NULL,
      updated_at INTEGER NOT NULL
    )
  `);

  // sync_cursors 表 - 同步游标
  db.exec(`
    CREATE TABLE IF NOT EXISTS sync_cursors (
      api_key_hash TEXT PRIMARY KEY,
      cursor TEXT NOT NULL,
      updated_at INTEGER NOT NULL
    )
  `);

  // ========== 用户认证系统表 ==========

  // users 表 - 用户账号
  db.exec(`
    CREATE TABLE IF NOT EXISTS users (
      id TEXT PRIMARY KEY,
      username TEXT UNIQUE NOT NULL,
      password_hash TEXT NOT NULL,
      sync_key_fingerprint TEXT NOT NULL,
      role TEXT DEFAULT 'user' CHECK(role IN ('user', 'admin')),
      status TEXT DEFAULT 'active' CHECK(status IN ('active', 'disabled')),
      created_at INTEGER NOT NULL,
      updated_at INTEGER NOT NULL,
      last_login_at INTEGER
    )
  `);

  // sessions 表 - 用户会话
  db.exec(`
    CREATE TABLE IF NOT EXISTS sessions (
      id TEXT PRIMARY KEY,
      user_id TEXT NOT NULL,
      refresh_token_hash TEXT NOT NULL,
      device_info TEXT,
      ip_address TEXT,
      created_at INTEGER NOT NULL,
      expires_at INTEGER NOT NULL,
      revoked INTEGER DEFAULT 0,
      FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE
    )
  `);

  // audit_logs 表 - 审计日志
  db.exec(`
    CREATE TABLE IF NOT EXISTS audit_logs (
      id TEXT PRIMARY KEY,
      user_id TEXT,
      action TEXT NOT NULL,
      ip_address TEXT NOT NULL,
      user_agent TEXT,
      details TEXT,
      success INTEGER NOT NULL,
      timestamp INTEGER NOT NULL
    )
  `);

  // rate_limits 表 - 频率限制
  db.exec(`
    CREATE TABLE IF NOT EXISTS rate_limits (
      key TEXT PRIMARY KEY,
      count INTEGER NOT NULL,
      window_start INTEGER NOT NULL,
      blocked_until INTEGER,
      block_count INTEGER DEFAULT 0
    )
  `);

  // 创建索引 - 原有索引
  db.exec(`
    CREATE INDEX IF NOT EXISTS idx_items_type ON items(type);
    CREATE INDEX IF NOT EXISTS idx_items_updated_time ON items(updated_time);
    CREATE INDEX IF NOT EXISTS idx_items_deleted_time ON items(deleted_time);
    CREATE INDEX IF NOT EXISTS idx_items_user_id ON items(user_id);
    CREATE INDEX IF NOT EXISTS idx_changes_item_id ON changes(item_id);
    CREATE INDEX IF NOT EXISTS idx_changes_created_at ON changes(created_at);
    CREATE INDEX IF NOT EXISTS idx_changes_user_id ON changes(user_id);
  `);

  // 创建索引 - 用户认证系统索引
  db.exec(`
    CREATE INDEX IF NOT EXISTS idx_users_username ON users(username);
    CREATE INDEX IF NOT EXISTS idx_sessions_user_id ON sessions(user_id);
    CREATE INDEX IF NOT EXISTS idx_sessions_expires_at ON sessions(expires_at);
    CREATE INDEX IF NOT EXISTS idx_audit_logs_user_id ON audit_logs(user_id);
    CREATE INDEX IF NOT EXISTS idx_audit_logs_timestamp ON audit_logs(timestamp);
    CREATE INDEX IF NOT EXISTS idx_audit_logs_action ON audit_logs(action);
  `);

  // system_settings 表 - 系统设置
  db.exec(`
    CREATE TABLE IF NOT EXISTS system_settings (
      key TEXT PRIMARY KEY,
      value TEXT NOT NULL,
      updated_at INTEGER NOT NULL
    )
  `);

  // 初始化默认元数据
  const now = Date.now();
  const initMeta = db.prepare(`
    INSERT OR IGNORE INTO metadata (key, value, updated_at) VALUES (?, ?, ?)
  `);

  initMeta.run('version', '1.0', now);
  initMeta.run('capabilities', JSON.stringify(['items', 'resources', 'changes', 'auth']), now);
  initMeta.run('schema_version', String(SCHEMA_VERSION), now);

  // 初始化系统设置（默认开放注册，直到第一个管理员创建）
  const initSetting = db.prepare(`
    INSERT OR IGNORE INTO system_settings (key, value, updated_at) VALUES (?, ?, ?)
  `);
  initSetting.run('registration_enabled', 'true', now);
}

// 运行数据库迁移
export function runMigrations(db: Database.Database): void {
  // 获取当前 schema 版本
  let currentVersion = 1;
  try {
    const row = db.prepare('SELECT value FROM metadata WHERE key = ?').get('schema_version') as { value: string } | undefined;
    if (row) {
      currentVersion = parseInt(row.value, 10);
    }
  } catch {
    // 表可能不存在，使用默认版本
  }

  // 迁移到版本 2：添加 user_id 字段
  if (currentVersion < 2) {
    migrateToV2(db);
  }

  // 迁移到版本 3：添加 system_settings 表
  if (currentVersion < 3) {
    migrateToV3(db);
  }

  // 迁移到版本 4：添加 block_count 字段到 rate_limits 表
  if (currentVersion < 4) {
    migrateToV4(db);
  }

  // 更新 schema 版本
  const now = Date.now();
  db.prepare('INSERT OR REPLACE INTO metadata (key, value, updated_at) VALUES (?, ?, ?)')
    .run('schema_version', String(SCHEMA_VERSION), now);
}

// 迁移到版本 2：添加用户隔离支持
function migrateToV2(db: Database.Database): void {
  // 检查 items 表是否已有 user_id 字段
  const itemsInfo = db.prepare("PRAGMA table_info(items)").all() as Array<{ name: string }>;
  const hasItemsUserId = itemsInfo.some(col => col.name === 'user_id');

  if (!hasItemsUserId) {
    db.exec('ALTER TABLE items ADD COLUMN user_id TEXT');
    db.exec('CREATE INDEX IF NOT EXISTS idx_items_user_id ON items(user_id)');
  }

  // 检查 changes 表是否已有 user_id 字段
  const changesInfo = db.prepare("PRAGMA table_info(changes)").all() as Array<{ name: string }>;
  const hasChangesUserId = changesInfo.some(col => col.name === 'user_id');

  if (!hasChangesUserId) {
    db.exec('ALTER TABLE changes ADD COLUMN user_id TEXT');
    db.exec('CREATE INDEX IF NOT EXISTS idx_changes_user_id ON changes(user_id)');
  }
}


// 迁移到版本 3：添加 system_settings 表
function migrateToV3(db: Database.Database): void {
  // 检查 system_settings 表是否存在
  const tables = db.prepare("SELECT name FROM sqlite_master WHERE type='table' AND name='system_settings'").all();

  if (tables.length === 0) {
    db.exec(`
      CREATE TABLE IF NOT EXISTS system_settings (
        key TEXT PRIMARY KEY,
        value TEXT NOT NULL,
        updated_at INTEGER NOT NULL
      )
    `);

    // 初始化默认设置
    const now = Date.now();
    db.prepare('INSERT OR IGNORE INTO system_settings (key, value, updated_at) VALUES (?, ?, ?)')
      .run('registration_enabled', 'true', now);
  }
}

// 迁移到版本 4：添加 block_count 字段到 rate_limits 表（渐进式封禁）
function migrateToV4(db: Database.Database): void {
  // 检查 rate_limits 表是否已有 block_count 字段
  const rateLimitsInfo = db.prepare("PRAGMA table_info(rate_limits)").all() as Array<{ name: string }>;
  const hasBlockCount = rateLimitsInfo.some(col => col.name === 'block_count');

  if (!hasBlockCount) {
    db.exec('ALTER TABLE rate_limits ADD COLUMN block_count INTEGER DEFAULT 0');
  }
}

/**
 * 查找替换对话框组件
 * 支持 Ctrl+F 查找，Ctrl+H 替换
 */

import React, { useState, useCallback, useEffect, useRef } from 'react';
import { Modal, Input, Button, Checkbox, Space, Tag, message } from 'antd';
import { SearchOutlined, SwapOutlined } from '@ant-design/icons';

export interface FindResult {
  row: number;
  col: number;
  value: string;
}

interface FindReplaceDialogProps {
  open: boolean;
  mode: 'find' | 'replace';
  onClose: () => void;
  onFind: (searchText: string, options: FindOptions) => FindResult[];
  onReplace: (searchText: string, replaceText: string, options: FindOptions) => number;
  onReplaceAll: (searchText: string, replaceText: string, options: FindOptions) => number;
  onNavigateToResult: (result: FindResult) => void;
}

export interface FindOptions {
  caseSensitive: boolean;
  wholeCell: boolean;
  useRegex: boolean;
}

export const FindReplaceDialog: React.FC<FindReplaceDialogProps> = ({
  open,
  mode,
  onClose,
  onFind,
  onReplace,
  onReplaceAll,
  onNavigateToResult,
}) => {
  const [searchText, setSearchText] = useState('');
  const [replaceText, setReplaceText] = useState('');
  const [options, setOptions] = useState<FindOptions>({
    caseSensitive: false,
    wholeCell: false,
    useRegex: false,
  });
  const [results, setResults] = useState<FindResult[]>([]);
  const [currentIndex, setCurrentIndex] = useState(-1);
  const [isReplaceMode, setIsReplaceMode] = useState(mode === 'replace');

  const searchInputRef = useRef<any>(null);

  // 当对话框打开时聚焦搜索框
  useEffect(() => {
    if (open) {
      setIsReplaceMode(mode === 'replace');
      setTimeout(() => {
        searchInputRef.current?.focus();
      }, 100);
    }
  }, [open, mode]);

  // 执行查找
  const handleFind = useCallback(() => {
    if (!searchText.trim()) {
      setResults([]);
      setCurrentIndex(-1);
      return;
    }

    const foundResults = onFind(searchText, options);
    setResults(foundResults);

    if (foundResults.length > 0) {
      setCurrentIndex(0);
      onNavigateToResult(foundResults[0]);
      message.info(`找到 ${foundResults.length} 个匹配项`);
    } else {
      setCurrentIndex(-1);
      message.info('未找到匹配项');
    }
  }, [searchText, options, onFind, onNavigateToResult]);

  // 查找下一个
  const handleFindNext = useCallback(() => {
    if (results.length === 0) {
      handleFind();
      return;
    }

    const nextIndex = (currentIndex + 1) % results.length;
    setCurrentIndex(nextIndex);
    onNavigateToResult(results[nextIndex]);
  }, [results, currentIndex, handleFind, onNavigateToResult]);

  // 查找上一个
  const handleFindPrev = useCallback(() => {
    if (results.length === 0) {
      handleFind();
      return;
    }

    const prevIndex = currentIndex <= 0 ? results.length - 1 : currentIndex - 1;
    setCurrentIndex(prevIndex);
    onNavigateToResult(results[prevIndex]);
  }, [results, currentIndex, handleFind, onNavigateToResult]);

  // 替换当前
  const handleReplace = useCallback(() => {
    if (!searchText.trim() || currentIndex < 0) return;

    const count = onReplace(searchText, replaceText, options);
    if (count > 0) {
      // 重新查找
      const foundResults = onFind(searchText, options);
      setResults(foundResults);
      if (foundResults.length > 0) {
        const newIndex = Math.min(currentIndex, foundResults.length - 1);
        setCurrentIndex(newIndex);
        onNavigateToResult(foundResults[newIndex]);
      } else {
        setCurrentIndex(-1);
      }
      message.success('已替换');
    }
  }, [searchText, replaceText, options, currentIndex, onReplace, onFind, onNavigateToResult]);

  // 全部替换
  const handleReplaceAll = useCallback(() => {
    if (!searchText.trim()) return;

    const count = onReplaceAll(searchText, replaceText, options);
    if (count > 0) {
      message.success(`已替换 ${count} 处`);
      setResults([]);
      setCurrentIndex(-1);
    } else {
      message.info('未找到匹配项');
    }
  }, [searchText, replaceText, options, onReplaceAll]);

  // 处理键盘事件
  const handleKeyDown = useCallback((e: React.KeyboardEvent) => {
    if (e.key === 'Enter') {
      e.preventDefault();
      if (e.shiftKey) {
        handleFindPrev();
      } else {
        handleFindNext();
      }
    } else if (e.key === 'Escape') {
      onClose();
    }
  }, [handleFindNext, handleFindPrev, onClose]);

  return (
    <Modal
      title={
        <Space>
          {isReplaceMode ? <SwapOutlined /> : <SearchOutlined />}
          {isReplaceMode ? '查找和替换' : '查找'}
        </Space>
      }
      open={open}
      onCancel={onClose}
      footer={null}
      width={450}
      destroyOnClose={false}
    >
      <div style={{ display: 'flex', flexDirection: 'column', gap: 12 }} onKeyDown={handleKeyDown}>
        {/* 查找输入 */}
        <div>
          <div style={{ marginBottom: 4, fontSize: 12, color: '#666' }}>查找内容</div>
          <Input
            ref={searchInputRef}
            value={searchText}
            onChange={(e) => setSearchText(e.target.value)}
            placeholder="输入要查找的内容"
            suffix={
              results.length > 0 ? (
                <Tag color="blue">{currentIndex + 1}/{results.length}</Tag>
              ) : null
            }
          />
        </div>

        {/* 替换输入 */}
        {isReplaceMode && (
          <div>
            <div style={{ marginBottom: 4, fontSize: 12, color: '#666' }}>替换为</div>
            <Input
              value={replaceText}
              onChange={(e) => setReplaceText(e.target.value)}
              placeholder="输入替换内容"
            />
          </div>
        )}

        {/* 选项 */}
        <Space wrap>
          <Checkbox
            checked={options.caseSensitive}
            onChange={(e) => setOptions({ ...options, caseSensitive: e.target.checked })}
          >
            区分大小写
          </Checkbox>
          <Checkbox
            checked={options.wholeCell}
            onChange={(e) => setOptions({ ...options, wholeCell: e.target.checked })}
          >
            整个单元格匹配
          </Checkbox>
          <Checkbox
            checked={options.useRegex}
            onChange={(e) => setOptions({ ...options, useRegex: e.target.checked })}
          >
            使用正则表达式
          </Checkbox>
        </Space>

        {/* 模式切换 */}
        <div>
          <Button
            type="link"
            size="small"
            onClick={() => setIsReplaceMode(!isReplaceMode)}
            style={{ padding: 0 }}
          >
            {isReplaceMode ? '切换到查找模式' : '切换到替换模式'}
          </Button>
        </div>

        {/* 操作按钮 */}
        <Space style={{ justifyContent: 'flex-end', display: 'flex' }}>
          <Button onClick={handleFindPrev} disabled={results.length === 0}>
            上一个
          </Button>
          <Button onClick={handleFindNext} type={results.length === 0 ? 'primary' : 'default'}>
            {results.length === 0 ? '查找' : '下一个'}
          </Button>
          {isReplaceMode && (
            <>
              <Button onClick={handleReplace} disabled={currentIndex < 0}>
                替换
              </Button>
              <Button onClick={handleReplaceAll} type="primary">
                全部替换
              </Button>
            </>
          )}
        </Space>
      </div>
    </Modal>
  );
};

/**
 * LAN Transfer Assistant - 设备列表组件
 */

import React, { useState, useMemo } from 'react';
import { List, Avatar, Badge, Typography, Space, Button, Tooltip, Empty, Tabs, Tag } from 'antd';
import {
  DesktopOutlined,
  MobileOutlined,
  StarOutlined,
  StarFilled,
  MessageOutlined,
  ClockCircleOutlined,
  UserOutlined,
} from '@ant-design/icons';
import { ConnectedDevice, TransferSession } from '../../services/transferClient';
import { useSettings } from '../../contexts/SettingsContext';

const { Text } = Typography;

interface DeviceListViewProps {
  connectedDevices: ConnectedDevice[];
  sessions: TransferSession[];
  selectedSessionId: string | null;
  onSelectSession: (sessionId: string) => void;
  onCreateSession: (device: ConnectedDevice) => void;
  serverRunning: boolean;
}

export const DeviceListView: React.FC<DeviceListViewProps> = ({
  connectedDevices,
  sessions,
  selectedSessionId,
  onSelectSession,
  onCreateSession,
  serverRunning,
}) => {
  const { isDarkMode } = useSettings();
  const [activeTab, setActiveTab] = useState<'online' | 'history'>('online');

  // 格式化时间
  const formatTime = (timestamp: number) => {
    const now = Date.now();
    const diff = now - timestamp;

    if (diff < 60000) return '刚刚';
    if (diff < 3600000) return `${Math.floor(diff / 60000)} 分钟前`;
    if (diff < 86400000) return `${Math.floor(diff / 3600000)} 小时前`;

    const date = new Date(timestamp);
    return `${date.getMonth() + 1}/${date.getDate()}`;
  };

  // 获取设备图标
  const getDeviceIcon = (type: 'desktop' | 'android') => {
    return type === 'desktop' ? <DesktopOutlined /> : <MobileOutlined />;
  };

  // 按设备分组的会话
  const sessionsByDevice = useMemo(() => {
    const map = new Map<string, TransferSession[]>();
    sessions.forEach(session => {
      const existing = map.get(session.peer_device_id) || [];
      existing.push(session);
      map.set(session.peer_device_id, existing);
    });
    return map;
  }, [sessions]);

  // 渲染在线设备列表
  const renderOnlineDevices = () => {
    if (!serverRunning) {
      return (
        <Empty
          image={Empty.PRESENTED_IMAGE_SIMPLE}
          description="服务未启动"
          style={{ marginTop: 48 }}
        />
      );
    }

    if (connectedDevices.length === 0) {
      return (
        <Empty
          image={Empty.PRESENTED_IMAGE_SIMPLE}
          description="暂无在线设备"
          style={{ marginTop: 48 }}
        >
          <Text type="secondary" style={{ fontSize: 12 }}>
            等待其他设备扫码连接
          </Text>
        </Empty>
      );
    }

    return (
      <List
        dataSource={connectedDevices}
        renderItem={device => {
          // 查找与该设备的现有会话
          const deviceSessions = sessionsByDevice.get(device.id) || [];
          const activeSession = deviceSessions.find(s => !s.ended_at);

          return (
            <List.Item
              style={{
                padding: '12px 16px',
                cursor: 'pointer',
                background:
                  activeSession?.id === selectedSessionId
                    ? isDarkMode
                      ? '#177ddc20'
                      : '#e6f7ff'
                    : 'transparent',
                borderBottom: `1px solid ${isDarkMode ? '#303030' : '#f0f0f0'}`,
              }}
              onClick={() => {
                if (activeSession) {
                  onSelectSession(activeSession.id);
                } else {
                  onCreateSession(device);
                }
              }}
            >
              <List.Item.Meta
                avatar={
                  <Badge dot status="success" offset={[-4, 28]}>
                    <Avatar
                      icon={getDeviceIcon(device.type)}
                      style={{
                        background: device.type === 'desktop' ? '#1890ff' : '#52c41a',
                      }}
                    />
                  </Badge>
                }
                title={
                  <Space>
                    <Text strong>{device.name}</Text>
                    <Tag
                      color={device.type === 'desktop' ? 'blue' : 'green'}
                      style={{ fontSize: 10 }}
                    >
                      {device.type === 'desktop' ? '桌面' : '手机'}
                    </Tag>
                  </Space>
                }
                description={
                  <Text type="secondary" style={{ fontSize: 12 }}>
                    {device.ip}
                  </Text>
                }
              />
              <Tooltip title={activeSession ? '继续聊天' : '开始聊天'}>
                <Button type="text" icon={<MessageOutlined />} size="small" />
              </Tooltip>
            </List.Item>
          );
        }}
      />
    );
  };

  // 渲染历史会话列表
  const renderHistorySessions = () => {
    const endedSessions = sessions;

    if (endedSessions.length === 0) {
      return (
        <Empty
          image={Empty.PRESENTED_IMAGE_SIMPLE}
          description="暂无历史记录"
          style={{ marginTop: 48 }}
        />
      );
    }

    return (
      <List
        dataSource={endedSessions}
        renderItem={session => (
          <List.Item
            style={{
              padding: '12px 16px',
              cursor: 'pointer',
              background:
                session.id === selectedSessionId
                  ? isDarkMode
                    ? '#177ddc20'
                    : '#e6f7ff'
                  : 'transparent',
              borderBottom: `1px solid ${isDarkMode ? '#303030' : '#f0f0f0'}`,
            }}
            onClick={() => onSelectSession(session.id)}
          >
            <List.Item.Meta
              avatar={<Avatar icon={<UserOutlined />} />}
              title={session.peer_device_name}
              description={
                <Space size={4}>
                  <ClockCircleOutlined style={{ fontSize: 10 }} />
                  <Text type="secondary" style={{ fontSize: 12 }}>
                    {formatTime(session.started_at)}
                  </Text>
                  <Tag style={{ fontSize: 10, marginLeft: 4 }}>
                    {session.connection_type === 'lan' ? '局域网' : '中继'}
                  </Tag>
                </Space>
              }
            />
          </List.Item>
        )}
      />
    );
  };

  return (
    <div
      style={{
        height: 'calc(100% - 140px)',
        overflow: 'hidden',
        display: 'flex',
        flexDirection: 'column',
      }}
    >
      <Tabs
        activeKey={activeTab}
        onChange={key => setActiveTab(key as 'online' | 'history')}
        centered
        size="small"
        style={{ marginBottom: 0 }}
        items={[
          {
            key: 'online',
            label: (
              <Space size={4}>
                <Badge count={connectedDevices.length} size="small" offset={[8, 0]}>
                  <span>在线</span>
                </Badge>
              </Space>
            ),
          },
          {
            key: 'history',
            label: '历史',
          },
        ]}
      />

      <div style={{ flex: 1, overflow: 'auto' }}>
        {activeTab === 'online' ? renderOnlineDevices() : renderHistorySessions()}
      </div>
    </div>
  );
};

export default DeviceListView;

import { DatabaseManager } from '../database/Database';
import {
  decryptLocalPayload,
  encryptLocalPayload,
  isLocalPayloadEncrypted,
} from '../database/LocalPayloadCrypto';

export interface NoteVersion {
  id: number;
  noteId: string;
  title: string;
  content: string;
  createdAt: number;
  size: number;
}

export class VersionHistory {
  private db: DatabaseManager;
  private maxVersions: number;
  private minInterval: number;  // 最小保存间隔（毫秒）

  constructor(db: DatabaseManager, maxVersions: number = 50, minInterval: number = 60000) {
    this.db = db;
    this.maxVersions = maxVersions;
    this.minInterval = minInterval;
    this.initializeTable();
    const migrated = this.migratePlainVersionsToEncrypted();
    if (migrated > 0) {
      this.compactDatabase();
    }
  }

  // 初始化版本历史表
  private initializeTable(): void {
    this.db.getDatabase().exec(`
      CREATE TABLE IF NOT EXISTS note_versions (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        note_id TEXT NOT NULL,
        title TEXT NOT NULL,
        content TEXT NOT NULL,
        created_at INTEGER NOT NULL,
        size INTEGER NOT NULL,
        FOREIGN KEY (note_id) REFERENCES items(id) ON DELETE CASCADE
      )
    `);

    this.db.getDatabase().exec(`
      CREATE INDEX IF NOT EXISTS idx_note_versions_note_id ON note_versions(note_id)
    `);

    this.db.getDatabase().exec(`
      CREATE INDEX IF NOT EXISTS idx_note_versions_created_at ON note_versions(created_at)
    `);
  }

  // 保存版本
  saveVersion(noteId: string, title: string, content: string): boolean {
    // 检查是否需要保存（避免频繁保存）
    const lastVersion = this.getLatestVersion(noteId);
    if (lastVersion) {
      const timeSinceLastSave = Date.now() - lastVersion.createdAt;
      if (timeSinceLastSave < this.minInterval) {
        return false;
      }
      // 如果内容没有变化，不保存
      if (lastVersion.content === content && lastVersion.title === title) {
        return false;
      }
    }

    const size = new Blob([content]).size;
    this.db.run(
      'INSERT INTO note_versions (note_id, title, content, created_at, size) VALUES (?, ?, ?, ?, ?)',
      [noteId, encryptLocalPayload(title), encryptLocalPayload(content), Date.now(), size]
    );

    // 清理旧版本
    this.cleanupOldVersions(noteId);

    return true;
  }

  // 获取笔记的所有版本
  getVersions(noteId: string): NoteVersion[] {
    return this.db.query<NoteVersion>(
      'SELECT id, note_id as noteId, title, content, created_at as createdAt, size FROM note_versions WHERE note_id = ? ORDER BY created_at DESC',
      [noteId]
    ).map(version => this.decryptVersion(version));
  }

  // 获取最新版本
  getLatestVersion(noteId: string): NoteVersion | undefined {
    const version = this.db.get<NoteVersion>(
      'SELECT id, note_id as noteId, title, content, created_at as createdAt, size FROM note_versions WHERE note_id = ? ORDER BY created_at DESC LIMIT 1',
      [noteId]
    );
    return version ? this.decryptVersion(version) : undefined;
  }

  // 获取特定版本
  getVersion(versionId: number): NoteVersion | undefined {
    const version = this.db.get<NoteVersion>(
      'SELECT id, note_id as noteId, title, content, created_at as createdAt, size FROM note_versions WHERE id = ?',
      [versionId]
    );
    return version ? this.decryptVersion(version) : undefined;
  }

  // 恢复到特定版本
  restoreVersion(versionId: number): { noteId: string; title: string; content: string } | null {
    const version = this.getVersion(versionId);
    if (!version) return null;

    return {
      noteId: version.noteId,
      title: version.title,
      content: version.content,
    };
  }

  // 删除特定版本
  deleteVersion(versionId: number): boolean {
    const result = this.db.run('DELETE FROM note_versions WHERE id = ?', [versionId]);
    return result.changes > 0;
  }

  // 删除笔记的所有版本
  deleteAllVersions(noteId: string): number {
    const result = this.db.run('DELETE FROM note_versions WHERE note_id = ?', [noteId]);
    return result.changes;
  }

  // 清理旧版本
  private cleanupOldVersions(noteId: string): void {
    const versions = this.getVersions(noteId);
    if (versions.length > this.maxVersions) {
      const toDelete = versions.slice(this.maxVersions);
      for (const version of toDelete) {
        this.deleteVersion(version.id);
      }
    }
  }

  // 获取版本统计
  getStats(noteId: string): { count: number; totalSize: number; oldestDate: number | null; newestDate: number | null } {
    const result = this.db.get<{
      count: number;
      totalSize: number;
      oldestDate: number | null;
      newestDate: number | null;
    }>(
      `SELECT 
        COUNT(*) as count, 
        COALESCE(SUM(size), 0) as totalSize,
        MIN(created_at) as oldestDate,
        MAX(created_at) as newestDate
      FROM note_versions WHERE note_id = ?`,
      [noteId]
    );

    return result || { count: 0, totalSize: 0, oldestDate: null, newestDate: null };
  }

  // 比较两个版本
  compareVersions(versionId1: number, versionId2: number): { added: string[]; removed: string[]; changed: boolean } {
    const v1 = this.getVersion(versionId1);
    const v2 = this.getVersion(versionId2);

    if (!v1 || !v2) {
      return { added: [], removed: [], changed: false };
    }

    const lines1 = v1.content.split('\n');
    const lines2 = v2.content.split('\n');

    const set1 = new Set(lines1);
    const set2 = new Set(lines2);

    const added = lines2.filter(line => !set1.has(line));
    const removed = lines1.filter(line => !set2.has(line));

    return {
      added,
      removed,
      changed: added.length > 0 || removed.length > 0,
    };
  }

  // 全局清理（清理所有笔记的旧版本）
  globalCleanup(): number {
    const noteIds = this.db.query<{ note_id: string }>(
      'SELECT DISTINCT note_id FROM note_versions'
    );

    let totalDeleted = 0;
    for (const { note_id } of noteIds) {
      const versions = this.getVersions(note_id);
      if (versions.length > this.maxVersions) {
        const toDelete = versions.slice(this.maxVersions);
        for (const version of toDelete) {
          this.deleteVersion(version.id);
          totalDeleted++;
        }
      }
    }

    return totalDeleted;
  }

  private decryptVersion(version: NoteVersion): NoteVersion {
    return {
      ...version,
      title: isLocalPayloadEncrypted(version.title) ? decryptLocalPayload(version.title) : version.title,
      content: isLocalPayloadEncrypted(version.content)
        ? decryptLocalPayload(version.content)
        : version.content,
    };
  }

  private migratePlainVersionsToEncrypted(): number {
    const versions = this.db.query<NoteVersion>(
      'SELECT id, note_id as noteId, title, content, created_at as createdAt, size FROM note_versions'
    );
    const plainVersions = versions.filter(
      version => !isLocalPayloadEncrypted(version.title) || !isLocalPayloadEncrypted(version.content)
    );
    if (plainVersions.length === 0) {
      return 0;
    }

    this.db.transaction(() => {
      for (const version of plainVersions) {
        this.db.run('UPDATE note_versions SET title = ?, content = ? WHERE id = ?', [
          encryptLocalPayload(version.title),
          encryptLocalPayload(version.content),
          version.id,
        ]);
      }
    });
    return plainVersions.length;
  }

  private compactDatabase(): void {
    try {
      this.db.getDatabase().pragma('wal_checkpoint(TRUNCATE)');
      this.db.getDatabase().exec('VACUUM');
      this.db.getDatabase().pragma('wal_checkpoint(TRUNCATE)');
    } catch (error) {
      console.warn('[VersionHistory] Failed to compact database after encryption migration:', error);
    }
  }
}

export default VersionHistory;

/**
 * 排序和筛选对话框组件
 */

import React, { useState, useCallback, useMemo } from 'react';
import { Modal, Select, Radio, Button, Space, Tag, Checkbox, Input, Divider } from 'antd';
import { SortAscendingOutlined, SortDescendingOutlined, FilterOutlined } from '@ant-design/icons';

// 列索引转字母
const colToLetter = (col: number): string => {
  let result = '';
  let n = col;
  while (n >= 0) {
    result = String.fromCharCode(65 + (n % 26)) + result;
    n = Math.floor(n / 26) - 1;
  }
  return result;
};

// 排序配置
export interface SortConfig {
  column: number;
  order: 'asc' | 'desc';
}

// 筛选条件
export interface FilterCondition {
  column: number;
  type: 'equals' | 'contains' | 'startsWith' | 'endsWith' | 'greaterThan' | 'lessThan' | 'between' | 'empty' | 'notEmpty';
  value: string;
  value2?: string; // 用于 between
}

interface SortDialogProps {
  open: boolean;
  columnCount: number;
  onClose: () => void;
  onSort: (config: SortConfig) => void;
}

export const SortDialog: React.FC<SortDialogProps> = ({
  open,
  columnCount,
  onClose,
  onSort,
}) => {
  const [column, setColumn] = useState(0);
  const [order, setOrder] = useState<'asc' | 'desc'>('asc');

  const columnOptions = useMemo(() => {
    return Array.from({ length: Math.min(columnCount, 26) }, (_, i) => ({
      value: i,
      label: `列 ${colToLetter(i)}`,
    }));
  }, [columnCount]);

  const handleSort = useCallback(() => {
    onSort({ column, order });
    onClose();
  }, [column, order, onSort, onClose]);

  return (
    <Modal
      title={
        <Space>
          <SortAscendingOutlined />
          排序
        </Space>
      }
      open={open}
      onCancel={onClose}
      onOk={handleSort}
      okText="排序"
      cancelText="取消"
      width={350}
    >
      <div style={{ display: 'flex', flexDirection: 'column', gap: 16 }}>
        <div>
          <div style={{ marginBottom: 8, fontSize: 12, color: '#666' }}>排序列</div>
          <Select
            value={column}
            onChange={setColumn}
            options={columnOptions}
            style={{ width: '100%' }}
          />
        </div>

        <div>
          <div style={{ marginBottom: 8, fontSize: 12, color: '#666' }}>排序方式</div>
          <Radio.Group value={order} onChange={(e) => setOrder(e.target.value)}>
            <Radio.Button value="asc">
              <SortAscendingOutlined /> 升序 (A→Z, 1→9)
            </Radio.Button>
            <Radio.Button value="desc">
              <SortDescendingOutlined /> 降序 (Z→A, 9→1)
            </Radio.Button>
          </Radio.Group>
        </div>
      </div>
    </Modal>
  );
};

interface FilterDialogProps {
  open: boolean;
  columnCount: number;
  activeFilters: FilterCondition[];
  onClose: () => void;
  onApplyFilter: (conditions: FilterCondition[]) => void;
  onClearFilters: () => void;
}

export const FilterDialog: React.FC<FilterDialogProps> = ({
  open,
  columnCount,
  activeFilters,
  onClose,
  onApplyFilter,
  onClearFilters,
}) => {
  const [conditions, setConditions] = useState<FilterCondition[]>(
    activeFilters.length > 0 ? activeFilters : [{ column: 0, type: 'contains', value: '' }]
  );

  // 当对话框打开时，同步 activeFilters 到 conditions
  React.useEffect(() => {
    if (open) {
      setConditions(activeFilters.length > 0 ? activeFilters : [{ column: 0, type: 'contains', value: '' }]);
    }
  }, [open, activeFilters]);

  const columnOptions = useMemo(() => {
    return Array.from({ length: Math.min(columnCount, 26) }, (_, i) => ({
      value: i,
      label: `列 ${colToLetter(i)}`,
    }));
  }, [columnCount]);

  const filterTypeOptions = [
    { value: 'equals', label: '等于' },
    { value: 'contains', label: '包含' },
    { value: 'startsWith', label: '开头是' },
    { value: 'endsWith', label: '结尾是' },
    { value: 'greaterThan', label: '大于' },
    { value: 'lessThan', label: '小于' },
    { value: 'between', label: '介于' },
    { value: 'empty', label: '为空' },
    { value: 'notEmpty', label: '不为空' },
  ];

  const updateCondition = useCallback((index: number, updates: Partial<FilterCondition>) => {
    setConditions(prev => prev.map((c, i) => i === index ? { ...c, ...updates } : c));
  }, []);

  const addCondition = useCallback(() => {
    setConditions(prev => [...prev, { column: 0, type: 'contains', value: '' }]);
  }, []);

  const removeCondition = useCallback((index: number) => {
    setConditions(prev => prev.filter((_, i) => i !== index));
  }, []);

  const handleApply = useCallback(() => {
    // 过滤掉空条件
    const validConditions = conditions.filter(c => 
      c.type === 'empty' || c.type === 'notEmpty' || c.value.trim() !== ''
    );
    onApplyFilter(validConditions);
    onClose();
  }, [conditions, onApplyFilter, onClose]);

  const handleClear = useCallback(() => {
    onClearFilters();
    setConditions([{ column: 0, type: 'contains', value: '' }]);
    onClose();
  }, [onClearFilters, onClose]);

  return (
    <Modal
      title={
        <Space>
          <FilterOutlined />
          筛选
          {activeFilters.length > 0 && <Tag color="blue">{activeFilters.length} 个条件</Tag>}
        </Space>
      }
      open={open}
      onCancel={onClose}
      footer={
        <Space>
          <Button onClick={handleClear} danger>清除筛选</Button>
          <Button onClick={onClose}>取消</Button>
          <Button type="primary" onClick={handleApply}>应用</Button>
        </Space>
      }
      width={500}
    >
      <div style={{ display: 'flex', flexDirection: 'column', gap: 12 }}>
        {conditions.map((condition, index) => (
          <div key={index} style={{ display: 'flex', gap: 8, alignItems: 'center' }}>
            <Select
              value={condition.column}
              onChange={(v) => updateCondition(index, { column: v })}
              options={columnOptions}
              style={{ width: 100 }}
              size="small"
            />
            <Select
              value={condition.type}
              onChange={(v) => updateCondition(index, { type: v as FilterCondition['type'] })}
              options={filterTypeOptions}
              style={{ width: 100 }}
              size="small"
            />
            {condition.type !== 'empty' && condition.type !== 'notEmpty' && (
              <>
                <Input
                  value={condition.value}
                  onChange={(e) => updateCondition(index, { value: e.target.value })}
                  placeholder="值"
                  style={{ flex: 1 }}
                  size="small"
                />
                {condition.type === 'between' && (
                  <>
                    <span>到</span>
                    <Input
                      value={condition.value2 || ''}
                      onChange={(e) => updateCondition(index, { value2: e.target.value })}
                      placeholder="值"
                      style={{ flex: 1 }}
                      size="small"
                    />
                  </>
                )}
              </>
            )}
            {conditions.length > 1 && (
              <Button size="small" danger onClick={() => removeCondition(index)}>
                删除
              </Button>
            )}
          </div>
        ))}

        <Button type="dashed" onClick={addCondition} style={{ width: '100%' }}>
          + 添加条件
        </Button>
      </div>
    </Modal>
  );
};

