interface TemplateSelectorProps {
  open: boolean;
  onClose: () => void;
  onSelect: (title: string, content: string) => void;
}

const TemplateSelector: React.FC<TemplateSelectorProps> = ({ open, onClose, onSelect }) => {
  const [selectedTemplate, setSelectedTemplate] = useState<NoteTemplate | null>(null);
  const [form] = Form.useForm();

  const handleTemplateClick = (template: NoteTemplate) => {
    if (template.variables.length === 0) {
      // 无变量，直接应用
      onSelect(template.name, template.content);
      onClose();
    } else {
      setSelectedTemplate(template);
      form.resetFields();
    }
  };

  const handleApplyTemplate = () => {
    if (!selectedTemplate) return;

    const values = form.getFieldsValue();
    let content = selectedTemplate.content;
    let title = selectedTemplate.name;

    // 替换变量
    for (const variable of selectedTemplate.variables) {
      let value = values[variable.name] || variable.defaultValue || '';

      // 处理日期类型
      if (value && value.$d) {
        const date = value.$d;
        if (variable.type === 'date') {
          value = date.toLocaleDateString('zh-CN');
        } else if (variable.type === 'time') {
          value = date.toLocaleTimeString('zh-CN', { hour: '2-digit', minute: '2-digit' });
        }
      }

      content = content.replace(new RegExp(`{{${variable.name}}}`, 'g'), value);

      if (variable.name === 'title' && value) {
        title = value;
      } else if (variable.name === 'bookTitle' && value) {
        title = `《${value}》读书笔记`;
      }
    }

    // 生成标题
    if (selectedTemplate.id === 'diary') {
      title = `${new Date().toLocaleDateString('zh-CN')} 日记`;
    }

    onSelect(title, content);
    setSelectedTemplate(null);
    onClose();
  };

  const renderVariableInput = (variable: TemplateVariable) => {
    switch (variable.type) {
      case 'select':
        return (
          <Select options={variable.options?.map(o => ({ value: o, label: o }))} />
        );
      case 'date':
        return <DatePicker style={{ width: '100%' }} />;
      case 'time':
        return <TimePicker style={{ width: '100%' }} format="HH:mm" />;
      default:
        return <Input placeholder={variable.label} />;
    }
  };

  return (
    <>
      <Modal
        title="选择模板"
        open={open && !selectedTemplate}
        onCancel={onClose}
        footer={null}
        width={600}
      >
        <Row gutter={[16, 16]}>
          {DEFAULT_TEMPLATES.map(template => (
            <Col span={8} key={template.id}>
              <Card
                hoverable
                onClick={() => handleTemplateClick(template)}
                style={{ textAlign: 'center' }}
              >
                <div style={{ fontSize: 32, marginBottom: 8 }}>{template.icon}</div>
                <div style={{ fontWeight: 500 }}>{template.name}</div>
                <div style={{ fontSize: 12, color: '#666' }}>{template.description}</div>
              </Card>
            </Col>
          ))}
        </Row>
      </Modal>

      <Modal
        title={`${selectedTemplate?.icon} ${selectedTemplate?.name}`}
        open={!!selectedTemplate}
        onCancel={() => setSelectedTemplate(null)}
        onOk={handleApplyTemplate}
        okText="创建笔记"
      >
        <Form form={form} layout="vertical">
          {selectedTemplate?.variables.map(variable => (
            <Form.Item
              key={variable.name}
              name={variable.name}
              label={variable.label}
              initialValue={variable.defaultValue}
            >
              {renderVariableInput(variable)}
            </Form.Item>
          ))}
        </Form>
      </Modal>
    </>
  );
};

export default TemplateSelector;

import { useState, useEffect, useCallback } from 'react';
import { ItemBase, NotePayload, ExcelNotePayload } from '@shared/types';
import { notesApi, itemsApi, parsePayload } from '../services/itemsApi';

export interface Note {
  id: string;
  title: string;
  content: string;
  folderId: string | null;
  isPinned: boolean;
  isLocked: boolean;
  lockPasswordHash: string | null;
  tags: string[];
  createdAt: number;
  updatedAt: number;
  type: 'note' | 'excel_note'; // 笔记类型
}

function itemToNote(item: ItemBase): Note {
  // 判断是否是 Excel 笔记
  if (item.type === 'excel_note') {
    const payload = parsePayload<ExcelNotePayload>(item);
    return {
      id: item.id,
      title: payload.title || '',
      content: '', // Excel 笔记没有 content
      folderId: payload.folder_id ?? null,
      isPinned: payload.is_pinned ?? false,
      isLocked: payload.is_locked ?? false,
      lockPasswordHash: payload.lock_password_hash ?? null,
      tags: payload.tags || [],
      createdAt: item.created_time,
      updatedAt: item.updated_time,
      type: 'excel_note',
    };
  } 

  // 普通笔记
  const payload = parsePayload<NotePayload>(item);
  return {
    id: item.id,
    title: payload.title || '',
    content: payload.content || '',
    folderId: payload.folder_id ?? null,
    isPinned: payload.is_pinned ?? false,
    isLocked: payload.is_locked ?? false,
    lockPasswordHash: payload.lock_password_hash ?? null,
    tags: payload.tags || [],  // 确保 tags 始终是数组
    createdAt: item.created_time,
    updatedAt: item.updated_time,
    type: 'note',
  };
}

export function useNotes(folderId: string | null) {
  const [notes, setNotes] = useState<Note[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<Error | null>(null);

  const loadNotes = useCallback(async () => {
    try {
      setLoading(true);
      setError(null);
      // 使用新的 API 同时获取普通笔记和 Excel 笔记
      const items = await notesApi.getAllWithExcel(folderId);
      if (items && Array.isArray(items)) {
        const noteList = items.map(itemToNote);
        // 置顶笔记优先
        noteList.sort((a: Note, b: Note) => {
          if (a.isPinned && !b.isPinned) return -1;
          if (!a.isPinned && b.isPinned) return 1;
          return b.updatedAt - a.updatedAt;
        });
        setNotes(noteList);
      } else {
        setNotes([]);
      }
    } catch (err) {
      setError(err as Error);
      setNotes([]);
    } finally {
      setLoading(false);
    }
  }, [folderId]);

  useEffect(() => {
    loadNotes();
  }, [loadNotes]);

  const createNote = useCallback(async (title: string, content: string = '') => {
    const payload: NotePayload = {
      title,
      content,
      folder_id: folderId,
      is_pinned: false,
      is_locked: false,
      lock_password_hash: null,
      tags: [],
    };
    const item = await notesApi.create(payload);
    if (item) {
      await loadNotes();
      return itemToNote(item);
    }
    return null;
  }, [folderId, loadNotes]);

  const updateNote = useCallback(async (id: string, updates: Partial<NotePayload>) => {
    const note = notes.find(n => n.id === id);
    if (!note) return null;

    // 获取当前笔记的完整 payload（包括 lock_password_hash）
    const currentItem = await itemsApi.getById(id);
    const currentPayload = currentItem ? parsePayload<NotePayload>(currentItem) : null;

    const payload: NotePayload = {
      title: updates.title ?? note.title,
      content: updates.content ?? note.content,
      folder_id: updates.folder_id ?? note.folderId,
      is_pinned: updates.is_pinned ?? note.isPinned,
      is_locked: updates.is_locked ?? note.isLocked,
      lock_password_hash: 'lock_password_hash' in updates ? (updates.lock_password_hash ?? null) : (currentPayload?.lock_password_hash ?? null),
      tags: updates.tags ?? note.tags,
    };

    const item = await notesApi.update(id, payload);
    if (item) {
      await loadNotes();
      return itemToNote(item);
    }
    return null;
  }, [notes, loadNotes]);

  const deleteNote = useCallback(async (id: string) => {
    const success = await notesApi.delete(id);
    if (success) {
      await loadNotes();
    }
    return success;
  }, [loadNotes]);

  const searchNotes = useCallback(async (query: string) => {
    if (!query.trim()) {
      await loadNotes();
      return;
    }
    const items = await notesApi.search(query);
    if (items) {
      setNotes(items.map(itemToNote));
    }
  }, [loadNotes]);

  // 锁定笔记
  const lockNote = useCallback(async (id: string, passwordHash: string) => {
    const note = notes.find(n => n.id === id);
    if (!note) return null;

    const payload: NotePayload = {
      title: note.title,
      content: note.content,
      folder_id: note.folderId,
      is_pinned: note.isPinned,
      is_locked: true,
      lock_password_hash: passwordHash,
      tags: note.tags,
    };

    const item = await notesApi.update(id, payload);
    if (item) {
      await loadNotes();
      return itemToNote(item);
    }
    return null;
  }, [notes, loadNotes]);

  // 解锁笔记（移除加密）
  const unlockNote = useCallback(async (id: string) => {
    const note = notes.find(n => n.id === id);
    if (!note) return null;

    const payload: NotePayload = {
      title: note.title,
      content: note.content,
      folder_id: note.folderId,
      is_pinned: note.isPinned,
      is_locked: false,
      lock_password_hash: null,
      tags: note.tags,
    };

    const item = await notesApi.update(id, payload);
    if (item) {
      await loadNotes();
      return itemToNote(item);
    }
    return null;
  }, [notes, loadNotes]);

  return {
    notes,
    loading,
    error,
    createNote,
    updateNote,
    deleteNote,
    searchNotes,
    lockNote,
    unlockNote,
    refresh: loadNotes,
  };
}

export function useNote(noteId: string | null, includeDeleted: boolean = false) {
  const [note, setNote] = useState<Note | null>(null);
  const [loading, setLoading] = useState(false);

  useEffect(() => {
    if (!noteId) {
      setNote(null);
      return;
    }

    setLoading(true);
    const fetchNote = includeDeleted 
      ? itemsApi.getByIdIncludeDeleted(noteId)
      : itemsApi.getById(noteId);

    fetchNote.then(item => {
      if (item) {
        setNote(itemToNote(item));
      } else {
        setNote(null);
      }
      setLoading(false);
    }).catch(() => {
      setNote(null);
      setLoading(false);
    });
  }, [noteId, includeDeleted]);

  return { note, loading };
}

