  syncOnChange: boolean;
  changeDebounce: number;  // 秒
  initialLastSyncTime?: number | null;  // 初始的上次同步时间（从持久化存储加载）
  onSyncComplete?: (lastSyncTime: number) => void;  // 同步完成回调（用于持久化）
}

export type SyncStatus = 'idle' | 'syncing' | 'error' | 'offline';

export interface SyncState {
  status: SyncStatus;
  lastSyncTime: number | null;
  lastSyncResult: SyncResult | null;
  pendingChanges: number;
  isOnline: boolean;
  progress: SyncProgress | null;  // 当前同步进度
}

type SyncEventCallback = (state: SyncState) => void;

export class SyncScheduler {
  private syncEngine: SyncEngine;
  private options: SyncSchedulerOptions;
  private state: SyncState;
  private intervalId: NodeJS.Timeout | null = null;
  private debounceId: NodeJS.Timeout | null = null;
  private listeners: Set<SyncEventCallback> = new Set();

  constructor(syncEngine: SyncEngine, options: Partial<SyncSchedulerOptions> = {}) {
    this.syncEngine = syncEngine;
    this.options = {
      autoSyncOnStart: false,  // 默认不在启动时立即同步，而是按间隔时间同步
      syncInterval: 5,
      syncOnChange: true,
      changeDebounce: 30,
      ...options,
    };
    this.state = {
      status: 'idle',
      lastSyncTime: this.options.initialLastSyncTime || null,  // 从选项中加载初始值
      lastSyncResult: null,
      pendingChanges: 0,
      isOnline: true,
      progress: null,
    };

    // 设置进度回调
    this.syncEngine.setProgressCallback((progress) => {
      this.updateState({ progress });
    });

    // 监听网络状态
    if (typeof window !== 'undefined') {
      window.addEventListener('online', () => this.handleOnline());
      window.addEventListener('offline', () => this.handleOffline());
      this.state.isOnline = navigator.onLine;
    }
  }

  // 启动调度器
  start(): void {
    if (this.options.autoSyncOnStart) {
      this.triggerSync();
    }

    if (this.options.syncInterval > 0) {
      this.startInterval();
    }
  }

  // 停止调度器
  stop(): void {
    this.stopInterval();
    this.cancelDebounce();
  }

  // 手动触发同步
  async triggerSync(force = false): Promise<SyncResult | null> {
    if (this.state.status === 'syncing') {
      if (force) {
        // 手动触发时等待当前同步完成后再执行
        console.log('Sync in progress, waiting to re-trigger after completion');
        return new Promise((resolve) => {
          const unsub = this.subscribe((state) => {
            if (state.status !== 'syncing') {
              unsub();
              resolve(this.triggerSync(false));
            }
          });
        });
      }
      console.log('Sync already in progress');
      return null;
    }

    if (!this.state.isOnline) {
      console.log('Offline, skipping sync');
      return null;
    }

    // 取消任何待执行的防抖自动同步，避免重复触发
    this.cancelDebounce();

    this.updateState({ status: 'syncing', progress: { phase: 'connecting', message: '正在连接服务器...' } });

    try {
      const result = await this.syncEngine.sync();
      const syncTime = Date.now();
      this.updateState({
        status: result.success ? 'idle' : 'error',
        lastSyncTime: syncTime,
        lastSyncResult: result,
        pendingChanges: 0,
        progress: null,
      });

      // 通知外部持久化同步时间
      if (result.success && this.options.onSyncComplete) {
        this.options.onSyncComplete(syncTime);
      }

      return result;
    } catch (error) {
      console.error('Sync failed:', error);
      this.updateState({
        status: 'error',
        lastSyncResult: {
          success: false,
          pushed: 0,
          pulled: 0,
          conflicts: 0,
          errors: [(error as Error).message],
          duration: 0,
        },
        progress: { phase: 'error', message: '同步失败', detail: (error as Error).message },
      });
      return null;
    }
  }

  // 通知有内容变更（触发防抖同步）
  notifyChange(): void {
    if (!this.options.syncOnChange) return;

    this.updateState({ pendingChanges: this.state.pendingChanges + 1 });

    this.cancelDebounce();
    this.debounceId = setTimeout(() => {
      this.triggerSync(false);
    }, this.options.changeDebounce * 1000);
  }

  // 获取当前状态
  getState(): SyncState {
    return { ...this.state };
  }

  // 订阅状态变化
  subscribe(callback: SyncEventCallback): () => void {
    this.listeners.add(callback);
    return () => this.listeners.delete(callback);
  }

  // 更新配置
  updateOptions(options: Partial<SyncSchedulerOptions>): void {
    const oldInterval = this.options.syncInterval;
    this.options = { ...this.options, ...options };

    // 如果间隔变化，重启定时器
    if (oldInterval !== this.options.syncInterval) {
      this.stopInterval();
      if (this.options.syncInterval > 0) {
        this.startInterval();
      }
    }
  }

  // 启动定时同步
  private startInterval(): void {
    this.stopInterval();
    const intervalMs = this.options.syncInterval * 60 * 1000;
    this.intervalId = setInterval(() => {
      this.triggerSync();
    }, intervalMs);
  }

  // 停止定时同步
  private stopInterval(): void {
    if (this.intervalId) {
      clearInterval(this.intervalId);
      this.intervalId = null;
    }
  }

  // 取消防抖
  private cancelDebounce(): void {
    if (this.debounceId) {
      clearTimeout(this.debounceId);
      this.debounceId = null;
    }
  }

  // 处理上线
  private handleOnline(): void {
    this.updateState({ isOnline: true, status: 'idle' });
    // 上线后立即同步
    this.triggerSync(false);
  }

  // 处理离线
  private handleOffline(): void {
    this.updateState({ isOnline: false, status: 'offline' });
    this.cancelDebounce();
  }

  // 更新状态并通知监听器
  private updateState(updates: Partial<SyncState>): void {
    this.state = { ...this.state, ...updates };
    this.listeners.forEach(callback => callback(this.state));
  }
}

export default SyncScheduler;

package com.mucheng.notes.presentation.viewmodel

import androidx.lifecycle.ViewModel
import androidx.lifecycle.viewModelScope
import com.mucheng.notes.data.local.entity.ItemEntity
import com.mucheng.notes.domain.model.ItemType
import com.mucheng.notes.domain.model.payload.TodoPayload
import com.mucheng.notes.domain.model.payload.TodoQuadrant
import com.mucheng.notes.domain.repository.ItemRepository
import dagger.hilt.android.lifecycle.HiltViewModel
import kotlinx.coroutines.flow.MutableStateFlow
import kotlinx.coroutines.flow.SharingStarted
import kotlinx.coroutines.flow.StateFlow
import kotlinx.coroutines.flow.asStateFlow
import kotlinx.coroutines.flow.map
import kotlinx.coroutines.flow.stateIn
import kotlinx.coroutines.launch
import kotlinx.serialization.encodeToString
import kotlinx.serialization.json.Json
import javax.inject.Inject

/**
 * 待办 UI 状态
 */
data class TodosUiState(
    val isLoading: Boolean = false,
    val error: String? = null,
    val showCompleted: Boolean = false
)

/**
 * 待办事项视图模型
 */
@HiltViewModel
class TodosViewModel @Inject constructor(
    private val itemRepository: ItemRepository
) : ViewModel() {

    private val json = Json { 
        ignoreUnknownKeys = true 
        isLenient = true
        coerceInputValues = true
    }

    private val _uiState = MutableStateFlow(TodosUiState())
    val uiState: StateFlow<TodosUiState> = _uiState.asStateFlow()

    /**
     * 待办列表（实时流）
     */
    val todos: StateFlow<List<TodoItem>> = itemRepository.getByType(ItemType.TODO)
        .map { items -> items.map { it.toTodoItem() } }
        .stateIn(viewModelScope, SharingStarted.Lazily, emptyList())

    /**
     * 按象限分组的待办
     */
    val todosByQuadrant: StateFlow<Map<TodoQuadrant, List<TodoItem>>> = todos
        .map { list -> list.groupBy { it.quadrant } }
        .stateIn(viewModelScope, SharingStarted.Lazily, emptyMap())

    /**
     * 创建待办
     */
    fun createTodo(
        title: String,
        description: String = "",
        quadrant: TodoQuadrant = TodoQuadrant.NOT_URGENT_NOT_IMPORTANT,
        dueDate: Long? = null,
        reminderTime: Long? = null
    ) {
        viewModelScope.launch {
            val payload = TodoPayload(
                title = title,
                description = description,
                quadrant = quadrant,
                completed = false,
                completedAt = null,
                dueDate = dueDate,
                reminderTime = reminderTime,
                reminderEnabled = reminderTime != null,
                priority = 0,
                tags = emptyList()
            )
            itemRepository.create(ItemType.TODO, json.encodeToString(payload))
        }
    }

    /**
     * 更新待办
     */
    fun updateTodo(id: String, title: String, description: String, quadrant: TodoQuadrant? = null) {
        viewModelScope.launch {
            val existing = itemRepository.getById(id) ?: return@launch
            val oldPayload = json.decodeFromString<TodoPayload>(existing.payload)
            val newPayload = oldPayload.copy(
                title = title, 
                description = description,
                quadrant = quadrant ?: oldPayload.quadrant
            )
            itemRepository.update(id, json.encodeToString(newPayload))
        }
    }

    /**
     * 完整更新待办（包括到期时间和提醒）
     */
    fun updateTodoFull(
        id: String, 
        title: String, 
        description: String, 
        quadrant: TodoQuadrant,
        dueDate: Long?,
        reminderTime: Long?
    ) {
        viewModelScope.launch {
            val existing = itemRepository.getById(id) ?: return@launch
            val oldPayload = json.decodeFromString<TodoPayload>(existing.payload)
            val newPayload = oldPayload.copy(
                title = title, 
                description = description,
                quadrant = quadrant,
                dueDate = dueDate,
                reminderTime = reminderTime,
                reminderEnabled = reminderTime != null
            )
            itemRepository.update(id, json.encodeToString(newPayload))
        }
    }

    /**
     * 切换完成状态
     */
    fun toggleCompleted(id: String) {
        viewModelScope.launch {
            val existing = itemRepository.getById(id) ?: return@launch
            val oldPayload = json.decodeFromString<TodoPayload>(existing.payload)
            val newPayload = oldPayload.copy(
                completed = !oldPayload.completed,
                completedAt = if (!oldPayload.completed) System.currentTimeMillis() else null
            )
            itemRepository.update(id, json.encodeToString(newPayload))
        }
    }

    /**
     * 更改象限
     */
    fun changeQuadrant(id: String, quadrant: TodoQuadrant) {
        viewModelScope.launch {
            val existing = itemRepository.getById(id) ?: return@launch
            val oldPayload = json.decodeFromString<TodoPayload>(existing.payload)
            val newPayload = oldPayload.copy(quadrant = quadrant)
            itemRepository.update(id, json.encodeToString(newPayload))
        }
    }

    /**
     * 删除待办
     */
    fun deleteTodo(id: String) {
        viewModelScope.launch {
            itemRepository.softDelete(id)
        }
    }

    /**
     * 设置提醒
     */
    fun setReminder(id: String, reminderTime: Long?) {
        viewModelScope.launch {
            val existing = itemRepository.getById(id) ?: return@launch
            val oldPayload = json.decodeFromString<TodoPayload>(existing.payload)
            val newPayload = oldPayload.copy(
                reminderTime = reminderTime,
                reminderEnabled = reminderTime != null
            )
            itemRepository.update(id, json.encodeToString(newPayload))
        }
    }

    /**
     * 切换显示已完成
     */
    fun toggleShowCompleted() {
        _uiState.value = _uiState.value.copy(showCompleted = !_uiState.value.showCompleted)
    }

    private fun ItemEntity.toTodoItem(): TodoItem {
        val payload = json.decodeFromString<TodoPayload>(this.payload)
        return TodoItem(
            id = this.id,
            title = payload.title,
            description = payload.description,
            quadrant = payload.quadrant,
            completed = payload.completed,
            completedAt = payload.completedAt,
            dueDate = payload.dueDate,
            reminderTime = payload.reminderTime,
            reminderEnabled = payload.reminderEnabled,
            priority = payload.priority,
            tags = payload.tags,
            updatedTime = this.updatedTime
        )
    }
}

/**
 * 待办展示模型
 */
data class TodoItem(
    val id: String,
    val title: String,
    val description: String,
    val quadrant: TodoQuadrant,
    val completed: Boolean,
    val completedAt: Long?,
    val dueDate: Long?,
    val reminderTime: Long?,
    val reminderEnabled: Boolean,
    val priority: Int,
    val tags: List<String>,
    val updatedTime: Long
)

import React, { useState } from 'react';
import { Input, List, Typography, Empty, Dropdown, Button } from 'antd';
import { 
  SearchOutlined, 
  LockOutlined,
  UnlockOutlined,
  MoreOutlined, 
  DeleteOutlined, 
  UndoOutlined,
  StarOutlined,
  StarFilled,
  CopyOutlined,
  FolderOutlined,
  PlusOutlined,
  FileAddOutlined,
  SnippetsOutlined,
  FileExcelOutlined,
  FileTextOutlined,
} from '@ant-design/icons';
import type { MenuProps } from 'antd';
import { Note } from '../hooks/useNotes';

const { Search } = Input;
const { Text } = Typography;

interface NoteListProps {
  notes: Note[];
  selectedNoteId: string | null;
  onSelectNote: (noteId: string) => void;
  onSearch?: (query: string) => void;
  onDeleteNote?: (noteId: string) => void;
  onRestoreNote?: (noteId: string) => void;
  onToggleStar?: (noteId: string, isStarred: boolean) => void;
  onDuplicateNote?: (noteId: string) => void;
  onMoveToFolder?: (noteId: string) => void;
  onLockNote?: (noteId: string) => void;
  onUnlockNote?: (noteId: string) => void;
  onCreateNote?: () => void;
  onCreateTemplateNote?: () => void;
  isTrashView?: boolean;
}

const NoteList: React.FC<NoteListProps> = ({
  notes,
  selectedNoteId,
  onSelectNote,
  onSearch,
  onDeleteNote,
  onRestoreNote,
  onToggleStar,
  onDuplicateNote,
  onMoveToFolder,
  onLockNote,
  onUnlockNote,
  onCreateNote,
  onCreateTemplateNote,
  isTrashView = false,
}) => {
  const [searchText, setSearchText] = useState('');

  const handleSearch = (value: string) => {
    setSearchText(value);
    onSearch?.(value);
  };

  const sortedNotes = [...notes].sort((a, b) => {
    if (a.isPinned && !b.isPinned) return -1;
    if (!a.isPinned && b.isPinned) return 1;
    return b.updatedAt - a.updatedAt;
  });

  const formatDate = (timestamp: number) => {
    const date = new Date(timestamp);
    return date.toLocaleDateString('zh-CN');
  };

  const highlightText = (text: string, query: string): React.ReactNode => {
    if (!query.trim()) return text;
    try {
      const escaped = query.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
      const regex = new RegExp('(' + escaped + ')', 'gi');
      const parts = text.split(regex);
      return parts.map((part, i) =>
        part.toLowerCase() === query.toLowerCase()
          ? <span key={i} style={{ backgroundColor: '#fff566', padding: '0 2px' }}>{part}</span>
          : part
      );
    } catch {
      return text;
    }
  };

  // 右键菜单项
  const getContextMenuItems = (note: Note): MenuProps['items'] => {
    if (isTrashView) {
      return [
        { key: 'restore', icon: <UndoOutlined />, label: '恢复', onClick: () => onRestoreNote?.(note.id) },
        { type: 'divider' },
        { key: 'delete', icon: <DeleteOutlined />, label: '永久删除', danger: true, onClick: () => onDeleteNote?.(note.id) },
      ];
    }
    return [
      { 
        key: 'star', 
        icon: note.isPinned ? <StarFilled style={{ color: '#faad14' }} /> : <StarOutlined />, 
        label: note.isPinned ? '取消星标' : '添加星标',
        onClick: () => onToggleStar?.(note.id, !note.isPinned),
      },
      { 
        key: 'lock', 
        icon: note.isLocked ? <UnlockOutlined /> : <LockOutlined />, 
        label: note.isLocked ? '解锁笔记' : '锁定笔记',
        onClick: () => note.isLocked ? onUnlockNote?.(note.id) : onLockNote?.(note.id),
      },
      { type: 'divider' },
      { key: 'duplicate', icon: <CopyOutlined />, label: '复制笔记', onClick: () => onDuplicateNote?.(note.id) },
      { key: 'move', icon: <FolderOutlined />, label: '移动到文件夹', onClick: () => onMoveToFolder?.(note.id) },
      { type: 'divider' },
      { key: 'delete', icon: <DeleteOutlined />, label: '删除', danger: true, onClick: () => onDeleteNote?.(note.id) },
    ];
  };

  // 下拉菜单项（更多按钮）
  const getDropdownItems = (note: Note): MenuProps['items'] => {
    if (isTrashView) {
      return [
        { key: 'restore', icon: <UndoOutlined />, label: '恢复', onClick: () => onRestoreNote?.(note.id) },
        { key: 'delete', icon: <DeleteOutlined />, label: '永久删除', danger: true, onClick: () => onDeleteNote?.(note.id) },
      ];
    }
    return [
      { 
        key: 'star', 
        icon: note.isPinned ? <StarFilled /> : <StarOutlined />, 
        label: note.isPinned ? '取消星标' : '添加星标',
        onClick: () => onToggleStar?.(note.id, !note.isPinned),
      },
      { 
        key: 'lock', 
        icon: note.isLocked ? <UnlockOutlined /> : <LockOutlined />, 
        label: note.isLocked ? '解锁' : '锁定',
        onClick: () => note.isLocked ? onUnlockNote?.(note.id) : onLockNote?.(note.id),
      },
      { key: 'duplicate', icon: <CopyOutlined />, label: '复制', onClick: () => onDuplicateNote?.(note.id) },
      { key: 'delete', icon: <DeleteOutlined />, label: '删除', danger: true, onClick: () => onDeleteNote?.(note.id) },
    ];
  };

  // 列表空白区域右键菜单
  const listContextMenuItems: MenuProps['items'] = [
    { key: 'new', icon: <FileAddOutlined />, label: '新建笔记', onClick: () => onCreateNote?.() },
    { key: 'new-template', icon: <SnippetsOutlined />, label: '从模板新建', onClick: () => onCreateTemplateNote?.() },
  ];

  return (
    <div className="note-list-container" style={{ display: 'flex', flexDirection: 'column', height: '100%' }}>
      <div style={{ padding: '10px 12px', borderBottom: '1px solid var(--border-color, #f0f0f0)', display: 'flex', gap: 8, alignItems: 'center' }}>
        <Search
          placeholder="搜索笔记..."
          prefix={<SearchOutlined style={{ color: '#bfbfbf' }} />}
          value={searchText}
          onChange={(e: React.ChangeEvent<HTMLInputElement>) => handleSearch(e.target.value)}
          allowClear
          size="small"
          style={{ borderRadius: 6, flex: 1 }}
        />
        {!isTrashView && (
          <Button 
            type="primary" 
            icon={<PlusOutlined />} 
            size="small" 
            onClick={onCreateNote}
            title="新建笔记"
          />
        )}
      </div>
      <Dropdown menu={{ items: listContextMenuItems }} trigger={['contextMenu']} disabled={isTrashView}>
        <div style={{ flex: 1, overflow: 'auto' }}>
          {sortedNotes.length === 0 ? (
            <Empty description={isTrashView ? "回收站为空" : "暂无笔记，右键新建"} style={{ marginTop: 40 }} />
          ) : (
            <List
              dataSource={sortedNotes}
              split={false}
              renderItem={(note: Note) => (
                <div onContextMenu={(e) => e.stopPropagation()}>
                  <Dropdown menu={{ items: getContextMenuItems(note) }} trigger={['contextMenu']}>
                    <List.Item
                      className={`note-list-item ${selectedNoteId === note.id ? 'selected' : ''}`}
                      onClick={() => onSelectNote(note.id)}
                      style={{
                        padding: '8px 12px',
                        margin: '2px 6px',
                        cursor: 'pointer',
                        borderRadius: 6,
                        border: 'none',
                      }}
                    >
                      <div style={{ width: '100%' }}>
                        <div style={{ display: 'flex', alignItems: 'center', gap: 6 }}>
                          {note.type === 'excel_note' && <FileExcelOutlined style={{ color: '#52c41a', fontSize: 12 }} />}
                          {note.isPinned && <StarFilled style={{ color: '#faad14', fontSize: 12 }} />}
                          {note.isLocked && <LockOutlined style={{ color: '#ff4d4f', fontSize: 12 }} />}
                          <Text strong ellipsis style={{ flex: 1, fontSize: 13 }}>
                            {searchText ? highlightText(note.title || '无标题', searchText) : (note.title || '无标题')}
                          </Text>
                          <Dropdown menu={{ items: getDropdownItems(note) }} trigger={['click']}>
                            <Button type="text" size="small" icon={<MoreOutlined />} onClick={(e: React.MouseEvent) => e.stopPropagation()} style={{ opacity: 0.5 }} />
                          </Dropdown>
                        </div>
                      </div>
                    </List.Item>
                  </Dropdown>
                </div>
              )}
            />
          )}
        </div>
      </Dropdown>
    </div>
  );
};

export default NoteList;

import * as crypto from 'crypto';

// 加密配置常量
const ALGORITHM = 'aes-256-gcm';
const KEY_LENGTH = 32; // 256 bits
const IV_LENGTH = 12;  // 96 bits for GCM
const AUTH_TAG_LENGTH = 16;
const SALT_LENGTH = 32;
const PBKDF2_ITERATIONS = 100000;

export interface EncryptedData {
  ciphertext: string;  // Base64 编码的密文
  iv: string;          // Base64 编码的 IV
  authTag: string;     // Base64 编码的认证标签
  salt?: string;       // Base64 编码的盐（用于密码派生密钥时）
}

export class CryptoEngine {
  private masterKey: Buffer | null = null;

  // 从密码派生密钥
  deriveKeyFromPassword(password: string, salt?: Buffer): { key: Buffer; salt: Buffer } {
    const useSalt = salt || crypto.randomBytes(SALT_LENGTH);
    const key = crypto.pbkdf2Sync(password, useSalt, PBKDF2_ITERATIONS, KEY_LENGTH, 'sha256');
    return { key, salt: useSalt };
  }

  // 生成随机密钥
  generateRandomKey(): Buffer {
    return crypto.randomBytes(KEY_LENGTH);
  }

  // 设置主密钥
  setMasterKey(key: Buffer): void {
    if (key.length !== KEY_LENGTH) {
      throw new Error(`Invalid key length: expected ${KEY_LENGTH}, got ${key.length}`);
    }
    this.masterKey = key;
  }

  // 从密码设置主密钥
  setMasterKeyFromPassword(password: string, salt: Buffer): void {
    const { key } = this.deriveKeyFromPassword(password, salt);
    this.masterKey = key;
  }

  // 清除主密钥
  clearMasterKey(): void {
    if (this.masterKey) {
      this.masterKey.fill(0);
      this.masterKey = null;
    }
  }

  // 检查是否已设置主密钥
  hasMasterKey(): boolean {
    return this.masterKey !== null;
  }

  // 获取主密钥（Base64格式）
  getMasterKey(): string {
    if (!this.masterKey) {
      throw new Error('No master key available');
    }
    return this.masterKey.toString('base64');
  }

  // 获取密钥指纹（用于验证密钥是否匹配）
  // 返回密钥的 SHA-256 哈希值（Base64编码）
  getKeyFingerprint(): string | null {
    if (!this.masterKey) {
      return null;
    }
    const hash = crypto.createHash('sha256');
    hash.update(this.masterKey);
    return hash.digest('base64');
  }

  // 验证密钥指纹是否匹配
  verifyKeyFingerprint(fingerprint: string): boolean {
    const currentFingerprint = this.getKeyFingerprint();
    return currentFingerprint === fingerprint;
  }

  // 加密数据
  encrypt(plaintext: string, key?: Buffer): EncryptedData {
    const useKey = key || this.masterKey;
    if (!useKey) {
      throw new Error('No encryption key available');
    }

    const iv = crypto.randomBytes(IV_LENGTH);
    const cipher = crypto.createCipheriv(ALGORITHM, useKey, iv, {
      authTagLength: AUTH_TAG_LENGTH,
    });

    const encrypted = Buffer.concat([
      cipher.update(plaintext, 'utf8'),
      cipher.final(),
    ]);

    return {
      ciphertext: encrypted.toString('base64'),
      iv: iv.toString('base64'),
      authTag: cipher.getAuthTag().toString('base64'),
    };
  }

  // 解密数据
  decrypt(encryptedData: EncryptedData, key?: Buffer): string {
    const useKey = key || this.masterKey;
    if (!useKey) {
      throw new Error('No decryption key available');
    }

    const iv = Buffer.from(encryptedData.iv, 'base64');
    const authTag = Buffer.from(encryptedData.authTag, 'base64');
    const ciphertext = Buffer.from(encryptedData.ciphertext, 'base64');

    const decipher = crypto.createDecipheriv(ALGORITHM, useKey, iv, {
      authTagLength: AUTH_TAG_LENGTH,
    });
    decipher.setAuthTag(authTag);

    const decrypted = Buffer.concat([
      decipher.update(ciphertext),
      decipher.final(),
    ]);

    return decrypted.toString('utf8');
  }

  // 使用密码加密（包含盐）
  encryptWithPassword(plaintext: string, password: string): EncryptedData {
    const { key, salt } = this.deriveKeyFromPassword(password);
    const encrypted = this.encrypt(plaintext, key);
    return {
      ...encrypted,
      salt: salt.toString('base64'),
    };
  }

  // 使用密码解密
  decryptWithPassword(encryptedData: EncryptedData, password: string): string {
    if (!encryptedData.salt) {
      throw new Error('Salt is required for password-based decryption');
    }
    const salt = Buffer.from(encryptedData.salt, 'base64');
    const { key } = this.deriveKeyFromPassword(password, salt);
    return this.decrypt(encryptedData, key);
  }

  // 加密 Item payload（用于同步）
  encryptPayload(payload: string): string {
    const encrypted = this.encrypt(payload);
    return JSON.stringify(encrypted);
  }

  // 解密 Item payload
  decryptPayload(encryptedPayload: string): string {
    const encrypted = JSON.parse(encryptedPayload) as EncryptedData;
    return this.decrypt(encrypted);
  }

  // 计算内容哈希
  computeHash(content: string): string {
    return crypto.createHash('sha256').update(content).digest('hex');
  }

  // 验证密码（通过尝试解密测试数据）
  verifyPassword(password: string, testData: EncryptedData): boolean {
    try {
      this.decryptWithPassword(testData, password);
      return true;
    } catch {
      return false;
    }
  }

  // 生成同步密钥标识（用于验证密钥匹配）
  generateKeyIdentifier(key?: Buffer): string {
    const useKey = key || this.masterKey;
    if (!useKey) {
      throw new Error('No key available');
    }
    // 使用密钥的哈希前16字符作为标识
    return crypto.createHash('sha256').update(useKey).digest('hex').substring(0, 16);
  }

  // 导出密钥（明文 Base64）
  // 注意：导出密码只是本地操作保护，不参与密钥加密
  exportKey(_exportPassword: string): string {
    if (!this.masterKey) {
      throw new Error('No master key to export');
    }
    // 直接返回主密钥的 Base64 编码
    return this.masterKey.toString('base64');
  }

  // 导入密钥（明文 Base64）
  // 注意：导入密码只是本地操作保护，不参与密钥解密
  importKey(encryptedKey: string, _importPassword: string): void {
    // 尝试解析为 JSON（兼容旧格式）
    try {
      const parsed = JSON.parse(encryptedKey);
      if (parsed.ciphertext && parsed.iv && parsed.authTag) {
        // 旧格式：加密的密钥，无法解密（因为不知道原密码）
        throw new Error('旧格式密钥不兼容，请在电脑端重新导出密钥');
      }
    } catch (e) {
      if (e instanceof SyntaxError) {
        // 不是 JSON，继续处理为 Base64
      } else {
        throw e;
      }
    }
    // 新格式：直接是 Base64 编码的主密钥
    this.masterKey = Buffer.from(encryptedKey, 'base64');
  }
}

export default CryptoEngine;

import { useState, useEffect, useCallback } from 'react';
import { ItemBase, BookmarkPayload, BookmarkFolderPayload } from '@shared/types';
import { itemsApi } from '../services/itemsApi';

export interface Bookmark {
  id: string;
  name: string;
  url: string;
  description: string;
  folderId: string | null;
  icon: string | null;
  tags: string[];
  createdAt: number;
  updatedAt: number;
}

export interface BookmarkFolder {
  id: string;
  name: string;
  parentId: string | null;
  createdAt: number;
}

function parsePayload<T>(item: ItemBase): T {
  return JSON.parse(item.payload) as T;
}

function itemToBookmark(item: ItemBase): Bookmark {
  const p = parsePayload<BookmarkPayload>(item);
  return {
    id: item.id,
    name: p.name,
    url: p.url,
    description: p.description || '',
    folderId: p.folder_id,
    icon: p.icon,
    tags: p.tags || [],
    createdAt: item.created_time,
    updatedAt: item.updated_time,
  };
}

function itemToFolder(item: ItemBase): BookmarkFolder {
  const p = parsePayload<BookmarkFolderPayload>(item);
  return {
    id: item.id,
    name: p.name,
    parentId: p.parent_id,
    createdAt: item.created_time,
  };
}

// API
const bookmarksApi = {
  create: (payload: BookmarkPayload): Promise<ItemBase> =>
    itemsApi.create('bookmark', payload),
  getAll: (): Promise<ItemBase[]> =>
    itemsApi.getByType('bookmark'),
  update: (id: string, payload: Partial<BookmarkPayload>): Promise<ItemBase | undefined> =>
    itemsApi.update(id, payload),
  delete: (id: string): Promise<boolean> =>
    itemsApi.delete(id),
};

const bookmarkFoldersApi = {
  create: (payload: BookmarkFolderPayload): Promise<ItemBase> =>
    itemsApi.create('bookmark_folder', payload),
  getAll: (): Promise<ItemBase[]> =>
    itemsApi.getByType('bookmark_folder'),
  update: (id: string, payload: Partial<BookmarkFolderPayload>): Promise<ItemBase | undefined> =>
    itemsApi.update(id, payload),
  delete: (id: string): Promise<boolean> =>
    itemsApi.delete(id),
};

export function useBookmarkFolders() {
  const [folders, setFolders] = useState<BookmarkFolder[]>([]);
  const [loading, setLoading] = useState(true);

  const loadFolders = useCallback(async () => {
    try {
      setLoading(true);
      const items = await bookmarkFoldersApi.getAll();
      if (items) {
        setFolders(items.filter(i => !i.deleted_time).map(itemToFolder));
      }
    } catch (err) {
      console.error('Failed to load bookmark folders:', err);
    } finally {
      setLoading(false);
    }
  }, []);

  useEffect(() => { loadFolders(); }, [loadFolders]);

  // 监听同步完成事件，刷新文件夹列表
  useEffect(() => {
    const handleSyncCompleted = () => {
      loadFolders();
    };
    window.addEventListener('sync-completed', handleSyncCompleted);
    return () => {
      window.removeEventListener('sync-completed', handleSyncCompleted);
    };
  }, [loadFolders]);

  const createFolder = useCallback(async (name: string, parentId: string | null = null) => {
    const item = await bookmarkFoldersApi.create({ name, parent_id: parentId });
    if (item) {
      await loadFolders();
      return itemToFolder(item);
    }
    return null;
  }, [loadFolders]);

  const updateFolder = useCallback(async (id: string, updates: Partial<BookmarkFolderPayload>) => {
    const item = await bookmarkFoldersApi.update(id, updates);
    if (item) { await loadFolders(); }
  }, [loadFolders]);

  const deleteFolder = useCallback(async (id: string) => {
    await bookmarkFoldersApi.delete(id);
    await loadFolders();
  }, [loadFolders]);

  return { folders, loading, createFolder, updateFolder, deleteFolder, refresh: loadFolders };
}

export function useBookmarks(folderId?: string | null, folders?: BookmarkFolder[]) {
  const [bookmarks, setBookmarks] = useState<Bookmark[]>([]);
  const [loading, setLoading] = useState(true);

  // 获取文件夹及其所有子文件夹的ID
  const getAllDescendantFolderIds = useCallback((parentId: string, allFolders: BookmarkFolder[]): string[] => {
    const result: string[] = [parentId];
    const children = allFolders.filter(f => f.parentId === parentId);
    for (const child of children) {
      result.push(...getAllDescendantFolderIds(child.id, allFolders));
    }
    return result;
  }, []);

  const loadBookmarks = useCallback(async () => {
    try {
      setLoading(true);
      const items = await bookmarksApi.getAll();
      if (items) {
        let list = items.filter(i => !i.deleted_time).map(itemToBookmark);
        if (folderId !== undefined) {
          if (folderId === null) {
            // 未分类：只显示没有文件夹的书签
            list = list.filter(b => b.folderId === null);
          } else if (folders && folders.length > 0) {
            // 有文件夹：显示该文件夹及其所有子文件夹下的书签
            const folderIds = getAllDescendantFolderIds(folderId, folders);
            list = list.filter(b => b.folderId && folderIds.includes(b.folderId));
          } else {
            // 没有传入folders，只过滤当前文件夹
            list = list.filter(b => b.folderId === folderId);
          }
        }
        list.sort((a, b) => a.name.localeCompare(b.name));
        setBookmarks(list);
      }
    } catch (err) {
      console.error('Failed to load bookmarks:', err);
    } finally {
      setLoading(false);
    }
  }, [folderId, folders, getAllDescendantFolderIds]);

  useEffect(() => { loadBookmarks(); }, [loadBookmarks]);

  // 监听同步完成事件，刷新书签列表
  useEffect(() => {
    const handleSyncCompleted = () => {
      loadBookmarks();
    };
    window.addEventListener('sync-completed', handleSyncCompleted);
    return () => {
      window.removeEventListener('sync-completed', handleSyncCompleted);
    };
  }, [loadBookmarks]);

  const createBookmark = useCallback(async (data: Partial<BookmarkPayload>) => {
    const payload: BookmarkPayload = {
      name: data.name || '',
      url: data.url || '',
      description: data.description || '',
      folder_id: data.folder_id ?? folderId ?? null,
      icon: data.icon || null,
      tags: data.tags || [],
    };
    const item = await bookmarksApi.create(payload);
    if (item) {
      await loadBookmarks();
      return itemToBookmark(item);
    }
    return null;
  }, [folderId, loadBookmarks]);

  const updateBookmark = useCallback(async (id: string, updates: Partial<BookmarkPayload>) => {
    const item = await bookmarksApi.update(id, updates);
    if (item) { await loadBookmarks(); return itemToBookmark(item); }
    return null;
  }, [loadBookmarks]);

  const deleteBookmark = useCallback(async (id: string) => {
    await bookmarksApi.delete(id);
    await loadBookmarks();
  }, [loadBookmarks]);

  return { bookmarks, loading, createBookmark, updateBookmark, deleteBookmark, refresh: loadBookmarks };
}

/**
 * GeneratorView 组件
 * 密码/资料生成器的主视图，整合配置和结果展示
 */

import React, { useState, useCallback } from 'react';
import { Layout, Button, message } from 'antd';
import { ArrowLeftOutlined } from '@ant-design/icons';
import { GeneratedProfile, VaultEntryPayload } from '@shared/types';
import { VaultFolder } from '../hooks/useVault';
import { useGenerator } from '../hooks/useGenerator';
import GeneratorConfig from './GeneratorConfig';
import GeneratorResults from './GeneratorResults';
import ImportModal from './ImportModal';

const { Sider, Content } = Layout;

interface GeneratorViewProps {
  folders: VaultFolder[];
  onBack: () => void;
  onImport: (payload: Partial<VaultEntryPayload>) => Promise<void>;
  onCreateFolder: (name: string) => Promise<VaultFolder | null>;
}

const GeneratorView: React.FC<GeneratorViewProps> = ({
  folders,
  onBack,
  onImport,
  onCreateFolder,
}) => {
  const {
    options,
    setCountry,
    setGender,
    setQuantity,
    setPasswordOptions,
    setIncludeFields,
    resetOptions,
    profiles,
    loading,
    error,
    generate,
    clearProfiles,
    formatAsNotes,
    formatForCopy,
  } = useGenerator();

  // 导入弹窗状态
  const [importModalVisible, setImportModalVisible] = useState(false);
  const [importProfile, setImportProfile] = useState<GeneratedProfile | null>(null);
  const [importProfiles, setImportProfiles] = useState<GeneratedProfile[]>([]);
  const [importLoading, setImportLoading] = useState(false);

  // 处理单个导入
  const handleImport = useCallback((profile: GeneratedProfile) => {
    setImportProfile(profile);
    setImportProfiles([]);
    setImportModalVisible(true);
  }, []);

  // 处理批量导入
  const handleBatchImport = useCallback(() => {
    setImportProfile(null);
    setImportProfiles(profiles);
    setImportModalVisible(true);
  }, [profiles]);

  // 确认导入
  const handleConfirmImport = useCallback(async (
    folderId: string | null,
    newFolderName?: string,
    customName?: string
  ) => {
    setImportLoading(true);

    try {
      let targetFolderId = folderId;

      // 如果需要创建新文件夹
      if (newFolderName) {
        const newFolder = await onCreateFolder(newFolderName);
        if (newFolder) {
          targetFolderId = newFolder.id;
        } else {
          throw new Error('创建文件夹失败');
        }
      }

      const profilesToImport = importProfiles.length > 0 ? importProfiles : (importProfile ? [importProfile] : []);
      const isBatchMode = importProfiles.length > 0;

      for (const profile of profilesToImport) {
        const payload: Partial<VaultEntryPayload> = {
          // 单条导入使用自定义名称，批量导入使用用户名
          name: isBatchMode ? profile.username : (customName || profile.username),
          entry_type: 'login',
          folder_id: targetFolderId,
          username: profile.username,
          password: profile.password,
          notes: formatAsNotes(profile),
          favorite: false,
          uris: [],
          totp_secrets: [],
          custom_fields: [],
        };

        await onImport(payload);
      }

      message.success(`成功导入 ${profilesToImport.length} 条记录`);
      setImportModalVisible(false);
      setImportProfile(null);
      setImportProfiles([]);
    } catch (err) {
      message.error(err instanceof Error ? err.message : '导入失败');
    } finally {
      setImportLoading(false);
    }
  }, [importProfile, importProfiles, onImport, onCreateFolder, formatAsNotes]);

  // 取消导入
  const handleCancelImport = useCallback(() => {
    setImportModalVisible(false);
    setImportProfile(null);
    setImportProfiles([]);
  }, []);

  // 复制字段（用于统计或日志）
  const handleCopyField = useCallback((_value: string, _label: string) => {
    // 可以在这里添加统计逻辑
  }, []);

  // 复制全部（用于统计或日志）
  const handleCopyAll = useCallback((_profile: GeneratedProfile) => {
    // 可以在这里添加统计逻辑
  }, []);

  return (
    <Layout style={{ height: '100%' }}>
      {/* 左侧配置区域 */}
      <Sider 
        width={280} 
        theme="light" 
        style={{ 
          borderRight: '1px solid var(--border-color, #f0f0f0)',
          display: 'flex',
          flexDirection: 'column',
        }}
      >
        {/* 返回按钮 */}
        <div style={{ 
          padding: '12px 16px', 
          borderBottom: '1px solid var(--border-color, #f0f0f0)',
          display: 'flex',
          alignItems: 'center',
          gap: 8,
        }}>
          <Button
            type="text"
            icon={<ArrowLeftOutlined />}
            onClick={onBack}
          >
            返回密码库
          </Button>
        </div>

        {/* 配置面板 */}
        <div style={{ flex: 1, overflow: 'auto' }}>
          <GeneratorConfig
            options={options}
            onCountryChange={setCountry}
            onGenderChange={setGender}
            onQuantityChange={setQuantity}
            onPasswordOptionsChange={setPasswordOptions}
            onIncludeFieldsChange={setIncludeFields}
            onGenerate={generate}
            onReset={() => {
              resetOptions();
              clearProfiles();
            }}
            loading={loading}
            error={error}
          />
        </div>
      </Sider>

      {/* 右侧结果区域 */}
      <Content style={{ display: 'flex', flexDirection: 'column' }}>
        <GeneratorResults
          profiles={profiles}
          onCopyField={handleCopyField}
          onCopyAll={handleCopyAll}
          onImport={handleImport}
          onBatchImport={handleBatchImport}
          formatForCopy={formatForCopy}
        />
      </Content>

      {/* 导入弹窗 */}
      <ImportModal
        visible={importModalVisible}
        profile={importProfile}
        profiles={importProfiles.length > 0 ? importProfiles : undefined}
        folders={folders}
        onConfirm={handleConfirmImport}
        onCancel={handleCancelImport}
        loading={importLoading}
      />
    </Layout>
  );
};

export default GeneratorView;

package com.mucheng.notes.presentation.viewmodel

import androidx.fragment.app.FragmentActivity
import androidx.lifecycle.ViewModel
import androidx.lifecycle.viewModelScope
import com.mucheng.notes.security.AppLockManager
import com.mucheng.notes.security.AuthResult
import com.mucheng.notes.security.BiometricManager
import com.mucheng.notes.security.BiometricStatus
import com.mucheng.notes.security.LockType
import dagger.hilt.android.lifecycle.HiltViewModel
import kotlinx.coroutines.flow.MutableStateFlow
import kotlinx.coroutines.flow.StateFlow
import kotlinx.coroutines.flow.asStateFlow
import kotlinx.coroutines.flow.update
import kotlinx.coroutines.launch
import javax.inject.Inject

/**
 * 锁屏界面状态
 */
data class LockScreenUiState(
    val lockType: LockType = LockType.PIN,
    val enteredPin: String = "",
    val error: String? = null,
    val isUnlocked: Boolean = false,
    val biometricAvailable: Boolean = false,
    val attempts: Int = 0,
    val pinLength: Int = 4
)

/**
 * 锁屏 ViewModel
 */
@HiltViewModel
class LockScreenViewModel @Inject constructor(
    private val appLockManager: AppLockManager,
    private val biometricManager: BiometricManager
) : ViewModel() {

    companion object {
        private const val MAX_ATTEMPTS = 5
        private const val MIN_PIN_LENGTH = 4
        private const val MAX_PIN_LENGTH = 6
    }

    private val _uiState = MutableStateFlow(LockScreenUiState())
    val uiState: StateFlow<LockScreenUiState> = _uiState.asStateFlow()

    private var activity: FragmentActivity? = null
    private var pinLength: Int = MIN_PIN_LENGTH

    init {
        initializeLockScreen()
    }

    /**
     * 设置 Activity（用于生物识别）
     */
    fun setActivity(activity: FragmentActivity) {
        this.activity = activity
        // 如果启用了生物识别且可用，自动触发
        val biometricEnabled = biometricManager.isBiometricEnabled()
        val biometricAvailable = biometricManager.canAuthenticate() == BiometricStatus.AVAILABLE
        if (biometricEnabled && biometricAvailable) {
            // 延迟一点触发，确保 UI 已经准备好
            viewModelScope.launch {
                kotlinx.coroutines.delay(300)
                authenticateWithBiometric()
            }
        }
    }

    /**
     * 初始化锁屏
     */
    private fun initializeLockScreen() {
        val lockType = appLockManager.getLockType()
        val biometricAvailable = biometricManager.canAuthenticate() == BiometricStatus.AVAILABLE
        val biometricEnabled = biometricManager.isBiometricEnabled()

        // 获取存储的 PIN 长度
        pinLength = appLockManager.getPinLength()

        _uiState.update {
            it.copy(
                lockType = if (biometricEnabled && biometricAvailable) LockType.BIOMETRIC else lockType,
                biometricAvailable = biometricAvailable && biometricEnabled,
                pinLength = pinLength
            )
        }
    }

    /**
     * PIN 码输入变化
     */
    fun onPinChange(pin: String) {
        _uiState.update { it.copy(enteredPin = pin, error = null) }

        // 当输入达到存储的 PIN 长度时验证
        if (pin.length == pinLength) {
            verifyPin(pin)
        }
    }

    /**
     * 验证 PIN 码
     */
    private fun verifyPin(pin: String) {
        viewModelScope.launch {
            val isValid = appLockManager.verifyPin(pin)

            if (isValid) {
                appLockManager.recordUnlock()
                _uiState.update { it.copy(isUnlocked = true) }
            } else {
                val newAttempts = _uiState.value.attempts + 1
                _uiState.update {
                    it.copy(
                        enteredPin = "",
                        error = if (newAttempts >= MAX_ATTEMPTS) {
                            "尝试次数过多，请稍后再试"
                        } else {
                            "PIN 码错误，还剩 ${MAX_ATTEMPTS - newAttempts} 次机会"
                        },
                        attempts = newAttempts
                    )
                }
            }
        }
    }

    /**
     * 图案输入完成
     */
    fun onPatternComplete(pattern: List<Int>) {
        viewModelScope.launch {
            val isValid = appLockManager.verifyPattern(pattern)

            if (isValid) {
                appLockManager.recordUnlock()
                _uiState.update { it.copy(isUnlocked = true) }
            } else {
                val newAttempts = _uiState.value.attempts + 1
                _uiState.update {
                    it.copy(
                        error = if (newAttempts >= MAX_ATTEMPTS) {
                            "尝试次数过多，请稍后再试"
                        } else {
                            "图案错误，还剩 ${MAX_ATTEMPTS - newAttempts} 次机会"
                        },
                        attempts = newAttempts
                    )
                }
            }
        }
    }

    /**
     * 使用生物识别认证
     */
    fun authenticateWithBiometric() {
        val currentActivity = activity ?: return

        viewModelScope.launch {
            val result = biometricManager.authenticate(
                activity = currentActivity,
                title = "身份验证",
                subtitle = "使用指纹或面部解锁",
                negativeButtonText = "使用密码"
            )

            when (result) {
                is AuthResult.Success -> {
                    appLockManager.recordUnlock()
                    _uiState.update { it.copy(isUnlocked = true) }
                }
                is AuthResult.Error -> {
                    _uiState.update { it.copy(error = result.message) }
                }
                is AuthResult.Cancelled -> {
                    // 用户取消，不做处理
                }
                is AuthResult.Fallback -> {
                    // 用户选择使用密码
                    switchToPinMode()
                }
            }
        }
    }

    /**
     * 切换到 PIN 模式
     */
    fun switchToPinMode() {
        _uiState.update {
            it.copy(
                lockType = LockType.PIN,
                enteredPin = "",
                error = null
            )
        }
    }

    /**
     * 清除错误
     */
    fun clearError() {
        _uiState.update { it.copy(error = null) }
    }
}

