/**
 * 电子表格视图组件
 * @param readOnly 只读预览模式，只渲染有数据的区域
 */
@Composable
fun SpreadsheetView(
    sheet: ExcelSheet,
    selectedCell: CellPosition,
    onCellSelect: (Int, Int) -> Unit,
    onCellChange: (Int, Int, String) -> Unit,
    getCellDisplayValue: (Int, Int) -> String,
    modifier: Modifier = Modifier,
    readOnly: Boolean = false
) {
    val horizontalScrollState = rememberScrollState()
    val cellWidth = 100.dp
    val cellHeight = 36.dp
    val headerWidth = 50.dp
    val headerHeight = 36.dp

    // 计算实际有数据的行列范围，只读模式下只渲染有数据的区域
    val maxDataRow = if (sheet.rows.isEmpty()) 0
        else sheet.rows.maxOf { it.rowIndex } + 1
    val maxDataCol = if (sheet.rows.isEmpty()) 0
        else sheet.rows.flatMap { it.cells }.maxOfOrNull { it.columnIndex + 1 } ?: 0

    // 只读模式：只显示有数据的区域（最少显示 5 行 5 列）
    // 编辑模式：显示 50 行 26 列
    val visibleRows = if (readOnly) maxOf(maxDataRow, 5) else 50
    val visibleCols = if (readOnly) maxOf(maxDataCol, 5) else 26

    Column(modifier = modifier.fillMaxSize()) {
        // 列头
        Row(
            modifier = Modifier
                .horizontalScroll(horizontalScrollState)
                .background(MaterialTheme.colorScheme.surfaceVariant)
        ) {
            // 左上角空白
            Box(
                modifier = Modifier
                    .size(headerWidth, headerHeight)
                    .border(0.5.dp, MaterialTheme.colorScheme.outline)
            )

            // 列标题 (A, B, C, ...)
            for (col in 0 until visibleCols) {
                Box(
                    modifier = Modifier
                        .size(cellWidth, headerHeight)
                        .border(0.5.dp, MaterialTheme.colorScheme.outline),
                    contentAlignment = Alignment.Center
                ) {
                    Text(
                        text = columnToLetter(col),
                        style = MaterialTheme.typography.bodySmall,
                        color = MaterialTheme.colorScheme.onSurfaceVariant
                    )
                }
            }
        }

        // 数据行
        LazyColumn(
            modifier = Modifier.fillMaxSize()
        ) {
            items(visibleRows) { row ->
                Row(
                    modifier = Modifier.horizontalScroll(horizontalScrollState)
                ) {
                    // 行号
                    Box(
                        modifier = Modifier
                            .size(headerWidth, cellHeight)
                            .background(MaterialTheme.colorScheme.surfaceVariant)
                            .border(0.5.dp, MaterialTheme.colorScheme.outline),
                        contentAlignment = Alignment.Center
                    ) {
                        Text(
                            text = (row + 1).toString(),
                            style = MaterialTheme.typography.bodySmall,
                            color = MaterialTheme.colorScheme.onSurfaceVariant
                        )
                    }

                    // 数据单元格
                    for (col in 0 until visibleCols) {
                        SpreadsheetCell(
                            value = getCellDisplayValue(row, col),
                            isSelected = selectedCell.row == row && selectedCell.col == col,
                            onClick = { onCellSelect(row, col) },
                            onValueChange = { onCellChange(row, col, it) },
                            modifier = Modifier.size(cellWidth, cellHeight),
                            readOnly = readOnly
                        )
                    }
                }
            }
        }
    }
}

/**
 * 单元格组件
 */
@Composable
private fun SpreadsheetCell(
    value: String,
    isSelected: Boolean,
    onClick: () -> Unit,
    onValueChange: (String) -> Unit,
    modifier: Modifier = Modifier,
    readOnly: Boolean = false
) {
    var isEditing by remember { mutableStateOf(false) }
    var editValue by remember(value) { mutableStateOf(value) }
    val focusRequester = remember { FocusRequester() }

    Box(
        modifier = modifier
            .border(
                width = if (isSelected && !readOnly) 2.dp else 0.5.dp,
                color = if (isSelected && !readOnly) MaterialTheme.colorScheme.primary
                        else MaterialTheme.colorScheme.outline
            )
            .background(
                if (isSelected && !readOnly) MaterialTheme.colorScheme.primaryContainer.copy(alpha = 0.3f)
                else MaterialTheme.colorScheme.surface
            )
            .clickable {
                if (!readOnly) {
                    onClick()
                    if (isSelected) isEditing = true
                }
            }
            .padding(4.dp),
        contentAlignment = Alignment.CenterStart
    ) {
        if (isEditing && isSelected && !readOnly) {
            BasicTextField(
                value = editValue,
                onValueChange = { editValue = it },
                modifier = Modifier
                    .fillMaxSize()
                    .focusRequester(focusRequester)
                    .onFocusChanged { state ->
                        if (!state.isFocused && isEditing) {
                            isEditing = false
                            if (editValue != value) onValueChange(editValue)
                        }
                    },
                textStyle = TextStyle(fontSize = 14.sp, color = MaterialTheme.colorScheme.onSurface),
                singleLine = true
            )
            LaunchedEffect(Unit) { focusRequester.requestFocus() }
        } else {
            Text(
                text = value,
                style = MaterialTheme.typography.bodyMedium,
                maxLines = 1,
                color = MaterialTheme.colorScheme.onSurface
            )
        }
    }
}

/**
 * 列索引转字母
 */
private fun columnToLetter(col: Int): String {
    var result = ""
    var n = col
    while (n >= 0) {
        result = ('A' + (n % 26)) + result
        n = n / 26 - 1
    }
    return result
}

/**
 * ImportModal 组件
 * 导入生成的资料到密码库的确认弹窗
 */

import React, { useState, useEffect } from 'react';
import {
  Modal,
  Form,
  Select,
  Input,
  Button,
  Space,
  message,
} from 'antd';
import { FolderAddOutlined } from '@ant-design/icons';
import { GeneratedProfile } from '@shared/types';
import { VaultFolder } from '../hooks/useVault';

interface ImportModalProps {
  visible: boolean;
  profile: GeneratedProfile | null;
  profiles?: GeneratedProfile[];  // 批量导入时使用
  folders: VaultFolder[];
  onConfirm: (folderId: string | null, newFolderName?: string, customName?: string) => Promise<void>;
  onCancel: () => void;
  loading: boolean;
}

const ImportModal: React.FC<ImportModalProps> = ({
  visible,
  profile,
  profiles,
  folders,
  onConfirm,
  onCancel,
  loading,
}) => {
  const [selectedFolderId, setSelectedFolderId] = useState<string | null>(null);
  const [showNewFolder, setShowNewFolder] = useState(false);
  const [newFolderName, setNewFolderName] = useState('');
  const [customName, setCustomName] = useState('');

  const isBatchMode = profiles && profiles.length > 0;
  const count = isBatchMode ? profiles.length : 1;

  // 当弹窗打开时，重置自定义名称
  useEffect(() => {
    if (visible) {
      setCustomName('');
    }
  }, [visible]);

  const handleConfirm = async () => {
    if (showNewFolder && !newFolderName.trim()) {
      message.warning('请输入文件夹名称');
      return;
    }

    if (!isBatchMode && !customName.trim()) {
      message.warning('请输入条目名称');
      return;
    }

    try {
      await onConfirm(
        showNewFolder ? null : selectedFolderId,
        showNewFolder ? newFolderName.trim() : undefined,
        !isBatchMode ? customName.trim() : undefined
      );
      // 重置状态
      setSelectedFolderId(null);
      setShowNewFolder(false);
      setNewFolderName('');
      setCustomName('');
    } catch (err) {
      // 错误处理由父组件完成
    }
  };

  const handleCancel = () => {
    setSelectedFolderId(null);
    setShowNewFolder(false);
    setNewFolderName('');
    setCustomName('');
    onCancel();
  };

  const folderOptions = [
    { value: '', label: '未分类' },
    ...folders.map(f => ({ value: f.id, label: f.name })),
  ];

  return (
    <Modal
      title={isBatchMode ? `批量导入 ${count} 条记录` : '导入到密码库'}
      open={visible}
      onOk={handleConfirm}
      onCancel={handleCancel}
      confirmLoading={loading}
      okText="导入"
      cancelText="取消"
      width={400}
    >
      <Form layout="vertical">
        {!isBatchMode && profile && (
          <>
            <Form.Item label="条目名称" required style={{ marginBottom: 12 }}>
              <Input
                value={customName}
                onChange={e => setCustomName(e.target.value)}
                placeholder="输入条目名称，如：Google账号、公司邮箱"
              />
            </Form.Item>
            <div style={{ 
              padding: 12, 
              background: 'var(--bg-secondary, #f5f5f5)', 
              borderRadius: 6,
              marginBottom: 16,
            }}>
              <div style={{ marginBottom: 8 }}>
                <span style={{ color: '#888', marginRight: 8 }}>用户名:</span>
                <span style={{ fontFamily: 'monospace' }}>{profile.username}</span>
              </div>
              {profile.fullName && (
                <div style={{ marginBottom: 8 }}>
                  <span style={{ color: '#888', marginRight: 8 }}>姓名:</span>
                  <span>{profile.fullName}</span>
                </div>
              )}
              {profile.email && (
                <div>
                  <span style={{ color: '#888', marginRight: 8 }}>邮箱:</span>
                  <span style={{ fontFamily: 'monospace' }}>{profile.email}</span>
                </div>
              )}
            </div>
          </>
        )}

        {isBatchMode && (
          <div style={{ 
            padding: 12, 
            background: 'var(--bg-secondary, #f5f5f5)', 
            borderRadius: 6,
            marginBottom: 16,
            textAlign: 'center',
          }}>
            <div style={{ fontSize: 24, fontWeight: 600, color: '#1890ff' }}>
              {count}
            </div>
            <div style={{ color: '#888' }}>条记录将被导入（名称使用用户名）</div>
          </div>
        )}

        <Form.Item label="选择文件夹">
          {!showNewFolder ? (
            <Space.Compact style={{ width: '100%' }}>
              <Select
                value={selectedFolderId || ''}
                onChange={v => setSelectedFolderId(v || null)}
                options={folderOptions}
                style={{ flex: 1 }}
                placeholder="选择文件夹"
              />
              <Button
                icon={<FolderAddOutlined />}
                onClick={() => setShowNewFolder(true)}
              >
                新建
              </Button>
            </Space.Compact>
          ) : (
            <Space.Compact style={{ width: '100%' }}>
              <Input
                value={newFolderName}
                onChange={e => setNewFolderName(e.target.value)}
                placeholder="输入新文件夹名称"
                style={{ flex: 1 }}
              />
              <Button onClick={() => setShowNewFolder(false)}>
                取消
              </Button>
            </Space.Compact>
          )}
        </Form.Item>

        <div style={{ fontSize: 12, color: '#888' }}>
          <p>导入后：</p>
          <ul style={{ paddingLeft: 20, margin: 0 }}>
            <li>用户名和密码将对应到条目的用户名和密码字段</li>
            <li>其他信息（姓名、地址、电话、邮箱、工作单位）将放入备注</li>
          </ul>
        </div>
      </Form>
    </Modal>
  );
};

export default ImportModal;

import { Router } from 'express';
import { getDatabase } from '../database';
import { createError } from '../middleware/errorHandler';

const router = Router();

/**
 * 获取用户标识符
 * JWT 认证使用 userId，API Key 认证使用 apiKeyHash
 */
function getUserIdentifier(req: Express.Request): string {
  if (req.userId) {
    return `user:${req.userId}`;
  }
  if (req.apiKeyHash) {
    return `apikey:${req.apiKeyHash}`;
  }
  throw createError('No authentication identifier', 401);
}

// GET /api/sync/cursor - 获取同步游标
router.get('/cursor', (req, res, next) => {
  try {
    const db = getDatabase();
    const identifier = getUserIdentifier(req);

    // 优先查询新的用户系统
    if (req.userId) {
      const row = db.prepare('SELECT cursor, updated_at FROM sync_cursors WHERE api_key_hash = ?')
        .get(identifier) as { cursor: string; updated_at: number } | undefined;

      if (row) {
        res.json({ cursor: row.cursor, updated_at: row.updated_at });
        return;
      }
    }

    // 向后兼容：查询旧的 API Key 系统
    if (req.apiKeyHash) {
      const row = db.prepare('SELECT cursor, updated_at FROM sync_cursors WHERE api_key_hash = ?')
        .get(req.apiKeyHash) as { cursor: string; updated_at: number } | undefined;

      if (row) {
        res.json({ cursor: row.cursor, updated_at: row.updated_at });
        return;
      }
    }

    res.json({ cursor: null });
  } catch (error) {
    next(error);
  }
});

// PUT /api/sync/cursor - 保存同步游标
router.put('/cursor', (req, res, next) => {
  try {
    const db = getDatabase();
    const identifier = getUserIdentifier(req);
    const { cursor } = req.body;

    if (cursor === undefined) {
      throw createError('Missing required field: cursor', 400);
    }

    const now = Date.now();
    const stmt = db.prepare(`
      INSERT INTO sync_cursors (api_key_hash, cursor, updated_at) VALUES (?, ?, ?)
      ON CONFLICT(api_key_hash) DO UPDATE SET cursor = ?, updated_at = ?
    `);
    stmt.run(identifier, cursor, now, cursor, now);

    res.json({ success: true });
  } catch (error) {
    next(error);
  }
});

// GET /api/sync/key-fingerprint - 获取密钥指纹
router.get('/key-fingerprint', (req, res, next) => {
  try {
    const db = getDatabase();

    // JWT 认证：从用户表获取指纹
    if (req.userId) {
      const user = db.prepare('SELECT sync_key_fingerprint FROM users WHERE id = ?')
        .get(req.userId) as { sync_key_fingerprint: string } | undefined;
      res.json({ fingerprint: user?.sync_key_fingerprint || null });
      return;
    }

    // API Key 认证：从旧表获取指纹
    if (req.apiKeyHash) {
      const row = db.prepare('SELECT fingerprint FROM key_fingerprints WHERE api_key_hash = ?')
        .get(req.apiKeyHash) as { fingerprint: string } | undefined;
      res.json({ fingerprint: row?.fingerprint || null });
      return;
    }

    res.json({ fingerprint: null });
  } catch (error) {
    next(error);
  }
});

// PUT /api/sync/key-fingerprint - 保存密钥指纹
router.put('/key-fingerprint', (req, res, next) => {
  try {
    const db = getDatabase();
    const { fingerprint } = req.body;

    if (!fingerprint) {
      throw createError('Missing required field: fingerprint', 400);
    }

    // JWT 认证：指纹已在用户表中，只需验证
    if (req.userId) {
      const user = db.prepare('SELECT sync_key_fingerprint FROM users WHERE id = ?')
        .get(req.userId) as { sync_key_fingerprint: string } | undefined;

      if (!user) {
        throw createError('User not found', 404);
      }

      // 验证指纹是否匹配
      if (user.sync_key_fingerprint !== fingerprint) {
        res.status(409).json({
          error: 'Fingerprint conflict',
          message: '同步密钥指纹不匹配，请检查同步密钥是否正确',
        });
        return;
      }

      res.json({ success: true });
      return;
    }

    // API Key 认证：使用旧表
    if (req.apiKeyHash) {
      const existing = db.prepare('SELECT fingerprint FROM key_fingerprints WHERE api_key_hash = ?')
        .get(req.apiKeyHash) as { fingerprint: string } | undefined;

      if (existing) {
        if (existing.fingerprint !== fingerprint) {
          res.status(409).json({
            error: 'Fingerprint conflict',
            existingFingerprint: existing.fingerprint,
          });
          return;
        }
        res.json({ success: true });
        return;
      }

      const now = Date.now();
      const stmt = db.prepare(`
        INSERT INTO key_fingerprints (api_key_hash, fingerprint, created_at, updated_at)
        VALUES (?, ?, ?, ?)
      `);
      stmt.run(req.apiKeyHash, fingerprint, now, now);

      res.json({ success: true });
      return;
    }

    throw createError('No authentication identifier', 401);
  } catch (error) {
    next(error);
  }
});

// DELETE /api/sync/key-fingerprint - 重置密钥指纹（管理员操作）
router.delete('/key-fingerprint', (req, res, next) => {
  try {
    const db = getDatabase();

    // JWT 认证：不允许通过此接口重置（需要通过用户设置更新）
    if (req.userId) {
      res.status(403).json({
        error: 'Forbidden',
        message: '请通过用户设置更新同步密钥',
      });
      return;
    }

    // API Key 认证：允许重置
    if (req.apiKeyHash) {
      const stmt = db.prepare('DELETE FROM key_fingerprints WHERE api_key_hash = ?');
      stmt.run(req.apiKeyHash);
      res.json({ success: true });
      return;
    }

    throw createError('No authentication identifier', 401);
  } catch (error) {
    next(error);
  }
});

export default router;

import { useState, useEffect, useCallback } from 'react';
import { ItemBase, TodoPayload, TodoQuadrant } from '@shared/types';
import { itemsApi } from '../services/itemsApi';

export interface Todo {
  id: string;
  title: string;
  description: string;
  quadrant: TodoQuadrant;
  completed: boolean;
  completedAt: number | null;
  dueDate: number | null;
  reminderTime: number | null;
  reminderEnabled: boolean;
  priority: number;
  tags: string[];
  createdAt: number;
  updatedAt: number;
}

function parsePayload<T>(item: ItemBase): T {
  return JSON.parse(item.payload) as T;
}

function itemToTodo(item: ItemBase): Todo {
  const payload = parsePayload<TodoPayload>(item);
  return {
    id: item.id,
    title: payload.title || '',
    description: payload.description || '',
    quadrant: payload.quadrant || 'q4',
    completed: payload.completed ?? false,
    completedAt: payload.completed_at ?? null,
    dueDate: payload.due_date ?? null,
    reminderTime: payload.reminder_time ?? null,
    reminderEnabled: payload.reminder_enabled ?? false,
    priority: payload.priority ?? 0,
    tags: payload.tags || [],  // 确保 tags 始终是数组
    createdAt: item.created_time,
    updatedAt: item.updated_time,
  };
}

// 待办事项 API
export const todosApi = {
  create: (payload: TodoPayload): Promise<ItemBase> =>
    itemsApi.create('todo', payload),

  getAll: (): Promise<ItemBase[]> =>
    itemsApi.getByType('todo'),

  getById: (id: string): Promise<ItemBase | undefined> =>
    itemsApi.getById(id),

  update: (id: string, payload: TodoPayload): Promise<ItemBase | undefined> =>
    itemsApi.update(id, payload),

  delete: (id: string): Promise<boolean> =>
    itemsApi.delete(id),
};

export function useTodos() {
  const [todos, setTodos] = useState<Todo[]>([]);
  const [loading, setLoading] = useState(true);

  const loadTodos = useCallback(async () => {
    try {
      setLoading(true);
      const items = await todosApi.getAll();
      if (items && Array.isArray(items)) {
        const list = items
          .filter(item => !item.deleted_time)
          .map(itemToTodo);
        // 按优先级排序
        list.sort((a, b) => a.priority - b.priority);
        setTodos(list);
      }
    } catch (err) {
      console.error('Failed to load todos:', err);
    } finally {
      setLoading(false);
    }
  }, []);

  useEffect(() => {
    loadTodos();
  }, [loadTodos]);

  // 监听同步完成事件，刷新待办列表
  useEffect(() => {
    const handleSyncCompleted = () => {
      loadTodos();
    };
    window.addEventListener('sync-completed', handleSyncCompleted);
    return () => {
      window.removeEventListener('sync-completed', handleSyncCompleted);
    };
  }, [loadTodos]);

  const createTodo = useCallback(async (
    title: string,
    quadrant: TodoQuadrant,
    description: string = '',
    dueDate: number | null = null,
    reminderTime: number | null = null
  ) => {
    // 获取该象限的最大优先级
    const quadrantTodos = todos.filter(t => t.quadrant === quadrant);
    const maxPriority = quadrantTodos.length > 0 
      ? Math.max(...quadrantTodos.map(t => t.priority)) 
      : 0;

    const payload: TodoPayload = {
      title,
      description,
      quadrant,
      completed: false,
      completed_at: null,
      due_date: dueDate,
      reminder_time: reminderTime,
      reminder_enabled: reminderTime !== null,
      priority: maxPriority + 1,
      tags: [],
    };
    const item = await todosApi.create(payload);
    if (item) {
      await loadTodos();
      return itemToTodo(item);
    }
    return null;
  }, [todos, loadTodos]);

  const updateTodo = useCallback(async (id: string, updates: Partial<TodoPayload>) => {
    // 先获取现有数据，然后合并更新
    const existingItem = await todosApi.getById(id);
    if (!existingItem) return null;

    const existingPayload = JSON.parse(existingItem.payload) as TodoPayload;
    const mergedPayload: TodoPayload = {
      ...existingPayload,
      ...updates,
    };

    const item = await todosApi.update(id, mergedPayload);
    if (item) {
      await loadTodos();
      return itemToTodo(item);
    }
    return null;
  }, [loadTodos]);

  const deleteTodo = useCallback(async (id: string) => {
    const success = await todosApi.delete(id);
    if (success) {
      await loadTodos();
    }
    return success;
  }, [loadTodos]);

  const toggleComplete = useCallback(async (id: string) => {
    const todo = todos.find(t => t.id === id);
    if (todo) {
      await updateTodo(id, {
        completed: !todo.completed,
        completed_at: !todo.completed ? Date.now() : null,
      });
    }
  }, [todos, updateTodo]);

  const moveTodo = useCallback(async (id: string, targetQuadrant: TodoQuadrant, targetPriority: number) => {
    await updateTodo(id, {
      quadrant: targetQuadrant,
      priority: targetPriority,
    });
  }, [updateTodo]);

  // 按象限分组
  const todosByQuadrant = {
    'urgent-important': todos.filter(t => t.quadrant === 'urgent-important'),
    'not-urgent-important': todos.filter(t => t.quadrant === 'not-urgent-important'),
    'urgent-not-important': todos.filter(t => t.quadrant === 'urgent-not-important'),
    'not-urgent-not-important': todos.filter(t => t.quadrant === 'not-urgent-not-important'),
  };

  return {
    todos,
    todosByQuadrant,
    loading,
    createTodo,
    updateTodo,
    deleteTodo,
    toggleComplete,
    moveTodo,
    refresh: loadTodos,
  };
}

import React, { useState } from 'react';
import { Modal, Button, Steps, Typography, Space, Card, Row, Col } from 'antd';
import {
  FileTextOutlined,
  FolderOutlined,
  TagOutlined,
  CloudSyncOutlined,
  LockOutlined,
  BulbOutlined,
} from '@ant-design/icons';

const { Title, Paragraph, Text } = Typography;

interface WelcomeGuideProps {
  open: boolean;
  onClose: () => void;
}

const features = [
