/**
 * 工作表标签组件
 * 支持切换、添加、删除、重命名工作表
 */

import React, { useState } from 'react';
import { Button, Dropdown, Input, Modal, message } from 'antd';
import { PlusOutlined, MoreOutlined } from '@ant-design/icons';
import type { MenuProps } from 'antd';
import { ExcelSheet } from '@shared/types';

interface SheetTabsProps {
  sheets: ExcelSheet[];
  activeIndex: number;
  onSelect: (index: number) => void;
  onAdd: (name?: string) => void;
  onDelete: (index: number) => void;
  onRename: (index: number, name: string) => void;
  onReorder: (fromIndex: number, toIndex: number) => void;
}

export const SheetTabs: React.FC<SheetTabsProps> = ({
  sheets,
  activeIndex,
  onSelect,
  onAdd,
  onDelete,
  onRename,
  onReorder,
}) => {
  const [renameIndex, setRenameIndex] = useState<number | null>(null);
  const [renameValue, setRenameValue] = useState('');
  const [dragIndex, setDragIndex] = useState<number | null>(null);

  const handleRenameStart = (index: number) => {
    setRenameIndex(index);
    setRenameValue(sheets[index].name);
  };

  const handleRenameConfirm = () => {
    if (renameIndex !== null && renameValue.trim()) {
      onRename(renameIndex, renameValue.trim());
    }
    setRenameIndex(null);
    setRenameValue('');
  };

  const handleRenameCancel = () => {
    setRenameIndex(null);
    setRenameValue('');
  };

  const handleDelete = (index: number) => {
    if (sheets.length <= 1) {
      message.warning('至少保留一个工作表');
      return;
    }
    Modal.confirm({
      title: '删除工作表',
      content: `确定要删除工作表 "${sheets[index].name}" 吗？此操作不可撤销。`,
      okText: '删除',
      okType: 'danger',
      cancelText: '取消',
      onOk: () => onDelete(index),
    });
  };

  const getMenuItems = (index: number): MenuProps['items'] => [
    {
      key: 'rename',
      label: '重命名',
      onClick: () => handleRenameStart(index),
    },
    {
      key: 'delete',
      label: '删除',
      danger: true,
      onClick: () => handleDelete(index),
      disabled: sheets.length <= 1,
    },
  ];

  const handleDragStart = (e: React.DragEvent, index: number) => {
    setDragIndex(index);
    e.dataTransfer.effectAllowed = 'move';
  };

  const handleDragOver = (e: React.DragEvent) => {
    e.preventDefault();
    e.dataTransfer.dropEffect = 'move';
  };

  const handleDrop = (e: React.DragEvent, targetIndex: number) => {
    e.preventDefault();
    if (dragIndex !== null && dragIndex !== targetIndex) {
      onReorder(dragIndex, targetIndex);
    }
    setDragIndex(null);
  };

  const handleDragEnd = () => {
    setDragIndex(null);
  };

  return (
    <div className="sheet-tabs" style={{
      display: 'flex',
      alignItems: 'center',
      padding: '4px 8px',
      borderTop: '1px solid #e8e8e8',
      background: '#fafafa',
      gap: 4,
      overflowX: 'auto',
    }}>
      {/* 添加工作表按钮 */}
      <Button
        icon={<PlusOutlined />}
        size="small"
        onClick={() => onAdd()}
        style={{ marginRight: 8 }}
      />

      {/* 工作表标签 */}
      {sheets.map((sheet, index) => (
        <div
          key={sheet.id}
          draggable
          onDragStart={(e) => handleDragStart(e, index)}
          onDragOver={handleDragOver}
          onDrop={(e) => handleDrop(e, index)}
          onDragEnd={handleDragEnd}
          style={{
            display: 'flex',
            alignItems: 'center',
            padding: '4px 8px',
            background: index === activeIndex ? '#fff' : 'transparent',
            border: index === activeIndex ? '1px solid #d9d9d9' : '1px solid transparent',
            borderBottom: index === activeIndex ? '1px solid #fff' : '1px solid transparent',
            borderRadius: '4px 4px 0 0',
            cursor: 'pointer',
            marginBottom: -1,
            opacity: dragIndex === index ? 0.5 : 1,
            transition: 'all 0.2s',
          }}
          onClick={() => onSelect(index)}
          onDoubleClick={() => handleRenameStart(index)}
        >
          {renameIndex === index ? (
            <Input
              value={renameValue}
              onChange={(e) => setRenameValue(e.target.value)}
              onBlur={handleRenameConfirm}
              onKeyDown={(e) => {
                if (e.key === 'Enter') handleRenameConfirm();
                if (e.key === 'Escape') handleRenameCancel();
              }}
              autoFocus
              size="small"
              style={{ width: 80 }}
              onClick={(e) => e.stopPropagation()}
            />
          ) : (
            <>
              <span style={{ 
                fontSize: 13, 
                maxWidth: 120, 
                overflow: 'hidden', 
                textOverflow: 'ellipsis',
                whiteSpace: 'nowrap',
              }}>
                {sheet.name}
              </span>
              <Dropdown menu={{ items: getMenuItems(index) }} trigger={['click']}>
                <Button
                  icon={<MoreOutlined />}
                  type="text"
                  size="small"
                  style={{ marginLeft: 4, padding: '0 4px' }}
                  onClick={(e) => e.stopPropagation()}
                />
              </Dropdown>
            </>
          )}
        </div>
      ))}
    </div>
  );
};

import { Router } from 'express';
import { ItemService } from '../services/ItemService';
import { createError } from '../middleware/errorHandler';
import { getDatabase } from '../database';
import { userService } from '../services/UserService';

const router = Router();

// GET /api/items/all - 全量拉取所有数据项（新客户端首次同步使用）
router.get('/all', (req, res, next) => {
  try {
    userService.claimLegacyDataForSingleUser(req.userId);
    const db = getDatabase();
    let sql = 'SELECT * FROM items';
    const params: (string | number)[] = [];

    if (req.userId) {
      sql += ' WHERE user_id = ?';
      params.push(req.userId);
    }

    sql += ' ORDER BY updated_time ASC';

    const items = db.prepare(sql).all(...params);

    // 返回当前最大 change_id，客户端全量拉取后用这个值作为游标（按用户过滤）
    let maxChangeSql = 'SELECT MAX(change_id) as max_id FROM changes';
    const maxChangeParams: (string | number)[] = [];
    if (req.userId) {
      maxChangeSql += ' WHERE user_id = ?';
      maxChangeParams.push(req.userId);
    }
    const maxChange = db.prepare(maxChangeSql).get(...maxChangeParams) as { max_id: number | null };
    const latestChangeId = maxChange?.max_id ?? 0;

    res.json({ items, latestChangeId });
  } catch (error) {
    next(error);
  }
});

// GET /api/items/count - 获取数据项计数
router.get('/count', (req, res, next) => {
  try {
    const itemService = new ItemService(req.userId);
    const type = req.query.type as string | undefined;
    const result = itemService.getCount(type);
    res.json(result);
  } catch (error) {
    next(error);
  }
});

// GET /api/items/list - 获取数据项列表（管理界面用）
router.get('/list', (req, res, next) => {
  try {
    userService.claimLegacyDataForSingleUser(req.userId);
    const db = getDatabase();
    const type = req.query.type as string | undefined;
    const limit = Math.min(parseInt(req.query.limit as string) || 50, 500);
    const offset = parseInt(req.query.offset as string) || 0;

    // 构建查询
    let sql = 'SELECT * FROM items WHERE deleted_time IS NULL';
    const params: (string | number)[] = [];

    if (req.userId) {
      sql += ' AND user_id = ?';
      params.push(req.userId);
    }

    if (type) {
      sql += ' AND type = ?';
      params.push(type);
    }

    sql += ' ORDER BY updated_time DESC LIMIT ? OFFSET ?';
    params.push(limit, offset);

    const items = db.prepare(sql).all(...params);
    res.json({ items, limit, offset });
  } catch (error) {
    next(error);
  }
});

// DELETE /api/items/cleanup - 清理软删除数据
router.delete('/cleanup', (req, res) => {
  const itemService = new ItemService(req.userId);
  const before = req.query.before 
    ? parseInt(req.query.before as string, 10) 
    : Date.now() - 30 * 24 * 60 * 60 * 1000; // 默认 30 天前

  const deleted = itemService.cleanupSoftDeleted(before);
  res.json({
    deleted,
    message: `Cleaned up ${deleted} soft-deleted items`,
  });
});

// POST /api/items/batch - 批量上传
router.post('/batch', (req, res, next) => {
  try {
    const { items } = req.body;

    if (!Array.isArray(items)) {
      throw createError('Items must be an array', 400);
    }

    if (items.length > 100) {
      throw createError('Batch size exceeds limit (100)', 400);
    }

    const itemService = new ItemService(req.userId);
    const result = itemService.batchPut(items);
    res.json(result);
  } catch (error) {
    next(error);
  }
});

// GET /api/items/:id - 获取单个数据项
router.get('/:id', (req, res, next) => {
  try {
    const itemService = new ItemService(req.userId);
    const item = itemService.getItem(req.params.id);

    if (!item) {
      throw createError('Item not found', 404);
    }

    res.json(item);
  } catch (error) {
    next(error);
  }
});

// PUT /api/items/:id - 创建或更新数据项
router.put('/:id', (req, res, next) => {
  try {
    const itemService = new ItemService(req.userId);
    const item = {
      ...req.body,
      id: req.params.id,
    };

    // 验证必需字段
    if (!item.type || !item.payload || !item.content_hash) {
      throw createError('Missing required fields: type, payload, content_hash', 400);
    }

    // 记录同步上传详情
    console.log(JSON.stringify({
      timestamp: new Date().toISOString(),
      level: 'info',
      message: 'Item PUT',
      itemId: item.id,
      type: item.type,
      userId: req.userId,
      contentHash: item.content_hash,
      payloadLength: item.payload?.length || 0,
    }));

    const result = itemService.putItem(item);
    res.json({ success: true, remoteRev: result.remoteRev });
  } catch (error) {
    next(error);
  }
});

// DELETE /api/items/:id - 硬删除数据项
router.delete('/:id', (req, res, next) => {
  try {
    const itemService = new ItemService(req.userId);
    const deleted = itemService.deleteItem(req.params.id);

    if (!deleted) {
      throw createError('Item not found', 404);
    }

    res.json({ success: true });
  } catch (error) {
    next(error);
  }
});

export default router;

import { DatabaseManager } from '../database/Database';
import { ItemBase, NotePayload } from '@shared/types';
import { decryptLocalPayload, isLocalPayloadEncrypted } from '../database/LocalPayloadCrypto';

export interface SearchResult {
  id: string;
  type: string;
  title: string;
  snippet: string;
  matchCount: number;
  score: number;
  updatedTime: number;
}

export interface SearchOptions {
  types?: string[];
  folderId?: string | null;
  tags?: string[];
  dateFrom?: number;
  dateTo?: number;
  limit?: number;
  offset?: number;
}

export class SearchEngine {
  private db: DatabaseManager;
  private ftsInitialized: boolean = false;

  constructor(db: DatabaseManager) {
    this.db = db;
  }

  initializeFTS(): void {
    if (this.ftsInitialized) return;
    this.dropPlaintextFtsArtifacts();
    this.ftsInitialized = true;
  }

  rebuildIndex(): void {
    this.dropPlaintextFtsArtifacts();
  }

  search(query: string, options: SearchOptions = {}): SearchResult[] {
    return this.simpleSearch(query, options);
  }

  simpleSearch(query: string, options: SearchOptions = {}): SearchResult[] {
    if (!query.trim()) return [];

    const { limit = 50, offset = 0 } = options;
    const normalized = query.toLowerCase();
    const notes = this.filterNotes(this.getNotes(), options)
      .map(item => ({ item, payload: this.parseNotePayload(item) }))
      .filter(({ payload }) => {
        const haystack = [
          payload.title,
          payload.content,
          ...(payload.tags || []),
        ].join('\n').toLowerCase();
        return haystack.includes(normalized);
      });

    return notes.slice(offset, offset + limit).map(({ item, payload }) => ({
      id: item.id,
      type: 'note',
      title: payload.title || '无标题',
      snippet: this.generateSnippet(payload.content || payload.title || '', query),
      matchCount: this.countMatches(`${payload.title}\n${payload.content}`, query),
      score: 1,
      updatedTime: item.updated_time,
    }));
  }

  searchByTags(tags: string[]): ItemBase[] {
    if (tags.length === 0) return [];
    return this.getNotes().filter(item => {
      const payload = this.parseNotePayload(item);
      return tags.every(tag => (payload.tags || []).includes(tag));
    });
  }

  searchByDateRange(from: number, to: number): ItemBase[] {
    return this.getNotes().filter(item => item.updated_time >= from && item.updated_time <= to);
  }

  getSuggestions(prefix: string, limit: number = 10): string[] {
    if (!prefix.trim()) return [];
    const normalized = prefix.toLowerCase();
    const seen = new Set<string>();
    const suggestions: string[] = [];

    for (const note of this.getNotes()) {
      const title = this.parseNotePayload(note).title || '';
      if (!title || !title.toLowerCase().startsWith(normalized) || seen.has(title)) {
        continue;
      }
      seen.add(title);
      suggestions.push(title);
      if (suggestions.length >= limit) break;
    }

    return suggestions;
  }

  getPopularTags(limit: number = 20): Array<{ tag: string; count: number }> {
    const tagCounts: Record<string, number> = {};
    for (const note of this.getNotes()) {
      const payload = this.parseNotePayload(note);
      for (const tag of payload.tags || []) {
        tagCounts[tag] = (tagCounts[tag] || 0) + 1;
      }
    }

    return Object.entries(tagCounts)
      .map(([tag, count]) => ({ tag, count }))
      .sort((a, b) => b.count - a.count)
      .slice(0, limit);
  }

  private getNotes(): ItemBase[] {
    return this.db.query<ItemBase>(
      "SELECT * FROM items WHERE type = 'note' AND deleted_time IS NULL ORDER BY updated_time DESC"
    ).map(item => this.decryptItem(item));
  }

  private filterNotes(notes: ItemBase[], options: SearchOptions): ItemBase[] {
    return notes.filter(note => {
      if (options.dateFrom && note.updated_time < options.dateFrom) return false;
      if (options.dateTo && note.updated_time > options.dateTo) return false;

      const payload = this.parseNotePayload(note);
      if (options.folderId !== undefined && payload.folder_id !== options.folderId) return false;
      if (options.tags?.length && !options.tags.every(tag => (payload.tags || []).includes(tag))) return false;
      return true;
    });
  }

  private decryptItem(item: ItemBase): ItemBase {
    if (!isLocalPayloadEncrypted(item.payload)) {
      return item;
    }
    return { ...item, payload: decryptLocalPayload(item.payload) };
  }

  private parseNotePayload(item: ItemBase): NotePayload {
    return JSON.parse(item.payload) as NotePayload;
  }

  private dropPlaintextFtsArtifacts(): void {
    this.db.getDatabase().exec(`
      DROP TRIGGER IF EXISTS notes_fts_insert;
      DROP TRIGGER IF EXISTS notes_fts_update;
      DROP TRIGGER IF EXISTS notes_fts_delete;
      DROP TABLE IF EXISTS notes_fts;
      DROP TABLE IF EXISTS items_fts;
    `);
  }

  private generateSnippet(content: string, query: string, maxLength: number = 150): string {
    const lowerContent = content.toLowerCase();
    const lowerQuery = query.toLowerCase();
    const index = lowerContent.indexOf(lowerQuery);

    if (index === -1) {
      return content.substring(0, maxLength) + (content.length > maxLength ? '...' : '');
    }

    const start = Math.max(0, index - 50);
    const end = Math.min(content.length, index + query.length + 100);
    let snippet = content.substring(start, end);

    if (start > 0) snippet = '...' + snippet;
    if (end < content.length) snippet = snippet + '...';

    return snippet;
  }

  private countMatches(text: string, query: string): number {
    const escapedQuery = query.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
    const regex = new RegExp(escapedQuery, 'gi');
    const matches = text.match(regex);
    return matches ? matches.length : 0;
  }
}

export default SearchEngine;

package com.mucheng.notes.presentation.components

