import dotenv from 'dotenv';
import path from 'path';
import crypto from 'crypto';

dotenv.config();

export interface Config {
  port: number;
  databasePath: string;
  resourcesPath: string;
  apiKeys: string[];
  legacyApiKeyAuthEnabled: boolean;
  logLevel: string;
  jsonBodyLimit: string;
  maxResourceSize: number;
  changeLogRetentionDays: number;
  corsOrigins: string[];
  // JWT 配置
  jwtSecret: string;
  jwtRefreshSecret: string;
  accessTokenExpiresIn: number;
  refreshTokenExpiresIn: number;
  // 频率限制配置
  apiRateLimit: number;
  syncRateLimit: number;
  loginRateLimit: number;
  registerRateLimit: number;
  // 安全配置
  trustProxy: boolean;
  secureMode: boolean;
  // Transfer 中继服务器配置
  transferRelayEnabled: boolean;
  transferRelayPath: string;
  transferRelayKey: string;  // 中继服务器连接密钥
  transferMaxFileSize: number;
  transferMaxConnections: number;
  transferSessionTimeout: number;
  // Transfer 详细配置（供 relay.ts 使用）
  transfer?: {
    maxConnections: number;
    messageRateLimit: number;
    fileTransferLimit: number;
    sessionTimeout: number;
    heartbeatInterval: number;
    relayKey: string;  // 中继密钥
  };
}

function parseApiKeys(value: string | undefined): string[] {
  if (!value) return [];
  return value.split(',').map(k => k.trim()).filter(k => k.length > 0);
}

function parseCorsOrigins(value: string | undefined): string[] {
  if (!value || value === '*') return ['*'];
  return value.split(',').map(o => o.trim()).filter(o => o.length > 0);
}

// 获取 JWT 密钥。
// 生产环境必须显式配置；开发环境使用进程级随机值，避免固定已知后备密钥。
function getRequiredSecret(envValue: string | undefined, envName: string): string {
  if (envValue && envValue.length >= 32) {
    return envValue;
  }

  if (process.env.NODE_ENV === 'production') {
    throw new Error(`${envName} must be set to a value with at least 32 characters`);
  }

  return crypto.randomBytes(32).toString('hex');
}

export const config: Config = {
  port: parseInt(process.env.PORT || '3000', 10),
  databasePath: process.env.DATABASE_PATH || './data/sync.db',
  resourcesPath: process.env.RESOURCES_PATH || './data/resources',
  apiKeys: parseApiKeys(process.env.API_KEYS),
  legacyApiKeyAuthEnabled: process.env.LEGACY_API_KEY_AUTH_ENABLED === 'true',
  logLevel: process.env.LOG_LEVEL || 'info',
  jsonBodyLimit: process.env.JSON_BODY_LIMIT || '50mb',
  maxResourceSize: parseInt(process.env.MAX_RESOURCE_SIZE || '104857600', 10),
  changeLogRetentionDays: parseInt(process.env.CHANGE_LOG_RETENTION_DAYS || '90', 10),
  corsOrigins: parseCorsOrigins(process.env.CORS_ORIGINS),
  // JWT 配置
  jwtSecret: getRequiredSecret(process.env.JWT_SECRET, 'JWT_SECRET'),
  jwtRefreshSecret: getRequiredSecret(process.env.JWT_REFRESH_SECRET, 'JWT_REFRESH_SECRET'),
  accessTokenExpiresIn: parseInt(process.env.ACCESS_TOKEN_EXPIRES_IN || '3600', 10), // 1小时
  refreshTokenExpiresIn: parseInt(process.env.REFRESH_TOKEN_EXPIRES_IN || '2592000', 10), // 30天（原7天太短）
  // 频率限制配置
  apiRateLimit: parseInt(process.env.API_RATE_LIMIT || '10000', 10),
  syncRateLimit: parseInt(process.env.SYNC_RATE_LIMIT || '50000', 10),
  loginRateLimit: parseInt(process.env.LOGIN_RATE_LIMIT || '5', 10),
  registerRateLimit: parseInt(process.env.REGISTER_RATE_LIMIT || '3', 10),
  // 安全配置
  trustProxy: process.env.TRUST_PROXY === 'true',  // 是否信任代理（用于获取真实 IP）
  secureMode: process.env.SECURE_MODE === 'true',  // 是否启用安全模式（强制 HTTPS）
  // Transfer 中继服务器配置
  transferRelayEnabled: process.env.TRANSFER_RELAY_ENABLED !== 'false',  // 默认启用
  transferRelayPath: process.env.TRANSFER_RELAY_PATH || '/transfer',
  transferRelayKey: process.env.TRANSFER_RELAY_KEY || '',  // 中继密钥（必须设置才能使用中继）
  transferMaxFileSize: parseInt(process.env.TRANSFER_MAX_FILE_SIZE || '104857600', 10),  // 100MB
  transferMaxConnections: parseInt(process.env.TRANSFER_MAX_CONNECTIONS || '100', 10),
  transferSessionTimeout: parseInt(process.env.TRANSFER_SESSION_TIMEOUT || '1800000', 10),  // 30分钟
  // Transfer 详细配置
  transfer: {
    maxConnections: parseInt(process.env.TRANSFER_MAX_CONNECTIONS || '100', 10),
    messageRateLimit: parseInt(process.env.TRANSFER_MESSAGE_RATE_LIMIT || '60', 10),  // 每分钟
    fileTransferLimit: parseInt(process.env.TRANSFER_FILE_RATE_LIMIT || '10', 10),  // 每分钟
    sessionTimeout: parseInt(process.env.TRANSFER_SESSION_TIMEOUT || '1800000', 10),  // 30分钟
    heartbeatInterval: parseInt(process.env.TRANSFER_HEARTBEAT_INTERVAL || '30000', 10),  // 30秒
    relayKey: process.env.TRANSFER_RELAY_KEY || '',  // 中继密钥
  },
};

// 安全检查 - 在启动时输出警告
export function checkSecurityConfig(): void {
  const warnings: string[] = [];

  // 检查 JWT 密钥
  if (!process.env.JWT_SECRET || process.env.JWT_SECRET.length < 32) {
    warnings.push('JWT_SECRET 未设置或太短（建议至少32字符）');
  }
  if (!process.env.JWT_REFRESH_SECRET || process.env.JWT_REFRESH_SECRET.length < 32) {
    warnings.push('JWT_REFRESH_SECRET 未设置或太短（建议至少32字符）');
  }

  // 检查中继密钥
  if (config.transferRelayEnabled && !config.transferRelayKey) {
    warnings.push('TRANSFER_RELAY_KEY 未设置，中继服务将拒绝所有连接');
  } else if (config.transferRelayEnabled && config.transferRelayKey.length < 16) {
    warnings.push('TRANSFER_RELAY_KEY 太短（建议至少16字符）');
  }

  // 检查 CORS 配置
  if (config.corsOrigins.includes('*')) {
    warnings.push('CORS_ORIGINS 设置为 *，允许任何来源访问（生产环境建议限制）');
  }

  if (config.apiKeys.length > 0 && !config.legacyApiKeyAuthEnabled) {
    warnings.push('API_KEYS 已设置但旧版 API Key 认证未启用；如确需兼容旧客户端，请设置 LEGACY_API_KEY_AUTH_ENABLED=true');
  } else if (config.legacyApiKeyAuthEnabled) {
    warnings.push('旧版 API Key 认证已启用；当前账号+密码+同步密钥部署建议关闭 LEGACY_API_KEY_AUTH_ENABLED');
  }

  if (config.secureMode && !config.trustProxy) {
    warnings.push('SECURE_MODE 已启用但 TRUST_PROXY 未启用；如果服务在 HTTPS 反代后面，可能无法识别 HTTPS 请求');
  }

  // 检查是否在生产环境使用默认端口
  if (process.env.NODE_ENV === 'production' && config.port === 3000) {
    warnings.push('生产环境建议使用非默认端口');
  }

  if (warnings.length > 0) {
    console.warn('\n⚠️  安全配置警告:');
    warnings.forEach(w => console.warn(`   - ${w}`));
    console.warn('');
  }
}

// 确保数据目录存在
export function ensureDataDirs(): void {
  const fs = require('fs');
  const dbDir = path.dirname(config.databasePath);

  if (!fs.existsSync(dbDir)) {
    fs.mkdirSync(dbDir, { recursive: true });
  }

  if (!fs.existsSync(config.resourcesPath)) {
    fs.mkdirSync(config.resourcesPath, { recursive: true });
  }
}

import { ItemsManager } from '../database/ItemsManager';
import { ItemBase, NotePayload } from '@shared/types';

export interface NoteLink {
  raw: string;           // 原始文本 [[标题]]
  title: string;         // 链接的笔记标题
  targetId?: string;     // 目标笔记 ID（如果存在）
  startIndex: number;    // 在内容中的起始位置
  endIndex: number;      // 在内容中的结束位置
}

export interface BackLink {
  sourceId: string;
  sourceTitle: string;
  context: string;       // 链接所在的上下文
}

export class NoteLinkParser {
  private itemsManager: ItemsManager;
  private linkPattern = /\[\[([^\]]+)\]\]/g;

  constructor(itemsManager: ItemsManager) {
    this.itemsManager = itemsManager;
  }

  // 解析笔记中的所有链接
  parseLinks(content: string): NoteLink[] {
    const links: NoteLink[] = [];
    let match;

    while ((match = this.linkPattern.exec(content)) !== null) {
      const title = match[1].trim();
      const targetNote = this.findNoteByTitle(title);

      links.push({
        raw: match[0],
        title,
        targetId: targetNote?.id,
        startIndex: match.index,
        endIndex: match.index + match[0].length,
      });
    }

    return links;
  }

  // 根据标题查找笔记
  findNoteByTitle(title: string): ItemBase | undefined {
    const notes = this.itemsManager.getByType('note');
    return notes.find(note => {
      const payload = JSON.parse(note.payload) as NotePayload;
      return payload.title.toLowerCase() === title.toLowerCase();
    });
  }

  // 获取笔记的反向链接
  getBackLinks(noteId: string): BackLink[] {
    const targetNote = this.itemsManager.getById(noteId);
    if (!targetNote) return [];

    const targetPayload = JSON.parse(targetNote.payload) as NotePayload;
    const targetTitle = targetPayload.title;

    const backLinks: BackLink[] = [];
    const allNotes = this.itemsManager.getByType('note');

    for (const note of allNotes) {
      if (note.id === noteId) continue;

      const payload = JSON.parse(note.payload) as NotePayload;
      const links = this.parseLinks(payload.content);

      for (const link of links) {
        if (link.title.toLowerCase() === targetTitle.toLowerCase()) {
          backLinks.push({
            sourceId: note.id,
            sourceTitle: payload.title,
            context: this.extractContext(payload.content, link.startIndex),
          });
        }
      }
    }

    return backLinks;
  }

  // 提取链接上下文
  private extractContext(content: string, linkIndex: number, contextLength: number = 100): string {
    const start = Math.max(0, linkIndex - contextLength / 2);
    const end = Math.min(content.length, linkIndex + contextLength / 2);
    let context = content.substring(start, end);

    if (start > 0) context = '...' + context;
    if (end < content.length) context = context + '...';

    return context.replace(/\n/g, ' ').trim();
  }

  // 更新笔记中的链接（当目标笔记标题变化时）
  updateLinks(oldTitle: string, newTitle: string): number {
    let updatedCount = 0;
    const allNotes = this.itemsManager.getByType('note');

    for (const note of allNotes) {
      const payload = JSON.parse(note.payload) as NotePayload;
      const oldPattern = `[[${oldTitle}]]`;
      const newPattern = `[[${newTitle}]]`;

      if (payload.content.includes(oldPattern)) {
        payload.content = payload.content.replace(
          new RegExp(`\\[\\[${this.escapeRegex(oldTitle)}\\]\\]`, 'g'),
          newPattern
        );
        this.itemsManager.update(note.id, payload);
        updatedCount++;
      }
    }

    return updatedCount;
  }

  // 将链接转换为可点击的 HTML
  renderLinksAsHtml(content: string): string {
    return content.replace(this.linkPattern, (match, title) => {
      const targetNote = this.findNoteByTitle(title);
      if (targetNote) {
        return `<a href="note://${targetNote.id}" class="note-link">${title}</a>`;
      }
      return `<span class="note-link-broken">${title}</span>`;
    });
  }

  // 获取所有链接的笔记（图谱数据）
  getLinksGraph(): Array<{ source: string; target: string; sourceTitle: string; targetTitle: string }> {
    const edges: Array<{ source: string; target: string; sourceTitle: string; targetTitle: string }> = [];
    const allNotes = this.itemsManager.getByType('note');

    for (const note of allNotes) {
      const payload = JSON.parse(note.payload) as NotePayload;
      const links = this.parseLinks(payload.content);

      for (const link of links) {
        if (link.targetId) {
          edges.push({
            source: note.id,
            target: link.targetId,
            sourceTitle: payload.title,
            targetTitle: link.title,
          });
        }
      }
    }

    return edges;
  }

  private escapeRegex(str: string): string {
    return str.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
  }
}

export default NoteLinkParser;

package com.mucheng.notes.security

import kotlinx.coroutines.delay
import kotlinx.coroutines.flow.Flow
import kotlinx.coroutines.flow.flow
import javax.crypto.Mac
import javax.crypto.spec.SecretKeySpec
import javax.inject.Inject
import javax.inject.Singleton
import kotlin.experimental.and

/**
 * TOTP 代码数据
 */
data class TOTPCode(
    val code: String,
    val remainingSeconds: Int
)

/**
 * TOTP 生成器接口
 */
interface TOTPGenerator {

    /**
     * 生成 TOTP 代码
     * @param secret Base32 编码的密钥
     * @param time 时间戳（毫秒），默认当前时间
     * @return 6 位数字代码
     */
    fun generateCode(secret: String, time: Long = System.currentTimeMillis()): String

    /**
     * 获取当前周期剩余秒数
     */
    fun getRemainingSeconds(): Int

    /**
     * 观察 TOTP 代码变化
     * @param secret Base32 编码的密钥
     * @return 持续发射 TOTPCode 的 Flow
     */
    fun observeCode(secret: String): Flow<TOTPCode>
}

/**
 * TOTP 生成器实现
 * 遵循 RFC 6238 标准
 */
@Singleton
class TOTPGeneratorImpl @Inject constructor() : TOTPGenerator {

    companion object {
        private const val TIME_STEP = 30L // 30 秒
        private const val CODE_DIGITS = 6
        private const val HMAC_ALGORITHM = "HmacSHA1"

        // Base32 字符集
        private const val BASE32_CHARS = "ABCDEFGHIJKLMNOPQRSTUVWXYZ234567"
    }

    override fun generateCode(secret: String, time: Long): String {
        // 验证密钥是否有效
        val cleanSecret = secret.uppercase().replace(" ", "").replace("-", "")
        if (cleanSecret.isEmpty()) {
            return "------"
        }

        // 验证是否为有效的 Base32 字符
        if (!cleanSecret.all { it in BASE32_CHARS || it == '=' }) {
            return "------"
        }

        return try {
            val key = base32Decode(cleanSecret)
            if (key.isEmpty()) {
                return "------"
            }

            val counter = time / 1000 / TIME_STEP

            val counterBytes = ByteArray(8)
            var value = counter
            for (i in 7 downTo 0) {
                counterBytes[i] = (value and 0xFF).toByte()
                value = value shr 8
            }

            val mac = Mac.getInstance(HMAC_ALGORITHM)
            mac.init(SecretKeySpec(key, HMAC_ALGORITHM))
            val hash = mac.doFinal(counterBytes)

            val offset = (hash[hash.size - 1] and 0x0F).toInt()
            val binary = ((hash[offset].toInt() and 0x7F) shl 24) or
                    ((hash[offset + 1].toInt() and 0xFF) shl 16) or
                    ((hash[offset + 2].toInt() and 0xFF) shl 8) or
                    (hash[offset + 3].toInt() and 0xFF)

            val otp = binary % Math.pow(10.0, CODE_DIGITS.toDouble()).toInt()
            otp.toString().padStart(CODE_DIGITS, '0')
        } catch (e: Exception) {
            // 任何异常都返回占位符，避免崩溃
            "------"
        }
    }

    override fun getRemainingSeconds(): Int {
        val currentSecond = (System.currentTimeMillis() / 1000) % TIME_STEP
        return (TIME_STEP - currentSecond).toInt()
    }

    override fun observeCode(secret: String): Flow<TOTPCode> = flow {
        // 如果密钥为空或无效，不启动 Flow
        val cleanSecret = secret.uppercase().replace(" ", "").replace("-", "")
        if (cleanSecret.isEmpty()) {
            emit(TOTPCode("------", 30))
            return@flow
        }

        while (true) {
            try {
                val code = generateCode(secret)
                val remaining = getRemainingSeconds()
                emit(TOTPCode(code, remaining))
            } catch (e: Exception) {
                emit(TOTPCode("------", 30))
            }

            // 等待到下一秒
            delay(1000)
        }
    }

    /**
     * Base32 解码
     */
    private fun base32Decode(input: String): ByteArray {
        val cleanInput = input.replace("=", "")
        val output = ByteArray(cleanInput.length * 5 / 8)

        var buffer = 0
        var bitsLeft = 0
        var outputIndex = 0

        for (char in cleanInput) {
            val value = BASE32_CHARS.indexOf(char)
            if (value < 0) continue

            buffer = (buffer shl 5) or value
            bitsLeft += 5

            if (bitsLeft >= 8) {
                bitsLeft -= 8
                output[outputIndex++] = (buffer shr bitsLeft).toByte()
            }
        }

        return output.copyOf(outputIndex)
    }
}

