/**
 * useImageHistory - 图片处理历史管理 Hook
 * 支持撤销/重做操作，最多保存 20 条历史记录
 */

import { useState, useCallback, useMemo } from 'react';
import { ProcessOptions, ProcessResult } from '../services/imageApi';

// 图片工具类型
export type ImageToolType =
  | 'format-convert'
  | 'resize'
  | 'crop'
  | 'rotate-flip'
  | 'color-adjust'
  | 'filters'
  | 'watermark'
  | 'metadata'
  | 'compress';

// 历史状态接口
export interface HistoryState {
  id: string;
  timestamp: number;
  toolType: ImageToolType;
  options: ProcessOptions;
  previewUrl: string;
  result?: ProcessResult;
}

// 历史管理器配置
const MAX_HISTORY = 20;

// 生成唯一 ID
const generateId = (): string => {
  return `${Date.now()}-${Math.random().toString(36).substr(2, 9)}`;
};

/**
 * 图片处理历史管理 Hook
 */
export function useImageHistory() {
  // 历史记录数组
  const [history, setHistory] = useState<HistoryState[]>([]);
  // 当前索引（指向当前状态在历史中的位置）
  const [currentIndex, setCurrentIndex] = useState(-1);

  /**
   * 添加新的历史状态
   */
  const push = useCallback((state: Omit<HistoryState, 'id' | 'timestamp'>) => {
    const newState: HistoryState = {
      ...state,
      id: generateId(),
      timestamp: Date.now(),
    };

    setHistory(prev => {
      // 如果当前不在历史末尾，删除当前位置之后的所有记录
      const newHistory = prev.slice(0, currentIndex + 1);

      // 添加新状态
      newHistory.push(newState);

      // 如果超过最大限制，删除最旧的记录
      if (newHistory.length > MAX_HISTORY) {
        newHistory.shift();
        return newHistory;
      }

      return newHistory;
    });

    setCurrentIndex(prev => {
      // 计算新索引
      const newIndex = Math.min(prev + 1, MAX_HISTORY - 1);
      return newIndex;
    });
  }, [currentIndex]);

  /**
   * 撤销操作
   */
  const undo = useCallback((): HistoryState | null => {
    if (currentIndex <= 0) {
      return null;
    }

    const newIndex = currentIndex - 1;
    setCurrentIndex(newIndex);
    return history[newIndex] || null;
  }, [currentIndex, history]);

  /**
   * 重做操作
   */
  const redo = useCallback((): HistoryState | null => {
    if (currentIndex >= history.length - 1) {
      return null;
    }

    const newIndex = currentIndex + 1;
    setCurrentIndex(newIndex);
    return history[newIndex] || null;
  }, [currentIndex, history]);

  /**
   * 清空历史
   */
  const clear = useCallback(() => {
    setHistory([]);
    setCurrentIndex(-1);
  }, []);

  /**
   * 获取当前状态
   */
  const getCurrentState = useCallback((): HistoryState | null => {
    if (currentIndex < 0 || currentIndex >= history.length) {
      return null;
    }
    return history[currentIndex];
  }, [currentIndex, history]);

  /**
   * 是否可以撤销
   */
  const canUndo = useMemo(() => currentIndex > 0, [currentIndex]);

  /**
   * 是否可以重做
   */
  const canRedo = useMemo(() => currentIndex < history.length - 1, [currentIndex, history.length]);

  /**
   * 历史记录长度
   */
  const historyLength = useMemo(() => history.length, [history]);

  return {
    // 状态
    history,
    currentIndex,
    historyLength,
    canUndo,
    canRedo,

    // 方法
    push,
    undo,
    redo,
    clear,
    getCurrentState,
  };
}

export default useImageHistory;

/**
 * useImageKeyboard - 图片处理快捷键 Hook
 * 支持常用操作的键盘快捷键
 */

import { useEffect, useCallback, useMemo } from 'react';

// 快捷键动作类型
export type KeyboardAction = 'undo' | 'redo' | 'save' | 'reset';

// 快捷键定义
export interface KeyboardShortcut {
  key: string;
  ctrl?: boolean;
  shift?: boolean;
  alt?: boolean;
  action: KeyboardAction;
  description: string;
}

// 快捷键回调
export interface KeyboardCallbacks {
  onUndo?: () => void;
  onRedo?: () => void;
  onSave?: () => void;
  onReset?: () => void;
}

// 默认快捷键配置
export const DEFAULT_SHORTCUTS: KeyboardShortcut[] = [
  {
    key: 'z',
    ctrl: true,
    action: 'undo',
    description: '撤销 (Ctrl+Z)',
  },
  {
    key: 'y',
    ctrl: true,
    action: 'redo',
    description: '重做 (Ctrl+Y)',
  },
  {
    key: 'z',
    ctrl: true,
    shift: true,
    action: 'redo',
    description: '重做 (Ctrl+Shift+Z)',
  },
  {
    key: 's',
    ctrl: true,
    action: 'save',
    description: '保存 (Ctrl+S)',
  },
  {
    key: 'Escape',
    action: 'reset',
    description: '重置 (Esc)',
  },
];

// 快捷键帮助信息
export const SHORTCUT_HELP = [
  { keys: 'Ctrl + Z', action: '撤销上一步操作' },
  { keys: 'Ctrl + Y', action: '重做操作' },
  { keys: 'Ctrl + Shift + Z', action: '重做操作（备选）' },
  { keys: 'Ctrl + S', action: '保存当前图片' },
  { keys: 'Esc', action: '重置当前操作' },
];

/**
 * 检查键盘事件是否匹配快捷键
 */
function matchShortcut(event: KeyboardEvent, shortcut: KeyboardShortcut): boolean {
  const keyMatch = event.key.toLowerCase() === shortcut.key.toLowerCase();
  const ctrlMatch = !!shortcut.ctrl === (event.ctrlKey || event.metaKey);
  const shiftMatch = !!shortcut.shift === event.shiftKey;
  const altMatch = !!shortcut.alt === event.altKey;

  return keyMatch && ctrlMatch && shiftMatch && altMatch;
}

/**
 * 图片处理快捷键 Hook
 */
export function useImageKeyboard(
  callbacks: KeyboardCallbacks,
  enabled: boolean = true
) {
  // 处理键盘事件
  const handleKeyDown = useCallback(
    (event: KeyboardEvent) => {
      if (!enabled) return;

      // 如果焦点在输入框中，不处理快捷键（除了 Escape）
      const target = event.target as HTMLElement;
      const isInputFocused =
        target.tagName === 'INPUT' ||
        target.tagName === 'TEXTAREA' ||
        target.isContentEditable;

      for (const shortcut of DEFAULT_SHORTCUTS) {
        if (matchShortcut(event, shortcut)) {
          // Escape 键在输入框中也应该生效
          if (isInputFocused && shortcut.action !== 'reset') {
            continue;
          }

          event.preventDefault();
          event.stopPropagation();

          switch (shortcut.action) {
            case 'undo':
              callbacks.onUndo?.();
              break;
            case 'redo':
              callbacks.onRedo?.();
              break;
            case 'save':
              callbacks.onSave?.();
              break;
            case 'reset':
              callbacks.onReset?.();
              break;
          }

          return;
        }
      }
    },
    [callbacks, enabled]
  );

  // 注册键盘事件监听
  useEffect(() => {
    if (!enabled) return;

    window.addEventListener('keydown', handleKeyDown);

    return () => {
      window.removeEventListener('keydown', handleKeyDown);
    };
  }, [handleKeyDown, enabled]);

  // 返回快捷键帮助信息
  const shortcuts = useMemo(() => DEFAULT_SHORTCUTS, []);
  const help = useMemo(() => SHORTCUT_HELP, []);

  return {
    shortcuts,
    help,
  };
}

export default useImageKeyboard;

/**
 * useImageSettings - 图片处理设置持久化 Hook
 * 记住用户的设置偏好
 */

import { useState, useCallback, useEffect, useMemo } from 'react';
import { ProcessOptions } from '../services/imageApi';
import { ImageToolType } from './useImageHistory';

// 用户设置接口
export interface UserSettings {
  // 实时预览开关
  realTimePreview: boolean;
  // 最后使用的工具
  lastUsedTool: ImageToolType;
  // 每个工具的最后使用设置
  toolSettings: Partial<Record<ImageToolType, Partial<ProcessOptions>>>;
}

// 默认设置
const DEFAULT_SETTINGS: UserSettings = {
  realTimePreview: true,
  lastUsedTool: 'format-convert',
  toolSettings: {},
};

// localStorage 存储键
const STORAGE_KEY = 'image-tool-settings';

/**
 * 从 localStorage 加载设置
 */
function loadSettings(): UserSettings {
  try {
    const stored = localStorage.getItem(STORAGE_KEY);
    if (stored) {
      const parsed = JSON.parse(stored);
      return {
        ...DEFAULT_SETTINGS,
        ...parsed,
      };
    }
  } catch (error) {
    console.error('Failed to load image settings:', error);
  }
  return DEFAULT_SETTINGS;
}

/**
 * 保存设置到 localStorage
 */
function saveSettings(settings: UserSettings): void {
  try {
    localStorage.setItem(STORAGE_KEY, JSON.stringify(settings));
  } catch (error) {
    console.error('Failed to save image settings:', error);
  }
}

/**
 * 图片处理设置持久化 Hook
 */
export function useImageSettings() {
  const [settings, setSettings] = useState<UserSettings>(() => loadSettings());

  // 保存设置变更
  useEffect(() => {
    saveSettings(settings);
  }, [settings]);

  /**
   * 更新实时预览开关
   */
  const setRealTimePreview = useCallback((enabled: boolean) => {
    setSettings(prev => ({
      ...prev,
      realTimePreview: enabled,
    }));
  }, []);

  /**
   * 更新最后使用的工具
   */
  const setLastUsedTool = useCallback((tool: ImageToolType) => {
    setSettings(prev => ({
      ...prev,
      lastUsedTool: tool,
    }));
  }, []);

  /**
   * 获取指定工具的设置
   */
  const getToolSettings = useCallback((toolType: ImageToolType): Partial<ProcessOptions> => {
    return settings.toolSettings[toolType] || {};
  }, [settings.toolSettings]);

  /**
   * 保存指定工具的设置
   */
  const saveToolSettings = useCallback((toolType: ImageToolType, options: Partial<ProcessOptions>) => {
    setSettings(prev => ({
      ...prev,
      toolSettings: {
        ...prev.toolSettings,
        [toolType]: {
          ...prev.toolSettings[toolType],
          ...options,
        },
      },
    }));
  }, []);

  /**
   * 清除指定工具的设置
   */
  const clearToolSettings = useCallback((toolType: ImageToolType) => {
    setSettings(prev => {
      const newToolSettings = { ...prev.toolSettings };
      delete newToolSettings[toolType];
      return {
        ...prev,
        toolSettings: newToolSettings,
      };
    });
  }, []);

  /**
   * 重置所有设置为默认值
   */
  const resetSettings = useCallback(() => {
    setSettings(DEFAULT_SETTINGS);
  }, []);

  /**
   * 获取所有设置
   */
  const allSettings = useMemo(() => settings, [settings]);

  return {
    // 状态
    realTimePreview: settings.realTimePreview,
    lastUsedTool: settings.lastUsedTool,
    allSettings,

    // 方法
    setRealTimePreview,
    setLastUsedTool,
    getToolSettings,
    saveToolSettings,
    clearToolSettings,
    resetSettings,
  };
}

export default useImageSettings;

/**
 * useRealTimePreview - 实时预览 Hook
 * 支持防抖处理和低分辨率预览
 */

import { useState, useCallback, useRef, useEffect } from 'react';
import { ProcessOptions, ProcessResult, imageApi } from '../services/imageApi';

// 实时预览配置
export interface RealTimePreviewConfig {
  enabled: boolean;
  debounceMs: number;
  previewScale: number; // 预览缩放比例
}

// 默认配置
const DEFAULT_CONFIG: RealTimePreviewConfig = {
  enabled: true,
  debounceMs: 300,
  previewScale: 0.5,
};

/**
 * 实时预览 Hook
 */
export function useRealTimePreview(
  imageData: string | null,
  config: Partial<RealTimePreviewConfig> = {}
) {
  const mergedConfig = { ...DEFAULT_CONFIG, ...config };

  const [previewResult, setPreviewResult] = useState<ProcessResult | null>(null);
  const [isProcessing, setIsProcessing] = useState(false);
  const [error, setError] = useState<string | null>(null);

  // 防抖定时器
  const debounceTimerRef = useRef<NodeJS.Timeout | null>(null);
  // 请求计数器（用于取消过期请求）
  const requestIdRef = useRef(0);

  /**
   * 清除防抖定时器
   */
  const clearDebounceTimer = useCallback(() => {
    if (debounceTimerRef.current) {
      clearTimeout(debounceTimerRef.current);
      debounceTimerRef.current = null;
    }
  }, []);

  /**
   * 执行预览处理
   */
  const processPreview = useCallback(async (
    options: ProcessOptions,
    immediate: boolean = false
  ) => {
    if (!imageData || !mergedConfig.enabled) {
      return;
    }

    // 清除之前的定时器
    clearDebounceTimer();

    const doProcess = async () => {
      const currentRequestId = ++requestIdRef.current;

      setIsProcessing(true);
      setError(null);

      try {
        // 使用低分辨率预览
        const previewOptions: ProcessOptions = {
          ...options,
          // 如果有 resize 选项，按比例缩小
          resize: options.resize ? {
            ...options.resize,
            width: options.resize.width 
              ? Math.round(options.resize.width * mergedConfig.previewScale) 
              : undefined,
            height: options.resize.height 
              ? Math.round(options.resize.height * mergedConfig.previewScale) 
              : undefined,
          } : undefined,
        };

        const result = await imageApi.process(imageData, previewOptions);

        // 检查请求是否过期
        if (currentRequestId === requestIdRef.current) {
          setPreviewResult(result);
        }
      } catch (err) {
        // 检查请求是否过期
        if (currentRequestId === requestIdRef.current) {
          setError((err as Error).message);
        }
      } finally {
        // 检查请求是否过期
        if (currentRequestId === requestIdRef.current) {
          setIsProcessing(false);
        }
      }
    };

    if (immediate) {
      await doProcess();
    } else {
      // 防抖处理
      debounceTimerRef.current = setTimeout(doProcess, mergedConfig.debounceMs);
    }
  }, [imageData, mergedConfig.enabled, mergedConfig.debounceMs, mergedConfig.previewScale, clearDebounceTimer]);

  /**
   * 取消当前预览
   */
  const cancelPreview = useCallback(() => {
    clearDebounceTimer();
    requestIdRef.current++;
    setIsProcessing(false);
  }, [clearDebounceTimer]);

  /**
   * 清除预览结果
   */
  const clearPreview = useCallback(() => {
    cancelPreview();
    setPreviewResult(null);
    setError(null);
  }, [cancelPreview]);

  // 组件卸载时清理
  useEffect(() => {
    return () => {
      clearDebounceTimer();
    };
  }, [clearDebounceTimer]);

  return {
    // 状态
    previewResult,
    isProcessing,
    error,

    // 方法
    processPreview,
    cancelPreview,
    clearPreview,
  };
}

export default useRealTimePreview;

package com.mucheng.notes.security

import android.app.Activity
import android.content.ClipData
import android.content.ClipboardManager
import android.content.Context
import android.os.Build
import android.os.Handler
import android.os.Looper
import android.view.WindowManager
import androidx.core.content.getSystemService

/**
 * 安全工具类
 * 
 * 提供安全相关的工具方法：
 * - FLAG_SECURE 防截图
 * - 剪贴板安全管理
 * - 敏感数据清理
 */
object SecurityUtils {

    private const val CLIPBOARD_CLEAR_DELAY = 30_000L // 30 秒

    /**
     * 启用 FLAG_SECURE 防截图
     * 用于密码库等敏感界面
     */
    fun enableSecureMode(activity: Activity) {
        activity.window.setFlags(
            WindowManager.LayoutParams.FLAG_SECURE,
            WindowManager.LayoutParams.FLAG_SECURE
        )
    }

    /**
     * 禁用 FLAG_SECURE
     */
    fun disableSecureMode(activity: Activity) {
        activity.window.clearFlags(WindowManager.LayoutParams.FLAG_SECURE)
    }

    /**
     * 安全复制到剪贴板
     * 30 秒后自动清除
     * 
     * @param context Context
     * @param label 剪贴板标签
     * @param text 要复制的文本
     * @param isSensitive 是否为敏感数据（密码等）
     */
    fun copyToClipboard(
        context: Context,
        label: String,
        text: String,
        isSensitive: Boolean = false
    ) {
        val clipboardManager = context.getSystemService<ClipboardManager>() ?: return

        val clipData = if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.N && isSensitive) {
            // Android 7.0+ 支持敏感数据标记
            ClipData.newPlainText(label, text).apply {
                description.extras = android.os.PersistableBundle().apply {
                    putBoolean("android.content.extra.IS_SENSITIVE", true)
                }
            }
        } else {
            ClipData.newPlainText(label, text)
        }

        clipboardManager.setPrimaryClip(clipData)

        // 30 秒后自动清除敏感数据
        if (isSensitive) {
            Handler(Looper.getMainLooper()).postDelayed({
                clearClipboard(context)
            }, CLIPBOARD_CLEAR_DELAY)
        }
    }

    /**
     * 清除剪贴板
     */
    fun clearClipboard(context: Context) {
        val clipboardManager = context.getSystemService<ClipboardManager>() ?: return

        if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.P) {
            clipboardManager.clearPrimaryClip()
        } else {
            // 旧版本通过设置空内容清除
            clipboardManager.setPrimaryClip(ClipData.newPlainText("", ""))
        }
    }

    /**
     * 安全清除字符串
     * 用于清除内存中的敏感数据
     */
    fun secureWipe(data: CharArray) {
        data.fill('\u0000')
    }

    /**
     * 安全清除字节数组
     */
    fun secureWipe(data: ByteArray) {
        data.fill(0)
    }

    /**
     * 检查是否在安全环境中运行
     * 检测 root、模拟器等
     */
    fun isSecureEnvironment(): Boolean {
        return !isRooted() && !isEmulator()
    }

    /**
     * 检测设备是否 root
     */
    private fun isRooted(): Boolean {
        val paths = arrayOf(
            "/system/app/Superuser.apk",
            "/sbin/su",
            "/system/bin/su",
            "/system/xbin/su",
            "/data/local/xbin/su",
            "/data/local/bin/su",
            "/system/sd/xbin/su",
            "/system/bin/failsafe/su",
            "/data/local/su"
        )

        return paths.any { java.io.File(it).exists() }
    }

    /**
     * 检测是否在模拟器中运行
     */
    private fun isEmulator(): Boolean {
        return (Build.FINGERPRINT.startsWith("generic")
                || Build.FINGERPRINT.startsWith("unknown")
                || Build.MODEL.contains("google_sdk")
                || Build.MODEL.contains("Emulator")
                || Build.MODEL.contains("Android SDK built for x86")
                || Build.MANUFACTURER.contains("Genymotion")
                || (Build.BRAND.startsWith("generic") && Build.DEVICE.startsWith("generic"))
                || "google_sdk" == Build.PRODUCT)
    }
}

