        }
    }

    MaterialTheme(
        colorScheme = colorScheme,
        content = content
    )
}

/**
 * useGenerator Hook
 * 管理密码/资料生成器的状态和逻辑
 */

import { useState, useCallback } from 'react';
import {
  GeneratorOptions,
  GeneratedProfile,
  DEFAULT_GENERATOR_OPTIONS,
  GeneratorCountryCode,
  GeneratorGender,
  PasswordOptions,
  GeneratorIncludeFields,
} from '@shared/types';
import {
  generateProfile,
  generateBatch,
  validateGeneratorOptions,
  formatProfileAsNotes,
  formatProfileForCopy,
} from '../services/fakerGenerator';

export interface UseGeneratorReturn {
  // 配置状态
  options: GeneratorOptions;
  setCountry: (country: GeneratorCountryCode) => void;
  setGender: (gender: GeneratorGender) => void;
  setQuantity: (quantity: number) => void;
  setPasswordOptions: (options: PasswordOptions) => void;
  setIncludeFields: (fields: GeneratorIncludeFields) => void;
  toggleIncludeField: (field: keyof GeneratorIncludeFields) => void;
  resetOptions: () => void;

  // 生成结果
  profiles: GeneratedProfile[];
  loading: boolean;
  error: string | null;

  // 操作
  generate: () => void;
  clearProfiles: () => void;

  // 工具函数
  formatAsNotes: (profile: GeneratedProfile) => string;
  formatForCopy: (profile: GeneratedProfile) => string;
}

export function useGenerator(): UseGeneratorReturn {
  const [options, setOptions] = useState<GeneratorOptions>(DEFAULT_GENERATOR_OPTIONS);
  const [profiles, setProfiles] = useState<GeneratedProfile[]>([]);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);

  // 设置国家
  const setCountry = useCallback((country: GeneratorCountryCode) => {
    setOptions(prev => ({ ...prev, country }));
  }, []);

  // 设置性别
  const setGender = useCallback((gender: GeneratorGender) => {
    setOptions(prev => ({ ...prev, gender }));
  }, []);

  // 设置数量
  const setQuantity = useCallback((quantity: number) => {
    setOptions(prev => ({ ...prev, quantity }));
  }, []);

  // 设置密码选项
  const setPasswordOptions = useCallback((passwordOptions: PasswordOptions) => {
    setOptions(prev => ({ ...prev, passwordOptions }));
  }, []);

  // 设置可选字段
  const setIncludeFields = useCallback((includeFields: GeneratorIncludeFields) => {
    setOptions(prev => ({ ...prev, includeFields }));
  }, []);

  // 切换单个可选字段
  const toggleIncludeField = useCallback((field: keyof GeneratorIncludeFields) => {
    setOptions(prev => ({
      ...prev,
      includeFields: {
        ...prev.includeFields,
        [field]: !prev.includeFields[field],
      },
    }));
  }, []);

  // 重置选项
  const resetOptions = useCallback(() => {
    setOptions(DEFAULT_GENERATOR_OPTIONS);
  }, []);

  // 生成资料
  const generate = useCallback(() => {
    setError(null);

    // 验证选项
    const validationError = validateGeneratorOptions(options);
    if (validationError) {
      setError(validationError);
      return;
    }

    setLoading(true);

    try {
      const newProfiles = generateBatch(options);
      setProfiles(newProfiles);
    } catch (err) {
      setError(err instanceof Error ? err.message : '生成失败');
    } finally {
      setLoading(false);
    }
  }, [options]);

  // 清除生成结果
  const clearProfiles = useCallback(() => {
    setProfiles([]);
    setError(null);
  }, []);

  return {
    options,
    setCountry,
    setGender,
    setQuantity,
    setPasswordOptions,
    setIncludeFields,
    toggleIncludeField,
    resetOptions,
    profiles,
    loading,
    error,
    generate,
    clearProfiles,
    formatAsNotes: formatProfileAsNotes,
    formatForCopy: formatProfileForCopy,
  };
}

import { Request, Response, NextFunction } from 'express';
import crypto from 'crypto';
import { config } from '../config';
import { tokenService } from '../services/TokenService';
import { AuthErrorCodes } from '../services/AuthService';
import { AccessTokenPayload, AuthMethod } from '../types';

// 计算 API Key 的哈希值
export function hashApiKey(apiKey: string): string {
  return crypto.createHash('sha256').update(apiKey).digest('hex');
}

// 验证 API Key
function isValidApiKey(apiKey: string): boolean {
  if (!config.legacyApiKeyAuthEnabled) {
    return false;
  }
  return config.apiKeys.includes(apiKey);
}

// 不需要认证的路径
const PUBLIC_PATHS = [
  '/api/health',
  '/api/health/status',
  '/api/auth/register',
  '/api/auth/login',
  '/api/auth/refresh',
  '/api/user/reset-password'
];

// 检查是否是公开路径
function isPublicPath(path: string): boolean {
  return PUBLIC_PATHS.some(p => path === p || path.startsWith(p + '/'));
}

// 认证中间件
export function authMiddleware(req: Request, res: Response, next: NextFunction): void {
  // 公开端点不需要认证
  if (isPublicPath(req.path)) {
    return next();
  }

  const apiKey = req.headers['x-api-key'] as string | undefined;
  const authHeader = req.headers['authorization'] as string | undefined;

  // 优先检查 JWT Bearer Token
  if (authHeader?.startsWith('Bearer ')) {
    const token = authHeader.slice(7);

    // 首先尝试验证为 JWT
    const payload = tokenService.verifyAccessToken(token);
    if (payload) {
      // JWT 认证成功
      req.userId = payload.sub;
      req.sessionId = payload.sid;
      req.syncKeyFingerprint = payload.skf;
      req.userRole = payload.role;
      req.authMethod = 'jwt';
      return next();
    }

    // 如果不是有效的 JWT，尝试作为 API Key 验证（向后兼容）
    if (isValidApiKey(token)) {
      req.apiKeyHash = hashApiKey(token);
      req.authMethod = 'apiKey';
      return next();
    }

    // 令牌无效
    res.status(401).json({
      error: {
        code: AuthErrorCodes.INVALID_TOKEN,
        message: '访问令牌无效或已过期'
      }
    });
    return;
  }

  // 检查 X-API-Key 头（向后兼容）
  if (apiKey && isValidApiKey(apiKey)) {
    req.apiKeyHash = hashApiKey(apiKey);
    req.authMethod = 'apiKey';
    return next();
  }

  // 认证失败
  if (apiKey || authHeader) {
    res.status(403).json({
      error: {
        code: AuthErrorCodes.INVALID_TOKEN,
        message: '无效的认证凭据'
      }
    });
  } else {
    res.status(401).json({
      error: {
        code: AuthErrorCodes.NO_AUTH,
        message: '未提供认证信息'
      }
    });
  }
}

// 管理员权限中间件
export function adminMiddleware(req: Request, res: Response, next: NextFunction): void {
  if (req.userRole !== 'admin') {
    res.status(403).json({
      error: {
        code: AuthErrorCodes.NO_ADMIN,
        message: '需要管理员权限'
      }
    });
    return;
  }
  next();
}

// 同步密钥指纹验证中间件（可选，用于需要额外验证的操作）
export function syncKeyMiddleware(req: Request, res: Response, next: NextFunction): void {
  // 只对 JWT 认证的请求验证同步密钥
  if (req.authMethod !== 'jwt') {
    return next();
  }

  const clientFingerprint = req.headers['x-sync-key-fingerprint'] as string | undefined;

  // 如果客户端提供了指纹，验证是否匹配
  if (clientFingerprint && clientFingerprint !== req.syncKeyFingerprint) {
    res.status(403).json({
      error: {
        code: AuthErrorCodes.SYNC_KEY_MISMATCH,
        message: '同步密钥指纹不匹配'
      }
    });
    return;
  }

  next();
}

package com.mucheng.notes.data.local.dao

import androidx.room.Dao
import androidx.room.Insert
import androidx.room.OnConflictStrategy
import androidx.room.Query
import com.mucheng.notes.data.local.entity.ItemEntity
import kotlinx.coroutines.flow.Flow

/**
 * Room DAO for items table
 * 提供所有数据项的 CRUD 操作
 */
@Dao
interface ItemDao {

    /**
     * 按类型获取所有未删除的项目（实时流）
     */
    @Query("SELECT * FROM items WHERE type = :type AND deleted_time IS NULL ORDER BY updated_time DESC")
    fun getByType(type: String): Flow<List<ItemEntity>>

    /**
     * 按多种类型获取所有未删除的项目（实时流）
     */
    @Query("SELECT * FROM items WHERE type IN (:types) AND deleted_time IS NULL ORDER BY updated_time DESC")
    fun getByTypes(types: List<String>): Flow<List<ItemEntity>>

    /**
     * 按类型获取所有未删除的项目（一次性查询）
     */
    @Query("SELECT * FROM items WHERE type = :type AND deleted_time IS NULL ORDER BY updated_time DESC")
    suspend fun getByTypeOnce(type: String): List<ItemEntity>

    /**
     * 按 ID 获取单个项目
     */
    @Query("SELECT * FROM items WHERE id = :id")
    suspend fun getById(id: String): ItemEntity?

    /**
     * 按 ID 获取未删除的项目
     */
    @Query("SELECT * FROM items WHERE id = :id AND deleted_time IS NULL")
    suspend fun getByIdNotDeleted(id: String): ItemEntity?

    /**
     * 获取所有待同步的项目（modified 或 deleted 状态）
     */
    @Query("SELECT * FROM items WHERE sync_status IN ('modified', 'deleted')")
    suspend fun getPendingSync(): List<ItemEntity>

    /**
     * 获取所有项目（包括已删除）
     */
    @Query("SELECT * FROM items ORDER BY updated_time DESC")
    suspend fun getAll(): List<ItemEntity>

    /**
     * 插入或更新项目
     */
    @Insert(onConflict = OnConflictStrategy.REPLACE)
    suspend fun upsert(item: ItemEntity)

    /**
     * 批量插入或更新
     */
    @Insert(onConflict = OnConflictStrategy.REPLACE)
    suspend fun upsertAll(items: List<ItemEntity>)

    /**
     * 软删除项目
     */
    @Query("UPDATE items SET deleted_time = :time, sync_status = 'deleted', local_rev = local_rev + 1 WHERE id = :id")
    suspend fun softDelete(id: String, time: Long)

    /**
     * 标记为已同步
     */
    @Query("UPDATE items SET sync_status = 'clean', remote_rev = :remoteRev WHERE id = :id")
    suspend fun markSynced(id: String, remoteRev: String)

    /**
     * 更新同步状态
     */
    @Query("UPDATE items SET sync_status = :status, local_rev = local_rev + 1 WHERE id = :id")
    suspend fun updateSyncStatus(id: String, status: String)

    /**
     * 搜索项目（在 payload 中搜索）
     */
    @Query("SELECT * FROM items WHERE type = :type AND deleted_time IS NULL AND payload LIKE '%' || :query || '%' ORDER BY updated_time DESC")
    suspend fun search(query: String, type: String): List<ItemEntity>

    /**
     * 全局搜索（所有类型）
     */
    @Query("SELECT * FROM items WHERE deleted_time IS NULL AND payload LIKE '%' || :query || '%' ORDER BY updated_time DESC")
    suspend fun searchAll(query: String): List<ItemEntity>

    /**
     * 按 folder_id 获取项目（用于笔记、书签等）
     */
    @Query("SELECT * FROM items WHERE type = :type AND deleted_time IS NULL AND payload LIKE '%\"folder_id\":\"' || :folderId || '\"%' ORDER BY updated_time DESC")
    suspend fun getByFolderId(type: String, folderId: String): List<ItemEntity>

    /**
     * 获取根目录项目（folder_id 为 null）
     */
    @Query("SELECT * FROM items WHERE type = :type AND deleted_time IS NULL AND (payload LIKE '%\"folder_id\":null%' OR payload NOT LIKE '%\"folder_id\":%') ORDER BY updated_time DESC")
    suspend fun getRootItems(type: String): List<ItemEntity>

    /**
     * 获取指定时间之后更新的项目
     */
    @Query("SELECT * FROM items WHERE updated_time > :since ORDER BY updated_time ASC")
    suspend fun getUpdatedSince(since: Long): List<ItemEntity>

    /**
     * 物理删除项目（仅用于清理）
     */
    @Query("DELETE FROM items WHERE id = :id")
    suspend fun hardDelete(id: String)

    /**
     * 清理已删除超过指定天数的项目
     */
    @Query("DELETE FROM items WHERE deleted_time IS NOT NULL AND deleted_time < :threshold")
    suspend fun cleanupDeleted(threshold: Long)

    /**
     * 获取项目数量
     */
    @Query("SELECT COUNT(*) FROM items WHERE type = :type AND deleted_time IS NULL")
    suspend fun countByType(type: String): Int
}

/**
 * 单元格右键菜单组件
 */

import React, { useState, useRef, useEffect, useCallback } from 'react';
import { Menu } from 'antd';
import type { MenuProps } from 'antd';
import {
  CopyOutlined,
  ScissorOutlined,
  SnippetsOutlined,
  ClearOutlined,
  MergeCellsOutlined,
  SplitCellsOutlined,
} from '@ant-design/icons';

interface CellContextMenuProps {
  children: React.ReactNode;
  hasSelection: boolean;
  isMerged: boolean;
  onCopy: () => void;
  onCut: () => void;
  onPaste: () => void;
  onClearContent: () => void;
  onClearFormat: () => void;
  onMergeCells: () => void;
  onUnmergeCells: () => void;
}

export const CellContextMenu: React.FC<CellContextMenuProps> = ({
  children,
  hasSelection,
  isMerged,
  onCopy,
  onCut,
  onPaste,
  onClearContent,
  onClearFormat,
  onMergeCells,
  onUnmergeCells,
}) => {
  const [visible, setVisible] = useState(false);
  const [position, setPosition] = useState({ x: 0, y: 0 });
  const menuRef = useRef<HTMLDivElement>(null);

  // 用 ref 存储所有回调，确保菜单点击时调用最新的
  const cbRef = useRef({
    onCopy, onCut, onPaste,
    onClearContent, onClearFormat, onMergeCells, onUnmergeCells,
  });
  cbRef.current = {
    onCopy, onCut, onPaste,
    onClearContent, onClearFormat, onMergeCells, onUnmergeCells,
  };

  const handleContextMenu = useCallback((e: React.MouseEvent) => {
    e.preventDefault();
    e.stopPropagation();
    setPosition({ x: e.clientX, y: e.clientY });
    setVisible(true);
  }, []);

  // 点击菜单外部关闭
  useEffect(() => {
    if (!visible) return;

    const handleMouseDown = (e: MouseEvent) => {
      if (menuRef.current && !menuRef.current.contains(e.target as Node)) {
        setVisible(false);
      }
    };

    // 用 setTimeout 延迟注册，避免当前右键事件立即触发关闭
    const timer = setTimeout(() => {
      document.addEventListener('mousedown', handleMouseDown, true);
    }, 0);

    return () => {
      clearTimeout(timer);
      document.removeEventListener('mousedown', handleMouseDown, true);
    };
  }, [visible]);

  const handleMenuClick: MenuProps['onClick'] = useCallback(({ key }: { key: string }) => {
    console.log('[CellContextMenu] Menu item clicked:', key);
    setVisible(false);
    const cb = cbRef.current;
    switch (key) {
      case 'copy': cb.onCopy(); break;
      case 'cut': cb.onCut(); break;
      case 'paste': cb.onPaste(); break;
      case 'clearContent': cb.onClearContent(); break;
      case 'clearFormat': cb.onClearFormat(); break;
      case 'mergeCells': cb.onMergeCells(); break;
      case 'unmergeCells': cb.onUnmergeCells(); break;
    }
  }, []);

  const menuItems: MenuProps['items'] = [
    { key: 'copy', label: '复制', icon: <CopyOutlined /> },
    { key: 'cut', label: '剪切', icon: <ScissorOutlined /> },
    { key: 'paste', label: '粘贴', icon: <SnippetsOutlined /> },
    { type: 'divider' },
    { key: 'mergeCells', label: '合并单元格', icon: <MergeCellsOutlined />, disabled: !hasSelection || isMerged },
    { key: 'unmergeCells', label: '取消合并', icon: <SplitCellsOutlined />, disabled: !isMerged },
    { type: 'divider' },
    { key: 'clearContent', label: '清除内容', icon: <ClearOutlined /> },
    { key: 'clearFormat', label: '清除格式' },
  ];

  return (
    <div onContextMenu={handleContextMenu} style={{ display: 'contents' }}>
      {children}
      {visible && (
        <div
          ref={menuRef}
          style={{
            position: 'fixed',
            left: position.x,
            top: position.y,
            zIndex: 9999,
            boxShadow: '0 3px 6px -4px rgba(0,0,0,.12), 0 6px 16px 0 rgba(0,0,0,.08), 0 9px 28px 8px rgba(0,0,0,.05)',
            borderRadius: 8,
            background: '#fff',
          }}
        >
          <Menu
            items={menuItems}
            onClick={handleMenuClick}
            style={{ borderRadius: 8, border: 'none' }}
          />
        </div>
      )}
    </div>
  );
};

package com.mucheng.notes.data.repository

import com.mucheng.notes.data.local.dao.ItemDao
import com.mucheng.notes.data.local.entity.ItemEntity
import com.mucheng.notes.domain.model.ItemType
import com.mucheng.notes.domain.repository.ItemRepository
import kotlinx.coroutines.flow.Flow
import java.security.MessageDigest
import java.util.UUID
import javax.inject.Inject
import javax.inject.Singleton

/**
 * ItemRepository 实现
 */
@Singleton
class ItemRepositoryImpl @Inject constructor(
    private val itemDao: ItemDao
) : ItemRepository {

    override fun getByType(type: ItemType): Flow<List<ItemEntity>> {
        return itemDao.getByType(type.value)
    }

    override fun getByTypes(types: List<ItemType>): Flow<List<ItemEntity>> {
        return itemDao.getByTypes(types.map { it.value })
    }

    override suspend fun getById(id: String): ItemEntity? {
        return itemDao.getByIdNotDeleted(id)
    }

    override suspend fun create(type: ItemType, payload: String): ItemEntity {
        val now = System.currentTimeMillis()
        val item = ItemEntity(
            id = UUID.randomUUID().toString(),
            type = type.value,
            createdTime = now,
            updatedTime = now,
            deletedTime = null,
            payload = payload,
            contentHash = computeContentHash(payload),
            syncStatus = "modified",
            localRev = 1,
            remoteRev = null,
            encryptionApplied = 0,
            schemaVersion = 1
        )
        itemDao.upsert(item)
        return item
    }

    override suspend fun update(id: String, payload: String): ItemEntity? {
        val existing = itemDao.getByIdNotDeleted(id) ?: return null

        val updated = existing.copy(
            payload = payload,
            updatedTime = System.currentTimeMillis(),
            contentHash = computeContentHash(payload),
            syncStatus = "modified",
            localRev = existing.localRev + 1
        )
        itemDao.upsert(updated)
        return updated
    }

    override suspend fun softDelete(id: String): Boolean {
        val existing = itemDao.getByIdNotDeleted(id) ?: return false
        itemDao.softDelete(id, System.currentTimeMillis())
        return true
    }

    override suspend fun search(query: String, type: ItemType?): List<ItemEntity> {
        return if (type != null) {
            itemDao.search(query, type.value)
        } else {
            itemDao.searchAll(query)
        }
    }

    override suspend fun getByFolderId(type: ItemType, folderId: String): List<ItemEntity> {
        return itemDao.getByFolderId(type.value, folderId)
    }

    override suspend fun getRootItems(type: ItemType): List<ItemEntity> {
        return itemDao.getRootItems(type.value)
    }

    override suspend fun getPendingSync(): List<ItemEntity> {
        return itemDao.getPendingSync()
    }

    override suspend fun markSynced(id: String, remoteRev: String) {
        itemDao.markSynced(id, remoteRev)
    }

    override suspend fun upsertAll(items: List<ItemEntity>) {
        itemDao.upsertAll(items)
    }

    override suspend fun createWithId(id: String, type: ItemType, payload: String): ItemEntity {
        val now = System.currentTimeMillis()
        val item = ItemEntity(
            id = id,
            type = type.value,
            createdTime = now,
            updatedTime = now,
            deletedTime = null,
            payload = payload,
            contentHash = computeContentHash(payload),
            syncStatus = "modified",
            localRev = 1,
            remoteRev = null,
            encryptionApplied = 0,
            schemaVersion = 1
        )
        itemDao.upsert(item)
        return item
    }

    override suspend fun getByTypeOnce(type: ItemType): List<ItemEntity> {
        return itemDao.getByTypeOnce(type.value)
    }

    /**
     * 计算内容哈希（SHA-256 前 16 字符）
     * 与桌面端保持一致
     */
    private fun computeContentHash(content: String): String {
        val digest = MessageDigest.getInstance("SHA-256")
        val hashBytes = digest.digest(content.toByteArray(Charsets.UTF_8))
        return hashBytes.joinToString("") { "%02x".format(it) }.take(16)
    }
}

import React, { useState } from 'react';
import { Input, Button, Typography, Space, message } from 'antd';
import { LockOutlined, UnlockOutlined } from '@ant-design/icons';

const { Title, Text } = Typography;

interface LockScreenProps {
  onUnlock: (password: string) => Promise<boolean>;
  failedAttempts: number;
  lockedUntil: number | null;
}

const LockScreen: React.FC<LockScreenProps> = ({ onUnlock, failedAttempts, lockedUntil }) => {
  const [password, setPassword] = useState('');
  const [loading, setLoading] = useState(false);

  const isTemporarilyLocked = lockedUntil && Date.now() < lockedUntil;
  const remainingTime = isTemporarilyLocked ? Math.ceil((lockedUntil - Date.now()) / 1000) : 0;

  const handleUnlock = async () => {
    if (!password.trim()) {
      message.warning('请输入密码');
      return;
    }

    setLoading(true);

    // 延迟以防止暴力破解
    await new Promise(resolve => setTimeout(resolve, 500));

    const success = await onUnlock(password);
    setLoading(false);

    if (!success) {
      message.error('密码错误');
      setPassword('');
    }
  };

  const handleKeyPress = (e: React.KeyboardEvent) => {
    if (e.key === 'Enter' && !isTemporarilyLocked) {
      handleUnlock();
    }
  };

  return (
    <div
      style={{
        position: 'fixed',
        top: 0,
        left: 0,
        right: 0,
        bottom: 0,
        background: 'linear-gradient(135deg, #667eea 0%, #764ba2 100%)',
        display: 'flex',
        alignItems: 'center',
        justifyContent: 'center',
        zIndex: 9999,
      }}
    >
      <div
        style={{
          background: 'white',
          borderRadius: 16,
          padding: 40,
          width: 360,
          textAlign: 'center',
          boxShadow: '0 20px 60px rgba(0,0,0,0.3)',
        }}
      >
        <div
          style={{
            width: 80,
            height: 80,
            borderRadius: '50%',
            background: '#f0f0f0',
            display: 'flex',
            alignItems: 'center',
            justifyContent: 'center',
            margin: '0 auto 24px',
          }}
        >
          <LockOutlined style={{ fontSize: 36, color: '#666' }} />
        </div>

        <Title level={3} style={{ marginBottom: 8 }}>
          暮城笔记
        </Title>
        <Text type="secondary" style={{ display: 'block', marginBottom: 24 }}>
          应用已锁定，请输入密码解锁
        </Text>

        {isTemporarilyLocked ? (
          <div style={{ marginBottom: 24 }}>
            <Text type="danger">
              多次密码错误，请等待 {remainingTime} 秒后重试
            </Text>
          </div>
        ) : (
          <Space direction="vertical" style={{ width: '100%' }} size="large">
            <Input.Password
              size="large"
              placeholder="输入密码"
              prefix={<LockOutlined />}
              value={password}
              onChange={e => setPassword(e.target.value)}
              onKeyPress={handleKeyPress}
              autoFocus
            />

            <Button
              type="primary"
              size="large"
              block
              icon={<UnlockOutlined />}
              loading={loading}
              onClick={handleUnlock}
            >
              解锁
            </Button>
          </Space>
        )}

        {failedAttempts > 0 && failedAttempts < 5 && (
          <Text type="secondary" style={{ display: 'block', marginTop: 16, fontSize: 12 }}>
            已失败 {failedAttempts} 次，5 次后将临时锁定
          </Text>
        )}
      </div>
    </div>
  );
};

export default LockScreen;

/**
 * PDF 工具共享工具函数
 */

/**
 * 格式化文件大小
 */
export function formatFileSize(bytes: number): string {
  if (bytes === 0) return '0 B';
  const k = 1024;
  const sizes = ['B', 'KB', 'MB', 'GB'];
  const i = Math.floor(Math.log(bytes) / Math.log(k));
  return parseFloat((bytes / Math.pow(k, i)).toFixed(2)) + ' ' + sizes[i];
}

/**
 * 生成唯一 ID
 */
export function generateId(): string {
  return Math.random().toString(36).substring(2, 9);
}

/**
 * 解析页面范围字符串，如 "1-3,5,7-10"
 */
export function parsePageRanges(rangeStr: string, totalPages: number): number[] {
  const pages: Set<number> = new Set();
  const parts = rangeStr.split(',').map(s => s.trim()).filter(s => s.length > 0);

  for (const part of parts) {
    if (part.includes('-')) {
      const [startStr, endStr] = part.split('-');
      const start = parseInt(startStr, 10);
      const end = parseInt(endStr, 10);

      if (!isNaN(start) && !isNaN(end)) {
        const rangeStart = Math.min(start, end);
        const rangeEnd = Math.max(start, end);
        for (let i = Math.max(1, rangeStart); i <= Math.min(rangeEnd, totalPages); i++) {
          pages.add(i);
        }
      }
    } else {
      const page = parseInt(part, 10);
      if (!isNaN(page) && page >= 1 && page <= totalPages) {
        pages.add(page);
      }
    }
  }

  return Array.from(pages).sort((a, b) => a - b);
}

/**
 * 验证 PDF 文件头
 */
export function validatePdfHeader(arrayBuffer: ArrayBuffer): boolean {
  const header = new Uint8Array(arrayBuffer.slice(0, 5));
  const pdfHeader = String.fromCharCode(...header);
  return pdfHeader.startsWith('%PDF-');
}

/**
 * ArrayBuffer 转 Base64
 */
export function arrayBufferToBase64(buffer: ArrayBuffer): string {
  const bytes = new Uint8Array(buffer);
  let binary = '';
  for (let i = 0; i < bytes.byteLength; i++) {
    binary += String.fromCharCode(bytes[i]);
  }
  return btoa(binary);
}

/**
 * Base64 转 ArrayBuffer
 */
export function base64ToArrayBuffer(base64: string): ArrayBuffer {
  const binary = atob(base64);
  const bytes = new Uint8Array(binary.length);
  for (let i = 0; i < binary.length; i++) {
    bytes[i] = binary.charCodeAt(i);
  }
  return bytes.buffer;
}

/**
 * 下载文件
 */
export function downloadFile(data: ArrayBuffer | Blob, filename: string, mimeType: string = 'application/pdf'): void {
  const blob = data instanceof Blob ? data : new Blob([data], { type: mimeType });
  const url = URL.createObjectURL(blob);
  const a = document.createElement('a');
  a.href = url;
  a.download = filename;
  document.body.appendChild(a);
  a.click();
  document.body.removeChild(a);
  URL.revokeObjectURL(url);
}

/**
 * 批量下载文件（使用延迟避免浏览器阻止）
 */
export async function downloadFilesSequentially(
  files: { data: ArrayBuffer | Blob; filename: string; mimeType?: string }[],
  delayMs: number = 200
): Promise<void> {
  for (let i = 0; i < files.length; i++) {
    const { data, filename, mimeType } = files[i];
    downloadFile(data, filename, mimeType);
    if (i < files.length - 1) {
      await new Promise(resolve => setTimeout(resolve, delayMs));
    }
  }
}

/**
 * Data URL 转 Blob
 */
export function dataURLtoBlob(dataURL: string): Blob {
  const arr = dataURL.split(',');
  const mime = arr[0].match(/:(.*?);/)?.[1] || 'application/octet-stream';
  const bstr = atob(arr[1]);
  let n = bstr.length;
  const u8arr = new Uint8Array(n);
  while (n--) {
    u8arr[n] = bstr.charCodeAt(n);
  }
  return new Blob([u8arr], { type: mime });
}

