/**
 * 主题设置页面
 */
@OptIn(ExperimentalMaterial3Api::class)
@Composable
fun ThemeSettingsScreen(
    navController: NavController,
    viewModel: SettingsViewModel
) {
    val uiState by viewModel.uiState.collectAsState()

    Scaffold(
        topBar = {
            TopAppBar(
                title = { Text(stringResource(R.string.settings_theme)) },
                navigationIcon = {
                    IconButton(onClick = { navController.popBackStack() }) {
                        Icon(Icons.AutoMirrored.Filled.ArrowBack, contentDescription = "返回")
                    }
                }
            )
        }
    ) { paddingValues ->
        // 等待状态初始化完成
        if (!uiState.isInitialized) {
            Box(
                modifier = Modifier
                    .fillMaxSize()
                    .padding(paddingValues),
                contentAlignment = Alignment.Center
            ) {
                CircularProgressIndicator()
            }
            return@Scaffold
        }

        Column(
            modifier = Modifier
                .fillMaxSize()
                .padding(paddingValues)
                .verticalScroll(rememberScrollState())
                .padding(16.dp)
        ) {
            Text(
                "外观",
                style = MaterialTheme.typography.titleMedium,
                color = MaterialTheme.colorScheme.primary
            )

            Spacer(modifier = Modifier.height(16.dp))

            SettingsSwitch(
                title = "跟随系统",
                subtitle = "自动切换深色/浅色模式",
                checked = uiState.followSystemTheme,
                onCheckedChange = { viewModel.setFollowSystemTheme(it) }
            )

            HorizontalDivider(modifier = Modifier.padding(vertical = 8.dp))

            SettingsSwitch(
                title = "深色模式",
                subtitle = "使用深色主题",
                checked = uiState.darkMode,
                onCheckedChange = { viewModel.setDarkMode(it) },
                enabled = !uiState.followSystemTheme
            )

            if (uiState.followSystemTheme) {
                Spacer(modifier = Modifier.height(8.dp))
                Text(
                    "跟随系统时，深色模式设置无效",
                    style = MaterialTheme.typography.bodySmall,
                    color = MaterialTheme.colorScheme.outline
                )
            }
        }
    }
}

@Composable
private fun SettingsSwitch(
    title: String,
    subtitle: String? = null,
    checked: Boolean,
    onCheckedChange: (Boolean) -> Unit,
    enabled: Boolean = true
) {
    Row(
        modifier = Modifier
            .fillMaxWidth()
            .clickable(enabled = enabled) { onCheckedChange(!checked) }
            .padding(vertical = 12.dp),
        verticalAlignment = Alignment.CenterVertically
    ) {
        Column(modifier = Modifier.weight(1f)) {
            Text(
                title,
                style = MaterialTheme.typography.bodyLarge,
                color = if (enabled) MaterialTheme.colorScheme.onSurface else MaterialTheme.colorScheme.outline
            )
            if (subtitle != null) {
                Text(
                    subtitle,
                    style = MaterialTheme.typography.bodySmall,
                    color = MaterialTheme.colorScheme.outline
                )
            }
        }
        Switch(checked = checked, onCheckedChange = onCheckedChange, enabled = enabled)
    }
}

import { useState, useEffect, useCallback } from 'react';
import { ItemBase, DiagramPayload, DiagramType } from '@shared/types';
import { itemsApi } from '../services/itemsApi';

export interface Diagram extends Omit<ItemBase, 'payload'> {
  payload: DiagramPayload;
}

// 解析 ItemBase 为 Diagram
function parseDiagram(item: ItemBase): Diagram {
  const payload = JSON.parse(item.payload) as DiagramPayload;
  return {
    ...item,
    payload: {
      name: payload.name || '未命名图表',
      diagram_type: payload.diagram_type || 'mindmap',
      data: payload.data || '{}',
      thumbnail: payload.thumbnail ?? null,
      folder_id: payload.folder_id ?? null,
    },
  };
}

export function useDiagrams() {
  const [diagrams, setDiagrams] = useState<Diagram[]>([]);
  const [loading, setLoading] = useState(true);

  // 加载所有图表
  const loadDiagrams = useCallback(async () => {
    try {
      const items = await itemsApi.getByType('diagram');
      setDiagrams(items.map(parseDiagram));
    } catch (error) {
      console.error('Failed to load diagrams:', error);
    } finally {
      setLoading(false);
    }
  }, []);

  useEffect(() => {
    loadDiagrams();
  }, [loadDiagrams]);

  // 创建图表
  const createDiagram = useCallback(async (
    name: string,
    diagramType: DiagramType,
    data: string = '{}'
  ): Promise<Diagram | null> => {
    try {
      const payload: DiagramPayload = {
        name,
        diagram_type: diagramType,
        data,
        thumbnail: null,
        folder_id: null,
      };
      const item = await itemsApi.create('diagram', payload);
      if (!item) {
        console.error('Failed to create diagram: API returned null');
        return null;
      }
      const diagram = parseDiagram(item);
      setDiagrams(prev => [diagram, ...prev]);
      return diagram;
    } catch (error) {
      console.error('Failed to create diagram:', error);
      return null;
    }
  }, []);

  // 更新图表
  const updateDiagram = useCallback(async (
    id: string,
    updates: Partial<DiagramPayload>
  ): Promise<boolean> => {
    try {
      const existing = diagrams.find(d => d.id === id);
      if (!existing) return false;

      const newPayload = { ...existing.payload, ...updates };
      const updated = await itemsApi.update(id, newPayload);
      if (updated) {
        setDiagrams(prev => prev.map(d => 
          d.id === id ? parseDiagram(updated) : d
        ));
        return true;
      }
      return false;
    } catch (error) {
      console.error('Failed to update diagram:', error);
      return false;
    }
  }, [diagrams]);

  // 删除图表（软删除）
  const deleteDiagram = useCallback(async (id: string): Promise<boolean> => {
    try {
      const success = await itemsApi.delete(id);
      if (success) {
        setDiagrams(prev => prev.filter(d => d.id !== id));
      }
      return success;
    } catch (error) {
      console.error('Failed to delete diagram:', error);
      return false;
    }
  }, []);

  // 按类型筛选
  const getDiagramsByType = useCallback((type: DiagramType): Diagram[] => {
    return diagrams.filter(d => d.payload.diagram_type === type);
  }, [diagrams]);

  // 获取单个图表
  const getDiagramById = useCallback((id: string): Diagram | undefined => {
    return diagrams.find(d => d.id === id);
  }, [diagrams]);

  return {
    diagrams,
    loading,
    createDiagram,
    updateDiagram,
    deleteDiagram,
    getDiagramsByType,
    getDiagramById,
    refresh: loadDiagrams,
  };
}

/**
 * 图片处理工具函数
 */

// 支持的图片格式
export const SUPPORTED_IMAGE_TYPES = ['image/jpeg', 'image/jpg', 'image/png', 'image/gif', 'image/webp'];

// 最大图片大小（5MB）
export const MAX_IMAGE_SIZE = 5 * 1024 * 1024;

// 最大图片尺寸
export const MAX_IMAGE_DIMENSION = 2048;

/**
 * 验证图片文件
 */
export function validateImage(file: File): { valid: boolean; error?: string } {
  if (!SUPPORTED_IMAGE_TYPES.includes(file.type)) {
    return { valid: false, error: '不支持的图片格式，请使用 JPG、PNG、GIF 或 WebP 格式' };
  }

  if (file.size > MAX_IMAGE_SIZE) {
    return { valid: false, error: '图片大小超过 5MB，请选择更小的图片' };
  }

  return { valid: true };
}

/**
 * 将文件转换为 base64
 */
export function fileToBase64(file: File): Promise<string> {
  return new Promise((resolve, reject) => {
    const reader = new FileReader();
    reader.onload = () => {
      if (typeof reader.result === 'string') {
        resolve(reader.result);
      } else {
        reject(new Error('Failed to read file'));
      }
    };
    reader.onerror = reject;
    reader.readAsDataURL(file);
  });
}

/**
 * 压缩图片
 */
export function compressImage(base64: string, maxWidth: number = MAX_IMAGE_DIMENSION, maxHeight: number = MAX_IMAGE_DIMENSION, quality: number = 0.8): Promise<string> {
  return new Promise((resolve, reject) => {
    const img = new Image();
    img.onload = () => {
      let { width, height } = img;

      // 计算缩放比例
      if (width > maxWidth || height > maxHeight) {
        const ratio = Math.min(maxWidth / width, maxHeight / height);
        width = width * ratio;
        height = height * ratio;
      }

      // 创建 canvas 进行压缩
      const canvas = document.createElement('canvas');
      canvas.width = width;
      canvas.height = height;

      const ctx = canvas.getContext('2d');
      if (!ctx) {
        reject(new Error('Failed to get canvas context'));
        return;
      }

      ctx.drawImage(img, 0, 0, width, height);

      // 转换为 base64
      const compressed = canvas.toDataURL('image/jpeg', quality);
      resolve(compressed);
    };
    img.onerror = reject;
    img.src = base64;
  });
}

/**
 * 从剪贴板获取图片
 */
export async function getImageFromClipboard(event: ClipboardEvent | React.ClipboardEvent): Promise<File | null> {
  const clipboardData = (event as any).clipboardData || (window as any).clipboardData;
  if (!clipboardData) return null;

  // Check for files directly (e.g. copying a file from Explorer)
  if (clipboardData.files && clipboardData.files.length > 0) {
    for (let i = 0; i < clipboardData.files.length; i++) {
      const file = clipboardData.files[i];
      if (file.type.startsWith('image/')) {
        return file;
      }
    }
  }

  // Check items (e.g. screenshot data)
  const items = clipboardData.items;
  if (items) {
    for (let i = 0; i < items.length; i++) {
      const item = items[i];
      if (item.type.indexOf('image') !== -1) {
        const file = item.getAsFile();
        return file;
      }
    }
  }

  return null;
}

/**
 * 获取图片尺寸
 */
export function getImageDimensions(base64: string): Promise<{ width: number; height: number }> {
  return new Promise((resolve, reject) => {
    const img = new Image();
    img.onload = () => {
      resolve({ width: img.width, height: img.height });
    };
    img.onerror = reject;
    img.src = base64;
  });
}

