/**
 * Excel 笔记详情页 - 用于从笔记列表直接打开 Excel 笔记
 */
@OptIn(ExperimentalMaterial3Api::class)
@Composable
fun ExcelDetailScreen(
    noteId: String,
    viewModel: ExcelDetailViewModel = hiltViewModel(),
    onNavigateBack: () -> Unit = {}
) {
    val uiState by viewModel.uiState.collectAsState()

    // 加载指定的 Excel 笔记
    LaunchedEffect(noteId) {
        viewModel.loadNote(noteId)
    }

    // 错误提示
    uiState.error?.let { error ->
        LaunchedEffect(error) {
            viewModel.clearError()
        }
    }

    val note = uiState.note
    val currentSheet = note?.payload?.sheets?.getOrNull(uiState.selectedSheetIndex)

    Scaffold(
        topBar = {
            TopAppBar(
                title = { Text(note?.payload?.title?.ifEmpty { "未命名" } ?: "加载中...") },
                navigationIcon = {
                    IconButton(onClick = onNavigateBack) {
                        Icon(Icons.Default.ArrowBack, contentDescription = "返回")
                    }
                }
            )
        },
        bottomBar = {
            // 工作表标签
            if (note != null && note.payload.sheets.isNotEmpty()) {
                Surface(tonalElevation = 2.dp) {
                    LazyRow(
                        modifier = Modifier
                            .fillMaxWidth()
                            .padding(8.dp),
                        horizontalArrangement = Arrangement.spacedBy(8.dp)
                    ) {
                        itemsIndexed(note.payload.sheets) { index, sheet ->
                            FilterChip(
                                selected = index == uiState.selectedSheetIndex,
                                onClick = { viewModel.selectSheet(index) },
                                label = { Text(sheet.name) }
                            )
                        }
                    }
                }
            }
        }
    ) { paddingValues ->
        Box(
            modifier = Modifier
                .fillMaxSize()
                .padding(paddingValues)
        ) {
            when {
                uiState.isLoading -> {
                    CircularProgressIndicator(modifier = Modifier.align(Alignment.Center))
                }
                note == null -> {
                    Column(
                        modifier = Modifier.align(Alignment.Center),
                        horizontalAlignment = Alignment.CenterHorizontally
                    ) {
                        Icon(
                            Icons.Default.Error,
                            contentDescription = null,
                            modifier = Modifier.size(64.dp),
                            tint = MaterialTheme.colorScheme.error
                        )
                        Spacer(modifier = Modifier.height(16.dp))
                        Text(
                            text = "无法加载笔记",
                            style = MaterialTheme.typography.bodyLarge,
                            color = MaterialTheme.colorScheme.error
                        )
                    }
                }
                currentSheet != null -> {
                    SpreadsheetView(
                        sheet = currentSheet,
                        selectedCell = uiState.selectedCell,
                        onCellSelect = { row, col -> viewModel.selectCell(row, col) },
                        onCellChange = { _, _, _ -> },
                        getCellDisplayValue = { row, col ->
                            viewModel.getCellDisplayValue(currentSheet, row, col)
                        }
                    )
                }
                else -> {
                    Text(
                        text = "无工作表",
                        modifier = Modifier.align(Alignment.Center),
                        color = MaterialTheme.colorScheme.outline
                    )
                }
            }
        }
    }
}

import React, { useState } from 'react';
import { Input, Button, message } from 'antd';
import { LockOutlined, KeyOutlined } from '@ant-design/icons';

interface VaultLockScreenProps {
  onUnlock: () => void;
  onSetPassword?: () => void;
  hasPassword: boolean;
}

// 密码哈希函数
const hashPassword = async (password: string): Promise<string> => {
  const encoder = new TextEncoder();
  const data = encoder.encode(password + 'mucheng-salt-2024');
  const hashBuffer = await crypto.subtle.digest('SHA-256', data);
  const hashArray = Array.from(new Uint8Array(hashBuffer));
  return hashArray.map(b => b.toString(16).padStart(2, '0')).join('');
};

const VaultLockScreen: React.FC<VaultLockScreenProps> = ({ onUnlock, onSetPassword, hasPassword }) => {
  const [password, setPassword] = useState('');
  const [loading, setLoading] = useState(false);

  const handleUnlock = async () => {
    if (!password) {
      message.warning('请输入密码');
      return;
    }

    setLoading(true);

    // 延迟以防止暴力破解
    await new Promise(resolve => setTimeout(resolve, 300));

    // 验证密码（使用哈希比较）
    const savedPassword = localStorage.getItem('mucheng-vault-password');
    const hashedInput = await hashPassword(password);

    if (hashedInput === savedPassword) {
      message.success('密码库已解锁');
      onUnlock();
    } else {
      message.error('密码错误');
    }

    setLoading(false);
    setPassword('');
  };

  const handleKeyPress = (e: React.KeyboardEvent) => {
    if (e.key === 'Enter') {
      handleUnlock();
    }
  };

  if (!hasPassword) {
    return (
      <div style={{
        display: 'flex',
        flexDirection: 'column',
        alignItems: 'center',
        justifyContent: 'center',
        height: '100%',
        background: '#fafafa',
        padding: 40,
      }}>
        <KeyOutlined style={{ fontSize: 64, color: '#1890ff', marginBottom: 24 }} />
        <h2 style={{ margin: '0 0 16px', color: '#333' }}>密码库</h2>
        <p style={{ color: '#666', marginBottom: 24, textAlign: 'center' }}>
          您尚未设置密码库密码<br />
          设置密码后可以保护您的敏感数据
        </p>
        <Button type="primary" onClick={onSetPassword}>
          设置密码库密码
        </Button>
      </div>
    );
  }

  return (
    <div style={{
      display: 'flex',
      flexDirection: 'column',
      alignItems: 'center',
      justifyContent: 'center',
      height: '100%',
      background: '#fafafa',
      padding: 40,
    }}>
      <LockOutlined style={{ fontSize: 64, color: '#1890ff', marginBottom: 24 }} />
      <h2 style={{ margin: '0 0 8px', color: '#333' }}>密码库已锁定</h2>
      <p style={{ color: '#666', marginBottom: 24 }}>请输入密码以访问密码库</p>

      <div style={{ width: 280 }}>
        <Input.Password
          size="large"
          placeholder="输入密码库密码"
          prefix={<LockOutlined style={{ color: '#bfbfbf' }} />}
          value={password}
          onChange={e => setPassword(e.target.value)}
          onKeyPress={handleKeyPress}
          autoFocus
          style={{ marginBottom: 16 }}
        />
        <Button 
          type="primary" 
          size="large" 
          block 
          onClick={handleUnlock}
          loading={loading}
        >
          解锁
        </Button>
      </div>

      <p style={{ color: '#999', fontSize: 12, marginTop: 24 }}>
        密码库密码可在设置 → 安全设置中修改
      </p>
    </div>
  );
};

