import { useState, useEffect, useCallback } from 'react';
import { ItemBase, FolderPayload } from '@shared/types';
import { foldersApi, parsePayload } from '../services/itemsApi';

export interface Folder {
  id: string;
  name: string;
  parentId: string | null;
  icon: string | null;
  color: string | null;
  createdAt: number;
  updatedAt: number;
}

function itemToFolder(item: ItemBase): Folder {
  const payload = parsePayload<FolderPayload>(item);
  return {
    id: item.id,
    name: payload.name || '未命名文件夹',
    parentId: payload.parent_id ?? null,
    icon: payload.icon ?? null,
    color: payload.color ?? null,
    createdAt: item.created_time,
    updatedAt: item.updated_time,
  };
}

export function useFolders() {
  const [folders, setFolders] = useState<Folder[]>([]);
  const [loading, setLoading] = useState(true);

  const loadFolders = useCallback(async () => {
    try {
      setLoading(true);
      const items = await foldersApi.getAll();
      if (items) {
        setFolders(items.map(itemToFolder));
      }
    } finally {
      setLoading(false);
    }
  }, []);

  useEffect(() => {
    loadFolders();
  }, [loadFolders]);

  // 监听同步完成事件，刷新文件夹列表
  useEffect(() => {
    const handleSyncCompleted = () => { loadFolders(); };
    window.addEventListener('sync-completed', handleSyncCompleted);
    return () => { window.removeEventListener('sync-completed', handleSyncCompleted); };
  }, [loadFolders]);

  const createFolder = useCallback(async (name: string, parentId: string | null = null) => {
    const payload: FolderPayload = {
      name,
      parent_id: parentId,
      icon: null,
      color: null,
    };
    const item = await foldersApi.create(payload);
    if (item) {
      await loadFolders();
      return itemToFolder(item);
    }
    return null;
  }, [loadFolders]);

  const updateFolder = useCallback(async (id: string, updates: Partial<FolderPayload>) => {
    const folder = folders.find(f => f.id === id);
    if (!folder) return null;

    const payload: FolderPayload = {
      name: updates.name ?? folder.name,
      parent_id: updates.parent_id ?? folder.parentId,
      icon: updates.icon ?? folder.icon,
      color: updates.color ?? folder.color,
    };

    const item = await foldersApi.update(id, payload);
    if (item) {
      await loadFolders();
      return itemToFolder(item);
    }
    return null;
  }, [folders, loadFolders]);

  const deleteFolder = useCallback(async (id: string) => {
    const success = await foldersApi.delete(id);
    if (success) {
      await loadFolders();
    }
    return success;
  }, [loadFolders]);

  // 构建文件夹树结构
  const folderTree = useCallback(() => {
    const rootFolders = folders.filter((f: Folder) => f.parentId === null);
    const getChildren = (parentId: string): Folder[] => {
      return folders.filter((f: Folder) => f.parentId === parentId);
    };

    const buildTree = (folder: Folder): Folder & { children: (Folder & { children: unknown[] })[] } => ({
      ...folder,
      children: getChildren(folder.id).map(buildTree),
    });

    return rootFolders.map(buildTree);
  }, [folders]);

  return {
    folders,
    folderTree,
    loading,
    createFolder,
    updateFolder,
    deleteFolder,
    refresh: loadFolders,
  };
}

import bcrypt from 'bcrypt';
import crypto from 'crypto';

// bcrypt 哈希轮数（至少10轮）
const BCRYPT_ROUNDS = 10;

/**
 * 使用 bcrypt 对密码进行哈希
 * @param password 明文密码
 * @returns 哈希后的密码
 */
export async function hashPassword(password: string): Promise<string> {
  return bcrypt.hash(password, BCRYPT_ROUNDS);
}

/**
 * 验证密码是否匹配
 * @param password 明文密码
 * @param hash 存储的哈希值
 * @returns 是否匹配
 */
export async function verifyPassword(password: string, hash: string): Promise<boolean> {
  return bcrypt.compare(password, hash);
}

/**
 * 计算同步密钥的 SHA-256 指纹
 * @param syncKey 同步密钥
 * @returns 十六进制指纹
 */
export function computeSyncKeyFingerprint(syncKey: string): string {
  return crypto.createHash('sha256').update(syncKey).digest('hex');
}

/**
 * 计算刷新令牌的哈希值
 * @param token 刷新令牌
 * @returns 十六进制哈希
 */
export function hashRefreshToken(token: string): string {
  return crypto.createHash('sha256').update(token).digest('hex');
}

/**
 * 生成随机 ID
 * @param length 字节长度（默认16，生成32字符的十六进制字符串）
 * @returns 随机十六进制字符串
 */
export function generateId(length: number = 16): string {
  return crypto.randomBytes(length).toString('hex');
}

/**
 * 生成随机令牌
 * @param length 字节长度（默认32，生成64字符的十六进制字符串）
 * @returns 随机十六进制字符串
 */
export function generateToken(length: number = 32): string {
  return crypto.randomBytes(length).toString('hex');
}

/**
 * 验证密码强度
 * @param password 密码
 * @returns 验证结果
 */
export function validatePasswordStrength(password: string): { valid: boolean; error?: string } {
  if (password.length < 8) {
    return { valid: false, error: '密码长度至少8个字符' };
  }
  if (password.length > 128) {
    return { valid: false, error: '密码长度不能超过128个字符' };
  }
  // 检查是否包含至少一个数字
  if (!/\d/.test(password)) {
    return { valid: false, error: '密码必须包含至少一个数字' };
  }
  // 检查是否包含至少一个字母
  if (!/[a-zA-Z]/.test(password)) {
    return { valid: false, error: '密码必须包含至少一个字母' };
  }
  // 检查常见弱密码
  const weakPasswords = [
    'password', '12345678', '123456789', 'qwerty123', 'admin123',
    'password1', 'password123', 'abc12345', 'letmein1', 'welcome1'
  ];
  if (weakPasswords.includes(password.toLowerCase())) {
    return { valid: false, error: '密码过于简单，请使用更复杂的密码' };
  }
  return { valid: true };
}

/**
 * 验证同步密钥长度
 * @param syncKey 同步密钥
 * @returns 验证结果
 */
export function validateSyncKeyLength(syncKey: string): { valid: boolean; error?: string } {
  if (syncKey.length < 16) {
    return { valid: false, error: '同步密钥长度至少16个字符' };
  }
  return { valid: true };
}

/**
 * 验证用户名格式
 * @param username 用户名
 * @returns 验证结果
 */
export function validateUsername(username: string): { valid: boolean; error?: string } {
  if (username.length < 3) {
    return { valid: false, error: '用户名长度至少3个字符' };
  }
  if (username.length > 32) {
    return { valid: false, error: '用户名长度不能超过32个字符' };
  }
  if (!/^[a-zA-Z0-9_-]+$/.test(username)) {
    return { valid: false, error: '用户名只能包含字母、数字、下划线和连字符' };
  }
  return { valid: true };
}

package com.mucheng.notes.security

import android.content.Context
import android.content.SharedPreferences
import androidx.security.crypto.EncryptedSharedPreferences
import androidx.security.crypto.MasterKey

/**
 * 同步相关敏感信息的安全存储。
 * 会自动迁移历史明文 SharedPreferences 中的值，并删除旧明文。
 */
object SecureSyncStorage {
    private const val PREFS_NAME = "secure_sync_prefs"
    private val legacyPrefsNames = listOf("app_settings", "sync_config")

    private fun getPrefs(context: Context): SharedPreferences {
        return try {
            val masterKey = MasterKey.Builder(context)
                .setKeyScheme(MasterKey.KeyScheme.AES256_GCM)
                .build()

            EncryptedSharedPreferences.create(
                context,
                PREFS_NAME,
                masterKey,
                EncryptedSharedPreferences.PrefKeyEncryptionScheme.AES256_SIV,
                EncryptedSharedPreferences.PrefValueEncryptionScheme.AES256_GCM
            )
        } catch (e: Exception) {
            android.util.Log.e("SecureSyncStorage", "Falling back to local prefs: ${e.message}")
            context.getSharedPreferences(PREFS_NAME, Context.MODE_PRIVATE)
        }
    }

    fun getString(context: Context, key: String): String? {
        val prefs = getPrefs(context)
        if (prefs.contains(key)) {
            return prefs.getString(key, null)
        }

        for (prefsName in legacyPrefsNames) {
            val legacyPrefs = context.getSharedPreferences(prefsName, Context.MODE_PRIVATE)
            if (!legacyPrefs.contains(key)) {
                continue
            }

            val value = legacyPrefs.getString(key, null)
            if (value != null) {
                prefs.edit().putString(key, value).apply()
            }
            legacyPrefs.edit().remove(key).apply()
            return value
        }

        return null
    }

    fun getLong(context: Context, key: String): Long? {
        val prefs = getPrefs(context)
        if (prefs.contains(key)) {
            return prefs.getLong(key, 0L)
        }

        for (prefsName in legacyPrefsNames) {
            val legacyPrefs = context.getSharedPreferences(prefsName, Context.MODE_PRIVATE)
            if (!legacyPrefs.contains(key)) {
                continue
            }

            val value = legacyPrefs.getLong(key, 0L)
            prefs.edit().putLong(key, value).apply()
            legacyPrefs.edit().remove(key).apply()
            return value
        }

        return null
    }

    fun putString(context: Context, key: String, value: String?) {
        val prefs = getPrefs(context)
        prefs.edit().apply {
            if (value == null) remove(key) else putString(key, value)
        }.apply()
        clearLegacy(context, key)
    }

    fun putLong(context: Context, key: String, value: Long?) {
        val prefs = getPrefs(context)
        prefs.edit().apply {
            if (value == null) remove(key) else putLong(key, value)
        }.apply()
        clearLegacy(context, key)
    }

    fun remove(context: Context, vararg keys: String) {
        val prefs = getPrefs(context)
        prefs.edit().apply {
            keys.forEach { remove(it) }
        }.apply()

        keys.forEach { key ->
            clearLegacy(context, key)
        }
    }

    private fun clearLegacy(context: Context, key: String) {
        legacyPrefsNames.forEach { prefsName ->
            context.getSharedPreferences(prefsName, Context.MODE_PRIVATE)
                .edit()
                .remove(key)
                .apply()
        }
    }
}

package com.mucheng.notes.data.repository

import android.content.Context
import com.mucheng.notes.data.sync.SyncEngine
import com.mucheng.notes.domain.model.SyncConfig
import com.mucheng.notes.domain.model.SyncModules
import com.mucheng.notes.domain.model.SyncResult
import com.mucheng.notes.domain.model.SyncStatus
import com.mucheng.notes.domain.repository.SyncRepository
import com.mucheng.notes.security.SecureSyncStorage
import dagger.hilt.android.qualifiers.ApplicationContext
import kotlinx.coroutines.flow.Flow
import kotlinx.coroutines.flow.MutableStateFlow
import kotlinx.coroutines.flow.asStateFlow
import javax.inject.Inject
import javax.inject.Singleton

/**
 * SyncRepository 实现
 */
@Singleton
class SyncRepositoryImpl @Inject constructor(
    private val syncEngine: SyncEngine,
    @ApplicationContext private val context: Context
) : SyncRepository {

    private val _syncStatus = MutableStateFlow(SyncStatus.IDLE)

    override suspend fun sync(): SyncResult {
        _syncStatus.value = SyncStatus.SYNCING

        // 在同步前从 SharedPreferences 加载配置并设置到 SyncEngine
        // 这样无论从哪里调用 sync()，都能正确加载配置
        val config = loadSyncConfig()
        if (config == null) {
            _syncStatus.value = SyncStatus.FAILED
            return SyncResult(error = "同步未配置")
        }

        if (!config.enabled) {
            _syncStatus.value = SyncStatus.FAILED
            return SyncResult(error = "同步已禁用")
        }

        // 设置配置到 SyncEngine（会初始化适配器和 token）
        syncEngine.setConfig(config)

        val result = syncEngine.sync()

        _syncStatus.value = if (result.success) {
            SyncStatus.SUCCESS
        } else {
            SyncStatus.FAILED
        }

        return result
    }

    /**
     * 从 SharedPreferences 加载同步配置
     */
    private fun loadSyncConfig(): SyncConfig? {
        val prefs = context.getSharedPreferences("app_settings", Context.MODE_PRIVATE)

        val syncEnabled = prefs.getBoolean("sync_enabled", false)
        val syncType = prefs.getString("sync_type", "webdav") ?: "webdav"
        val webdavUrl = prefs.getString("webdav_url", "") ?: ""

        if (webdavUrl.isBlank()) {
            return null
        }

        // 加载同步模块配置
        val syncModules = SyncModules(
            notes = prefs.getBoolean("sync_notes", true),
            bookmarks = prefs.getBoolean("sync_bookmarks", true),
            vault = prefs.getBoolean("sync_vault", true),
            diagrams = prefs.getBoolean("sync_diagrams", true),
            todos = prefs.getBoolean("sync_todos", true),
            ai = prefs.getBoolean("sync_ai", true)
        )

        return SyncConfig(
            enabled = syncEnabled,
            type = syncType,
            url = webdavUrl,
            syncPath = prefs.getString("sync_path", "/mucheng-notes") ?: "/mucheng-notes",
            username = prefs.getString("username", null),
            password = SecureSyncStorage.getString(context, "password"),
            apiKey = prefs.getString("api_key", null),
            syncModules = syncModules,
            // 自建服务器认证信息
            serverUsername = prefs.getString("server_username", null),
            serverPassword = SecureSyncStorage.getString(context, "server_password"),
            serverSyncKey = SecureSyncStorage.getString(context, "server_sync_key"),
            serverToken = SecureSyncStorage.getString(context, "server_token"),
            serverRefreshToken = SecureSyncStorage.getString(context, "server_refresh_token"),
            serverTokenExpires = SecureSyncStorage.getLong(context, "server_token_expires")?.takeIf { it > 0 }
        )
    }

    override suspend fun getSyncStatus(): SyncStatus {
        return _syncStatus.value
    }

    override fun observeSyncStatus(): Flow<SyncStatus> {
        return _syncStatus.asStateFlow()
    }
}

import { Router } from 'express';
import { ResourceService } from '../services/ResourceService';
import { createError } from '../middleware/errorHandler';
import { config } from '../config';

const router = Router();

// GET /api/resources/:id - 下载资源
router.get('/:id', (req, res, next) => {
  try {
    const resourceService = new ResourceService(req.userId);
    const data = resourceService.getResource(req.params.id);

    if (!data) {
      throw createError('Resource not found', 404);
    }

    // 设置默认 Content-Type
    res.setHeader('Content-Type', 'application/octet-stream');
    res.send(data);
  } catch (error) {
    next(error);
  }
});

// PUT /api/resources/:id - 上传资源
router.put('/:id', (req, res, next) => {
  try {
    // 检查文件大小
    const contentLength = parseInt(req.headers['content-length'] || '0', 10);
    if (contentLength > config.maxResourceSize) {
      throw createError(`Resource size exceeds limit (${config.maxResourceSize} bytes)`, 413);
    }

    const chunks: Buffer[] = [];
    let receivedBytes = 0;
    let rejected = false;

    req.on('data', (chunk: Buffer) => {
      if (rejected) {
        return;
      }

      receivedBytes += chunk.length;
      if (receivedBytes > config.maxResourceSize) {
        rejected = true;
        chunks.length = 0;
        res.status(413).json({ error: `Resource size exceeds limit (${config.maxResourceSize} bytes)` });
        req.destroy();
        return;
      }

      chunks.push(chunk);
    });

    req.on('end', () => {
      try {
        if (rejected || res.headersSent) {
          return;
        }

        const data = Buffer.concat(chunks);

        if (data.length > config.maxResourceSize) {
          res.status(413).json({ error: `Resource size exceeds limit (${config.maxResourceSize} bytes)` });
          return;
        }

        const resourceService = new ResourceService(req.userId);
        const saved = resourceService.putResource(req.params.id, data);
        if (!saved) {
          next(createError('Resource item not found or access denied', 404));
          return;
        }
        res.json({ success: true });
      } catch (error) {
        next(error);
      }
    });

    req.on('error', (error) => {
      if (rejected || res.headersSent) {
        return;
      }
      next(error);
    });
  } catch (error) {
    next(error);
  }
});

// DELETE /api/resources/:id - 删除资源
router.delete('/:id', (req, res, next) => {
  try {
    const resourceService = new ResourceService(req.userId);
    const deleted = resourceService.deleteResource(req.params.id);

    if (!deleted) {
      throw createError('Resource not found', 404);
    }

    res.json({ success: true });
  } catch (error) {
    next(error);
  }
});

export default router;

/**
 * 公式栏组件
 * 显示当前单元格地址和内容/公式
 */

import React, { useState, useEffect, useRef } from 'react';
import { Input } from 'antd';
import { FunctionOutlined } from '@ant-design/icons';

interface FormulaBarProps {
  cellAddress: string;
  value: string;
  formula: string | null;
  onChange: (value: string) => void;
  onCommit: () => void;
  onCancel: () => void;
}

export const FormulaBar: React.FC<FormulaBarProps> = ({
  cellAddress,
  value,
  formula,
  onChange,
  onCommit,
  onCancel,
}) => {
  const [isEditing, setIsEditing] = useState(false);
  const [editValue, setEditValue] = useState('');
  const inputRef = useRef<any>(null);

  // 当选中单元格变化时，更新显示值
  useEffect(() => {
    setEditValue(formula || String(value ?? ''));
    setIsEditing(false);
  }, [cellAddress, value, formula]);

  const handleFocus = () => {
    setIsEditing(true);
  };

  const handleChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    setEditValue(e.target.value);
    onChange(e.target.value);
  };

  const handleKeyDown = (e: React.KeyboardEvent) => {
    if (e.key === 'Enter') {
      e.preventDefault();
      onCommit();
      setIsEditing(false);
    } else if (e.key === 'Escape') {
      e.preventDefault();
      setEditValue(formula || String(value ?? ''));
      onCancel();
      setIsEditing(false);
    }
  };

  const handleBlur = () => {
    if (isEditing) {
      onCommit();
      setIsEditing(false);
    }
  };

  return (
    <div className="formula-bar" style={{
      display: 'flex',
      alignItems: 'center',
      padding: '4px 12px',
      borderBottom: '1px solid #e8e8e8',
      background: '#fff',
      gap: 8,
    }}>
      {/* 单元格地址 */}
      <div style={{
        minWidth: 60,
        padding: '4px 8px',
        background: '#f5f5f5',
        border: '1px solid #d9d9d9',
        borderRadius: 4,
        fontFamily: 'monospace',
        fontSize: 13,
        textAlign: 'center',
      }}>
        {cellAddress || 'A1'}
      </div>

      {/* 公式图标 */}
      <FunctionOutlined style={{ color: '#666', fontSize: 16 }} />

      {/* 公式/值输入框 */}
      <Input
        ref={inputRef}
        value={editValue}
        onChange={handleChange}
        onFocus={handleFocus}
        onBlur={handleBlur}
        onKeyDown={handleKeyDown}
        placeholder="输入值或公式（以 = 开头）"
        style={{ flex: 1 }}
        size="small"
      />
    </div>
  );
};

