import { app, safeStorage } from 'electron';
import * as fs from 'fs';
import * as path from 'path';

const SENSITIVE_KEYS = [
  'password',
  'api_key',
  'server_password',
  'server_sync_key',
  'server_token',
  'server_refresh_token',
] as const;

type SyncConfigRecord = Record<string, any>;

function getSyncConfigPath(): string {
  return path.join(app.getPath('userData'), 'sync-config.json');
}

function encryptValue(value: string): string {
  if (!safeStorage.isEncryptionAvailable()) {
    return value;
  }

  const encrypted = safeStorage.encryptString(value);
  return `enc:${encrypted.toString('base64')}`;
}

function decryptValue(value: string): string | undefined {
  if (!value.startsWith('enc:')) {
    return value;
  }

  if (!safeStorage.isEncryptionAvailable()) {
    console.warn('[SyncConfigStorage] Encryption unavailable, cannot decrypt stored sync secret');
    return undefined;
  }

  try {
    const encrypted = Buffer.from(value.slice(4), 'base64');
    return safeStorage.decryptString(encrypted);
  } catch (error) {
    console.error('[SyncConfigStorage] Failed to decrypt sync secret:', error);
    return undefined;
  }
}

export function saveSyncConfig(config: SyncConfigRecord): boolean {
  const syncConfigPath = getSyncConfigPath();
  const persistedConfig: SyncConfigRecord = { ...config };

  for (const key of SENSITIVE_KEYS) {
    const value = persistedConfig[key];
    if (typeof value === 'string' && value.length > 0) {
      persistedConfig[key] = encryptValue(value);
    }
  }

  fs.writeFileSync(syncConfigPath, JSON.stringify(persistedConfig, null, 2), 'utf8');
  return true;
}

export function loadSyncConfig(): SyncConfigRecord | null {
  const syncConfigPath = getSyncConfigPath();
  if (!fs.existsSync(syncConfigPath)) {
    return null;
  }

  const content = fs.readFileSync(syncConfigPath, 'utf8');
  const config = JSON.parse(content) as SyncConfigRecord;
  let requiresRewrite = false;

  for (const key of SENSITIVE_KEYS) {
    const value = config[key];
    if (typeof value !== 'string' || value.length === 0) {
      continue;
    }

    if (!value.startsWith('enc:')) {
      requiresRewrite = true;
    }

    config[key] = decryptValue(value);
  }

  if (requiresRewrite) {
    try {
      saveSyncConfig(config);
    } catch (error) {
      console.warn('[SyncConfigStorage] Failed to rewrite sync config after secret migration:', error);
    }
  }

  return config;
}

import { safeStorage } from 'electron';
import * as crypto from 'crypto';

const ENCRYPTED_PREFIX = 'mcenc:v1:';
const FALLBACK_KEY_SEED = 'mucheng-notes-local-payload-fallback-v1';
const ALGORITHM = 'aes-256-gcm';
const IV_LENGTH = 12;
const AUTH_TAG_LENGTH = 16;

export function isLocalPayloadEncrypted(payload: string): boolean {
  return payload.startsWith(ENCRYPTED_PREFIX);
}

function getFallbackKey(): Buffer {
  return crypto.createHash('sha256').update(FALLBACK_KEY_SEED).digest();
}

function isSafeStorageAvailable(): boolean {
  return Boolean(safeStorage?.isEncryptionAvailable?.());
}

function encryptWithFallback(plaintext: string): string {
  const iv = crypto.randomBytes(IV_LENGTH);
  const cipher = crypto.createCipheriv(ALGORITHM, getFallbackKey(), iv, {
    authTagLength: AUTH_TAG_LENGTH,
  });
  const ciphertext = Buffer.concat([cipher.update(plaintext, 'utf8'), cipher.final()]);
  return JSON.stringify({
    mode: 'fallback-aes-256-gcm',
    iv: iv.toString('base64'),
    authTag: cipher.getAuthTag().toString('base64'),
    ciphertext: ciphertext.toString('base64'),
  });
}

function decryptWithFallback(encoded: string): string {
  const data = JSON.parse(encoded) as {
    iv: string;
    authTag: string;
    ciphertext: string;
  };
  const decipher = crypto.createDecipheriv(
    ALGORITHM,
    getFallbackKey(),
    Buffer.from(data.iv, 'base64'),
    { authTagLength: AUTH_TAG_LENGTH }
  );
  decipher.setAuthTag(Buffer.from(data.authTag, 'base64'));
  return Buffer.concat([
    decipher.update(Buffer.from(data.ciphertext, 'base64')),
    decipher.final(),
  ]).toString('utf8');
}

export function encryptLocalPayload(payload: string): string {
  if (isLocalPayloadEncrypted(payload)) {
    return payload;
  }

  if (isSafeStorageAvailable()) {
    const encrypted = safeStorage.encryptString(payload);
    return `${ENCRYPTED_PREFIX}safe:${encrypted.toString('base64')}`;
  }

  return `${ENCRYPTED_PREFIX}fallback:${Buffer.from(encryptWithFallback(payload), 'utf8').toString('base64')}`;
}

export function decryptLocalPayload(payload: string): string {
  if (!isLocalPayloadEncrypted(payload)) {
    return payload;
  }

  const encoded = payload.slice(ENCRYPTED_PREFIX.length);
  const separator = encoded.indexOf(':');
  if (separator <= 0) {
    throw new Error('Invalid encrypted local payload format');
  }

  const mode = encoded.slice(0, separator);
  const data = encoded.slice(separator + 1);

  if (mode === 'safe') {
    if (!isSafeStorageAvailable()) {
      throw new Error('Local payload encryption is unavailable on this system');
    }
    return safeStorage.decryptString(Buffer.from(data, 'base64'));
  }

  if (mode === 'fallback') {
    return decryptWithFallback(Buffer.from(data, 'base64').toString('utf8'));
  }

  throw new Error(`Unsupported encrypted local payload mode: ${mode}`);
}

