import { Router } from 'express';
import { ChangeService } from '../services/ChangeService';
import { createError } from '../middleware/errorHandler';

const router = Router();

// GET /api/changes/cursor-check - 检查游标是否已过期
router.get('/cursor-check', (req, res, next) => {
  try {
    const cursor = req.query.cursor as string | undefined;
    if (!cursor) {
      return res.json({ expired: false });
    }

    const changeService = new ChangeService();
    const expired = changeService.isCursorExpired(cursor, req.userId);
    res.json({ expired });
  } catch (error) {
    next(error);
  }
});

// GET /api/changes - 获取变更列表
router.get('/', (req, res, next) => {
  try {
    const changeService = new ChangeService();
    const cursor = req.query.cursor as string | undefined;
    const requestedLimit = req.query.limit ? parseInt(req.query.limit as string, 10) : 100;
    const limit = Math.min(Math.max(Number.isFinite(requestedLimit) ? requestedLimit : 100, 1), 500);

    const result = changeService.listChanges(cursor, limit, req.userId);

    // 记录变更查询详情
    console.log(JSON.stringify({
      timestamp: new Date().toISOString(),
      level: 'info',
      message: 'Changes GET',
      userId: req.userId,
      cursor: cursor || 'null',
      limit,
      changesCount: result.changes.length,
      hasMore: result.hasMore,
      nextCursor: result.nextCursor,
    }));

    res.json(result);
  } catch (error) {
    next(error);
  }
});

// DELETE /api/changes - 清理过期变更
router.delete('/', (req, res, next) => {
  try {
    const before = req.query.before as string | undefined;

    if (!before) {
      throw createError('Missing required parameter: before', 400);
    }

    const changeService = new ChangeService();
    const deleted = changeService.cleanupBefore(parseInt(before, 10), req.userId);
    res.json({ deleted });
  } catch (error) {
    next(error);
  }
});

export default router;

import { useState, useEffect, useCallback } from 'react';
import { FeatureSettings } from '@shared/types';

const FEATURE_SETTINGS_KEY = 'mucheng-feature-settings';

const DEFAULT_SETTINGS: FeatureSettings = {
  ai_enabled: false,
  todo_enabled: true,
  vault_enabled: true,
  bookmark_enabled: true,
  toolbox_enabled: true,
  diagram_enabled: true,
  transfer_enabled: true,
  excel_enabled: true,
};

function getSettings(): FeatureSettings {
  const saved = localStorage.getItem(FEATURE_SETTINGS_KEY);
  if (saved) {
    try {
      return { ...DEFAULT_SETTINGS, ...JSON.parse(saved) };
    } catch { /* ignore */ }
  }
  return DEFAULT_SETTINGS;
}

function saveSettings(settings: FeatureSettings): void {
  localStorage.setItem(FEATURE_SETTINGS_KEY, JSON.stringify(settings));
  // 触发自定义事件通知其他组件
  window.dispatchEvent(new Event('feature-settings-updated'));
}

export function useFeatureSettings() {
  const [settings, setSettings] = useState<FeatureSettings>(() => getSettings());

  // 监听设置变化
  useEffect(() => {
    const handleUpdate = () => {
      setSettings(getSettings());
    };

    window.addEventListener('feature-settings-updated', handleUpdate);
    window.addEventListener('storage', (e) => {
      if (e.key === FEATURE_SETTINGS_KEY) handleUpdate();
    });

    return () => {
      window.removeEventListener('feature-settings-updated', handleUpdate);
    };
  }, []);

  const updateSettings = useCallback((updates: Partial<FeatureSettings>) => {
    setSettings(prev => {
      const newSettings = { ...prev, ...updates };
      saveSettings(newSettings);
      return newSettings;
    });
  }, []);

  return {
    settings,
    updateSettings,
  };
}

import { Request, Response, NextFunction } from 'express';
import { config } from '../config';

type LogLevel = 'debug' | 'info' | 'warn' | 'error';

const LOG_LEVELS: Record<LogLevel, number> = {
  debug: 0,
  info: 1,
  warn: 2,
  error: 3,
};

function shouldLog(level: LogLevel): boolean {
  const configLevel = config.logLevel as LogLevel;
  return LOG_LEVELS[level] >= LOG_LEVELS[configLevel];
}

export function log(level: LogLevel, message: string, data?: Record<string, unknown>): void {
  if (!shouldLog(level)) return;

  const logEntry = {
    timestamp: new Date().toISOString(),
    level,
    message,
    ...data,
  };

  console.log(JSON.stringify(logEntry));
}

export function loggerMiddleware(req: Request, res: Response, next: NextFunction): void {
  const start = Date.now();

  res.on('finish', () => {
    const duration = Date.now() - start;

    // 对同步相关的请求记录更详细的信息
    const isSyncRequest = req.originalUrl.startsWith('/api/items') || 
                          req.originalUrl.startsWith('/api/changes') ||
                          req.originalUrl.startsWith('/api/sync');

    const logData: Record<string, unknown> = {
      method: req.method,
      path: req.originalUrl,
      status: res.statusCode,
      duration: `${duration}ms`,
      ip: req.ip,
    };

    // 添加用户标识（如果有）
    if ((req as any).userId) {
      logData.userId = (req as any).userId;
    }

    // 对 PUT/POST 请求记录请求体大小
    if (isSyncRequest && (req.method === 'PUT' || req.method === 'POST')) {
      logData.bodySize = req.headers['content-length'] || 0;
    }

    log('info', 'Request', logData);
  });

  next();
}

