      ];
      return extractBySelectors(selectors);
    },

    // 简书
    jianshu: () => {
      const selectors = ['.article', 'article', '.show-content'];
      return extractBySelectors(selectors);
    },

    // CSDN
    csdn: () => {
      const selectors = [
        '#article_content', '.article_content',
        '#content_views', '.markdown_views'
      ];
      return extractBySelectors(selectors);
    },

    // 掘金
    juejin: () => {
      const selectors = [
        '.article-content', '.markdown-body',
        'article .content'
      ];
      return extractBySelectors(selectors);
    },

    // 博客园
    cnblogs: () => {
