  currentTab = tabName;

  tabs.forEach(tab => {
    tab.classList.toggle('active', tab.dataset.tab === tabName);
  });

  noteForm.classList.toggle('active', tabName === 'note');
  bookmarkForm.classList.toggle('active', tabName === 'bookmark');

