/**
 * Readability.js - 简化版
 * 基于 Mozilla Readability 的精简实现
 * 用于从网页中提取主要文章内容
 * 
 * 原始项目: https://github.com/mozilla/readability
 * License: Apache-2.0
 */

var Readability = function(doc, options) {
  this._doc = doc;
  this._options = options || {};
  this._articleTitle = null;
  this._articleByline = null;
  this._articleDir = null;
  this._articleSiteName = null;

  // 配置
  this._charThreshold = this._options.charThreshold || 500;
  this._classesToPreserve = this._options.classesToPreserve || [];

  // 不太可能是内容的元素
  this.UNLIKELY_CANDIDATES = /banner|breadcrumbs|combx|comment|community|cover-wrap|disqus|extra|foot|header|legends|menu|related|remark|replies|rss|shoutbox|sidebar|skyscraper|social|sponsor|supplemental|ad-break|agegate|pagination|pager|popup|yom-hierarchical-nav|yom-hierarchical-nav-item/i;

  // 可能是内容的元素
  this.MAYBE_CANDIDATES = /and|article|body|column|main|shadow/i;

  // 正面指标
  this.POSITIVE = /article|body|content|entry|hentry|h-entry|main|page|pagination|post|text|blog|story/i;

  // 负面指标
  this.NEGATIVE = /hidden|^hid$| hid$| hid |^hid |banner|combx|comment|com-|contact|foot|footer|footnote|masthead|media|meta|outbrain|promo|related|scroll|share|shoutbox|sidebar|skyscraper|sponsor|shopping|tags|tool|widget/i;
};

Readability.prototype = {
  /**
   * 解析文档并返回文章内容
   */
  parse: function() {
    // 获取标题
    this._articleTitle = this._getArticleTitle();

    // 获取作者
    this._articleByline = this._getArticleByline();

    // 获取站点名称
    this._articleSiteName = this._getArticleSiteName();

    // 获取文章内容
    var articleContent = this._grabArticle();

    if (!articleContent) {
      return null;
    }

    // 清理内容
    this._postProcessContent(articleContent);

    // 获取摘要
    var excerpt = this._getExcerpt(articleContent);

    return {
      title: this._articleTitle,
      byline: this._articleByline,
      content: articleContent.innerHTML,
      textContent: articleContent.textContent,
      length: articleContent.textContent.length,
      excerpt: excerpt,
      siteName: this._articleSiteName,
    };
  },

  /**
   * 获取文章标题
   */
  _getArticleTitle: function() {
    var doc = this._doc;
    var curTitle = "";
    var origTitle = "";

    try {
      curTitle = origTitle = doc.title.trim();

      // 尝试从 meta 标签获取
      var metaTitle = doc.querySelector('meta[property="og:title"]');
      if (metaTitle) {
        curTitle = metaTitle.getAttribute("content");
      }

      // 尝试从 h1 获取
      if (!curTitle) {
        var h1 = doc.querySelector("h1");
        if (h1) {
          curTitle = h1.textContent.trim();
        }
      }
    } catch (e) {
      curTitle = origTitle;
    }

    return curTitle;
  },

  /**
   * 获取作者信息
   */
  _getArticleByline: function() {
    var doc = this._doc;

    // 尝试从 meta 标签获取
    var metaAuthor = doc.querySelector('meta[name="author"]');
    if (metaAuthor) {
      return metaAuthor.getAttribute("content");
    }

    // 尝试从常见的作者元素获取
    var authorSelectors = [
      '.author',
      '.byline',
      '[rel="author"]',
      '[itemprop="author"]',
    ];

    for (var i = 0; i < authorSelectors.length; i++) {
      var author = doc.querySelector(authorSelectors[i]);
      if (author) {
        return author.textContent.trim();
      }
    }

    return null;
  },

  /**
   * 获取站点名称
   */
  _getArticleSiteName: function() {
    var doc = this._doc;

    var metaSiteName = doc.querySelector('meta[property="og:site_name"]');
    if (metaSiteName) {
      return metaSiteName.getAttribute("content");
    }

    return null;
  },

  /**
   * 获取文章内容
   */
  _grabArticle: function() {
    var doc = this._doc;
    var page = doc.body;

    if (!page) {
      return null;
    }

    // 尝试使用语义化标签
    var article = doc.querySelector("article");
    if (article && article.textContent.length > this._charThreshold) {
      return article.cloneNode(true);
    }

    // 尝试使用 main 标签
    var main = doc.querySelector("main");
    if (main && main.textContent.length > this._charThreshold) {
      return main.cloneNode(true);
    }

    // 尝试使用常见的内容容器
    var contentSelectors = [
      '.post-content',
      '.article-content',
      '.entry-content',
      '.content',
      '#content',
      '.post',
      '.article',
    ];

    for (var i = 0; i < contentSelectors.length; i++) {
      var content = doc.querySelector(contentSelectors[i]);
      if (content && content.textContent.length > this._charThreshold) {
        return content.cloneNode(true);
      }
    }

    // 降级：使用评分算法
    return this._grabArticleByScoring();
  },

  /**
   * 使用评分算法获取文章内容
   */
  _grabArticleByScoring: function() {
    var doc = this._doc;
    var candidates = [];
    var elementsToScore = doc.querySelectorAll("p, td, pre");

    for (var i = 0; i < elementsToScore.length; i++) {
      var elem = elementsToScore[i];
      var parent = elem.parentNode;
      var grandParent = parent ? parent.parentNode : null;
      var innerText = elem.textContent.trim();

      if (innerText.length < 25) {
        continue;
      }

      // 初始化父元素分数
      if (!parent.readabilityScore) {
        parent.readabilityScore = this._initializeScore(parent);
        candidates.push(parent);
      }

      if (grandParent && !grandParent.readabilityScore) {
        grandParent.readabilityScore = this._initializeScore(grandParent);
        candidates.push(grandParent);
      }

      // 计算内容分数
      var contentScore = 1;
      contentScore += innerText.split(',').length;
      contentScore += Math.min(Math.floor(innerText.length / 100), 3);

      parent.readabilityScore += contentScore;
      if (grandParent) {
        grandParent.readabilityScore += contentScore / 2;
      }
    }

    // 找到最高分的候选元素
    var topCandidate = null;
    for (var j = 0; j < candidates.length; j++) {
      var candidate = candidates[j];
      var score = candidate.readabilityScore * (1 - this._getLinkDensity(candidate));
      candidate.readabilityScore = score;

      if (!topCandidate || score > topCandidate.readabilityScore) {
        topCandidate = candidate;
      }
    }

    if (topCandidate) {
      return topCandidate.cloneNode(true);
    }

    // 最后方案：返回 body
    return doc.body.cloneNode(true);
  },

  /**
   * 初始化元素分数
   */
  _initializeScore: function(elem) {
    var score = 0;
    var tagName = elem.tagName.toUpperCase();

    switch (tagName) {
      case "DIV":
        score += 5;
        break;
      case "PRE":
      case "TD":
      case "BLOCKQUOTE":
        score += 3;
        break;
      case "ADDRESS":
      case "OL":
      case "UL":
      case "DL":
      case "DD":
      case "DT":
      case "LI":
      case "FORM":
        score -= 3;
        break;
      case "H1":
      case "H2":
      case "H3":
      case "H4":
      case "H5":
      case "H6":
      case "TH":
        score -= 5;
        break;
    }

    // 根据 class 和 id 调整分数
    var className = elem.className || "";
    var id = elem.id || "";

    if (this.POSITIVE.test(className + " " + id)) {
      score += 25;
    }
    if (this.NEGATIVE.test(className + " " + id)) {
      score -= 25;
    }

    return score;
  },

  /**
   * 计算链接密度
   */
  _getLinkDensity: function(elem) {
    var textLength = elem.textContent.length;
    if (textLength === 0) {
      return 0;
    }

    var linkLength = 0;
    var links = elem.querySelectorAll("a");
    for (var i = 0; i < links.length; i++) {
      linkLength += links[i].textContent.length;
    }

    return linkLength / textLength;
  },

  /**
   * 后处理内容
   */
  _postProcessContent: function(articleContent) {
    // 移除脚本和样式
    var scripts = articleContent.querySelectorAll("script, style, noscript");
    for (var i = scripts.length - 1; i >= 0; i--) {
      scripts[i].parentNode.removeChild(scripts[i]);
    }

    // 移除隐藏元素
    var hidden = articleContent.querySelectorAll("[hidden], [style*='display:none'], [style*='display: none']");
    for (var j = hidden.length - 1; j >= 0; j--) {
      hidden[j].parentNode.removeChild(hidden[j]);
    }

    // 清理属性
    var allElements = articleContent.querySelectorAll("*");
    for (var k = 0; k < allElements.length; k++) {
      var elem = allElements[k];
      // 保留 href 和 src
      var attrs = elem.attributes;
      for (var l = attrs.length - 1; l >= 0; l--) {
        var attrName = attrs[l].name;
        if (attrName !== "href" && attrName !== "src" && attrName !== "alt") {
          elem.removeAttribute(attrName);
        }
      }
    }
  },

  /**
   * 获取摘要
   */
  _getExcerpt: function(articleContent) {
    // 尝试从 meta 获取
    var metaDesc = this._doc.querySelector('meta[name="description"]');
    if (metaDesc) {
      return metaDesc.getAttribute("content");
    }

    var metaOgDesc = this._doc.querySelector('meta[property="og:description"]');
    if (metaOgDesc) {
      return metaOgDesc.getAttribute("content");
    }

    // 从内容中提取
    var firstP = articleContent.querySelector("p");
    if (firstP) {
      return firstP.textContent.substring(0, 200);
    }

    return articleContent.textContent.substring(0, 200);
  },
};

// 导出
if (typeof module !== "undefined" && module.exports) {
  module.exports = Readability;
}

/**
 * 同步机制自动化测试脚本
 * 
 * 用法:
 *   node scripts/test-sync-mechanism.js
 * 
 * 环境变量:
 *   WEBDAV_URL - WebDAV 服务器地址 (默认: http://localhost:8080)
 *   WEBDAV_USER - WebDAV 用户名 (默认: test)
 *   WEBDAV_PASS - WebDAV 密码 (默认: test123)
 */

const { createClient } = require('webdav');
const crypto = require('crypto');

// 配置
const config = {
  url: process.env.WEBDAV_URL || 'http://localhost:8080',
  username: process.env.WEBDAV_USER || 'test',
  password: process.env.WEBDAV_PASS || 'test123',
  basePath: '/mucheng-notes-test',
};

// 创建 WebDAV 客户端
const client = createClient(config.url, {
  username: config.username,
  password: config.password,
});

// 辅助函数
function getPath(subPath) {
  return `${config.basePath}/${subPath}`;
}

function generateId() {
  return crypto.randomUUID();
}

function computeHash(content) {
  return crypto.createHash('sha256').update(content).digest('hex');
}

async function sleep(ms) {
  return new Promise(resolve => setTimeout(resolve, ms));
}

// 测试用例
class SyncMechanismTest {
  constructor() {
    this.testResults = [];
  }

  async setup() {
    console.log('🔧 Setting up test environment...');

    // 清理测试目录
    try {
      if (await client.exists(config.basePath)) {
        await client.deleteFile(config.basePath);
      }
    } catch (e) {
      // 忽略删除错误
    }

    // 创建目录结构
    await client.createDirectory(config.basePath);
    await client.createDirectory(getPath('items'));
    await client.createDirectory(getPath('changes'));
    await client.createDirectory(getPath('resources'));
    await client.createDirectory(getPath('locks'));

    // 创建 workspace.json
    const workspace = {
      version: '1.0',
      capabilities: ['items', 'resources', 'changes'],
      last_sync_time: null,
      key_identifier: null,
    };
    await client.putFileContents(getPath('workspace.json'), JSON.stringify(workspace, null, 2));

    console.log('✅ Test environment ready');
  }

  async cleanup() {
    console.log('🧹 Cleaning up...');
    try {
      await client.deleteFile(config.basePath);
    } catch (e) {
      console.warn('⚠️  Cleanup failed:', e.message);
    }
  }

  async test1_CreateItemAndChange() {
    console.log('\n📝 Test 1: Create item and change log');

    const itemId = generateId();
    const now = Date.now();
    const payload = JSON.stringify({ title: 'Test Note', content: 'Hello World' });

    // 创建 item
    const item = {
      id: itemId,
      type: 'note',
      created_time: now,
      updated_time: now,
      deleted_time: null,
      payload: payload,
      content_hash: computeHash(payload),
      sync_status: 'clean',
      local_rev: 1,
      remote_rev: now.toString(),
      encryption_applied: 0,
      schema_version: 1,
    };

    await client.putFileContents(
      getPath(`items/${itemId}.json`),
      JSON.stringify(item, null, 2)
    );

    // 创建 change log
    const change = {
      change_id: now,
      item_id: itemId,
      type: 'note',
      updated_time: now,
      deleted_time: null,
      content_hash: item.content_hash,
    };

    await client.putFileContents(
      getPath(`changes/${now}.json`),
      JSON.stringify(change, null, 2)
    );

    // 验证
    const itemExists = await client.exists(getPath(`items/${itemId}.json`));
    const changeExists = await client.exists(getPath(`changes/${now}.json`));

    const passed = itemExists && changeExists;
    this.testResults.push({ name: 'Test 1', passed });

    console.log(passed ? '✅ PASSED' : '❌ FAILED');
    return { itemId, changeId: now };
  }

  async test2_ListChanges(changeId) {
    console.log('\n📋 Test 2: List changes');

    const changesDir = getPath('changes');
    const files = await client.getDirectoryContents(changesDir);

    const changeFiles = files.filter(f => f.basename.endsWith('.json'));
    const passed = changeFiles.length > 0;

    this.testResults.push({ name: 'Test 2', passed });
    console.log(passed ? '✅ PASSED' : '❌ FAILED');
    console.log(`   Found ${changeFiles.length} change file(s)`);

    return changeFiles;
  }

  async test3_SyncCursor(changeId) {
    console.log('\n🔖 Test 3: Sync cursor');

    const cursor = {
      cursor: `${changeId}.json`,
      timestamp: Date.now(),
    };

    await client.putFileContents(
      getPath('sync-cursor.json'),
      JSON.stringify(cursor, null, 2)
    );

    // 验证
    const content = await client.getFileContents(getPath('sync-cursor.json'), { format: 'text' });
    const savedCursor = JSON.parse(content);

    const passed = savedCursor.cursor === cursor.cursor;
    this.testResults.push({ name: 'Test 3', passed });

    console.log(passed ? '✅ PASSED' : '❌ FAILED');
    console.log(`   Cursor: ${savedCursor.cursor}`);
  }

  async test4_ChangeLogFormat(changeId) {
    console.log('\n📄 Test 4: Change log format validation');

    const content = await client.getFileContents(getPath(`changes/${changeId}.json`), { format: 'text' });
    const change = JSON.parse(content);

    // 验证必需字段
    const requiredFields = ['change_id', 'item_id', 'type', 'updated_time', 'content_hash'];
    const hasAllFields = requiredFields.every(field => change.hasOwnProperty(field));

    // 验证字段类型
    const validTypes =
      typeof change.change_id === 'number' &&
      typeof change.item_id === 'string' &&
      typeof change.type === 'string' &&
      typeof change.updated_time === 'number' &&
      typeof change.content_hash === 'string';

    const passed = hasAllFields && validTypes;
    this.testResults.push({ name: 'Test 4', passed });

    console.log(passed ? '✅ PASSED' : '❌ FAILED');
    if (!passed) {
      console.log('   Missing fields:', requiredFields.filter(f => !change.hasOwnProperty(f)));
    }
  }

  async runAll() {
    console.log('🚀 Starting Sync Mechanism Tests\n');
    console.log('Configuration:');
    console.log(`  URL: ${config.url}`);
    console.log(`  Base Path: ${config.basePath}`);
    console.log('');

    try {
      await this.setup();

      const { itemId, changeId } = await this.test1_CreateItemAndChange();
      await this.test2_ListChanges(changeId);
      await this.test3_SyncCursor(changeId);
      await this.test4_ChangeLogFormat(changeId);

      // 总结
      console.log('\n' + '='.repeat(50));
      console.log('📊 Test Summary');
      console.log('='.repeat(50));

      const passed = this.testResults.filter(r => r.passed).length;
      const total = this.testResults.length;

      this.testResults.forEach(result => {
        const icon = result.passed ? '✅' : '❌';
        console.log(`${icon} ${result.name}`);
      });

      console.log('');
      console.log(`Total: ${passed}/${total} passed`);

      if (passed === total) {
        console.log('\n🎉 All tests passed!');
      } else {
        console.log('\n⚠️  Some tests failed');
        process.exit(1);
      }

    } catch (error) {
      console.error('\n❌ Test failed with error:', error.message);
      console.error(error.stack);
      process.exit(1);
    } finally {
      await this.cleanup();
    }
  }
}

// 运行测试
if (require.main === module) {
  const test = new SyncMechanismTest();
  test.runAll().catch(err => {
    console.error('Fatal error:', err);
    process.exit(1);
  });
}

module.exports = SyncMechanismTest;

/**
 * 同步错误诊断脚本
 * 
 * 用法:
 *   node scripts/diagnose-sync-error.js <item-id>
 * 
 * 功能:
 *   1. 从WebDAV下载指定的数据项
 *   2. 验证JSON格式
 *   3. 检查字段完整性
 *   4. 验证加密数据格式
 *   5. 生成诊断报告
 */

const { createClient } = require('webdav');
const fs = require('fs');

// 配置
const config = {
  url: process.env.WEBDAV_URL || 'http://localhost:8080',
  username: process.env.WEBDAV_USER || 'test',
  password: process.env.WEBDAV_PASS || 'test123',
  basePath: '/mucheng-notes',
};

const client = createClient(config.url, {
  username: config.username,
  password: config.password,
});

// 必需字段
const REQUIRED_FIELDS = [
  'id',
  'type',
  'created_time',
  'updated_time',
  'deleted_time',
  'payload',
  'content_hash',
  'sync_status',
  'local_rev',
  'remote_rev',
  'encryption_applied',
  'schema_version',
];

// 字段类型
const FIELD_TYPES = {
  id: 'string',
  type: 'string',
  created_time: 'number',
  updated_time: 'number',
  deleted_time: ['number', 'null'],
  payload: 'string',
  content_hash: 'string',
  sync_status: 'string',
  local_rev: 'number',
  remote_rev: ['string', 'null'],
  encryption_applied: 'number',
  schema_version: 'number',
};

async function diagnoseItem(itemId) {
  console.log('🔍 Diagnosing item:', itemId);
  console.log('');

  const report = {
    itemId,
    timestamp: new Date().toISOString(),
    checks: [],
    errors: [],
    warnings: [],
  };

  try {
    // 1. 下载数据
    console.log('📥 Step 1: Downloading item from WebDAV...');
    const itemPath = `${config.basePath}/items/${itemId}.json`;

    const exists = await client.exists(itemPath);
    if (!exists) {
      report.errors.push(`Item file does not exist: ${itemPath}`);
      console.log('❌ Item not found on WebDAV server');
      return report;
    }

    const content = await client.getFileContents(itemPath, { format: 'text' });
    console.log(`✅ Downloaded ${content.length} bytes`);
    report.checks.push({ name: 'Download', status: 'PASS' });

    // 2. 验证JSON格式
    console.log('\n📄 Step 2: Validating JSON format...');
    let item;
    try {
      item = JSON.parse(content);
      console.log('✅ Valid JSON');
      report.checks.push({ name: 'JSON Format', status: 'PASS' });
    } catch (e) {
      report.errors.push(`Invalid JSON: ${e.message}`);
      console.log('❌ Invalid JSON:', e.message);
      report.checks.push({ name: 'JSON Format', status: 'FAIL', error: e.message });
      return report;
    }

    // 3. 检查必需字段
    console.log('\n🔑 Step 3: Checking required fields...');
    const missingFields = [];
    for (const field of REQUIRED_FIELDS) {
      if (!(field in item)) {
        missingFields.push(field);
      }
    }

    if (missingFields.length > 0) {
      report.errors.push(`Missing fields: ${missingFields.join(', ')}`);
      console.log('❌ Missing fields:', missingFields);
      report.checks.push({ name: 'Required Fields', status: 'FAIL', missing: missingFields });
    } else {
      console.log('✅ All required fields present');
      report.checks.push({ name: 'Required Fields', status: 'PASS' });
    }

    // 4. 检查字段类型
    console.log('\n🔢 Step 4: Checking field types...');
    const typeErrors = [];
    for (const [field, expectedType] of Object.entries(FIELD_TYPES)) {
      if (!(field in item)) continue;

      const actualType = item[field] === null ? 'null' : typeof item[field];
      const expected = Array.isArray(expectedType) ? expectedType : [expectedType];

      if (!expected.includes(actualType)) {
        typeErrors.push(`${field}: expected ${expected.join(' or ')}, got ${actualType}`);
      }
    }

    if (typeErrors.length > 0) {
      report.errors.push(`Type errors: ${typeErrors.join('; ')}`);
      console.log('❌ Type errors:', typeErrors);
      report.checks.push({ name: 'Field Types', status: 'FAIL', errors: typeErrors });
    } else {
      console.log('✅ All field types correct');
      report.checks.push({ name: 'Field Types', status: 'PASS' });
    }

    // 5. 检查字段命名规范 (snake_case)
    console.log('\n🐍 Step 5: Checking field naming convention...');
    const camelCaseFields = Object.keys(item).filter(key => /[A-Z]/.test(key));
    if (camelCaseFields.length > 0) {
      report.warnings.push(`Found camelCase fields (should be snake_case): ${camelCaseFields.join(', ')}`);
      console.log('⚠️  Warning: Found camelCase fields:', camelCaseFields);
      console.log('   Mobile app expects snake_case (e.g., created_time, not createdTime)');
      report.checks.push({ name: 'Naming Convention', status: 'WARN', camelCase: camelCaseFields });
    } else {
      console.log('✅ All fields use snake_case');
      report.checks.push({ name: 'Naming Convention', status: 'PASS' });
    }

    // 6. 检查加密数据格式
    if (item.encryption_applied === 1) {
      console.log('\n🔐 Step 6: Checking encrypted payload format...');
      try {
        const encryptedData = JSON.parse(item.payload);
        const requiredEncFields = ['ciphertext', 'iv', 'authTag'];
        const missingEncFields = requiredEncFields.filter(f => !(f in encryptedData));

        if (missingEncFields.length > 0) {
          report.errors.push(`Encrypted payload missing fields: ${missingEncFields.join(', ')}`);
          console.log('❌ Missing encrypted fields:', missingEncFields);
          report.checks.push({ name: 'Encryption Format', status: 'FAIL', missing: missingEncFields });
        } else {
          console.log('✅ Encrypted payload format valid');
          console.log(`   - ciphertext: ${encryptedData.ciphertext.length} chars`);
          console.log(`   - iv: ${encryptedData.iv.length} chars`);
          console.log(`   - authTag: ${encryptedData.authTag.length} chars`);
          report.checks.push({ name: 'Encryption Format', status: 'PASS' });
        }
      } catch (e) {
        report.errors.push(`Invalid encrypted payload JSON: ${e.message}`);
        console.log('❌ Encrypted payload is not valid JSON:', e.message);
        report.checks.push({ name: 'Encryption Format', status: 'FAIL', error: e.message });
      }
    } else {
      console.log('\n📝 Step 6: Item is not encrypted');
      report.checks.push({ name: 'Encryption Format', status: 'N/A' });
    }

    // 7. 生成摘要
    console.log('\n' + '='.repeat(60));
    console.log('📊 Diagnosis Summary');
    console.log('='.repeat(60));
    console.log(`Item ID: ${itemId}`);
    console.log(`Type: ${item.type}`);
    console.log(`Encryption: ${item.encryption_applied === 1 ? 'Yes' : 'No'}`);
    console.log(`Sync Status: ${item.sync_status}`);
    console.log('');
    console.log(`Errors: ${report.errors.length}`);
    console.log(`Warnings: ${report.warnings.length}`);
    console.log('');

    if (report.errors.length > 0) {
      console.log('❌ Errors:');
      report.errors.forEach(err => console.log(`   - ${err}`));
    }

    if (report.warnings.length > 0) {
      console.log('⚠️  Warnings:');
      report.warnings.forEach(warn => console.log(`   - ${warn}`));
    }

    if (report.errors.length === 0 && report.warnings.length === 0) {
      console.log('✅ No issues found - item should sync correctly to mobile');
    }

    return report;

  } catch (error) {
    report.errors.push(`Unexpected error: ${error.message}`);
    console.error('\n❌ Unexpected error:', error.message);
    console.error(error.stack);
    return report;
  }
}

// 主函数
async function main() {
  const itemId = process.argv[2];

  if (!itemId) {
    console.error('Usage: node scripts/diagnose-sync-error.js <item-id>');
    console.error('');
    console.error('Example:');
    console.error('  node scripts/diagnose-sync-error.js 12345678-1234-1234-1234-123456789abc');
    process.exit(1);
  }

  const report = await diagnoseItem(itemId);

  // 保存报告
  const reportPath = `diagnosis-${itemId}.json`;
  fs.writeFileSync(reportPath, JSON.stringify(report, null, 2));
  console.log('');
  console.log(`📄 Full report saved to: ${reportPath}`);

  process.exit(report.errors.length > 0 ? 1 : 0);
}

if (require.main === module) {
  main().catch(err => {
    console.error('Fatal error:', err);
    process.exit(1);
  });
}

module.exports = { diagnoseItem };

/**
 * Ghostscript 下载脚本
 * 下载 Ghostscript 便携版到 gs-portable 目录
 * 
 * 使用方法: node scripts/download-ghostscript.js
 */

const https = require('https');
const http = require('http');
const fs = require('fs');
const path = require('path');
const { execSync } = require('child_process');

// Ghostscript 版本和下载地址
const GS_VERSION = '10.02.1';
const GS_DOWNLOAD_URL = `https://github.com/ArtifexSoftware/ghostpdl-downloads/releases/download/gs10021/gs10021w64.exe`;

// 目标目录
const GS_DIR = path.join(__dirname, '..', 'gs-portable');
const TEMP_DIR = path.join(__dirname, '..', 'temp');

// 确保目录存在
function ensureDir(dir) {
  if (!fs.existsSync(dir)) {
    fs.mkdirSync(dir, { recursive: true });
  }
}

// 下载文件
function downloadFile(url, dest) {
  return new Promise((resolve, reject) => {
    console.log(`Downloading from: ${url}`);
    console.log(`Saving to: ${dest}`);

    const file = fs.createWriteStream(dest);
    const protocol = url.startsWith('https') ? https : http;

    const request = protocol.get(url, (response) => {
      // 处理重定向
      if (response.statusCode === 301 || response.statusCode === 302) {
        const redirectUrl = response.headers.location;
        console.log(`Redirecting to: ${redirectUrl}`);
        file.close();
        fs.unlinkSync(dest);
        downloadFile(redirectUrl, dest).then(resolve).catch(reject);
        return;
      }

      if (response.statusCode !== 200) {
        reject(new Error(`Failed to download: ${response.statusCode}`));
        return;
      }

      const totalSize = parseInt(response.headers['content-length'], 10);
      let downloadedSize = 0;

      response.on('data', (chunk) => {
        downloadedSize += chunk.length;
        const percent = totalSize ? ((downloadedSize / totalSize) * 100).toFixed(1) : '?';
        process.stdout.write(`\rDownloading: ${percent}% (${(downloadedSize / 1024 / 1024).toFixed(1)} MB)`);
      });

      response.pipe(file);

      file.on('finish', () => {
        file.close();
        console.log('\nDownload complete!');
        resolve();
      });
    });

    request.on('error', (err) => {
      fs.unlink(dest, () => {});
      reject(err);
    });
  });
}

// 提取 Ghostscript 文件（使用 7z 或手动提取）
async function extractGhostscript(installerPath) {
  console.log('\nExtracting Ghostscript...');

  // 尝试使用 7z 提取
  try {
    // 检查是否有 7z
    execSync('7z --help', { stdio: 'ignore' });

    // 使用 7z 提取
    const extractDir = path.join(TEMP_DIR, 'gs-extract');
    ensureDir(extractDir);

    execSync(`7z x "${installerPath}" -o"${extractDir}" -y`, { stdio: 'inherit' });

    // 查找并复制需要的文件
    const gsDir = findGsDir(extractDir);
    if (gsDir) {
      copyGsFiles(gsDir);
      return true;
    }
  } catch (e) {
    console.log('7z not available, trying alternative method...');
  }

  // 备用方案：提示用户手动安装
  console.log('\n========================================');
  console.log('自动提取失败，请手动操作：');
  console.log('1. 运行下载的安装程序: ' + installerPath);
  console.log('2. 安装到默认位置');
  console.log('3. 将以下文件复制到 gs-portable 目录:');
  console.log('   - bin/gswin64c.exe');
  console.log('   - bin/gsdll64.dll');
  console.log('   - lib/* (所有文件)');
  console.log('   - Resource/* (所有文件)');
  console.log('========================================\n');

  return false;
}

// 查找 Ghostscript 目录
function findGsDir(extractDir) {
  const items = fs.readdirSync(extractDir);
  for (const item of items) {
    const itemPath = path.join(extractDir, item);
    if (fs.statSync(itemPath).isDirectory()) {
      if (item.startsWith('gs') || fs.existsSync(path.join(itemPath, 'bin'))) {
        return itemPath;
      }
      // 递归查找
      const found = findGsDir(itemPath);
      if (found) return found;
    }
  }
  return null;
}

// 复制 Ghostscript 文件
function copyGsFiles(gsDir) {
  console.log(`Copying files from: ${gsDir}`);

  // 复制 bin 目录
  const binSrc = path.join(gsDir, 'bin');
  const binDest = path.join(GS_DIR, 'bin');
  if (fs.existsSync(binSrc)) {
    copyDir(binSrc, binDest);
  }

  // 复制 lib 目录
  const libSrc = path.join(gsDir, 'lib');
  const libDest = path.join(GS_DIR, 'lib');
  if (fs.existsSync(libSrc)) {
    copyDir(libSrc, libDest);
  }

  // 复制 Resource 目录
  const resSrc = path.join(gsDir, 'Resource');
  const resDest = path.join(GS_DIR, 'Resource');
  if (fs.existsSync(resSrc)) {
    copyDir(resSrc, resDest);
  }

  console.log('Files copied successfully!');
}

// 递归复制目录
function copyDir(src, dest) {
  ensureDir(dest);
  const items = fs.readdirSync(src);

  for (const item of items) {
    const srcPath = path.join(src, item);
    const destPath = path.join(dest, item);

    if (fs.statSync(srcPath).isDirectory()) {
      copyDir(srcPath, destPath);
    } else {
      fs.copyFileSync(srcPath, destPath);
    }
  }
}

// 清理临时文件
function cleanup() {
  console.log('\nCleaning up...');
  if (fs.existsSync(TEMP_DIR)) {
    fs.rmSync(TEMP_DIR, { recursive: true, force: true });
  }
}

// 主函数
async function main() {
  console.log('========================================');
  console.log(`Ghostscript Portable Setup v${GS_VERSION}`);
  console.log('========================================\n');

  try {
    ensureDir(GS_DIR);
    ensureDir(TEMP_DIR);

    // 检查是否已存在
    const gsExe = path.join(GS_DIR, 'bin', 'gswin64c.exe');
    if (fs.existsSync(gsExe)) {
      console.log('Ghostscript already exists in gs-portable/');
      console.log('Delete the directory to re-download.');
      return;
    }

    // 下载安装程序
    const installerPath = path.join(TEMP_DIR, 'gs-installer.exe');
    await downloadFile(GS_DOWNLOAD_URL, installerPath);

    // 提取文件
    const success = await extractGhostscript(installerPath);

    if (success) {
      console.log('\n========================================');
      console.log('Ghostscript setup complete!');
      console.log('Location: ' + GS_DIR);
      console.log('========================================');
    }

  } catch (error) {
    console.error('Error:', error.message);
    process.exit(1);
  } finally {
    // cleanup();
  }
}

main();

/**
 * Turndown Plugin GFM (GitHub Flavored Markdown)
 * 支持表格、删除线、任务列表等 GFM 特性
 * 基于 https://github.com/mixmark-io/turndown-plugin-gfm
 */

var turndownPluginGfm = (function () {
  'use strict';

  var highlightRegExp = /highlight-(?:text|source)-([a-z0-9]+)/;

  function highlightedCodeBlock(turndownService) {
    turndownService.addRule('highlightedCodeBlock', {
      filter: function (node) {
        var firstChild = node.firstChild;
        return (
          node.nodeName === 'DIV' &&
          highlightRegExp.test(node.className) &&
          firstChild &&
          firstChild.nodeName === 'PRE'
        );
      },
      replacement: function (content, node, options) {
        var className = node.className || '';
        var language = (className.match(highlightRegExp) || [null, ''])[1];

        return (
          '\n\n' + options.fence + language + '\n' +
          node.firstChild.textContent +
          '\n' + options.fence + '\n\n'
        );
      }
    });
  }

  function strikethrough(turndownService) {
    turndownService.addRule('strikethrough', {
      filter: ['del', 's', 'strike'],
      replacement: function (content) {
        return '~~' + content + '~~';
      }
    });
  }

  var indexOf = Array.prototype.indexOf;
  var every = Array.prototype.every;
  var rules = {};

  rules.tableCell = {
    filter: ['th', 'td'],
    replacement: function (content, node) {
      return cell(content, node);
    }
  };

  rules.tableRow = {
    filter: 'tr',
    replacement: function (content, node) {
      var borderCells = '';
      var alignMap = { left: ':--', right: '--:', center: ':-:' };

      if (isHeadingRow(node)) {
        for (var i = 0; i < node.childNodes.length; i++) {
          var border = '---';
          var align = (
            node.childNodes[i].getAttribute('align') || ''
          ).toLowerCase();

          if (align) border = alignMap[align] || border;

          borderCells += cell(border, node.childNodes[i]);
        }
      }
      return '\n' + content + (borderCells ? '\n' + borderCells : '');
    }
  };

  rules.table = {
    filter: function (node) {
      return node.nodeName === 'TABLE' && !isNestedTable(node);
    },
    replacement: function (content) {
      // 清理内容中的多余空行
      content = content.replace(/\n+/g, '\n').trim();
      return '\n\n' + content + '\n\n';
    }
  };

  rules.tableSection = {
    filter: ['thead', 'tbody', 'tfoot'],
    replacement: function (content) {
      return content;
    }
  };

  function isHeadingRow(tr) {
    var parentNode = tr.parentNode;
    return (
      parentNode.nodeName === 'THEAD' ||
      (
        parentNode.firstChild === tr &&
        (parentNode.nodeName === 'TABLE' || isFirstTbody(parentNode)) &&
        every.call(tr.childNodes, function (n) { return n.nodeName === 'TH'; })
      )
    );
  }

  function isFirstTbody(element) {
    var previousSibling = element.previousSibling;
    return (
      element.nodeName === 'TBODY' &&
      (
        !previousSibling ||
        (
          previousSibling.nodeName === 'THEAD' &&
          /^\s*$/i.test(previousSibling.textContent)
        )
      )
    );
  }

  function isNestedTable(node) {
    var currentNode = node.parentNode;
    while (currentNode) {
      if (currentNode.nodeName === 'TABLE') return true;
      currentNode = currentNode.parentNode;
    }
    return false;
  }

  function cell(content, node) {
    var index = indexOf.call(node.parentNode.childNodes, node);
    var prefix = ' ';
    if (index === 0) prefix = '| ';
    // 清理单元格内容中的换行符
    content = content.replace(/\n/g, ' ').trim();
    return prefix + content + ' |';
  }

  function tables(turndownService) {
    turndownService.keep(function (node) {
      return node.nodeName === 'TABLE' && isNestedTable(node);
    });
    for (var key in rules) {
      turndownService.addRule(key, rules[key]);
    }
  }

  function taskListItems(turndownService) {
    turndownService.addRule('taskListItems', {
      filter: function (node) {
        return node.type === 'checkbox' && node.parentNode.nodeName === 'LI';
      },
      replacement: function (content, node) {
        return (node.checked ? '[x]' : '[ ]') + ' ';
      }
    });
  }

  function gfm(turndownService) {
    turndownService.use([
      highlightedCodeBlock,
      strikethrough,
      tables,
      taskListItems
    ]);
  }

  return {
    gfm: gfm,
    highlightedCodeBlock: highlightedCodeBlock,
    strikethrough: strikethrough,
    tables: tables,
    taskListItems: taskListItems
  };
})();

if (typeof module !== 'undefined' && module.exports) {
  module.exports = turndownPluginGfm;
}

